CREATE OR REPLACE FUNCTION public._adoption_template_validate_and_load(_template_id uuid, _organization_id uuid, _workspace_id uuid, _payload jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  _initiatives jsonb;
  _i jsonb;
  _t jsonb;
  _ikey text;
  _tkey text;
  _ititle text;
  _seen_init text[] := ARRAY[]::text[];
  _seen_task text[];
  _isort int := 0;
  _tsort int;
  _init_id uuid;
  _readiness public.adoption_readiness_area;
BEGIN
  IF _payload IS NULL OR jsonb_typeof(_payload) <> 'object' THEN
    RAISE EXCEPTION 'invalid_template_payload';
  END IF;
  _initiatives := _payload->'initiatives';
  IF _initiatives IS NULL OR jsonb_typeof(_initiatives) <> 'array'
     OR jsonb_array_length(_initiatives) = 0 THEN
    RAISE EXCEPTION 'invalid_template_payload';
  END IF;

  -- Replace child rows for this template
  DELETE FROM public.adoption_template_tasks WHERE adoption_template_id = _template_id;
  DELETE FROM public.adoption_template_initiatives WHERE adoption_template_id = _template_id;

  FOR _i IN SELECT * FROM jsonb_array_elements(_initiatives)
  LOOP
    _ikey := COALESCE(NULLIF(btrim(_i->>'key'), ''), NULL);
    IF _ikey IS NULL THEN RAISE EXCEPTION 'invalid_template_payload'; END IF;
    IF _ikey = ANY(_seen_init) THEN RAISE EXCEPTION 'duplicate_initiative_key'; END IF;
    _seen_init := _seen_init || _ikey;

    IF COALESCE(btrim(_i->>'name'),'') = '' THEN
      RAISE EXCEPTION 'invalid_template_payload';
    END IF;

    BEGIN
      _readiness := (_i->>'readiness_area')::public.adoption_readiness_area;
    EXCEPTION WHEN others THEN
      RAISE EXCEPTION 'invalid_readiness_area';
    END;

    IF _i->'tasks' IS NULL OR jsonb_typeof(_i->'tasks') <> 'array'
       OR jsonb_array_length(_i->'tasks') = 0 THEN
      RAISE EXCEPTION 'initiative_requires_task';
    END IF;

    INSERT INTO public.adoption_template_initiatives(
      adoption_template_id, organization_id, workspace_id,
      template_key, name, readiness_area, summary,
      default_selected, sort_order
    ) VALUES (
      _template_id, _organization_id, _workspace_id,
      _ikey, _i->>'name', _readiness, NULLIF(btrim(COALESCE(_i->>'summary','')), ''),
      COALESCE((_i->>'default_selected')::boolean, true),
      COALESCE((_i->>'sort_order')::int, _isort)
    ) RETURNING id INTO _init_id;
    _isort := _isort + 10;

    _seen_task := ARRAY[]::text[];
    _tsort := 0;
    FOR _t IN SELECT * FROM jsonb_array_elements(_i->'tasks')
    LOOP
      _tkey := COALESCE(NULLIF(btrim(_t->>'key'), ''), NULL);
      IF _tkey IS NULL THEN RAISE EXCEPTION 'invalid_template_payload'; END IF;
      IF _tkey = ANY(_seen_task) THEN RAISE EXCEPTION 'duplicate_task_key'; END IF;
      _seen_task := _seen_task || _tkey;

      _ititle := COALESCE(NULLIF(btrim(_t->>'title'),''), NULL);
      IF _ititle IS NULL THEN RAISE EXCEPTION 'task_title_required'; END IF;

      INSERT INTO public.adoption_template_tasks(
        adoption_template_id, adoption_template_initiative_id,
        organization_id, workspace_id,
        template_key, title, description,
        default_selected, is_custom, sort_order
      ) VALUES (
        _template_id, _init_id,
        _organization_id, _workspace_id,
        _tkey, _ititle, NULLIF(btrim(COALESCE(_t->>'description','')), ''),
        COALESCE((_t->>'default_selected')::boolean, true),
        COALESCE((_t->>'is_custom')::boolean, true),
        COALESCE((_t->>'sort_order')::int, _tsort)
      );
      _tsort := _tsort + 10;
    END LOOP;
  END LOOP;
END $function$

CREATE OR REPLACE FUNCTION public._apply_phase_extension_internal(_phase_id uuid, _new_start date, _new_end date, _trigger_id uuid, _trigger_kind text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  ph record;
  pr record;
  prop_pr_start date;
  prop_pr_end   date;
  needs_pr_ext  boolean := false;
BEGIN
  SELECT id, project_id, workspace_id, organization_id, start_date, target_end_date, name
    INTO ph FROM public.phases WHERE id = _phase_id;

  -- Cascade to project if needed
  SELECT id, start_date, target_end_date, name
    INTO pr FROM public.projects WHERE id = ph.project_id;

  prop_pr_start := pr.start_date;
  prop_pr_end   := pr.target_end_date;

  IF _new_start IS NOT NULL AND pr.start_date IS NOT NULL AND _new_start < pr.start_date THEN
    needs_pr_ext := true; prop_pr_start := _new_start;
  END IF;
  IF _new_end IS NOT NULL AND pr.target_end_date IS NOT NULL AND _new_end > pr.target_end_date THEN
    needs_pr_ext := true; prop_pr_end := _new_end;
  END IF;

  IF needs_pr_ext THEN
    PERFORM public._apply_project_extension_internal(pr.id, prop_pr_start, prop_pr_end, _phase_id, 'phase');
  END IF;

  UPDATE public.phases
     SET start_date = COALESCE(_new_start, start_date),
         target_end_date = COALESCE(_new_end, target_end_date)
   WHERE id = _phase_id;

  PERFORM public.log_activity_event(
    ph.organization_id,
    auth.uid(),
    'parent_extended_for_child_edit',
    'phase',
    _phase_id,
    jsonb_build_object(
      'trigger_kind', _trigger_kind,
      'trigger_id',   _trigger_id,
      'old_start',    ph.start_date,
      'old_end',      ph.target_end_date,
      'new_start',    _new_start,
      'new_end',      _new_end
    ),
    ph.workspace_id
  );
END;
$function$

CREATE OR REPLACE FUNCTION public._assert_admin(_workspace_id uuid, _organization_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := auth.uid();
BEGIN
  IF _uid IS NULL OR NOT is_active_user(_uid) THEN
    RAISE EXCEPTION 'Unauthorized' USING ERRCODE = '42501';
  END IF;
  IF NOT (
    is_workspace_admin_or_higher(_uid, _workspace_id)
    OR is_org_admin(_uid, _organization_id)
  ) THEN
    RAISE EXCEPTION 'Forbidden: Workspace Admin or Org Admin required' USING ERRCODE = '42501';
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public._assert_job_payload_no_secret_keys(_payload jsonb)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE _k text;
BEGIN
  IF _payload IS NULL THEN RETURN; END IF;
  IF jsonb_typeof(_payload) <> 'object' THEN RETURN; END IF;
  FOR _k IN SELECT lower(key) FROM jsonb_object_keys(_payload) AS key LOOP
    IF _k IN ('secret','password','token','api_key','apikey','client_secret','access_token','refresh_token') THEN
      RAISE EXCEPTION 'Job payload must not contain secret-like top-level key: %', _k;
    END IF;
  END LOOP;
END $function$

CREATE OR REPLACE FUNCTION public._assert_pm_or_admin(_workspace_id uuid, _organization_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := auth.uid();
BEGIN
  IF _uid IS NULL OR NOT is_active_user(_uid) THEN
    RAISE EXCEPTION 'Unauthorized' USING ERRCODE = '42501';
  END IF;
  IF NOT (
    has_pm_authority(_uid, _workspace_id)
    OR is_workspace_admin_or_higher(_uid, _workspace_id)
    OR is_org_admin(_uid, _organization_id)
  ) THEN
    RAISE EXCEPTION 'Forbidden: PM or Admin authority required' USING ERRCODE = '42501';
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public._assert_tenant_admin_caller(_tenant_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _ok boolean;
BEGIN
  IF _uid IS NULL OR _tenant_id IS NULL THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;
  SELECT EXISTS (
    SELECT 1 FROM public.tenant_memberships tm
    WHERE tm.tenant_id = _tenant_id
      AND tm.user_id = _uid
      AND tm.status = 'active'
      AND tm.role IN ('tenant_owner','tenant_admin')
  ) INTO _ok;
  IF NOT _ok THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public._assert_tenant_admin_or_super(_tenant_id uuid, _reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF public.is_tenant_admin(_tenant_id, auth.uid()) THEN RETURN; END IF;
  IF public.is_platform_super_admin(auth.uid()) THEN
    IF _reason IS NULL OR length(btrim(_reason)) = 0 THEN
      RAISE EXCEPTION 'Platform super admin actions on tenant % require a reason', _tenant_id USING ERRCODE = '42501';
    END IF;
    RETURN;
  END IF;
  RAISE EXCEPTION 'Not authorized for tenant %', _tenant_id USING ERRCODE = '42501';
END $function$

CREATE OR REPLACE FUNCTION public._clone_anchor_for_phase(_phase_id uuid)
 RETURNS date
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  _start date;
  _earliest date;
BEGIN
  SELECT start_date INTO _start FROM public.phases WHERE id = _phase_id;
  IF _start IS NOT NULL THEN
    RETURN _start;
  END IF;

  SELECT MIN(d) INTO _earliest FROM (
    SELECT start_date AS d FROM public.phases WHERE id = _phase_id
    UNION ALL SELECT target_end_date FROM public.phases WHERE id = _phase_id
    UNION ALL SELECT start_date FROM public.tasks
      WHERE phase_id = _phase_id AND is_archived = false
    UNION ALL SELECT due_date FROM public.tasks
      WHERE phase_id = _phase_id AND is_archived = false
  ) s WHERE d IS NOT NULL;

  RETURN _earliest;
END;
$function$

CREATE OR REPLACE FUNCTION public._clone_anchor_for_task(_task_id uuid)
 RETURNS date
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _anchor date;
BEGIN
  SELECT start_date INTO _anchor
  FROM public.tasks
  WHERE id = _task_id;

  IF _anchor IS NOT NULL THEN
    RETURN _anchor;
  END IF;

  SELECT LEAST(
    COALESCE(t.start_date, 'infinity'::date),
    COALESCE(t.due_date,   'infinity'::date)
  )
  INTO _anchor
  FROM public.tasks t
  WHERE t.id = _task_id;

  IF _anchor = 'infinity'::date THEN
    RETURN NULL;
  END IF;

  RETURN _anchor;
END;
$function$

CREATE OR REPLACE FUNCTION public._compute_project_effective_window(_bp jsonb, _anchor date)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  _proj jsonb := COALESCE(_bp->'project', '{}'::jsonb);
  _nom_start date;
  _nom_end date;
  _eff_start date;
  _eff_end date;
  _reasons jsonb := '[]'::jsonb;
  _ph jsonb;
  _tk jsonb;
  _sp jsonb;
  _start_off int;
  _end_off int;
  _due_off int;
  _d_start date;
  _d_end date;
BEGIN
  IF _anchor IS NULL THEN
    RETURN jsonb_build_object(
      'nominal_start', NULL, 'nominal_end', NULL,
      'effective_start', NULL, 'effective_end', NULL,
      'requires_widening', false, 'reasons', '[]'::jsonb
    );
  END IF;

  _start_off := NULLIF(_proj->'schedule'->>'start_offset_days','')::int;
  _end_off   := NULLIF(_proj->'schedule'->>'target_end_offset_days','')::int;
  _nom_start := CASE WHEN _start_off IS NOT NULL THEN _anchor + _start_off ELSE _anchor END;
  _nom_end   := CASE WHEN _end_off   IS NOT NULL THEN _anchor + _end_off   ELSE NULL END;

  _eff_start := _nom_start;
  _eff_end   := _nom_end;

  -- Walk phases
  FOR _ph IN SELECT * FROM jsonb_array_elements(COALESCE(_bp->'phases','[]'::jsonb)) LOOP
    _start_off := NULLIF(_ph->'schedule'->>'start_offset_days','')::int;
    _end_off   := NULLIF(_ph->'schedule'->>'target_end_offset_days','')::int;
    IF _start_off IS NOT NULL THEN
      _d_start := _anchor + _start_off;
      IF _eff_start IS NULL OR _d_start < _eff_start THEN
        _eff_start := _d_start;
        _reasons := _reasons || jsonb_build_object(
          'kind','phase_before_project','name', _ph->>'name','date', _d_start
        );
      END IF;
    END IF;
    IF _end_off IS NOT NULL THEN
      _d_end := _anchor + _end_off;
      IF _eff_end IS NULL OR _d_end > _eff_end THEN
        _eff_end := _d_end;
        _reasons := _reasons || jsonb_build_object(
          'kind','phase_after_project','name', _ph->>'name','date', _d_end
        );
      END IF;
    END IF;
  END LOOP;

  -- Walk tasks
  FOR _tk IN SELECT * FROM jsonb_array_elements(COALESCE(_bp->'tasks','[]'::jsonb)) LOOP
    _start_off := NULLIF(_tk->'schedule'->>'start_offset_days','')::int;
    _due_off   := NULLIF(_tk->'schedule'->>'due_offset_days','')::int;
    IF _start_off IS NOT NULL THEN
      _d_start := _anchor + _start_off;
      IF _eff_start IS NULL OR _d_start < _eff_start THEN
        _eff_start := _d_start;
        _reasons := _reasons || jsonb_build_object(
          'kind','task_before_project','name', _tk->>'name','date', _d_start
        );
      END IF;
    END IF;
    IF _due_off IS NOT NULL THEN
      _d_end := _anchor + _due_off;
      IF _eff_end IS NULL OR _d_end > _eff_end THEN
        _eff_end := _d_end;
        _reasons := _reasons || jsonb_build_object(
          'kind','task_after_project','name', _tk->>'name','date', _d_end
        );
      END IF;
    END IF;
  END LOOP;

  -- Sprints (agile, optional)
  FOR _sp IN SELECT * FROM jsonb_array_elements(COALESCE(_bp->'agile'->'sprints','[]'::jsonb)) LOOP
    _start_off := NULLIF(_sp->'schedule'->>'start_offset_days','')::int;
    _end_off   := NULLIF(_sp->'schedule'->>'end_offset_days','')::int;
    IF _start_off IS NOT NULL THEN
      _d_start := _anchor + _start_off;
      IF _eff_start IS NULL OR _d_start < _eff_start THEN
        _eff_start := _d_start;
        _reasons := _reasons || jsonb_build_object(
          'kind','sprint_before_project','name', _sp->>'name','date', _d_start
        );
      END IF;
    END IF;
    IF _end_off IS NOT NULL THEN
      _d_end := _anchor + _end_off;
      IF _eff_end IS NULL OR _d_end > _eff_end THEN
        _eff_end := _d_end;
        _reasons := _reasons || jsonb_build_object(
          'kind','sprint_after_project','name', _sp->>'name','date', _d_end
        );
      END IF;
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'nominal_start', _nom_start,
    'nominal_end', _nom_end,
    'effective_start', _eff_start,
    'effective_end', _eff_end,
    'requires_widening',
        (_eff_start IS DISTINCT FROM _nom_start)
        OR (_eff_end   IS DISTINCT FROM _nom_end),
    'reasons', _reasons
  );
END;
$function$

CREATE OR REPLACE FUNCTION public._gov_advance_next_expected_date(_base_date date, _frequency_type text, _actual_date_held date)
 RETURNS date
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE _next date; _guard int := 0;
BEGIN
  IF _frequency_type = 'ad_hoc' OR _base_date IS NULL THEN
    RETURN NULL;
  END IF;
  _next := _gov_frequency_next_date(_base_date, _frequency_type);
  IF _next IS NULL THEN RETURN NULL; END IF;
  -- Advance from the prior expected date until strictly after actual_date_held,
  -- preserving cadence rhythm even if the meeting was late.
  WHILE _actual_date_held IS NOT NULL AND _next <= _actual_date_held LOOP
    _next := _gov_frequency_next_date(_next, _frequency_type);
    _guard := _guard + 1;
    IF _guard > 1000 OR _next IS NULL THEN
      EXIT;
    END IF;
  END LOOP;
  RETURN _next;
END; $function$

CREATE OR REPLACE FUNCTION public._gov_assert_project_read(_project_id uuid)
 RETURNS record
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid := auth.uid(); _r record;
BEGIN
  IF _uid IS NULL OR NOT is_active_user(_uid) THEN
    RAISE EXCEPTION 'Unauthorized' USING ERRCODE='42501';
  END IF;
  SELECT id, organization_id, workspace_id INTO _r FROM projects WHERE id = _project_id;
  IF _r IS NULL THEN
    RAISE EXCEPTION 'Project not found' USING ERRCODE='P0002';
  END IF;
  IF NOT public.can_read_project(_uid, _project_id) THEN
    RAISE EXCEPTION 'Forbidden' USING ERRCODE='42501';
  END IF;
  RETURN _r;
END; $function$

CREATE OR REPLACE FUNCTION public._gov_assert_project_write(_project_id uuid)
 RETURNS record
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid := auth.uid(); _r record;
BEGIN
  IF _uid IS NULL OR NOT is_active_user(_uid) THEN
    RAISE EXCEPTION 'Unauthorized' USING ERRCODE='42501'; END IF;
  SELECT id, organization_id, workspace_id INTO _r FROM projects WHERE id = _project_id;
  IF _r IS NULL THEN RAISE EXCEPTION 'Project not found' USING ERRCODE='P0002'; END IF;
  IF NOT public.has_project_pm_authority(_uid, _project_id) THEN
    RAISE EXCEPTION 'Forbidden: project PM authority required' USING ERRCODE='42501'; END IF;
  RETURN _r;
END; $function$

CREATE OR REPLACE FUNCTION public._gov_report_assert_scope(_organization_id uuid, _workspace_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid := auth.uid();
BEGIN
  IF _uid IS NULL OR NOT is_active_user(_uid) THEN
    RAISE EXCEPTION 'Unauthorized' USING ERRCODE = '42501';
  END IF;
  IF _organization_id IS NULL THEN
    RAISE EXCEPTION 'organization_id is required' USING ERRCODE = '22023';
  END IF;
  IF is_org_admin(_uid, _organization_id) THEN
    RETURN;
  END IF;
  -- Non org-admin callers must scope to a workspace they belong to.
  IF _workspace_id IS NULL THEN
    RAISE EXCEPTION 'Forbidden: workspace_id required for non org-admin reporting'
      USING ERRCODE = '42501';
  END IF;
  IF NOT is_workspace_member(_uid, _workspace_id) THEN
    RAISE EXCEPTION 'Forbidden' USING ERRCODE = '42501';
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public._kc_ai_meta_decrypt_array(_cipher text, _org uuid)
 RETURNS text[]
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_plain text;
BEGIN
  IF _cipher IS NULL THEN
    RETURN ARRAY[]::text[];
  END IF;
  v_plain := public.btpm_decrypt(_cipher, _org);
  IF v_plain IS NULL OR v_plain = '' THEN
    RETURN ARRAY[]::text[];
  END IF;
  RETURN ARRAY(SELECT jsonb_array_elements_text(v_plain::jsonb));
EXCEPTION WHEN OTHERS THEN
  RETURN ARRAY[]::text[];
END;
$function$

CREATE OR REPLACE FUNCTION public._kc_ai_meta_decrypt_jsonb(_cipher text, _org uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_plain text;
BEGIN
  IF _cipher IS NULL THEN RETURN NULL; END IF;
  v_plain := public.btpm_decrypt(_cipher, _org);
  IF v_plain IS NULL OR v_plain = '' THEN RETURN NULL; END IF;
  RETURN v_plain::jsonb;
EXCEPTION WHEN OTHERS THEN RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public._kc_ai_meta_encrypt_array(_arr text[], _org uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
  IF _arr IS NULL THEN
    RETURN NULL;
  END IF;
  PERFORM public.ensure_org_encryption_key(_org);
  RETURN public.btpm_encrypt(to_jsonb(_arr)::text, _org);
END;
$function$

CREATE OR REPLACE FUNCTION public._kc_ai_meta_encrypt_jsonb(_value jsonb, _org uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
  IF _value IS NULL THEN RETURN NULL; END IF;
  PERFORM public.ensure_org_encryption_key(_org);
  RETURN public.btpm_encrypt(_value::text, _org);
END;
$function$

CREATE OR REPLACE FUNCTION public._log_entity_material_update(_owner_type text, _owner_id uuid, _organization_id uuid, _workspace_id uuid, _anchor_type text, _anchor_id uuid, _scalar_diff jsonb, _old_user_ids uuid[], _new_user_ids uuid[], _old_object_keys text[], _new_object_keys text[], _old_user_labels jsonb, _new_user_labels jsonb, _old_object_labels jsonb, _new_object_labels jsonb, _entity_title text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_event           text;
  v_meta            jsonb;
  v_added_users     uuid[];
  v_removed_users   uuid[];
  v_added_objects   text[];
  v_removed_objects text[];
  v_has_change      boolean := false;
BEGIN
  v_added_users     := ARRAY(SELECT u FROM unnest(_new_user_ids)   u WHERE u <> ALL (COALESCE(_old_user_ids,   ARRAY[]::uuid[])));
  v_removed_users   := ARRAY(SELECT u FROM unnest(_old_user_ids)   u WHERE u <> ALL (COALESCE(_new_user_ids,   ARRAY[]::uuid[])));
  v_added_objects   := ARRAY(SELECT k FROM unnest(_new_object_keys) k WHERE k <> ALL (COALESCE(_old_object_keys, ARRAY[]::text[])));
  v_removed_objects := ARRAY(SELECT k FROM unnest(_old_object_keys) k WHERE k <> ALL (COALESCE(_new_object_keys, ARRAY[]::text[])));

  IF jsonb_strip_nulls(COALESCE(_scalar_diff, '{}'::jsonb)) <> '{}'::jsonb THEN v_has_change := true; END IF;
  IF array_length(v_added_users,     1) IS NOT NULL THEN v_has_change := true; END IF;
  IF array_length(v_removed_users,   1) IS NOT NULL THEN v_has_change := true; END IF;
  IF array_length(v_added_objects,   1) IS NOT NULL THEN v_has_change := true; END IF;
  IF array_length(v_removed_objects, 1) IS NOT NULL THEN v_has_change := true; END IF;

  IF NOT v_has_change THEN RETURN; END IF;

  v_event := CASE _owner_type WHEN 'blocker' THEN 'blocker_updated' WHEN 'risk' THEN 'risk_updated' ELSE _owner_type || '_updated' END;

  v_meta := jsonb_build_object(
    CASE _owner_type WHEN 'blocker' THEN 'blocker_id' ELSE 'risk_id' END, _owner_id,
    'title',           _entity_title,
    'anchor_type',     _anchor_type,
    'anchor_id',       _anchor_id,
    'changed_fields',  COALESCE(_scalar_diff, '{}'::jsonb),
    'people_added',    COALESCE(_new_user_labels,   '[]'::jsonb),
    'people_removed',  COALESCE(_old_user_labels,   '[]'::jsonb),
    'objects_added',   COALESCE(_new_object_labels, '[]'::jsonb),
    'objects_removed', COALESCE(_old_object_labels, '[]'::jsonb)
  );

  -- Replace the *_added / *_removed arrays with the actually-added/removed
  -- subset (above passed full sets so we have labels). We rebuild here using
  -- the diff arrays.
  v_meta := v_meta
    || jsonb_build_object(
      'people_added', COALESCE((
        SELECT jsonb_agg(elt) FROM jsonb_array_elements(COALESCE(_new_user_labels,'[]'::jsonb)) elt
         WHERE (elt->>'user_id')::uuid = ANY (v_added_users)
      ), '[]'::jsonb),
      'people_removed', COALESCE((
        SELECT jsonb_agg(elt) FROM jsonb_array_elements(COALESCE(_old_user_labels,'[]'::jsonb)) elt
         WHERE (elt->>'user_id')::uuid = ANY (v_removed_users)
      ), '[]'::jsonb),
      'objects_added', COALESCE((
        SELECT jsonb_agg(elt) FROM jsonb_array_elements(COALESCE(_new_object_labels,'[]'::jsonb)) elt
         WHERE ((elt->>'referenced_type') || ':' || (elt->>'referenced_id')) = ANY (v_added_objects)
      ), '[]'::jsonb),
      'objects_removed', COALESCE((
        SELECT jsonb_agg(elt) FROM jsonb_array_elements(COALESCE(_old_object_labels,'[]'::jsonb)) elt
         WHERE ((elt->>'referenced_type') || ':' || (elt->>'referenced_id')) = ANY (v_removed_objects)
      ), '[]'::jsonb)
    );

  -- Write on the entity itself
  PERFORM public.log_activity_event(
    _organization_id, auth.uid(), v_event, _owner_type, _owner_id, v_meta, _workspace_id
  );
  -- Mirror on the anchor object
  IF _anchor_type IS NOT NULL AND _anchor_id IS NOT NULL THEN
    PERFORM public.log_activity_event(
      _organization_id, auth.uid(), v_event, _anchor_type, _anchor_id, v_meta, _workspace_id
    );
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public._normalize_azure_openai_endpoint(_input text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  _s text;
  _rest text;
  _host text;
  _path text;
BEGIN
  IF _input IS NULL THEN RETURN NULL; END IF;
  _s := btrim(_input);
  IF _s = '' THEN RETURN NULL; END IF;

  -- Require HTTPS scheme (case-insensitive) and reject anything else.
  IF _s !~* '^https://' THEN RETURN NULL; END IF;
  _rest := substring(_s FROM 9);

  -- Reject query strings and fragments.
  IF position('?' IN _rest) > 0 OR position('#' IN _rest) > 0 THEN
    RETURN NULL;
  END IF;

  -- Reject embedded userinfo (user:pass@host).
  IF position('@' IN split_part(_rest, '/', 1)) > 0 THEN
    RETURN NULL;
  END IF;

  _host := lower(split_part(_rest, '/', 1));
  IF _host = '' THEN RETURN NULL; END IF;

  -- Reject host:port; Azure endpoints use default 443.
  IF position(':' IN _host) > 0 THEN RETURN NULL; END IF;

  -- Reject IP-address hosts.
  IF _host ~ '^[0-9]+(\.[0-9]+){3}$' THEN RETURN NULL; END IF;
  IF _host ~ '^[0-9.]+$' THEN RETURN NULL; END IF;
  IF _host ~ '^\[' THEN RETURN NULL; END IF; -- ipv6 literal

  -- Whitelist Azure OpenAI host suffixes anchored at end.
  IF NOT (_host ~ '\.openai\.azure\.com$' OR _host ~ '\.services\.ai\.azure\.com$') THEN
    RETURN NULL;
  END IF;

  -- Extract path portion after host.
  _path := substring(_rest FROM (length(split_part(_rest, '/', 1)) + 1));
  IF _path IS NULL THEN _path := ''; END IF;

  -- Trim trailing slashes.
  _path := regexp_replace(_path, '/+$', '');
  -- Trim canonical /openai/v1 suffix if present (case-insensitive).
  _path := regexp_replace(_path, '/openai/v1$', '', 'i');
  -- Any remaining non-empty path is disallowed.
  IF _path <> '' THEN RETURN NULL; END IF;

  RETURN 'https://' || _host;
END $function$

CREATE OR REPLACE FUNCTION public._pbi_assert_safe_metadata(_meta jsonb)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  k text;
  unsafe text[] := ARRAY[
    'token','access_token','refresh_token','authorization',
    'client_secret','secret','password','raw_payload','raw_response',
    'comments','execution_updates','attachment','email_body'
  ];
BEGIN
  IF _meta IS NULL THEN RETURN; END IF;
  IF jsonb_typeof(_meta) <> 'object' THEN
    RAISE EXCEPTION 'safe_metadata must be a JSON object';
  END IF;
  FOR k IN SELECT jsonb_object_keys(_meta) LOOP
    IF lower(k) = ANY(unsafe) THEN
      RAISE EXCEPTION 'safe_metadata contains forbidden key: %', k;
    END IF;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public._recompute_phase_completion(_phase_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_phase            public.phases%ROWTYPE;
  v_eligible_count   integer;
  v_incomplete_count integer;
  v_should_be_complete boolean;
BEGIN
  SELECT * INTO v_phase FROM public.phases p WHERE p.id = _phase_id;
  IF NOT FOUND THEN
    RETURN;
  END IF;

  IF v_phase.is_archived OR v_phase.status = 'cancelled' THEN
    RETURN;
  END IF;

  SELECT
    COUNT(*),
    COUNT(*) FILTER (WHERE t.status <> 'completed')
  INTO v_eligible_count, v_incomplete_count
  FROM public.tasks t
  WHERE t.phase_id = _phase_id
    AND t.is_archived = false
    AND t.status <> 'cancelled';

  v_should_be_complete := (v_eligible_count > 0 AND v_incomplete_count = 0);

  IF v_should_be_complete AND v_phase.status <> 'completed' THEN
    PERFORM set_config('app.allow_lifecycle_bypass', 'on', true);
    UPDATE public.phases p
    SET status = 'completed', updated_at = now()
    WHERE p.id = _phase_id;
    PERFORM set_config('app.allow_lifecycle_bypass', '', true);

    PERFORM public.log_activity_event(
      v_phase.organization_id,
      NULL,
      'phase_auto_completed',
      'phase',
      _phase_id,
      jsonb_build_object(
        'prior_status', v_phase.status,
        'new_status', 'completed',
        'reason', 'all_eligible_tasks_completed',
        'eligible_task_count', v_eligible_count,
        'project_id', v_phase.project_id
      ),
      v_phase.workspace_id
    );

  ELSIF (NOT v_should_be_complete) AND v_phase.status = 'completed' THEN
    PERFORM set_config('app.allow_lifecycle_bypass', 'on', true);
    UPDATE public.phases p
    SET status = 'active', updated_at = now()
    WHERE p.id = _phase_id;
    PERFORM set_config('app.allow_lifecycle_bypass', '', true);

    PERFORM public.log_activity_event(
      v_phase.organization_id,
      NULL,
      'phase_auto_reopened',
      'phase',
      _phase_id,
      jsonb_build_object(
        'prior_status', 'completed',
        'new_status', 'active',
        'reason', CASE
          WHEN v_eligible_count = 0 THEN 'no_eligible_tasks'
          ELSE 'incomplete_eligible_tasks'
        END,
        'eligible_task_count', v_eligible_count,
        'incomplete_task_count', v_incomplete_count,
        'project_id', v_phase.project_id
      ),
      v_phase.workspace_id
    );
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public._sanitize_storage_segment(_input text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE _s text;
BEGIN
  IF _input IS NULL THEN RETURN NULL; END IF;
  _s := btrim(_input);
  IF length(_s) = 0 THEN RETURN NULL; END IF;
  IF _s ~ '[\/\\]' OR _s ~ '[[:cntrl:]]' OR _s = '.' OR _s = '..' OR _s ~ '\.\.' THEN
    RAISE EXCEPTION 'Unsafe storage segment: %', _input;
  END IF;
  _s := regexp_replace(_s, '[^A-Za-z0-9._\-\(\) ]', '_', 'g');
  IF length(_s) > 200 THEN _s := substr(_s, 1, 200); END IF;
  RETURN _s;
END $function$

CREATE OR REPLACE FUNCTION public._snapshot_baseline(_project_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_proj public.projects%ROWTYPE;
        v_bad_phase int; v_bad_task int; v_phase_oob int; v_task_oob int;
BEGIN
  SELECT * INTO v_proj FROM public.projects WHERE id = _project_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Project not found'; END IF;
  IF NOT public.has_project_pm_authority(auth.uid(), _project_id) THEN
    RAISE EXCEPTION 'Not authorized to baseline this project'; END IF;
  IF v_proj.start_date IS NULL OR v_proj.target_end_date IS NULL THEN
    RAISE EXCEPTION 'Project planned start and target end dates are required.'; END IF;
  IF v_proj.start_date > v_proj.target_end_date THEN
    RAISE EXCEPTION 'Project planned start is after target end date.'; END IF;
  SELECT count(*) INTO v_bad_phase FROM public.phases
   WHERE project_id=_project_id AND is_archived=false
     AND (start_date IS NULL OR target_end_date IS NULL OR start_date > target_end_date);
  IF v_bad_phase > 0 THEN RAISE EXCEPTION 'All phases must have a valid planned start and end date (% invalid).', v_bad_phase; END IF;
  SELECT count(*) INTO v_bad_task FROM public.tasks
   WHERE project_id=_project_id AND is_archived=false
     AND (start_date IS NULL OR due_date IS NULL OR start_date > due_date);
  IF v_bad_task > 0 THEN RAISE EXCEPTION 'All tasks must have a valid planned start and due date (% invalid).', v_bad_task; END IF;
  SELECT count(*) INTO v_phase_oob FROM public.phases
   WHERE project_id=_project_id AND is_archived=false
     AND (start_date < v_proj.start_date OR target_end_date > v_proj.target_end_date);
  IF v_phase_oob > 0 THEN RAISE EXCEPTION 'Phase planned dates must fit within project range (% out of bounds).', v_phase_oob; END IF;
  SELECT count(*) INTO v_task_oob FROM public.tasks t JOIN public.phases p ON p.id=t.phase_id
   WHERE t.project_id=_project_id AND t.is_archived=false AND p.is_archived=false
     AND (t.start_date < p.start_date OR t.due_date > p.target_end_date);
  IF v_task_oob > 0 THEN RAISE EXCEPTION 'Task planned dates must fit within their phase range (% out of bounds).', v_task_oob; END IF;
  PERFORM set_config('btpm.baseline_write','on',true);
  UPDATE public.projects SET baseline_start_date=start_date, baseline_end_date=target_end_date,
    is_baselined=true, baseline_approved_at=now(), baseline_approved_by=auth.uid() WHERE id=_project_id;
  UPDATE public.phases SET baseline_start_date=start_date, baseline_end_date=target_end_date,
    added_after_baseline=false WHERE project_id=_project_id AND is_archived=false;
  UPDATE public.tasks SET baseline_start_date=start_date, baseline_end_date=due_date,
    added_after_baseline=false WHERE project_id=_project_id AND is_archived=false;
  PERFORM set_config('btpm.baseline_write','off',true);
END; $function$

CREATE OR REPLACE FUNCTION public._validate_object_links(_links jsonb, _workspace_id uuid, _organization_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v jsonb;
  v_type text;
  v_id uuid;
  v_count int;
BEGIN
  IF _links IS NULL OR jsonb_typeof(_links) <> 'array' THEN RETURN; END IF;
  FOR v IN SELECT * FROM jsonb_array_elements(_links) LOOP
    v_type := v->>'referenced_type';
    v_id := (v->>'referenced_id')::uuid;
    IF v_type NOT IN ('project','phase','task') THEN
      RAISE EXCEPTION 'Invalid object link type: %', v_type;
    END IF;
    -- Same-workspace + same-org enforcement
    IF v_type = 'project' THEN
      SELECT count(*) INTO v_count FROM public.projects
       WHERE id = v_id AND workspace_id = _workspace_id AND organization_id = _organization_id;
    ELSIF v_type = 'phase' THEN
      SELECT count(*) INTO v_count FROM public.phases
       WHERE id = v_id AND workspace_id = _workspace_id AND organization_id = _organization_id;
    ELSE
      SELECT count(*) INTO v_count FROM public.tasks
       WHERE id = v_id AND workspace_id = _workspace_id AND organization_id = _organization_id;
    END IF;
    IF v_count = 0 THEN
      RAISE EXCEPTION 'Linked % % is not in this workspace', v_type, v_id;
    END IF;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public._validate_user_links(_links jsonb, _workspace_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v jsonb;
  v_user uuid;
  v_count int;
BEGIN
  IF _links IS NULL OR jsonb_typeof(_links) <> 'array' THEN RETURN; END IF;
  FOR v IN SELECT * FROM jsonb_array_elements(_links) LOOP
    v_user := (v->>'user_id')::uuid;
    SELECT count(*) INTO v_count FROM public.workspace_memberships
     WHERE user_id = v_user AND workspace_id = _workspace_id;
    IF v_count = 0 THEN
      RAISE EXCEPTION 'Linked user % is not a member of this workspace', v_user;
    END IF;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public._validate_user_links(_links jsonb, _workspace_id uuid, _project_id uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v jsonb; v_user uuid; v_stk uuid; v_count int;
BEGIN
  IF _links IS NULL OR jsonb_typeof(_links) <> 'array' THEN RETURN; END IF;
  FOR v IN SELECT * FROM jsonb_array_elements(_links) LOOP
    v_user := NULLIF(v->>'user_id','')::uuid;
    v_stk  := NULLIF(v->>'stakeholder_id','')::uuid;
    IF (v_user IS NULL AND v_stk IS NULL) OR (v_user IS NOT NULL AND v_stk IS NOT NULL) THEN
      RAISE EXCEPTION 'Each person link must have exactly one of user_id or stakeholder_id';
    END IF;
    IF v_user IS NOT NULL THEN
      SELECT count(*) INTO v_count FROM public.workspace_memberships
       WHERE user_id = v_user AND workspace_id = _workspace_id;
      IF v_count = 0 THEN
        RAISE EXCEPTION 'Linked user % is not a member of this workspace', v_user;
      END IF;
    ELSE
      IF _project_id IS NULL THEN
        RAISE EXCEPTION 'Stakeholder links require a project context';
      END IF;
      SELECT count(*) INTO v_count FROM public.project_stakeholders
       WHERE id = v_stk AND project_id = _project_id
         AND workspace_id = _workspace_id AND removed_at IS NULL;
      IF v_count = 0 THEN
        RAISE EXCEPTION 'Linked stakeholder % is not an active stakeholder of this project', v_stk;
      END IF;
    END IF;
  END LOOP;
END $function$

CREATE OR REPLACE FUNCTION public.accept_invitation(_token uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  _inv RECORD;
  _user_id uuid;
  _user_email text;
  _token_hash text;
  _tenant_id uuid;
  _target_org_role public.organization_role;
BEGIN
  _user_id := auth.uid();
  IF _user_id IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF NOT public.is_active_user(_user_id) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;

  _token_hash := encode(digest(_token::text, 'sha256'), 'hex');
  SELECT i.id, i.email, i.organization_id, i.workspace_id, i.tenant_id,
         i.tenant_role, i.organization_role, i.role, i.status, i.expires_at
    INTO _inv
    FROM public.invitations i
   WHERE i.token = _token_hash AND i.status = 'pending' AND i.expires_at > now();
  IF _inv.id IS NULL THEN RAISE EXCEPTION 'Invitation not found, expired, or already used'; END IF;

  SELECT email INTO _user_email FROM auth.users WHERE id = _user_id;
  IF lower(_user_email) <> lower(_inv.email) THEN RAISE EXCEPTION 'Invitation email does not match your account'; END IF;

  -- Resolve tenant id from organization when the invitation predates tenant_id column.
  _tenant_id := _inv.tenant_id;
  IF _tenant_id IS NULL AND _inv.organization_id IS NOT NULL THEN
    SELECT tenant_id INTO _tenant_id FROM public.organizations WHERE id = _inv.organization_id;
  END IF;

  -- Profile organization link (legacy field, kept for compatibility).
  IF _inv.organization_id IS NOT NULL THEN
    UPDATE public.profiles
       SET organization_id = _inv.organization_id
     WHERE id = _user_id AND (organization_id IS NULL OR organization_id = _inv.organization_id);
  END IF;

  -- Tenant membership (activate if missing/deactivated).
  IF _tenant_id IS NOT NULL THEN
    INSERT INTO public.tenant_memberships (tenant_id, user_id, role, status, created_by, updated_by)
    VALUES (_tenant_id, _user_id,
            COALESCE(_inv.tenant_role, 'tenant_member'::public.tenant_role),
            'active'::public.membership_status, _user_id, _user_id)
    ON CONFLICT (tenant_id, user_id) DO UPDATE
      SET status = 'active'::public.membership_status,
          updated_at = now();
  END IF;

  -- Organization membership.
  IF _inv.organization_id IS NOT NULL AND _tenant_id IS NOT NULL THEN
    _target_org_role := COALESCE(
      _inv.organization_role,
      CASE WHEN _inv.role = 'org_admin' THEN 'org_admin'::public.organization_role
           ELSE 'org_member'::public.organization_role END
    );
    INSERT INTO public.organization_memberships
      (tenant_id, organization_id, user_id, role, status, created_by, updated_by)
    VALUES (_tenant_id, _inv.organization_id, _user_id, _target_org_role,
            'active'::public.membership_status, _user_id, _user_id)
    ON CONFLICT (organization_id, user_id) DO UPDATE
      SET status = 'active'::public.membership_status,
          role = CASE WHEN EXCLUDED.role = 'org_admin' THEN 'org_admin'::public.organization_role
                      ELSE public.organization_memberships.role END,
          updated_at = now();
  END IF;

  -- Workspace membership + legacy user_roles preservation.
  IF _inv.workspace_id IS NOT NULL THEN
    INSERT INTO public.workspace_memberships (workspace_id, user_id)
    VALUES (_inv.workspace_id, _user_id) ON CONFLICT (workspace_id, user_id) DO NOTHING;
    IF _inv.role IS NOT NULL AND _inv.role <> 'org_admin' THEN
      INSERT INTO public.user_roles (user_id, role, organization_id, workspace_id)
      VALUES (_user_id, _inv.role, _inv.organization_id, _inv.workspace_id)
      ON CONFLICT DO NOTHING;
    END IF;
  ELSIF _inv.role = 'org_admin' AND _inv.organization_id IS NOT NULL THEN
    INSERT INTO public.user_roles (user_id, role, organization_id)
    VALUES (_user_id, 'org_admin', _inv.organization_id) ON CONFLICT DO NOTHING;
  END IF;

  UPDATE public.invitations SET status = 'accepted', updated_at = now() WHERE id = _inv.id;

  -- Conservative context seed for single-org users only.
  PERFORM public._seed_single_org_preference(_user_id);

  PERFORM public.log_activity_event(_inv.organization_id, _user_id, 'invitation_accepted',
    'invitation', _inv.id,
    jsonb_build_object('email', _inv.email, 'role', _inv.role::text, 'workspace_id', _inv.workspace_id),
    _inv.workspace_id);
  RETURN _inv.id;
END;
$function$

CREATE OR REPLACE FUNCTION public.accept_pending_invitation_for_user(_user_id uuid, _invitation_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _inv record;
  _email text;
  _org_tenant uuid;
  _ws_org uuid;
  _ws_org_tenant uuid;
  _profile_org uuid;
  _target_org_role public.organization_role;
  _effective_organization_id uuid;
BEGIN
  IF _user_id IS NULL OR _invitation_id IS NULL THEN
    RAISE EXCEPTION 'accept_pending_invitation_for_user: user_id and invitation_id required';
  END IF;

  SELECT lower(au.email) INTO _email FROM auth.users au WHERE au.id = _user_id;
  IF _email IS NULL THEN RAISE EXCEPTION 'User % has no email', _user_id; END IF;

  SELECT i.id, i.email, i.organization_id, i.workspace_id, i.tenant_id,
         i.tenant_role, i.organization_role, i.role, i.status, i.expires_at
  INTO _inv
  FROM public.invitations i
  WHERE i.id = _invitation_id;

  IF _inv.id IS NULL THEN RAISE EXCEPTION 'Invitation not found'; END IF;
  IF _inv.status <> 'pending' THEN RAISE EXCEPTION 'Invitation is not pending (status=%).', _inv.status; END IF;
  IF _inv.expires_at IS NULL OR _inv.expires_at <= now() THEN RAISE EXCEPTION 'Invitation is expired'; END IF;
  IF lower(_inv.email) <> _email THEN
    RAISE EXCEPTION 'Invitation email does not match authenticated user';
  END IF;
  IF _inv.tenant_id IS NULL THEN
    RAISE EXCEPTION 'Invitation is missing tenant_id (invalid post-4D.2 state)';
  END IF;

  -- Organization -> tenant consistency
  IF _inv.organization_id IS NOT NULL THEN
    SELECT tenant_id INTO _org_tenant FROM public.organizations WHERE id = _inv.organization_id;
    IF _org_tenant IS NULL THEN RAISE EXCEPTION 'Invitation organization not found'; END IF;
    IF _org_tenant <> _inv.tenant_id THEN
      RAISE EXCEPTION 'Invitation tenant does not match organization tenant';
    END IF;
  END IF;

  -- Workspace -> organization -> tenant consistency
  IF _inv.workspace_id IS NOT NULL THEN
    SELECT organization_id INTO _ws_org FROM public.workspaces WHERE id = _inv.workspace_id;
    IF _ws_org IS NULL THEN RAISE EXCEPTION 'Invitation workspace not found'; END IF;
    IF _inv.organization_id IS NOT NULL AND _ws_org <> _inv.organization_id THEN
      RAISE EXCEPTION 'Invitation workspace does not belong to invitation organization';
    END IF;
    SELECT tenant_id INTO _ws_org_tenant FROM public.organizations WHERE id = _ws_org;
    IF _ws_org_tenant IS NULL THEN RAISE EXCEPTION 'Invitation workspace organization not found'; END IF;
    IF _ws_org_tenant <> _inv.tenant_id THEN
      RAISE EXCEPTION 'Invitation workspace organization tenant does not match invitation tenant';
    END IF;
  END IF;

  -- Effective organization: invitation.org > workspace.org > NULL (tenant-only)
  _effective_organization_id := COALESCE(_inv.organization_id, _ws_org);

  -- Profile: never overwrite existing organization_id; set only when currently NULL and we have one
  SELECT organization_id INTO _profile_org FROM public.profiles WHERE id = _user_id;
  IF _profile_org IS NULL AND _effective_organization_id IS NOT NULL THEN
    INSERT INTO public.profiles (id, email, organization_id)
    VALUES (_user_id, _email, _effective_organization_id)
    ON CONFLICT (id) DO UPDATE SET
      organization_id = COALESCE(public.profiles.organization_id, EXCLUDED.organization_id),
      email = COALESCE(public.profiles.email, EXCLUDED.email);
  ELSE
    INSERT INTO public.profiles (id, email)
    VALUES (_user_id, _email)
    ON CONFLICT (id) DO UPDATE SET email = COALESCE(public.profiles.email, EXCLUDED.email);
  END IF;

  -- Tenant membership
  INSERT INTO public.tenant_memberships (tenant_id, user_id, role, status, created_by)
  VALUES (_inv.tenant_id, _user_id, COALESCE(_inv.tenant_role, 'tenant_member'), 'active', _user_id)
  ON CONFLICT (tenant_id, user_id) DO UPDATE
    SET status = 'active', updated_at = now();

  -- Organization membership (effective org — includes workspace-only derived org)
  IF _effective_organization_id IS NOT NULL THEN
    _target_org_role := COALESCE(
      _inv.organization_role,
      CASE WHEN _inv.role = 'org_admin' THEN 'org_admin'::public.organization_role
           ELSE 'org_member'::public.organization_role END
    );
    INSERT INTO public.organization_memberships
      (tenant_id, organization_id, user_id, role, status, created_by)
    VALUES (_inv.tenant_id, _effective_organization_id, _user_id, _target_org_role, 'active', _user_id)
    ON CONFLICT (organization_id, user_id) DO UPDATE
      SET status = 'active',
          role = CASE
            WHEN EXCLUDED.role = 'org_admin' THEN 'org_admin'::public.organization_role
            ELSE public.organization_memberships.role
          END,
          updated_at = now();
  END IF;

  -- Workspace membership + legacy user_roles preservation
  IF _inv.workspace_id IS NOT NULL THEN
    INSERT INTO public.workspace_memberships (workspace_id, user_id)
    VALUES (_inv.workspace_id, _user_id)
    ON CONFLICT DO NOTHING;

    IF _inv.role IS NOT NULL AND _inv.role <> 'org_admin' AND _effective_organization_id IS NOT NULL THEN
      INSERT INTO public.user_roles (user_id, role, organization_id, workspace_id)
      VALUES (_user_id, _inv.role, _effective_organization_id, _inv.workspace_id)
      ON CONFLICT DO NOTHING;
    END IF;
  ELSIF _inv.role = 'org_admin' AND _effective_organization_id IS NOT NULL THEN
    INSERT INTO public.user_roles (user_id, role, organization_id)
    VALUES (_user_id, 'org_admin', _effective_organization_id)
    ON CONFLICT DO NOTHING;
  END IF;

  -- Mark accepted
  UPDATE public.invitations
     SET status = 'accepted', updated_at = now()
   WHERE id = _inv.id AND status = 'pending';

  -- Activity log (best-effort) when organization context exists
  IF _effective_organization_id IS NOT NULL THEN
    BEGIN
      INSERT INTO public.activity_events
        (organization_id, actor_id, event_type, target_type, target_id, metadata)
      VALUES (_effective_organization_id, _user_id, 'invitation_accepted', 'invitation', _inv.id,
              jsonb_build_object(
                'email', _email,
                'source', 'accept_pending_invitation_for_user',
                'workspace_id', _inv.workspace_id,
                'effective_organization_id', _effective_organization_id,
                'invitation_organization_id', _inv.organization_id
              )::text);
    EXCEPTION WHEN OTHERS THEN
      RAISE NOTICE 'activity_events insert skipped for invitation %: %', _inv.id, SQLERRM;
    END;
  END IF;

  RETURN true;
END $function$

CREATE OR REPLACE FUNCTION public.acknowledge_api_d_policy(_client_key text, _correlation_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  _uid uuid := auth.uid();
  _client public.api_clients%rowtype;
  _policy public.api_client_policy_versions%rowtype;
  _policy_count integer;
  _org_count integer;
  _existing public.api_user_policy_acknowledgements%rowtype;
  _reactivated boolean := false;
  _first boolean := false;
  _fail_closed constant jsonb := jsonb_build_object('ok', false, 'changed', false, 'acknowledged', false);
begin
  if _uid is null then return _fail_closed; end if;

  if _client_key is null
     or length(_client_key) < 3 or length(_client_key) > 64
     or _client_key !~ '^[a-z0-9][a-z0-9_.-]{1,62}[a-z0-9]$' then
    return _fail_closed;
  end if;

  if _correlation_id is not null
     and _correlation_id !~ '^[A-Za-z0-9_-]{1,64}$' then
    return _fail_closed;
  end if;

  if not exists (
    select 1 from public.profiles p
    where p.id = _uid and p.is_active = true
  ) then
    return _fail_closed;
  end if;

  select * into _client
  from public.api_clients
  where client_key = _client_key and lifecycle_status = 'active'
  limit 1;
  if _client.id is null then return _fail_closed; end if;

  select count(*) into _policy_count
  from public.api_client_policy_versions
  where api_client_id = _client.id and lifecycle_status = 'active';
  if _policy_count <> 1 then return _fail_closed; end if;

  select * into _policy
  from public.api_client_policy_versions
  where api_client_id = _client.id and lifecycle_status = 'active'
  limit 1;

  -- Eligible-org gate: authoritative org membership ∩ active tenant chain
  -- ∩ current active tenant membership ∩ enabled API-C org enablement.
  select count(*) into _org_count
  from public.organization_memberships om
  join public.organizations o
    on o.id = om.organization_id
  join public.tenants t
    on t.id = o.tenant_id
   and t.id = om.tenant_id
  join public.tenant_memberships tm_o
    on tm_o.tenant_id = t.id
   and tm_o.user_id = _uid
   and tm_o.status = 'active'
   and tm_o.deactivated_at is null
  join public.api_organization_client_enablements oe
    on oe.organization_id = o.id
   and oe.tenant_id = t.id
   and oe.api_client_id = _client.id
   and oe.lifecycle_status = 'enabled'
  where om.user_id = _uid
    and om.status = 'active'
    and om.deactivated_at is null
    and t.status = 'active'
    and t.suspended_at is null
    and t.archived_at is null
    and t.purged_at is null;

  if _org_count = 0 then return _fail_closed; end if;

  -- Existing acknowledgement row for the exact identity.
  select * into _existing
  from public.api_user_policy_acknowledgements
  where user_id = _uid
    and api_client_id = _client.id
    and policy_version_id = _policy.id
  limit 1;

  if _existing.id is not null and _existing.revoked_at is null then
    -- Idempotent no-op — do not append an audit row.
    return jsonb_build_object('ok', true, 'changed', false, 'acknowledged', true);
  end if;

  if _existing.id is not null then
    -- Reactivate revoked row.
    update public.api_user_policy_acknowledgements
       set revoked_at = null,
           acknowledged_at = now(),
           ack_metadata = jsonb_build_object('source', 'btpm_ui')
     where id = _existing.id;
    _reactivated := true;
  else
    insert into public.api_user_policy_acknowledgements
      (user_id, api_client_id, policy_version_id, acknowledged_at, ack_metadata)
    values
      (_uid, _client.id, _policy.id, now(), jsonb_build_object('source', 'btpm_ui'));
    _first := true;
  end if;

  insert into public.api_consent_audit_events
    (actor_user_id, api_client_id, policy_version_id, action, source_channel, correlation_id)
  values
    (_uid, _client.id, _policy.id, 'acknowledge', 'btpm_ui', _correlation_id);

  return jsonb_build_object('ok', true, 'changed', true, 'acknowledged', true);
exception
  when others then
    return _fail_closed;
end;
$function$

CREATE OR REPLACE FUNCTION public.activate_ai_instruction_template(_id uuid)
 RETURNS ai_instruction_templates
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _org_id uuid;
  _row public.ai_instruction_templates;
BEGIN
  SELECT organization_id INTO _org_id FROM public.profiles WHERE id = auth.uid();
  IF _org_id IS NULL OR NOT public.is_org_admin(auth.uid(), _org_id) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO _row FROM public.ai_instruction_templates WHERE id = _id;
  IF _row.id IS NULL THEN RAISE EXCEPTION 'template not found'; END IF;
  IF _row.organization_id <> _org_id THEN RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501'; END IF;
  IF _row.status = 'archived' THEN RAISE EXCEPTION 'cannot activate archived version'; END IF;
  IF _row.status = 'active' THEN RETURN _row; END IF;

  -- AI.8.1e: demote previously active version to 'draft' (was 'archived'),
  -- so version switching remains reversible. Explicit archive remains the only
  -- path to 'archived' via archive_ai_instruction_template.
  UPDATE public.ai_instruction_templates
     SET status = 'draft'
   WHERE organization_id = _org_id
     AND feature_key = _row.feature_key
     AND status = 'active'
     AND id <> _id;

  UPDATE public.ai_instruction_templates
     SET status = 'active',
         activated_by = auth.uid(),
         activated_at = now()
   WHERE id = _id
  RETURNING * INTO _row;

  RETURN _row;
END;
$function$

CREATE OR REPLACE FUNCTION public.add_adoption_template_tasks_to_existing_plan(_project_id uuid, _template_id uuid DEFAULT NULL::uuid, _template_key text DEFAULT 'btpm_standard_adoption'::text, _selected_task_keys text[] DEFAULT '{}'::text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _org uuid;
  _ws uuid;
  _plan_id uuid;
  _phase_id uuid;
  _phase_start date;
  _phase_end date;
  _created_initiatives int := 0;
  _created_tasks int := 0;
  _skipped int := 0;
  _selected_count int := 0;
  _existing_titles text[] := ARRAY[]::text[];
  _init_key text;
  _task_key text;
  _init_name text;
  _init_readiness text;
  _init_sort int;
  _init_summary text;
  _task_title text;
  _task_desc text;
  _norm_title text;
  _initiative_id uuid;
  _next_sort int;
  _is_standard boolean := (_template_id IS NULL);
  _max_init_sort int;
BEGIN
  IF _uid IS NULL OR NOT public.is_active_user(_uid) THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;

  SELECT organization_id, workspace_id INTO _org, _ws
  FROM public.projects WHERE id = _project_id;
  IF _org IS NULL THEN RAISE EXCEPTION 'invalid_project'; END IF;

  IF NOT public.has_pm_authority(_uid, _ws) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  SELECT id INTO _plan_id
  FROM public.adoption_plans
  WHERE project_id = _project_id AND is_archived = false
  LIMIT 1;
  IF _plan_id IS NULL THEN
    RAISE EXCEPTION 'adoption_plan_required';
  END IF;

  IF _is_standard THEN
    IF COALESCE(_template_key, 'btpm_standard_adoption') <> 'btpm_standard_adoption' THEN
      RAISE EXCEPTION 'invalid_template_key';
    END IF;
  ELSE
    IF NOT EXISTS (
      SELECT 1 FROM public.adoption_templates
      WHERE id = _template_id AND workspace_id = _ws AND is_archived = false
    ) THEN
      RAISE EXCEPTION 'invalid_template';
    END IF;
  END IF;

  SELECT phase_id INTO _phase_id
  FROM public.tasks
  WHERE project_id = _project_id
    AND is_archived = false
    AND is_adoption_related = true
    AND phase_id IS NOT NULL
  GROUP BY phase_id
  ORDER BY count(*) DESC
  LIMIT 1;

  IF _phase_id IS NULL THEN
    RAISE EXCEPTION 'adoption_phase_not_found';
  END IF;

  SELECT start_date, target_end_date INTO _phase_start, _phase_end
  FROM public.phases WHERE id = _phase_id;

  IF EXISTS (SELECT 1 FROM public.projects WHERE id = _project_id AND COALESCE(is_baselined,false))
     AND (_phase_start IS NULL OR _phase_end IS NULL) THEN
    RAISE EXCEPTION 'adoption_phase_dates_required_for_baselined_project';
  END IF;

  IF _selected_task_keys IS NULL OR array_length(_selected_task_keys, 1) IS NULL THEN
    RAISE EXCEPTION 'adoption_template_selection_empty';
  END IF;
  _selected_count := array_length(_selected_task_keys, 1);

  SELECT COALESCE(array_agg(DISTINCT lower(btrim(regexp_replace(
      public.btpm_decrypt(name, organization_id), '\s+', ' ', 'g')))), ARRAY[]::text[])
    INTO _existing_titles
  FROM public.tasks
  WHERE project_id = _project_id
    AND is_archived = false
    AND is_adoption_related = true;

  SELECT COALESCE(MAX(sort_order), -1) INTO _max_init_sort
  FROM public.adoption_initiatives
  WHERE adoption_plan_id = _plan_id AND is_archived = false;

  FOR _init_key, _task_key IN
    SELECT split_part(k,'.',1) AS ik,
           substring(k from position('.' in k)+1) AS tk
    FROM unnest(_selected_task_keys) AS k
    WHERE position('.' in k) > 0
  LOOP
    _init_name := NULL; _init_readiness := NULL; _init_sort := NULL; _init_summary := NULL;
    _task_title := NULL; _task_desc := NULL;

    IF _is_standard THEN
      SELECT i->>'name', i->>'readiness_area', (i->>'sort_order')::int, i->>'summary',
             t->>'title', NULL::text
        INTO _init_name, _init_readiness, _init_sort, _init_summary,
             _task_title, _task_desc
      FROM jsonb_array_elements(public._btpm_adoption_template_v1()) AS i,
           jsonb_array_elements(i->'tasks') AS t
      WHERE i->>'key' = _init_key AND t->>'key' = _task_key;
    ELSE
      SELECT public.btpm_decrypt(i.name, i.organization_id),
             i.readiness_area, i.sort_order,
             public.btpm_decrypt(i.summary, i.organization_id),
             public.btpm_decrypt(t.title, t.organization_id),
             public.btpm_decrypt(t.description, t.organization_id)
        INTO _init_name, _init_readiness, _init_sort, _init_summary,
             _task_title, _task_desc
      FROM public.adoption_template_initiatives i
      JOIN public.adoption_template_tasks t ON t.adoption_template_initiative_id = i.id
      WHERE i.adoption_template_id = _template_id
        AND i.is_archived = false AND t.is_archived = false
        AND i.template_key = _init_key AND t.template_key = _task_key
      LIMIT 1;
    END IF;

    IF _task_title IS NULL OR btrim(_task_title) = '' THEN
      _skipped := _skipped + 1;
      CONTINUE;
    END IF;

    _norm_title := lower(btrim(regexp_replace(_task_title, '\s+', ' ', 'g')));

    IF _norm_title = ANY(_existing_titles) THEN
      _skipped := _skipped + 1;
      CONTINUE;
    END IF;

    SELECT id INTO _initiative_id
    FROM public.adoption_initiatives
    WHERE adoption_plan_id = _plan_id AND is_archived = false
      AND readiness_area = _init_readiness
    LIMIT 1;

    IF _initiative_id IS NULL THEN
      _max_init_sort := _max_init_sort + 1;
      INSERT INTO public.adoption_initiatives(
        organization_id, workspace_id, project_id, adoption_plan_id,
        name, summary, readiness_area, status, priority, sort_order, created_by
      ) VALUES (
        _org, _ws, _project_id, _plan_id,
        _init_name, _init_summary, _init_readiness,
        'planned'::public.adoption_initiative_status,
        'medium'::public.pm_priority,
        _max_init_sort, _uid
      ) RETURNING id INTO _initiative_id;
      _created_initiatives := _created_initiatives + 1;
    END IF;

    SELECT COALESCE(MAX(sort_order), -1) + 10 INTO _next_sort
    FROM public.tasks WHERE phase_id = _phase_id AND is_archived = false;

    INSERT INTO public.tasks(
      organization_id, workspace_id, project_id, phase_id,
      name, description, task_type, status, priority, sort_order,
      start_date, due_date,
      is_adoption_related, adoption_initiative_id, created_by
    ) VALUES (
      _org, _ws, _project_id, _phase_id,
      _task_title, _task_desc,
      'work_item'::public.task_type,
      'planned'::public.pm_status,
      'medium'::public.pm_priority,
      _next_sort,
      _phase_start, _phase_end,
      true, _initiative_id, _uid
    );
    _created_tasks := _created_tasks + 1;
    _existing_titles := _existing_titles || _norm_title;
  END LOOP;

  PERFORM public.log_activity_event(
    _org,
    _uid,
    'adoption_template_tasks_added',
    'project',
    _project_id,
    jsonb_build_object(
      'adoption_plan_id', _plan_id,
      'phase_id', _phase_id,
      'template_id', _template_id,
      'template_key', CASE WHEN _is_standard THEN _template_key ELSE NULL END,
      'created_initiative_count', _created_initiatives,
      'created_task_count', _created_tasks,
      'skipped_duplicate_count', _skipped,
      'selected_task_count', _selected_count
    ),
    _ws
  );

  RETURN jsonb_build_object(
    'project_id', _project_id,
    'adoption_plan_id', _plan_id,
    'phase_id', _phase_id,
    'template_id', _template_id,
    'template_key', CASE WHEN _is_standard THEN _template_key ELSE NULL END,
    'created_initiative_count', _created_initiatives,
    'created_task_count', _created_tasks,
    'skipped_duplicate_count', _skipped,
    'selected_task_count', _selected_count
  );
END $function$

CREATE OR REPLACE FUNCTION public.add_project_people_preset_member(_preset_id uuid, _expected_preset_updated_at timestamp with time zone, _member_kind text, _stakeholder_type text, _user_id uuid, _external_name text, _canonical_role_key text, _role_label text, _correlation_id text DEFAULT NULL::text, _idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor          uuid := auth.uid();
  v_preset         public.project_people_presets;
  v_new_id         uuid;
  v_role_norm      text;
  v_canonical_norm text;
  v_external_norm  text;
  v_dupe_external  uuid;
  r                record;
BEGIN
  SELECT * INTO v_preset FROM public.project_people_presets WHERE id = _preset_id FOR UPDATE;
  IF v_preset.id IS NULL THEN
    RETURN public.pmg_build_result('not_authorized', 'add_project_people_preset_member',
      'project_people_preset_member', NULL, NULL, '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL);
  END IF;
  PERFORM public._ppp_authorize_write(v_actor, v_preset, true);

  IF v_preset.updated_at IS DISTINCT FROM _expected_preset_updated_at THEN
    RETURN public.pmg_build_result('conflict', 'add_project_people_preset_member',
      'project_people_preset_member', NULL, NULL, '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb,
      jsonb_build_object('server_updated_at', v_preset.updated_at));
  END IF;

  IF _member_kind NOT IN ('team_member','stakeholder') THEN
    RETURN public.pmg_build_result('invalid', 'add_project_people_preset_member',
      'project_people_preset_member', NULL, NULL,
      jsonb_build_object('reason','invalid_member_kind'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL);
  END IF;

  v_role_norm      := NULLIF(btrim(COALESCE(_role_label, '')), '');
  v_canonical_norm := NULLIF(btrim(COALESCE(_canonical_role_key, '')), '');
  v_external_norm  := NULLIF(btrim(COALESCE(_external_name, '')), '');

  IF _member_kind = 'stakeholder' AND _stakeholder_type = 'external' THEN
    IF v_external_norm IS NULL THEN
      RETURN public.pmg_build_result('invalid', 'add_project_people_preset_member',
        'project_people_preset_member', NULL, NULL,
        jsonb_build_object('reason','external_name_required'),
        '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL);
    END IF;
    -- decrypt-compare within preset for case-insensitive duplicate external name
    FOR r IN
      SELECT id, external_name FROM public.project_people_preset_members
       WHERE preset_id = _preset_id
         AND member_kind = 'stakeholder' AND stakeholder_type = 'external'
       FOR UPDATE
    LOOP
      IF lower(btrim(public.btpm_decrypt(r.external_name, v_preset.organization_id))) = lower(v_external_norm) THEN
        v_dupe_external := r.id; EXIT;
      END IF;
    END LOOP;
    IF v_dupe_external IS NOT NULL THEN
      RETURN public.pmg_build_result('no_change', 'add_project_people_preset_member',
        'project_people_preset_member', v_dupe_external, NULL,
        jsonb_build_object('id', v_dupe_external, 'reason','duplicate_external_name'),
        '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL);
    END IF;
  END IF;

  BEGIN
    INSERT INTO public.project_people_preset_members (
      preset_id, member_kind, stakeholder_type,
      user_id, external_name, canonical_role_key, role_label
    ) VALUES (
      _preset_id, _member_kind,
      CASE WHEN _member_kind = 'stakeholder' THEN _stakeholder_type ELSE NULL END,
      CASE WHEN _member_kind = 'team_member' OR (_member_kind='stakeholder' AND _stakeholder_type='workspace_member') THEN _user_id ELSE NULL END,
      CASE WHEN _member_kind = 'stakeholder' AND _stakeholder_type = 'external' THEN v_external_norm ELSE NULL END,
      CASE WHEN _member_kind = 'team_member' THEN v_canonical_norm ELSE NULL END,
      v_role_norm
    )
    RETURNING id INTO v_new_id;
  EXCEPTION
    WHEN unique_violation THEN
      RETURN public.pmg_build_result('no_change', 'add_project_people_preset_member',
        'project_people_preset_member', NULL, NULL,
        jsonb_build_object('reason','already_member'),
        '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL);
    WHEN check_violation OR not_null_violation OR foreign_key_violation OR invalid_text_representation OR raise_exception THEN
      RETURN public.pmg_build_result('invalid', 'add_project_people_preset_member',
        'project_people_preset_member', NULL, NULL,
        jsonb_build_object('reason', SQLERRM),
        '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL);
  END;

  -- Touch parent updated_at so library views refresh
  UPDATE public.project_people_presets SET updated_at = now() WHERE id = _preset_id;

  PERFORM public._ppp_record_audit('applied', 'add_project_people_preset_member',
    v_preset, 'project_people_preset_member', v_new_id, _correlation_id, _idempotency_key,
    jsonb_build_object('member_kind', _member_kind, 'stakeholder_type', _stakeholder_type));

  RETURN public.pmg_build_result('applied', 'add_project_people_preset_member',
    'project_people_preset_member', v_new_id, NULL,
    jsonb_build_object('id', v_new_id, 'preset_id', _preset_id),
    '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL);
END; $function$

CREATE OR REPLACE FUNCTION public.add_project_stakeholder(_project_id uuid, _stakeholder_type text, _user_id uuid, _external_name text, _role_label text, _notes text, _start_date date DEFAULT NULL::date)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_actor uuid := auth.uid(); v_org uuid; v_ws uuid; v_new_id uuid; v_display text;
  v_role_label text := NULLIF(btrim(COALESCE(_role_label, '')), '');
  v_notes text := NULLIF(btrim(COALESCE(_notes, '')), '');
BEGIN
  IF v_actor IS NULL OR NOT public.is_active_user(v_actor) THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  SELECT organization_id, workspace_id INTO v_org, v_ws FROM public.projects WHERE id = _project_id;
  IF v_org IS NULL THEN RAISE EXCEPTION 'Project not found'; END IF;
  IF NOT public.has_project_pm_authority(v_actor, _project_id) THEN
    RAISE EXCEPTION 'Not authorized to manage stakeholders'; END IF;
  IF _stakeholder_type = 'workspace_member' THEN
    IF _user_id IS NULL THEN RAISE EXCEPTION 'user_id required for workspace_member'; END IF;
    IF NOT public.is_workspace_member(_user_id, v_ws) THEN
      RAISE EXCEPTION 'Selected user is not a workspace member'; END IF;
    IF EXISTS (SELECT 1 FROM public.project_stakeholders WHERE project_id = _project_id
      AND stakeholder_type='workspace_member' AND user_id=_user_id AND removed_at IS NULL) THEN
      RAISE EXCEPTION 'This member is already an active stakeholder'; END IF;
    SELECT COALESCE(display_name, email, _user_id::text) INTO v_display FROM public.profiles WHERE id=_user_id;
  ELSIF _stakeholder_type = 'external' THEN
    IF _external_name IS NULL OR length(btrim(_external_name)) = 0 THEN
      RAISE EXCEPTION 'external_name required for external stakeholder'; END IF;
    v_display := btrim(_external_name);
  ELSE RAISE EXCEPTION 'Invalid stakeholder_type'; END IF;
  INSERT INTO public.project_stakeholders (organization_id, workspace_id, project_id, stakeholder_type,
    user_id, external_name, role_label, notes, start_date, created_by)
  VALUES (v_org, v_ws, _project_id, _stakeholder_type,
    CASE WHEN _stakeholder_type='workspace_member' THEN _user_id ELSE NULL END,
    CASE WHEN _stakeholder_type='external' THEN btrim(_external_name) ELSE NULL END,
    v_role_label, v_notes, _start_date, v_actor) RETURNING id INTO v_new_id;
  PERFORM public.log_activity_event(v_org, v_actor, 'stakeholder_added', 'project', _project_id,
    jsonb_build_object('stakeholder_id', v_new_id, 'stakeholder_type', _stakeholder_type,
      'display_name', v_display, 'role_label', v_role_label, 'start_date', _start_date), v_ws);
  RETURN v_new_id;
END; $function$

CREATE OR REPLACE FUNCTION public.add_roadmap_story_pack_external_file(_story_pack_id uuid, _drive_id text, _item_id text, _display_name text DEFAULT NULL::text, _web_url text DEFAULT NULL::text, _user_note text DEFAULT NULL::text, _mime_type text DEFAULT NULL::text, _size_bytes bigint DEFAULT NULL::bigint, _include_in_story boolean DEFAULT true, _provider text DEFAULT 'sharepoint'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _org_id uuid;
  _new_id uuid;
BEGIN
  IF _uid IS NULL OR NOT public.is_active_user(_uid) THEN
    RAISE EXCEPTION 'unauthorized' USING ERRCODE = '42501';
  END IF;
  IF NOT public.is_story_pack_owner(_uid, _story_pack_id) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  PERFORM public.assert_roadmap_story_pack_editable(_story_pack_id);
  IF _provider IS NULL OR _provider <> 'sharepoint' THEN
    RAISE EXCEPTION 'unsupported provider' USING ERRCODE = '22023';
  END IF;

  SELECT organization_id INTO _org_id FROM public.roadmap_story_packs WHERE id = _story_pack_id;

  INSERT INTO public.roadmap_story_pack_external_files (
    story_pack_id, provider, drive_id, item_id,
    display_name_encrypted, web_url_encrypted, user_note_encrypted,
    mime_type, size_bytes, include_in_story, created_by
  ) VALUES (
    _story_pack_id, _provider, _drive_id, _item_id,
    CASE WHEN _display_name IS NULL OR _display_name = '' THEN NULL ELSE public.btpm_encrypt(_display_name, _org_id) END,
    CASE WHEN _web_url      IS NULL OR _web_url      = '' THEN NULL ELSE public.btpm_encrypt(_web_url,      _org_id) END,
    CASE WHEN _user_note    IS NULL OR _user_note    = '' THEN NULL ELSE public.btpm_encrypt(_user_note,    _org_id) END,
    _mime_type, _size_bytes, COALESCE(_include_in_story, true), _uid
  ) RETURNING id INTO _new_id;

  RETURN _new_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.add_roadmap_story_pack_note(_story_pack_id uuid, _body text, _label text DEFAULT NULL::text, _include_in_story boolean DEFAULT true, _sort_order integer DEFAULT NULL::integer)
 RETURNS uuid
 LANGUAGE plpgsql
