CREATE OR REPLACE FUNCTION public.adjust_governance_cadence_next_expected_date(_cadence_id uuid, _next_expected_date date)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE _row governance_cadences%ROWTYPE; _old date;
BEGIN
  SELECT * INTO _row FROM governance_cadences WHERE id = _cadence_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Cadence not found' USING ERRCODE='P0002'; END IF;
  PERFORM _gov_assert_project_write(_row.project_id);
  IF _row.archived_at IS NOT NULL THEN
    RAISE EXCEPTION 'Cannot adjust archived cadence' USING ERRCODE='42501';
  END IF;
  IF _row.frequency_type <> 'ad_hoc' AND _next_expected_date IS NULL THEN
    RAISE EXCEPTION 'Non-ad-hoc cadence requires a next expected date' USING ERRCODE='22023';
  END IF;
  _old := _row.next_expected_date;
  UPDATE governance_cadences
    SET next_expected_date = _next_expected_date,
        updated_at = now(),
        updated_by = auth.uid()
    WHERE id = _cadence_id;
  PERFORM log_activity_event(_row.organization_id, auth.uid(),
    'governance_cadence_next_expected_date_adjusted', 'governance_cadence', _cadence_id,
    jsonb_build_object('project_id', _row.project_id,
                       'cadence_id', _cadence_id,
                       'old_next_expected_date', _old,
                       'new_next_expected_date', _next_expected_date,
                       'event_type', _row.event_type,
                       'frequency_type', _row.frequency_type),
    _row.workspace_id);
END; $function$

CREATE OR REPLACE FUNCTION public.admin_add_portfolio_team_member(_portfolio_item_id uuid, _user_id uuid, _role text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _org uuid;
  _user_org uuid;
  _user_active boolean;
  _existing_id uuid;
  _existing_active boolean;
BEGIN
  IF _uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF NOT public.is_active_user(_uid) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;

  SELECT organization_id INTO _org FROM public.portfolio_items WHERE id = _portfolio_item_id;
  IF _org IS NULL THEN RAISE EXCEPTION 'Portfolio item not found'; END IF;
  IF NOT public.is_org_admin(_uid, _org) THEN RAISE EXCEPTION 'Not authorized'; END IF;

  IF _role NOT IN (
    'product_manager','commercial_lead','finance_partner','supply_lead',
    'regulatory_lead','quality_lead','tech_services_lead','launch_lead',
    'bd_lead','srm_lead','other'
  ) THEN RAISE EXCEPTION 'Invalid role'; END IF;

  SELECT organization_id, is_active INTO _user_org, _user_active FROM public.profiles WHERE id = _user_id;
  IF _user_org IS NULL THEN RAISE EXCEPTION 'User not found'; END IF;
  IF _user_org IS DISTINCT FROM _org THEN RAISE EXCEPTION 'User must belong to the same organization'; END IF;
  IF NOT COALESCE(_user_active, false) THEN RAISE EXCEPTION 'User is deactivated'; END IF;

  -- Look for existing row (active or inactive) for same portfolio+user+role
  SELECT id, is_active INTO _existing_id, _existing_active
    FROM public.portfolio_item_team_members
   WHERE portfolio_item_id = _portfolio_item_id
     AND user_id = _user_id
     AND role = _role
   ORDER BY is_active DESC, updated_at DESC
   LIMIT 1;

  IF _existing_id IS NOT NULL THEN
    IF _existing_active THEN
      -- No-op: already active
      RETURN _existing_id;
    ELSE
      UPDATE public.portfolio_item_team_members
         SET is_active = true, updated_by = _uid
       WHERE id = _existing_id;

      PERFORM public.log_activity_event(
        _org, _uid, 'portfolio_team_member_added', 'portfolio', _portfolio_item_id,
        jsonb_build_object('user_id', _user_id, 'role', _role, 'reactivated', true),
        NULL::uuid
      );
      RETURN _existing_id;
    END IF;
  END IF;

  INSERT INTO public.portfolio_item_team_members (
    portfolio_item_id, organization_id, user_id, role, created_by, updated_by
  ) VALUES (
    _portfolio_item_id, _org, _user_id, _role, _uid, _uid
  ) RETURNING id INTO _existing_id;

  PERFORM public.log_activity_event(
    _org, _uid, 'portfolio_team_member_added', 'portfolio', _portfolio_item_id,
    jsonb_build_object('user_id', _user_id, 'role', _role),
    NULL::uuid
  );

  RETURN _existing_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_add_workspace_access(_organization_id uuid, _target_user_id uuid, _workspace_id uuid, _role app_role)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE _ws_name text;
BEGIN
  IF NOT public.is_active_user(auth.uid()) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;
  IF NOT public.is_org_admin(auth.uid(), _organization_id) THEN RAISE EXCEPTION 'Access denied'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = _target_user_id AND organization_id = _organization_id) THEN
    RAISE EXCEPTION 'User not found';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.workspaces WHERE id = _workspace_id AND organization_id = _organization_id) THEN
    RAISE EXCEPTION 'Workspace not found';
  END IF;
  IF _role IN ('org_admin') THEN RAISE EXCEPTION 'Cannot assign org_admin as workspace role'; END IF;

  -- Ensure tenant + organization membership layers exist first.
  PERFORM public._ensure_membership_layers(_target_user_id, _organization_id, auth.uid());

  INSERT INTO public.workspace_memberships (workspace_id, user_id)
    VALUES (_workspace_id, _target_user_id)
    ON CONFLICT (workspace_id, user_id) DO NOTHING;
  DELETE FROM public.user_roles
    WHERE user_id = _target_user_id AND workspace_id = _workspace_id AND organization_id = _organization_id;
  INSERT INTO public.user_roles (user_id, role, organization_id, workspace_id)
    VALUES (_target_user_id, _role, _organization_id, _workspace_id);

  -- Conservative context seed for single-org users only.
  PERFORM public._seed_single_org_preference(_target_user_id);

  SELECT name INTO _ws_name FROM public.workspaces WHERE id = _workspace_id;
  PERFORM public.log_activity_event(_organization_id, auth.uid(), 'workspace_access_added',
    'user', _target_user_id,
    jsonb_build_object('workspace_id', _workspace_id, 'workspace_name', _ws_name, 'role', _role::text),
    _workspace_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_archive_portfolio_item(_portfolio_item_id uuid, _is_archived boolean DEFAULT true)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _org uuid;
BEGIN
  IF _uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF NOT public.is_active_user(_uid) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;

  SELECT organization_id INTO _org FROM public.portfolio_items WHERE id = _portfolio_item_id;
  IF _org IS NULL THEN RAISE EXCEPTION 'Portfolio item not found'; END IF;

  IF NOT public.is_org_admin(_uid, _org) THEN RAISE EXCEPTION 'Not authorized'; END IF;

  UPDATE public.portfolio_items
     SET is_archived = _is_archived,
         archived_at = CASE WHEN _is_archived THEN now() ELSE NULL END,
         updated_by = _uid
   WHERE id = _portfolio_item_id;

  PERFORM public.log_activity_event(
    _org, _uid,
    CASE WHEN _is_archived THEN 'portfolio_archived' ELSE 'portfolio_unarchived' END,
    'portfolio', _portfolio_item_id, NULL::jsonb, NULL::uuid
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_assign_projects_to_portfolio(_portfolio_item_id uuid, _project_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _org uuid;
  _archived boolean;
  _assigned int := 0;
  _reassigned int := 0;
  _skipped int := 0;
  _affected uuid[] := ARRAY[]::uuid[];
  _rec record;
BEGIN
  IF _uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF NOT public.is_active_user(_uid) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;
  IF _project_ids IS NULL OR array_length(_project_ids, 1) IS NULL THEN
    RAISE EXCEPTION 'At least one project must be selected';
  END IF;

  SELECT organization_id, is_archived INTO _org, _archived
    FROM public.portfolio_items WHERE id = _portfolio_item_id;
  IF _org IS NULL THEN RAISE EXCEPTION 'Portfolio item not found'; END IF;
  IF _archived THEN RAISE EXCEPTION 'Portfolio item is archived and cannot receive new assignments'; END IF;
  IF NOT public.is_org_admin(_uid, _org) THEN RAISE EXCEPTION 'Not authorized'; END IF;

  FOR _rec IN
    SELECT p.id, p.organization_id, p.workspace_id, p.portfolio_item_id AS current_pi
      FROM public.projects p
     WHERE p.id = ANY(_project_ids)
  LOOP
    IF _rec.organization_id <> _org THEN
      RAISE EXCEPTION 'Project % belongs to a different organization', _rec.id;
    END IF;

    IF _rec.current_pi IS NOT DISTINCT FROM _portfolio_item_id THEN
      _skipped := _skipped + 1;
      CONTINUE;
    END IF;

    UPDATE public.projects
       SET portfolio_item_id = _portfolio_item_id,
           updated_at = now()
     WHERE id = _rec.id;

    IF _rec.current_pi IS NULL THEN
      _assigned := _assigned + 1;
    ELSE
      _reassigned := _reassigned + 1;
    END IF;
    _affected := _affected || _rec.id;

    PERFORM public.log_activity_event(
      _org, _uid, 'project_portfolio_changed', 'project', _rec.id,
      jsonb_build_object(
        'old_portfolio_item_id', _rec.current_pi,
        'new_portfolio_item_id', _portfolio_item_id,
        'source', 'admin_portfolio_manage'
      ),
      _rec.workspace_id
    );
  END LOOP;

  RETURN jsonb_build_object(
    'assigned_count', _assigned,
    'reassigned_count', _reassigned,
    'skipped_count', _skipped,
    'affected_project_ids', to_jsonb(_affected)
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_change_workspace_role(_organization_id uuid, _target_user_id uuid, _workspace_id uuid, _new_role app_role)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE _ws_name text; _old_role text;
BEGIN
  IF NOT public.is_active_user(auth.uid()) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;
  IF NOT public.is_org_admin(auth.uid(), _organization_id) THEN RAISE EXCEPTION 'Access denied'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.workspace_memberships WHERE user_id = _target_user_id AND workspace_id = _workspace_id) THEN RAISE EXCEPTION 'User is not a member'; END IF;
  IF _new_role IN ('org_admin') THEN RAISE EXCEPTION 'Cannot assign org_admin as workspace role'; END IF;
  SELECT ur.role::text INTO _old_role FROM public.user_roles ur WHERE ur.user_id = _target_user_id AND ur.workspace_id = _workspace_id AND ur.organization_id = _organization_id LIMIT 1;
  DELETE FROM public.user_roles WHERE user_id = _target_user_id AND workspace_id = _workspace_id AND organization_id = _organization_id;
  INSERT INTO public.user_roles (user_id, role, organization_id, workspace_id) VALUES (_target_user_id, _new_role, _organization_id, _workspace_id);
  SELECT name INTO _ws_name FROM public.workspaces WHERE id = _workspace_id;
  PERFORM public.log_activity_event(_organization_id, auth.uid(), 'workspace_role_changed', 'user', _target_user_id, jsonb_build_object('workspace_id', _workspace_id, 'workspace_name', _ws_name, 'old_role', _old_role, 'new_role', _new_role::text), _workspace_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_create_invitation(_organization_id uuid, _email text, _workspace_id uuid, _role app_role)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE _caller_id uuid; _inv_id uuid; _ws_name text; _raw_token uuid; _token_hash text; _tenant uuid;
BEGIN
  _caller_id := auth.uid(); IF _caller_id IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF NOT public.is_active_user(_caller_id) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;
  IF NOT public.is_org_admin(_caller_id, _organization_id) THEN RAISE EXCEPTION 'Access denied'; END IF;
  SELECT tenant_id INTO _tenant FROM public.organizations WHERE id = _organization_id;
  IF _tenant IS NULL THEN RAISE EXCEPTION 'Organization tenant not resolvable'; END IF;
  IF _workspace_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.workspaces WHERE id = _workspace_id AND organization_id = _organization_id) THEN RAISE EXCEPTION 'Workspace not found'; END IF;
  IF _role = 'org_admin' AND _workspace_id IS NOT NULL THEN RAISE EXCEPTION 'Cannot assign org_admin as workspace role'; END IF;
  IF EXISTS (SELECT 1 FROM public.invitations WHERE organization_id = _organization_id AND lower(email) = lower(_email) AND status='pending' AND expires_at > now()) THEN RAISE EXCEPTION 'A pending invitation already exists for this email'; END IF;
  IF EXISTS (SELECT 1 FROM public.profiles WHERE organization_id = _organization_id AND lower(email) = lower(_email)) THEN RAISE EXCEPTION 'This email already belongs to an accepted user'; END IF;
  _raw_token := gen_random_uuid(); _token_hash := encode(digest(_raw_token::text, 'sha256'), 'hex');
  INSERT INTO public.invitations (email, organization_id, workspace_id, role, invited_by, status, token, tenant_id, organization_role)
  VALUES (lower(_email), _organization_id, _workspace_id, _role, _caller_id, 'pending', _token_hash, _tenant,
          CASE WHEN _role = 'org_admin' THEN 'org_admin'::public.organization_role ELSE 'org_member'::public.organization_role END)
  RETURNING id INTO _inv_id;
  IF _workspace_id IS NOT NULL THEN SELECT name INTO _ws_name FROM public.workspaces WHERE id = _workspace_id; END IF;
  PERFORM public.log_activity_event(_organization_id, _caller_id, 'invitation_created', 'invitation', _inv_id, jsonb_build_object('email', lower(_email), 'role', _role::text, 'workspace_id', _workspace_id, 'workspace_name', _ws_name, 'tenant_id', _tenant), _workspace_id);
  RETURN _inv_id;
END $function$

CREATE OR REPLACE FUNCTION public.admin_create_portfolio_item(_organization_id uuid, _name text, _code text DEFAULT NULL::text, _description text DEFAULT NULL::text, _lifecycle_state text DEFAULT 'opportunity_candidate'::text, _owner_id uuid DEFAULT NULL::uuid, _strategic_priority text DEFAULT 'medium'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _new_id uuid;
  _name_trim text;
  _owner_org uuid;
BEGIN
  IF _uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF NOT public.is_active_user(_uid) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;
  IF NOT public.is_org_admin(_uid, _organization_id) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  _name_trim := btrim(COALESCE(_name, ''));
  IF _name_trim = '' THEN RAISE EXCEPTION 'Name is required'; END IF;
  IF char_length(_name_trim) > 200 THEN RAISE EXCEPTION 'Name exceeds 200 characters'; END IF;
  IF _code IS NOT NULL AND char_length(_code) > 80 THEN RAISE EXCEPTION 'Code exceeds 80 characters'; END IF;
  IF _description IS NOT NULL AND char_length(_description) > 4000 THEN RAISE EXCEPTION 'Description exceeds 4000 characters'; END IF;
  IF _lifecycle_state NOT IN (
    'opportunity_candidate','business_case_approved','contracted','development',
    'submission_approval','launch_preparation','launched_commercial',
    'lcm_optimization','on_hold','discontinuation','retired'
  ) THEN RAISE EXCEPTION 'Invalid lifecycle_state'; END IF;
  IF _strategic_priority NOT IN ('critical','high','medium','low','watchlist') THEN
    RAISE EXCEPTION 'Invalid strategic_priority';
  END IF;
  IF _owner_id IS NOT NULL THEN
    SELECT organization_id INTO _owner_org FROM public.profiles WHERE id = _owner_id;
    IF _owner_org IS DISTINCT FROM _organization_id THEN
      RAISE EXCEPTION 'Owner must belong to the same organization';
    END IF;
  END IF;

  INSERT INTO public.portfolio_items (
    organization_id, name, code, description, lifecycle_state, strategic_priority, owner_id, created_by, updated_by
  ) VALUES (
    _organization_id, _name_trim, _code, _description, _lifecycle_state, _strategic_priority, _owner_id, _uid, _uid
  ) RETURNING id INTO _new_id;

  PERFORM public.log_activity_event(
    _organization_id, _uid, 'portfolio_created', 'portfolio', _new_id, NULL::jsonb, NULL::uuid
  );

  RETURN _new_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_deactivate_user(_organization_id uuid, _target_user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
  IF NOT public.is_active_user(auth.uid()) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;
  IF NOT public.is_org_admin(auth.uid(), _organization_id) THEN RAISE EXCEPTION 'Access denied'; END IF;
  IF _target_user_id = auth.uid() THEN RAISE EXCEPTION 'Cannot deactivate yourself'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = _target_user_id AND organization_id = _organization_id) THEN RAISE EXCEPTION 'User not found'; END IF;
  UPDATE public.profiles SET is_active = false, updated_at = now() WHERE id = _target_user_id AND organization_id = _organization_id;
  PERFORM public.log_activity_event(_organization_id, auth.uid(), 'user_deactivated', 'user', _target_user_id, '{}'::jsonb, NULL);
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_delete_invitation(_organization_id uuid, _invitation_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE _email text; _ws_id uuid;
BEGIN
  IF NOT public.is_active_user(auth.uid()) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;
  IF NOT public.is_org_admin(auth.uid(), _organization_id) THEN RAISE EXCEPTION 'Access denied'; END IF;
  SELECT email, workspace_id INTO _email, _ws_id FROM public.invitations WHERE id = _invitation_id AND organization_id = _organization_id AND status IN ('pending','revoked','expired','declined');
  DELETE FROM public.invitations WHERE id = _invitation_id AND organization_id = _organization_id AND status IN ('pending','revoked','expired','declined');
  IF NOT FOUND THEN RAISE EXCEPTION 'Invitation not found or cannot be deleted'; END IF;
  PERFORM public.log_activity_event(_organization_id, auth.uid(), 'invitation_deleted', 'invitation', _invitation_id, jsonb_build_object('email', _email), _ws_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_delete_user(_organization_id uuid, _target_user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE _target_email text;
BEGIN
  IF NOT public.is_active_user(auth.uid()) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;
  IF NOT public.is_org_admin(auth.uid(), _organization_id) THEN RAISE EXCEPTION 'Access denied'; END IF;
  IF _target_user_id = auth.uid() THEN RAISE EXCEPTION 'Cannot delete yourself'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = _target_user_id AND organization_id = _organization_id) THEN RAISE EXCEPTION 'User not found'; END IF;
  IF EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = _target_user_id AND organization_id = _organization_id AND role = 'org_admin' AND workspace_id IS NULL) THEN
    IF (SELECT count(*) FROM public.user_roles WHERE organization_id = _organization_id AND role = 'org_admin' AND workspace_id IS NULL) <= 1 THEN RAISE EXCEPTION 'Cannot delete the last org admin'; END IF;
  END IF;
  IF EXISTS (SELECT ur.workspace_id FROM public.user_roles ur WHERE ur.user_id = _target_user_id AND ur.organization_id = _organization_id AND ur.role = 'workspace_admin' AND ur.workspace_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.user_roles ur2 WHERE ur2.workspace_id = ur.workspace_id AND ur2.role = 'workspace_admin' AND ur2.user_id != _target_user_id)) THEN RAISE EXCEPTION 'Cannot delete: last workspace admin. Reassign first.'; END IF;
  SELECT email INTO _target_email FROM public.profiles WHERE id = _target_user_id;
  PERFORM public.log_activity_event(_organization_id, auth.uid(), 'user_deleted', 'user', _target_user_id, jsonb_build_object('email', _target_email), NULL);
  UPDATE public.comments SET author_id = '00000000-0000-0000-0000-000000000000' WHERE author_id = _target_user_id AND organization_id = _organization_id;
  UPDATE public.execution_updates SET author_id = '00000000-0000-0000-0000-000000000000' WHERE author_id = _target_user_id AND organization_id = _organization_id;
  UPDATE public.activity_events SET actor_id = NULL WHERE actor_id = _target_user_id AND organization_id = _organization_id;
  UPDATE public.blockers SET reported_by = NULL WHERE reported_by = _target_user_id AND organization_id = _organization_id;
  UPDATE public.blockers SET resolved_by = NULL WHERE resolved_by = _target_user_id AND organization_id = _organization_id;
  UPDATE public.risks SET reported_by = NULL WHERE reported_by = _target_user_id AND organization_id = _organization_id;
  UPDATE public.tasks SET owner_id = NULL WHERE owner_id = _target_user_id AND organization_id = _organization_id;
  UPDATE public.tasks SET created_by = NULL WHERE created_by = _target_user_id AND organization_id = _organization_id;
  UPDATE public.phases SET created_by = NULL WHERE created_by = _target_user_id AND organization_id = _organization_id;
  UPDATE public.projects SET created_by = NULL WHERE created_by = _target_user_id AND organization_id = _organization_id;
  UPDATE public.programs SET created_by = NULL WHERE created_by = _target_user_id AND organization_id = _organization_id;
  UPDATE public.kpi_definitions SET created_by = NULL WHERE created_by = _target_user_id AND organization_id = _organization_id;
  DELETE FROM public.task_assignments WHERE assignee_id = _target_user_id AND organization_id = _organization_id;
  DELETE FROM public.task_assignments WHERE assigned_by = _target_user_id AND organization_id = _organization_id;
  DELETE FROM public.raci_assignments WHERE user_id = _target_user_id AND organization_id = _organization_id;
  DELETE FROM public.project_team_members WHERE user_id = _target_user_id AND organization_id = _organization_id;
  DELETE FROM public.kpi_updates WHERE author_id = _target_user_id AND organization_id = _organization_id;
  DELETE FROM public.user_roles WHERE user_id = _target_user_id AND organization_id = _organization_id;
  DELETE FROM public.workspace_memberships wm USING public.workspaces w WHERE wm.workspace_id = w.id AND w.organization_id = _organization_id AND wm.user_id = _target_user_id;
  UPDATE public.invitations SET invited_by = auth.uid() WHERE invited_by = _target_user_id AND organization_id = _organization_id;
  DELETE FROM public.profiles WHERE id = _target_user_id AND organization_id = _organization_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_list_org_workspaces(_organization_id uuid)
 RETURNS json
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _result json;
BEGIN
  IF _uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF NOT public.is_active_user(_uid) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;

  -- Caller must be an org admin of the target organization
  IF NOT EXISTS (
    SELECT 1 FROM public.user_roles
    WHERE user_id = _uid
      AND organization_id = _organization_id
      AND role = 'org_admin'
  ) THEN
    RAISE EXCEPTION 'Insufficient privileges';
  END IF;

  SELECT json_agg(row_to_json(t)) INTO _result
  FROM (
    SELECT
      w.id,
      public.btpm_decrypt(w.name, _organization_id) AS name,
      w.organization_id,
      w.is_archived
    FROM public.workspaces w
    WHERE w.organization_id = _organization_id
      AND w.is_archived = false
    ORDER BY public.btpm_decrypt(w.name, _organization_id)
  ) t;

  RETURN COALESCE(_result, '[]'::json);
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_list_portfolio_team_members(_portfolio_item_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _org uuid;
  _result jsonb;
BEGIN
  IF _uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF NOT public.is_active_user(_uid) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;

  SELECT organization_id INTO _org FROM public.portfolio_items WHERE id = _portfolio_item_id;
  IF _org IS NULL THEN RAISE EXCEPTION 'Portfolio item not found'; END IF;
  IF NOT public.is_org_admin(_uid, _org) THEN RAISE EXCEPTION 'Not authorized'; END IF;

  SELECT COALESCE(jsonb_agg(row_to_json(t) ORDER BY t.display_name NULLS LAST, t.email), '[]'::jsonb)
    INTO _result
  FROM (
    SELECT
      tm.id AS team_member_id,
      tm.portfolio_item_id,
      tm.organization_id,
      tm.user_id,
      tm.role,
      CASE WHEN p.organization_id IS NOT NULL
           THEN public.btpm_decrypt(p.display_name, p.organization_id)
           ELSE p.display_name END AS display_name,
      p.email,
      tm.is_active,
      tm.created_at,
      tm.updated_at
    FROM public.portfolio_item_team_members tm
    JOIN public.profiles p ON p.id = tm.user_id
    WHERE tm.portfolio_item_id = _portfolio_item_id
      AND tm.is_active = true
  ) t;

  RETURN _result;
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_move_project_workspace(_organization_id uuid, _project_id uuid, _target_workspace_id uuid, _target_program_id uuid DEFAULT NULL::uuid, _confirm_program_clear boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_project public.projects%ROWTYPE;
  v_src_ws public.workspaces%ROWTYPE;
  v_tgt_ws public.workspaces%ROWTYPE;
  v_tgt_pg public.programs%ROWTYPE;
  v_phases uuid[];
  v_tasks uuid[];
  v_kpis uuid[];
  v_prev_program uuid;
  v_program_clear boolean;
  v_access_removed int := 0;
  v_updated jsonb := '{}'::jsonb;
  v_dup boolean;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF NOT public.is_org_admin(v_uid, _organization_id) THEN
    RAISE EXCEPTION 'Not authorized: org admin required';
  END IF;

  SELECT * INTO v_project FROM public.projects WHERE id = _project_id FOR UPDATE;
  IF NOT FOUND OR v_project.organization_id <> _organization_id THEN
    RAISE EXCEPTION 'Project not found in organization';
  END IF;
  IF v_project.is_archived THEN RAISE EXCEPTION 'Project is archived'; END IF;

  SELECT * INTO v_src_ws FROM public.workspaces WHERE id = v_project.workspace_id;
  SELECT * INTO v_tgt_ws FROM public.workspaces WHERE id = _target_workspace_id;
  IF NOT FOUND OR v_tgt_ws.organization_id <> _organization_id THEN
    RAISE EXCEPTION 'Target workspace not in organization';
  END IF;
  IF v_src_ws.id = v_tgt_ws.id THEN RAISE EXCEPTION 'Source and target workspaces are the same'; END IF;
  IF v_src_ws.is_archived OR v_src_ws.is_active = false THEN RAISE EXCEPTION 'Source workspace inactive'; END IF;
  IF v_tgt_ws.is_archived OR v_tgt_ws.is_active = false THEN RAISE EXCEPTION 'Target workspace inactive'; END IF;

  IF _target_program_id IS NOT NULL THEN
    SELECT * INTO v_tgt_pg FROM public.programs WHERE id = _target_program_id;
    IF NOT FOUND
       OR v_tgt_pg.organization_id <> _organization_id
       OR v_tgt_pg.workspace_id <> _target_workspace_id
       OR v_tgt_pg.is_archived THEN
      RAISE EXCEPTION 'Invalid target program';
    END IF;
  END IF;

  v_prev_program := v_project.program_id;
  v_program_clear := (v_prev_program IS NOT NULL AND _target_program_id IS NULL);
  IF v_program_clear AND NOT _confirm_program_clear THEN
    RAISE EXCEPTION 'Program clear not confirmed';
  END IF;

  -- Duplicate name guard
  SELECT EXISTS (
    SELECT 1 FROM public.projects
    WHERE workspace_id = _target_workspace_id
      AND id <> _project_id
      AND is_archived = false
      AND lower(name) = lower(v_project.name)
  ) INTO v_dup;
  IF v_dup THEN RAISE EXCEPTION 'Duplicate project name in target workspace'; END IF;

  SELECT COALESCE(array_agg(id), ARRAY[]::uuid[]) INTO v_phases FROM public.phases WHERE project_id = _project_id;
  SELECT COALESCE(array_agg(id), ARRAY[]::uuid[]) INTO v_tasks FROM public.tasks WHERE project_id = _project_id;
  SELECT COALESCE(array_agg(id), ARRAY[]::uuid[]) INTO v_kpis FROM public.kpi_definitions
    WHERE (target_type='project' AND target_id=_project_id)
       OR (target_type='phase'   AND target_id = ANY(v_phases))
       OR (target_type='task'    AND target_id = ANY(v_tasks));

  -- 1. Update project itself
  UPDATE public.projects
     SET workspace_id = _target_workspace_id,
         program_id   = _target_program_id,
         updated_at   = now()
   WHERE id = _project_id;

  -- 2. Move Set A (direct project-scoped tables)
  UPDATE public.phases                         SET workspace_id = _target_workspace_id WHERE project_id=_project_id;
  UPDATE public.tasks                          SET workspace_id = _target_workspace_id WHERE project_id=_project_id;
  UPDATE public.backlog_items                  SET workspace_id = _target_workspace_id WHERE project_id=_project_id;
  UPDATE public.sprints                        SET workspace_id = _target_workspace_id WHERE project_id=_project_id;
  UPDATE public.board_workflow_states          SET workspace_id = _target_workspace_id WHERE project_id=_project_id;
  UPDATE public.project_team_members           SET workspace_id = _target_workspace_id WHERE project_id=_project_id;
  UPDATE public.project_stakeholders           SET workspace_id = _target_workspace_id WHERE project_id=_project_id;
  UPDATE public.generated_operational_documents SET workspace_id = _target_workspace_id WHERE project_id=_project_id;
  UPDATE public.governance_cadences            SET workspace_id = _target_workspace_id WHERE project_id=_project_id;
  UPDATE public.governance_records             SET workspace_id = _target_workspace_id WHERE project_id=_project_id;
  UPDATE public.governance_record_decisions    SET workspace_id = _target_workspace_id WHERE project_id=_project_id;
  UPDATE public.governance_record_links        SET workspace_id = _target_workspace_id WHERE project_id=_project_id;
  UPDATE public.kpi_snapshots                  SET workspace_id = _target_workspace_id WHERE project_id=_project_id;
  UPDATE public.kpi_snapshot_capture_run_items SET workspace_id = _target_workspace_id WHERE project_id=_project_id;
  UPDATE public.kpi_app_mappings               SET workspace_id = _target_workspace_id WHERE project_id=_project_id;
  UPDATE public.kpi_app_submission_outbox      SET workspace_id = _target_workspace_id WHERE project_id=_project_id;
  UPDATE public.kpi_app_scheduler_run_items    SET workspace_id = _target_workspace_id WHERE project_id=_project_id;
  UPDATE public.powerbi_data_scope_rules       SET workspace_id = _target_workspace_id WHERE project_id=_project_id;
  UPDATE public.sharepoint_project_bindings    SET workspace_id = _target_workspace_id WHERE project_id=_project_id;

  -- 3. Move Set B (polymorphic target_type/target_id)
  UPDATE public.comments                 SET workspace_id = _target_workspace_id
    WHERE (target_type='project' AND target_id=_project_id)
       OR (target_type='phase'   AND target_id = ANY(v_phases))
       OR (target_type='task'    AND target_id = ANY(v_tasks));
  UPDATE public.execution_updates        SET workspace_id = _target_workspace_id
    WHERE (target_type='project' AND target_id=_project_id)
       OR (target_type='phase'   AND target_id = ANY(v_phases))
       OR (target_type='task'    AND target_id = ANY(v_tasks));
  UPDATE public.activity_events          SET workspace_id = _target_workspace_id
    WHERE (target_type='project' AND target_id=_project_id)
       OR (target_type='phase'   AND target_id = ANY(v_phases))
       OR (target_type='task'    AND target_id = ANY(v_tasks));
  UPDATE public.blockers                 SET workspace_id = _target_workspace_id
    WHERE (target_type='project' AND target_id=_project_id)
       OR (target_type='phase'   AND target_id = ANY(v_phases))
       OR (target_type='task'    AND target_id = ANY(v_tasks));
  UPDATE public.risks                    SET workspace_id = _target_workspace_id
    WHERE (target_type='project' AND target_id=_project_id)
       OR (target_type='phase'   AND target_id = ANY(v_phases))
       OR (target_type='task'    AND target_id = ANY(v_tasks));
  UPDATE public.dependencies             SET workspace_id = _target_workspace_id
    WHERE (target_type='project' AND target_id=_project_id)
       OR (target_type='phase'   AND target_id = ANY(v_phases))
       OR (target_type='task'    AND target_id = ANY(v_tasks));
  UPDATE public.kpi_definitions          SET workspace_id = _target_workspace_id
    WHERE id = ANY(v_kpis);
  UPDATE public.raci_assignments         SET workspace_id = _target_workspace_id
    WHERE (target_type='project' AND target_id=_project_id)
       OR (target_type='phase'   AND target_id = ANY(v_phases))
       OR (target_type='task'    AND target_id = ANY(v_tasks));
  UPDATE public.notification_outbox      SET workspace_id = _target_workspace_id
    WHERE (target_type='project' AND target_id=_project_id)
       OR (target_type='phase'   AND target_id = ANY(v_phases))
       OR (target_type='task'    AND target_id = ANY(v_tasks));
  UPDATE public.email_payload_snapshots  SET workspace_id = _target_workspace_id
    WHERE (target_type='project' AND target_id=_project_id)
       OR (target_type='phase'   AND target_id = ANY(v_phases))
       OR (target_type='task'    AND target_id = ANY(v_tasks));

  -- 4. Derived
  UPDATE public.kpi_updates      SET workspace_id = _target_workspace_id WHERE kpi_definition_id = ANY(v_kpis);
  UPDATE public.task_assignments SET workspace_id = _target_workspace_id WHERE task_id = ANY(v_tasks);
  UPDATE public.entity_object_links SET workspace_id = _target_workspace_id
    WHERE (owner_type IN ('project','phase','task')
           AND (owner_id=_project_id OR owner_id = ANY(v_phases) OR owner_id = ANY(v_tasks)))
       OR (referenced_type IN ('project','phase','task')
           AND (referenced_id=_project_id OR referenced_id = ANY(v_phases) OR referenced_id = ANY(v_tasks)));
  UPDATE public.entity_user_links SET workspace_id = _target_workspace_id
    WHERE owner_type IN ('project','phase','task')
      AND (owner_id=_project_id OR owner_id = ANY(v_phases) OR owner_id = ANY(v_tasks));

  -- 5. Soft-remove stale direct project memberships
  WITH removed AS (
    UPDATE public.project_memberships
       SET removed_at = now(), updated_at = now()
     WHERE project_id = _project_id
       AND removed_at IS NULL
       AND user_id NOT IN (SELECT user_id FROM public.workspace_memberships WHERE workspace_id = _target_workspace_id)
     RETURNING 1
  ) SELECT count(*) INTO v_access_removed FROM removed;

  v_updated := jsonb_build_object(
    'phases', array_length(v_phases,1),
    'tasks',  array_length(v_tasks,1),
    'kpi_definitions', array_length(v_kpis,1)
  );

  -- 6. Activity event for the move (IDs/counts only — no decrypted names)
  INSERT INTO public.activity_events (organization_id, workspace_id, event_type, target_type, target_id, actor_id, metadata)
  VALUES (_organization_id, _target_workspace_id, 'project_workspace_moved', 'project', _project_id, v_uid,
    jsonb_build_object(
      'source_workspace_id', v_src_ws.id,
      'target_workspace_id', v_tgt_ws.id,
      'previous_program_id', v_prev_program,
      'new_program_id', _target_program_id,
      'program_cleared', v_program_clear,
      'access_removed_count', v_access_removed,
      'updated_counts', v_updated
    )::text
  );

  RETURN jsonb_build_object(
    'moved_project_id', _project_id,
    'source_workspace_id', v_src_ws.id,
    'target_workspace_id', v_tgt_ws.id,
    'target_route', '/workspace/' || _target_workspace_id::text || '/project/' || _project_id::text,
    'previous_program_id', v_prev_program,
    'new_program_id', _target_program_id,
    'program_cleared', v_program_clear,
    'updated_counts', v_updated,
    'access_removed_count', v_access_removed
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_reactivate_user(_organization_id uuid, _target_user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
  IF NOT public.is_active_user(auth.uid()) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;
  IF NOT public.is_org_admin(auth.uid(), _organization_id) THEN RAISE EXCEPTION 'Access denied'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = _target_user_id AND organization_id = _organization_id) THEN RAISE EXCEPTION 'User not found'; END IF;
  UPDATE public.profiles SET is_active = true, updated_at = now() WHERE id = _target_user_id AND organization_id = _organization_id;
  PERFORM public.log_activity_event(_organization_id, auth.uid(), 'user_reactivated', 'user', _target_user_id, '{}'::jsonb, NULL);
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_remove_portfolio_team_member(_team_member_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _row public.portfolio_item_team_members%ROWTYPE;
BEGIN
  IF _uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF NOT public.is_active_user(_uid) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;

  SELECT * INTO _row FROM public.portfolio_item_team_members WHERE id = _team_member_id;
  IF _row.id IS NULL THEN RAISE EXCEPTION 'Team member not found'; END IF;
  IF NOT public.is_org_admin(_uid, _row.organization_id) THEN RAISE EXCEPTION 'Not authorized'; END IF;

  IF _row.is_active THEN
    UPDATE public.portfolio_item_team_members
       SET is_active = false, updated_by = _uid
     WHERE id = _team_member_id;

    PERFORM public.log_activity_event(
      _row.organization_id, _uid, 'portfolio_team_member_removed', 'portfolio', _row.portfolio_item_id,
      jsonb_build_object('user_id', _row.user_id, 'role', _row.role),
      NULL::uuid
    );
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_remove_projects_from_portfolio(_portfolio_item_id uuid, _project_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _org uuid;
  _removed int := 0;
  _skipped int := 0;
  _affected uuid[] := ARRAY[]::uuid[];
  _rec record;
BEGIN
  IF _uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF NOT public.is_active_user(_uid) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;
  IF _project_ids IS NULL OR array_length(_project_ids, 1) IS NULL THEN
    RAISE EXCEPTION 'At least one project must be selected';
  END IF;

  SELECT organization_id INTO _org FROM public.portfolio_items WHERE id = _portfolio_item_id;
  IF _org IS NULL THEN RAISE EXCEPTION 'Portfolio item not found'; END IF;
  IF NOT public.is_org_admin(_uid, _org) THEN RAISE EXCEPTION 'Not authorized'; END IF;

  FOR _rec IN
    SELECT p.id, p.organization_id, p.workspace_id, p.portfolio_item_id AS current_pi
      FROM public.projects p
     WHERE p.id = ANY(_project_ids)
  LOOP
    IF _rec.organization_id <> _org THEN
      RAISE EXCEPTION 'Project % belongs to a different organization', _rec.id;
    END IF;

    IF _rec.current_pi IS DISTINCT FROM _portfolio_item_id THEN
      _skipped := _skipped + 1;
      CONTINUE;
    END IF;

    UPDATE public.projects
       SET portfolio_item_id = NULL,
           updated_at = now()
     WHERE id = _rec.id;

    _removed := _removed + 1;
    _affected := _affected || _rec.id;

    PERFORM public.log_activity_event(
      _org, _uid, 'project_portfolio_changed', 'project', _rec.id,
      jsonb_build_object(
        'old_portfolio_item_id', _portfolio_item_id,
        'new_portfolio_item_id', NULL,
        'source', 'admin_portfolio_manage'
      ),
      _rec.workspace_id
    );
  END LOOP;

  RETURN jsonb_build_object(
    'removed_count', _removed,
    'skipped_count', _skipped,
    'affected_project_ids', to_jsonb(_affected)
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_remove_workspace_access(_organization_id uuid, _target_user_id uuid, _workspace_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE _ws_name text;
BEGIN
  IF NOT public.is_active_user(auth.uid()) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;
  IF NOT public.is_org_admin(auth.uid(), _organization_id) THEN RAISE EXCEPTION 'Access denied'; END IF;
  SELECT name INTO _ws_name FROM public.workspaces WHERE id = _workspace_id;
  PERFORM public.log_activity_event(_organization_id, auth.uid(), 'workspace_access_removed', 'user', _target_user_id, jsonb_build_object('workspace_id', _workspace_id, 'workspace_name', _ws_name), _workspace_id);
  DELETE FROM public.user_roles WHERE user_id = _target_user_id AND workspace_id = _workspace_id AND organization_id = _organization_id;
  DELETE FROM public.workspace_memberships WHERE user_id = _target_user_id AND workspace_id = _workspace_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_resend_invitation(_organization_id uuid, _invitation_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE _email text; _new_token uuid; _token_hash text;
BEGIN
  IF NOT public.is_active_user(auth.uid()) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;
  IF NOT public.is_org_admin(auth.uid(), _organization_id) THEN RAISE EXCEPTION 'Access denied'; END IF;
  SELECT email INTO _email FROM public.invitations WHERE id = _invitation_id AND organization_id = _organization_id AND status = 'pending';
  IF NOT FOUND THEN RAISE EXCEPTION 'Pending invitation not found'; END IF;
  _new_token := gen_random_uuid(); _token_hash := encode(digest(_new_token::text, 'sha256'), 'hex');
  UPDATE public.invitations SET expires_at = now() + interval '7 days', updated_at = now(), token = _token_hash WHERE id = _invitation_id AND organization_id = _organization_id AND status = 'pending';
  PERFORM public.log_activity_event(_organization_id, auth.uid(), 'invitation_resent', 'invitation', _invitation_id, jsonb_build_object('email', _email));
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_revoke_invitation(_organization_id uuid, _invitation_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE _email text; _ws_id uuid;
BEGIN
  IF NOT public.is_active_user(auth.uid()) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;
  IF NOT public.is_org_admin(auth.uid(), _organization_id) THEN RAISE EXCEPTION 'Access denied'; END IF;
  SELECT email, workspace_id INTO _email, _ws_id FROM public.invitations WHERE id = _invitation_id AND organization_id = _organization_id AND status = 'pending';
  UPDATE public.invitations SET status = 'revoked', updated_at = now() WHERE id = _invitation_id AND organization_id = _organization_id AND status = 'pending';
  IF NOT FOUND THEN RAISE EXCEPTION 'Pending invitation not found'; END IF;
  PERFORM public.log_activity_event(_organization_id, auth.uid(), 'invitation_revoked', 'invitation', _invitation_id, jsonb_build_object('email', _email), _ws_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_set_org_admin(_organization_id uuid, _target_user_id uuid, _is_admin boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE _remaining int;
BEGIN
  IF NOT public.is_active_user(auth.uid()) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;
  IF NOT public.is_org_admin(auth.uid(), _organization_id) THEN RAISE EXCEPTION 'Access denied'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = _target_user_id AND organization_id = _organization_id) THEN
    RAISE EXCEPTION 'User not found';
  END IF;

  IF _is_admin THEN
    PERFORM public._ensure_membership_layers(_target_user_id, _organization_id, auth.uid());
    UPDATE public.organization_memberships
       SET role = 'org_admin'::public.organization_role,
           status = 'active'::public.membership_status,
           updated_by = auth.uid(), updated_at = now()
     WHERE organization_id = _organization_id AND user_id = _target_user_id
       AND role <> 'org_admin';
    INSERT INTO public.user_roles (user_id, role, organization_id, workspace_id)
      VALUES (_target_user_id, 'org_admin', _organization_id, NULL) ON CONFLICT DO NOTHING;
    PERFORM public.log_activity_event(_organization_id, auth.uid(), 'org_admin_granted',
      'user', _target_user_id, '{}'::jsonb, NULL);
  ELSE
    IF _target_user_id = auth.uid() THEN RAISE EXCEPTION 'Cannot remove your own org admin role'; END IF;

    -- Last-admin safeguard (preserves current behavior).
    SELECT COUNT(*) INTO _remaining
      FROM public.organization_memberships
     WHERE organization_id = _organization_id AND status = 'active'
       AND role = 'org_admin' AND user_id <> _target_user_id;
    IF _remaining < 1 AND EXISTS (
      SELECT 1 FROM public.organization_memberships
       WHERE organization_id = _organization_id AND user_id = _target_user_id
         AND status = 'active' AND role = 'org_admin'
    ) THEN
      RAISE EXCEPTION 'Cannot remove the last Org Admin';
    END IF;

    UPDATE public.organization_memberships
       SET role = 'org_member'::public.organization_role,
           updated_by = auth.uid(), updated_at = now()
     WHERE organization_id = _organization_id AND user_id = _target_user_id
       AND role = 'org_admin';
    DELETE FROM public.user_roles
     WHERE user_id = _target_user_id AND role = 'org_admin'
       AND organization_id = _organization_id AND workspace_id IS NULL;
    PERFORM public.log_activity_event(_organization_id, auth.uid(), 'org_admin_revoked',
      'user', _target_user_id, '{}'::jsonb, NULL);
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_test_tenant_integration_metadata(_integration_id uuid, _reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _integ public.tenant_integrations;
  _secret_count int;
  _new_status public.tenant_integration_status;
BEGIN
  SELECT * INTO _integ FROM public.tenant_integrations WHERE id = _integration_id;
  IF _integ.id IS NULL THEN RAISE EXCEPTION 'Integration % not found', _integration_id; END IF;
  PERFORM public._assert_tenant_admin_or_super(_integ.tenant_id, _reason);
  SELECT COUNT(*) INTO _secret_count FROM public.tenant_secret_refs
   WHERE integration_id = _integ.id AND status = 'active';
  _new_status := CASE
    WHEN _secret_count = 0 THEN 'not_configured'::public.tenant_integration_status
    WHEN _integ.is_enabled THEN 'active'::public.tenant_integration_status
    ELSE 'disabled'::public.tenant_integration_status
  END;
  UPDATE public.tenant_integrations
     SET last_tested_at = now(), status = _new_status,
         updated_by = auth.uid(), updated_at = now()
   WHERE id = _integration_id;
  INSERT INTO public.tenant_secret_access_audit(tenant_id, integration_id, actor_user_id, action, reason, function_name, result)
  VALUES (_integ.tenant_id, _integ.id, auth.uid(), 'tested', _reason, 'admin_test_tenant_integration_metadata', 'success');
  RETURN jsonb_build_object('integration_id', _integ.id, 'status', _new_status,
                            'active_secret_count', _secret_count, 'tested_at', now());
END $function$

CREATE OR REPLACE FUNCTION public.admin_update_portfolio_item(_portfolio_item_id uuid, _name text, _code text DEFAULT NULL::text, _description text DEFAULT NULL::text, _lifecycle_state text DEFAULT 'opportunity_candidate'::text, _owner_id uuid DEFAULT NULL::uuid, _strategic_priority text DEFAULT 'medium'::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _org uuid;
  _name_trim text;
  _owner_org uuid;
BEGIN
  IF _uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF NOT public.is_active_user(_uid) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;

  SELECT organization_id INTO _org FROM public.portfolio_items WHERE id = _portfolio_item_id;
  IF _org IS NULL THEN RAISE EXCEPTION 'Portfolio item not found'; END IF;

  IF NOT public.is_org_admin(_uid, _org) THEN RAISE EXCEPTION 'Not authorized'; END IF;

  _name_trim := btrim(COALESCE(_name, ''));
  IF _name_trim = '' THEN RAISE EXCEPTION 'Name is required'; END IF;
  IF char_length(_name_trim) > 200 THEN RAISE EXCEPTION 'Name exceeds 200 characters'; END IF;
  IF _code IS NOT NULL AND char_length(_code) > 80 THEN RAISE EXCEPTION 'Code exceeds 80 characters'; END IF;
  IF _description IS NOT NULL AND char_length(_description) > 4000 THEN RAISE EXCEPTION 'Description exceeds 4000 characters'; END IF;
  IF _lifecycle_state NOT IN (
    'opportunity_candidate','business_case_approved','contracted','development',
    'submission_approval','launch_preparation','launched_commercial',
    'lcm_optimization','on_hold','discontinuation','retired'
  ) THEN RAISE EXCEPTION 'Invalid lifecycle_state'; END IF;
  IF _strategic_priority NOT IN ('critical','high','medium','low','watchlist') THEN
    RAISE EXCEPTION 'Invalid strategic_priority';
  END IF;
  IF _owner_id IS NOT NULL THEN
    SELECT organization_id INTO _owner_org FROM public.profiles WHERE id = _owner_id;
    IF _owner_org IS DISTINCT FROM _org THEN
      RAISE EXCEPTION 'Owner must belong to the same organization';
    END IF;
  END IF;

  UPDATE public.portfolio_items
     SET name = _name_trim,
         code = _code,
         description = _description,
         lifecycle_state = _lifecycle_state,
         strategic_priority = _strategic_priority,
         owner_id = _owner_id,
         updated_by = _uid
   WHERE id = _portfolio_item_id;

  PERFORM public.log_activity_event(
    _org, _uid, 'portfolio_updated', 'portfolio', _portfolio_item_id, NULL::jsonb, NULL::uuid
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_update_portfolio_team_member_role(_team_member_id uuid, _role text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _row public.portfolio_item_team_members%ROWTYPE;
  _conflict_id uuid;
BEGIN
  IF _uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF NOT public.is_active_user(_uid) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;

  SELECT * INTO _row FROM public.portfolio_item_team_members WHERE id = _team_member_id;
  IF _row.id IS NULL THEN RAISE EXCEPTION 'Team member not found'; END IF;
  IF NOT public.is_org_admin(_uid, _row.organization_id) THEN RAISE EXCEPTION 'Not authorized'; END IF;

  IF _role NOT IN (
    'product_manager','commercial_lead','finance_partner','supply_lead',
    'regulatory_lead','quality_lead','tech_services_lead','launch_lead',
    'bd_lead','srm_lead','other'
  ) THEN RAISE EXCEPTION 'Invalid role'; END IF;

  IF _row.role = _role THEN RETURN; END IF;

  -- Prevent duplicate active row conflict
  SELECT id INTO _conflict_id
    FROM public.portfolio_item_team_members
   WHERE portfolio_item_id = _row.portfolio_item_id
     AND user_id = _row.user_id
     AND role = _role
     AND is_active = true
     AND id <> _team_member_id
   LIMIT 1;
  IF _conflict_id IS NOT NULL THEN
    RAISE EXCEPTION 'This user already has that role on this Portfolio';
  END IF;

  UPDATE public.portfolio_item_team_members
     SET role = _role, updated_by = _uid
   WHERE id = _team_member_id;

  PERFORM public.log_activity_event(
    _row.organization_id, _uid, 'portfolio_team_member_role_changed', 'portfolio', _row.portfolio_item_id,
    jsonb_build_object('user_id', _row.user_id, 'previous_role', _row.role, 'new_role', _role),
    NULL::uuid
  );
END;
$function$

