 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_org uuid := public.get_user_org_id(auth.uid());
  v_article_org uuid;
  v_id uuid;
BEGIN
  IF v_org IS NULL OR NOT public.is_org_admin(auth.uid(), v_org) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  SELECT organization_id INTO v_article_org
  FROM public.knowledge_articles WHERE id = _article_id;

  IF v_article_org IS NULL OR v_article_org <> v_org THEN
