    _ai_flow, _feature_area, _route_patterns, _user_intents, _audience,
    _synonyms, _freshness_label, _related_feature_flags,
    public._kc_ai_meta_encrypt_array(_question_examples, v_org),
    public._kc_ai_meta_encrypt_array(_answer_rules,      v_org),
    public._kc_ai_meta_encrypt_array(_forbidden_claims,  v_org),
    auth.uid(), auth.uid()
  )
  ON CONFLICT (article_id) DO UPDATE SET
    ai_flow                     = EXCLUDED.ai_flow,
    feature_area                = EXCLUDED.feature_area,
    route_patterns              = EXCLUDED.route_patterns,
    user_intents                = EXCLUDED.user_intents,
    audience                    = EXCLUDED.audience,
    synonyms                    = EXCLUDED.synonyms,
    freshness_label             = EXCLUDED.freshness_label,
    related_feature_flags       = EXCLUDED.related_feature_flags,
    question_examples_protected = EXCLUDED.question_examples_protected,
    answer_rules_protected      = EXCLUDED.answer_rules_protected,
    forbidden_claims_protected  = EXCLUDED.forbidden_claims_protected,
    updated_by                  = auth.uid(),
    updated_at                  = now()
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$function$

