CREATE OR REPLACE FUNCTION public.adoption_resolve_object_project(_object_type text, _object_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _t text; _tid uuid; _proj uuid;
BEGIN
  IF _object_type = 'risk' THEN
    SELECT target_type, target_id INTO _t, _tid FROM public.risks WHERE id = _object_id;
  ELSIF _object_type = 'blocker' THEN
    SELECT target_type, target_id INTO _t, _tid FROM public.blockers WHERE id = _object_id;
  ELSIF _object_type = 'kpi' THEN
    SELECT target_type, target_id INTO _t, _tid FROM public.kpi_definitions WHERE id = _object_id;
    -- KPIs must be project-scoped for adoption linking
    IF _t IS DISTINCT FROM 'project' THEN RETURN NULL; END IF;
    RETURN _tid;
  ELSE
    RETURN NULL;
  END IF;

  IF _tid IS NULL THEN RETURN NULL; END IF;
  IF _t = 'project' THEN
    RETURN _tid;
  ELSIF _t = 'phase' THEN
    SELECT project_id INTO _proj FROM public.phases WHERE id = _tid;
    RETURN _proj;
  ELSIF _t = 'task' THEN
    SELECT project_id INTO _proj FROM public.tasks WHERE id = _tid;
    RETURN _proj;
  END IF;
  RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.ai_guide_v2_admin_reindex_knowledge(p_scope text, p_article_id uuid DEFAULT NULL::uuid, p_force boolean DEFAULT false)
 RETURNS TABLE(job_id uuid, status text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  _org uuid;
  _job_type text;
  _new_id uuid;
begin
  if auth.uid() is null then
    raise exception 'Access denied';
  end if;
  _org := public.get_user_org_id(auth.uid());
  if _org is null or not public.is_org_admin(auth.uid(), _org) then
    raise exception 'Access denied';
  end if;

  _job_type := case p_scope
    when 'full' then 'full_rebuild'
    when 'article' then 'article_refresh'
    when 'workflow' then 'workflow_refresh'
    when 'metadata' then 'metadata_refresh'
    else null
  end;

  if _job_type is null then
    raise exception 'Invalid scope: %', p_scope;
  end if;

  insert into public.ai_guide_v2_embedding_jobs (
    organization_id, job_type, status, requested_by, source_article_id, stats
  ) values (
    _org, _job_type, 'queued', auth.uid(), p_article_id,
    jsonb_build_object('force', coalesce(p_force, false))
  )
  returning id into _new_id;

  return query select _new_id, 'queued'::text;
end;
$function$

CREATE OR REPLACE FUNCTION public.ai_help_append_message(_conversation_id uuid, _role text, _content text, _context_route text DEFAULT NULL::text, _context_label text DEFAULT NULL::text, _source_article_ids uuid[] DEFAULT '{}'::uuid[])
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_org  uuid := public.get_user_org_id(auth.uid());
  v_conv public.ai_help_conversations%ROWTYPE;
  v_id   uuid;
BEGIN
  IF v_org IS NULL OR NOT public.is_active_user(auth.uid()) THEN
    RAISE EXCEPTION 'forbidden';
