  IF _role NOT IN ('user','assistant') THEN
    RAISE EXCEPTION 'invalid role';
  END IF;
  SELECT * INTO v_conv FROM public.ai_help_conversations WHERE id = _conversation_id;
  IF v_conv.id IS NULL OR v_conv.user_id <> auth.uid() OR v_conv.organization_id <> v_org THEN
    RAISE EXCEPTION 'forbidden';
