    (_conversation_id, v_org, auth.uid(), _role, _content, _context_route, _context_label, COALESCE(_source_article_ids, '{}'::uuid[]))
  RETURNING id INTO v_id;

  UPDATE public.ai_help_conversations SET updated_at = now() WHERE id = _conversation_id;
  RETURN v_id;
