CREATE OR REPLACE FUNCTION public.ai_help_list_messages(_conversation_id uuid)
 RETURNS TABLE(id uuid, role text, content text, context_route text, context_label text, source_article_ids uuid[], created_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_org  uuid := public.get_user_org_id(auth.uid());
  v_conv public.ai_help_conversations%ROWTYPE;
BEGIN
  IF v_org IS NULL OR NOT public.is_active_user(auth.uid()) THEN RETURN; END IF;
  SELECT * INTO v_conv FROM public.ai_help_conversations c WHERE c.id = _conversation_id;
  IF v_conv.id IS NULL OR v_conv.user_id <> auth.uid() OR v_conv.organization_id <> v_org THEN RETURN; END IF;

  RETURN QUERY
  SELECT m.id, m.role,
         public.btpm_decrypt(m.content, m.organization_id),
         m.context_route,
         public.btpm_decrypt(m.context_label, m.organization_id),
         m.source_article_ids, m.created_at
  FROM public.ai_help_messages m
  WHERE m.conversation_id = _conversation_id
  ORDER BY m.created_at ASC;
END; $function$

CREATE OR REPLACE FUNCTION public.ai_help_list_my_feedback_for_conversation(_conversation_id uuid)
 RETURNS TABLE(id uuid, assistant_message_id uuid, rating text, reason_code text, comment text, created_at timestamp with time zone, updated_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
#variable_conflict use_column
DECLARE
  v_org  uuid := public.get_user_org_id(auth.uid());
  v_conv public.ai_help_conversations%ROWTYPE;
BEGIN
  IF v_org IS NULL OR NOT public.is_active_user(auth.uid()) THEN RETURN; END IF;
  SELECT * INTO v_conv FROM public.ai_help_conversations c WHERE c.id = _conversation_id;
  IF v_conv.id IS NULL OR v_conv.user_id <> auth.uid() OR v_conv.organization_id <> v_org THEN RETURN; END IF;

  RETURN QUERY
