CREATE OR REPLACE FUNCTION public.ai_help_upsert_message_feedback(_assistant_message_id uuid, _rating text, _reason_code text DEFAULT NULL::text, _comment text DEFAULT NULL::text)
 RETURNS TABLE(id uuid, assistant_message_id uuid, conversation_id uuid, rating text, reason_code text, comment text, created_at timestamp with time zone, updated_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
#variable_conflict use_column
DECLARE
  v_org uuid := public.get_user_org_id(auth.uid());
  v_msg public.ai_help_messages%ROWTYPE;
  v_id  uuid;
BEGIN
  IF v_org IS NULL OR NOT public.is_active_user(auth.uid()) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;
  IF _rating NOT IN ('helpful','not_helpful') THEN
    RAISE EXCEPTION 'invalid rating';
  END IF;
  SELECT * INTO v_msg FROM public.ai_help_messages m WHERE m.id = _assistant_message_id;
  IF v_msg.id IS NULL
     OR v_msg.role <> 'assistant'
     OR v_msg.user_id <> auth.uid()
     OR v_msg.organization_id <> v_org THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  -- Pass plaintext _comment; the BEFORE INSERT/UPDATE trigger
  -- (trg_encrypt_ai_help_feedback_fields) handles encryption exactly once.
  INSERT INTO public.ai_help_message_feedback AS f
    (organization_id, conversation_id, assistant_message_id, user_id, rating, reason_code, comment)
  VALUES
    (v_org, v_msg.conversation_id, _assistant_message_id, auth.uid(), _rating, _reason_code, _comment)
  ON CONFLICT (user_id, assistant_message_id) DO UPDATE
    SET rating      = EXCLUDED.rating,
        reason_code = EXCLUDED.reason_code,
        comment     = _comment
  RETURNING f.id INTO v_id;

  RETURN QUERY
  SELECT f.id, f.assistant_message_id, f.conversation_id, f.rating, f.reason_code,
         public.btpm_decrypt(f.comment, f.organization_id),
         f.created_at, f.updated_at
  FROM public.ai_help_message_feedback f
  WHERE f.id = v_id;
END; $function$

CREATE OR REPLACE FUNCTION public.append_execution_update(_target_type text, _target_id uuid, _summary text, _update_date date, _status_label text DEFAULT NULL::text, _correlation_id text DEFAULT NULL::text, _idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_target_type text := lower(nullif(btrim(coalesce(_target_type,'')),''));
  v_project_id uuid;
  v_workspace_id uuid;
  v_organization_id uuid;
  v_summary text;
  v_status text;
  v_new_id uuid;
  v_data jsonb;
BEGIN
  IF v_actor IS NULL OR NOT public.is_active_user(v_actor) THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'append_execution_update',
      'execution_update', NULL, NULL,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF v_target_type NOT IN ('phase','task') OR _target_id IS NULL THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'append_execution_update',
      'execution_update', NULL, NULL,
      jsonb_build_object('reason','invalid_target'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  v_summary := nullif(btrim(coalesce(_summary,'')), '');
  IF v_summary IS NULL THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'append_execution_update',
      'execution_update', NULL, NULL,
      jsonb_build_object('reason','summary_required'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  -- PMG.6B.1: only reject NULL update_date; no future-date restriction.
  IF _update_date IS NULL THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'append_execution_update',
      'execution_update', NULL, NULL,
      jsonb_build_object('reason','invalid_update_date'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  -- PMG.6B.1: normalize blank status label to NULL; no application length limit.
  v_status := nullif(btrim(coalesce(_status_label,'')), '');

  IF v_target_type = 'phase' THEN
    SELECT project_id, workspace_id, organization_id
      INTO v_project_id, v_workspace_id, v_organization_id
      FROM public.phases WHERE id = _target_id;
  ELSE
    SELECT project_id, workspace_id, organization_id
      INTO v_project_id, v_workspace_id, v_organization_id
      FROM public.tasks WHERE id = _target_id;
  END IF;

  IF v_project_id IS NULL THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'append_execution_update',
      'execution_update', NULL, NULL,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF NOT public.has_project_pm_authority(v_actor, v_project_id)
     OR NOT public.can_write_demo(v_actor, v_workspace_id) THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'append_execution_update',
      'execution_update', NULL, v_project_id,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  BEGIN
    INSERT INTO public.execution_updates (
      target_type, target_id, summary, status_label, update_date,
      author_id, workspace_id, organization_id
    ) VALUES (
      v_target_type, _target_id, v_summary, v_status, _update_date,
      v_actor, v_workspace_id, v_organization_id
    )
    RETURNING id INTO v_new_id;
  EXCEPTION
    WHEN check_violation OR raise_exception OR not_null_violation OR invalid_text_representation OR foreign_key_violation THEN
      RETURN public.pmg_build_result(
        'invalid'::public.pmg_command_status, 'append_execution_update',
        'execution_update', NULL, v_project_id,
        jsonb_build_object('reason', SQLERRM),
        '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
      );
  END;

  v_data := jsonb_build_object(
    'id', v_new_id,
    'target_type', v_target_type,
    'target_id', _target_id,
    'project_id', v_project_id,
    'workspace_id', v_workspace_id,
    'update_date', _update_date,
    'has_status_label', v_status IS NOT NULL
  );

  PERFORM public.pmg_record_command_audit(
    'applied'::public.pmg_command_status, 'append_execution_update',
    'btpm_ui'::public.pmg_source_channel,
    v_project_id, 'execution_update', v_new_id, NULL,
    _correlation_id, _idempotency_key,
    jsonb_build_object(
      'target_type', v_target_type,
      'target_id', _target_id,
      'workspace_id', v_workspace_id,
      'update_date', _update_date,
      'has_status_label', v_status IS NOT NULL
    )
  );

  RETURN public.pmg_build_result(
    'applied'::public.pmg_command_status, 'append_execution_update',
    'execution_update', v_new_id, v_project_id,
    v_data, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.append_kpi_update(_kpi_definition_id uuid, _value numeric, _update_date date, _note text DEFAULT NULL::text, _correlation_id text DEFAULT NULL::text, _idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_kpi record;
  v_project_id uuid;
  v_project record;
  v_note text;
  v_new_id uuid;
BEGIN
  IF v_actor IS NULL OR NOT public.is_active_user(v_actor) THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'append_kpi_update',
      'kpi_update', NULL, NULL,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF _kpi_definition_id IS NULL THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'append_kpi_update',
      'kpi_update', NULL, NULL,
      jsonb_build_object('reason','kpi_definition_id_required'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF _value IS NULL THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'append_kpi_update',
      'kpi_update', NULL, NULL,
      jsonb_build_object('reason','value_required'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF _update_date IS NULL THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'append_kpi_update',
      'kpi_update', NULL, NULL,
      jsonb_build_object('reason','update_date_required'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  SELECT id, workspace_id, organization_id, target_type, target_id,
         is_archived, source_mode, value_type
    INTO v_kpi
    FROM public.kpi_definitions
   WHERE id = _kpi_definition_id
   FOR UPDATE;

  IF v_kpi.id IS NULL THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'append_kpi_update',
      'kpi_update', NULL, NULL,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF v_kpi.target_type IS DISTINCT FROM 'project' OR v_kpi.target_id IS NULL THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'append_kpi_update',
      'kpi_update', NULL, NULL,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  v_project_id := v_kpi.target_id;

  SELECT id, organization_id, workspace_id
    INTO v_project
    FROM public.projects
   WHERE id = v_project_id;

  IF v_project.id IS NULL THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'append_kpi_update',
      'kpi_update', NULL, v_project_id,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF NOT public.has_project_pm_authority(v_actor, v_project_id)
     OR NOT public.can_write_demo(v_actor, v_project.workspace_id) THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'append_kpi_update',
      'kpi_update', NULL, v_project_id,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  v_note := nullif(btrim(coalesce(_note, '')), '');

  BEGIN
    INSERT INTO public.kpi_updates (
      kpi_definition_id, value, update_date, note,
      author_id, workspace_id, organization_id
    ) VALUES (
      _kpi_definition_id, _value, _update_date, v_note,
      v_actor, v_kpi.workspace_id, v_kpi.organization_id
    )
    RETURNING id INTO v_new_id;
  EXCEPTION
    WHEN check_violation OR raise_exception OR not_null_violation OR invalid_text_representation OR foreign_key_violation THEN
      RETURN public.pmg_build_result(
        'invalid'::public.pmg_command_status, 'append_kpi_update',
        'kpi_update', NULL, v_project_id,
        jsonb_build_object('reason', SQLERRM),
        '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
      );
  END;

  PERFORM public.pmg_record_command_audit(
    'applied'::public.pmg_command_status, 'append_kpi_update',
    'btpm_ui'::public.pmg_source_channel,
    v_project_id, 'kpi_update', v_new_id, NULL,
    _correlation_id, _idempotency_key,
    jsonb_build_object(
      'kpi_definition_id', _kpi_definition_id,
      'project_id', v_project_id,
      'workspace_id', v_kpi.workspace_id,
      'update_date', _update_date,
      'value_type', v_kpi.value_type,
      'source_mode', v_kpi.source_mode,
      'value_present', true,
      'note_present', (v_note IS NOT NULL)
    )
  );

  RETURN public.pmg_build_result(
    'applied'::public.pmg_command_status, 'append_kpi_update',
    'kpi_update', v_new_id, v_project_id,
    jsonb_build_object('id', v_new_id, 'kpi_update_id', v_new_id),
    '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.apply_backlog_item_create(_project_id uuid, _title text, _description text DEFAULT NULL::text, _priority text DEFAULT 'medium'::text, _phase_id uuid DEFAULT NULL::uuid, _sprint_id uuid DEFAULT NULL::uuid, _workflow_state_id uuid DEFAULT NULL::uuid, _correlation_id text DEFAULT NULL::text, _idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_project record;
  v_title text;
  v_description text;
  v_priority public.pm_priority;
  v_sort_order int;
  v_new_id uuid;
  v_row record;
  v_data jsonb;
BEGIN
  IF v_actor IS NULL OR NOT public.is_active_user(v_actor) THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'apply_backlog_item_create',
      'backlog_item', NULL, _project_id,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  -- Lock the parent Project row to serialize backlog creation for this project,
  -- including the empty-backlog case where no sibling rows exist to lock.
  SELECT id, workspace_id, organization_id INTO v_project
    FROM public.projects WHERE id = _project_id FOR UPDATE;
  IF v_project.id IS NULL THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'apply_backlog_item_create',
      'backlog_item', NULL, _project_id,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF NOT public.has_project_pm_authority(v_actor, _project_id)
     OR NOT public.can_write_demo(v_actor, v_project.workspace_id) THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'apply_backlog_item_create',
      'backlog_item', NULL, _project_id,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  v_title := btrim(COALESCE(_title,''));
  IF v_title = '' THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'apply_backlog_item_create',
      'backlog_item', NULL, _project_id,
      jsonb_build_object('reason','title_blank'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF _description IS NULL THEN
    v_description := NULL;
  ELSE
    v_description := btrim(_description);
    IF v_description = '' THEN v_description := NULL; END IF;
  END IF;

  BEGIN
    v_priority := COALESCE(_priority,'medium')::public.pm_priority;
  EXCEPTION WHEN others THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'apply_backlog_item_create',
      'backlog_item', NULL, _project_id,
      jsonb_build_object('reason','invalid_priority'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END;

  IF _phase_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.phases WHERE id = _phase_id AND project_id = _project_id
  ) THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'apply_backlog_item_create',
      'backlog_item', NULL, _project_id,
      jsonb_build_object('reason','phase_not_in_project'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF _sprint_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.sprints WHERE id = _sprint_id AND project_id = _project_id
  ) THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'apply_backlog_item_create',
      'backlog_item', NULL, _project_id,
      jsonb_build_object('reason','sprint_not_in_project'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF _workflow_state_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.board_workflow_states
     WHERE id = _workflow_state_id AND project_id = _project_id
  ) THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'apply_backlog_item_create',
      'backlog_item', NULL, _project_id,
      jsonb_build_object('reason','workflow_state_not_in_project'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  -- Parent Project row is already locked above; derive next sort_order safely
  -- even when no sibling backlog rows exist.
  SELECT COALESCE(MAX(sort_order) + 1, 0) INTO v_sort_order
    FROM public.backlog_items
   WHERE project_id = _project_id AND is_archived = false;

  INSERT INTO public.backlog_items(
    organization_id, workspace_id, project_id,
    phase_id, sprint_id, workflow_state_id,
    title, description, priority, sort_order, created_by
  ) VALUES (
    v_project.organization_id, v_project.workspace_id, _project_id,
    _phase_id, _sprint_id, _workflow_state_id,
    v_title, v_description, v_priority, v_sort_order, v_actor
  )
  RETURNING id INTO v_new_id;

  SELECT id, project_id, organization_id, phase_id, sprint_id, workflow_state_id,
         title, description, priority, sort_order, is_archived, updated_at
    INTO v_row FROM public.backlog_items WHERE id = v_new_id;

  v_data := jsonb_build_object(
    'id', v_row.id,
    'project_id', v_row.project_id,
    'phase_id', v_row.phase_id,
    'sprint_id', v_row.sprint_id,
    'workflow_state_id', v_row.workflow_state_id,
    'title', v_row.title,
    'description', CASE WHEN v_row.description IS NULL THEN NULL
                        ELSE public.btpm_decrypt(v_row.description, v_row.organization_id) END,
    'priority', v_row.priority,
    'sort_order', v_row.sort_order,
    'is_archived', v_row.is_archived,
    'updated_at', v_row.updated_at
  );

  PERFORM public.pmg_record_command_audit(
    'applied'::public.pmg_command_status, 'apply_backlog_item_create',
    'btpm_ui'::public.pmg_source_channel,
    _project_id, 'backlog_item', v_new_id, NULL,
    _correlation_id, _idempotency_key,
    jsonb_build_object(
      'has_description', v_description IS NOT NULL,
      'has_phase', _phase_id IS NOT NULL,
      'has_sprint', _sprint_id IS NOT NULL,
      'has_workflow_state', _workflow_state_id IS NOT NULL
    )
  );

  RETURN public.pmg_build_result(
    'applied'::public.pmg_command_status, 'apply_backlog_item_create',
    'backlog_item', v_new_id, _project_id,
    v_data, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.apply_backlog_item_update(_backlog_item_id uuid, _expected_updated_at timestamp with time zone, _set_title boolean DEFAULT false, _title text DEFAULT NULL::text, _set_description boolean DEFAULT false, _description text DEFAULT NULL::text, _set_priority boolean DEFAULT false, _priority text DEFAULT NULL::text, _set_phase_id boolean DEFAULT false, _phase_id uuid DEFAULT NULL::uuid, _set_sprint_id boolean DEFAULT false, _sprint_id uuid DEFAULT NULL::uuid, _set_workflow_state_id boolean DEFAULT false, _workflow_state_id uuid DEFAULT NULL::uuid, _correlation_id text DEFAULT NULL::text, _idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_row record;
  v_project_id uuid;
  v_workspace_id uuid;
  v_org_id uuid;
  v_current_description text;
  v_new_title text;
  v_new_description text;
  v_new_priority public.pm_priority;
  v_new_phase uuid;
  v_new_sprint uuid;
  v_new_wfs uuid;
  v_changes int := 0;
  v_upd record;
  v_data jsonb;
BEGIN
  IF v_actor IS NULL OR NOT public.is_active_user(v_actor) THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'apply_backlog_item_update',
      'backlog_item', _backlog_item_id, NULL,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF _expected_updated_at IS NULL THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'apply_backlog_item_update',
      'backlog_item', _backlog_item_id, NULL,
      jsonb_build_object('reason','expected_updated_at_required'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  SELECT id, project_id, workspace_id, organization_id, phase_id, sprint_id,
         workflow_state_id, title, description, priority, sort_order, is_archived, updated_at
    INTO v_row
    FROM public.backlog_items
   WHERE id = _backlog_item_id
   FOR UPDATE;

  IF v_row.id IS NULL THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'apply_backlog_item_update',
      'backlog_item', _backlog_item_id, NULL,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  v_project_id := v_row.project_id;
  v_workspace_id := v_row.workspace_id;
  v_org_id := v_row.organization_id;

  IF NOT public.has_project_pm_authority(v_actor, v_project_id)
     OR NOT public.can_write_demo(v_actor, v_workspace_id) THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'apply_backlog_item_update',
      'backlog_item', _backlog_item_id, v_project_id,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF v_row.updated_at IS DISTINCT FROM _expected_updated_at THEN
    PERFORM public.pmg_record_command_audit(
      'conflict'::public.pmg_command_status, 'apply_backlog_item_update',
      'btpm_ui'::public.pmg_source_channel,
      v_project_id, 'backlog_item', _backlog_item_id, NULL,
      _correlation_id, _idempotency_key,
      jsonb_build_object('stale', true)
    );
    RETURN public.pmg_build_result(
      'conflict'::public.pmg_command_status, 'apply_backlog_item_update',
      'backlog_item', _backlog_item_id, v_project_id,
      jsonb_build_object('code','stale_backlog_item','current_updated_at', v_row.updated_at),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  v_current_description := CASE WHEN v_row.description IS NULL THEN NULL
    ELSE public.btpm_decrypt(v_row.description, v_org_id) END;

  -- Resolve incoming fields with explicit set/clear semantics.
  IF _set_title THEN
    v_new_title := btrim(COALESCE(_title,''));
    IF v_new_title = '' THEN
      RETURN public.pmg_build_result(
        'invalid'::public.pmg_command_status, 'apply_backlog_item_update',
        'backlog_item', _backlog_item_id, v_project_id,
        jsonb_build_object('reason','title_blank'),
        '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
      );
    END IF;
  ELSE
    v_new_title := v_row.title;
  END IF;

  IF _set_description THEN
    IF _description IS NULL THEN
      v_new_description := NULL;
    ELSE
      v_new_description := btrim(_description);
      IF v_new_description = '' THEN v_new_description := NULL; END IF;
    END IF;
  ELSE
    v_new_description := v_current_description;
  END IF;

  IF _set_priority THEN
    BEGIN
      v_new_priority := COALESCE(_priority, 'medium')::public.pm_priority;
    EXCEPTION WHEN others THEN
      RETURN public.pmg_build_result(
        'invalid'::public.pmg_command_status, 'apply_backlog_item_update',
        'backlog_item', _backlog_item_id, v_project_id,
        jsonb_build_object('reason','invalid_priority'),
        '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
      );
    END;
  ELSE
    v_new_priority := v_row.priority;
  END IF;

  IF _set_phase_id THEN
    v_new_phase := _phase_id;
    IF v_new_phase IS NOT NULL AND NOT EXISTS (
      SELECT 1 FROM public.phases WHERE id = v_new_phase AND project_id = v_project_id
    ) THEN
      RETURN public.pmg_build_result(
        'invalid'::public.pmg_command_status, 'apply_backlog_item_update',
        'backlog_item', _backlog_item_id, v_project_id,
        jsonb_build_object('reason','phase_not_in_project'),
        '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
      );
    END IF;
  ELSE
    v_new_phase := v_row.phase_id;
  END IF;

  IF _set_sprint_id THEN
    v_new_sprint := _sprint_id;
    IF v_new_sprint IS NOT NULL AND NOT EXISTS (
      SELECT 1 FROM public.sprints WHERE id = v_new_sprint AND project_id = v_project_id
    ) THEN
      RETURN public.pmg_build_result(
        'invalid'::public.pmg_command_status, 'apply_backlog_item_update',
        'backlog_item', _backlog_item_id, v_project_id,
        jsonb_build_object('reason','sprint_not_in_project'),
        '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
      );
    END IF;
  ELSE
    v_new_sprint := v_row.sprint_id;
  END IF;

  IF _set_workflow_state_id THEN
    v_new_wfs := _workflow_state_id;
    IF v_new_wfs IS NOT NULL AND NOT EXISTS (
      SELECT 1 FROM public.board_workflow_states WHERE id = v_new_wfs AND project_id = v_project_id
    ) THEN
      RETURN public.pmg_build_result(
        'invalid'::public.pmg_command_status, 'apply_backlog_item_update',
        'backlog_item', _backlog_item_id, v_project_id,
        jsonb_build_object('reason','workflow_state_not_in_project'),
        '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
      );
    END IF;
  ELSE
    v_new_wfs := v_row.workflow_state_id;
  END IF;

  v_changes :=
      (CASE WHEN v_new_title       IS DISTINCT FROM v_row.title             THEN 1 ELSE 0 END)
    + (CASE WHEN v_new_description IS DISTINCT FROM v_current_description   THEN 1 ELSE 0 END)
    + (CASE WHEN v_new_priority    IS DISTINCT FROM v_row.priority          THEN 1 ELSE 0 END)
    + (CASE WHEN v_new_phase       IS DISTINCT FROM v_row.phase_id          THEN 1 ELSE 0 END)
    + (CASE WHEN v_new_sprint      IS DISTINCT FROM v_row.sprint_id         THEN 1 ELSE 0 END)
    + (CASE WHEN v_new_wfs         IS DISTINCT FROM v_row.workflow_state_id THEN 1 ELSE 0 END);

  IF v_changes = 0 THEN
    v_data := jsonb_build_object(
      'id', v_row.id, 'project_id', v_project_id,
      'phase_id', v_row.phase_id, 'sprint_id', v_row.sprint_id,
      'workflow_state_id', v_row.workflow_state_id,
      'title', v_row.title, 'description', v_current_description,
      'priority', v_row.priority, 'sort_order', v_row.sort_order,
      'is_archived', v_row.is_archived, 'updated_at', v_row.updated_at
    );
    PERFORM public.pmg_record_command_audit(
      'no_change'::public.pmg_command_status, 'apply_backlog_item_update',
      'btpm_ui'::public.pmg_source_channel,
      v_project_id, 'backlog_item', _backlog_item_id, NULL,
      _correlation_id, _idempotency_key,
      jsonb_build_object('changed_field_count', 0, 'stale', false)
    );
    RETURN public.pmg_build_result(
      'no_change'::public.pmg_command_status, 'apply_backlog_item_update',
      'backlog_item', _backlog_item_id, v_project_id,
      v_data, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  UPDATE public.backlog_items
     SET title = v_new_title,
         description = v_new_description,
         priority = v_new_priority,
         phase_id = v_new_phase,
         sprint_id = v_new_sprint,
         workflow_state_id = v_new_wfs
   WHERE id = _backlog_item_id;

  SELECT id, project_id, organization_id, phase_id, sprint_id, workflow_state_id,
         title, description, priority, sort_order, is_archived, updated_at
    INTO v_upd FROM public.backlog_items WHERE id = _backlog_item_id;

  v_data := jsonb_build_object(
    'id', v_upd.id, 'project_id', v_upd.project_id,
    'phase_id', v_upd.phase_id, 'sprint_id', v_upd.sprint_id,
    'workflow_state_id', v_upd.workflow_state_id,
    'title', v_upd.title,
    'description', CASE WHEN v_upd.description IS NULL THEN NULL
                        ELSE public.btpm_decrypt(v_upd.description, v_upd.organization_id) END,
    'priority', v_upd.priority, 'sort_order', v_upd.sort_order,
    'is_archived', v_upd.is_archived, 'updated_at', v_upd.updated_at
  );

  PERFORM public.pmg_record_command_audit(
    'applied'::public.pmg_command_status, 'apply_backlog_item_update',
    'btpm_ui'::public.pmg_source_channel,
    v_project_id, 'backlog_item', _backlog_item_id, NULL,
    _correlation_id, _idempotency_key,
    jsonb_build_object(
      'changed_field_count', v_changes,
      'title_changed', v_new_title IS DISTINCT FROM v_row.title,
      'description_changed', v_new_description IS DISTINCT FROM v_current_description,
      'priority_changed', v_new_priority IS DISTINCT FROM v_row.priority,
      'phase_changed', v_new_phase IS DISTINCT FROM v_row.phase_id,
      'sprint_changed', v_new_sprint IS DISTINCT FROM v_row.sprint_id,
      'workflow_state_changed', v_new_wfs IS DISTINCT FROM v_row.workflow_state_id,
      'stale', false
    )
  );

  RETURN public.pmg_build_result(
    'applied'::public.pmg_command_status, 'apply_backlog_item_update',
    'backlog_item', _backlog_item_id, v_project_id,
    v_data, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.apply_kpi_definition_create(_project_id uuid, _name text, _description text DEFAULT NULL::text, _unit text DEFAULT NULL::text, _target_value numeric DEFAULT NULL::numeric, _target_direction kpi_target_direction DEFAULT 'target_exact'::kpi_target_direction, _source_mode text DEFAULT 'manual'::text, _value_type text DEFAULT 'number'::text, _cadence text DEFAULT 'manual_only'::text, _calculation_key text DEFAULT NULL::text, _formula_version integer DEFAULT NULL::integer, _completion_method text DEFAULT NULL::text, _comment_required boolean DEFAULT false, _action_plan_required boolean DEFAULT false, _auto_snapshot_enabled boolean DEFAULT false, _correlation_id text DEFAULT NULL::text, _idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_project record;
  v_name text;
  v_desc text;
  v_unit text;
  v_new_id uuid;
BEGIN
  IF v_actor IS NULL OR NOT public.is_active_user(v_actor) THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'apply_kpi_definition_create',
      'kpi_definition', NULL, NULL,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF _project_id IS NULL THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'apply_kpi_definition_create',
      'kpi_definition', NULL, NULL,
      jsonb_build_object('reason', 'Project is required'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  SELECT id, organization_id, workspace_id
    INTO v_project
    FROM public.projects
    WHERE id = _project_id
    FOR UPDATE;

  IF NOT FOUND THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'apply_kpi_definition_create',
      'kpi_definition', NULL, _project_id,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF NOT public.has_project_pm_authority(v_actor, _project_id)
     OR NOT public.can_write_demo(v_actor, v_project.workspace_id) THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'apply_kpi_definition_create',
      'kpi_definition', NULL, _project_id,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  v_name := btrim(coalesce(_name, ''));
  IF v_name = '' THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'apply_kpi_definition_create',
      'kpi_definition', NULL, _project_id,
      jsonb_build_object('reason', 'KPI name is required'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  v_desc := nullif(btrim(coalesce(_description, '')), '');
  v_unit := nullif(btrim(coalesce(_unit, '')), '');

  BEGIN
    INSERT INTO public.kpi_definitions (
      name, description, unit, target_value, target_direction,
      target_type, target_id,
      workspace_id, organization_id, created_by,
      source_mode, value_type, cadence,
      calculation_key, formula_version, completion_method,
      comment_required, action_plan_required, auto_snapshot_enabled
    ) VALUES (
      v_name, v_desc, v_unit, _target_value, coalesce(_target_direction, 'target_exact'::public.kpi_target_direction),
      'project', _project_id,
      v_project.workspace_id, v_project.organization_id, v_actor,
      coalesce(_source_mode, 'manual'),
      coalesce(_value_type, 'number'),
      coalesce(_cadence, 'manual_only'),
      _calculation_key, _formula_version, _completion_method,
      coalesce(_comment_required, false),
      coalesce(_action_plan_required, false),
      coalesce(_auto_snapshot_enabled, false)
    )
    RETURNING id INTO v_new_id;
  EXCEPTION
    WHEN check_violation OR raise_exception OR not_null_violation OR invalid_text_representation THEN
      RETURN public.pmg_build_result(
        'invalid'::public.pmg_command_status, 'apply_kpi_definition_create',
        'kpi_definition', NULL, _project_id,
        jsonb_build_object('reason', SQLERRM),
        '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
      );
  END;

  PERFORM public.pmg_record_command_audit(
    'applied'::public.pmg_command_status, 'apply_kpi_definition_create',
    'btpm_ui'::public.pmg_source_channel,
    _project_id, 'kpi_definition', v_new_id, NULL,
    _correlation_id, _idempotency_key,
    jsonb_build_object(
      'project_id', _project_id,
      'workspace_id', v_project.workspace_id,
      'source_mode', coalesce(_source_mode, 'manual'),
      'value_type', coalesce(_value_type, 'number'),
      'cadence', coalesce(_cadence, 'manual_only'),
      'target_direction', coalesce(_target_direction, 'target_exact'::public.kpi_target_direction)::text,
      'has_target_value', (_target_value IS NOT NULL),
      'description_set', (v_desc IS NOT NULL),
      'unit_set', (v_unit IS NOT NULL),
      'calculation_key_set', (_calculation_key IS NOT NULL),
      'formula_version', _formula_version,
      'completion_method', _completion_method,
      'comment_required', coalesce(_comment_required, false),
      'action_plan_required', coalesce(_action_plan_required, false),
      'auto_snapshot_enabled', coalesce(_auto_snapshot_enabled, false)
    )
  );

  RETURN public.pmg_build_result(
    'applied'::public.pmg_command_status, 'apply_kpi_definition_create',
    'kpi_definition', v_new_id, _project_id,
    jsonb_build_object('id', v_new_id, 'kpi_definition_id', v_new_id),
    '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.apply_kpi_definition_update(_kpi_definition_id uuid, _expected_updated_at timestamp with time zone, _name text DEFAULT NULL::text, _description text DEFAULT NULL::text, _unit text DEFAULT NULL::text, _target_value numeric DEFAULT NULL::numeric, _target_direction kpi_target_direction DEFAULT NULL::kpi_target_direction, _source_mode text DEFAULT NULL::text, _value_type text DEFAULT NULL::text, _cadence text DEFAULT NULL::text, _calculation_key text DEFAULT NULL::text, _formula_version integer DEFAULT NULL::integer, _completion_method text DEFAULT NULL::text, _comment_required boolean DEFAULT NULL::boolean, _action_plan_required boolean DEFAULT NULL::boolean, _auto_snapshot_enabled boolean DEFAULT NULL::boolean, _set_name boolean DEFAULT false, _set_description boolean DEFAULT false, _set_unit boolean DEFAULT false, _set_target_value boolean DEFAULT false, _set_target_direction boolean DEFAULT false, _set_source_mode boolean DEFAULT false, _set_value_type boolean DEFAULT false, _set_cadence boolean DEFAULT false, _set_calculation_key boolean DEFAULT false, _set_formula_version boolean DEFAULT false, _set_completion_method boolean DEFAULT false, _set_comment_required boolean DEFAULT false, _set_action_plan_required boolean DEFAULT false, _set_auto_snapshot_enabled boolean DEFAULT false, _correlation_id text DEFAULT NULL::text, _idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_row record;
  v_project_id uuid;
  v_project record;

  n_name text;
  n_description text;
  n_unit text;
  n_calculation_key text;
  n_completion_method text;

  c_description text;

  v_changes jsonb := '{}'::jsonb;
  v_change_count int := 0;
  v_data jsonb;
BEGIN
  IF v_actor IS NULL OR NOT public.is_active_user(v_actor) THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'apply_kpi_definition_update',
      'kpi_definition', _kpi_definition_id, NULL,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF _expected_updated_at IS NULL THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'apply_kpi_definition_update',
      'kpi_definition', _kpi_definition_id, NULL,
      jsonb_build_object('reason','expected_updated_at_required'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  SELECT *
    INTO v_row
    FROM public.kpi_definitions
   WHERE id = _kpi_definition_id
   FOR UPDATE;

  IF v_row.id IS NULL THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'apply_kpi_definition_update',
      'kpi_definition', _kpi_definition_id, NULL,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  -- Only project-targeted KPIs are supported by current UI. Any other level
  -- returns non-leaking not_authorized.
  IF v_row.target_type IS DISTINCT FROM 'project' OR v_row.target_id IS NULL THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'apply_kpi_definition_update',
      'kpi_definition', _kpi_definition_id, NULL,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  v_project_id := v_row.target_id;

  SELECT id, organization_id, workspace_id
    INTO v_project
    FROM public.projects
   WHERE id = v_project_id;

  IF v_project.id IS NULL THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'apply_kpi_definition_update',
      'kpi_definition', _kpi_definition_id, v_project_id,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF NOT public.has_project_pm_authority(v_actor, v_project_id)
     OR NOT public.can_write_demo(v_actor, v_project.workspace_id) THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'apply_kpi_definition_update',
      'kpi_definition', _kpi_definition_id, v_project_id,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF v_row.updated_at IS DISTINCT FROM _expected_updated_at THEN
    PERFORM public.pmg_record_command_audit(
      'conflict'::public.pmg_command_status, 'apply_kpi_definition_update',
      'btpm_ui'::public.pmg_source_channel,
      v_project_id, 'kpi_definition', _kpi_definition_id, NULL,
      _correlation_id, _idempotency_key,
      jsonb_build_object('stale', true)
    );
    RETURN public.pmg_build_result(
      'conflict'::public.pmg_command_status, 'apply_kpi_definition_update',
      'kpi_definition', _kpi_definition_id, v_project_id,
      jsonb_build_object(
        'code','stale_kpi_definition',
        'current_updated_at', v_row.updated_at
      ),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  -- Normalize text fields.
  n_name              := CASE WHEN _set_name              THEN NULLIF(btrim(_name), '') ELSE NULL END;
  n_description       := CASE WHEN _set_description       THEN NULLIF(btrim(coalesce(_description, '')), '') ELSE NULL END;
  n_unit              := CASE WHEN _set_unit              THEN NULLIF(btrim(coalesce(_unit, '')), '') ELSE NULL END;
  n_calculation_key   := CASE WHEN _set_calculation_key   THEN NULLIF(btrim(coalesce(_calculation_key, '')), '') ELSE NULL END;
  n_completion_method := CASE WHEN _set_completion_method THEN NULLIF(btrim(coalesce(_completion_method, '')), '') ELSE NULL END;

  IF _set_name AND n_name IS NULL THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'apply_kpi_definition_update',
      'kpi_definition', _kpi_definition_id, v_project_id,
      jsonb_build_object('reason','name_required'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  -- Non-nullable enum-like text fields cannot be cleared to blank.
  IF (_set_source_mode AND (_source_mode IS NULL OR btrim(_source_mode) = ''))
     OR (_set_value_type AND (_value_type IS NULL OR btrim(_value_type) = ''))
     OR (_set_cadence    AND (_cadence    IS NULL OR btrim(_cadence)    = '')) THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'apply_kpi_definition_update',
      'kpi_definition', _kpi_definition_id, v_project_id,
      jsonb_build_object('reason','required_field_blank'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF _set_target_direction AND _target_direction IS NULL THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'apply_kpi_definition_update',
      'kpi_definition', _kpi_definition_id, v_project_id,
      jsonb_build_object('reason','target_direction_required'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  -- Decrypt current description plaintext for comparison.
  c_description := public.btpm_decrypt(v_row.description, v_row.organization_id);

  IF _set_name                 AND n_name                 IS DISTINCT FROM v_row.name                 THEN v_changes := v_changes || jsonb_build_object('name', true);                 v_change_count := v_change_count + 1; END IF;
  IF _set_description          AND n_description          IS DISTINCT FROM c_description              THEN v_changes := v_changes || jsonb_build_object('description', true);          v_change_count := v_change_count + 1; END IF;
  IF _set_unit                 AND n_unit                 IS DISTINCT FROM v_row.unit                 THEN v_changes := v_changes || jsonb_build_object('unit', true);                 v_change_count := v_change_count + 1; END IF;
  IF _set_target_value         AND _target_value          IS DISTINCT FROM v_row.target_value         THEN v_changes := v_changes || jsonb_build_object('target_value', true);         v_change_count := v_change_count + 1; END IF;
  IF _set_target_direction     AND _target_direction      IS DISTINCT FROM v_row.target_direction     THEN v_changes := v_changes || jsonb_build_object('target_direction', true);     v_change_count := v_change_count + 1; END IF;
  IF _set_source_mode          AND _source_mode           IS DISTINCT FROM v_row.source_mode          THEN v_changes := v_changes || jsonb_build_object('source_mode', true);          v_change_count := v_change_count + 1; END IF;
  IF _set_value_type           AND _value_type            IS DISTINCT FROM v_row.value_type           THEN v_changes := v_changes || jsonb_build_object('value_type', true);           v_change_count := v_change_count + 1; END IF;
  IF _set_cadence              AND _cadence               IS DISTINCT FROM v_row.cadence              THEN v_changes := v_changes || jsonb_build_object('cadence', true);              v_change_count := v_change_count + 1; END IF;
  IF _set_calculation_key      AND n_calculation_key      IS DISTINCT FROM v_row.calculation_key      THEN v_changes := v_changes || jsonb_build_object('calculation_key', true);      v_change_count := v_change_count + 1; END IF;
  IF _set_formula_version      AND _formula_version       IS DISTINCT FROM v_row.formula_version      THEN v_changes := v_changes || jsonb_build_object('formula_version', true);      v_change_count := v_change_count + 1; END IF;
  IF _set_completion_method    AND n_completion_method    IS DISTINCT FROM v_row.completion_method    THEN v_changes := v_changes || jsonb_build_object('completion_method', true);    v_change_count := v_change_count + 1; END IF;
  IF _set_comment_required     AND _comment_required      IS DISTINCT FROM v_row.comment_required     THEN v_changes := v_changes || jsonb_build_object('comment_required', true);     v_change_count := v_change_count + 1; END IF;
  IF _set_action_plan_required AND _action_plan_required  IS DISTINCT FROM v_row.action_plan_required THEN v_changes := v_changes || jsonb_build_object('action_plan_required', true); v_change_count := v_change_count + 1; END IF;
  IF _set_auto_snapshot_enabled AND _auto_snapshot_enabled IS DISTINCT FROM v_row.auto_snapshot_enabled THEN v_changes := v_changes || jsonb_build_object('auto_snapshot_enabled', true); v_change_count := v_change_count + 1; END IF;

  IF v_change_count = 0 THEN
    v_data := jsonb_build_object('id', v_row.id, 'updated_at', v_row.updated_at);
    PERFORM public.pmg_record_command_audit(
      'no_change'::public.pmg_command_status, 'apply_kpi_definition_update',
      'btpm_ui'::public.pmg_source_channel,
      v_project_id, 'kpi_definition', _kpi_definition_id, NULL,
      _correlation_id, _idempotency_key,
      jsonb_build_object('changed_fields', v_changes, 'change_count', 0, 'stale', false)
    );
    RETURN public.pmg_build_result(
      'no_change'::public.pmg_command_status, 'apply_kpi_definition_update',
      'kpi_definition', _kpi_definition_id, v_project_id,
      v_data, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  BEGIN
    UPDATE public.kpi_definitions
       SET name                  = CASE WHEN _set_name                  THEN n_name                  ELSE name                  END,
           description           = CASE WHEN _set_description           THEN n_description           ELSE description           END,
           unit                  = CASE WHEN _set_unit                  THEN n_unit                  ELSE unit                  END,
           target_value          = CASE WHEN _set_target_value          THEN _target_value           ELSE target_value          END,
           target_direction      = CASE WHEN _set_target_direction      THEN _target_direction       ELSE target_direction      END,
           source_mode           = CASE WHEN _set_source_mode           THEN _source_mode            ELSE source_mode           END,
           value_type            = CASE WHEN _set_value_type            THEN _value_type             ELSE value_type            END,
           cadence               = CASE WHEN _set_cadence               THEN _cadence                ELSE cadence               END,
           calculation_key       = CASE WHEN _set_calculation_key       THEN n_calculation_key       ELSE calculation_key       END,
           formula_version       = CASE WHEN _set_formula_version       THEN _formula_version        ELSE formula_version       END,
           completion_method     = CASE WHEN _set_completion_method     THEN n_completion_method     ELSE completion_method     END,
           comment_required      = CASE WHEN _set_comment_required      THEN _comment_required       ELSE comment_required      END,
           action_plan_required  = CASE WHEN _set_action_plan_required  THEN _action_plan_required   ELSE action_plan_required  END,
           auto_snapshot_enabled = CASE WHEN _set_auto_snapshot_enabled THEN _auto_snapshot_enabled  ELSE auto_snapshot_enabled END
     WHERE id = _kpi_definition_id
     RETURNING updated_at INTO v_row.updated_at;
  EXCEPTION
    WHEN check_violation OR raise_exception OR not_null_violation OR invalid_text_representation OR foreign_key_violation THEN
      RETURN public.pmg_build_result(
        'invalid'::public.pmg_command_status, 'apply_kpi_definition_update',
        'kpi_definition', _kpi_definition_id, v_project_id,
        jsonb_build_object('reason', SQLERRM),
        '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
      );
  END;

  v_data := jsonb_build_object('id', _kpi_definition_id, 'updated_at', v_row.updated_at);

  PERFORM public.pmg_record_command_audit(
    'applied'::public.pmg_command_status, 'apply_kpi_definition_update',
    'btpm_ui'::public.pmg_source_channel,
    v_project_id, 'kpi_definition', _kpi_definition_id, NULL,
    _correlation_id, _idempotency_key,
    jsonb_build_object('changed_fields', v_changes, 'change_count', v_change_count, 'stale', false)
  );

  RETURN public.pmg_build_result(
    'applied'::public.pmg_command_status, 'apply_kpi_definition_update',
    'kpi_definition', _kpi_definition_id, v_project_id,
    v_data, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.apply_phase_planning_change(_phase_id uuid, _new_start date, _new_end date, _confirm_parent_extension boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  ph record;
  pr record;
  needs_ext boolean := false;
  prop_start date;
  prop_end   date;
BEGIN
  SELECT id, project_id, workspace_id, organization_id, status, is_archived,
         start_date, target_end_date, name
    INTO ph
    FROM public.phases
   WHERE id = _phase_id;

  IF ph.id IS NULL THEN
    RAISE EXCEPTION 'apply_phase_planning_change: phase not found';
  END IF;

  IF NOT public.is_workspace_admin_or_higher(auth.uid(), ph.workspace_id) THEN
    RAISE EXCEPTION 'apply_phase_planning_change: not authorized';
  END IF;

  IF ph.status = 'completed' THEN
    RAISE EXCEPTION 'apply_phase_planning_change: phase is completed and locked. Reopen first.';
  END IF;
  IF ph.status = 'cancelled' OR ph.is_archived THEN
    RAISE EXCEPTION 'apply_phase_planning_change: phase is cancelled/archived';
  END IF;

  IF _new_start IS NOT NULL AND _new_end IS NOT NULL AND _new_end < _new_start THEN
    RAISE EXCEPTION 'apply_phase_planning_change: end date must be on or after start date';
  END IF;

  SELECT id, name, start_date, target_end_date
    INTO pr
    FROM public.projects
   WHERE id = ph.project_id;

  prop_start := pr.start_date;
  prop_end   := pr.target_end_date;

  IF _new_start IS NOT NULL AND pr.start_date IS NOT NULL AND _new_start < pr.start_date THEN
    needs_ext := true; prop_start := _new_start;
  END IF;
  IF _new_end IS NOT NULL AND pr.target_end_date IS NOT NULL AND _new_end > pr.target_end_date THEN
    needs_ext := true; prop_end := _new_end;
  END IF;

  IF needs_ext AND NOT _confirm_parent_extension THEN
    RAISE EXCEPTION 'apply_phase_planning_change: parent extension required but not confirmed'
      USING ERRCODE = 'check_violation';
  END IF;

  IF needs_ext THEN
    PERFORM set_config('app.allow_planned_extension', 'on', true);

    PERFORM public._apply_project_extension_internal(pr.id, prop_start, prop_end, _phase_id, 'phase');

    UPDATE public.phases
       SET start_date = _new_start,
           target_end_date = _new_end
     WHERE id = _phase_id;

    PERFORM set_config('app.allow_planned_extension', 'off', true);
  ELSE
    UPDATE public.phases
       SET start_date = _new_start,
           target_end_date = _new_end
     WHERE id = _phase_id;
  END IF;

  RETURN _phase_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.apply_phase_timeline_action(_phase_id uuid, _action text, _new_start date, _new_end date, _confirm_project_extension boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_preview        jsonb;
  v_phase          public.phases%ROWTYPE;
  v_project        public.projects%ROWTYPE;
  v_uid            uuid := auth.uid();
  v_resolved       text;
  v_delta_days     int;
  v_proposed_start date;
  v_proposed_end   date;
  v_proj_propose_s date;
  v_proj_propose_e date;
  v_proj_ext_req   boolean;
  v_event_type     text;
  v_moved_count    int := 0;
  v_anchored_count int := 0;
  v_old_start      date;
  v_old_end        date;
  v_org_id         uuid;
  v_ws_id          uuid;
  r_task           record;
  v_conflict       record;
BEGIN
  v_preview := public.preview_phase_timeline_action(_phase_id, _action, _new_start, _new_end);

  IF (v_preview ->> 'blocked')::boolean THEN
    RAISE EXCEPTION 'BTPM_GANTT_BLOCKED: %', (v_preview ->> 'blocked_reason');
  END IF;

  v_resolved       := v_preview ->> 'resolved_action';
  v_proposed_start := (v_preview ->> 'phase_proposed_start')::date;
  v_proposed_end   := (v_preview ->> 'phase_proposed_end')::date;
  v_proj_propose_s := (v_preview ->> 'parent_proposed_start')::date;
  v_proj_propose_e := (v_preview ->> 'parent_proposed_end')::date;
  v_proj_ext_req   := (v_preview ->> 'requires_project_extension')::boolean;
  v_delta_days     := (v_preview ->> 'delta_days')::int;
  v_anchored_count := COALESCE((v_preview ->> 'anchored_children_count')::int, 0);

  IF v_proj_ext_req AND NOT _confirm_project_extension THEN
    RAISE EXCEPTION 'BTPM_GANTT_NEEDS_PROJECT_EXT: project extension confirmation required'
      USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO v_phase   FROM public.phases   WHERE id = _phase_id;
  SELECT * INTO v_project FROM public.projects WHERE id = v_phase.project_id;
  v_old_start := v_phase.start_date;
  v_old_end   := v_phase.target_end_date;
  v_org_id    := v_phase.organization_id;
  v_ws_id     := v_phase.workspace_id;

  PERFORM set_config('app.allow_planned_extension', 'on', true);

  IF v_proj_ext_req THEN
    PERFORM public._apply_project_extension_internal(
      v_project.id, v_proj_propose_s, v_proj_propose_e,
      'phase', v_phase.id
    );
  END IF;

  -- Update the phase planned window. Phase-level dep trigger still applies.
  UPDATE public.phases
     SET start_date = v_proposed_start,
         target_end_date = v_proposed_end
   WHERE id = _phase_id;

  -- Coordinated children shift: bypass per-row task dep trigger; we
  -- re-validate every shifted task explicitly after the statement.
  IF v_resolved IN ('move_phase_plan','shift_remaining_work') AND v_delta_days <> 0 THEN
    PERFORM set_config('app.allow_coordinated_shift', 'on', true);

    WITH upd AS (
      UPDATE public.tasks
         SET start_date = start_date + v_delta_days,
             due_date   = due_date   + v_delta_days
       WHERE phase_id = _phase_id
         AND is_archived = false
         AND status <> 'cancelled'
         AND status <> 'completed'
         AND actual_start_date IS NULL
         AND actual_end_date IS NULL
         AND start_date IS NOT NULL
         AND due_date   IS NOT NULL
       RETURNING id, name, start_date, due_date
    )
    SELECT COUNT(*) INTO v_moved_count FROM upd;

    PERFORM set_config('app.allow_coordinated_shift', 'off', true);

    -- Post-shift validation: every shifted task must still satisfy its
    -- dependencies (covers cross-phase / cross-project task deps).
    FOR r_task IN
      SELECT id, name, start_date, due_date
        FROM public.tasks
       WHERE phase_id = _phase_id
         AND is_archived = false
         AND status <> 'cancelled'
         AND status <> 'completed'
         AND actual_start_date IS NULL
         AND actual_end_date IS NULL
         AND start_date IS NOT NULL
         AND due_date   IS NOT NULL
    LOOP
      SELECT * INTO v_conflict
      FROM public.btpm_check_entity_schedule('task', r_task.id, r_task.start_date, r_task.due_date)
      LIMIT 1;

      IF v_conflict.side = 'successor' THEN
        RAISE EXCEPTION
          'BTPM_DEP_CONFLICT_SUCC: cannot move "%": predecessor "%" must finish (ends %) on or before this item starts (would be %)',
          r_task.name, v_conflict.other_name, v_conflict.other_end, r_task.start_date
          USING ERRCODE = 'check_violation';
      ELSIF v_conflict.side = 'predecessor' THEN
        RAISE EXCEPTION
          'BTPM_DEP_CONFLICT_PRED: cannot move "%": successor "%" starts % which is before this item would finish (%)',
          r_task.name, v_conflict.other_name, v_conflict.other_start, r_task.due_date
          USING ERRCODE = 'check_violation';
      END IF;
    END LOOP;

    v_event_type := CASE WHEN v_resolved = 'shift_remaining_work'
                         THEN 'phase_remaining_work_shifted'
                         ELSE 'phase_plan_moved' END;
  ELSE
    v_event_type := CASE WHEN v_resolved = 'resize_phase' THEN 'phase_resized'
                         ELSE 'phase_plan_moved' END;
  END IF;

  INSERT INTO public.activity_events
    (organization_id, workspace_id, actor_id, event_type, target_type, target_id, metadata)
  VALUES
    (v_org_id, v_ws_id, v_uid, v_event_type, 'phase', v_phase.id,
     jsonb_build_object(
       'action', _action,
       'resolved_action', v_resolved,
       'old_start', v_old_start,
       'old_end',   v_old_end,
       'new_start', v_proposed_start,
       'new_end',   v_proposed_end,
       'delta_days', v_delta_days,
       'moved_children_count', v_moved_count,
       'anchored_children_count', v_anchored_count,
       'project_extended', v_proj_ext_req
     )::text);

  RETURN jsonb_build_object(
    'ok', true,
    'resolved_action', v_resolved,
    'delta_days', v_delta_days,
    'moved_children_count', v_moved_count,
    'anchored_children_count', v_anchored_count,
    'project_extended', v_proj_ext_req
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.apply_phase_update(_phase_id uuid, _expected_updated_at timestamp with time zone, _name text, _description text DEFAULT NULL::text, _status pm_status DEFAULT NULL::pm_status, _phase_type phase_type DEFAULT NULL::phase_type, _correlation_id text DEFAULT NULL::text, _idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_phase record;
  v_project_id uuid;
  v_workspace_id uuid;
  v_current_description text;
  v_name text;
  v_description text;
  v_new_status public.pm_status;
  v_new_phase_type public.phase_type;
  v_name_changed boolean;
  v_description_changed boolean;
  v_status_changed boolean;
  v_phase_type_changed boolean;
  v_changed_count int;
  v_updated record;
  v_updated_description text;
  v_data jsonb;
BEGIN
  IF v_actor IS NULL THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'apply_phase_update',
      'phase', _phase_id, NULL,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF NOT public.is_active_user(v_actor) THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'apply_phase_update',
      'phase', _phase_id, NULL,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF _expected_updated_at IS NULL THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'apply_phase_update',
      'phase', _phase_id, NULL,
      jsonb_build_object('reason','expected_updated_at_required'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  -- Lock the Phase row and derive Project id + workspace + organization for decrypt.
  SELECT id, project_id, workspace_id, organization_id, name, description, status, phase_type, updated_at
    INTO v_phase
    FROM public.phases
   WHERE id = _phase_id
   FOR UPDATE;

  IF v_phase.id IS NULL THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'apply_phase_update',
      'phase', _phase_id, NULL,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  v_project_id := v_phase.project_id;
  v_workspace_id := v_phase.workspace_id;

  IF NOT public.has_project_pm_authority(v_actor, v_project_id)
     OR NOT public.can_write_demo(v_actor, v_workspace_id) THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'apply_phase_update',
      'phase', _phase_id, v_project_id,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF v_phase.updated_at IS DISTINCT FROM _expected_updated_at THEN
    PERFORM public.pmg_record_command_audit(
      'conflict'::public.pmg_command_status, 'apply_phase_update',
      'btpm_ui'::public.pmg_source_channel,
      v_project_id, 'phase', _phase_id, NULL,
      _correlation_id, _idempotency_key,
      jsonb_build_object('stale', true)
    );
    RETURN public.pmg_build_result(
      'conflict'::public.pmg_command_status, 'apply_phase_update',
      'phase', _phase_id, v_project_id,
      jsonb_build_object(
        'code', 'stale_phase',
        'current_updated_at', v_phase.updated_at
      ),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  -- Canonical current plaintext values.
  IF v_phase.description IS NULL THEN
    v_current_description := NULL;
  ELSE
    v_current_description := public.btpm_decrypt(v_phase.description, v_phase.organization_id);
  END IF;

  v_name := btrim(COALESCE(_name, ''));
  IF v_name = '' THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'apply_phase_update',
      'phase', _phase_id, v_project_id,
      jsonb_build_object('reason','name_blank'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF _description IS NULL THEN
    v_description := NULL;
  ELSE
    v_description := btrim(_description);
    IF v_description = '' THEN
      v_description := NULL;
    END IF;
  END IF;

  v_new_status := COALESCE(_status, v_phase.status);
  v_new_phase_type := COALESCE(_phase_type, v_phase.phase_type);

  v_name_changed := v_name IS DISTINCT FROM v_phase.name;
  v_description_changed := v_description IS DISTINCT FROM v_current_description;
  v_status_changed := v_new_status IS DISTINCT FROM v_phase.status;
  v_phase_type_changed := v_new_phase_type IS DISTINCT FROM v_phase.phase_type;

  v_changed_count :=
    (CASE WHEN v_name_changed THEN 1 ELSE 0 END)
    + (CASE WHEN v_description_changed THEN 1 ELSE 0 END)
    + (CASE WHEN v_status_changed THEN 1 ELSE 0 END)
    + (CASE WHEN v_phase_type_changed THEN 1 ELSE 0 END);

  IF v_changed_count = 0 THEN
    v_data := jsonb_build_object(
      'id', v_phase.id,
      'project_id', v_project_id,
      'name', v_phase.name,
      'description', v_current_description,
      'status', v_phase.status,
      'phase_type', v_phase.phase_type,
      'updated_at', v_phase.updated_at
    );

    PERFORM public.pmg_record_command_audit(
      'no_change'::public.pmg_command_status, 'apply_phase_update',
      'btpm_ui'::public.pmg_source_channel,
      v_project_id, 'phase', _phase_id, NULL,
      _correlation_id, _idempotency_key,
      jsonb_build_object(
        'changed_field_count', 0,
        'name_changed', false,
        'description_changed', false,
        'status_changed', false,
        'phase_type_changed', false,
        'stale', false
      )
    );

    RETURN public.pmg_build_result(
      'no_change'::public.pmg_command_status, 'apply_phase_update',
      'phase', _phase_id, v_project_id,
      v_data, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  UPDATE public.phases
     SET name = v_name,
         description = v_description,
         status = v_new_status,
         phase_type = v_new_phase_type
   WHERE id = _phase_id;

  SELECT id, project_id, organization_id, name, description, status, phase_type, updated_at
    INTO v_updated
    FROM public.phases
   WHERE id = _phase_id;

  IF v_updated.description IS NULL THEN
    v_updated_description := NULL;
  ELSE
    v_updated_description := public.btpm_decrypt(v_updated.description, v_updated.organization_id);
  END IF;

  v_data := jsonb_build_object(
    'id', v_updated.id,
    'project_id', v_updated.project_id,
    'name', v_updated.name,
    'description', v_updated_description,
    'status', v_updated.status,
    'phase_type', v_updated.phase_type,
    'updated_at', v_updated.updated_at
  );

  PERFORM public.pmg_record_command_audit(
    'applied'::public.pmg_command_status, 'apply_phase_update',
    'btpm_ui'::public.pmg_source_channel,
    v_project_id, 'phase', _phase_id, NULL,
    _correlation_id, _idempotency_key,
    jsonb_build_object(
      'changed_field_count', v_changed_count,
      'name_changed', v_name_changed,
      'description_changed', v_description_changed,
      'status_changed', v_status_changed,
      'phase_type_changed', v_phase_type_changed,
      'stale', false
    )
  );

  RETURN public.pmg_build_result(
    'applied'::public.pmg_command_status, 'apply_phase_update',
    'phase', _phase_id, v_project_id,
    v_data, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.apply_program_create(_name text, _workspace_id uuid, _description text DEFAULT NULL::text, _correlation_id text DEFAULT NULL::text, _idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_name text;
  v_desc text;
  v_org uuid;
  v_new_id uuid;
BEGIN
  IF v_actor IS NULL OR NOT public.is_active_user(v_actor) THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'apply_program_create',
      'program', NULL, NULL,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  v_name := btrim(coalesce(_name, ''));
  IF v_name = '' THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'apply_program_create',
      'program', NULL, NULL,
      jsonb_build_object('reason', 'Program name is required'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;
  IF char_length(v_name) > 200 THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'apply_program_create',
      'program', NULL, NULL,
      jsonb_build_object('reason', 'Program name must be 200 characters or less'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF _workspace_id IS NULL THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'apply_program_create',
      'program', NULL, NULL,
      jsonb_build_object('reason', 'Workspace is required'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  SELECT organization_id INTO v_org
  FROM public.workspaces
  WHERE id = _workspace_id;

  IF v_org IS NULL THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'apply_program_create',
      'program', NULL, NULL,
      jsonb_build_object('reason', 'Workspace not found'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF NOT public.has_pm_authority(v_actor, _workspace_id)
     OR v_org <> public.get_user_org_id(v_actor)
     OR NOT public.can_write_demo(v_actor, _workspace_id) THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'apply_program_create',
      'program', NULL, NULL,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  v_desc := nullif(btrim(coalesce(_description, '')), '');

  INSERT INTO public.programs (
    name, description, workspace_id, organization_id, created_by
  ) VALUES (
    v_name, v_desc, _workspace_id, v_org, v_actor
  )
  RETURNING id INTO v_new_id;

  PERFORM public.pmg_record_command_audit(
    'applied'::public.pmg_command_status, 'apply_program_create',
    'btpm_ui'::public.pmg_source_channel,
    NULL, 'program', v_new_id, NULL,
    _correlation_id, _idempotency_key,
    jsonb_build_object(
      'workspace_id', _workspace_id,
      'description_set', (v_desc IS NOT NULL)
    )
  );

  RETURN public.pmg_build_result(
    'applied'::public.pmg_command_status, 'apply_program_create',
    'program', v_new_id, NULL,
    jsonb_build_object('id', v_new_id, 'program_id', v_new_id),
    '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.apply_program_update(_program_id uuid, _expected_updated_at timestamp with time zone, _name text DEFAULT NULL::text, _status pm_status DEFAULT NULL::pm_status, _description text DEFAULT NULL::text, _set_description boolean DEFAULT false, _correlation_id text DEFAULT NULL::text, _idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_prog public.programs%ROWTYPE;
  v_new_name text;
  v_new_desc text;
  v_current_name text;
  v_current_desc text;
  v_change_name boolean := false;
  v_change_status boolean := false;
  v_change_desc boolean := false;
  v_changed_count int := 0;
BEGIN
  IF v_actor IS NULL OR NOT public.is_active_user(v_actor) THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'apply_program_update',
      'program', _program_id, NULL,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF _program_id IS NULL OR _expected_updated_at IS NULL THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'apply_program_update',
      'program', _program_id, NULL,
      jsonb_build_object('reason', 'program_id and expected_updated_at are required'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  SELECT * INTO v_prog FROM public.programs WHERE id = _program_id FOR UPDATE;

  IF NOT FOUND THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'apply_program_update',
      'program', _program_id, NULL,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF NOT public.has_pm_authority(v_actor, v_prog.workspace_id)
     OR v_prog.organization_id <> public.get_user_org_id(v_actor)
     OR NOT public.can_write_demo(v_actor, v_prog.workspace_id) THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'apply_program_update',
      'program', _program_id, NULL,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  -- Preserve archive lock. Archive/unarchive remain owned by dedicated
  -- lifecycle RPCs (archive_program / unarchive_program). No completed-status
  -- lock: Programs have no completion command and the prior update path did
  -- not treat completed as read-only.
  IF v_prog.is_archived THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'apply_program_update',
      'program', _program_id, NULL,
      jsonb_build_object('reason', 'Program is archived and cannot be edited'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF v_prog.updated_at IS DISTINCT FROM _expected_updated_at THEN
    PERFORM public.pmg_record_command_audit(
      'conflict'::public.pmg_command_status, 'apply_program_update',
      'btpm_ui'::public.pmg_source_channel,
      NULL, 'program', _program_id, NULL,
      _correlation_id, _idempotency_key,
      jsonb_build_object('reason', 'stale_program')
    );
    RETURN public.pmg_build_result(
      'conflict'::public.pmg_command_status, 'apply_program_update',
      'program', _program_id, NULL,
      jsonb_build_object(
        'reason', 'stale_program',
        'current_updated_at', v_prog.updated_at
      ),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb,
      jsonb_build_object('current_updated_at', v_prog.updated_at)
    );
  END IF;

  IF _name IS NOT NULL THEN
    v_new_name := btrim(_name);
    IF v_new_name = '' THEN
      RETURN public.pmg_build_result(
        'invalid'::public.pmg_command_status, 'apply_program_update',
        'program', _program_id, NULL,
        jsonb_build_object('reason', 'Program name is required'),
        '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
      );
    END IF;
    IF char_length(v_new_name) > 200 THEN
      RETURN public.pmg_build_result(
        'invalid'::public.pmg_command_status, 'apply_program_update',
        'program', _program_id, NULL,
        jsonb_build_object('reason', 'Program name must be 200 characters or less'),
        '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
      );
    END IF;
  END IF;

  IF _set_description THEN
    v_new_desc := nullif(btrim(coalesce(_description, '')), '');
  END IF;

  v_current_name := public.btpm_decrypt(v_prog.name, v_prog.organization_id);
  v_current_desc := public.btpm_decrypt(v_prog.description, v_prog.organization_id);

  IF _name IS NOT NULL AND v_new_name IS DISTINCT FROM v_current_name THEN
    v_change_name := true;
    v_changed_count := v_changed_count + 1;
  END IF;
  IF _status IS NOT NULL AND _status <> v_prog.status THEN
    v_change_status := true;
    v_changed_count := v_changed_count + 1;
  END IF;
  IF _set_description AND v_new_desc IS DISTINCT FROM v_current_desc THEN
    v_change_desc := true;
    v_changed_count := v_changed_count + 1;
  END IF;

  IF v_changed_count = 0 THEN
    PERFORM public.pmg_record_command_audit(
      'no_change'::public.pmg_command_status, 'apply_program_update',
      'btpm_ui'::public.pmg_source_channel,
      NULL, 'program', _program_id, NULL,
      _correlation_id, _idempotency_key,
      jsonb_build_object('changed_field_count', 0)
    );
    RETURN public.pmg_build_result(
      'no_change'::public.pmg_command_status, 'apply_program_update',
      'program', _program_id, NULL,
      jsonb_build_object('updated_at', v_prog.updated_at),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  UPDATE public.programs SET
    name = CASE WHEN v_change_name THEN v_new_name ELSE name END,
    status = CASE WHEN v_change_status THEN _status ELSE status END,
    description = CASE WHEN v_change_desc THEN v_new_desc ELSE description END
  WHERE id = _program_id;

  SELECT updated_at INTO v_prog.updated_at FROM public.programs WHERE id = _program_id;

  PERFORM public.pmg_record_command_audit(
    'applied'::public.pmg_command_status, 'apply_program_update',
    'btpm_ui'::public.pmg_source_channel,
    NULL, 'program', _program_id, NULL,
    _correlation_id, _idempotency_key,
    jsonb_build_object(
      'changed_field_count', v_changed_count,
      'name_changed', v_change_name,
      'status_changed', v_change_status,
      'description_changed', v_change_desc
    )
  );

  RETURN public.pmg_build_result(
    'applied'::public.pmg_command_status, 'apply_program_update',
    'program', _program_id, NULL,
    jsonb_build_object(
      'program_id', _program_id,
      'updated_at', v_prog.updated_at,
      'changed_field_count', v_changed_count
    ),
    '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.apply_project_binding_validation(_binding_id uuid, _status text, _folder_item_id text, _resolved_site_id text, _resolved_site_web_url text, _resolved_library_id_or_drive_id text, _resolved_library_web_url text, _validation_code text, _validation_note text)
 RETURNS sharepoint_project_bindings
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _row public.sharepoint_project_bindings;
BEGIN
  IF _uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO _row FROM public.sharepoint_project_bindings WHERE id = _binding_id;
  IF _row.id IS NULL THEN
    RAISE EXCEPTION 'Binding not found' USING ERRCODE = 'P0002';
  END IF;

  IF NOT public.has_project_pm_authority(_uid, _row.project_id) THEN
    RAISE EXCEPTION 'Forbidden: project PM authority required' USING ERRCODE = '42501';
  END IF;

  IF _status NOT IN ('validated', 'invalid') THEN
    RAISE EXCEPTION 'Invalid status: %', _status USING ERRCODE = '22023';
  END IF;

  UPDATE public.sharepoint_project_bindings
  SET
    binding_status = _status::sharepoint_project_binding_status,
    folder_item_id = COALESCE(_folder_item_id, folder_item_id),
    resolved_site_id = COALESCE(_resolved_site_id, resolved_site_id),
    resolved_site_web_url = COALESCE(_resolved_site_web_url, resolved_site_web_url),
    resolved_library_id_or_drive_id = COALESCE(_resolved_library_id_or_drive_id, resolved_library_id_or_drive_id),
    resolved_library_web_url = COALESCE(_resolved_library_web_url, resolved_library_web_url),
    last_validated_at = now(),
    last_validation_code = _validation_code,
    last_validation_note = _validation_note,
    updated_at = now(),
    updated_by = _uid
  WHERE id = _binding_id
  RETURNING * INTO _row;

  RETURN _row;
END;
$function$

CREATE OR REPLACE FUNCTION public.apply_project_create_blank(_name text, _workspace_id uuid, _program_id uuid DEFAULT NULL::uuid, _delivery_model project_delivery_model DEFAULT NULL::project_delivery_model, _correlation_id text DEFAULT NULL::text, _idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_ws_id uuid;
  v_new_id uuid;
  v_msg text;
  v_state text;
  v_data jsonb;
BEGIN
  -- Pre-flight identity guard (does not replace delegate's own checks).
  IF v_actor IS NULL OR NOT public.is_active_user(v_actor) THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'apply_project_create_blank',
      'project', NULL, NULL,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  -- Server-verify the workspace exists (do not trust caller beyond the id).
  -- If the workspace does not exist, fall through so the delegate returns
  -- the canonical 'Workspace not found' invalid envelope.
  SELECT id INTO v_ws_id
    FROM public.workspaces
   WHERE id = _workspace_id;

  IF v_ws_id IS NOT NULL AND NOT public.can_write_demo(v_actor, v_ws_id) THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'apply_project_create_blank',
      'project', NULL, NULL,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  BEGIN
    -- Delegate to the canonical implementation. All authority, containment,
    -- validation, encryption, sort/order defaults, and triggers run here.
    v_new_id := public.create_blank_project(
      _name          := _name,
      _workspace_id  := _workspace_id,
      _program_id    := _program_id,
      _delivery_model := _delivery_model
    );
  EXCEPTION
    WHEN insufficient_privilege THEN
      RETURN public.pmg_build_result(
        'not_authorized'::public.pmg_command_status, 'apply_project_create_blank',
        'project', NULL, NULL,
        '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
      );
    WHEN raise_exception THEN
      GET STACKED DIAGNOSTICS
        v_msg = MESSAGE_TEXT,
        v_state = RETURNED_SQLSTATE;
      IF v_msg IN (
        'Project name is required',
        'Project name must be 200 characters or less',
        'Workspace not found',
        'Program must belong to the same workspace as the project'
      ) THEN
        RETURN public.pmg_build_result(
          'invalid'::public.pmg_command_status, 'apply_project_create_blank',
          'project', NULL, NULL,
          jsonb_build_object('reason', v_msg),
          '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
        );
      END IF;
      RAISE;
  END;

  IF v_new_id IS NULL THEN
    RAISE EXCEPTION 'apply_project_create_blank: delegate returned NULL id';
  END IF;

  v_data := jsonb_build_object('id', v_new_id, 'project_id', v_new_id);

  PERFORM public.pmg_record_command_audit(
    'applied'::public.pmg_command_status, 'apply_project_create_blank',
    'btpm_ui'::public.pmg_source_channel,
    v_new_id, 'project', v_new_id, NULL,
    _correlation_id, _idempotency_key,
    jsonb_build_object(
      'workspace_id', _workspace_id,
      'program_set', (_program_id IS NOT NULL),
      'delivery_model_set', (_delivery_model IS NOT NULL)
    )
  );

  RETURN public.pmg_build_result(
    'applied'::public.pmg_command_status, 'apply_project_create_blank',
    'project', v_new_id, v_new_id,
    v_data, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.apply_project_people_preset(_preset_id uuid, _project_id uuid, _correlation_id text DEFAULT NULL::text, _idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor           uuid := auth.uid();
  v_preset          public.project_people_presets;
  v_project         record;
  v_prior_meta      jsonb;
  v_items_out       jsonb := '[]'::jsonb;
  v_warnings        jsonb := '[]'::jsonb;
  v_added_team      int := 0;
  v_added_stake     int := 0;
  v_skipped_exist   int := 0;
  v_skipped_inel    int := 0;
  v_total           int := 0;
  v_new_ptm_id      uuid;
  v_new_sk_id       uuid;
  v_display         text;
  r                 record;
  v_role_norm       text;
  v_canonical_norm  text;
  v_classification  text;
  v_reason          text;
BEGIN
  -- 1. Authenticated / active
  IF v_actor IS NULL OR NOT public.is_active_user(v_actor) THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'apply_project_people_preset',
      'project_people_preset', _preset_id, _project_id,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL);
  END IF;

  -- 2. Transaction-scoped advisory lock: (actor, command, idempotency_key)
  --    prevents concurrent same-key double execution across sessions.
  IF _idempotency_key IS NOT NULL AND length(btrim(_idempotency_key)) > 0 THEN
    PERFORM pg_advisory_xact_lock(
      hashtextextended('apply_project_people_preset|' || v_actor::text || '|' || _idempotency_key, 0)
    );
  END IF;
  -- Also serialize concurrent applies of the same (preset, project) pair.
  PERFORM pg_advisory_xact_lock(
    hashtextextended('apply_project_people_preset|' || _preset_id::text || '|' || _project_id::text, 0)
  );

  -- 3. Idempotency replay
  IF _idempotency_key IS NOT NULL AND length(btrim(_idempotency_key)) > 0 THEN
    SELECT metadata INTO v_prior_meta
      FROM public.pmg_command_audit
     WHERE command = 'apply_project_people_preset'
       AND actor_id = v_actor
       AND idempotency_key = _idempotency_key
       AND status = 'applied'::public.pmg_command_status
     ORDER BY created_at DESC
     LIMIT 1;

    IF v_prior_meta IS NOT NULL THEN
      RETURN public.pmg_build_result(
        'no_change'::public.pmg_command_status, 'apply_project_people_preset',
        'project_people_preset', _preset_id, _project_id,
        jsonb_build_object(
          'preset_id',           _preset_id,
          'project_id',          _project_id,
          'reason',              'idempotent_replay',
          'added_team_members',  COALESCE((v_prior_meta->>'added_team_members')::int, 0),
          'added_stakeholders',  COALESCE((v_prior_meta->>'added_stakeholders')::int, 0),
          'skipped_existing',    COALESCE((v_prior_meta->>'skipped_existing')::int, 0),
          'skipped_ineligible',  COALESCE((v_prior_meta->>'skipped_ineligible')::int, 0),
          'total_members',       COALESCE((v_prior_meta->>'total_members')::int, 0),
          'item_results',        '[]'::jsonb
        ),
        '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL);
    END IF;
  END IF;

  -- 4. Resolve preset + project under SHARE lock. Both must resolve; refuse
  --    without leaking existence.
  SELECT * INTO v_preset FROM public.project_people_presets WHERE id = _preset_id FOR SHARE;
  IF v_preset.id IS NULL THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'apply_project_people_preset',
      'project_people_preset', _preset_id, _project_id,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL);
  END IF;

  SELECT id, workspace_id, organization_id
    INTO v_project FROM public.projects WHERE id = _project_id FOR SHARE;
  IF v_project.id IS NULL THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'apply_project_people_preset',
      'project_people_preset', _preset_id, _project_id,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL);
  END IF;

  -- 5. Authority: canonical Project PM (same helper the existing
  --    Team/Stakeholder single-row RPCs trust) + demo-workspace lock.
  IF NOT public.has_project_pm_authority(v_actor, _project_id)
     OR NOT public.can_write_demo(v_actor, v_project.workspace_id) THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'apply_project_people_preset',
      'project_people_preset', _preset_id, _project_id,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL);
  END IF;

  -- 6. Scope containment: same workspace AND same org.
  IF v_preset.workspace_id IS DISTINCT FROM v_project.workspace_id
     OR v_preset.organization_id IS DISTINCT FROM v_project.organization_id THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'apply_project_people_preset',
      'project_people_preset', _preset_id, _project_id,
      jsonb_build_object('reason','workspace_mismatch'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL);
  END IF;
  IF v_preset.scope_type <> 'workspace' THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'apply_project_people_preset',
      'project_people_preset', _preset_id, _project_id,
      jsonb_build_object('reason','invalid_scope'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL);
  END IF;
  IF v_preset.archived_at IS NOT NULL THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'apply_project_people_preset',
      'project_people_preset', _preset_id, _project_id,
      jsonb_build_object('reason','preset_archived'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL);
  END IF;

  -- 7. Lock preset member set for the duration.
  PERFORM 1 FROM public.project_people_preset_members
   WHERE preset_id = _preset_id FOR SHARE;

  SELECT COUNT(*)::int INTO v_total
    FROM public.project_people_preset_members WHERE preset_id = _preset_id;
  IF v_total = 0 THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'apply_project_people_preset',
      'project_people_preset', _preset_id, _project_id,
      jsonb_build_object('reason','empty_preset'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL);
  END IF;

  -- 8. Iterate members and apply. Any unexpected failure aborts the whole
  --    apply via the enclosing BEGIN/EXCEPTION (rolling back everything).
  BEGIN
    FOR r IN
      SELECT
        m.id                                                             AS member_id,
        m.member_kind, m.stakeholder_type, m.user_id, m.canonical_role_key,
        NULLIF(btrim(public.btpm_decrypt(m.role_label,    v_preset.organization_id)), '') AS role_label,
        NULLIF(btrim(public.btpm_decrypt(m.external_name, v_preset.organization_id)), '') AS external_name_plain
      FROM public.project_people_preset_members m
      WHERE m.preset_id = _preset_id
      ORDER BY m.member_kind, m.id
    LOOP
      v_classification := NULL;
      v_reason := NULL;
      v_role_norm := r.role_label;
      v_canonical_norm := NULLIF(btrim(COALESCE(r.canonical_role_key,'')),'');

      IF r.member_kind = 'team_member' THEN
        IF EXISTS (SELECT 1 FROM public.project_team_members ptm
                    WHERE ptm.project_id = _project_id AND ptm.user_id = r.user_id) THEN
          v_classification := 'already_exists';
          v_skipped_exist := v_skipped_exist + 1;
        ELSIF NOT public.is_active_user(r.user_id) THEN
          v_classification := 'inactive_user';
          v_skipped_inel := v_skipped_inel + 1;
        ELSIF NOT public.is_workspace_member(r.user_id, v_project.workspace_id) THEN
          v_classification := 'no_longer_workspace_member';
          v_skipped_inel := v_skipped_inel + 1;
        ELSE
          BEGIN
            INSERT INTO public.project_team_members (
              project_id, user_id, workspace_id, organization_id,
              role_label, canonical_role_key
            ) VALUES (
              _project_id, r.user_id, v_project.workspace_id, v_project.organization_id,
              v_role_norm, v_canonical_norm
            )
            RETURNING id INTO v_new_ptm_id;
            v_classification := 'will_add';
            v_added_team := v_added_team + 1;
          EXCEPTION
            WHEN unique_violation THEN
              -- Race with concurrent add — treat as skip/already-exists.
              v_classification := 'already_exists';
              v_skipped_exist := v_skipped_exist + 1;
          END;
        END IF;

      ELSIF r.member_kind = 'stakeholder' AND r.stakeholder_type = 'workspace_member' THEN
        IF EXISTS (SELECT 1 FROM public.project_stakeholders sk
                    WHERE sk.project_id = _project_id
                      AND sk.stakeholder_type = 'workspace_member'
                      AND sk.user_id = r.user_id
                      AND sk.removed_at IS NULL) THEN
          v_classification := 'already_exists';
          v_skipped_exist := v_skipped_exist + 1;
        ELSIF NOT public.is_active_user(r.user_id) THEN
          v_classification := 'inactive_user';
          v_skipped_inel := v_skipped_inel + 1;
        ELSIF NOT public.is_workspace_member(r.user_id, v_project.workspace_id) THEN
          v_classification := 'no_longer_workspace_member';
          v_skipped_inel := v_skipped_inel + 1;
        ELSIF EXISTS (SELECT 1 FROM public.project_stakeholders sk
                       WHERE sk.project_id = _project_id
                         AND sk.stakeholder_type = 'workspace_member'
                         AND sk.user_id = r.user_id
                         AND sk.removed_at IS NOT NULL) THEN
          v_classification := 'otherwise_ineligible';
          v_reason := 'previously_removed';
          v_skipped_inel := v_skipped_inel + 1;
        ELSE
          BEGIN
            INSERT INTO public.project_stakeholders (
              organization_id, workspace_id, project_id, stakeholder_type,
              user_id, external_name, role_label, notes, start_date, created_by
            ) VALUES (
              v_project.organization_id, v_project.workspace_id, _project_id, 'workspace_member',
              r.user_id, NULL, v_role_norm, NULL, NULL, v_actor
            )
            RETURNING id INTO v_new_sk_id;
            v_classification := 'will_add';
            v_added_stake := v_added_stake + 1;

            SELECT COALESCE(display_name, email, r.user_id::text) INTO v_display
              FROM public.profiles WHERE id = r.user_id;
            PERFORM public.log_activity_event(
              v_project.organization_id, v_actor, 'stakeholder_added', 'project', _project_id,
              jsonb_build_object(
                'stakeholder_id',   v_new_sk_id,
                'stakeholder_type', 'workspace_member',
                'display_name',     v_display,
                'role_label',       v_role_norm,
                'start_date',       NULL,
                'source',           'wpp_apply',
                'preset_id',        _preset_id
              ),
              v_project.workspace_id
            );
          EXCEPTION
            WHEN unique_violation THEN
              v_classification := 'already_exists';
              v_skipped_exist := v_skipped_exist + 1;
          END;
        END IF;

      ELSIF r.member_kind = 'stakeholder' AND r.stakeholder_type = 'external' THEN
        IF r.external_name_plain IS NULL THEN
          v_classification := 'invalid_external';
          v_skipped_inel := v_skipped_inel + 1;
        ELSIF EXISTS (
          SELECT 1 FROM public.project_stakeholders sk
          WHERE sk.project_id = _project_id
            AND sk.stakeholder_type = 'external'
            AND sk.removed_at IS NULL
            AND lower(btrim(sk.external_name)) = lower(r.external_name_plain)
        ) THEN
          v_classification := 'already_exists';
          v_skipped_exist := v_skipped_exist + 1;
        ELSE
          INSERT INTO public.project_stakeholders (
            organization_id, workspace_id, project_id, stakeholder_type,
            user_id, external_name, role_label, notes, start_date, created_by
          ) VALUES (
            v_project.organization_id, v_project.workspace_id, _project_id, 'external',
            NULL, r.external_name_plain, v_role_norm, NULL, NULL, v_actor
          )
          RETURNING id INTO v_new_sk_id;
          v_classification := 'will_add';
          v_added_stake := v_added_stake + 1;

          PERFORM public.log_activity_event(
            v_project.organization_id, v_actor, 'stakeholder_added', 'project', _project_id,
            jsonb_build_object(
              'stakeholder_id',   v_new_sk_id,
              'stakeholder_type', 'external',
              'display_name',     r.external_name_plain,
              'role_label',       v_role_norm,
              'start_date',       NULL,
              'source',           'wpp_apply',
              'preset_id',        _preset_id
            ),
            v_project.workspace_id
          );
        END IF;
      ELSE
        v_classification := 'otherwise_ineligible';
        v_reason := 'unknown_member_kind';
        v_skipped_inel := v_skipped_inel + 1;
      END IF;

      v_items_out := v_items_out || jsonb_build_array(jsonb_build_object(
        'member_id',      r.member_id,
        'member_kind',    r.member_kind,
        'stakeholder_type', r.stakeholder_type,
        'classification', v_classification,
        'reason',         v_reason
      ));
    END LOOP;
  EXCEPTION
    WHEN OTHERS THEN
      RETURN public.pmg_build_result(
        'invalid'::public.pmg_command_status, 'apply_project_people_preset',
        'project_people_preset', _preset_id, _project_id,
        jsonb_build_object('reason','apply_failed','detail', SQLERRM),
        '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL);
  END;

  -- 9. Aggregate PMG audit (exactly one row).
  PERFORM public._ppp_record_audit(
    CASE WHEN v_added_team + v_added_stake = 0
         THEN 'no_change'::public.pmg_command_status
         ELSE 'applied'::public.pmg_command_status END,
    'apply_project_people_preset',
    v_preset,
    'project_people_preset', _preset_id,
    _correlation_id, _idempotency_key,
    jsonb_build_object(
      'target_project_id',   _project_id,
      'added_team_members',  v_added_team,
      'added_stakeholders',  v_added_stake,
      'skipped_existing',    v_skipped_exist,
      'skipped_ineligible',  v_skipped_inel,
      'total_members',       v_total
    )
  );

  RETURN public.pmg_build_result(
    CASE WHEN v_added_team + v_added_stake = 0
         THEN 'no_change'::public.pmg_command_status
         ELSE 'applied'::public.pmg_command_status END,
    'apply_project_people_preset',
    'project_people_preset', _preset_id, _project_id,
    jsonb_build_object(
      'preset_id',           _preset_id,
      'project_id',          _project_id,
      'added_team_members',  v_added_team,
      'added_stakeholders',  v_added_stake,
      'skipped_existing',    v_skipped_exist,
      'skipped_ineligible',  v_skipped_inel,
      'total_members',       v_total,
      'item_results',        v_items_out
    ),
    '[]'::jsonb, v_warnings, '[]'::jsonb, NULL);
END; $function$

CREATE OR REPLACE FUNCTION public.apply_project_planning_change(_project_id uuid, _new_start date, _new_end date)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE pr record; bad record; old_start date; old_end date;
BEGIN
  SELECT id, organization_id, workspace_id, name, start_date, target_end_date
    INTO pr FROM public.projects WHERE id = _project_id;
  IF pr.id IS NULL THEN RAISE EXCEPTION 'apply_project_planning_change: project not found'; END IF;
  IF NOT public.has_project_pm_authority(auth.uid(), _project_id) THEN
    RAISE EXCEPTION 'apply_project_planning_change: not authorized'; END IF;
  IF _new_start IS NOT NULL AND _new_end IS NOT NULL AND _new_end < _new_start THEN
    RAISE EXCEPTION 'apply_project_planning_change: end date must be on or after start date'
      USING ERRCODE='check_violation'; END IF;
  IF _new_start IS NOT NULL THEN
    SELECT id, name, start_date AS d INTO bad FROM public.phases
     WHERE project_id = pr.id AND status <> 'cancelled' AND NOT is_archived
       AND start_date IS NOT NULL AND start_date < _new_start
     ORDER BY start_date ASC LIMIT 1;
    IF bad.id IS NOT NULL THEN
      RAISE EXCEPTION
        'BTPM_CONTAINMENT_PROJECT_SHRINK_START: cannot move project "%": child phase "%" starts %, before proposed start %.',
        pr.name, bad.name, bad.d, _new_start USING ERRCODE='check_violation'; END IF;
  END IF;
  IF _new_end IS NOT NULL THEN
    SELECT id, name, target_end_date AS d INTO bad FROM public.phases
     WHERE project_id = pr.id AND status <> 'cancelled' AND NOT is_archived
       AND target_end_date IS NOT NULL AND target_end_date > _new_end
     ORDER BY target_end_date DESC LIMIT 1;
    IF bad.id IS NOT NULL THEN
      RAISE EXCEPTION
        'BTPM_CONTAINMENT_PROJECT_SHRINK_END: cannot move project "%": child phase "%" ends %, after proposed end %.',
        pr.name, bad.name, bad.d, _new_end USING ERRCODE='check_violation'; END IF;
  END IF;
  old_start := pr.start_date; old_end := pr.target_end_date;
  UPDATE public.projects SET start_date = _new_start, target_end_date = _new_end WHERE id = _project_id;
  PERFORM public.log_activity_event(pr.organization_id, auth.uid(),
    'project_planning_window_changed', 'project', _project_id,
    jsonb_build_object('old_start', old_start, 'old_end', old_end,
      'new_start', _new_start, 'new_end', _new_end), pr.workspace_id);
END; $function$

CREATE OR REPLACE FUNCTION public.apply_project_status_transition(_project_id uuid, _expected_updated_at timestamp with time zone, _target_status pm_status, _confirm_warnings boolean DEFAULT false, _correlation_id text DEFAULT NULL::text, _idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_project record;
  v_old_status public.pm_status;
  v_validation jsonb;
  v_hard jsonb;
  v_warn jsonb;
  v_hard_count int;
  v_warn_count int;
  v_updated_at timestamptz;
  v_data jsonb;
BEGIN
  IF v_actor IS NULL THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'apply_project_status_transition',
      'project', _project_id, _project_id,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF NOT public.is_active_user(v_actor) THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'apply_project_status_transition',
      'project', _project_id, _project_id,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF _expected_updated_at IS NULL THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'apply_project_status_transition',
      'project', _project_id, _project_id,
      jsonb_build_object('reason','expected_updated_at_required'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF _target_status IS NULL THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'apply_project_status_transition',
      'project', _project_id, _project_id,
      jsonb_build_object('reason','target_status_required'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  SELECT id, status, updated_at, organization_id, workspace_id
    INTO v_project
    FROM public.projects
   WHERE id = _project_id
   FOR UPDATE;

  IF v_project.id IS NULL THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'apply_project_status_transition',
      'project', _project_id, _project_id,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF NOT public.has_project_pm_authority(v_actor, _project_id)
     OR NOT public.can_write_demo(v_actor, v_project.workspace_id) THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'apply_project_status_transition',
      'project', _project_id, _project_id,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF v_project.updated_at IS DISTINCT FROM _expected_updated_at THEN
    PERFORM public.pmg_record_command_audit(
      'conflict'::public.pmg_command_status, 'apply_project_status_transition',
      'btpm_ui'::public.pmg_source_channel,
      _project_id, 'project', _project_id, NULL,
      _correlation_id, _idempotency_key,
      jsonb_build_object('stale', true)
    );
    RETURN public.pmg_build_result(
      'conflict'::public.pmg_command_status, 'apply_project_status_transition',
      'project', _project_id, _project_id,
      jsonb_build_object(
        'code', 'stale_project',
        'current_updated_at', v_project.updated_at
      ),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  v_old_status := v_project.status;

  IF _target_status = v_old_status THEN
    v_data := jsonb_build_object(
      'id', v_project.id,
      'status', v_project.status,
      'updated_at', v_project.updated_at
    );
    PERFORM public.pmg_record_command_audit(
      'no_change'::public.pmg_command_status, 'apply_project_status_transition',
      'btpm_ui'::public.pmg_source_channel,
      _project_id, 'project', _project_id, NULL,
      _correlation_id, _idempotency_key,
      jsonb_build_object(
        'status_from', v_old_status::text,
        'status_to', _target_status::text,
        'confirmed', COALESCE(_confirm_warnings, false),
        'stale', false
      )
    );
    RETURN public.pmg_build_result(
      'no_change'::public.pmg_command_status, 'apply_project_status_transition',
      'project', _project_id, _project_id,
      v_data, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF v_old_status = 'completed' AND _target_status <> 'active' THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'apply_project_status_transition',
      'project', _project_id, _project_id,
      jsonb_build_object(
        'reason','transition_not_supported',
        'status_from', v_old_status::text,
        'status_to', _target_status::text
      ),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF _target_status = 'completed' AND v_old_status <> 'completed' THEN
    v_validation := public.validate_project_completion(_project_id);
    v_hard := COALESCE(v_validation->'hard_blocks', '[]'::jsonb);
    v_warn := COALESCE(v_validation->'warnings', '[]'::jsonb);
    v_hard_count := jsonb_array_length(v_hard);
    v_warn_count := jsonb_array_length(v_warn);

    IF v_hard_count > 0 THEN
      PERFORM public.pmg_record_command_audit(
        'blocked'::public.pmg_command_status, 'apply_project_status_transition',
        'btpm_ui'::public.pmg_source_channel,
        _project_id, 'project', _project_id, NULL,
        _correlation_id, _idempotency_key,
        jsonb_build_object(
          'status_from', v_old_status::text,
          'status_to', _target_status::text,
          'hard_block_count', v_hard_count,
          'hard_block_codes', (
            SELECT COALESCE(jsonb_agg(elem->>'code'), '[]'::jsonb)
              FROM jsonb_array_elements(v_hard) AS elem
          ),
          'warning_count', v_warn_count,
          'confirmed', COALESCE(_confirm_warnings, false),
          'stale', false
        )
      );
      RETURN public.pmg_build_result(
        'blocked'::public.pmg_command_status, 'apply_project_status_transition',
        'project', _project_id, _project_id,
        jsonb_build_object(
          'code', 'completion_hard_blocked',
          'hard_blocks', v_hard,
          'warnings', v_warn,
          'counts', COALESCE(v_validation->'counts', '{}'::jsonb)
        ),
        '[]'::jsonb, v_hard, '[]'::jsonb, NULL
      );
    END IF;

    IF v_warn_count > 0 AND NOT COALESCE(_confirm_warnings, false) THEN
      PERFORM public.pmg_record_command_audit(
        'confirmation_required'::public.pmg_command_status, 'apply_project_status_transition',
        'btpm_ui'::public.pmg_source_channel,
        _project_id, 'project', _project_id, NULL,
        _correlation_id, _idempotency_key,
        jsonb_build_object(
          'status_from', v_old_status::text,
          'status_to', _target_status::text,
          'warning_count', v_warn_count,
          'warning_codes', (
            SELECT COALESCE(jsonb_agg(elem->>'code'), '[]'::jsonb)
              FROM jsonb_array_elements(v_warn) AS elem
          ),
          'hard_block_count', 0,
          'confirmed', false,
          'stale', false
        )
      );
      RETURN public.pmg_build_result(
        'confirmation_required'::public.pmg_command_status, 'apply_project_status_transition',
        'project', _project_id, _project_id,
        jsonb_build_object(
          'code', 'completion_soft_warnings',
          'warnings', v_warn,
          'counts', COALESCE(v_validation->'counts', '{}'::jsonb)
        ),
        '[]'::jsonb, v_warn, v_warn, NULL
      );
    END IF;
  END IF;

  UPDATE public.projects
     SET status = _target_status
   WHERE id = _project_id;

  SELECT updated_at INTO v_updated_at FROM public.projects WHERE id = _project_id;

  v_data := jsonb_build_object(
    'id', _project_id,
    'status', _target_status,
    'previous_status', v_old_status,
    'updated_at', v_updated_at
  );

  PERFORM public.pmg_record_command_audit(
    'applied'::public.pmg_command_status, 'apply_project_status_transition',
    'btpm_ui'::public.pmg_source_channel,
    _project_id, 'project', _project_id, NULL,
    _correlation_id, _idempotency_key,
    jsonb_build_object(
      'status_from', v_old_status::text,
      'status_to', _target_status::text,
      'confirmed', COALESCE(_confirm_warnings, false),
      'reopen', (v_old_status = 'completed' AND _target_status = 'active'),
      'stale', false
    )
  );

  RETURN public.pmg_build_result(
    'applied'::public.pmg_command_status, 'apply_project_status_transition',
    'project', _project_id, _project_id,
    v_data, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.apply_project_team_member_add(_project_id uuid, _user_id uuid, _role_label text DEFAULT NULL::text, _canonical_role_key text DEFAULT NULL::text, _correlation_id text DEFAULT NULL::text, _idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_project record;
  v_new_id uuid;
  v_existing_id uuid;
  v_role_norm text;
  v_canonical_norm text;
  v_data jsonb;
BEGIN
  IF v_actor IS NULL OR NOT public.is_active_user(v_actor) THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'apply_project_team_member_add',
      'project_team_member', NULL, _project_id,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF _project_id IS NULL OR _user_id IS NULL THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'apply_project_team_member_add',
      'project_team_member', NULL, _project_id,
      jsonb_build_object('reason','project_id_and_user_id_required'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  SELECT id, workspace_id, organization_id
    INTO v_project
    FROM public.projects
   WHERE id = _project_id
   FOR SHARE;

  IF v_project.id IS NULL THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'apply_project_team_member_add',
      'project_team_member', NULL, _project_id,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF NOT public.has_project_pm_authority(v_actor, _project_id)
     OR NOT public.can_write_demo(v_actor, v_project.workspace_id) THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'apply_project_team_member_add',
      'project_team_member', NULL, _project_id,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF NOT public.is_active_user(_user_id) THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'apply_project_team_member_add',
      'project_team_member', NULL, _project_id,
      jsonb_build_object('reason','user_not_eligible'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  v_role_norm := NULLIF(btrim(COALESCE(_role_label, '')), '');
  v_canonical_norm := NULLIF(btrim(COALESCE(_canonical_role_key, '')), '');

  -- Duplicate detection: already a member → no_change
  SELECT id INTO v_existing_id
    FROM public.project_team_members
   WHERE project_id = _project_id AND user_id = _user_id
   LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    v_data := jsonb_build_object(
      'id', v_existing_id,
      'project_id', _project_id,
      'user_id', _user_id
    );
    PERFORM public.pmg_record_command_audit(
      'no_change'::public.pmg_command_status, 'apply_project_team_member_add',
      'btpm_ui'::public.pmg_source_channel,
      _project_id, 'project_team_member', v_existing_id, NULL,
      _correlation_id, _idempotency_key,
      jsonb_build_object('workspace_id', v_project.workspace_id, 'reason','already_member')
    );
    RETURN public.pmg_build_result(
      'no_change'::public.pmg_command_status, 'apply_project_team_member_add',
      'project_team_member', v_existing_id, _project_id,
      v_data, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  BEGIN
    INSERT INTO public.project_team_members (
      project_id, user_id, workspace_id, organization_id,
      role_label, canonical_role_key
    ) VALUES (
      _project_id, _user_id, v_project.workspace_id, v_project.organization_id,
      v_role_norm, v_canonical_norm
    )
    RETURNING id INTO v_new_id;
  EXCEPTION
    WHEN unique_violation THEN
      -- Race with concurrent add
      SELECT id INTO v_existing_id
        FROM public.project_team_members
       WHERE project_id = _project_id AND user_id = _user_id
       LIMIT 1;
      v_data := jsonb_build_object('id', v_existing_id, 'project_id', _project_id, 'user_id', _user_id);
      PERFORM public.pmg_record_command_audit(
        'no_change'::public.pmg_command_status, 'apply_project_team_member_add',
        'btpm_ui'::public.pmg_source_channel,
        _project_id, 'project_team_member', v_existing_id, NULL,
        _correlation_id, _idempotency_key,
        jsonb_build_object('workspace_id', v_project.workspace_id, 'reason','race_already_member')
      );
      RETURN public.pmg_build_result(
        'no_change'::public.pmg_command_status, 'apply_project_team_member_add',
        'project_team_member', v_existing_id, _project_id,
        v_data, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
      );
    WHEN foreign_key_violation OR not_null_violation OR check_violation OR invalid_text_representation THEN
      RETURN public.pmg_build_result(
        'invalid'::public.pmg_command_status, 'apply_project_team_member_add',
        'project_team_member', NULL, _project_id,
        jsonb_build_object('reason', SQLERRM),
        '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
      );
  END;

  v_data := jsonb_build_object(
    'id', v_new_id,
    'project_id', _project_id,
    'user_id', _user_id
  );

  PERFORM public.pmg_record_command_audit(
    'applied'::public.pmg_command_status, 'apply_project_team_member_add',
    'btpm_ui'::public.pmg_source_channel,
    _project_id, 'project_team_member', v_new_id, NULL,
    _correlation_id, _idempotency_key,
    jsonb_build_object(
      'workspace_id', v_project.workspace_id,
      'role_label_present', v_role_norm IS NOT NULL,
      'canonical_role_key_present', v_canonical_norm IS NOT NULL
    )
  );

  RETURN public.pmg_build_result(
    'applied'::public.pmg_command_status, 'apply_project_team_member_add',
    'project_team_member', v_new_id, _project_id,
    v_data, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.apply_project_team_member_remove(_member_id uuid, _expected_updated_at timestamp with time zone, _correlation_id text DEFAULT NULL::text, _idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_row record;
  v_data jsonb;
BEGIN
  IF v_actor IS NULL OR NOT public.is_active_user(v_actor) THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'apply_project_team_member_remove',
      'project_team_member', _member_id, NULL,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF _member_id IS NULL THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'apply_project_team_member_remove',
      'project_team_member', NULL, NULL,
      jsonb_build_object('reason','member_id_required'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  SELECT id, project_id, workspace_id, organization_id, user_id, updated_at
    INTO v_row
    FROM public.project_team_members
   WHERE id = _member_id
   FOR UPDATE;

  IF v_row.id IS NULL THEN
    -- Already removed → no_change
    PERFORM public.pmg_record_command_audit(
      'no_change'::public.pmg_command_status, 'apply_project_team_member_remove',
      'btpm_ui'::public.pmg_source_channel,
      NULL, 'project_team_member', _member_id, NULL,
      _correlation_id, _idempotency_key,
      jsonb_build_object('reason','already_removed')
    );
    RETURN public.pmg_build_result(
      'no_change'::public.pmg_command_status, 'apply_project_team_member_remove',
      'project_team_member', _member_id, NULL,
      jsonb_build_object('id', _member_id), '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF NOT public.has_project_pm_authority(v_actor, v_row.project_id)
     OR NOT public.can_write_demo(v_actor, v_row.workspace_id) THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'apply_project_team_member_remove',
      'project_team_member', _member_id, v_row.project_id,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF _expected_updated_at IS NULL
     OR v_row.updated_at IS DISTINCT FROM _expected_updated_at THEN
    PERFORM public.pmg_record_command_audit(
      'conflict'::public.pmg_command_status, 'apply_project_team_member_remove',
      'btpm_ui'::public.pmg_source_channel,
      v_row.project_id, 'project_team_member', _member_id, NULL,
      _correlation_id, _idempotency_key,
      jsonb_build_object('workspace_id', v_row.workspace_id, 'reason','stale_updated_at')
    );
    RETURN public.pmg_build_result(
      'conflict'::public.pmg_command_status, 'apply_project_team_member_remove',
      'project_team_member', _member_id, v_row.project_id,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb,
      jsonb_build_object('expected_updated_at', _expected_updated_at, 'actual_updated_at', v_row.updated_at)
    );
  END IF;

  DELETE FROM public.project_team_members WHERE id = _member_id;

  v_data := jsonb_build_object(
    'id', _member_id,
    'project_id', v_row.project_id,
    'user_id', v_row.user_id
  );

  PERFORM public.pmg_record_command_audit(
    'applied'::public.pmg_command_status, 'apply_project_team_member_remove',
    'btpm_ui'::public.pmg_source_channel,
    v_row.project_id, 'project_team_member', _member_id, NULL,
    _correlation_id, _idempotency_key,
    jsonb_build_object('workspace_id', v_row.workspace_id)
  );

  RETURN public.pmg_build_result(
    'applied'::public.pmg_command_status, 'apply_project_team_member_remove',
    'project_team_member', _member_id, v_row.project_id,
    v_data, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.apply_project_team_member_role_update(_member_id uuid, _role_label text, _canonical_role_key text, _expected_updated_at timestamp with time zone, _correlation_id text DEFAULT NULL::text, _idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_row record;
  v_role_norm text;
  v_canonical_norm text;
  v_current_role_plain text;
  v_data jsonb;
  v_new_updated_at timestamptz;
BEGIN
  IF v_actor IS NULL OR NOT public.is_active_user(v_actor) THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'apply_project_team_member_role_update',
      'project_team_member', _member_id, NULL,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF _member_id IS NULL THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'apply_project_team_member_role_update',
      'project_team_member', NULL, NULL,
      jsonb_build_object('reason','member_id_required'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  SELECT id, project_id, workspace_id, organization_id,
         role_label, canonical_role_key, updated_at
    INTO v_row
    FROM public.project_team_members
   WHERE id = _member_id
   FOR UPDATE;

  IF v_row.id IS NULL THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'apply_project_team_member_role_update',
      'project_team_member', _member_id, NULL,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF NOT public.has_project_pm_authority(v_actor, v_row.project_id)
     OR NOT public.can_write_demo(v_actor, v_row.workspace_id) THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'apply_project_team_member_role_update',
      'project_team_member', _member_id, v_row.project_id,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF _expected_updated_at IS NULL
     OR v_row.updated_at IS DISTINCT FROM _expected_updated_at THEN
    PERFORM public.pmg_record_command_audit(
      'conflict'::public.pmg_command_status, 'apply_project_team_member_role_update',
      'btpm_ui'::public.pmg_source_channel,
      v_row.project_id, 'project_team_member', _member_id, NULL,
      _correlation_id, _idempotency_key,
      jsonb_build_object('workspace_id', v_row.workspace_id, 'reason','stale_updated_at')
    );
    RETURN public.pmg_build_result(
      'conflict'::public.pmg_command_status, 'apply_project_team_member_role_update',
      'project_team_member', _member_id, v_row.project_id,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb,
      jsonb_build_object('expected_updated_at', _expected_updated_at, 'actual_updated_at', v_row.updated_at)
    );
  END IF;

  v_role_norm := NULLIF(btrim(COALESCE(_role_label, '')), '');
  v_canonical_norm := NULLIF(btrim(COALESCE(_canonical_role_key, '')), '');

  v_current_role_plain := public.btpm_decrypt(v_row.role_label, v_row.organization_id);

  IF v_current_role_plain IS NOT DISTINCT FROM v_role_norm
     AND v_row.canonical_role_key IS NOT DISTINCT FROM v_canonical_norm THEN
    v_data := jsonb_build_object('id', _member_id, 'project_id', v_row.project_id);
    PERFORM public.pmg_record_command_audit(
      'no_change'::public.pmg_command_status, 'apply_project_team_member_role_update',
      'btpm_ui'::public.pmg_source_channel,
      v_row.project_id, 'project_team_member', _member_id, NULL,
      _correlation_id, _idempotency_key,
      jsonb_build_object('workspace_id', v_row.workspace_id)
    );
    RETURN public.pmg_build_result(
      'no_change'::public.pmg_command_status, 'apply_project_team_member_role_update',
      'project_team_member', _member_id, v_row.project_id,
      v_data, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  BEGIN
    UPDATE public.project_team_members
       SET role_label = v_role_norm,
           canonical_role_key = v_canonical_norm
     WHERE id = _member_id
     RETURNING updated_at INTO v_new_updated_at;
  EXCEPTION
    WHEN foreign_key_violation OR not_null_violation OR check_violation OR invalid_text_representation THEN
      RETURN public.pmg_build_result(
        'invalid'::public.pmg_command_status, 'apply_project_team_member_role_update',
        'project_team_member', _member_id, v_row.project_id,
        jsonb_build_object('reason', SQLERRM),
        '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
      );
  END;

  v_data := jsonb_build_object(
    'id', _member_id,
    'project_id', v_row.project_id,
    'updated_at', v_new_updated_at
  );

  PERFORM public.pmg_record_command_audit(
    'applied'::public.pmg_command_status, 'apply_project_team_member_role_update',
    'btpm_ui'::public.pmg_source_channel,
    v_row.project_id, 'project_team_member', _member_id, NULL,
    _correlation_id, _idempotency_key,
    jsonb_build_object(
      'workspace_id', v_row.workspace_id,
      'role_label_present', v_role_norm IS NOT NULL,
      'canonical_role_key_present', v_canonical_norm IS NOT NULL
    )
  );

  RETURN public.pmg_build_result(
    'applied'::public.pmg_command_status, 'apply_project_team_member_role_update',
    'project_team_member', _member_id, v_row.project_id,
    v_data, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.apply_project_update(_project_id uuid, _expected_updated_at timestamp with time zone, _name text DEFAULT NULL::text, _priority pm_priority DEFAULT NULL::pm_priority, _description text DEFAULT NULL::text, _charter text DEFAULT NULL::text, _goals text DEFAULT NULL::text, _scope_in text DEFAULT NULL::text, _scope_out text DEFAULT NULL::text, _business_case text DEFAULT NULL::text, _success_criteria text DEFAULT NULL::text, _completion_criteria text DEFAULT NULL::text, _budget_narrative text DEFAULT NULL::text, _assumptions text DEFAULT NULL::text, _constraints text DEFAULT NULL::text, _program_id uuid DEFAULT NULL::uuid, _delivery_model project_delivery_model DEFAULT NULL::project_delivery_model, _set_name boolean DEFAULT false, _set_priority boolean DEFAULT false, _set_description boolean DEFAULT false, _set_charter boolean DEFAULT false, _set_goals boolean DEFAULT false, _set_scope_in boolean DEFAULT false, _set_scope_out boolean DEFAULT false, _set_business_case boolean DEFAULT false, _set_success_criteria boolean DEFAULT false, _set_completion_criteria boolean DEFAULT false, _set_budget_narrative boolean DEFAULT false, _set_assumptions boolean DEFAULT false, _set_constraints boolean DEFAULT false, _set_program_id boolean DEFAULT false, _set_delivery_model boolean DEFAULT false, _correlation_id text DEFAULT NULL::text, _idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_row record;
  v_org uuid;
  v_ws uuid;
  v_program record;

  n_name text;
  n_description text;
  n_charter text;
  n_goals text;
  n_scope_in text;
  n_scope_out text;
  n_business_case text;
  n_success_criteria text;
  n_completion_criteria text;
  n_budget_narrative text;
  n_assumptions text;
  n_constraints text;

  c_description text;
  c_charter text;
  c_goals text;
  c_scope_in text;
  c_scope_out text;
  c_business_case text;
  c_success_criteria text;
  c_completion_criteria text;
  c_budget_narrative text;
  c_assumptions text;
  c_constraints text;

  v_changes jsonb := '{}'::jsonb;
  v_change_count int := 0;
  v_data jsonb;
BEGIN
  IF v_actor IS NULL OR NOT public.is_active_user(v_actor) THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'apply_project_update',
      'project', _project_id, _project_id,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF _expected_updated_at IS NULL THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'apply_project_update',
      'project', _project_id, _project_id,
      jsonb_build_object('reason','expected_updated_at_required'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  SELECT *
    INTO v_row
    FROM public.projects
   WHERE id = _project_id
   FOR UPDATE;

  IF v_row.id IS NULL THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'apply_project_update',
      'project', _project_id, _project_id,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF NOT public.has_project_pm_authority(v_actor, _project_id)
     OR NOT public.can_write_demo(v_actor, v_row.workspace_id) THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'apply_project_update',
      'project', _project_id, _project_id,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF v_row.updated_at IS DISTINCT FROM _expected_updated_at THEN
    PERFORM public.pmg_record_command_audit(
      'conflict'::public.pmg_command_status, 'apply_project_update',
      'btpm_ui'::public.pmg_source_channel,
      _project_id, 'project', _project_id, NULL,
      _correlation_id, _idempotency_key,
      jsonb_build_object('stale', true)
    );
    RETURN public.pmg_build_result(
      'conflict'::public.pmg_command_status, 'apply_project_update',
      'project', _project_id, _project_id,
      jsonb_build_object(
        'code','stale_project',
        'current_updated_at', v_row.updated_at
      ),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  v_org := v_row.organization_id;
  v_ws  := v_row.workspace_id;

  n_name               := CASE WHEN _set_name               THEN NULLIF(btrim(_name), '') ELSE NULL END;
  n_description        := CASE WHEN _set_description        THEN NULLIF(btrim(_description), '') ELSE NULL END;
  n_charter            := CASE WHEN _set_charter            THEN NULLIF(btrim(_charter), '') ELSE NULL END;
  n_goals              := CASE WHEN _set_goals              THEN NULLIF(btrim(_goals), '') ELSE NULL END;
  n_scope_in           := CASE WHEN _set_scope_in           THEN NULLIF(btrim(_scope_in), '') ELSE NULL END;
  n_scope_out          := CASE WHEN _set_scope_out          THEN NULLIF(btrim(_scope_out), '') ELSE NULL END;
  n_business_case      := CASE WHEN _set_business_case      THEN NULLIF(btrim(_business_case), '') ELSE NULL END;
  n_success_criteria   := CASE WHEN _set_success_criteria   THEN NULLIF(btrim(_success_criteria), '') ELSE NULL END;
  n_completion_criteria:= CASE WHEN _set_completion_criteria THEN NULLIF(btrim(_completion_criteria), '') ELSE NULL END;
  n_budget_narrative   := CASE WHEN _set_budget_narrative   THEN NULLIF(btrim(_budget_narrative), '') ELSE NULL END;
  n_assumptions        := CASE WHEN _set_assumptions        THEN NULLIF(btrim(_assumptions), '') ELSE NULL END;
  n_constraints        := CASE WHEN _set_constraints        THEN NULLIF(btrim(_constraints), '') ELSE NULL END;

  IF _set_name AND (n_name IS NULL) THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'apply_project_update',
      'project', _project_id, _project_id,
      jsonb_build_object('reason','name_required'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF _set_program_id THEN
    IF _program_id IS NOT NULL THEN
      SELECT id, workspace_id, organization_id, is_archived
        INTO v_program
        FROM public.programs
       WHERE id = _program_id;

      IF v_program.id IS NULL
         OR v_program.is_archived
         OR v_program.workspace_id  IS DISTINCT FROM v_ws
         OR v_program.organization_id IS DISTINCT FROM v_org
      THEN
        RETURN public.pmg_build_result(
          'invalid'::public.pmg_command_status, 'apply_project_update',
          'project', _project_id, _project_id,
          jsonb_build_object('reason','invalid_program'),
          '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
        );
      END IF;
    END IF;
  END IF;

  c_description         := public.btpm_decrypt(v_row.description,         v_org);
  c_charter             := public.btpm_decrypt(v_row.charter,             v_org);
  c_goals               := public.btpm_decrypt(v_row.goals,               v_org);
  c_scope_in            := public.btpm_decrypt(v_row.scope_in,            v_org);
  c_scope_out           := public.btpm_decrypt(v_row.scope_out,           v_org);
  c_business_case       := public.btpm_decrypt(v_row.business_case,       v_org);
  c_success_criteria    := public.btpm_decrypt(v_row.success_criteria,    v_org);
  c_completion_criteria := public.btpm_decrypt(v_row.completion_criteria, v_org);
  c_budget_narrative    := public.btpm_decrypt(v_row.budget_narrative,    v_org);
  c_assumptions         := public.btpm_decrypt(v_row.assumptions,         v_org);
  c_constraints         := public.btpm_decrypt(v_row.constraints,         v_org);

  IF _set_name               AND n_name               IS DISTINCT FROM v_row.name               THEN v_changes := v_changes || jsonb_build_object('name', true);               v_change_count := v_change_count + 1; END IF;
  IF _set_priority           AND _priority            IS DISTINCT FROM v_row.priority           THEN v_changes := v_changes || jsonb_build_object('priority', true);           v_change_count := v_change_count + 1; END IF;
  IF _set_description        AND n_description        IS DISTINCT FROM c_description            THEN v_changes := v_changes || jsonb_build_object('description', true);        v_change_count := v_change_count + 1; END IF;
  IF _set_charter            AND n_charter            IS DISTINCT FROM c_charter                THEN v_changes := v_changes || jsonb_build_object('charter', true);            v_change_count := v_change_count + 1; END IF;
  IF _set_goals              AND n_goals              IS DISTINCT FROM c_goals                  THEN v_changes := v_changes || jsonb_build_object('goals', true);              v_change_count := v_change_count + 1; END IF;
  IF _set_scope_in           AND n_scope_in           IS DISTINCT FROM c_scope_in               THEN v_changes := v_changes || jsonb_build_object('scope_in', true);           v_change_count := v_change_count + 1; END IF;
  IF _set_scope_out          AND n_scope_out          IS DISTINCT FROM c_scope_out              THEN v_changes := v_changes || jsonb_build_object('scope_out', true);          v_change_count := v_change_count + 1; END IF;
  IF _set_business_case      AND n_business_case      IS DISTINCT FROM c_business_case          THEN v_changes := v_changes || jsonb_build_object('business_case', true);      v_change_count := v_change_count + 1; END IF;
  IF _set_success_criteria   AND n_success_criteria   IS DISTINCT FROM c_success_criteria       THEN v_changes := v_changes || jsonb_build_object('success_criteria', true);   v_change_count := v_change_count + 1; END IF;
  IF _set_completion_criteria AND n_completion_criteria IS DISTINCT FROM c_completion_criteria  THEN v_changes := v_changes || jsonb_build_object('completion_criteria', true); v_change_count := v_change_count + 1; END IF;
  IF _set_budget_narrative   AND n_budget_narrative   IS DISTINCT FROM c_budget_narrative       THEN v_changes := v_changes || jsonb_build_object('budget_narrative', true);   v_change_count := v_change_count + 1; END IF;
  IF _set_assumptions        AND n_assumptions        IS DISTINCT FROM c_assumptions            THEN v_changes := v_changes || jsonb_build_object('assumptions', true);        v_change_count := v_change_count + 1; END IF;
  IF _set_constraints        AND n_constraints        IS DISTINCT FROM c_constraints            THEN v_changes := v_changes || jsonb_build_object('constraints', true);        v_change_count := v_change_count + 1; END IF;
  IF _set_program_id         AND _program_id          IS DISTINCT FROM v_row.program_id         THEN v_changes := v_changes || jsonb_build_object('program_id', true);         v_change_count := v_change_count + 1; END IF;
  IF _set_delivery_model     AND _delivery_model      IS DISTINCT FROM v_row.delivery_model     THEN v_changes := v_changes || jsonb_build_object('delivery_model', true);     v_change_count := v_change_count + 1; END IF;

  IF v_change_count = 0 THEN
    v_data := jsonb_build_object('id', v_row.id, 'updated_at', v_row.updated_at);
    PERFORM public.pmg_record_command_audit(
      'no_change'::public.pmg_command_status, 'apply_project_update',
      'btpm_ui'::public.pmg_source_channel,
      _project_id, 'project', _project_id, NULL,
      _correlation_id, _idempotency_key,
      jsonb_build_object('changed_fields', v_changes, 'change_count', 0, 'stale', false)
    );
    RETURN public.pmg_build_result(
      'no_change'::public.pmg_command_status, 'apply_project_update',
      'project', _project_id, _project_id,
      v_data, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  UPDATE public.projects
     SET name                = CASE WHEN _set_name               THEN n_name               ELSE name               END,
         priority            = CASE WHEN _set_priority           THEN _priority            ELSE priority           END,
         description         = CASE WHEN _set_description        THEN n_description        ELSE description        END,
         charter             = CASE WHEN _set_charter            THEN n_charter            ELSE charter            END,
         goals               = CASE WHEN _set_goals              THEN n_goals              ELSE goals              END,
         scope_in            = CASE WHEN _set_scope_in           THEN n_scope_in           ELSE scope_in           END,
         scope_out           = CASE WHEN _set_scope_out          THEN n_scope_out          ELSE scope_out          END,
         business_case       = CASE WHEN _set_business_case      THEN n_business_case      ELSE business_case      END,
         success_criteria    = CASE WHEN _set_success_criteria   THEN n_success_criteria   ELSE success_criteria   END,
         completion_criteria = CASE WHEN _set_completion_criteria THEN n_completion_criteria ELSE completion_criteria END,
         budget_narrative    = CASE WHEN _set_budget_narrative   THEN n_budget_narrative   ELSE budget_narrative   END,
         assumptions         = CASE WHEN _set_assumptions        THEN n_assumptions        ELSE assumptions        END,
         constraints         = CASE WHEN _set_constraints        THEN n_constraints        ELSE constraints        END,
         program_id          = CASE WHEN _set_program_id         THEN _program_id          ELSE program_id         END,
         delivery_model      = CASE WHEN _set_delivery_model     THEN _delivery_model      ELSE delivery_model     END,
         updated_at          = now()
   WHERE id = _project_id
   RETURNING updated_at INTO v_row.updated_at;

  v_data := jsonb_build_object('id', _project_id, 'updated_at', v_row.updated_at);

  PERFORM public.pmg_record_command_audit(
    'applied'::public.pmg_command_status, 'apply_project_update',
    'btpm_ui'::public.pmg_source_channel,
    _project_id, 'project', _project_id, NULL,
    _correlation_id, _idempotency_key,
    jsonb_build_object('changed_fields', v_changes, 'change_count', v_change_count, 'stale', false)
  );

  RETURN public.pmg_build_result(
    'applied'::public.pmg_command_status, 'apply_project_update',
    'project', _project_id, _project_id,
    v_data, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.apply_sprint_create(_project_id uuid, _name text, _goal text DEFAULT NULL::text, _status text DEFAULT 'planning'::text, _start_date date DEFAULT NULL::date, _end_date date DEFAULT NULL::date, _correlation_id text DEFAULT NULL::text, _idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_project record;
  v_name text;
  v_goal text;
  v_status public.sprint_status;
  v_sort_order int;
  v_new_id uuid;
  v_row record;
  v_data jsonb;
BEGIN
  IF v_actor IS NULL OR NOT public.is_active_user(v_actor) THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'apply_sprint_create',
      'sprint', NULL, _project_id,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  -- Lock parent Project row so empty-list concurrent creates serialize.
  SELECT id, workspace_id, organization_id INTO v_project
    FROM public.projects WHERE id = _project_id FOR UPDATE;
  IF v_project.id IS NULL THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'apply_sprint_create',
      'sprint', NULL, _project_id,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF NOT public.has_project_pm_authority(v_actor, _project_id)
     OR NOT public.can_write_demo(v_actor, v_project.workspace_id) THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'apply_sprint_create',
      'sprint', NULL, _project_id,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  v_name := btrim(COALESCE(_name,''));
  IF v_name = '' THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'apply_sprint_create',
      'sprint', NULL, _project_id,
      jsonb_build_object('reason','name_blank'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF _goal IS NULL THEN
    v_goal := NULL;
  ELSE
    v_goal := btrim(_goal);
    IF v_goal = '' THEN v_goal := NULL; END IF;
  END IF;

  BEGIN
    v_status := COALESCE(_status,'planning')::public.sprint_status;
  EXCEPTION WHEN others THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'apply_sprint_create',
      'sprint', NULL, _project_id,
      jsonb_build_object('reason','invalid_status'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END;

  SELECT COALESCE(MAX(sort_order) + 1, 0) INTO v_sort_order
    FROM public.sprints
   WHERE project_id = _project_id AND is_archived = false;

  INSERT INTO public.sprints(
    organization_id, workspace_id, project_id,
    name, goal, status, start_date, end_date,
    sort_order, created_by
  ) VALUES (
    v_project.organization_id, v_project.workspace_id, _project_id,
    v_name, v_goal, v_status, _start_date, _end_date,
    v_sort_order, v_actor
  )
  RETURNING id INTO v_new_id;

  SELECT id, project_id, organization_id, workspace_id, name, goal, status,
         start_date, end_date, sort_order, is_archived, updated_at
    INTO v_row FROM public.sprints WHERE id = v_new_id;

  v_data := jsonb_build_object(
    'id', v_row.id,
    'project_id', v_row.project_id,
    'workspace_id', v_row.workspace_id,
    'organization_id', v_row.organization_id,
    'name', v_row.name,
    'goal', CASE WHEN v_row.goal IS NULL OR v_row.goal = '' THEN v_row.goal
                 ELSE public.btpm_decrypt(v_row.goal, v_row.organization_id) END,
    'status', v_row.status,
    'start_date', v_row.start_date,
    'end_date', v_row.end_date,
    'sort_order', v_row.sort_order,
    'is_archived', v_row.is_archived,
    'updated_at', v_row.updated_at
  );

  PERFORM public.pmg_record_command_audit(
    'applied'::public.pmg_command_status, 'apply_sprint_create',
    'btpm_ui'::public.pmg_source_channel,
    _project_id, 'sprint', v_new_id, NULL,
    _correlation_id, _idempotency_key,
    jsonb_build_object(
      'has_goal', v_goal IS NOT NULL,
      'has_start_date', _start_date IS NOT NULL,
      'has_end_date', _end_date IS NOT NULL,
      'status', v_status
    )
  );

  RETURN public.pmg_build_result(
    'applied'::public.pmg_command_status, 'apply_sprint_create',
    'sprint', v_new_id, _project_id,
    v_data, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.apply_sprint_update(_sprint_id uuid, _expected_updated_at timestamp with time zone, _set_name boolean DEFAULT false, _name text DEFAULT NULL::text, _set_goal boolean DEFAULT false, _goal text DEFAULT NULL::text, _set_status boolean DEFAULT false, _status text DEFAULT NULL::text, _set_start_date boolean DEFAULT false, _start_date date DEFAULT NULL::date, _set_end_date boolean DEFAULT false, _end_date date DEFAULT NULL::date, _correlation_id text DEFAULT NULL::text, _idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_row record;
  v_project_id uuid;
  v_workspace_id uuid;
  v_org_id uuid;
  v_current_goal text;
  v_new_name text;
  v_new_goal text;
  v_new_status public.sprint_status;
  v_new_start date;
  v_new_end date;
  v_changes int := 0;
  v_upd record;
  v_data jsonb;
BEGIN
  IF v_actor IS NULL OR NOT public.is_active_user(v_actor) THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'apply_sprint_update',
      'sprint', _sprint_id, NULL,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF _expected_updated_at IS NULL THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'apply_sprint_update',
      'sprint', _sprint_id, NULL,
      jsonb_build_object('reason','expected_updated_at_required'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  SELECT id, project_id, workspace_id, organization_id, name, goal, status,
         start_date, end_date, sort_order, is_archived, updated_at
    INTO v_row
    FROM public.sprints
   WHERE id = _sprint_id
   FOR UPDATE;

  IF v_row.id IS NULL THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'apply_sprint_update',
      'sprint', _sprint_id, NULL,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  v_project_id := v_row.project_id;
  v_workspace_id := v_row.workspace_id;
  v_org_id := v_row.organization_id;

  IF NOT public.has_project_pm_authority(v_actor, v_project_id)
     OR NOT public.can_write_demo(v_actor, v_workspace_id) THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'apply_sprint_update',
      'sprint', _sprint_id, v_project_id,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF v_row.updated_at IS DISTINCT FROM _expected_updated_at THEN
    PERFORM public.pmg_record_command_audit(
      'conflict'::public.pmg_command_status, 'apply_sprint_update',
      'btpm_ui'::public.pmg_source_channel,
      v_project_id, 'sprint', _sprint_id, NULL,
      _correlation_id, _idempotency_key,
      jsonb_build_object('stale', true)
    );
    RETURN public.pmg_build_result(
      'conflict'::public.pmg_command_status, 'apply_sprint_update',
      'sprint', _sprint_id, v_project_id,
      jsonb_build_object('code','stale_sprint','current_updated_at', v_row.updated_at),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  v_current_goal := CASE WHEN v_row.goal IS NULL OR v_row.goal = '' THEN v_row.goal
                         ELSE public.btpm_decrypt(v_row.goal, v_org_id) END;

  IF _set_name THEN
    v_new_name := btrim(COALESCE(_name,''));
    IF v_new_name = '' THEN
      RETURN public.pmg_build_result(
        'invalid'::public.pmg_command_status, 'apply_sprint_update',
        'sprint', _sprint_id, v_project_id,
        jsonb_build_object('reason','name_blank'),
        '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
      );
    END IF;
  ELSE
    v_new_name := v_row.name;
  END IF;

  IF _set_goal THEN
    IF _goal IS NULL THEN
      v_new_goal := NULL;
    ELSE
      v_new_goal := btrim(_goal);
      IF v_new_goal = '' THEN v_new_goal := NULL; END IF;
    END IF;
  ELSE
    v_new_goal := v_current_goal;
  END IF;

  IF _set_status THEN
    BEGIN
      v_new_status := COALESCE(_status,'planning')::public.sprint_status;
    EXCEPTION WHEN others THEN
      RETURN public.pmg_build_result(
        'invalid'::public.pmg_command_status, 'apply_sprint_update',
        'sprint', _sprint_id, v_project_id,
        jsonb_build_object('reason','invalid_status'),
        '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
      );
    END;
  ELSE
    v_new_status := v_row.status;
  END IF;

  IF _set_start_date THEN
    v_new_start := _start_date;
  ELSE
    v_new_start := v_row.start_date;
  END IF;

  IF _set_end_date THEN
    v_new_end := _end_date;
  ELSE
    v_new_end := v_row.end_date;
  END IF;

  v_changes :=
      (CASE WHEN v_new_name   IS DISTINCT FROM v_row.name       THEN 1 ELSE 0 END)
    + (CASE WHEN v_new_goal   IS DISTINCT FROM v_current_goal   THEN 1 ELSE 0 END)
    + (CASE WHEN v_new_status IS DISTINCT FROM v_row.status     THEN 1 ELSE 0 END)
    + (CASE WHEN v_new_start  IS DISTINCT FROM v_row.start_date THEN 1 ELSE 0 END)
    + (CASE WHEN v_new_end    IS DISTINCT FROM v_row.end_date   THEN 1 ELSE 0 END);

  IF v_changes = 0 THEN
    v_data := jsonb_build_object(
      'id', v_row.id, 'project_id', v_project_id,
      'workspace_id', v_workspace_id, 'organization_id', v_org_id,
      'name', v_row.name, 'goal', v_current_goal,
      'status', v_row.status,
      'start_date', v_row.start_date, 'end_date', v_row.end_date,
      'sort_order', v_row.sort_order, 'is_archived', v_row.is_archived,
      'updated_at', v_row.updated_at
    );
    PERFORM public.pmg_record_command_audit(
      'no_change'::public.pmg_command_status, 'apply_sprint_update',
      'btpm_ui'::public.pmg_source_channel,
      v_project_id, 'sprint', _sprint_id, NULL,
      _correlation_id, _idempotency_key,
      jsonb_build_object('changed_field_count', 0, 'stale', false)
    );
    RETURN public.pmg_build_result(
      'no_change'::public.pmg_command_status, 'apply_sprint_update',
      'sprint', _sprint_id, v_project_id,
      v_data, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  UPDATE public.sprints
     SET name = v_new_name,
         goal = v_new_goal,
         status = v_new_status,
         start_date = v_new_start,
         end_date = v_new_end
   WHERE id = _sprint_id;

  SELECT id, project_id, organization_id, workspace_id, name, goal, status,
         start_date, end_date, sort_order, is_archived, updated_at
    INTO v_upd FROM public.sprints WHERE id = _sprint_id;

  v_data := jsonb_build_object(
    'id', v_upd.id, 'project_id', v_upd.project_id,
    'workspace_id', v_upd.workspace_id, 'organization_id', v_upd.organization_id,
    'name', v_upd.name,
    'goal', CASE WHEN v_upd.goal IS NULL OR v_upd.goal = '' THEN v_upd.goal
                 ELSE public.btpm_decrypt(v_upd.goal, v_upd.organization_id) END,
    'status', v_upd.status,
    'start_date', v_upd.start_date, 'end_date', v_upd.end_date,
    'sort_order', v_upd.sort_order, 'is_archived', v_upd.is_archived,
    'updated_at', v_upd.updated_at
  );

  PERFORM public.pmg_record_command_audit(
    'applied'::public.pmg_command_status, 'apply_sprint_update',
    'btpm_ui'::public.pmg_source_channel,
    v_project_id, 'sprint', _sprint_id, NULL,
    _correlation_id, _idempotency_key,
    jsonb_build_object(
      'changed_field_count', v_changes,
      'name_changed', v_new_name IS DISTINCT FROM v_row.name,
      'goal_changed', v_new_goal IS DISTINCT FROM v_current_goal,
      'status_changed', v_new_status IS DISTINCT FROM v_row.status,
      'start_date_changed', v_new_start IS DISTINCT FROM v_row.start_date,
      'end_date_changed', v_new_end IS DISTINCT FROM v_row.end_date,
      'stale', false
    )
  );

  RETURN public.pmg_build_result(
    'applied'::public.pmg_command_status, 'apply_sprint_update',
    'sprint', _sprint_id, v_project_id,
    v_data, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.apply_task_assignee_set(_task_id uuid, _assignee_id uuid DEFAULT NULL::uuid, _correlation_id text DEFAULT NULL::text, _idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_task record;
  v_project_id uuid;
  v_workspace_id uuid;
  v_organization_id uuid;
  v_current_assignee uuid;
  v_data jsonb;
BEGIN
  IF v_actor IS NULL OR NOT public.is_active_user(v_actor) THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'apply_task_assignee_set',
      'task', _task_id, NULL,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF _task_id IS NULL THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'apply_task_assignee_set',
      'task', NULL, NULL,
      jsonb_build_object('reason','task_id_required'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  SELECT id, project_id, workspace_id, organization_id
    INTO v_task
    FROM public.tasks
   WHERE id = _task_id
   FOR UPDATE;

  IF v_task.id IS NULL THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'apply_task_assignee_set',
      'task', _task_id, NULL,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  v_project_id      := v_task.project_id;
  v_workspace_id    := v_task.workspace_id;
  v_organization_id := v_task.organization_id;

  -- Consistent with other PMG task commands: PM authority + demo-write protection.
  IF NOT public.has_project_pm_authority(v_actor, v_project_id)
     OR NOT public.can_write_demo(v_actor, v_workspace_id) THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'apply_task_assignee_set',
      'task', _task_id, v_project_id,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  -- Eligibility for a non-null assignee: must be a member of the task's
  -- workspace (mirrors the assignee list surfaced by the UI).
  IF _assignee_id IS NOT NULL THEN
    IF NOT public.is_workspace_member(_assignee_id, v_workspace_id) THEN
      RETURN public.pmg_build_result(
        'invalid'::public.pmg_command_status, 'apply_task_assignee_set',
        'task', _task_id, v_project_id,
        jsonb_build_object('reason','assignee_not_eligible'),
        '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
      );
    END IF;
  END IF;

  -- Snapshot the current active assignee to detect no_change safely.
  SELECT assignee_id INTO v_current_assignee
    FROM public.task_assignments
   WHERE task_id = _task_id
   ORDER BY created_at DESC
   LIMIT 1;

  IF v_current_assignee IS NOT DISTINCT FROM _assignee_id THEN
    v_data := jsonb_build_object(
      'task_id', _task_id,
      'old_assignee_id', v_current_assignee,
      'new_assignee_id', _assignee_id
    );
    PERFORM public.pmg_record_command_audit(
      'no_change'::public.pmg_command_status, 'apply_task_assignee_set',
      'btpm_ui'::public.pmg_source_channel,
      v_project_id, 'task', _task_id, NULL,
      _correlation_id, _idempotency_key,
      jsonb_build_object(
        'workspace_id', v_workspace_id,
        'assignee_cleared', _assignee_id IS NULL
      )
    );
    RETURN public.pmg_build_result(
      'no_change'::public.pmg_command_status, 'apply_task_assignee_set',
      'task', _task_id, v_project_id,
      v_data, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  -- Delegate the DELETE / optional INSERT / activity emission exactly once.
  BEGIN
    PERFORM public.set_task_assignee(_task_id, _assignee_id);
  EXCEPTION
    WHEN insufficient_privilege OR raise_exception THEN
      RETURN public.pmg_build_result(
        'not_authorized'::public.pmg_command_status, 'apply_task_assignee_set',
        'task', _task_id, v_project_id,
        jsonb_build_object('reason', SQLERRM),
        '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
      );
    WHEN foreign_key_violation OR not_null_violation
      OR check_violation OR invalid_text_representation THEN
      RETURN public.pmg_build_result(
        'invalid'::public.pmg_command_status, 'apply_task_assignee_set',
        'task', _task_id, v_project_id,
        jsonb_build_object('reason', SQLERRM),
        '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
      );
  END;

  v_data := jsonb_build_object(
    'task_id', _task_id,
    'old_assignee_id', v_current_assignee,
    'new_assignee_id', _assignee_id,
    'project_id', v_project_id,
    'workspace_id', v_workspace_id
  );

  PERFORM public.pmg_record_command_audit(
    'applied'::public.pmg_command_status, 'apply_task_assignee_set',
    'btpm_ui'::public.pmg_source_channel,
    v_project_id, 'task', _task_id, NULL,
    _correlation_id, _idempotency_key,
    jsonb_build_object(
      'workspace_id', v_workspace_id,
      'assignee_cleared', _assignee_id IS NULL
    )
  );

  RETURN public.pmg_build_result(
    'applied'::public.pmg_command_status, 'apply_task_assignee_set',
    'task', _task_id, v_project_id,
    v_data, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.apply_task_create(_phase_id uuid, _name text, _description text DEFAULT NULL::text, _status pm_status DEFAULT 'planned'::pm_status, _priority pm_priority DEFAULT 'medium'::pm_priority, _task_type task_type DEFAULT 'work_item'::task_type, _start_date date DEFAULT NULL::date, _due_date date DEFAULT NULL::date, _estimated_hours numeric DEFAULT NULL::numeric, _sort_order integer DEFAULT NULL::integer, _correlation_id text DEFAULT NULL::text, _idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_phase record;
  v_project_id uuid;
  v_name text;
  v_description text;
  v_max_sort int;
  v_resolved_sort int;
  v_shifted_count int := 0;
  v_new_id uuid;
  v_new_row record;
  v_new_description text;
  v_data jsonb;
BEGIN
  IF v_actor IS NULL THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'apply_task_create',
      'task', NULL, NULL,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF NOT public.is_active_user(v_actor) THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'apply_task_create',
      'task', NULL, NULL,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  SELECT id, project_id, workspace_id, organization_id, name, start_date, target_end_date
    INTO v_phase
    FROM public.phases
   WHERE id = _phase_id
   FOR UPDATE;

  IF v_phase.id IS NULL THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'apply_task_create',
      'task', NULL, NULL,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  v_project_id := v_phase.project_id;

  IF NOT public.has_project_pm_authority(v_actor, v_project_id)
     OR NOT public.can_write_demo(v_actor, v_phase.workspace_id) THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'apply_task_create',
      'task', NULL, v_project_id,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  v_name := btrim(COALESCE(_name, ''));
  IF v_name = '' THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'apply_task_create',
      'task', NULL, v_project_id,
      jsonb_build_object('reason','name_blank'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF _description IS NULL THEN
    v_description := NULL;
  ELSE
    v_description := btrim(_description);
    IF v_description = '' THEN v_description := NULL; END IF;
  END IF;

  IF _estimated_hours IS NOT NULL AND _estimated_hours < 0 THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'apply_task_create',
      'task', NULL, v_project_id,
      jsonb_build_object('reason','estimated_hours_negative'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF _start_date IS NOT NULL AND _due_date IS NOT NULL
     AND _start_date > _due_date THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'apply_task_create',
      'task', NULL, v_project_id,
      jsonb_build_object('reason','start_after_due'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF _sort_order IS NOT NULL AND _sort_order < 0 THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'apply_task_create',
      'task', NULL, v_project_id,
      jsonb_build_object('reason','sort_order_negative'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF _start_date IS NOT NULL AND v_phase.start_date IS NOT NULL
     AND _start_date < v_phase.start_date THEN
    RETURN public.pmg_build_result(
      'confirmation_required'::public.pmg_command_status, 'apply_task_create',
      'task', NULL, v_project_id,
      jsonb_build_object(
        'reason','task_start_before_phase_start',
        'phase_id', v_phase.id,
        'phase_start_date', v_phase.start_date,
        'phase_target_end_date', v_phase.target_end_date,
        'task_start_date', _start_date,
        'task_due_date', _due_date
      ),
      '[]'::jsonb, '[]'::jsonb,
      jsonb_build_array(jsonb_build_object(
        'code','extend_phase_window_required',
        'required_phase_start_date', _start_date,
        'required_phase_target_end_date', v_phase.target_end_date
      )),
      NULL
    );
  END IF;

  IF _due_date IS NOT NULL AND v_phase.target_end_date IS NOT NULL
     AND _due_date > v_phase.target_end_date THEN
    RETURN public.pmg_build_result(
      'confirmation_required'::public.pmg_command_status, 'apply_task_create',
      'task', NULL, v_project_id,
      jsonb_build_object(
        'reason','task_due_after_phase_end',
        'phase_id', v_phase.id,
        'phase_start_date', v_phase.start_date,
        'phase_target_end_date', v_phase.target_end_date,
        'task_start_date', _start_date,
        'task_due_date', _due_date
      ),
      '[]'::jsonb, '[]'::jsonb,
      jsonb_build_array(jsonb_build_object(
        'code','extend_phase_window_required',
        'required_phase_start_date', v_phase.start_date,
        'required_phase_target_end_date', _due_date
      )),
      NULL
    );
  END IF;

  PERFORM 1 FROM public.tasks
    WHERE phase_id = _phase_id
    FOR UPDATE;

  SELECT COALESCE(max(sort_order), -1) INTO v_max_sort
    FROM public.tasks
   WHERE phase_id = _phase_id;

  IF _sort_order IS NULL THEN
    v_resolved_sort := v_max_sort + 1;
  ELSE
    IF _sort_order > v_max_sort + 1 THEN
      v_resolved_sort := v_max_sort + 1;
    ELSE
      v_resolved_sort := _sort_order;
    END IF;

    IF v_resolved_sort <= v_max_sort THEN
      WITH shifted AS (
        UPDATE public.tasks
           SET sort_order = sort_order + 1
         WHERE phase_id = _phase_id
           AND sort_order >= v_resolved_sort
        RETURNING id
      )
      SELECT count(*) INTO v_shifted_count FROM shifted;
    END IF;
  END IF;

  INSERT INTO public.tasks (
    organization_id,
    workspace_id,
    project_id,
    phase_id,
    name,
    description,
    status,
    priority,
    task_type,
    start_date,
    due_date,
    estimated_hours,
    sort_order,
    created_by
  ) VALUES (
    v_phase.organization_id,
    v_phase.workspace_id,
    v_phase.project_id,
    v_phase.id,
    v_name,
    v_description,
    _status,
    _priority,
    _task_type,
    _start_date,
    _due_date,
    _estimated_hours,
    v_resolved_sort,
    v_actor
  )
  RETURNING id INTO v_new_id;

  SELECT id, organization_id, workspace_id, project_id, phase_id,
         name, description, status, priority, task_type,
         start_date, due_date, estimated_hours, sort_order,
         is_archived, created_at, updated_at
    INTO v_new_row
    FROM public.tasks
   WHERE id = v_new_id;

  IF v_new_row.description IS NULL THEN
    v_new_description := NULL;
  ELSE
    v_new_description := public.btpm_decrypt(v_new_row.description, v_new_row.organization_id);
  END IF;

  v_data := jsonb_build_object(
    'id', v_new_row.id,
    'organization_id', v_new_row.organization_id,
    'workspace_id', v_new_row.workspace_id,
    'project_id', v_new_row.project_id,
    'phase_id', v_new_row.phase_id,
    'name', v_new_row.name,
    'description', v_new_description,
    'status', v_new_row.status,
    'priority', v_new_row.priority,
    'task_type', v_new_row.task_type,
    'start_date', v_new_row.start_date,
    'due_date', v_new_row.due_date,
    'estimated_hours', v_new_row.estimated_hours,
    'sort_order', v_new_row.sort_order,
    'is_archived', v_new_row.is_archived,
    'created_at', v_new_row.created_at,
    'updated_at', v_new_row.updated_at,
    'shifted_sibling_count', v_shifted_count
  );

  PERFORM public.pmg_record_command_audit(
    'applied'::public.pmg_command_status, 'apply_task_create',
    'btpm_ui'::public.pmg_source_channel,
    v_project_id, 'task', v_new_id, NULL,
    _correlation_id, _idempotency_key,
    jsonb_build_object(
      'task_id', v_new_id,
      'phase_id', v_phase.id,
      'resolved_sort_order', v_resolved_sort,
      'shifted_sibling_count', v_shifted_count,
      'has_start_date', (_start_date IS NOT NULL),
      'has_due_date', (_due_date IS NOT NULL),
      'has_description', (v_description IS NOT NULL),
      'has_estimated_hours', (_estimated_hours IS NOT NULL),
      'status', _status,
      'priority', _priority,
      'task_type', _task_type
    )
  );

  RETURN public.pmg_build_result(
    'applied'::public.pmg_command_status, 'apply_task_create',
    'task', v_new_id, v_project_id,
    v_data, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.apply_task_execution_change(_task_id uuid, _expected_updated_at timestamp with time zone, _set_actual_start boolean DEFAULT false, _actual_start_date date DEFAULT NULL::date, _set_actual_end boolean DEFAULT false, _actual_end_date date DEFAULT NULL::date, _status pm_status DEFAULT NULL::pm_status, _correlation_id text DEFAULT NULL::text, _idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_task record;
  v_project record;
  v_project_id uuid;
  v_new_actual_start date;
  v_new_actual_end date;
  v_new_status public.pm_status;
  v_actual_start_changed boolean;
  v_actual_end_changed boolean;
  v_status_changed boolean;
  v_changed_count int;
  v_updated record;
  v_data jsonb;
BEGIN
  IF v_actor IS NULL OR NOT public.is_active_user(v_actor) THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'apply_task_execution_change',
      'task', _task_id, NULL,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF _expected_updated_at IS NULL THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'apply_task_execution_change',
      'task', _task_id, NULL,
      jsonb_build_object('reason','expected_updated_at_required'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  -- Only the statuses the active execution surface uses are accepted here.
  -- Reopen is served by public.reopen_task and is intentionally not routable
  -- through this command.
  IF _status IS NOT NULL AND _status NOT IN ('active'::public.pm_status, 'completed'::public.pm_status) THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'apply_task_execution_change',
      'task', _task_id, NULL,
      jsonb_build_object('reason','status_not_allowed'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  SELECT id, project_id, workspace_id, organization_id, phase_id,
         status, actual_start_date, actual_end_date, updated_at
    INTO v_task
    FROM public.tasks
   WHERE id = _task_id
   FOR UPDATE;

  IF v_task.id IS NULL THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'apply_task_execution_change',
      'task', _task_id, NULL,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  v_project_id := v_task.project_id;

  SELECT id, workspace_id INTO v_project
    FROM public.projects
   WHERE id = v_project_id;

  IF v_project.id IS NULL
     OR NOT public.has_project_pm_authority(v_actor, v_project_id)
     OR NOT public.can_write_demo(v_actor, v_project.workspace_id) THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'apply_task_execution_change',
      'task', _task_id, v_project_id,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF v_task.updated_at IS DISTINCT FROM _expected_updated_at THEN
    PERFORM public.pmg_record_command_audit(
      'conflict'::public.pmg_command_status, 'apply_task_execution_change',
      'btpm_ui'::public.pmg_source_channel,
      v_project_id, 'task', _task_id, NULL,
      _correlation_id, _idempotency_key,
      jsonb_build_object('stale', true)
    );
    RETURN public.pmg_build_result(
      'conflict'::public.pmg_command_status, 'apply_task_execution_change',
      'task', _task_id, v_project_id,
      jsonb_build_object(
        'code', 'stale_task',
        'current_updated_at', v_task.updated_at
      ),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  -- Explicit set flags: omitted means unchanged; passed means write (NULL clears).
  IF _set_actual_start THEN
    v_new_actual_start := _actual_start_date;
  ELSE
    v_new_actual_start := v_task.actual_start_date;
  END IF;

  IF _set_actual_end THEN
    v_new_actual_end := _actual_end_date;
  ELSE
    v_new_actual_end := v_task.actual_end_date;
  END IF;

  v_new_status := COALESCE(_status, v_task.status);

  v_actual_start_changed := v_new_actual_start IS DISTINCT FROM v_task.actual_start_date;
  v_actual_end_changed   := v_new_actual_end   IS DISTINCT FROM v_task.actual_end_date;
  v_status_changed       := v_new_status       IS DISTINCT FROM v_task.status;

  v_changed_count :=
      (CASE WHEN v_actual_start_changed THEN 1 ELSE 0 END)
    + (CASE WHEN v_actual_end_changed   THEN 1 ELSE 0 END)
    + (CASE WHEN v_status_changed       THEN 1 ELSE 0 END);

  IF v_changed_count = 0 THEN
    v_data := jsonb_build_object(
      'id', v_task.id,
      'project_id', v_project_id,
      'phase_id', v_task.phase_id,
      'status', v_task.status,
      'actual_start_date', v_task.actual_start_date,
      'actual_end_date', v_task.actual_end_date,
      'updated_at', v_task.updated_at
    );

    PERFORM public.pmg_record_command_audit(
      'no_change'::public.pmg_command_status, 'apply_task_execution_change',
      'btpm_ui'::public.pmg_source_channel,
      v_project_id, 'task', _task_id, NULL,
      _correlation_id, _idempotency_key,
      jsonb_build_object(
        'changed_field_count', 0,
        'actual_start_changed', false,
        'actual_end_changed', false,
        'status_changed', false,
        'stale', false
      )
    );

    RETURN public.pmg_build_result(
      'no_change'::public.pmg_command_status, 'apply_task_execution_change',
      'task', _task_id, v_project_id,
      v_data, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  BEGIN
    UPDATE public.tasks
       SET actual_start_date = v_new_actual_start,
           actual_end_date   = v_new_actual_end,
           status            = v_new_status
     WHERE id = _task_id;
  EXCEPTION
    WHEN check_violation OR raise_exception OR not_null_violation OR invalid_text_representation THEN
      -- Preserve trigger-owned validation messages (completed-lock, range,
      -- derived-actual guards) by surfacing them as invalid + reason.
      PERFORM public.pmg_record_command_audit(
        'invalid'::public.pmg_command_status, 'apply_task_execution_change',
        'btpm_ui'::public.pmg_source_channel,
        v_project_id, 'task', _task_id, NULL,
        _correlation_id, _idempotency_key,
        jsonb_build_object('reason', SQLERRM)
      );
      RETURN public.pmg_build_result(
        'invalid'::public.pmg_command_status, 'apply_task_execution_change',
        'task', _task_id, v_project_id,
        jsonb_build_object('reason', SQLERRM),
        '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
      );
  END;

  SELECT id, project_id, phase_id, status,
         actual_start_date, actual_end_date, updated_at
    INTO v_updated
    FROM public.tasks
   WHERE id = _task_id;

  v_data := jsonb_build_object(
    'id', v_updated.id,
    'project_id', v_updated.project_id,
    'phase_id', v_updated.phase_id,
    'status', v_updated.status,
    'actual_start_date', v_updated.actual_start_date,
    'actual_end_date', v_updated.actual_end_date,
    'updated_at', v_updated.updated_at
  );

  PERFORM public.pmg_record_command_audit(
    'applied'::public.pmg_command_status, 'apply_task_execution_change',
    'btpm_ui'::public.pmg_source_channel,
    v_project_id, 'task', _task_id, NULL,
    _correlation_id, _idempotency_key,
    jsonb_build_object(
      'changed_field_count', v_changed_count,
      'actual_start_changed', v_actual_start_changed,
      'actual_end_changed', v_actual_end_changed,
      'status_changed', v_status_changed,
      'stale', false
    )
  );

  RETURN public.pmg_build_result(
    'applied'::public.pmg_command_status, 'apply_task_execution_change',
    'task', _task_id, v_project_id,
    v_data, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.apply_task_planning_change(_task_id uuid, _new_start date, _new_due date, _confirm_parent_extension boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  t  record;
  ph record;
  needs_ext boolean := false;
  prop_start date;
  prop_end   date;
BEGIN
  SELECT id, phase_id, workspace_id, organization_id, status, is_archived,
         start_date, due_date, name
    INTO t
    FROM public.tasks
   WHERE id = _task_id;

  IF t.id IS NULL THEN
    RAISE EXCEPTION 'apply_task_planning_change: task not found';
  END IF;

  IF NOT public.is_workspace_admin_or_higher(auth.uid(), t.workspace_id) THEN
    RAISE EXCEPTION 'apply_task_planning_change: not authorized';
  END IF;

  IF t.status = 'completed' THEN
    RAISE EXCEPTION 'apply_task_planning_change: task is completed and locked. Reopen first.';
  END IF;
  IF t.status = 'cancelled' OR t.is_archived THEN
    RAISE EXCEPTION 'apply_task_planning_change: task is cancelled/archived';
  END IF;

  IF _new_start IS NOT NULL AND _new_due IS NOT NULL AND _new_due < _new_start THEN
    RAISE EXCEPTION 'apply_task_planning_change: due date must be on or after start date';
  END IF;

  SELECT id, name, start_date, target_end_date
    INTO ph
    FROM public.phases
   WHERE id = t.phase_id;

  prop_start := ph.start_date;
  prop_end   := ph.target_end_date;

  IF _new_start IS NOT NULL AND ph.start_date IS NOT NULL AND _new_start < ph.start_date THEN
    needs_ext := true; prop_start := _new_start;
  END IF;
  IF _new_due IS NOT NULL AND ph.target_end_date IS NOT NULL AND _new_due > ph.target_end_date THEN
    needs_ext := true; prop_end := _new_due;
  END IF;

  IF needs_ext AND NOT _confirm_parent_extension THEN
    RAISE EXCEPTION 'apply_task_planning_change: parent extension required but not confirmed'
      USING ERRCODE = 'check_violation';
  END IF;

  IF needs_ext THEN
    PERFORM set_config('app.allow_planned_extension', 'on', true);

    -- Extend phase first; if its new window now exceeds project, recursively extend project too.
    PERFORM public._apply_phase_extension_internal(ph.id, prop_start, prop_end, _task_id, 'task');

    -- Now apply the task change (still inside bypass)
    UPDATE public.tasks
       SET start_date = _new_start,
           due_date   = _new_due
     WHERE id = _task_id;

    PERFORM set_config('app.allow_planned_extension', 'off', true);
  ELSE
    UPDATE public.tasks
       SET start_date = _new_start,
           due_date   = _new_due
     WHERE id = _task_id;
  END IF;

  RETURN _task_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.apply_task_stakeholder_roles_set(_task_id uuid, _expected_updated_at timestamp with time zone, _requester_stakeholder_id uuid DEFAULT NULL::uuid, _executor_stakeholder_ids uuid[] DEFAULT '{}'::uuid[], _correlation_id text DEFAULT NULL::text, _idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_command constant text := 'apply_task_stakeholder_roles_set';
  v_actor uuid := auth.uid();
  v_task record;
  v_desired_executors uuid[];
  v_all_desired uuid[];
  v_new_updated_at timestamptz;
  v_current_requester uuid;
  v_current_executors uuid[];
  v_added_executors uuid[];
  v_removed_executors uuid[];
  v_added_any boolean;
  v_removed_any boolean;
  v_requester_changed boolean;
  v_invalid_ids uuid[];
  v_requester_count int;
  v_executor_count int;
BEGIN
  IF v_actor IS NULL OR NOT public.is_active_user(v_actor) THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, v_command,
      'task', _task_id, NULL,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF _task_id IS NULL OR _expected_updated_at IS NULL THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, v_command,
      'task', _task_id, NULL,
      jsonb_build_object('reason','task_id_and_expected_updated_at_required'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  SELECT id, project_id, workspace_id, organization_id, status, is_archived, updated_at
    INTO v_task
    FROM public.tasks
    WHERE id = _task_id
    FOR UPDATE;

  IF v_task.id IS NULL THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, v_command,
      'task', _task_id, NULL,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF NOT public.has_project_pm_authority(v_actor, v_task.project_id)
     OR NOT public.can_write_demo(v_actor, v_task.workspace_id) THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, v_command,
      'task', _task_id, v_task.project_id,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF v_task.status = 'cancelled'::public.pm_status OR v_task.is_archived IS TRUE THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, v_command,
      'task', _task_id, v_task.project_id,
      jsonb_build_object('reason','task_read_only_lifecycle'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF v_task.updated_at IS DISTINCT FROM _expected_updated_at THEN
    RETURN public.pmg_build_result(
      'conflict'::public.pmg_command_status, v_command,
      'task', _task_id, v_task.project_id,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb,
      jsonb_build_object(
        'expected_updated_at', _expected_updated_at,
        'current_updated_at', v_task.updated_at
      )
    );
  END IF;

  -- Normalize desired executors: null -> empty, drop nulls, dedupe, deterministic order
  SELECT COALESCE(array_agg(DISTINCT x ORDER BY x), '{}'::uuid[])
    INTO v_desired_executors
    FROM unnest(COALESCE(_executor_stakeholder_ids, '{}'::uuid[])) AS t(x)
    WHERE x IS NOT NULL;

  v_all_desired := v_desired_executors;
  IF _requester_stakeholder_id IS NOT NULL THEN
    v_all_desired := v_all_desired || ARRAY[_requester_stakeholder_id];
  END IF;

  -- Validate every desired stakeholder against exact Project/Workspace/Organization
  IF array_length(v_all_desired, 1) IS NOT NULL THEN
    SELECT COALESCE(array_agg(DISTINCT x), '{}'::uuid[])
      INTO v_invalid_ids
      FROM unnest(v_all_desired) AS t(x)
      WHERE NOT EXISTS (
        SELECT 1 FROM public.project_stakeholders ps
        WHERE ps.id = x
          AND ps.project_id = v_task.project_id
          AND ps.workspace_id = v_task.workspace_id
          AND ps.organization_id = v_task.organization_id
      );
    IF array_length(v_invalid_ids, 1) IS NOT NULL THEN
      RETURN public.pmg_build_result(
        'invalid'::public.pmg_command_status, v_command,
        'task', _task_id, v_task.project_id,
        jsonb_build_object(
          'reason','stakeholder_not_in_project',
          'stakeholder_ids', to_jsonb(v_invalid_ids)
        ),
        '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
      );
    END IF;
  END IF;

  -- Former-stakeholder rule: a removed Stakeholder is only acceptable if
  -- already linked to this Task in the same role. New links to removed
  -- stakeholders (including role switches) are rejected.
  IF _requester_stakeholder_id IS NOT NULL AND EXISTS (
    SELECT 1
      FROM public.project_stakeholders ps
      WHERE ps.id = _requester_stakeholder_id
        AND ps.removed_at IS NOT NULL
        AND NOT EXISTS (
          SELECT 1 FROM public.task_stakeholder_roles r
          WHERE r.task_id = _task_id
            AND r.project_stakeholder_id = ps.id
            AND r.role_type = 'requester'::public.task_stakeholder_role_type
        )
  ) THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, v_command,
      'task', _task_id, v_task.project_id,
      jsonb_build_object(
        'reason','former_stakeholder_cannot_be_added',
        'role', 'requester',
        'stakeholder_ids', to_jsonb(ARRAY[_requester_stakeholder_id])
      ),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF EXISTS (
    SELECT 1
      FROM public.project_stakeholders ps
      WHERE ps.removed_at IS NOT NULL
        AND ps.id = ANY(v_desired_executors)
        AND NOT EXISTS (
          SELECT 1 FROM public.task_stakeholder_roles r
          WHERE r.task_id = _task_id
            AND r.project_stakeholder_id = ps.id
            AND r.role_type = 'executor'::public.task_stakeholder_role_type
        )
  ) THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, v_command,
      'task', _task_id, v_task.project_id,
      jsonb_build_object(
        'reason','former_stakeholder_cannot_be_added',
        'role','executor'
      ),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  -- Snapshot current state
  SELECT project_stakeholder_id INTO v_current_requester
    FROM public.task_stakeholder_roles
    WHERE task_id = _task_id
      AND role_type = 'requester'::public.task_stakeholder_role_type;

  SELECT COALESCE(array_agg(project_stakeholder_id ORDER BY project_stakeholder_id), '{}'::uuid[])
    INTO v_current_executors
    FROM public.task_stakeholder_roles
    WHERE task_id = _task_id
      AND role_type = 'executor'::public.task_stakeholder_role_type;

  v_requester_changed := (v_current_requester IS DISTINCT FROM _requester_stakeholder_id);

  SELECT COALESCE(array_agg(x ORDER BY x), '{}'::uuid[]) INTO v_added_executors
    FROM unnest(v_desired_executors) AS t(x)
    WHERE NOT (x = ANY(v_current_executors));
  SELECT COALESCE(array_agg(x ORDER BY x), '{}'::uuid[]) INTO v_removed_executors
    FROM unnest(v_current_executors) AS t(x)
    WHERE NOT (x = ANY(v_desired_executors));

  v_added_any := array_length(v_added_executors, 1) IS NOT NULL;
  v_removed_any := array_length(v_removed_executors, 1) IS NOT NULL;

  v_requester_count := CASE WHEN _requester_stakeholder_id IS NULL THEN 0 ELSE 1 END;
  v_executor_count := COALESCE(array_length(v_desired_executors, 1), 0);

  IF NOT v_requester_changed AND NOT v_added_any AND NOT v_removed_any THEN
    PERFORM public.pmg_record_command_audit(
      'no_change'::public.pmg_command_status, v_command,
      'btpm_ui'::public.pmg_source_channel,
      v_task.project_id, 'task', _task_id, NULL,
      _correlation_id, _idempotency_key,
      jsonb_build_object(
        'workspace_id', v_task.workspace_id,
        'requester_count', v_requester_count,
        'executor_count', v_executor_count
      )
    );
    RETURN public.pmg_build_result(
      'no_change'::public.pmg_command_status, v_command,
      'task', _task_id, v_task.project_id,
      jsonb_build_object(
        'task_id', _task_id,
        'project_id', v_task.project_id,
        'requester_stakeholder_id', _requester_stakeholder_id,
        'executor_stakeholder_ids', to_jsonb(v_desired_executors),
        'requester_count', v_requester_count,
        'executor_count', v_executor_count,
        'updated_at', v_task.updated_at
      ),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  -- Apply the minimal delta atomically.
  IF v_requester_changed AND v_current_requester IS NOT NULL THEN
    DELETE FROM public.task_stakeholder_roles
      WHERE task_id = _task_id
        AND role_type = 'requester'::public.task_stakeholder_role_type;
  END IF;

  IF v_removed_any THEN
    DELETE FROM public.task_stakeholder_roles
      WHERE task_id = _task_id
        AND role_type = 'executor'::public.task_stakeholder_role_type
        AND project_stakeholder_id = ANY(v_removed_executors);
  END IF;

  IF v_requester_changed AND _requester_stakeholder_id IS NOT NULL THEN
    INSERT INTO public.task_stakeholder_roles (task_id, project_stakeholder_id, role_type, created_by)
      VALUES (_task_id, _requester_stakeholder_id, 'requester'::public.task_stakeholder_role_type, v_actor);
  END IF;

  IF v_added_any THEN
    INSERT INTO public.task_stakeholder_roles (task_id, project_stakeholder_id, role_type, created_by)
      SELECT _task_id, x, 'executor'::public.task_stakeholder_role_type, v_actor
        FROM unnest(v_added_executors) AS t(x);
  END IF;

  UPDATE public.tasks SET updated_at = now() WHERE id = _task_id
    RETURNING updated_at INTO v_new_updated_at;

  IF v_requester_changed THEN
    PERFORM public.log_activity_event(
      v_task.organization_id, v_actor,
      'task_requester_changed', 'task', _task_id,
      jsonb_build_object(
        'old_requester_stakeholder_id', v_current_requester,
        'new_requester_stakeholder_id', _requester_stakeholder_id
      ),
      v_task.workspace_id
    );
  END IF;

  IF v_added_any OR v_removed_any THEN
    PERFORM public.log_activity_event(
      v_task.organization_id, v_actor,
      'task_executors_changed', 'task', _task_id,
      jsonb_build_object(
        'added_stakeholder_ids', to_jsonb(v_added_executors),
        'removed_stakeholder_ids', to_jsonb(v_removed_executors)
      ),
      v_task.workspace_id
    );
  END IF;

  PERFORM public.pmg_record_command_audit(
    'applied'::public.pmg_command_status, v_command,
    'btpm_ui'::public.pmg_source_channel,
    v_task.project_id, 'task', _task_id, NULL,
    _correlation_id, _idempotency_key,
    jsonb_build_object(
      'workspace_id', v_task.workspace_id,
      'requester_count', v_requester_count,
      'executor_count', v_executor_count,
      'executors_added_count', COALESCE(array_length(v_added_executors, 1), 0),
      'executors_removed_count', COALESCE(array_length(v_removed_executors, 1), 0),
      'requester_changed', v_requester_changed
    )
  );

  RETURN public.pmg_build_result(
    'applied'::public.pmg_command_status, v_command,
    'task', _task_id, v_task.project_id,
    jsonb_build_object(
      'task_id', _task_id,
      'project_id', v_task.project_id,
      'requester_stakeholder_id', _requester_stakeholder_id,
      'executor_stakeholder_ids', to_jsonb(v_desired_executors),
      'requester_count', v_requester_count,
      'executor_count', v_executor_count,
      'updated_at', v_new_updated_at
    ),
    '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.apply_task_update(_task_id uuid, _expected_updated_at timestamp with time zone, _name text, _description text DEFAULT NULL::text, _status pm_status DEFAULT NULL::pm_status, _priority pm_priority DEFAULT NULL::pm_priority, _task_type task_type DEFAULT NULL::task_type, _estimated_hours numeric DEFAULT NULL::numeric, _correlation_id text DEFAULT NULL::text, _idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_task record;
  v_project_id uuid;
  v_current_description text;
  v_name text;
  v_description text;
  v_new_status public.pm_status;
  v_new_priority public.pm_priority;
  v_new_task_type public.task_type;
  v_new_estimated numeric;
  v_name_changed boolean;
  v_description_changed boolean;
  v_status_changed boolean;
  v_priority_changed boolean;
  v_task_type_changed boolean;
  v_estimated_changed boolean;
  v_changed_count int;
  v_updated record;
  v_updated_description text;
  v_data jsonb;
BEGIN
  IF v_actor IS NULL THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'apply_task_update',
      'task', _task_id, NULL,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF NOT public.is_active_user(v_actor) THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'apply_task_update',
      'task', _task_id, NULL,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF _expected_updated_at IS NULL THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'apply_task_update',
      'task', _task_id, NULL,
      jsonb_build_object('reason','expected_updated_at_required'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  SELECT id, project_id, workspace_id, organization_id, phase_id,
         name, description, status, priority, task_type, estimated_hours, updated_at
    INTO v_task
    FROM public.tasks
   WHERE id = _task_id
   FOR UPDATE;

  IF v_task.id IS NULL THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'apply_task_update',
      'task', _task_id, NULL,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  v_project_id := v_task.project_id;

  IF NOT public.has_project_pm_authority(v_actor, v_project_id)
     OR NOT public.can_write_demo(v_actor, v_task.workspace_id) THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'apply_task_update',
      'task', _task_id, v_project_id,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF v_task.updated_at IS DISTINCT FROM _expected_updated_at THEN
    PERFORM public.pmg_record_command_audit(
      'conflict'::public.pmg_command_status, 'apply_task_update',
      'btpm_ui'::public.pmg_source_channel,
      v_project_id, 'task', _task_id, NULL,
      _correlation_id, _idempotency_key,
      jsonb_build_object('stale', true)
    );
    RETURN public.pmg_build_result(
      'conflict'::public.pmg_command_status, 'apply_task_update',
      'task', _task_id, v_project_id,
      jsonb_build_object(
        'code', 'stale_task',
        'current_updated_at', v_task.updated_at
      ),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF v_task.description IS NULL THEN
    v_current_description := NULL;
  ELSE
    v_current_description := public.btpm_decrypt(v_task.description, v_task.organization_id);
  END IF;

  v_name := btrim(COALESCE(_name, ''));
  IF v_name = '' THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'apply_task_update',
      'task', _task_id, v_project_id,
      jsonb_build_object('reason','name_blank'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF _description IS NULL THEN
    v_description := NULL;
  ELSE
    v_description := btrim(_description);
    IF v_description = '' THEN
      v_description := NULL;
    END IF;
  END IF;

  v_new_status    := COALESCE(_status, v_task.status);
  v_new_priority  := COALESCE(_priority, v_task.priority);
  v_new_task_type := COALESCE(_task_type, v_task.task_type);
  v_new_estimated := _estimated_hours;

  IF v_new_estimated IS NOT NULL AND v_new_estimated < 0 THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'apply_task_update',
      'task', _task_id, v_project_id,
      jsonb_build_object('reason','estimated_hours_negative'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  v_name_changed        := v_name IS DISTINCT FROM v_task.name;
  v_description_changed := v_description IS DISTINCT FROM v_current_description;
  v_status_changed      := v_new_status IS DISTINCT FROM v_task.status;
  v_priority_changed    := v_new_priority IS DISTINCT FROM v_task.priority;
  v_task_type_changed   := v_new_task_type IS DISTINCT FROM v_task.task_type;
  v_estimated_changed   := v_new_estimated IS DISTINCT FROM v_task.estimated_hours;

  v_changed_count :=
      (CASE WHEN v_name_changed        THEN 1 ELSE 0 END)
    + (CASE WHEN v_description_changed THEN 1 ELSE 0 END)
    + (CASE WHEN v_status_changed      THEN 1 ELSE 0 END)
    + (CASE WHEN v_priority_changed    THEN 1 ELSE 0 END)
    + (CASE WHEN v_task_type_changed   THEN 1 ELSE 0 END)
    + (CASE WHEN v_estimated_changed   THEN 1 ELSE 0 END);

  IF v_changed_count = 0 THEN
    v_data := jsonb_build_object(
      'id', v_task.id,
      'project_id', v_project_id,
      'phase_id', v_task.phase_id,
      'name', v_task.name,
      'description', v_current_description,
      'status', v_task.status,
      'priority', v_task.priority,
      'task_type', v_task.task_type,
      'estimated_hours', v_task.estimated_hours,
      'updated_at', v_task.updated_at
    );

    PERFORM public.pmg_record_command_audit(
      'no_change'::public.pmg_command_status, 'apply_task_update',
      'btpm_ui'::public.pmg_source_channel,
      v_project_id, 'task', _task_id, NULL,
      _correlation_id, _idempotency_key,
      jsonb_build_object(
        'changed_field_count', 0,
        'name_changed', false,
        'description_changed', false,
        'status_changed', false,
        'priority_changed', false,
        'task_type_changed', false,
        'estimated_hours_changed', false,
        'stale', false
      )
    );

    RETURN public.pmg_build_result(
      'no_change'::public.pmg_command_status, 'apply_task_update',
      'task', _task_id, v_project_id,
      v_data, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  UPDATE public.tasks
     SET name = v_name,
         description = v_description,
         status = v_new_status,
         priority = v_new_priority,
         task_type = v_new_task_type,
         estimated_hours = v_new_estimated
   WHERE id = _task_id;

  SELECT id, project_id, organization_id, phase_id,
         name, description, status, priority, task_type, estimated_hours, updated_at
    INTO v_updated
    FROM public.tasks
   WHERE id = _task_id;

  IF v_updated.description IS NULL THEN
    v_updated_description := NULL;
  ELSE
    v_updated_description := public.btpm_decrypt(v_updated.description, v_updated.organization_id);
  END IF;

  v_data := jsonb_build_object(
    'id', v_updated.id,
    'project_id', v_updated.project_id,
    'phase_id', v_updated.phase_id,
    'name', v_updated.name,
    'description', v_updated_description,
    'status', v_updated.status,
    'priority', v_updated.priority,
    'task_type', v_updated.task_type,
    'estimated_hours', v_updated.estimated_hours,
    'updated_at', v_updated.updated_at
  );

  PERFORM public.pmg_record_command_audit(
    'applied'::public.pmg_command_status, 'apply_task_update',
    'btpm_ui'::public.pmg_source_channel,
    v_project_id, 'task', _task_id, NULL,
    _correlation_id, _idempotency_key,
    jsonb_build_object(
      'changed_field_count', v_changed_count,
      'name_changed', v_name_changed,
      'description_changed', v_description_changed,
      'status_changed', v_status_changed,
      'priority_changed', v_priority_changed,
      'task_type_changed', v_task_type_changed,
      'estimated_hours_changed', v_estimated_changed,
      'stale', false
    )
  );

  RETURN public.pmg_build_result(
    'applied'::public.pmg_command_status, 'apply_task_update',
    'task', _task_id, v_project_id,
    v_data, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.apply_workspace_binding_validation(_binding_id uuid, _status text, _site_id text, _library_id_or_drive_id text, _site_label_or_name text, _library_label_or_name text, _validation_code text, _validation_note text)
 RETURNS sharepoint_workspace_bindings
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _row public.sharepoint_workspace_bindings;
BEGIN
  IF _uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO _row FROM public.sharepoint_workspace_bindings WHERE id = _binding_id;
  IF _row.id IS NULL THEN
    RAISE EXCEPTION 'Binding not found' USING ERRCODE = 'P0002';
  END IF;

  -- SP authority tightening: Org Admin only.
  IF NOT public.is_org_admin(_uid, _row.organization_id) THEN
    RAISE EXCEPTION 'Forbidden' USING ERRCODE = '42501';
  END IF;

  IF _status NOT IN ('validated', 'invalid') THEN
    RAISE EXCEPTION 'Invalid status: %', _status USING ERRCODE = '22023';
  END IF;

  UPDATE public.sharepoint_workspace_bindings
  SET
    binding_status = _status::sharepoint_workspace_binding_status,
    site_id = COALESCE(_site_id, site_id),
    library_id_or_drive_id = COALESCE(_library_id_or_drive_id, library_id_or_drive_id),
    site_label_or_name = COALESCE(_site_label_or_name, site_label_or_name),
    library_label_or_name = COALESCE(_library_label_or_name, library_label_or_name),
    last_validated_at = now(),
    last_validation_code = _validation_code,
    last_validation_note = _validation_note,
    updated_at = now(),
    updated_by = _uid
  WHERE id = _binding_id
  RETURNING * INTO _row;

  RETURN _row;
END;
$function$

CREATE OR REPLACE FUNCTION public.approve_project_baseline(_project_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_proj public.projects%ROWTYPE;
BEGIN
  SELECT * INTO v_proj FROM public.projects WHERE id = _project_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Project not found'; END IF;
  IF v_proj.is_baselined THEN
    RAISE EXCEPTION 'Project is already baselined. Use rebaseline_project to overwrite.';
  END IF;
  PERFORM public._snapshot_baseline(_project_id);
  PERFORM public.log_activity_event(
    _organization_id => v_proj.organization_id,
    _actor_id        => auth.uid(),
    _event_type      => 'baseline_approved',
    _target_type     => 'project',
    _target_id       => _project_id,
    _metadata        => jsonb_build_object('approved_at', now()),
    _workspace_id    => v_proj.workspace_id
  );
END; $function$

CREATE OR REPLACE FUNCTION public.archive_adoption_initiative(_initiative_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _org uuid; _ws uuid; _proj uuid; _uid uuid := auth.uid();
BEGIN
  IF _uid IS NULL OR NOT public.is_active_user(_uid) THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  SELECT organization_id, workspace_id, project_id INTO _org, _ws, _proj
  FROM public.adoption_initiatives WHERE id = _initiative_id;
  IF _org IS NULL THEN RAISE EXCEPTION 'invalid_initiative'; END IF;
  IF NOT public.has_pm_authority(_uid, _ws) THEN RAISE EXCEPTION 'forbidden'; END IF;

  UPDATE public.adoption_initiatives SET is_archived = true, updated_at = now() WHERE id = _initiative_id;

  PERFORM public.log_activity_event(
    _organization_id => _org, _actor_id => _uid,
    _event_type => 'adoption_initiative_archived',
    _target_type => 'project', _target_id => _proj,
    _metadata => jsonb_build_object('adoption_initiative_id', _initiative_id),
    _workspace_id => _ws
  );
  RETURN _initiative_id;
END $function$

CREATE OR REPLACE FUNCTION public.archive_adoption_template(_template_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _t record;
BEGIN
  IF _uid IS NULL OR NOT public.is_active_user(_uid) THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;
  SELECT * INTO _t FROM public.adoption_templates WHERE id = _template_id;
  IF _t.id IS NULL THEN
    RAISE EXCEPTION 'invalid_template';
  END IF;
  IF _t.is_system THEN
    RAISE EXCEPTION 'system_template_read_only';
  END IF;
  IF NOT public.has_pm_authority(_uid, _t.workspace_id) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  UPDATE public.adoption_templates SET is_archived = true, updated_by = _uid, updated_at = now()
  WHERE id = _template_id;
  RETURN _template_id;
END $function$

CREATE OR REPLACE FUNCTION public.archive_ai_instruction_template(_id uuid)
 RETURNS ai_instruction_templates
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _org_id uuid;
  _row public.ai_instruction_templates;
BEGIN
  SELECT organization_id INTO _org_id FROM public.profiles WHERE id = auth.uid();
  IF _org_id IS NULL OR NOT public.is_org_admin(auth.uid(), _org_id) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO _row FROM public.ai_instruction_templates WHERE id = _id;
  IF _row.id IS NULL THEN RAISE EXCEPTION 'template not found'; END IF;
  IF _row.organization_id <> _org_id THEN RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501'; END IF;

  UPDATE public.ai_instruction_templates
     SET status = 'archived'
   WHERE id = _id
  RETURNING * INTO _row;

  RETURN _row;
END;
$function$

CREATE OR REPLACE FUNCTION public.archive_backlog_item(_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _row backlog_items%ROWTYPE;
BEGIN
  SELECT * INTO _row FROM backlog_items WHERE id = _id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Backlog item not found' USING ERRCODE='P0002'; END IF;
  PERFORM _assert_pm_or_admin(_row.workspace_id, _row.organization_id);
  IF NOT _row.is_archived THEN
    UPDATE backlog_items SET is_archived=true, updated_at=now() WHERE id=_id;
    PERFORM log_activity_event(_row.organization_id, auth.uid(), 'backlog_item_archived', 'backlog_item', _id, '{}'::jsonb, _row.workspace_id);
  END IF;
END; $function$

CREATE OR REPLACE FUNCTION public.archive_board_workflow_state(_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _row board_workflow_states%ROWTYPE;
BEGIN
  SELECT * INTO _row FROM board_workflow_states WHERE id = _id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Workflow state not found' USING ERRCODE='P0002'; END IF;
  PERFORM _assert_pm_or_admin(_row.workspace_id, _row.organization_id);
  IF NOT _row.is_archived THEN
    UPDATE board_workflow_states SET is_archived=true, updated_at=now() WHERE id=_id;
    PERFORM log_activity_event(_row.organization_id, auth.uid(), 'board_workflow_state_archived', 'board_workflow_state', _id, '{}'::jsonb, _row.workspace_id);
  END IF;
END; $function$

CREATE OR REPLACE FUNCTION public.archive_governance_cadence(_cadence_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _row governance_cadences%ROWTYPE;
BEGIN
  SELECT * INTO _row FROM governance_cadences WHERE id = _cadence_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Cadence not found' USING ERRCODE='P0002'; END IF;
  PERFORM _gov_assert_project_write(_row.project_id);
  IF _row.archived_at IS NULL THEN
    UPDATE governance_cadences SET archived_at = now(), archived_by = auth.uid(), updated_at = now()
    WHERE id = _cadence_id;
    PERFORM log_activity_event(_row.organization_id, auth.uid(),
      'governance_cadence_archived', 'governance_cadence', _cadence_id,
      jsonb_build_object('project_id', _row.project_id), _row.workspace_id);
  END IF;
END; $function$

CREATE OR REPLACE FUNCTION public.archive_governance_record(_record_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _row governance_records%ROWTYPE;
BEGIN
  SELECT * INTO _row FROM governance_records WHERE id = _record_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Record not found' USING ERRCODE='P0002'; END IF;
  PERFORM _gov_assert_project_write(_row.project_id);
  IF _row.archived_at IS NULL THEN
    UPDATE governance_records SET archived_at = now(), archived_by = auth.uid(), updated_at = now()
    WHERE id = _record_id;
    PERFORM log_activity_event(_row.organization_id, auth.uid(),
      'governance_record_archived', 'governance_record', _record_id,
      jsonb_build_object('project_id', _row.project_id), _row.workspace_id);
  END IF;
END; $function$

CREATE OR REPLACE FUNCTION public.archive_governance_record_btpm_context_link(_context_link_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE _ln public.governance_record_btpm_context_links%ROWTYPE; _row public.governance_records%ROWTYPE;
BEGIN
  SELECT * INTO _ln FROM public.governance_record_btpm_context_links WHERE id = _context_link_id;
