CREATE OR REPLACE FUNCTION public.archive_project_benefit(_benefit_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE _b public.project_benefits%ROWTYPE; _proj_status text;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE='42501';
  END IF;

  SELECT * INTO _b FROM public.project_benefits WHERE id = _benefit_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Benefit not found' USING ERRCODE='P0002';
  END IF;
  IF NOT public.has_project_pm_authority(auth.uid(), _b.project_id) THEN
    RAISE EXCEPTION 'Project-edit authority required' USING ERRCODE='42501';
  END IF;

  IF _b.archived_at IS NOT NULL THEN
    RETURN; -- idempotent
  END IF;

  SELECT status::text INTO _proj_status FROM public.projects WHERE id = _b.project_id;

  UPDATE public.project_benefits
     SET archived_at = now(),
         updated_by = auth.uid(),
         updated_at = now()
   WHERE id = _benefit_id;

  PERFORM public.log_activity_event(
    _b.organization_id, auth.uid(),
    'project_benefit_archived', 'project_benefit', _benefit_id,
    jsonb_build_object(
      'project_id', _b.project_id,
      'project_status_at_event', _proj_status,
      'post_closure', (_proj_status IN ('completed','cancelled'))
    ),
    _b.workspace_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.archive_project_people_preset(_preset_id uuid, _expected_updated_at timestamp with time zone, _correlation_id text DEFAULT NULL::text, _idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_preset public.project_people_presets;
BEGIN
  SELECT * INTO v_preset FROM public.project_people_presets WHERE id = _preset_id FOR UPDATE;
  IF v_preset.id IS NULL THEN
    RETURN public.pmg_build_result('not_authorized', 'archive_project_people_preset',
      'project_people_preset', NULL, NULL, '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL);
  END IF;
  PERFORM public._ppp_authorize_write(v_actor, v_preset, true);

  IF v_preset.updated_at IS DISTINCT FROM _expected_updated_at THEN
    RETURN public.pmg_build_result('conflict', 'archive_project_people_preset',
      'project_people_preset', _preset_id, NULL, '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb,
      jsonb_build_object('server_updated_at', v_preset.updated_at));
  END IF;

  UPDATE public.project_people_presets
     SET archived_at = now(), archived_by = v_actor
   WHERE id = _preset_id;

  PERFORM public._ppp_record_audit('applied', 'archive_project_people_preset',
    v_preset, 'project_people_preset', _preset_id, _correlation_id, _idempotency_key, '{}'::jsonb);

  RETURN public.pmg_build_result('applied', 'archive_project_people_preset',
    'project_people_preset', _preset_id, NULL,
    jsonb_build_object('id', _preset_id),
    '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL);
END; $function$

