CREATE OR REPLACE FUNCTION public.assert_environment_action_allowed(_organization_id uuid, _action text, _reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _o public.organizations;
  _is_prod boolean;
  _actor uuid := auth.uid();
  _allowed boolean;
  _known_actions text[] := ARRAY[
    'outbound_email','external_api_write','real_integration',
    'export','export_without_watermark','storage_write','background_job_enqueue'
  ];
BEGIN
  IF _organization_id IS NULL THEN
    RAISE EXCEPTION 'environment_action_blocked: organization_id is required' USING ERRCODE='42501';
  END IF;
  IF _action IS NULL OR NOT (_action = ANY(_known_actions)) THEN
    RAISE EXCEPTION 'environment_action_blocked: unknown action %', _action USING ERRCODE='42501';
  END IF;

  SELECT * INTO _o FROM public.organizations WHERE id = _organization_id;
  IF _o.id IS NULL THEN
    RAISE EXCEPTION 'environment_action_blocked: organization % not found', _organization_id USING ERRCODE='42501';
  END IF;

  IF _actor IS NOT NULL THEN
    IF NOT (
      public.is_platform_super_admin(_actor)
      OR public.is_tenant_admin(_o.tenant_id, _actor)
      OR public.is_organization_member(_o.id, _actor)
    ) THEN
      RAISE EXCEPTION 'environment_action_blocked: not authorized on organization %', _organization_id USING ERRCODE='42501';
    END IF;
  END IF;

  _is_prod := (_o.environment_role = 'production');
  _allowed := CASE _action
    WHEN 'outbound_email'           THEN _is_prod
    WHEN 'external_api_write'       THEN _is_prod
    WHEN 'real_integration'         THEN _is_prod
    WHEN 'export'                   THEN true
    WHEN 'export_without_watermark' THEN _is_prod
    WHEN 'storage_write'            THEN true
    WHEN 'background_job_enqueue'   THEN true
    ELSE false
  END;

  IF NOT _allowed THEN
    RAISE EXCEPTION 'environment_action_blocked: action % is not allowed in environment_role=% (organization %)',
      _action, _o.environment_role, _organization_id USING ERRCODE='42501';
  END IF;

  RETURN jsonb_build_object(
    'allowed', true,
    'organization_id', _o.id,
    'tenant_id', _o.tenant_id,
    'environment_role', _o.environment_role,
    'action', _action,
    'reason', _reason
  );
END $function$

CREATE OR REPLACE FUNCTION public.assign_project_portfolio(_project_id uuid, _portfolio_item_id uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _p_org uuid;
  _p_ws  uuid;
  _current uuid;
  _pi_org uuid;
  _pi_archived boolean;
BEGIN
  IF _uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF NOT public.is_active_user(_uid) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;

  SELECT organization_id, workspace_id, portfolio_item_id
    INTO _p_org, _p_ws, _current
    FROM public.projects WHERE id = _project_id;
  IF _p_org IS NULL THEN RAISE EXCEPTION 'Project not found'; END IF;

  IF NOT public.has_project_pm_authority(_uid, _project_id) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;
  IF NOT public.can_write_demo(_uid, _p_ws) THEN
    RAISE EXCEPTION 'Demo workspace is read-only';
  END IF;

  IF _portfolio_item_id IS NOT NULL THEN
    SELECT organization_id, is_archived
      INTO _pi_org, _pi_archived
      FROM public.portfolio_items WHERE id = _portfolio_item_id;
    IF _pi_org IS NULL THEN RAISE EXCEPTION 'Portfolio item not found'; END IF;
    IF _pi_org <> _p_org THEN RAISE EXCEPTION 'Portfolio item belongs to a different organization'; END IF;
    IF _pi_archived THEN RAISE EXCEPTION 'Portfolio item is archived'; END IF;
  END IF;

  IF _current IS NOT DISTINCT FROM _portfolio_item_id THEN
    RETURN;
  END IF;

  UPDATE public.projects
     SET portfolio_item_id = _portfolio_item_id
   WHERE id = _project_id;

  PERFORM public.log_activity_event(
    _p_org, _uid, 'project_portfolio_changed', 'project', _project_id,
    jsonb_build_object(
      'old_portfolio_item_id', _current,
      'new_portfolio_item_id', _portfolio_item_id
    ),
    _p_ws
  );
END;
$function$

