CREATE OR REPLACE FUNCTION public.auto_accept_pending_invitations(_user_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _email text;
  _inv_id uuid;
  _count integer := 0;
BEGIN
  SELECT lower(au.email) INTO _email FROM auth.users au WHERE au.id = _user_id;
  IF _email IS NULL THEN RETURN 0; END IF;

  FOR _inv_id IN
    SELECT i.id
    FROM public.invitations i
    WHERE lower(i.email) = _email
      AND i.status = 'pending'
      AND i.expires_at > now()
    ORDER BY i.created_at
  LOOP
    BEGIN
      PERFORM public.accept_pending_invitation_for_user(_user_id, _inv_id);
      _count := _count + 1;
    EXCEPTION WHEN OTHERS THEN
      RAISE NOTICE 'auto_accept skipped invitation %: %', _inv_id, SQLERRM;
    END;
  END LOOP;

  RETURN _count;
END $function$

CREATE OR REPLACE FUNCTION public.bootstrap_organization(_name text, _slug text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _user_id uuid; _tenant uuid; _tenant_count int;
BEGIN
  _user_id := auth.uid();
  IF _user_id IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF NOT public.is_active_user(_user_id) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;
  SELECT tenant_id, count(*) OVER() INTO _tenant, _tenant_count
  FROM public.tenant_memberships
  WHERE user_id = _user_id AND status='active' AND role IN ('tenant_owner','tenant_admin')
  LIMIT 1;
  IF _tenant IS NULL AND public.is_platform_super_admin(_user_id) THEN
    SELECT id, count(*) OVER() INTO _tenant, _tenant_count
    FROM public.tenants WHERE status='active' LIMIT 1;
  END IF;
  IF _tenant IS NULL OR _tenant_count IS DISTINCT FROM 1 THEN
    RAISE EXCEPTION 'bootstrap_organization requires a single unambiguous tenant scope. Use bootstrap_organization_for_tenant(_tenant_id, ...).';
  END IF;
  RETURN public.bootstrap_organization_for_tenant(_tenant, _name, _slug);
END $function$

CREATE OR REPLACE FUNCTION public.bootstrap_organization_for_tenant(_tenant_id uuid, _name text, _slug text, _organization_kind organization_kind DEFAULT 'production'::organization_kind, _environment_role environment_role DEFAULT 'production'::environment_role)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _org_id uuid; _user_id uuid;
BEGIN
  _user_id := auth.uid();
  IF _user_id IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF NOT public.is_active_user(_user_id) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;
  IF NOT (public.is_platform_super_admin(_user_id) OR public.is_tenant_admin(_tenant_id, _user_id)) THEN
    RAISE EXCEPTION 'Access denied: requires Platform Super Admin or Tenant Owner/Admin';
  END IF;
  INSERT INTO public.organizations (tenant_id, name, slug, organization_kind, environment_role, created_by)
  VALUES (_tenant_id, _name, _slug, _organization_kind, _environment_role, _user_id)
  RETURNING id INTO _org_id;
  IF public.is_tenant_member(_tenant_id, _user_id) THEN
    INSERT INTO public.organization_memberships (tenant_id, organization_id, user_id, role, status, created_by)
    VALUES (_tenant_id, _org_id, _user_id, 'org_admin', 'active', _user_id)
    ON CONFLICT (organization_id, user_id) DO NOTHING;
  END IF;
  RETURN _org_id;
END $function$

CREATE OR REPLACE FUNCTION public.bulk_set_powerbi_workspace_scope(_organization_id uuid, _workspace_ids uuid[], _scope_mode text, _reason text DEFAULT NULL::text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_id uuid;
  v_count integer := 0;
  v_invalid integer;
BEGIN
  IF v_uid IS NULL OR NOT public.is_org_admin(v_uid, _organization_id) THEN
    RAISE EXCEPTION 'Org Admin only';
  END IF;
  IF _scope_mode NOT IN ('included','excluded') THEN
    RAISE EXCEPTION 'Invalid scope_mode for workspace rule';
  END IF;

  SELECT count(*) INTO v_invalid
  FROM unnest(_workspace_ids) wid
  WHERE NOT EXISTS (
    SELECT 1 FROM public.workspaces w
    WHERE w.id = wid AND w.organization_id = _organization_id
  );
  IF v_invalid > 0 THEN
    RAISE EXCEPTION 'One or more workspaces do not belong to organization';
  END IF;

  FOREACH v_id IN ARRAY _workspace_ids LOOP
    PERFORM public.set_powerbi_workspace_scope(_organization_id, v_id, _scope_mode, _reason);
    v_count := v_count + 1;
  END LOOP;

  RETURN v_count;
END;
$function$

CREATE OR REPLACE FUNCTION public.can_capture_kpi_snapshot(_kpi_definition_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _ws_id uuid;
  _org_id uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN false;
  END IF;

  SELECT kd.workspace_id, kd.organization_id
    INTO _ws_id, _org_id
  FROM kpi_definitions kd
  WHERE kd.id = _kpi_definition_id
    AND kd.is_archived = false;

  IF _ws_id IS NULL THEN
    RETURN false;
  END IF;

  -- Mirror the prior kpi_snap_insert_pm predicate exactly.
  RETURN
    is_active_user(auth.uid())
    AND has_pm_authority(auth.uid(), _ws_id)
    AND _org_id = get_user_org_id(auth.uid())
    AND can_write_demo(auth.uid(), _ws_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.can_view_roadmap_story_presentation_version(_version_id uuid, _user_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _v public.roadmap_story_presentation_versions;
  _p public.roadmap_story_presentations;
  _pack public.roadmap_story_packs;
  _user_org uuid;
  _proj record;
  _project_count integer := 0;
BEGIN
  IF _user_id IS NULL OR NOT public.is_active_user(_user_id) THEN
    RETURN false;
  END IF;

  SELECT * INTO _v FROM public.roadmap_story_presentation_versions WHERE id = _version_id;
  IF NOT FOUND OR _v.status <> 'active' THEN
    RETURN false;
  END IF;

  SELECT * INTO _p FROM public.roadmap_story_presentations WHERE id = _v.presentation_id;
  IF NOT FOUND OR _p.status <> 'active' THEN
    RETURN false;
  END IF;

  SELECT organization_id INTO _user_org FROM public.profiles WHERE id = _user_id;
  IF _user_org IS NULL OR _user_org <> _v.organization_id THEN
    RETURN false;
  END IF;

  SELECT * INTO _pack FROM public.roadmap_story_packs WHERE id = _v.story_pack_id;

  SELECT count(*) INTO _project_count
    FROM public.roadmap_story_presentation_version_projects
   WHERE presentation_version_id = _version_id;

  IF _project_count = 0 THEN
    -- No project scope recorded: owner/publisher only, never broad access.
    RETURN (_v.published_by = _user_id)
        OR (_pack.id IS NOT NULL AND _pack.created_by = _user_id);
  END IF;

  -- All-source-projects: AND, not OR. Any missing access -> deny.
  FOR _proj IN
    SELECT project_id
      FROM public.roadmap_story_presentation_version_projects
     WHERE presentation_version_id = _version_id
  LOOP
    IF NOT public.has_project_access(_user_id, _proj.project_id) THEN
      RETURN false;
    END IF;
  END LOOP;

  RETURN true;
END;
$function$

CREATE OR REPLACE FUNCTION public.clone_phase_in_project(_phase_id uuid, _new_phase_name text, _phase_start_date date DEFAULT NULL::date, _confirm_widening boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _caller uuid := auth.uid();
  _src_phase RECORD;
  _proj RECORD;
  _preview jsonb;
  _bp jsonb;
  _phase_obj jsonb;
  _tk jsonb; _dep jsonb;
  _new_phase_id uuid; _new_id uuid;
  _task_map jsonb := '{}'::jsonb;
  _start_off int; _end_off int; _due_off int;
  _ph_start date; _ph_end date;
  _t_start date; _t_due date;
  _next_sort int;
  _did_widen boolean := false;
  _new_proj_start date; _new_proj_end date;
  _task_count int := 0; _dep_count int := 0;
  _src_id uuid; _tgt_id uuid;
  _dep_entity text;
BEGIN
  IF _caller IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF _new_phase_name IS NULL OR length(btrim(_new_phase_name)) = 0 THEN
    RAISE EXCEPTION 'New phase name is required';
  END IF;

  SELECT * INTO _src_phase FROM public.phases WHERE id = _phase_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Phase not found'; END IF;

  IF NOT public.has_pm_authority(_caller, _src_phase.workspace_id) THEN
    RAISE EXCEPTION 'PM authority required';
  END IF;

  SELECT * INTO _proj FROM public.projects WHERE id = _src_phase.project_id;

  _preview := public.preview_phase_clone_in_project(_phase_id, _phase_start_date);
  IF (_preview->>'requires_widening')::boolean AND NOT _confirm_widening THEN
    RAISE EXCEPTION 'BTPM_REQUIRES_WIDENING:%',
      (_preview || jsonb_build_object('scope','phase_clone'))::text
      USING ERRCODE = 'check_violation';
  END IF;

  _bp := public.preview_phase_clone_blueprint(_phase_id);
  _phase_obj := COALESCE(_bp->'phase', '{}'::jsonb);

  IF (_preview->>'requires_widening')::boolean AND _confirm_widening THEN
    _new_proj_start := NULLIF(_preview->>'parent_proposed_start','')::date;
    _new_proj_end   := NULLIF(_preview->>'parent_proposed_end','')::date;

    PERFORM set_config('app.allow_planned_extension','on', true);
    UPDATE public.projects
       SET start_date = _new_proj_start,
           target_end_date = _new_proj_end,
           updated_at = now()
     WHERE id = _proj.id;

    BEGIN
      PERFORM public.log_activity_event(
        _caller, 'project_extended_for_phase_clone',
        jsonb_build_object(
          'old_start', _proj.start_date,
          'old_end',   _proj.target_end_date,
          'new_start', _new_proj_start,
          'new_end',   _new_proj_end,
          'trigger_phase_id', _phase_id
        ),
        _proj.organization_id, _proj.id, 'project', _proj.workspace_id
      );
    EXCEPTION WHEN OTHERS THEN NULL; END;

    _did_widen := true;
  END IF;

  IF _phase_start_date IS NULL OR (_bp->>'schedule_mode') <> 'relative' THEN
    _ph_start := _phase_start_date;
    _ph_end := NULL;
  ELSE
    _start_off := NULLIF(_phase_obj->'schedule'->>'start_offset_days','')::int;
    _end_off   := NULLIF(_phase_obj->'schedule'->>'target_end_offset_days','')::int;
    _ph_start := CASE WHEN _start_off IS NOT NULL THEN _phase_start_date + _start_off ELSE _phase_start_date END;
    _ph_end   := CASE WHEN _end_off   IS NOT NULL THEN _phase_start_date + _end_off   ELSE NULL END;
  END IF;

  UPDATE public.phases
     SET sort_order = sort_order + 1, updated_at = now()
   WHERE project_id = _src_phase.project_id
     AND sort_order > _src_phase.sort_order;

  _next_sort := _src_phase.sort_order + 1;

  IF (_preview->>'requires_widening')::boolean AND _confirm_widening THEN
    PERFORM set_config('app.allow_planned_extension','on', true);
  END IF;

  INSERT INTO public.phases (
    organization_id, workspace_id, project_id,
    name, description, phase_type, sort_order,
    status, is_archived, start_date, target_end_date, created_by
  ) VALUES (
    _src_phase.organization_id, _src_phase.workspace_id, _src_phase.project_id,
    _new_phase_name,
    NULLIF(_phase_obj->>'description',''),
    COALESCE((_phase_obj->>'phase_type')::phase_type, 'work_item'::phase_type),
    _next_sort,
    'planned'::pm_status, false,
    _ph_start, _ph_end, _caller
  ) RETURNING id INTO _new_phase_id;

  FOR _tk IN SELECT * FROM jsonb_array_elements(COALESCE(_bp->'tasks','[]'::jsonb)) LOOP
    IF _phase_start_date IS NULL OR (_bp->>'schedule_mode') <> 'relative' THEN
      _t_start := NULL; _t_due := NULL;
    ELSE
      _start_off := NULLIF(_tk->'schedule'->>'start_offset_days','')::int;
      _due_off   := NULLIF(_tk->'schedule'->>'due_offset_days','')::int;
      _t_start := CASE WHEN _start_off IS NOT NULL THEN _phase_start_date + _start_off ELSE NULL END;
      _t_due   := CASE WHEN _due_off   IS NOT NULL THEN _phase_start_date + _due_off   ELSE NULL END;
    END IF;

    INSERT INTO public.tasks (
      organization_id, workspace_id, project_id, phase_id,
      name, description, task_type, priority, status,
      sort_order, estimated_hours, is_archived,
      start_date, due_date, created_by
    ) VALUES (
      _src_phase.organization_id, _src_phase.workspace_id, _src_phase.project_id, _new_phase_id,
      COALESCE(NULLIF(_tk->>'name',''), 'Task'),
      NULLIF(_tk->>'description',''),
      COALESCE((_tk->>'task_type')::task_type, 'work_item'::task_type),
      COALESCE((_tk->>'priority')::pm_priority, 'medium'::pm_priority),
      'planned'::pm_status,
      COALESCE((_tk->>'sort_order')::int, 0),
      NULLIF(_tk->>'estimated_hours','')::numeric,
      false, _t_start, _t_due, _caller
    ) RETURNING id INTO _new_id;
    _task_map := _task_map || jsonb_build_object(_tk->>'ref', _new_id::text);
    _task_count := _task_count + 1;
  END LOOP;

  -- Internal task↔task dependencies — read canonical `entity_type` (legacy fallback kept).
  FOR _dep IN SELECT * FROM jsonb_array_elements(COALESCE(_bp->'dependencies','[]'::jsonb)) LOOP
    _dep_entity := COALESCE(_dep->>'entity_type', _dep->>'source_type');
    IF _dep_entity = 'task' THEN
      _src_id := NULLIF(_task_map->>(_dep->>'source_ref'),'')::uuid;
      _tgt_id := NULLIF(_task_map->>(_dep->>'target_ref'),'')::uuid;
      IF _src_id IS NOT NULL AND _tgt_id IS NOT NULL THEN
        INSERT INTO public.dependencies (
          organization_id, workspace_id,
          source_type, source_id, target_type, target_id,
          dependency_type, description, created_by
        ) VALUES (
          _src_phase.organization_id, _src_phase.workspace_id,
          'task', _src_id, 'task', _tgt_id,
          COALESCE((_dep->>'dependency_type')::dependency_type, 'finish_to_start'::dependency_type),
          NULLIF(_dep->>'description',''), _caller
        );
        _dep_count := _dep_count + 1;
      END IF;
    END IF;
  END LOOP;

  PERFORM set_config('app.allow_planned_extension','off', true);

  BEGIN
    PERFORM public.log_activity_event(
      _caller, 'phase_cloned',
      jsonb_build_object(
        'source_phase_id', _phase_id,
        'new_phase_id', _new_phase_id,
        'widened', _did_widen
      ),
      _src_phase.organization_id, _new_phase_id, 'phase', _src_phase.workspace_id
    );
  EXCEPTION WHEN OTHERS THEN NULL; END;

  RETURN jsonb_build_object(
    'phase_id', _new_phase_id,
    'project_id', _src_phase.project_id,
    'workspace_id', _src_phase.workspace_id,
    'widened', _did_widen,
    'created_counts', jsonb_build_object('tasks', _task_count, 'dependencies', _dep_count)
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.clone_task_in_phase(_task_id uuid, _new_task_name text, _task_start_date date DEFAULT NULL::date, _confirm_widening boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _caller uuid := auth.uid();
  _src_task RECORD;
  _phase RECORD;
  _preview jsonb;
  _bp jsonb;
  _task_obj jsonb;
  _new_task_id uuid;
  _start_off int; _due_off int;
  _t_start date; _t_due date;
  _next_sort int;
  _did_widen boolean := false;
  _new_ph_start date; _new_ph_end date;
BEGIN
  IF _caller IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF _new_task_name IS NULL OR length(btrim(_new_task_name)) = 0 THEN
    RAISE EXCEPTION 'New task name is required';
  END IF;

  SELECT * INTO _src_task FROM public.tasks WHERE id = _task_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Task not found'; END IF;

  IF NOT public.has_pm_authority(_caller, _src_task.workspace_id) THEN
    RAISE EXCEPTION 'PM authority required';
  END IF;

  SELECT * INTO _phase FROM public.phases WHERE id = _src_task.phase_id;

  _preview := public.preview_task_clone_in_phase(_task_id, _task_start_date);
  IF (_preview->>'requires_widening')::boolean AND NOT _confirm_widening THEN
    RAISE EXCEPTION 'BTPM_REQUIRES_WIDENING:%',
      (_preview || jsonb_build_object('scope','task_clone'))::text
      USING ERRCODE = 'check_violation';
  END IF;

  _bp := public.preview_task_clone_blueprint(_task_id);
  _task_obj := COALESCE(_bp->'task', '{}'::jsonb);

  -- Widen parent phase first if confirmed (which itself may need to extend project — use apply RPC chain)
  IF (_preview->>'requires_widening')::boolean AND _confirm_widening THEN
    _new_ph_start := NULLIF(_preview->>'parent_proposed_start','')::date;
    _new_ph_end   := NULLIF(_preview->>'parent_proposed_end','')::date;

    -- Use apply_phase_planning_change so 4F.3 cascades to project if needed
    PERFORM public.apply_phase_planning_change(
      _phase.id, _new_ph_start, _new_ph_end, true
    );

    BEGIN
      PERFORM public.log_activity_event(
        _caller, 'phase_extended_for_task_clone',
        jsonb_build_object(
          'old_start', _phase.start_date,
          'old_end',   _phase.target_end_date,
          'new_start', _new_ph_start,
          'new_end',   _new_ph_end,
          'trigger_task_id', _task_id
        ),
        _phase.organization_id, _phase.id, 'phase', _phase.workspace_id
      );
    EXCEPTION WHEN OTHERS THEN NULL; END;

    _did_widen := true;
  END IF;

  -- Compute new task dates
  IF _task_start_date IS NULL OR (_bp->>'schedule_mode') <> 'relative' THEN
    _t_start := _task_start_date;
    _t_due := NULL;
  ELSE
    _start_off := NULLIF(_task_obj->'schedule'->>'start_offset_days','')::int;
    _due_off   := NULLIF(_task_obj->'schedule'->>'due_offset_days','')::int;
    _t_start := CASE WHEN _start_off IS NOT NULL THEN _task_start_date + _start_off ELSE _task_start_date END;
    _t_due   := CASE WHEN _due_off   IS NOT NULL THEN _task_start_date + _due_off   ELSE NULL END;
  END IF;

  -- Shift sibling sort_order +1
  UPDATE public.tasks
     SET sort_order = sort_order + 1, updated_at = now()
   WHERE phase_id = _src_task.phase_id
     AND sort_order > _src_task.sort_order;

  _next_sort := _src_task.sort_order + 1;

  INSERT INTO public.tasks (
    organization_id, workspace_id, project_id, phase_id,
    name, description, task_type, priority, status,
    sort_order, estimated_hours, is_archived,
    start_date, due_date, created_by
  ) VALUES (
    _src_task.organization_id, _src_task.workspace_id, _src_task.project_id, _src_task.phase_id,
    _new_task_name,
    NULLIF(_task_obj->>'description',''),
    COALESCE((_task_obj->>'task_type')::task_type, 'work_item'::task_type),
    COALESCE((_task_obj->>'priority')::pm_priority, 'medium'::pm_priority),
    'planned'::pm_status,
    _next_sort,
    NULLIF(_task_obj->>'estimated_hours','')::numeric,
    false, _t_start, _t_due, _caller
  ) RETURNING id INTO _new_task_id;

  BEGIN
    PERFORM public.log_activity_event(
      _caller, 'task_cloned',
      jsonb_build_object(
        'source_task_id', _task_id,
        'new_task_id', _new_task_id,
        'widened', _did_widen
      ),
      _src_task.organization_id, _new_task_id, 'task', _src_task.workspace_id
    );
  EXCEPTION WHEN OTHERS THEN NULL; END;

  RETURN jsonb_build_object(
    'task_id', _new_task_id,
    'phase_id', _src_task.phase_id,
    'project_id', _src_task.project_id,
    'workspace_id', _src_task.workspace_id,
    'widened', _did_widen
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.close_governance_decision_case(_record_id uuid, _closure_note text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  _row public.governance_records%ROWTYPE;
  _outcome_id uuid;
  _outcome_closed_at timestamptz;
  _note text;
BEGIN
  SELECT * INTO _row FROM public.governance_records WHERE id = _record_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Record not found' USING ERRCODE='P0002'; END IF;
  IF _row.record_kind IS DISTINCT FROM 'decision_case' THEN
    RAISE EXCEPTION 'Only decision_case records can be closed' USING ERRCODE='22023';
  END IF;
  PERFORM public._gov_assert_project_write(_row.project_id);

  IF _row.decision_stage = 'closed' THEN
    RAISE EXCEPTION 'Decision case is already closed' USING ERRCODE='22023';
  END IF;

  SELECT id, closed_at INTO _outcome_id, _outcome_closed_at
    FROM public.governance_record_decision_outcomes
   WHERE governance_record_id = _record_id;
  IF _outcome_id IS NULL THEN
    RAISE EXCEPTION 'A decision outcome must be recorded before closing the decision case' USING ERRCODE='22023';
  END IF;
  IF _outcome_closed_at IS NOT NULL THEN
    RAISE EXCEPTION 'Decision case is already closed' USING ERRCODE='22023';
  END IF;

  _note := NULLIF(trim(COALESCE(_closure_note, '')), '');

  UPDATE public.governance_record_decision_outcomes
     SET closure_note = COALESCE(_note, closure_note),
         closed_at = now(),
         closed_by = auth.uid(),
         updated_by = auth.uid(),
         updated_at = now()
   WHERE id = _outcome_id;

  UPDATE public.governance_records
     SET decision_stage = 'closed', updated_at = now()
   WHERE id = _record_id;

  PERFORM public.log_activity_event(_row.organization_id, auth.uid(),
    'governance_record_decision_case_closed', 'governance_record', _record_id,
    jsonb_build_object('project_id', _row.project_id,
                       'decision_outcome_id', _outcome_id,
                       'closure_note_present', _note IS NOT NULL),
    _row.workspace_id);
END; $function$

CREATE OR REPLACE FUNCTION public.commit_btpm_import_v1_core(_organization_id uuid, _workspace_id uuid, _dry_run_batch_id uuid, _payload jsonb, _payload_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  _user uuid := auth.uid();
  _batch record;
  _ws record;
  _rec jsonb;
  _pid uuid;
  _existing uuid;
  _prog_id uuid;
  _proj_uuid uuid;
  _phase_uuid uuid;
  _task_uuid uuid;
  _target_uuid uuid;
  _target_type text;
  _target_key text;
  _uid uuid;
  _email text;
  _idx int;
  _rowc int;
  _programs_created int := 0;
  _programs_reused int := 0;
  _projects_created int := 0;
  _phases_created int := 0;
  _tasks_created int := 0;
  _team_created int := 0;
  _asg_created int := 0;
  _risks_created int := 0;
  _blockers_created int := 0;
  _updates_created int := 0;
  _stakeholders_created int := 0;
  _requester_links int := 0;
  _executor_links int := 0;
  _program_map jsonb := '{}'::jsonb;
  _project_map jsonb := '{}'::jsonb;
  _phase_map jsonb := '{}'::jsonb;
  _task_map jsonb := '{}'::jsonb;
  _stakeholder_map jsonb := '{}'::jsonb;
  _created_programs jsonb := '[]'::jsonb;
  _created_projects jsonb := '[]'::jsonb;
  _created_phases jsonb := '[]'::jsonb;
  _created_tasks jsonb := '[]'::jsonb;
  _profile_active boolean;
  _is_v2 boolean;
  _stype text;
  _ex_name text;
  _role_label text;
  _notes text;
  _req_key text;
  _exec_keys jsonb;
  _exec_key text;
  _req_sid uuid;
  _exec_ids uuid[];
  _seen_execs uuid[];
  _accountability_result jsonb;
  _accountability_status text;
  _task_updated_at timestamptz;
BEGIN
  IF _user IS NULL THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;

  SELECT is_active INTO _profile_active FROM public.profiles WHERE id = _user;
  IF _profile_active IS DISTINCT FROM true THEN
    RAISE EXCEPTION 'inactive_user';
  END IF;

  IF NOT public.is_org_admin(_user, _organization_id) THEN
    RAISE EXCEPTION 'org_admin_required';
  END IF;

  SELECT * INTO _ws FROM public.workspaces WHERE id = _workspace_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'workspace_not_found'; END IF;
  IF _ws.organization_id <> _organization_id THEN RAISE EXCEPTION 'workspace_not_in_org'; END IF;
  IF _ws.is_archived OR _ws.is_active = false THEN RAISE EXCEPTION 'workspace_archived_or_inactive'; END IF;

  SELECT * INTO _batch FROM public.btpm_import_batches WHERE id = _dry_run_batch_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'dry_run_batch_not_found'; END IF;
  IF _batch.organization_id <> _organization_id OR _batch.workspace_id <> _workspace_id THEN
    RAISE EXCEPTION 'dry_run_batch_not_valid';
  END IF;
  IF _batch.requested_by <> _user THEN RAISE EXCEPTION 'dry_run_batch_not_valid'; END IF;
  IF _batch.committed_at IS NOT NULL THEN RAISE EXCEPTION 'dry_run_already_committed'; END IF;
  IF _batch.status <> 'dry_run_valid' THEN RAISE EXCEPTION 'dry_run_batch_not_valid'; END IF;
  IF _batch.payload_hash <> _payload_hash THEN RAISE EXCEPTION 'dry_run_payload_mismatch'; END IF;
  IF _batch.schema_version <> COALESCE(_payload->>'schema_version','') THEN RAISE EXCEPTION 'dry_run_payload_mismatch'; END IF;
  IF _batch.import_type <> COALESCE(_payload->>'import_type','') THEN RAISE EXCEPTION 'dry_run_payload_mismatch'; END IF;

  _is_v2 := (_batch.schema_version = 'btpm_import_v2');

  FOR _rec IN SELECT value FROM jsonb_array_elements(COALESCE(_payload->'programs','[]'::jsonb)) AS t(value) LOOP
    SELECT id INTO _existing FROM public.programs
      WHERE workspace_id = _workspace_id AND name = _rec->>'name' AND is_archived = false LIMIT 1;
    IF _existing IS NOT NULL THEN
      _programs_reused := _programs_reused + 1;
      _pid := _existing;
    ELSE
      INSERT INTO public.programs(organization_id, workspace_id, name, description, status, created_by)
      VALUES (_organization_id, _workspace_id, _rec->>'name', NULLIF(_rec->>'description',''),
              COALESCE(NULLIF(_rec->>'status','')::pm_status, 'planned'::pm_status), _user)
      RETURNING id INTO _pid;
      _programs_created := _programs_created + 1;
      _created_programs := _created_programs || jsonb_build_array(jsonb_build_object('id',_pid,'external_key',_rec->>'external_key'));
    END IF;
    _program_map := _program_map || jsonb_build_object(_rec->>'external_key', to_jsonb(_pid));
  END LOOP;

  FOR _rec IN SELECT value FROM jsonb_array_elements(COALESCE(_payload->'projects','[]'::jsonb)) AS t(value) LOOP
    IF EXISTS (SELECT 1 FROM public.projects WHERE workspace_id = _workspace_id AND name = _rec->>'name' AND is_archived = false) THEN
      RAISE EXCEPTION 'project_name_conflict: %', _rec->>'name';
    END IF;
    _prog_id := NULL;
    IF NULLIF(_rec->>'program_external_key','') IS NOT NULL THEN
      _prog_id := NULLIF(_program_map->>(_rec->>'program_external_key'),'')::uuid;
    END IF;
    INSERT INTO public.projects(
      organization_id, workspace_id, program_id, name, description, status, priority,
      start_date, target_end_date, project_stage, delivery_model,
      charter, goals, scope_in, scope_out, business_case, success_criteria, completion_criteria,
      budget_narrative, assumptions, constraints, created_by)
    VALUES (
      _organization_id, _workspace_id, _prog_id, _rec->>'name', NULLIF(_rec->>'description',''),
      COALESCE(NULLIF(_rec->>'status','')::pm_status, 'planned'::pm_status),
      COALESCE(NULLIF(_rec->>'priority','')::pm_priority, 'medium'::pm_priority),
      NULLIF(_rec->>'planned_start','')::date,
      NULLIF(_rec->>'planned_end','')::date,
      COALESCE(NULLIF(_rec->>'project_stage','')::project_stage, 'planning'::project_stage),
      NULLIF(_rec->>'delivery_model','')::project_delivery_model,
      NULLIF(_rec->>'charter',''), NULLIF(_rec->>'goals',''), NULLIF(_rec->>'scope_in',''), NULLIF(_rec->>'scope_out',''),
      NULLIF(_rec->>'business_case',''), NULLIF(_rec->>'success_criteria',''), NULLIF(_rec->>'completion_criteria',''),
      NULLIF(_rec->>'budget_narrative',''), NULLIF(_rec->>'assumptions',''), NULLIF(_rec->>'constraints',''), _user)
    RETURNING id INTO _pid;
    _project_map := _project_map || jsonb_build_object(_rec->>'external_key', to_jsonb(_pid));
    _projects_created := _projects_created + 1;
    _created_projects := _created_projects || jsonb_build_array(jsonb_build_object('id',_pid,'external_key',_rec->>'external_key'));
  END LOOP;

  _idx := 0;
  FOR _rec IN SELECT value FROM jsonb_array_elements(COALESCE(_payload->'phases','[]'::jsonb)) AS t(value) LOOP
    _proj_uuid := NULLIF(_project_map->>(_rec->>'project_external_key'),'')::uuid;
    IF _proj_uuid IS NULL THEN
      RAISE EXCEPTION 'broken_reference: phase % has no matching project', _rec->>'external_key';
    END IF;
    INSERT INTO public.phases(organization_id, workspace_id, project_id, name, description, status, sort_order, start_date, target_end_date, created_by)
    VALUES (_organization_id, _workspace_id, _proj_uuid, _rec->>'name', NULLIF(_rec->>'description',''),
            COALESCE(NULLIF(_rec->>'status','')::pm_status,'planned'::pm_status),
            COALESCE(NULLIF(_rec->>'order_index','')::int, _idx),
            NULLIF(_rec->>'planned_start','')::date,
            NULLIF(_rec->>'planned_end','')::date,
            _user)
    RETURNING id INTO _pid;
    _phase_map := _phase_map || jsonb_build_object(_rec->>'external_key', to_jsonb(_pid));
    _phases_created := _phases_created + 1;
    _created_phases := _created_phases || jsonb_build_array(jsonb_build_object('id',_pid,'external_key',_rec->>'external_key'));
    _idx := _idx + 1;
  END LOOP;

  _idx := 0;
  FOR _rec IN SELECT value FROM jsonb_array_elements(COALESCE(_payload->'tasks','[]'::jsonb)) AS t(value) LOOP
    _proj_uuid := NULLIF(_project_map->>(_rec->>'project_external_key'),'')::uuid;
    _phase_uuid := NULLIF(_phase_map->>(_rec->>'phase_external_key'),'')::uuid;
    IF _proj_uuid IS NULL OR _phase_uuid IS NULL THEN
      RAISE EXCEPTION 'broken_reference: task %', _rec->>'external_key';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.phases WHERE id = _phase_uuid AND project_id = _proj_uuid) THEN
      RAISE EXCEPTION 'broken_reference: task % phase not in same project', _rec->>'external_key';
    END IF;
    INSERT INTO public.tasks(organization_id, workspace_id, project_id, phase_id, name, description, task_type, status, priority, sort_order, start_date, due_date, created_by)
    VALUES (_organization_id, _workspace_id, _proj_uuid, _phase_uuid, _rec->>'name', NULLIF(_rec->>'description',''),
            COALESCE(NULLIF(_rec->>'task_type','')::task_type, 'work_item'::task_type),
            COALESCE(NULLIF(_rec->>'status','')::pm_status,'planned'::pm_status),
            COALESCE(NULLIF(_rec->>'priority','')::pm_priority,'medium'::pm_priority),
            COALESCE(NULLIF(_rec->>'order_index','')::int, _idx),
            NULLIF(_rec->>'planned_start','')::date,
            NULLIF(_rec->>'due_date','')::date,
            _user)
    RETURNING id INTO _pid;
    _task_map := _task_map || jsonb_build_object(_rec->>'external_key', to_jsonb(_pid));
    _tasks_created := _tasks_created + 1;
    _created_tasks := _created_tasks || jsonb_build_array(jsonb_build_object('id',_pid,'external_key',_rec->>'external_key'));
    _idx := _idx + 1;
  END LOOP;

  FOR _rec IN SELECT value FROM jsonb_array_elements(COALESCE(_payload->'project_team_members','[]'::jsonb)) AS t(value) LOOP
    _proj_uuid := NULLIF(_project_map->>(_rec->>'project_external_key'),'')::uuid;
    IF _proj_uuid IS NULL THEN RAISE EXCEPTION 'broken_reference: team member %', _rec->>'external_key'; END IF;
    _email := lower(_rec->>'user_email');
    SELECT p.id INTO _uid FROM public.profiles p WHERE lower(p.email) = _email AND p.is_active = true LIMIT 1;
    IF _uid IS NULL THEN RAISE EXCEPTION 'user_not_found: %', _email; END IF;
    IF NOT EXISTS (SELECT 1 FROM public.organization_memberships WHERE organization_id = _organization_id AND user_id = _uid AND status = 'active') THEN
      RAISE EXCEPTION 'user_inactive: %', _email;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.workspace_memberships WHERE workspace_id = _workspace_id AND user_id = _uid) THEN
      RAISE EXCEPTION 'user_not_in_workspace: %', _email;
    END IF;
    INSERT INTO public.project_team_members(project_id, user_id, role_label, workspace_id, organization_id)
    VALUES (_proj_uuid, _uid, NULLIF(_rec->>'role_label',''), _workspace_id, _organization_id)
    ON CONFLICT (project_id, user_id) DO NOTHING;
    GET DIAGNOSTICS _rowc = ROW_COUNT;
    IF _rowc > 0 THEN _team_created := _team_created + 1; END IF;
  END LOOP;

  FOR _rec IN SELECT value FROM jsonb_array_elements(COALESCE(_payload->'task_assignments','[]'::jsonb)) AS t(value) LOOP
    _task_uuid := NULLIF(_task_map->>(_rec->>'task_external_key'),'')::uuid;
    IF _task_uuid IS NULL THEN RAISE EXCEPTION 'broken_reference: assignment %', _rec->>'external_key'; END IF;
    _email := lower(_rec->>'assignee_email');
    SELECT p.id INTO _uid FROM public.profiles p WHERE lower(p.email) = _email AND p.is_active = true LIMIT 1;
    IF _uid IS NULL THEN RAISE EXCEPTION 'user_not_found: %', _email; END IF;
    IF NOT EXISTS (SELECT 1 FROM public.organization_memberships WHERE organization_id = _organization_id AND user_id = _uid AND status = 'active') THEN
      RAISE EXCEPTION 'user_inactive: %', _email;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.workspace_memberships WHERE workspace_id = _workspace_id AND user_id = _uid) THEN
      RAISE EXCEPTION 'user_not_in_workspace: %', _email;
    END IF;
    INSERT INTO public.task_assignments(task_id, assignee_id, assigned_by, workspace_id, organization_id)
    VALUES (_task_uuid, _uid, _user, _workspace_id, _organization_id)
    ON CONFLICT (task_id, assignee_id) DO NOTHING;
    GET DIAGNOSTICS _rowc = ROW_COUNT;
    IF _rowc > 0 THEN _asg_created := _asg_created + 1; END IF;
  END LOOP;

  FOR _rec IN SELECT value FROM jsonb_array_elements(COALESCE(_payload->'risks','[]'::jsonb)) AS t(value) LOOP
    _target_type := _rec->>'target_type';
    _target_key := _rec->>'target_external_key';
    _target_uuid := CASE _target_type
      WHEN 'project' THEN NULLIF(_project_map->>_target_key,'')::uuid
      WHEN 'phase'   THEN NULLIF(_phase_map->>_target_key,'')::uuid
      WHEN 'task'    THEN NULLIF(_task_map->>_target_key,'')::uuid
      ELSE NULL
    END;
    IF _target_uuid IS NULL THEN
      RAISE EXCEPTION 'target_not_resolved: risk % target %/%', _rec->>'external_key', _target_type, _target_key;
    END IF;
    IF NULLIF(_rec->>'owner_email','') IS NOT NULL THEN
      _email := lower(_rec->>'owner_email');
      SELECT p.id INTO _uid FROM public.profiles p WHERE lower(p.email) = _email AND p.is_active = true LIMIT 1;
      IF _uid IS NULL THEN RAISE EXCEPTION 'user_not_found: %', _email; END IF;
      IF NOT EXISTS (SELECT 1 FROM public.organization_memberships WHERE organization_id = _organization_id AND user_id = _uid AND status = 'active') THEN
        RAISE EXCEPTION 'user_inactive: %', _email;
      END IF;
      IF NOT EXISTS (SELECT 1 FROM public.workspace_memberships WHERE workspace_id = _workspace_id AND user_id = _uid) THEN
        RAISE EXCEPTION 'user_not_in_workspace: %', _email;
      END IF;
    END IF;
    INSERT INTO public.risks(
      organization_id, workspace_id, target_type, target_id,
      title, description, likelihood, impact, status, mitigation_plan, reported_by)
    VALUES (
      _organization_id, _workspace_id, _target_type, _target_uuid,
      _rec->>'title', NULLIF(_rec->>'description',''),
      COALESCE(NULLIF(_rec->>'likelihood','')::risk_likelihood, 'medium'::risk_likelihood),
      COALESCE(NULLIF(_rec->>'impact','')::pm_priority, 'medium'::pm_priority),
      COALESCE(NULLIF(_rec->>'status','')::risk_status, 'open'::risk_status),
      NULLIF(_rec->>'mitigation_plan',''),
      _user);
    _risks_created := _risks_created + 1;
  END LOOP;

  FOR _rec IN SELECT value FROM jsonb_array_elements(COALESCE(_payload->'blockers','[]'::jsonb)) AS t(value) LOOP
    _target_type := _rec->>'target_type';
    _target_key := _rec->>'target_external_key';
    _target_uuid := CASE _target_type
      WHEN 'project' THEN NULLIF(_project_map->>_target_key,'')::uuid
      WHEN 'phase'   THEN NULLIF(_phase_map->>_target_key,'')::uuid
      WHEN 'task'    THEN NULLIF(_task_map->>_target_key,'')::uuid
      ELSE NULL
    END;
    IF _target_uuid IS NULL THEN
      RAISE EXCEPTION 'target_not_resolved: blocker % target %/%', _rec->>'external_key', _target_type, _target_key;
    END IF;
    IF NULLIF(_rec->>'owner_email','') IS NOT NULL THEN
      _email := lower(_rec->>'owner_email');
      SELECT p.id INTO _uid FROM public.profiles p WHERE lower(p.email) = _email AND p.is_active = true LIMIT 1;
      IF _uid IS NULL THEN RAISE EXCEPTION 'user_not_found: %', _email; END IF;
      IF NOT EXISTS (SELECT 1 FROM public.organization_memberships WHERE organization_id = _organization_id AND user_id = _uid AND status = 'active') THEN
        RAISE EXCEPTION 'user_inactive: %', _email;
      END IF;
      IF NOT EXISTS (SELECT 1 FROM public.workspace_memberships WHERE workspace_id = _workspace_id AND user_id = _uid) THEN
        RAISE EXCEPTION 'user_not_in_workspace: %', _email;
      END IF;
    END IF;
    INSERT INTO public.blockers(
      organization_id, workspace_id, target_type, target_id,
      title, description, severity, status, reported_by, resolved_by, resolved_at)
    VALUES (
      _organization_id, _workspace_id, _target_type, _target_uuid,
      _rec->>'title', NULLIF(_rec->>'description',''),
      COALESCE(NULLIF(_rec->>'severity','')::pm_priority, 'medium'::pm_priority),
      COALESCE(NULLIF(_rec->>'status','')::blocker_status, 'open'::blocker_status),
      _user, NULL, NULL);
    _blockers_created := _blockers_created + 1;
  END LOOP;

  FOR _rec IN SELECT value FROM jsonb_array_elements(COALESCE(_payload->'execution_updates','[]'::jsonb)) AS t(value) LOOP
    _target_type := _rec->>'target_type';
    _target_key := _rec->>'target_external_key';
    _target_uuid := CASE _target_type
      WHEN 'project' THEN NULLIF(_project_map->>_target_key,'')::uuid
      WHEN 'phase'   THEN NULLIF(_phase_map->>_target_key,'')::uuid
      WHEN 'task'    THEN NULLIF(_task_map->>_target_key,'')::uuid
      ELSE NULL
    END;
    IF _target_uuid IS NULL THEN
      RAISE EXCEPTION 'target_not_resolved: execution_update % target %/%', _rec->>'external_key', _target_type, _target_key;
    END IF;
    IF NULLIF(_rec->>'author_email','') IS NOT NULL THEN
      _email := lower(_rec->>'author_email');
      SELECT p.id INTO _uid FROM public.profiles p WHERE lower(p.email) = _email AND p.is_active = true LIMIT 1;
      IF _uid IS NULL THEN RAISE EXCEPTION 'author_email_invalid: %', _email; END IF;
      IF NOT EXISTS (SELECT 1 FROM public.organization_memberships WHERE organization_id = _organization_id AND user_id = _uid AND status = 'active') THEN
        RAISE EXCEPTION 'user_inactive: %', _email;
      END IF;
      IF NOT EXISTS (SELECT 1 FROM public.workspace_memberships WHERE workspace_id = _workspace_id AND user_id = _uid) THEN
        RAISE EXCEPTION 'user_not_in_workspace: %', _email;
      END IF;
    ELSE
      _uid := _user;
    END IF;
    INSERT INTO public.execution_updates(
      organization_id, workspace_id, author_id, target_type, target_id,
      update_date, status_label, summary)
    VALUES (
      _organization_id, _workspace_id, _uid, _target_type, _target_uuid,
      COALESCE(NULLIF(_rec->>'update_date','')::date, CURRENT_DATE),
      NULLIF(_rec->>'status_label',''),
      _rec->>'summary');
    _updates_created := _updates_created + 1;
  END LOOP;

  -- ===================== TAE.11B — v2-only sections =====================
  IF _is_v2 THEN
    -- Create Project Stakeholders through the canonical add_project_stakeholder
    -- command. Duplicate external_keys inside the payload are rejected.
    FOR _rec IN SELECT value FROM jsonb_array_elements(COALESCE(_payload->'project_stakeholders','[]'::jsonb)) AS t(value) LOOP
      IF NULLIF(_rec->>'external_key','') IS NULL THEN
        RAISE EXCEPTION 'stakeholder_missing_external_key';
      END IF;
      IF (_stakeholder_map ? (_rec->>'external_key')) THEN
        RAISE EXCEPTION 'duplicate_stakeholder_external_key: %', _rec->>'external_key';
      END IF;
      _proj_uuid := NULLIF(_project_map->>(_rec->>'project_external_key'),'')::uuid;
      IF _proj_uuid IS NULL THEN
        RAISE EXCEPTION 'broken_reference: stakeholder % has no matching project', _rec->>'external_key';
      END IF;
      _stype := _rec->>'stakeholder_type';
      _role_label := NULLIF(_rec->>'role_label','');
      _notes := NULLIF(_rec->>'notes','');
      IF _stype = 'workspace_member' THEN
        _email := lower(_rec->>'user_email');
        IF _email IS NULL OR _email = '' THEN
          RAISE EXCEPTION 'stakeholder_user_email_required: %', _rec->>'external_key';
        END IF;
        SELECT p.id INTO _uid FROM public.profiles p WHERE lower(p.email) = _email AND p.is_active = true LIMIT 1;
        IF _uid IS NULL THEN RAISE EXCEPTION 'user_not_found: %', _email; END IF;
        IF NOT EXISTS (SELECT 1 FROM public.organization_memberships WHERE organization_id = _organization_id AND user_id = _uid AND status = 'active') THEN
          RAISE EXCEPTION 'user_inactive: %', _email;
        END IF;
        IF NOT EXISTS (SELECT 1 FROM public.workspace_memberships WHERE workspace_id = _workspace_id AND user_id = _uid) THEN
          RAISE EXCEPTION 'user_not_in_workspace: %', _email;
        END IF;
        _pid := public.add_project_stakeholder(_proj_uuid, 'workspace_member', _uid, NULL, _role_label, _notes);
      ELSIF _stype = 'external' THEN
        _ex_name := NULLIF(btrim(_rec->>'external_name'),'');
        IF _ex_name IS NULL THEN
          RAISE EXCEPTION 'stakeholder_external_name_required: %', _rec->>'external_key';
        END IF;
        _pid := public.add_project_stakeholder(_proj_uuid, 'external', NULL, _ex_name, _role_label, _notes);
      ELSE
        RAISE EXCEPTION 'invalid_stakeholder_type: %', COALESCE(_stype, '(null)');
      END IF;
      _stakeholder_map := _stakeholder_map || jsonb_build_object(_rec->>'external_key', to_jsonb(_pid));
      _stakeholders_created := _stakeholders_created + 1;
    END LOOP;

    -- Apply Task Requester/Executors through the canonical PMG command.
    -- Executors are deduplicated deterministically; same stakeholder may
    -- serve as both roles.
    FOR _rec IN SELECT value FROM jsonb_array_elements(COALESCE(_payload->'tasks','[]'::jsonb)) AS t(value) LOOP
      _req_key := NULLIF(_rec->>'requested_by_stakeholder_external_key','');
      _exec_keys := _rec->'executed_by_stakeholder_external_keys';
      IF _req_key IS NULL AND (_exec_keys IS NULL OR jsonb_typeof(_exec_keys) <> 'array' OR jsonb_array_length(_exec_keys) = 0) THEN
        CONTINUE;
      END IF;
      _task_uuid := NULLIF(_task_map->>(_rec->>'external_key'),'')::uuid;
      IF _task_uuid IS NULL THEN
        RAISE EXCEPTION 'broken_reference: task % missing from task map', _rec->>'external_key';
      END IF;
      _proj_uuid := NULLIF(_project_map->>(_rec->>'project_external_key'),'')::uuid;

      _req_sid := NULL;
      IF _req_key IS NOT NULL THEN
        _req_sid := NULLIF(_stakeholder_map->>_req_key,'')::uuid;
        IF _req_sid IS NULL THEN
          RAISE EXCEPTION 'broken_reference: task % requester "%" is not a known stakeholder', _rec->>'external_key', _req_key;
        END IF;
        -- Cross-project protection: verify the resolved stakeholder belongs to the same Project.
        IF NOT EXISTS (SELECT 1 FROM public.project_stakeholders WHERE id = _req_sid AND project_id = _proj_uuid) THEN
          RAISE EXCEPTION 'cross_project_reference: task % requester "%" not in project', _rec->>'external_key', _req_key;
        END IF;
      END IF;

      _exec_ids := '{}'::uuid[];
      _seen_execs := '{}'::uuid[];
      IF _exec_keys IS NOT NULL AND jsonb_typeof(_exec_keys) = 'array' THEN
        FOR _exec_key IN SELECT value::text FROM jsonb_array_elements_text(_exec_keys) LOOP
          IF _exec_key IS NULL OR _exec_key = '' THEN CONTINUE; END IF;
          _pid := NULLIF(_stakeholder_map->>_exec_key,'')::uuid;
          IF _pid IS NULL THEN
            RAISE EXCEPTION 'broken_reference: task % executor "%" is not a known stakeholder', _rec->>'external_key', _exec_key;
          END IF;
          IF NOT EXISTS (SELECT 1 FROM public.project_stakeholders WHERE id = _pid AND project_id = _proj_uuid) THEN
            RAISE EXCEPTION 'cross_project_reference: task % executor "%" not in project', _rec->>'external_key', _exec_key;
          END IF;
          IF NOT (_pid = ANY(_seen_execs)) THEN
            _seen_execs := _seen_execs || _pid;
            _exec_ids := _exec_ids || _pid;
          END IF;
        END LOOP;
      END IF;

      -- Read the current updated_at (freshly created above) for optimistic concurrency.
      SELECT updated_at INTO _task_updated_at FROM public.tasks WHERE id = _task_uuid;

      _accountability_result := public.apply_task_stakeholder_roles_set(
        _task_uuid,
        _task_updated_at,
        _req_sid,
        _exec_ids,
        NULL,
        'import:' || _dry_run_batch_id::text || ':task:' || (_rec->>'external_key')
      );

      _accountability_status := _accountability_result->>'status';
      IF _accountability_status IS DISTINCT FROM 'applied' AND _accountability_status IS DISTINCT FROM 'no_change' THEN
        RAISE EXCEPTION 'task_accountability_apply_failed: task=% status=% details=%',
          _rec->>'external_key', COALESCE(_accountability_status,'(null)'), _accountability_result::text;
      END IF;

      IF _req_sid IS NOT NULL THEN
        _requester_links := _requester_links + 1;
      END IF;
      _executor_links := _executor_links + COALESCE(array_length(_exec_ids, 1), 0);
    END LOOP;
  END IF;
  -- =================== end TAE.11B v2-only sections =====================

  UPDATE public.btpm_import_batches
     SET status = 'committed',
         committed_at = now(),
         safe_summary_json = safe_summary_json || jsonb_build_object(
           'commit_counts', jsonb_build_object(
             'programs_created', _programs_created,
             'programs_reused', _programs_reused,
             'projects_created', _projects_created,
             'phases_created', _phases_created,
             'tasks_created', _tasks_created,
             'project_team_members_created', _team_created,
             'task_assignments_created', _asg_created,
             'risks_created', _risks_created,
             'blockers_created', _blockers_created,
             'execution_updates_created', _updates_created,
             'project_stakeholders_created', _stakeholders_created,
             'task_requester_links_created', _requester_links,
             'task_executor_links_created', _executor_links
           )
         )
   WHERE id = _dry_run_batch_id;

  INSERT INTO public.activity_events(organization_id, workspace_id, actor_id, event_type, target_type, target_id, metadata)
  VALUES (_organization_id, _workspace_id, _user, 'import_committed', 'workspace', _workspace_id,
          jsonb_build_object(
            'batch_id', _dry_run_batch_id,
            'schema_version', _batch.schema_version,
            'import_type', _batch.import_type,
            'counts', jsonb_build_object(
              'programs_created', _programs_created,
              'programs_reused', _programs_reused,
              'projects_created', _projects_created,
              'phases_created', _phases_created,
              'tasks_created', _tasks_created,
              'project_team_members_created', _team_created,
              'task_assignments_created', _asg_created,
              'risks_created', _risks_created,
              'blockers_created', _blockers_created,
              'execution_updates_created', _updates_created,
              'project_stakeholders_created', _stakeholders_created,
              'task_requester_links_created', _requester_links,
              'task_executor_links_created', _executor_links
            )
          )::text);

  PERFORM public.pmg_record_command_audit(
    'applied'::pmg_command_status,
    CASE WHEN _is_v2 THEN 'commit_btpm_import_v2' ELSE 'commit_btpm_import_v1' END,
    'admin_import'::pmg_source_channel,
    NULL::uuid,
    'import_batch',
    _dry_run_batch_id,
    NULL::uuid,
    NULL::text,
    NULL::text,
    jsonb_build_object(
      'batch_id', _dry_run_batch_id,
      'workspace_id', _workspace_id,
      'organization_id', _organization_id,
      'schema_version', _batch.schema_version,
      'import_type', _batch.import_type,
      'payload_hash_present', (_payload_hash IS NOT NULL AND length(_payload_hash) > 0),
      'counts', jsonb_build_object(
        'programs_created', _programs_created,
        'programs_reused', _programs_reused,
        'projects_created', _projects_created,
        'phases_created', _phases_created,
        'tasks_created', _tasks_created,
        'project_team_members_created', _team_created,
        'task_assignments_created', _asg_created,
        'risks_created', _risks_created,
        'blockers_created', _blockers_created,
        'execution_updates_created', _updates_created,
        'project_stakeholders_created', _stakeholders_created,
        'task_requester_links_created', _requester_links,
        'task_executor_links_created', _executor_links
      )
    )
  );

  RETURN jsonb_build_object(
    'ok', true,
    'batch_id', _dry_run_batch_id,
    'summary', jsonb_build_object(
      'programs_created', _programs_created,
      'programs_reused', _programs_reused,
      'projects_created', _projects_created,
      'phases_created', _phases_created,
      'tasks_created', _tasks_created,
      'project_team_members_created', _team_created,
      'task_assignments_created', _asg_created,
      'risks_created', _risks_created,
      'blockers_created', _blockers_created,
      'execution_updates_created', _updates_created,
      'project_stakeholders_created', _stakeholders_created,
      'task_requester_links_created', _requester_links,
      'task_executor_links_created', _executor_links
    ),
    'created', jsonb_build_object(
      'programs', _created_programs,
      'projects', _created_projects,
      'phases', _created_phases,
      'tasks', _created_tasks
    )
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.complete_roadmap_story_generation_run(_run_id uuid, _story_json text, _source_snapshot_json text, _source_manifest jsonb, _model_metadata jsonb, _prompt_tokens integer, _completion_tokens integer, _total_tokens integer, _raw_output_text text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _run public.roadmap_story_ai_runs;
  _pack public.roadmap_story_packs;
  _next_version integer;
  _version_id uuid;
  _raw text;
  _snapshot_encrypted text;
  _merged_manifest jsonb;
BEGIN
  IF _uid IS NULL OR NOT public.is_active_user(_uid) THEN
    RAISE EXCEPTION 'unauthorized' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO _run FROM public.roadmap_story_ai_runs WHERE id = _run_id;
  IF NOT FOUND OR _run.created_by <> _uid THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO _pack FROM public.roadmap_story_packs WHERE id = _run.story_pack_id;
  IF NOT FOUND OR _pack.created_by <> _uid THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF _pack.status = 'archived' THEN
    RAISE EXCEPTION 'This Story Pack is archived.' USING ERRCODE = '42501';
  END IF;
  IF _story_json IS NULL OR _story_json = '' THEN
    RAISE EXCEPTION 'story_json required';
  END IF;

  -- Prefer caller-supplied snapshot; otherwise reuse the one attached at start.
  IF _source_snapshot_json IS NOT NULL AND _source_snapshot_json <> '' THEN
    _snapshot_encrypted := public.btpm_encrypt(_source_snapshot_json, _pack.organization_id);
  ELSE
    _snapshot_encrypted := _run.source_snapshot_encrypted;
  END IF;

  -- Merge manifest: caller-supplied overrides; otherwise reuse run input_manifest.
  IF _source_manifest IS NULL OR _source_manifest = '{}'::jsonb THEN
    _merged_manifest := COALESCE(_run.input_manifest, '{}'::jsonb);
  ELSE
    _merged_manifest := _source_manifest;
  END IF;

  SELECT COALESCE(MAX(version_number), 0) + 1 INTO _next_version
  FROM public.roadmap_story_pack_versions WHERE story_pack_id = _pack.id;

  INSERT INTO public.roadmap_story_pack_versions (
    story_pack_id, version_number, created_by, status,
    story_json_encrypted, source_snapshot_encrypted,
    source_manifest, model_metadata
  )
  VALUES (
    _pack.id, _next_version, _uid, 'draft',
    public.btpm_encrypt(_story_json, _pack.organization_id),
    _snapshot_encrypted,
    _merged_manifest,
    COALESCE(_model_metadata, '{}'::jsonb)
  )
  RETURNING id INTO _version_id;

  _raw := COALESCE(NULLIF(_raw_output_text, ''), _story_json);

  UPDATE public.roadmap_story_ai_runs
  SET status = 'succeeded',
      story_pack_version_id = _version_id,
      output_text_encrypted = public.btpm_encrypt(_raw, _pack.organization_id),
      prompt_tokens = _prompt_tokens,
      completion_tokens = _completion_tokens,
      total_tokens = _total_tokens,
      completed_at = now()
  WHERE id = _run_id;

  RETURN _version_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.complete_roadmap_story_presentation_run(_run_id uuid, _raw_output_text text, _parsed_blueprint_json text, _validation_json text, _is_valid boolean, _model_metadata jsonb, _prompt_tokens integer, _completion_tokens integer, _total_tokens integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _run public.roadmap_story_pack_presentation_runs;
  _pack public.roadmap_story_packs;
BEGIN
  IF _uid IS NULL OR NOT public.is_active_user(_uid) THEN
    RAISE EXCEPTION 'unauthorized' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO _run FROM public.roadmap_story_pack_presentation_runs WHERE id = _run_id;
  IF NOT FOUND OR _run.created_by <> _uid THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO _pack FROM public.roadmap_story_packs WHERE id = _run.story_pack_id;
  IF NOT FOUND OR _pack.created_by <> _uid THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  UPDATE public.roadmap_story_pack_presentation_runs
     SET status = 'succeeded',
         is_valid = COALESCE(_is_valid, false),
         raw_response_encrypted = CASE WHEN _raw_output_text IS NULL OR _raw_output_text = '' THEN NULL
              ELSE public.btpm_encrypt(_raw_output_text, _pack.organization_id) END,
         parsed_blueprint_encrypted = CASE WHEN _parsed_blueprint_json IS NULL OR _parsed_blueprint_json = '' THEN NULL
              ELSE public.btpm_encrypt(_parsed_blueprint_json, _pack.organization_id) END,
         validation_json_encrypted = CASE WHEN _validation_json IS NULL OR _validation_json = '' THEN NULL
              ELSE public.btpm_encrypt(_validation_json, _pack.organization_id) END,
         model_metadata = COALESCE(_model_metadata, '{}'::jsonb),
         prompt_tokens = _prompt_tokens,
         completion_tokens = _completion_tokens,
         total_tokens = _total_tokens,
         completed_at = now()
   WHERE id = _run_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_adoption_initiative(_adoption_plan_id uuid, _name text, _readiness_area adoption_readiness_area, _owner_id uuid DEFAULT NULL::uuid, _status adoption_initiative_status DEFAULT 'planned'::adoption_initiative_status, _priority pm_priority DEFAULT 'medium'::pm_priority, _target_date date DEFAULT NULL::date, _summary text DEFAULT NULL::text, _sort_order integer DEFAULT 0)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _org uuid; _ws uuid; _proj uuid; _uid uuid := auth.uid(); _id uuid;
BEGIN
  IF _uid IS NULL OR NOT public.is_active_user(_uid) THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  SELECT organization_id, workspace_id, project_id INTO _org, _ws, _proj
  FROM public.adoption_plans WHERE id = _adoption_plan_id;
  IF _org IS NULL THEN RAISE EXCEPTION 'invalid_adoption_plan'; END IF;
  IF NOT public.has_pm_authority(_uid, _ws) THEN RAISE EXCEPTION 'forbidden'; END IF;
  IF _name IS NULL OR btrim(_name) = '' THEN RAISE EXCEPTION 'name_required'; END IF;

  INSERT INTO public.adoption_initiatives(
    organization_id, workspace_id, project_id, adoption_plan_id,
    name, readiness_area, owner_id, status, priority, target_date, summary, sort_order, created_by
  ) VALUES (
    _org, _ws, _proj, _adoption_plan_id,
    _name, _readiness_area, _owner_id, _status, _priority, _target_date, _summary, _sort_order, _uid
  ) RETURNING id INTO _id;

  PERFORM public.log_activity_event(
    _organization_id => _org, _actor_id => _uid,
    _event_type => 'adoption_initiative_created',
    _target_type => 'project', _target_id => _proj,
    _metadata => jsonb_build_object(
      'adoption_plan_id', _adoption_plan_id,
      'adoption_initiative_id', _id,
      'readiness_area', _readiness_area::text,
      'status', _status::text
    ),
    _workspace_id => _ws
  );
  RETURN _id;
END $function$

CREATE OR REPLACE FUNCTION public.create_adoption_template_from_payload(_workspace_id uuid, _name text, _description text, _payload jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _org uuid;
  _template_id uuid;
  _source_key text;
BEGIN
  IF _uid IS NULL OR NOT public.is_active_user(_uid) THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;
  IF COALESCE(btrim(_name), '') = '' THEN
    RAISE EXCEPTION 'template_name_required';
  END IF;
  SELECT organization_id INTO _org FROM public.workspaces WHERE id = _workspace_id;
  IF _org IS NULL THEN
    RAISE EXCEPTION 'invalid_workspace';
  END IF;
  IF NOT public.has_pm_authority(_uid, _workspace_id) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  _source_key := NULLIF(btrim(COALESCE(_payload->>'source_template_key','')), '');

  INSERT INTO public.adoption_templates(
    organization_id, workspace_id, name, description,
    scope, source_template_key, is_system, is_archived, created_by, updated_by
  ) VALUES (
    _org, _workspace_id, btrim(_name), NULLIF(btrim(COALESCE(_description,'')),''),
    'workspace', _source_key, false, false, _uid, _uid
  ) RETURNING id INTO _template_id;

  PERFORM public._adoption_template_validate_and_load(_template_id, _org, _workspace_id, _payload);

  RETURN _template_id;
END $function$

CREATE OR REPLACE FUNCTION public.create_ai_instruction_template_version(_feature_key text, _title text, _instruction_text text, _notes text)
 RETURNS ai_instruction_templates
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _org_id uuid;
  _next int;
  _row public.ai_instruction_templates;
BEGIN
  SELECT organization_id INTO _org_id FROM public.profiles WHERE id = auth.uid();
  IF _org_id IS NULL OR NOT public.is_org_admin(auth.uid(), _org_id) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF _feature_key NOT IN ('decision_case_brief') THEN
    RAISE EXCEPTION 'invalid feature_key';
  END IF;
  IF _title IS NULL OR length(btrim(_title)) = 0 THEN
    RAISE EXCEPTION 'title required';
  END IF;
  IF _instruction_text IS NULL OR length(btrim(_instruction_text)) = 0 THEN
    RAISE EXCEPTION 'instruction_text required';
  END IF;

  SELECT COALESCE(MAX(version), 0) + 1 INTO _next
    FROM public.ai_instruction_templates
   WHERE organization_id = _org_id AND feature_key = _feature_key;

  INSERT INTO public.ai_instruction_templates
    (organization_id, feature_key, version, title, instruction_text, notes, status, created_by)
  VALUES
    (_org_id, _feature_key, _next, _title, _instruction_text, _notes, 'draft', auth.uid())
  RETURNING * INTO _row;

  RETURN _row;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_blank_project(_name text, _workspace_id uuid, _program_id uuid DEFAULT NULL::uuid, _delivery_model project_delivery_model DEFAULT NULL::project_delivery_model)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _org uuid;
  _is_demo boolean;
  _new_id uuid;
  _name_trim text := btrim(coalesce(_name, ''));
BEGIN
  IF _uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;
  IF NOT public.is_active_user(_uid) THEN
    RAISE EXCEPTION 'Account is deactivated' USING ERRCODE = '42501';
  END IF;
  IF _name_trim = '' THEN
    RAISE EXCEPTION 'Project name is required';
  END IF;
  IF length(_name_trim) > 200 THEN
    RAISE EXCEPTION 'Project name must be 200 characters or less';
  END IF;

  SELECT organization_id, is_demo INTO _org, _is_demo
  FROM public.workspaces WHERE id = _workspace_id;
  IF _org IS NULL THEN
    RAISE EXCEPTION 'Workspace not found';
  END IF;

  IF _org <> public.get_user_org_id(_uid) THEN
    RAISE EXCEPTION 'Workspace is not in your organization' USING ERRCODE = '42501';
  END IF;

  IF NOT public.has_pm_authority(_uid, _workspace_id) THEN
    RAISE EXCEPTION 'You do not have permission to create projects in this workspace' USING ERRCODE = '42501';
  END IF;

  IF NOT public.can_write_demo(_uid, _workspace_id) THEN
    RAISE EXCEPTION 'Cannot write to this demo workspace' USING ERRCODE = '42501';
  END IF;

  IF _program_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.programs
      WHERE id = _program_id AND workspace_id = _workspace_id
    ) THEN
      RAISE EXCEPTION 'Program must belong to the same workspace as the project';
    END IF;
  END IF;

  INSERT INTO public.projects (name, workspace_id, organization_id, program_id, created_by, delivery_model)
  VALUES (_name_trim, _workspace_id, _org, _program_id, _uid, _delivery_model)
  RETURNING id INTO _new_id;

  RETURN _new_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_blocker_with_links(_title text, _description text, _severity text, _target_type text, _target_id uuid, _organization_id uuid, _workspace_id uuid, _user_links jsonb DEFAULT '[]'::jsonb, _object_links jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_id uuid; v jsonb; v_idx int;
  v_project_id uuid;
  v_workspace_id uuid;
  v_organization_id uuid;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF NOT public.is_active_user(v_uid) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;

  IF _target_type = 'project' THEN
    SELECT p.id, p.workspace_id, p.organization_id
      INTO v_project_id, v_workspace_id, v_organization_id
      FROM public.projects p WHERE p.id = _target_id;
  ELSIF _target_type = 'phase' THEN
    SELECT p.id, p.workspace_id, p.organization_id
      INTO v_project_id, v_workspace_id, v_organization_id
      FROM public.phases ph
      JOIN public.projects p ON p.id = ph.project_id
      WHERE ph.id = _target_id;
  ELSIF _target_type = 'task' THEN
    SELECT p.id, p.workspace_id, p.organization_id
      INTO v_project_id, v_workspace_id, v_organization_id
      FROM public.tasks t
      JOIN public.projects p ON p.id = t.project_id
      LEFT JOIN public.phases ph ON ph.id = t.phase_id
      WHERE t.id = _target_id
        AND (t.phase_id IS NULL OR ph.project_id = t.project_id);
  ELSE
    RAISE EXCEPTION 'Target is unavailable or not authorized';
  END IF;

  IF v_project_id IS NULL OR v_workspace_id IS NULL OR v_organization_id IS NULL THEN
    RAISE EXCEPTION 'Target is unavailable or not authorized';
  END IF;

  IF _workspace_id IS DISTINCT FROM v_workspace_id
     OR _organization_id IS DISTINCT FROM v_organization_id THEN
    RAISE EXCEPTION 'Target is unavailable or not authorized';
  END IF;

  IF NOT public.has_pm_authority(v_uid, v_workspace_id) THEN
    RAISE EXCEPTION 'Target is unavailable or not authorized';
  END IF;

  IF NOT public.can_write_demo(v_uid, v_workspace_id) THEN
    RAISE EXCEPTION 'Not authorized: this workspace is read-only';
  END IF;

  PERFORM public._validate_object_links(_object_links, v_workspace_id, v_organization_id);
  PERFORM public._validate_user_links(_user_links, v_workspace_id, v_project_id);

  INSERT INTO public.blockers (
    organization_id, workspace_id, target_type, target_id,
    title, description, severity, reported_by
  ) VALUES (
    v_organization_id, v_workspace_id, _target_type, _target_id,
    _title, _description,
    COALESCE(_severity, 'medium')::pm_priority,
    v_uid
  ) RETURNING id INTO v_id;

  v_idx := 0;
  FOR v IN SELECT * FROM jsonb_array_elements(COALESCE(_user_links,'[]'::jsonb)) LOOP
    INSERT INTO public.entity_user_links (owner_type, owner_id, organization_id, workspace_id,
                                          user_id, stakeholder_id, link_role, sort_order, created_by)
    VALUES ('blocker', v_id, v_organization_id, v_workspace_id,
            NULLIF(v->>'user_id','')::uuid,
            NULLIF(v->>'stakeholder_id','')::uuid,
            'related_person', v_idx, v_uid)
    ON CONFLICT DO NOTHING;
    v_idx := v_idx + 1;
  END LOOP;

  v_idx := 0;
  FOR v IN SELECT * FROM jsonb_array_elements(COALESCE(_object_links,'[]'::jsonb)) LOOP
    INSERT INTO public.entity_object_links (owner_type, owner_id, organization_id, workspace_id, referenced_type, referenced_id, link_role, sort_order, created_by)
    VALUES ('blocker', v_id, v_organization_id, v_workspace_id, v->>'referenced_type', (v->>'referenced_id')::uuid, 'related_object', v_idx, v_uid)
    ON CONFLICT DO NOTHING;
    v_idx := v_idx + 1;
  END LOOP;

  RETURN jsonb_build_object('id', v_id);
END $function$

CREATE OR REPLACE FUNCTION public.create_blocker_with_links(_title text, _description text, _severity text, _target_type text, _target_id uuid, _organization_id uuid, _workspace_id uuid, _user_links jsonb DEFAULT '[]'::jsonb, _object_links jsonb DEFAULT '[]'::jsonb, _status text DEFAULT 'open'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_id uuid; v jsonb; v_idx int;
  v_project_id uuid;
  v_workspace_id uuid;
  v_organization_id uuid;
  v_status blocker_status;
  v_is_resolved boolean;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF NOT public.is_active_user(v_uid) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;

  IF _target_type = 'project' THEN
    SELECT p.id, p.workspace_id, p.organization_id
      INTO v_project_id, v_workspace_id, v_organization_id
      FROM public.projects p WHERE p.id = _target_id;
  ELSIF _target_type = 'phase' THEN
    SELECT p.id, p.workspace_id, p.organization_id
      INTO v_project_id, v_workspace_id, v_organization_id
      FROM public.phases ph
      JOIN public.projects p ON p.id = ph.project_id
      WHERE ph.id = _target_id;
  ELSIF _target_type = 'task' THEN
    SELECT p.id, p.workspace_id, p.organization_id
      INTO v_project_id, v_workspace_id, v_organization_id
      FROM public.tasks t
      JOIN public.projects p ON p.id = t.project_id
      LEFT JOIN public.phases ph ON ph.id = t.phase_id
      WHERE t.id = _target_id
        AND (t.phase_id IS NULL OR ph.project_id = t.project_id);
  ELSE
    RAISE EXCEPTION 'Target is unavailable or not authorized';
  END IF;

  IF v_project_id IS NULL OR v_workspace_id IS NULL OR v_organization_id IS NULL THEN
    RAISE EXCEPTION 'Target is unavailable or not authorized';
  END IF;

  IF _workspace_id IS DISTINCT FROM v_workspace_id
     OR _organization_id IS DISTINCT FROM v_organization_id THEN
    RAISE EXCEPTION 'Target is unavailable or not authorized';
  END IF;

  IF NOT public.has_pm_authority(v_uid, v_workspace_id) THEN
    RAISE EXCEPTION 'Target is unavailable or not authorized';
  END IF;

  IF NOT public.can_write_demo(v_uid, v_workspace_id) THEN
    RAISE EXCEPTION 'Not authorized: this workspace is read-only';
  END IF;

  PERFORM public._validate_object_links(_object_links, v_workspace_id, v_organization_id);
  PERFORM public._validate_user_links(_user_links, v_workspace_id, v_project_id);

  v_status := COALESCE(_status, 'open')::blocker_status;
  v_is_resolved := (v_status = 'resolved'::blocker_status);

  INSERT INTO public.blockers (
    organization_id, workspace_id, target_type, target_id,
    title, description, severity, status, reported_by,
    resolved_by, resolved_at
  ) VALUES (
    v_organization_id, v_workspace_id, _target_type, _target_id,
    _title, _description,
    COALESCE(_severity, 'medium')::pm_priority,
    v_status,
    v_uid,
    CASE WHEN v_is_resolved THEN v_uid ELSE NULL END,
    CASE WHEN v_is_resolved THEN now() ELSE NULL END
  ) RETURNING id INTO v_id;

  v_idx := 0;
  FOR v IN SELECT * FROM jsonb_array_elements(COALESCE(_user_links,'[]'::jsonb)) LOOP
    INSERT INTO public.entity_user_links (owner_type, owner_id, organization_id, workspace_id,
                                          user_id, stakeholder_id, link_role, sort_order, created_by)
    VALUES ('blocker', v_id, v_organization_id, v_workspace_id,
            NULLIF(v->>'user_id','')::uuid,
            NULLIF(v->>'stakeholder_id','')::uuid,
            'related_person', v_idx, v_uid)
    ON CONFLICT DO NOTHING;
    v_idx := v_idx + 1;
  END LOOP;

  v_idx := 0;
  FOR v IN SELECT * FROM jsonb_array_elements(COALESCE(_object_links,'[]'::jsonb)) LOOP
    INSERT INTO public.entity_object_links (owner_type, owner_id, organization_id, workspace_id, referenced_type, referenced_id, link_role, sort_order, created_by)
    VALUES ('blocker', v_id, v_organization_id, v_workspace_id, v->>'referenced_type', (v->>'referenced_id')::uuid, 'related_object', v_idx, v_uid)
    ON CONFLICT DO NOTHING;
    v_idx := v_idx + 1;
  END LOOP;

  RETURN jsonb_build_object('id', v_id);
END $function$

CREATE OR REPLACE FUNCTION public.create_comment_with_references(_body text, _target_type text, _target_id uuid, _organization_id uuid, _workspace_id uuid, _references jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_comment_id uuid;
  v_ref jsonb;
  v_idx int := 0;
  v_auth_org_id uuid;
  v_auth_ws_id uuid;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF NOT public.is_active_user(v_uid) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;

  IF _target_id IS NULL OR _target_type IS NULL THEN
    RAISE EXCEPTION 'Target is required';
  END IF;

  -- Resolve authoritative context strictly from currently supported comment targets.
  IF _target_type = 'task' THEN
    SELECT organization_id, workspace_id INTO v_auth_org_id, v_auth_ws_id
    FROM public.tasks WHERE id = _target_id;
  ELSIF _target_type = 'phase' THEN
    SELECT organization_id, workspace_id INTO v_auth_org_id, v_auth_ws_id
    FROM public.phases WHERE id = _target_id;
  ELSE
    RAISE EXCEPTION 'Unsupported comment target type: %', _target_type;
  END IF;

  IF v_auth_org_id IS NULL OR v_auth_ws_id IS NULL THEN
    RAISE EXCEPTION 'Target not found';
  END IF;

  -- Reject any caller-supplied scope that disagrees with the authoritative target context.
  IF _organization_id IS NOT NULL AND _organization_id <> v_auth_org_id THEN
    RAISE EXCEPTION 'Organization does not match target';
  END IF;
  IF _workspace_id IS NOT NULL AND _workspace_id <> v_auth_ws_id THEN
    RAISE EXCEPTION 'Workspace does not match target';
  END IF;

  IF NOT (public.is_workspace_member(v_uid, v_auth_ws_id)
          OR public.is_org_admin(v_uid, v_auth_org_id)) THEN
    RAISE EXCEPTION 'Not authorized for this workspace';
  END IF;
  IF NOT public.can_write_demo(v_uid, v_auth_ws_id) THEN
    RAISE EXCEPTION 'Not authorized to write in this workspace (read-only/demo)';
  END IF;

  PERFORM public._validate_object_links(_references, v_auth_ws_id, v_auth_org_id);

  INSERT INTO public.comments (organization_id, workspace_id, author_id, target_type, target_id, body)
  VALUES (v_auth_org_id, v_auth_ws_id, v_uid, _target_type, _target_id, _body)
  RETURNING id INTO v_comment_id;

  IF _references IS NOT NULL AND jsonb_typeof(_references) = 'array' THEN
    FOR v_ref IN SELECT * FROM jsonb_array_elements(_references) LOOP
      INSERT INTO public.entity_object_links (
        owner_type, owner_id, organization_id, workspace_id,
        referenced_type, referenced_id, link_role, sort_order, created_by
      ) VALUES (
        'comment', v_comment_id, v_auth_org_id, v_auth_ws_id,
        v_ref->>'referenced_type',
        (v_ref->>'referenced_id')::uuid,
        'reference',
        COALESCE((v_ref->>'sort_order')::int, v_idx),
        v_uid
      ) ON CONFLICT DO NOTHING;
      v_idx := v_idx + 1;
    END LOOP;
  END IF;

  RETURN jsonb_build_object('id', v_comment_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.create_dependency(_source_type text, _source_id uuid, _target_type text, _target_id uuid, _correlation_id text DEFAULT NULL::text, _idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_src_type text := lower(nullif(btrim(coalesce(_source_type,'')),''));
  v_tgt_type text := lower(nullif(btrim(coalesce(_target_type,'')),''));
  v_src_ws uuid; v_src_org uuid; v_src_project uuid;
  v_tgt_ws uuid; v_tgt_org uuid; v_tgt_project uuid;
  v_new_id uuid;
  v_data jsonb;
BEGIN
  IF v_actor IS NULL OR NOT public.is_active_user(v_actor) THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'create_dependency',
      'dependency', NULL, NULL,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF v_src_type IS NULL OR v_tgt_type IS NULL
     OR v_src_type NOT IN ('project','phase','task')
     OR v_tgt_type NOT IN ('project','phase','task')
     OR _source_id IS NULL OR _target_id IS NULL THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'create_dependency',
      'dependency', NULL, NULL,
      jsonb_build_object('reason','invalid_target'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF v_src_type <> v_tgt_type THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'create_dependency',
      'dependency', NULL, NULL,
      jsonb_build_object('reason','not_same_level'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF _source_id = _target_id THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'create_dependency',
      'dependency', NULL, NULL,
      jsonb_build_object('reason','self_reference'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  -- Resolve context server-side
  IF v_src_type = 'phase' THEN
    SELECT project_id, workspace_id, organization_id
      INTO v_src_project, v_src_ws, v_src_org
      FROM public.phases WHERE id = _source_id;
    SELECT project_id, workspace_id, organization_id
      INTO v_tgt_project, v_tgt_ws, v_tgt_org
      FROM public.phases WHERE id = _target_id;
  ELSIF v_src_type = 'task' THEN
    SELECT project_id, workspace_id, organization_id
      INTO v_src_project, v_src_ws, v_src_org
      FROM public.tasks WHERE id = _source_id;
    SELECT project_id, workspace_id, organization_id
      INTO v_tgt_project, v_tgt_ws, v_tgt_org
      FROM public.tasks WHERE id = _target_id;
  ELSE -- project
    SELECT id, workspace_id, organization_id
      INTO v_src_project, v_src_ws, v_src_org
      FROM public.projects WHERE id = _source_id;
    SELECT id, workspace_id, organization_id
      INTO v_tgt_project, v_tgt_ws, v_tgt_org
      FROM public.projects WHERE id = _target_id;
  END IF;

  IF v_src_project IS NULL OR v_tgt_project IS NULL THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'create_dependency',
      'dependency', NULL, NULL,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  -- Same organization; for phase/task also same project.
  IF v_src_org <> v_tgt_org THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'create_dependency',
      'dependency', NULL, NULL,
      jsonb_build_object('reason','cross_org'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF v_src_type IN ('phase','task') AND v_src_project <> v_tgt_project THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'create_dependency',
      'dependency', NULL, NULL,
      jsonb_build_object('reason','cross_project'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  -- Authority: for phase/task both endpoints already share one workspace, so
  -- one check is sufficient. For projects, check BOTH endpoint workspaces to
  -- prevent cross-workspace escalation.
  IF v_src_type = 'project' THEN
    IF NOT public.has_pm_authority(v_actor, v_src_ws)
       OR NOT public.has_pm_authority(v_actor, v_tgt_ws)
       OR NOT public.can_write_demo(v_actor, v_src_ws)
       OR NOT public.can_write_demo(v_actor, v_tgt_ws) THEN
      RETURN public.pmg_build_result(
        'not_authorized'::public.pmg_command_status, 'create_dependency',
        'dependency', NULL, v_src_project,
        '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
      );
    END IF;
  ELSE
    IF NOT public.has_pm_authority(v_actor, v_src_ws)
       OR NOT public.can_write_demo(v_actor, v_src_ws) THEN
      RETURN public.pmg_build_result(
        'not_authorized'::public.pmg_command_status, 'create_dependency',
        'dependency', NULL, v_src_project,
        '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
      );
    END IF;
  END IF;

  BEGIN
    INSERT INTO public.dependencies (
      organization_id, workspace_id,
      source_type, source_id, target_type, target_id,
      dependency_type, created_by
    ) VALUES (
      v_src_org, v_src_ws,
      v_src_type, _source_id, v_tgt_type, _target_id,
      'finish_to_start'::public.dependency_type, v_actor
    )
    RETURNING id INTO v_new_id;
  EXCEPTION
    WHEN unique_violation THEN
      RETURN public.pmg_build_result(
        'invalid'::public.pmg_command_status, 'create_dependency',
        'dependency', NULL, v_src_project,
        jsonb_build_object('reason','duplicate'),
        '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
      );
    WHEN check_violation OR raise_exception OR not_null_violation
      OR invalid_text_representation OR foreign_key_violation THEN
      RETURN public.pmg_build_result(
        'invalid'::public.pmg_command_status, 'create_dependency',
        'dependency', NULL, v_src_project,
        jsonb_build_object('reason', SQLERRM),
        '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
      );
  END;

  v_data := jsonb_build_object(
    'id', v_new_id,
    'source_type', v_src_type, 'source_id', _source_id,
    'target_type', v_tgt_type, 'target_id', _target_id,
    'project_id', v_src_project,
    'workspace_id', v_src_ws,
    'dependency_type', 'finish_to_start'
  );

  PERFORM public.pmg_record_command_audit(
    'applied'::public.pmg_command_status, 'create_dependency',
    'btpm_ui'::public.pmg_source_channel,
    v_src_project, 'dependency', v_new_id, NULL,
    _correlation_id, _idempotency_key,
    jsonb_build_object(
      'source_type', v_src_type, 'target_type', v_tgt_type,
      'workspace_id', v_src_ws
    )
  );

  RETURN public.pmg_build_result(
    'applied'::public.pmg_command_status, 'create_dependency',
    'dependency', v_new_id, v_src_project,
    v_data, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.create_governance_record_brief_version(_record_id uuid, _source_type text DEFAULT 'copilot_paste'::text, _raw_copilot_output text DEFAULT NULL::text, _edited_brief_text text DEFAULT NULL::text, _executive_intro_text text DEFAULT NULL::text, _options_summary text DEFAULT NULL::text, _recommendation_text text DEFAULT NULL::text, _guardrails_text text DEFAULT NULL::text, _residual_risks_text text DEFAULT NULL::text, _requested_decision_text text DEFAULT NULL::text, _make_current boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  _row public.governance_records%ROWTYPE;
  _next int;
  _id uuid;
  _raw text; _edited text; _intro text; _opts text; _rec text; _grd text; _rsk text; _req text;
BEGIN
  SELECT * INTO _row FROM public.governance_records WHERE id = _record_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Record not found' USING ERRCODE='P0002'; END IF;
  IF _row.record_kind IS DISTINCT FROM 'decision_case' THEN
    RAISE EXCEPTION 'Brief versions are only allowed on decision_case records' USING ERRCODE='22023';
  END IF;
  PERFORM public._gov_assert_project_write(_row.project_id);

  IF _source_type NOT IN ('copilot_paste','manual_edit','btpm_generated') THEN
    RAISE EXCEPTION 'Invalid source_type %', _source_type USING ERRCODE='22023';
  END IF;

  _raw    := NULLIF(trim(COALESCE(_raw_copilot_output, '')), '');
  _edited := NULLIF(trim(COALESCE(_edited_brief_text, '')), '');
  _intro  := NULLIF(trim(COALESCE(_executive_intro_text, '')), '');
  _opts   := NULLIF(trim(COALESCE(_options_summary, '')), '');
  _rec    := NULLIF(trim(COALESCE(_recommendation_text, '')), '');
  _grd    := NULLIF(trim(COALESCE(_guardrails_text, '')), '');
  _rsk    := NULLIF(trim(COALESCE(_residual_risks_text, '')), '');
  _req    := NULLIF(trim(COALESCE(_requested_decision_text, '')), '');

  IF _raw IS NULL AND _edited IS NULL AND _intro IS NULL AND _opts IS NULL
     AND _rec IS NULL AND _grd IS NULL AND _rsk IS NULL AND _req IS NULL THEN
    RAISE EXCEPTION 'At least one brief field is required' USING ERRCODE='22023';
  END IF;

  SELECT COALESCE(MAX(version_number), 0) + 1 INTO _next
    FROM public.governance_record_brief_versions
    WHERE governance_record_id = _record_id;

  IF COALESCE(_make_current, true) THEN
    UPDATE public.governance_record_brief_versions
      SET is_current = false, updated_by = auth.uid(), updated_at = now()
      WHERE governance_record_id = _record_id AND is_current = true;
  END IF;

  INSERT INTO public.governance_record_brief_versions (
    organization_id, workspace_id, project_id, governance_record_id,
    version_number, source_type, is_current,
    raw_copilot_output, edited_brief_text, executive_intro_text, options_summary,
    recommendation_text, guardrails_text, residual_risks_text, requested_decision_text,
    created_by, updated_by
  ) VALUES (
    _row.organization_id, _row.workspace_id, _row.project_id, _record_id,
    _next, _source_type, COALESCE(_make_current, true),
    _raw, _edited, _intro, _opts, _rec, _grd, _rsk, _req,
    auth.uid(), auth.uid()
  ) RETURNING id INTO _id;

  PERFORM public.log_activity_event(_row.organization_id, auth.uid(),
    'governance_record_brief_version_created', 'governance_record', _record_id,
    jsonb_build_object('project_id', _row.project_id,
                       'brief_version_id', _id,
                       'version_number', _next,
                       'source_type', _source_type,
                       'is_current', COALESCE(_make_current, true)),
    _row.workspace_id);

  RETURN jsonb_build_object('id', _id, 'version_number', _next);
END; $function$

CREATE OR REPLACE FUNCTION public.create_governance_record_btpm_context_link(_record_id uuid, _source_project_id uuid, _object_type text, _object_id uuid, _relationship_type text DEFAULT 'directly_relevant'::text, _context_reason text DEFAULT NULL::text, _relevance_level text DEFAULT 'medium'::text, _included_in_package boolean DEFAULT true)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE _row public.governance_records%ROWTYPE; _sp record; _id uuid; _reason text;
BEGIN
  SELECT * INTO _row FROM public.governance_records WHERE id = _record_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Record not found' USING ERRCODE='P0002'; END IF;
  IF _row.record_kind IS DISTINCT FROM 'decision_case' THEN
    RAISE EXCEPTION 'BTPM context links are only allowed on decision_case records' USING ERRCODE='22023';
  END IF;
  PERFORM public._gov_assert_project_write(_row.project_id);

  SELECT id, organization_id, workspace_id INTO _sp
    FROM public.projects WHERE id = _source_project_id;
  IF _sp IS NULL THEN RAISE EXCEPTION 'Source project not found' USING ERRCODE='P0002'; END IF;
  IF _sp.organization_id <> _row.organization_id THEN
    RAISE EXCEPTION 'Source project must be in the same organization' USING ERRCODE='22023';
  END IF;
  IF NOT public.has_project_access(auth.uid(), _source_project_id) THEN
    RAISE EXCEPTION 'You do not have access to the source project' USING ERRCODE='42501';
  END IF;

  _reason := NULLIF(trim(COALESCE(_context_reason, '')), '');

  INSERT INTO public.governance_record_btpm_context_links (
    organization_id, workspace_id, project_id, governance_record_id,
    source_project_id, source_workspace_id,
    object_type, object_id, relationship_type, context_reason,
    relevance_level, included_in_package,
    created_by, updated_by
  ) VALUES (
    _row.organization_id, _row.workspace_id, _row.project_id, _record_id,
    _source_project_id, _sp.workspace_id,
    _object_type, _object_id, COALESCE(_relationship_type,'directly_relevant'), _reason,
    COALESCE(_relevance_level,'medium'), COALESCE(_included_in_package, true),
    auth.uid(), auth.uid()
  ) RETURNING id INTO _id;

  PERFORM public.log_activity_event(_row.organization_id, auth.uid(),
    'governance_record_btpm_context_link_created', 'governance_record', _record_id,
    jsonb_build_object('project_id', _row.project_id,
                       'source_project_id', _source_project_id,
                       'object_type', _object_type,
                       'object_id', _object_id,
                       'relationship_type', COALESCE(_relationship_type,'directly_relevant'),
                       'btpm_context_link_id', _id),
    _row.workspace_id);

  RETURN _id;
END; $function$

CREATE OR REPLACE FUNCTION public.create_governance_record_cross_project_link(_record_id uuid, _linked_project_id uuid, _relationship_type text, _relationship_reason text DEFAULT NULL::text, _source_dependency_id uuid DEFAULT NULL::uuid, _included_in_package boolean DEFAULT true)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE _row public.governance_records%ROWTYPE; _lp record; _id uuid; _reason text;
BEGIN
  SELECT * INTO _row FROM public.governance_records WHERE id = _record_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Record not found' USING ERRCODE='P0002'; END IF;
  IF _row.record_kind IS DISTINCT FROM 'decision_case' THEN
    RAISE EXCEPTION 'Cross-project links are only allowed on decision_case records' USING ERRCODE='22023';
  END IF;
  PERFORM public._gov_assert_project_write(_row.project_id);

  IF _linked_project_id = _row.project_id THEN
    RAISE EXCEPTION 'Cross-project link cannot reference the parent project itself' USING ERRCODE='22023';
  END IF;

  SELECT id, organization_id, workspace_id INTO _lp
    FROM public.projects WHERE id = _linked_project_id;
  IF _lp IS NULL THEN
    RAISE EXCEPTION 'Linked project not found' USING ERRCODE='P0002';
  END IF;
  IF _lp.organization_id <> _row.organization_id THEN
    RAISE EXCEPTION 'Linked project must be in the same organization' USING ERRCODE='22023';
  END IF;
  IF NOT public.has_project_access(auth.uid(), _linked_project_id) THEN
    RAISE EXCEPTION 'You do not have access to the linked project' USING ERRCODE='42501';
  END IF;
  IF _relationship_type NOT IN
     ('formal_dependency','shared_risk','shared_blocker','shared_milestone','manual_related','other') THEN
    RAISE EXCEPTION 'Invalid relationship_type %', _relationship_type USING ERRCODE='22023';
  END IF;

  _reason := NULLIF(trim(COALESCE(_relationship_reason, '')), '');

  INSERT INTO public.governance_record_cross_project_links (
    organization_id, workspace_id, project_id, governance_record_id,
    linked_project_id, linked_project_workspace_id,
    relationship_type, relationship_reason,
    source_dependency_id, included_in_package, created_by, updated_by
  ) VALUES (
    _row.organization_id, _row.workspace_id, _row.project_id, _record_id,
    _linked_project_id, _lp.workspace_id,
    _relationship_type, _reason,
    _source_dependency_id, COALESCE(_included_in_package, true),
    auth.uid(), auth.uid()
  ) RETURNING id INTO _id;

  PERFORM public.log_activity_event(_row.organization_id, auth.uid(),
    'governance_record_cross_project_link_created', 'governance_record', _record_id,
    jsonb_build_object('project_id', _row.project_id, 'linked_project_id', _linked_project_id,
                       'relationship_type', _relationship_type, 'cross_project_link_id', _id),
    _row.workspace_id);

  RETURN _id;
END; $function$

CREATE OR REPLACE FUNCTION public.create_governance_record_evidence_reference(_record_id uuid, _evidence_type text, _title text, _external_url text, _summary text DEFAULT NULL::text, _evidence_date date DEFAULT NULL::date, _owner_stakeholder_id uuid DEFAULT NULL::uuid, _relevance_level text DEFAULT 'medium'::text, _included_in_package boolean DEFAULT true)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE _row governance_records%ROWTYPE; _id uuid; _t text; _u text; _s text;
BEGIN
  SELECT * INTO _row FROM governance_records WHERE id = _record_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Record not found' USING ERRCODE='P0002'; END IF;
  IF _row.record_kind IS DISTINCT FROM 'decision_case' THEN
    RAISE EXCEPTION 'Evidence references are only allowed on decision_case records' USING ERRCODE='22023';
  END IF;
  PERFORM _gov_assert_project_write(_row.project_id);

  IF _evidence_type IS NULL OR _evidence_type NOT IN
    ('sharepoint_file','onenote_page','outlook_reference','teams_reference','meeting_minutes','other_link') THEN
    RAISE EXCEPTION 'Invalid evidence_type' USING ERRCODE='22023';
  END IF;
  IF _relevance_level IS NULL OR _relevance_level NOT IN ('high','medium','low') THEN
    RAISE EXCEPTION 'Invalid relevance_level' USING ERRCODE='22023';
  END IF;

  _t := NULLIF(trim(_title), '');
  _u := NULLIF(trim(_external_url), '');
  _s := NULLIF(trim(coalesce(_summary,'')), '');
  IF _t IS NULL THEN RAISE EXCEPTION 'Title is required' USING ERRCODE='22023'; END IF;
  IF _u IS NULL THEN RAISE EXCEPTION 'External URL is required' USING ERRCODE='22023'; END IF;
  IF lower(_u) NOT LIKE 'http://%' AND lower(_u) NOT LIKE 'https://%' THEN
    RAISE EXCEPTION 'External URL must start with http:// or https://' USING ERRCODE='22023';
  END IF;

  IF _owner_stakeholder_id IS NOT NULL THEN
    IF NOT EXISTS (SELECT 1 FROM project_stakeholders s
                   WHERE s.id = _owner_stakeholder_id AND s.project_id = _row.project_id) THEN
      RAISE EXCEPTION 'Owner stakeholder does not belong to this project' USING ERRCODE='22023';
    END IF;
  END IF;

  INSERT INTO governance_record_evidence_references (
    organization_id, workspace_id, project_id, governance_record_id,
    evidence_type, title, external_url, summary, evidence_date,
    owner_stakeholder_id, relevance_level, included_in_package,
    created_by, updated_by)
  VALUES (
    _row.organization_id, _row.workspace_id, _row.project_id, _record_id,
    _evidence_type, _t, _u, _s, _evidence_date,
    _owner_stakeholder_id, _relevance_level, COALESCE(_included_in_package, true),
    auth.uid(), auth.uid())
  RETURNING id INTO _id;

  PERFORM log_activity_event(_row.organization_id, auth.uid(),
    'governance_record_evidence_reference_created', 'governance_record', _record_id,
    jsonb_build_object('project_id', _row.project_id,
                       'evidence_id', _id,
                       'evidence_type', _evidence_type,
                       'relevance_level', _relevance_level,
                       'included_in_package', COALESCE(_included_in_package, true)),
    _row.workspace_id);
  RETURN _id;
END; $function$

CREATE OR REPLACE FUNCTION public.create_governance_record_stakeholder_package(_record_id uuid, _package_title text, _package_status text DEFAULT 'draft'::text, _audience_text text DEFAULT NULL::text, _executive_summary text DEFAULT NULL::text, _decision_question_text text DEFAULT NULL::text, _background_context text DEFAULT NULL::text, _options_summary text DEFAULT NULL::text, _recommendation_text text DEFAULT NULL::text, _decision_ask_text text DEFAULT NULL::text, _evidence_summary text DEFAULT NULL::text, _guardrails_text text DEFAULT NULL::text, _residual_risks_text text DEFAULT NULL::text, _next_steps_text text DEFAULT NULL::text, _distribution_note text DEFAULT NULL::text, _distribution_evidence_url text DEFAULT NULL::text, _make_current boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  _row public.governance_records%ROWTYPE;
  _next int;
  _id uuid;
  _title text; _aud text; _exec text; _q text; _bg text; _opts text; _rec text;
  _ask text; _ev text; _grd text; _rsk text; _nx text; _dn text; _url text;
BEGIN
  SELECT * INTO _row FROM public.governance_records WHERE id = _record_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Record not found' USING ERRCODE='P0002'; END IF;
  IF _row.record_kind IS DISTINCT FROM 'decision_case' THEN
    RAISE EXCEPTION 'Stakeholder packages are only allowed on decision_case records' USING ERRCODE='22023';
  END IF;
  PERFORM public._gov_assert_project_write(_row.project_id);

  IF _package_status NOT IN ('draft','ready') THEN
    RAISE EXCEPTION 'Use mark_governance_record_stakeholder_package_provided to mark a Stakeholder Package as provided.' USING ERRCODE='22023';
  END IF;

  _title := NULLIF(trim(COALESCE(_package_title, '')), '');
  IF _title IS NULL THEN
    RAISE EXCEPTION 'package_title is required' USING ERRCODE='22023';
  END IF;

  _aud  := NULLIF(trim(COALESCE(_audience_text, '')), '');
  _exec := NULLIF(trim(COALESCE(_executive_summary, '')), '');
  _q    := NULLIF(trim(COALESCE(_decision_question_text, '')), '');
  _bg   := NULLIF(trim(COALESCE(_background_context, '')), '');
  _opts := NULLIF(trim(COALESCE(_options_summary, '')), '');
  _rec  := NULLIF(trim(COALESCE(_recommendation_text, '')), '');
  _ask  := NULLIF(trim(COALESCE(_decision_ask_text, '')), '');
  _ev   := NULLIF(trim(COALESCE(_evidence_summary, '')), '');
  _grd  := NULLIF(trim(COALESCE(_guardrails_text, '')), '');
  _rsk  := NULLIF(trim(COALESCE(_residual_risks_text, '')), '');
  _nx   := NULLIF(trim(COALESCE(_next_steps_text, '')), '');
  _dn   := NULLIF(trim(COALESCE(_distribution_note, '')), '');
  _url  := NULLIF(trim(COALESCE(_distribution_evidence_url, '')), '');

  IF _url IS NOT NULL AND _url NOT LIKE 'http://%' AND _url NOT LIKE 'https://%' THEN
    RAISE EXCEPTION 'distribution_evidence_url must start with http:// or https://' USING ERRCODE='22023';
  END IF;

  SELECT COALESCE(MAX(version_number), 0) + 1 INTO _next
    FROM public.governance_record_stakeholder_packages
    WHERE governance_record_id = _record_id;

  IF COALESCE(_make_current, true) THEN
    UPDATE public.governance_record_stakeholder_packages
      SET is_current = false, updated_by = auth.uid(), updated_at = now()
      WHERE governance_record_id = _record_id AND is_current = true;
  END IF;

  INSERT INTO public.governance_record_stakeholder_packages (
    organization_id, workspace_id, project_id, governance_record_id,
    version_number, is_current, package_status,
    audience_text, package_title, executive_summary, decision_question_text,
    background_context, options_summary, recommendation_text, decision_ask_text,
    evidence_summary, guardrails_text, residual_risks_text, next_steps_text,
    distribution_note, distribution_evidence_url,
    provided_to_stakeholders_at, provided_to_stakeholders_by,
    created_by, updated_by
  ) VALUES (
    _row.organization_id, _row.workspace_id, _row.project_id, _record_id,
    _next, COALESCE(_make_current, true), _package_status,
    _aud, _title, _exec, _q,
    _bg, _opts, _rec, _ask,
    _ev, _grd, _rsk, _nx,
    _dn, _url,
    NULL, NULL,
    auth.uid(), auth.uid()
  ) RETURNING id INTO _id;

  PERFORM public.log_activity_event(_row.organization_id, auth.uid(),
    'governance_record_stakeholder_package_created', 'governance_record', _record_id,
    jsonb_build_object('project_id', _row.project_id,
                       'stakeholder_package_id', _id,
                       'version_number', _next,
                       'package_status', _package_status,
                       'is_current', COALESCE(_make_current, true)),
    _row.workspace_id);

  RETURN jsonb_build_object('id', _id, 'version_number', _next);
END; $function$

CREATE OR REPLACE FUNCTION public.create_project_adoption_plan(_project_id uuid, _objective text DEFAULT NULL::text, _adoption_owner_id uuid DEFAULT NULL::uuid, _impacted_audience_summary text DEFAULT NULL::text, _approach_summary text DEFAULT NULL::text, _readiness_status adoption_readiness_status DEFAULT 'not_started'::adoption_readiness_status, _created_from_template boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _org uuid; _ws uuid; _uid uuid := auth.uid(); _id uuid;
BEGIN
  IF _uid IS NULL OR NOT public.is_active_user(_uid) THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  SELECT organization_id, workspace_id INTO _org, _ws FROM public.projects WHERE id = _project_id;
  IF _org IS NULL THEN RAISE EXCEPTION 'invalid_project'; END IF;
  IF NOT public.has_pm_authority(_uid, _ws) THEN RAISE EXCEPTION 'forbidden'; END IF;
  IF EXISTS (SELECT 1 FROM public.adoption_plans WHERE project_id = _project_id AND is_archived = false) THEN
    RAISE EXCEPTION 'adoption_plan_already_exists';
  END IF;

  INSERT INTO public.adoption_plans(
    organization_id, workspace_id, project_id, objective, adoption_owner_id,
    impacted_audience_summary, approach_summary, readiness_status,
    created_from_template, created_by
  ) VALUES (
    _org, _ws, _project_id, _objective, _adoption_owner_id,
    _impacted_audience_summary, _approach_summary, _readiness_status,
    _created_from_template, _uid
  ) RETURNING id INTO _id;

  PERFORM public.log_activity_event(
    _organization_id => _org, _actor_id => _uid,
    _event_type => 'adoption_plan_created',
    _target_type => 'project', _target_id => _project_id,
    _metadata => jsonb_build_object('adoption_plan_id', _id, 'readiness_status', _readiness_status::text),
    _workspace_id => _ws
  );
  RETURN _id;
END $function$

CREATE OR REPLACE FUNCTION public.create_project_benefit(_project_id uuid, _benefit_type text, _metric_name text, _unit_of_measure text, _target_value numeric, _realization_status text DEFAULT 'planned'::text, _custom_benefit_type_label text DEFAULT NULL::text, _description text DEFAULT NULL::text, _baseline_value numeric DEFAULT NULL::numeric, _actual_value numeric DEFAULT NULL::numeric, _benefit_owner_id uuid DEFAULT NULL::uuid, _expected_realization_date date DEFAULT NULL::date, _actual_realization_date date DEFAULT NULL::date, _evidence_note text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  _p record;
  _id uuid;
  _proj_status text;
  _custom text;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE='42501';
  END IF;
  IF NOT public.has_project_pm_authority(auth.uid(), _project_id) THEN
    RAISE EXCEPTION 'Project-edit authority required' USING ERRCODE='42501';
  END IF;

  SELECT organization_id, workspace_id, status::text
    INTO _p FROM public.projects WHERE id = _project_id;
  IF _p IS NULL THEN
    RAISE EXCEPTION 'Project not found' USING ERRCODE='P0002';
  END IF;
  _proj_status := _p.status;

  IF _metric_name IS NULL OR length(btrim(_metric_name)) = 0 THEN
    RAISE EXCEPTION 'metric_name is required' USING ERRCODE='22023';
  END IF;
  IF _unit_of_measure IS NULL OR length(btrim(_unit_of_measure)) = 0 THEN
    RAISE EXCEPTION 'unit_of_measure is required' USING ERRCODE='22023';
  END IF;

  _custom := NULLIF(btrim(COALESCE(_custom_benefit_type_label, '')), '');

  INSERT INTO public.project_benefits (
    organization_id, workspace_id, project_id,
    benefit_type, custom_benefit_type_label,
    metric_name, description, unit_of_measure,
    baseline_value, target_value, actual_value,
    benefit_owner_id, realization_status,
    expected_realization_date, actual_realization_date,
    evidence_note, created_by, updated_by
  ) VALUES (
    _p.organization_id, _p.workspace_id, _project_id,
    _benefit_type, _custom,
    btrim(_metric_name),
    NULLIF(btrim(COALESCE(_description,'')), ''),
    btrim(_unit_of_measure),
    _baseline_value, _target_value, _actual_value,
    _benefit_owner_id, COALESCE(_realization_status,'planned'),
    _expected_realization_date, _actual_realization_date,
    NULLIF(btrim(COALESCE(_evidence_note,'')), ''),
    auth.uid(), auth.uid()
  ) RETURNING id INTO _id;

  PERFORM public.log_activity_event(
    _p.organization_id, auth.uid(),
    'project_benefit_created', 'project_benefit', _id,
    jsonb_build_object(
      'project_id', _project_id,
      'benefit_type', _benefit_type,
      'realization_status', COALESCE(_realization_status,'planned'),
      'project_status_at_event', _proj_status,
      'post_closure', (_proj_status IN ('completed','cancelled'))
    ),
    _p.workspace_id);

  RETURN _id;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_risk_with_links(_title text, _description text, _mitigation_plan text, _likelihood text, _impact text, _status text, _target_type text, _target_id uuid, _organization_id uuid, _workspace_id uuid, _user_links jsonb DEFAULT '[]'::jsonb, _object_links jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_id uuid;
  v jsonb;
  v_idx int;
  v_project_id uuid;
  v_workspace_id uuid;
  v_organization_id uuid;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF NOT public.is_active_user(v_uid) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;

  IF _target_type = 'project' THEN
    SELECT p.id, p.workspace_id, p.organization_id
      INTO v_project_id, v_workspace_id, v_organization_id
      FROM public.projects p WHERE p.id = _target_id;
  ELSIF _target_type = 'phase' THEN
    SELECT p.id, p.workspace_id, p.organization_id
      INTO v_project_id, v_workspace_id, v_organization_id
      FROM public.phases ph
      JOIN public.projects p ON p.id = ph.project_id
      WHERE ph.id = _target_id;
  ELSIF _target_type = 'task' THEN
    SELECT p.id, p.workspace_id, p.organization_id
      INTO v_project_id, v_workspace_id, v_organization_id
      FROM public.tasks t
      JOIN public.projects p ON p.id = t.project_id
      LEFT JOIN public.phases ph ON ph.id = t.phase_id
      WHERE t.id = _target_id
        AND (t.phase_id IS NULL OR ph.project_id = t.project_id);
  ELSE
    RAISE EXCEPTION 'Target is unavailable or not authorized';
  END IF;

  IF v_project_id IS NULL OR v_workspace_id IS NULL OR v_organization_id IS NULL THEN
    RAISE EXCEPTION 'Target is unavailable or not authorized';
  END IF;

  IF _workspace_id IS DISTINCT FROM v_workspace_id
     OR _organization_id IS DISTINCT FROM v_organization_id THEN
    RAISE EXCEPTION 'Target is unavailable or not authorized';
  END IF;

  IF NOT public.has_pm_authority(v_uid, v_workspace_id) THEN
    RAISE EXCEPTION 'Target is unavailable or not authorized';
  END IF;

  IF NOT public.can_write_demo(v_uid, v_workspace_id) THEN
    RAISE EXCEPTION 'Not authorized: this workspace is read-only';
  END IF;

  PERFORM public._validate_object_links(_object_links, v_workspace_id, v_organization_id);
  PERFORM public._validate_user_links(_user_links, v_workspace_id, v_project_id);

  INSERT INTO public.risks (
    organization_id, workspace_id, target_type, target_id,
    title, description, mitigation_plan,
    likelihood, impact, status, reported_by
  ) VALUES (
    v_organization_id, v_workspace_id, _target_type, _target_id,
    _title, _description, _mitigation_plan,
    COALESCE(_likelihood,'medium')::risk_likelihood,
    COALESCE(_impact,'medium')::pm_priority,
    COALESCE(_status,'open')::risk_status,
    v_uid
  ) RETURNING id INTO v_id;

  v_idx := 0;
  FOR v IN SELECT * FROM jsonb_array_elements(COALESCE(_user_links,'[]'::jsonb)) LOOP
    INSERT INTO public.entity_user_links (owner_type, owner_id, organization_id, workspace_id,
                                          user_id, stakeholder_id, link_role, sort_order, created_by)
    VALUES ('risk', v_id, v_organization_id, v_workspace_id,
            NULLIF(v->>'user_id','')::uuid,
            NULLIF(v->>'stakeholder_id','')::uuid,
            'related_person', v_idx, v_uid)
    ON CONFLICT DO NOTHING;
    v_idx := v_idx + 1;
  END LOOP;

  v_idx := 0;
  FOR v IN SELECT * FROM jsonb_array_elements(COALESCE(_object_links,'[]'::jsonb)) LOOP
    INSERT INTO public.entity_object_links (owner_type, owner_id, organization_id, workspace_id, referenced_type, referenced_id, link_role, sort_order, created_by)
    VALUES ('risk', v_id, v_organization_id, v_workspace_id, v->>'referenced_type', (v->>'referenced_id')::uuid, 'related_object', v_idx, v_uid)
    ON CONFLICT DO NOTHING;
    v_idx := v_idx + 1;
  END LOOP;

  RETURN jsonb_build_object('id', v_id);
END $function$

CREATE OR REPLACE FUNCTION public.create_roadmap_story_pack(_title text DEFAULT NULL::text, _guidance text DEFAULT NULL::text, _audience text DEFAULT NULL::text, _focus text DEFAULT NULL::text, _primary_workspace_id uuid DEFAULT NULL::uuid, _program_id uuid DEFAULT NULL::uuid, _scope_config jsonb DEFAULT '{}'::jsonb, _source_config jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _org_id uuid;
  _new_id uuid;
  _cat text;
  _allowed text[] := public.roadmap_story_allowed_source_categories();
  _src_overrides jsonb;
  _enabled boolean;
  _config jsonb;
  _sort integer;
BEGIN
  IF _uid IS NULL OR NOT public.is_active_user(_uid) THEN
    RAISE EXCEPTION 'unauthorized' USING ERRCODE = '42501';
  END IF;

  SELECT organization_id INTO _org_id FROM public.profiles WHERE id = _uid;
  IF _org_id IS NULL THEN RAISE EXCEPTION 'no organization' USING ERRCODE = '42501'; END IF;

  IF _primary_workspace_id IS NOT NULL THEN
    IF NOT EXISTS (SELECT 1 FROM public.workspaces WHERE id = _primary_workspace_id AND organization_id = _org_id)
       OR NOT public.is_workspace_member(_uid, _primary_workspace_id) THEN
      RAISE EXCEPTION 'forbidden: primary workspace not accessible' USING ERRCODE = '42501';
    END IF;
  END IF;

  IF _program_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.programs p
      JOIN public.workspaces w ON w.id = p.workspace_id
      WHERE p.id = _program_id AND w.organization_id = _org_id AND public.is_workspace_member(_uid, p.workspace_id)
    ) THEN
      RAISE EXCEPTION 'forbidden: program not accessible' USING ERRCODE = '42501';
    END IF;
  END IF;

  PERFORM public.validate_roadmap_story_scope(_uid, _org_id, _scope_config);

  INSERT INTO public.roadmap_story_packs (
    organization_id, primary_workspace_id, program_id, created_by, status,
    scope_config, source_config,
    title_encrypted, user_guidance_encrypted, audience, focus
  ) VALUES (
    _org_id, _primary_workspace_id, _program_id, _uid, 'draft',
    COALESCE(_scope_config, '{}'::jsonb), COALESCE(_source_config, '{}'::jsonb),
    CASE WHEN _title    IS NOT NULL THEN public.btpm_encrypt(_title,    _org_id) END,
    CASE WHEN _guidance IS NOT NULL THEN public.btpm_encrypt(_guidance, _org_id) END,
    _audience, _focus
  ) RETURNING id INTO _new_id;

  -- Seed default source categories (all enabled, no category mandatory/locked).
  -- _source_config may carry overrides keyed by category: { "<cat>": { "enabled": bool, "config": {...}, "sort_order": n } }
  _src_overrides := COALESCE(_source_config->'categories', '{}'::jsonb);
  FOREACH _cat IN ARRAY _allowed LOOP
    _enabled := COALESCE((_src_overrides->_cat->>'enabled')::boolean, true);
    _config  := COALESCE(_src_overrides->_cat->'config', '{}'::jsonb);
    _sort    := NULLIF(_src_overrides->_cat->>'sort_order','')::integer;
    INSERT INTO public.roadmap_story_pack_sources (story_pack_id, source_category, is_enabled, config, sort_order)
    VALUES (_new_id, _cat, _enabled, _config, _sort);
  END LOOP;

  RETURN _new_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_workspace(_name text, _description text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _org_id UUID;
  _ws_id UUID;
  _user_id UUID;
BEGIN
  _user_id := auth.uid();
  IF _user_id IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF NOT public.is_active_user(_user_id) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;

  SELECT organization_id INTO _org_id FROM public.profiles WHERE id = _user_id;
  IF _org_id IS NULL THEN RAISE EXCEPTION 'User does not belong to an organization'; END IF;
  IF NOT public.is_org_admin(_user_id, _org_id) THEN RAISE EXCEPTION 'Only organization admins can create workspaces'; END IF;

  INSERT INTO public.workspaces (name, description, organization_id, created_by) VALUES (_name, _description, _org_id, _user_id) RETURNING id INTO _ws_id;
  INSERT INTO public.workspace_memberships (workspace_id, user_id) VALUES (_ws_id, _user_id);
  INSERT INTO public.user_roles (user_id, role, organization_id, workspace_id) VALUES (_user_id, 'workspace_admin', _org_id, _ws_id);
  RETURN _ws_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_workspace_in_organization(_organization_id uuid, _name text, _description text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _ws_id UUID;
  _user_id UUID;
BEGIN
  _user_id := auth.uid();
  IF _user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  IF NOT public.is_active_user(_user_id) THEN
    RAISE EXCEPTION 'Account is deactivated';
  END IF;
  IF _organization_id IS NULL THEN
    RAISE EXCEPTION 'organization_id is required';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.organizations WHERE id = _organization_id) THEN
    RAISE EXCEPTION 'Organization not found';
  END IF;
  IF NOT public.is_user_org_admin(_user_id, _organization_id) THEN
    RAISE EXCEPTION 'Only organization admins can create workspaces in this organization';
  END IF;
  IF _name IS NULL OR btrim(_name) = '' THEN
    RAISE EXCEPTION 'Workspace name is required';
  END IF;

  INSERT INTO public.workspaces (name, description, organization_id, created_by)
  VALUES (btrim(_name), _description, _organization_id, _user_id)
  RETURNING id INTO _ws_id;

  INSERT INTO public.workspace_memberships (workspace_id, user_id)
  VALUES (_ws_id, _user_id);

  INSERT INTO public.user_roles (user_id, role, organization_id, workspace_id)
  VALUES (_user_id, 'workspace_admin', _organization_id, _ws_id);

  RETURN _ws_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.deactivate_workspace(_workspace_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_org uuid;
  v_actor uuid := auth.uid();
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'NOT_AUTHENTICATED' USING ERRCODE = '42501';
  END IF;

  SELECT organization_id INTO v_org
    FROM public.workspaces
   WHERE id = _workspace_id;

  IF v_org IS NULL THEN
    RAISE EXCEPTION 'WORKSPACE_NOT_FOUND' USING ERRCODE = 'P0002';
  END IF;

  -- Authority: Org Admin only (Workspace Admin is NOT sufficient)
  IF NOT public.is_org_admin(v_actor, v_org) THEN
    RAISE EXCEPTION 'NOT_AUTHORIZED_ORG_ADMIN_REQUIRED' USING ERRCODE = '42501';
  END IF;

  -- Idempotent flip; preserve all child data, memberships, history
  UPDATE public.workspaces
     SET is_active  = false,
         updated_at = now()
   WHERE id = _workspace_id
     AND is_active = true;

  -- Activity log
  INSERT INTO public.activity_events
    (organization_id, workspace_id, actor_id, target_type, target_id, event_type, metadata)
  VALUES
    (v_org, _workspace_id, v_actor, 'workspace', _workspace_id,
     'workspace.deactivated',
     jsonb_build_object('lifecycle', 'deactivate', 'step', '5.4')::text);
END;
$function$

CREATE OR REPLACE FUNCTION public.delete_roadmap_story_pack_note(_note_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _story_pack_id uuid;
BEGIN
  IF _uid IS NULL OR NOT public.is_active_user(_uid) THEN
    RAISE EXCEPTION 'unauthorized' USING ERRCODE = '42501';
  END IF;
  SELECT story_pack_id INTO _story_pack_id FROM public.roadmap_story_pack_notes WHERE id = _note_id;
  IF _story_pack_id IS NULL OR NOT public.is_story_pack_owner(_uid, _story_pack_id) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  PERFORM public.assert_roadmap_story_pack_editable(_story_pack_id);
  DELETE FROM public.roadmap_story_pack_notes WHERE id = _note_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.disable_sharepoint_project_binding(_binding_id uuid)
 RETURNS sharepoint_project_bindings
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_row public.sharepoint_project_bindings;
BEGIN
  IF NOT public.is_active_user(auth.uid()) THEN
    RAISE EXCEPTION 'unauthorized';
  END IF;

  SELECT * INTO v_row FROM public.sharepoint_project_bindings WHERE id = _binding_id;
  IF v_row.id IS NULL THEN
    RAISE EXCEPTION 'binding_not_found';
  END IF;

  IF NOT public.has_project_pm_authority(auth.uid(), v_row.project_id) THEN
    RAISE EXCEPTION 'unauthorized';
  END IF;

  UPDATE public.sharepoint_project_bindings
  SET binding_status = 'disabled',
      disabled_at    = now(),
      disabled_by    = auth.uid(),
      updated_by     = auth.uid()
  WHERE id = _binding_id
  RETURNING * INTO v_row;

  RETURN v_row;
END;
$function$

CREATE OR REPLACE FUNCTION public.disable_sharepoint_workspace_binding(_binding_id uuid)
 RETURNS sharepoint_workspace_bindings
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_row public.sharepoint_workspace_bindings;
BEGIN
  IF NOT public.is_active_user(auth.uid()) THEN
    RAISE EXCEPTION 'unauthorized';
  END IF;

  SELECT * INTO v_row FROM public.sharepoint_workspace_bindings WHERE id = _binding_id;
  IF v_row.id IS NULL THEN
    RAISE EXCEPTION 'binding_not_found';
  END IF;

  -- SP authority tightening: Org Admin only.
  IF NOT public.is_org_admin(auth.uid(), v_row.organization_id) THEN
    RAISE EXCEPTION 'unauthorized';
  END IF;

  UPDATE public.sharepoint_workspace_bindings
  SET binding_status = 'disabled',
      disabled_at    = now(),
      disabled_by    = auth.uid(),
      updated_by     = auth.uid()
  WHERE id = _binding_id
  RETURNING * INTO v_row;

  RETURN v_row;
END;
$function$

CREATE OR REPLACE FUNCTION public.enqueue_tenant_background_job(_tenant_id uuid, _job_type text, _payload jsonb DEFAULT '{}'::jsonb, _organization_id uuid DEFAULT NULL::uuid, _workspace_id uuid DEFAULT NULL::uuid, _priority integer DEFAULT 100, _idempotency_key text DEFAULT NULL::text, _max_attempts integer DEFAULT 3, _not_before timestamp with time zone DEFAULT NULL::timestamp with time zone, _run_as_user_id uuid DEFAULT NULL::uuid)
 RETURNS tenant_background_jobs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _row public.tenant_background_jobs;
  _org_tenant uuid;
  _actor uuid := auth.uid();
  _effective_run_as uuid;
  _is_tenant_admin boolean;
  _is_org_admin boolean;
BEGIN
  IF _actor IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF _tenant_id IS NULL THEN RAISE EXCEPTION 'tenant_id is required'; END IF;
  IF _job_type IS NULL OR length(btrim(_job_type)) = 0 THEN RAISE EXCEPTION 'job_type is required'; END IF;
  IF jsonb_typeof(COALESCE(_payload, '{}'::jsonb)) <> 'object' THEN
    RAISE EXCEPTION 'payload must be a JSON object';
  END IF;
  PERFORM public._assert_job_payload_no_secret_keys(COALESCE(_payload, '{}'::jsonb));

  IF NOT (
    public.is_platform_super_admin(_actor)
    OR public.is_tenant_admin(_tenant_id, _actor)
    OR (_organization_id IS NOT NULL AND public.is_organization_admin(_organization_id, _actor))
    OR (_workspace_id IS NOT NULL AND public.is_workspace_member(_actor, _workspace_id))
  ) THEN
    RAISE EXCEPTION 'Not authorized to enqueue job in this scope' USING ERRCODE = '42501';
  END IF;

  IF _organization_id IS NOT NULL THEN
    SELECT tenant_id INTO _org_tenant FROM public.organizations WHERE id = _organization_id;
    IF _org_tenant IS NULL OR _org_tenant <> _tenant_id THEN
      RAISE EXCEPTION 'Organization % does not belong to tenant %', _organization_id, _tenant_id;
    END IF;
  END IF;

  _effective_run_as := COALESCE(_run_as_user_id, _actor);
  IF _effective_run_as <> _actor THEN
    _is_tenant_admin := public.is_tenant_admin(_tenant_id, _actor) OR public.is_platform_super_admin(_actor);
    _is_org_admin := (_organization_id IS NOT NULL AND public.is_organization_admin(_organization_id, _actor));
    IF NOT (_is_tenant_admin OR _is_org_admin) THEN
      RAISE EXCEPTION 'Only tenant or organization admins may set run_as_user_id to another user'
        USING ERRCODE = '42501';
    END IF;
    IF NOT public.is_tenant_member(_tenant_id, _effective_run_as) THEN
      RAISE EXCEPTION 'run_as_user_id is not an active tenant member';
    END IF;
    IF _organization_id IS NOT NULL
       AND NOT public.is_organization_member(_organization_id, _effective_run_as) THEN
      RAISE EXCEPTION 'run_as_user_id is not an active organization member';
    END IF;
    IF _workspace_id IS NOT NULL
       AND NOT public.is_workspace_member(_effective_run_as, _workspace_id) THEN
      RAISE EXCEPTION 'run_as_user_id is not an active workspace member';
    END IF;
  END IF;

  IF _idempotency_key IS NOT NULL THEN
    SELECT * INTO _row FROM public.tenant_background_jobs
      WHERE tenant_id = _tenant_id AND job_type = _job_type AND idempotency_key = _idempotency_key;
    IF _row.id IS NOT NULL THEN RETURN _row; END IF;
  END IF;

  INSERT INTO public.tenant_background_jobs (
    tenant_id, organization_id, workspace_id, job_type, priority,
    requested_by, run_as_user_id, idempotency_key, payload, max_attempts, not_before
  ) VALUES (
    _tenant_id, _organization_id, _workspace_id, _job_type, COALESCE(_priority, 100),
    _actor, _effective_run_as, _idempotency_key, COALESCE(_payload, '{}'::jsonb),
    COALESCE(_max_attempts, 3), _not_before
  ) RETURNING * INTO _row;
  RETURN _row;
END $function$

CREATE OR REPLACE FUNCTION public.ensure_user_profile()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE _user_id uuid; _email text;
BEGIN
  _user_id := auth.uid(); IF _user_id IS NULL THEN RETURN; END IF;
  SELECT email INTO _email FROM auth.users WHERE id = _user_id;
  INSERT INTO public.profiles (id, email) VALUES (_user_id, lower(_email)) ON CONFLICT (id) DO UPDATE SET email = COALESCE(profiles.email, EXCLUDED.email), updated_at = now();
END;
$function$

CREATE OR REPLACE FUNCTION public.fail_roadmap_story_generation_run(_run_id uuid, _error_text text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _run public.roadmap_story_ai_runs;
  _pack public.roadmap_story_packs;
BEGIN
  IF _uid IS NULL OR NOT public.is_active_user(_uid) THEN
    RAISE EXCEPTION 'unauthorized' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO _run FROM public.roadmap_story_ai_runs WHERE id = _run_id;
  IF NOT FOUND OR _run.created_by <> _uid THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO _pack FROM public.roadmap_story_packs WHERE id = _run.story_pack_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  UPDATE public.roadmap_story_ai_runs
  SET status = 'failed',
      completed_at = now(),
      error_text_encrypted = CASE WHEN _error_text IS NULL OR _error_text = '' THEN NULL
                                  ELSE public.btpm_encrypt(_error_text, _pack.organization_id) END
  WHERE id = _run_id;
END;
$function$

