CREATE OR REPLACE FUNCTION public.generate_project_adoption_plan_from_saved_template(_project_id uuid, _template_id uuid DEFAULT NULL::uuid, _template_key text DEFAULT 'btpm_standard_adoption'::text, _phase_name text DEFAULT 'Adoption & Readiness'::text, _phase_start_date date DEFAULT NULL::date, _phase_end_date date DEFAULT NULL::date, _selection jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _org uuid;
  _ws uuid;
  _is_baselined boolean := false;
  _phase_start date;
  _phase_end date;
  _plan_id uuid;
  _phase_id uuid;
  _next_phase_sort int;
  _initiative_id uuid;
  _initiative_count int := 0;
  _task_count int := 0;
  _selected_task_count int := 0;
  _custom_task_count int := 0;
  _selected_keys text[] := NULL;
  _custom_tasks jsonb := '[]'::jsonb;
  _has_selection boolean := false;
  _valid_init_keys text[] := ARRAY[]::text[];
  _valid_task_keys text[] := ARRAY[]::text[];
  _k text;
  _ct jsonb;
  _ikey text;
  _init_row record;
  _task_row record;
  _selected_in_init int;
  _sort int;
  _template_name text;
BEGIN
  IF _uid IS NULL OR NOT public.is_active_user(_uid) THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;

  -- Delegate to existing CM.7A path when standard template selected
  IF _template_id IS NULL THEN
    IF COALESCE(_template_key, 'btpm_standard_adoption') <> 'btpm_standard_adoption' THEN
      RAISE EXCEPTION 'invalid_template_key';
    END IF;
    RETURN public.generate_project_adoption_plan_from_template(
      _project_id, true, _phase_name, _selection, _phase_start_date, _phase_end_date
    );
  END IF;

  -- Saved custom template path
  SELECT organization_id, workspace_id, COALESCE(is_baselined,false)
    INTO _org, _ws, _is_baselined
  FROM public.projects WHERE id = _project_id;
  IF _org IS NULL THEN RAISE EXCEPTION 'invalid_project'; END IF;

  IF NOT public.has_pm_authority(_uid, _ws) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  IF EXISTS (SELECT 1 FROM public.adoption_plans
             WHERE project_id = _project_id AND is_archived = false) THEN
    RAISE EXCEPTION 'adoption_plan_already_exists';
  END IF;

  -- Validate template exists and belongs to project's workspace; capture decrypted name
  SELECT public.btpm_decrypt(name, organization_id) INTO _template_name
  FROM public.adoption_templates
  WHERE id = _template_id AND workspace_id = _ws AND is_archived = false;
  IF _template_name IS NULL THEN
    RAISE EXCEPTION 'invalid_template';
  END IF;

  -- Phase date rules
  IF _is_baselined AND (_phase_start_date IS NULL OR _phase_end_date IS NULL) THEN
    RAISE EXCEPTION 'adoption_phase_dates_required_for_baselined_project';
  END IF;
  IF _phase_start_date IS NOT NULL AND _phase_end_date IS NOT NULL
     AND _phase_end_date < _phase_start_date THEN
    RAISE EXCEPTION 'adoption_phase_end_before_start';
  END IF;
  _phase_start := _phase_start_date;
  _phase_end := _phase_end_date;

  -- Build valid key sets from saved template
  SELECT array_agg(template_key) INTO _valid_init_keys
  FROM public.adoption_template_initiatives
  WHERE adoption_template_id = _template_id AND is_archived = false;

  SELECT array_agg(format('%s.%s', i.template_key, t.template_key)) INTO _valid_task_keys
  FROM public.adoption_template_initiatives i
  JOIN public.adoption_template_tasks t ON t.adoption_template_initiative_id = i.id
  WHERE i.adoption_template_id = _template_id
    AND i.is_archived = false AND t.is_archived = false;

  -- Parse selection
  IF _selection IS NOT NULL THEN
    IF jsonb_typeof(_selection) <> 'object' THEN
      RAISE EXCEPTION 'adoption_template_selection_invalid';
    END IF;
    _has_selection := true;
    IF _selection ? 'selected_task_keys' AND jsonb_typeof(_selection->'selected_task_keys') = 'array' THEN
      SELECT array_agg(value::text) INTO _selected_keys
      FROM jsonb_array_elements_text(_selection->'selected_task_keys');
      _selected_keys := COALESCE(_selected_keys, ARRAY[]::text[]);
      FOREACH _k IN ARRAY _selected_keys LOOP
        IF NOT (_k = ANY(COALESCE(_valid_task_keys, ARRAY[]::text[]))) THEN
          RAISE EXCEPTION 'adoption_template_selection_invalid';
        END IF;
      END LOOP;
    ELSE
      _selected_keys := ARRAY[]::text[];
    END IF;
    IF _selection ? 'custom_tasks' AND jsonb_typeof(_selection->'custom_tasks') = 'array' THEN
      _custom_tasks := _selection->'custom_tasks';
      FOR _ct IN SELECT value FROM jsonb_array_elements(_custom_tasks) AS value LOOP
        _ikey := _ct->>'initiative_key';
        IF _ikey IS NULL OR NOT (_ikey = ANY(COALESCE(_valid_init_keys, ARRAY[]::text[]))) THEN
          RAISE EXCEPTION 'adoption_template_selection_invalid';
        END IF;
        IF COALESCE(btrim(_ct->>'title'),'') = '' THEN
          RAISE EXCEPTION 'adoption_template_selection_invalid';
        END IF;
      END LOOP;
    END IF;
    IF (COALESCE(array_length(_selected_keys,1),0) + COALESCE(jsonb_array_length(_custom_tasks),0)) = 0 THEN
      RAISE EXCEPTION 'adoption_template_selection_empty';
    END IF;
  END IF;

  _selected_task_count := COALESCE(array_length(_selected_keys,1),0);
  _custom_task_count := COALESCE(jsonb_array_length(_custom_tasks),0);

  -- Create adoption plan
  INSERT INTO public.adoption_plans(
    organization_id, workspace_id, project_id,
    objective, impacted_audience_summary, approach_summary,
    readiness_status, created_from_template, enabled, created_by
  ) VALUES (
    _org, _ws, _project_id,
    'Drive successful adoption of the change delivered by this project so impacted users work in the new way and the expected business outcome is realized.',
    'All users, teams, and stakeholder groups directly affected by the change delivered by this project. Refine the audience as stakeholder analysis progresses.',
    'Use the saved workspace adoption template chosen at generation time.',
    'preparing', true, true, _uid
  ) RETURNING id INTO _plan_id;

  SELECT COALESCE(MAX(sort_order), -1) + 1 INTO _next_phase_sort
  FROM public.phases WHERE project_id = _project_id AND is_archived = false;

  INSERT INTO public.phases(
    organization_id, workspace_id, project_id,
    name, description, status, sort_order,
    start_date, target_end_date, created_by
  ) VALUES (
    _org, _ws, _project_id,
    _phase_name,
    'Contains people-side adoption work generated from a saved workspace Adoption Template. Tasks here are normal BTPM tasks linked to Adoption Initiatives.',
    'planned', _next_phase_sort,
    _phase_start, _phase_end, _uid
  ) RETURNING id INTO _phase_id;

  -- Iterate saved template initiatives (do NOT mutate template rows)
  FOR _init_row IN
    SELECT id, template_key, name, summary, readiness_area, sort_order, organization_id
    FROM public.adoption_template_initiatives
    WHERE adoption_template_id = _template_id AND is_archived = false
    ORDER BY sort_order, template_key
  LOOP
    _selected_in_init := 0;
    IF _has_selection THEN
      SELECT COUNT(*) INTO _selected_in_init
      FROM public.adoption_template_tasks t
      WHERE t.adoption_template_initiative_id = _init_row.id
        AND t.is_archived = false
        AND format('%s.%s', _init_row.template_key, t.template_key) = ANY(_selected_keys);
      _selected_in_init := _selected_in_init + (
        SELECT COUNT(*) FROM jsonb_array_elements(_custom_tasks) AS c
        WHERE c->>'initiative_key' = _init_row.template_key
      );
    ELSE
      SELECT COUNT(*) INTO _selected_in_init
      FROM public.adoption_template_tasks t
      WHERE t.adoption_template_initiative_id = _init_row.id AND t.is_archived = false;
    END IF;

    IF _selected_in_init = 0 THEN CONTINUE; END IF;

    INSERT INTO public.adoption_initiatives(
      organization_id, workspace_id, project_id, adoption_plan_id,
      name, summary, readiness_area, status, priority, sort_order, created_by
    ) VALUES (
      _org, _ws, _project_id, _plan_id,
      public.btpm_decrypt(_init_row.name, _init_row.organization_id),
      public.btpm_decrypt(_init_row.summary, _init_row.organization_id),
      _init_row.readiness_area,
      'planned'::public.adoption_initiative_status,
      'medium'::public.pm_priority,
      _init_row.sort_order,
      _uid
    ) RETURNING id INTO _initiative_id;
    _initiative_count := _initiative_count + 1;

    _sort := 0;
    -- Selected template tasks → normal BTPM tasks
    FOR _task_row IN
      SELECT t.template_key, t.title, t.description, t.sort_order, t.organization_id
      FROM public.adoption_template_tasks t
      WHERE t.adoption_template_initiative_id = _init_row.id
        AND t.is_archived = false
        AND (
          NOT _has_selection
          OR format('%s.%s', _init_row.template_key, t.template_key) = ANY(_selected_keys)
        )
      ORDER BY t.sort_order, t.template_key
    LOOP
      INSERT INTO public.tasks(
        organization_id, workspace_id, project_id, phase_id,
        name, description, task_type, status, priority, sort_order,
        start_date, due_date,
        is_adoption_related, adoption_initiative_id, created_by
      ) VALUES (
        _org, _ws, _project_id, _phase_id,
        public.btpm_decrypt(_task_row.title, _task_row.organization_id),
        public.btpm_decrypt(_task_row.description, _task_row.organization_id),
        'work_item'::public.task_type,
        'planned'::public.pm_status,
        'medium'::public.pm_priority,
        _sort,
        _phase_start, _phase_end,
        true, _initiative_id, _uid
      );
      _sort := _sort + 10;
      _task_count := _task_count + 1;
    END LOOP;

    -- Custom tasks attached to this initiative (single, correct loop)
    FOR _ct IN
      SELECT c FROM jsonb_array_elements(_custom_tasks) AS c
      WHERE c->>'initiative_key' = _init_row.template_key
    LOOP
      INSERT INTO public.tasks(
        organization_id, workspace_id, project_id, phase_id,
        name, description, task_type, status, priority, sort_order,
        start_date, due_date,
        is_adoption_related, adoption_initiative_id, created_by
      ) VALUES (
        _org, _ws, _project_id, _phase_id,
        btrim(_ct->>'title'),
        NULLIF(btrim(COALESCE(_ct->>'description','')),''),
        'work_item'::public.task_type,
        'planned'::public.pm_status,
        'medium'::public.pm_priority,
        _sort,
        _phase_start, _phase_end,
        true, _initiative_id, _uid
      );
      _sort := _sort + 10;
      _task_count := _task_count + 1;
    END LOOP;
  END LOOP;

  -- Activity event via canonical helper (uses event_type, not action)
  PERFORM public.log_activity_event(
    _org,
    _uid,
    'adoption_template_generated',
    'project',
    _project_id,
    jsonb_build_object(
      'adoption_plan_id', _plan_id,
      'created_phase_id', _phase_id,
      'created_initiative_count', _initiative_count,
      'created_task_count', _task_count,
      'selected_task_count', _selected_task_count,
      'custom_task_count', _custom_task_count,
      'generated_from_selection', _has_selection,
      'template_name', _template_name,
      'template_id', _template_id,
      'template_source', 'workspace',
      'phase_name', _phase_name,
      'phase_start_date', _phase_start,
      'phase_end_date', _phase_end,
      'is_baselined_project', _is_baselined
    ),
    _ws
  );

  RETURN jsonb_build_object(
    'adoption_plan_id', _plan_id,
    'phase_id', _phase_id,
    'initiative_count', _initiative_count,
    'task_count', _task_count,
    'template_id', _template_id,
    'template_source', 'workspace'
  );
END $function$

CREATE OR REPLACE FUNCTION public.generate_project_adoption_plan_from_template(_project_id uuid, _create_phase boolean DEFAULT true, _phase_name text DEFAULT 'Adoption & Readiness'::text, _selection jsonb DEFAULT NULL::jsonb, _phase_start_date date DEFAULT NULL::date, _phase_end_date date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _org uuid;
  _ws  uuid;
  _proj_start date;
  _proj_end   date;
  _is_baselined boolean := false;
  _phase_start date;
  _phase_end   date;
  _plan_id uuid;
  _phase_id uuid := NULL;
  _next_phase_sort int;
  _template jsonb;
  _init jsonb;
  _initiative_id uuid;
  _task_sort int := 0;
  _initiative_count int := 0;
  _task_count int := 0;
  _initiative_map jsonb := '[]'::jsonb;
  _selected_keys text[] := NULL;
  _custom_tasks jsonb := '[]'::jsonb;
  _has_selection boolean := false;
  _selected_std_count int := 0;
  _custom_count int := 0;
  _valid_task_keys text[] := ARRAY[]::text[];
  _valid_init_keys text[] := ARRAY[]::text[];
  _k text;
  _ct jsonb;
  _init_key text;
  _selected_in_init int;
  _custom_titles_for_init text[];
  _custom_descs_for_init text[];
  _picked_titles text[];
BEGIN
  IF _uid IS NULL OR NOT public.is_active_user(_uid) THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;

  SELECT organization_id, workspace_id, start_date, target_end_date, COALESCE(is_baselined, false)
    INTO _org, _ws, _proj_start, _proj_end, _is_baselined
  FROM public.projects WHERE id = _project_id;
  IF _org IS NULL THEN
    RAISE EXCEPTION 'invalid_project';
  END IF;

  IF NOT public.has_pm_authority(_uid, _ws) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  IF EXISTS (SELECT 1 FROM public.adoption_plans
             WHERE project_id = _project_id AND is_archived = false) THEN
    RAISE EXCEPTION 'adoption_plan_already_exists';
  END IF;

  IF NOT _create_phase THEN
    RAISE EXCEPTION 'phase_required_for_task_generation';
  END IF;

  _template := public._btpm_adoption_template_v1();

  SELECT array_agg(i->>'key') INTO _valid_init_keys
  FROM jsonb_array_elements(_template) AS i;

  SELECT array_agg(format('%s.%s', i->>'key', t->>'key')) INTO _valid_task_keys
  FROM jsonb_array_elements(_template) AS i,
       jsonb_array_elements(i->'tasks') AS t;

  IF _selection IS NOT NULL THEN
    IF jsonb_typeof(_selection) <> 'object' THEN
      RAISE EXCEPTION 'adoption_template_selection_invalid';
    END IF;
    _has_selection := true;

    IF _selection ? 'selected_task_keys' AND jsonb_typeof(_selection->'selected_task_keys') <> 'null' THEN
      IF jsonb_typeof(_selection->'selected_task_keys') <> 'array' THEN
        RAISE EXCEPTION 'adoption_template_selection_invalid';
      END IF;
      SELECT array_agg(value::text) INTO _selected_keys
      FROM jsonb_array_elements_text(_selection->'selected_task_keys');
      _selected_keys := COALESCE(_selected_keys, ARRAY[]::text[]);
      FOREACH _k IN ARRAY _selected_keys LOOP
        IF NOT (_k = ANY(_valid_task_keys)) THEN
          RAISE EXCEPTION 'adoption_template_selection_invalid';
        END IF;
      END LOOP;
      _selected_std_count := COALESCE(array_length(_selected_keys, 1), 0);
    ELSE
      _selected_keys := ARRAY[]::text[];
    END IF;

    IF _selection ? 'custom_tasks' AND jsonb_typeof(_selection->'custom_tasks') <> 'null' THEN
      IF jsonb_typeof(_selection->'custom_tasks') <> 'array' THEN
        RAISE EXCEPTION 'adoption_template_selection_invalid';
      END IF;
      _custom_tasks := _selection->'custom_tasks';
      FOR _ct IN SELECT * FROM jsonb_array_elements(_custom_tasks) LOOP
        IF jsonb_typeof(_ct) <> 'object' THEN
          RAISE EXCEPTION 'adoption_template_selection_invalid';
        END IF;
        _init_key := _ct->>'initiative_key';
        IF _init_key IS NULL OR NOT (_init_key = ANY(_valid_init_keys)) THEN
          RAISE EXCEPTION 'adoption_template_selection_invalid';
        END IF;
        IF COALESCE(btrim(_ct->>'title'),'') = '' THEN
          RAISE EXCEPTION 'adoption_template_selection_invalid';
        END IF;
        _custom_count := _custom_count + 1;
      END LOOP;
    END IF;

    IF (_selected_std_count + _custom_count) = 0 THEN
      RAISE EXCEPTION 'adoption_template_selection_empty';
    END IF;
  END IF;

  -- Phase dates: use ONLY caller-confirmed dates. No hidden fabrication.
  _phase_start := _phase_start_date;
  _phase_end   := _phase_end_date;

  IF _phase_start IS NOT NULL AND _phase_end IS NOT NULL AND _phase_end < _phase_start THEN
    RAISE EXCEPTION 'adoption_phase_end_before_start';
  END IF;

  -- Baselined projects require explicit phase dates so generated tasks can carry planned dates.
  IF _is_baselined AND (_phase_start IS NULL OR _phase_end IS NULL) THEN
    RAISE EXCEPTION 'adoption_phase_dates_required_for_baselined_project';
  END IF;

  INSERT INTO public.adoption_plans(
    organization_id, workspace_id, project_id,
    objective, impacted_audience_summary, approach_summary,
    readiness_status, created_from_template, enabled, created_by
  ) VALUES (
    _org, _ws, _project_id,
    'Drive successful adoption of the change delivered by this project so impacted users work in the new way and the expected business outcome is realized.',
    'All users, teams, and stakeholder groups directly affected by the change delivered by this project. Refine the audience as stakeholder analysis progresses.',
    'Use the BTPM standard adoption approach: stakeholder impact, sponsor alignment, communication, training and enablement, feedback, adoption tracking, hypercare, and reinforcement.',
    'preparing', true, true, _uid
  ) RETURNING id INTO _plan_id;

  SELECT COALESCE(MAX(sort_order), -1) + 1 INTO _next_phase_sort
  FROM public.phases
  WHERE project_id = _project_id AND is_archived = false;

  INSERT INTO public.phases(
    organization_id, workspace_id, project_id,
    name, description, status, sort_order,
    start_date, target_end_date, created_by
  ) VALUES (
    _org, _ws, _project_id,
    _phase_name,
    'Contains people-side adoption work generated from the BTPM Adoption Plan template. Tasks here are normal BTPM tasks linked to Adoption Initiatives.',
    'planned', _next_phase_sort,
    _phase_start, _phase_end, _uid
  ) RETURNING id INTO _phase_id;

  FOR _init IN SELECT * FROM jsonb_array_elements(_template)
  LOOP
    _init_key := _init->>'key';

    IF _has_selection THEN
      SELECT COALESCE(array_agg(t->>'title' ORDER BY ord), ARRAY[]::text[])
        INTO _picked_titles
      FROM jsonb_array_elements(_init->'tasks') WITH ORDINALITY AS x(t, ord)
      WHERE format('%s.%s', _init_key, t->>'key') = ANY(_selected_keys);
    ELSE
      SELECT COALESCE(array_agg(t->>'title' ORDER BY ord), ARRAY[]::text[])
        INTO _picked_titles
      FROM jsonb_array_elements(_init->'tasks') WITH ORDINALITY AS x(t, ord);
    END IF;

    IF _has_selection THEN
      SELECT
        COALESCE(array_agg(ct->>'title' ORDER BY ord), ARRAY[]::text[]),
        COALESCE(array_agg(NULLIF(btrim(COALESCE(ct->>'description','')), '') ORDER BY ord), ARRAY[]::text[])
        INTO _custom_titles_for_init, _custom_descs_for_init
      FROM jsonb_array_elements(_custom_tasks) WITH ORDINALITY AS y(ct, ord)
      WHERE ct->>'initiative_key' = _init_key;
    ELSE
      _custom_titles_for_init := ARRAY[]::text[];
      _custom_descs_for_init  := ARRAY[]::text[];
    END IF;

    _selected_in_init := COALESCE(array_length(_picked_titles, 1), 0)
                       + COALESCE(array_length(_custom_titles_for_init, 1), 0);

    IF _selected_in_init = 0 THEN
      CONTINUE;
    END IF;

    INSERT INTO public.adoption_initiatives(
      organization_id, workspace_id, project_id, adoption_plan_id,
      name, summary, readiness_area, status, priority, sort_order, created_by
    ) VALUES (
      _org, _ws, _project_id, _plan_id,
      _init->>'name',
      _init->>'summary',
      (_init->>'readiness_area')::public.adoption_readiness_area,
      'planned'::public.adoption_initiative_status,
      'medium'::public.pm_priority,
      (_init->>'sort_order')::int,
      _uid
    ) RETURNING id INTO _initiative_id;

    _initiative_count := _initiative_count + 1;
    _initiative_map := _initiative_map || jsonb_build_object(
      'initiative_id', _initiative_id, 'name', _init->>'name', 'key', _init_key
    );

    IF COALESCE(array_length(_picked_titles, 1), 0) > 0 THEN
      FOR i IN 1..array_length(_picked_titles, 1) LOOP
        INSERT INTO public.tasks(
          organization_id, workspace_id, project_id, phase_id,
          name, task_type, status, priority, sort_order,
          start_date, due_date,
          is_adoption_related, adoption_initiative_id, created_by
        ) VALUES (
          _org, _ws, _project_id, _phase_id,
          _picked_titles[i],
          'work_item'::public.task_type,
          'planned'::public.pm_status,
          'medium'::public.pm_priority,
          _task_sort,
          _phase_start, _phase_end,
          true, _initiative_id, _uid
        );
        _task_sort := _task_sort + 1;
        _task_count := _task_count + 1;
      END LOOP;
    END IF;

    IF COALESCE(array_length(_custom_titles_for_init, 1), 0) > 0 THEN
      FOR i IN 1..array_length(_custom_titles_for_init, 1) LOOP
        INSERT INTO public.tasks(
          organization_id, workspace_id, project_id, phase_id,
          name, description, task_type, status, priority, sort_order,
          start_date, due_date,
          is_adoption_related, adoption_initiative_id, created_by
        ) VALUES (
          _org, _ws, _project_id, _phase_id,
          _custom_titles_for_init[i],
          _custom_descs_for_init[i],
          'work_item'::public.task_type,
          'planned'::public.pm_status,
          'medium'::public.pm_priority,
          _task_sort,
          _phase_start, _phase_end,
          true, _initiative_id, _uid
        );
        _task_sort := _task_sort + 1;
        _task_count := _task_count + 1;
      END LOOP;
    END IF;
  END LOOP;

  PERFORM public.log_activity_event(
    _organization_id => _org,
    _actor_id        => _uid,
    _event_type      => 'adoption_template_generated',
    _target_type     => 'project',
    _target_id       => _project_id,
    _metadata        => jsonb_build_object(
      'adoption_plan_id', _plan_id,
      'created_phase_id', _phase_id,
      'created_initiative_count', _initiative_count,
      'created_task_count', _task_count,
      'phase_start_date', _phase_start,
      'phase_end_date',   _phase_end,
      'is_baselined_project', _is_baselined,
      'selection_mode', CASE WHEN _has_selection THEN 'selective' ELSE 'full_template' END,
      'selected_standard_task_count', _selected_std_count,
      'selected_custom_task_count', _custom_count
    )
  );

  RETURN jsonb_build_object(
    'adoption_plan_id', _plan_id,
    'phase_id', _phase_id,
    'phase_start_date', _phase_start,
    'phase_end_date', _phase_end,
    'initiative_count', _initiative_count,
    'task_count', _task_count,
    'initiatives', _initiative_map
  );
END $function$

CREATE OR REPLACE FUNCTION public.get_accessible_roadmap_story_published_versions(_query text DEFAULT NULL::text, _limit integer DEFAULT 50)
 RETURNS TABLE(version_id uuid, presentation_id uuid, story_pack_id uuid, version_number integer, title text, status text, published_by uuid, published_at timestamp with time zone, source_project_count integer, is_owner boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _user_org uuid;
  _lim integer := COALESCE(_limit, 50);
  _q text := NULLIF(btrim(COALESCE(_query, '')), '');
BEGIN
  IF _uid IS NULL OR NOT public.is_active_user(_uid) THEN
    RAISE EXCEPTION 'unauthorized' USING ERRCODE = '42501';
  END IF;

  IF _lim < 1 THEN _lim := 1; END IF;
  IF _lim > 200 THEN _lim := 200; END IF;

  SELECT organization_id INTO _user_org FROM public.profiles WHERE id = _uid;
  IF _user_org IS NULL THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT * FROM (
    SELECT
      v.id AS version_id,
      v.presentation_id,
      v.story_pack_id,
      v.version_number,
      public.btpm_decrypt(v.title_encrypted, v.organization_id) AS title,
      v.status,
      v.published_by,
      v.published_at,
      (SELECT count(*)::int FROM public.roadmap_story_presentation_version_projects p
        WHERE p.presentation_version_id = v.id) AS source_project_count,
      (v.published_by = _uid) AS is_owner
    FROM public.roadmap_story_presentation_versions v
    JOIN public.roadmap_story_presentations c ON c.id = v.presentation_id
    WHERE v.organization_id = _user_org
      AND v.status = 'active'
      AND c.status = 'active'
      AND public.can_view_roadmap_story_presentation_version(v.id, _uid) = true
  ) t
  WHERE _q IS NULL OR t.title ILIKE ('%' || _q || '%')
  ORDER BY t.published_at DESC
  LIMIT _lim;
END;
$function$

CREATE OR REPLACE FUNCTION public.get_admin_user_detail(_organization_id uuid, _user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE _result jsonb;
BEGIN
  IF NOT public.is_active_user(auth.uid()) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;
  IF NOT public.is_org_admin(auth.uid(), _organization_id) THEN RAISE EXCEPTION 'Access denied'; END IF;
  SELECT jsonb_build_object('user_id', p.id, 'display_name', btpm_decrypt(p.display_name, _organization_id), 'email', p.email, 'avatar_url', btpm_decrypt(p.avatar_url, _organization_id), 'created_at', p.created_at, 'is_active', p.is_active, 'is_org_admin', EXISTS (SELECT 1 FROM public.user_roles ur WHERE ur.user_id = p.id AND ur.organization_id = _organization_id AND ur.role = 'org_admin' AND ur.workspace_id IS NULL), 'workspaces', COALESCE((SELECT jsonb_agg(jsonb_build_object('workspace_id', w.id, 'workspace_name', w.name, 'membership_id', wm.id, 'role', (SELECT ur.role::text FROM public.user_roles ur WHERE ur.user_id = p.id AND ur.workspace_id = w.id AND ur.organization_id = _organization_id ORDER BY CASE ur.role WHEN 'workspace_admin' THEN 1 WHEN 'project_manager' THEN 2 WHEN 'contributor' THEN 3 WHEN 'viewer' THEN 4 ELSE 5 END LIMIT 1)) ORDER BY w.name) FROM public.workspace_memberships wm JOIN public.workspaces w ON w.id = wm.workspace_id AND w.organization_id = _organization_id WHERE wm.user_id = p.id), '[]'::jsonb)) INTO _result FROM public.profiles p WHERE p.id = _user_id AND p.organization_id = _organization_id;
  IF _result IS NULL THEN RAISE EXCEPTION 'User not found in this organization'; END IF;
  RETURN _result;
END;
$function$

CREATE OR REPLACE FUNCTION public.get_ai_feature_settings()
 RETURNS SETOF ai_feature_settings
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _org_id uuid;
  _guide_model uuid;
  _dc_model uuid;
  _rs_model uuid;
BEGIN
  SELECT organization_id INTO _org_id FROM public.profiles WHERE id = auth.uid();
  IF _org_id IS NULL OR NOT public.is_org_admin(auth.uid(), _org_id) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  SELECT id INTO _guide_model FROM public.ai_model_registry WHERE provider='openai' AND recommended_for_guide = true AND active = true ORDER BY sort_order LIMIT 1;
  SELECT id INTO _dc_model    FROM public.ai_model_registry WHERE provider='openai' AND recommended_for_decision_cases = true AND active = true ORDER BY sort_order LIMIT 1;
  SELECT id INTO _rs_model    FROM public.ai_model_registry WHERE provider='openai' AND recommended_for_roadmap_story = true AND active = true ORDER BY sort_order LIMIT 1;
  IF _rs_model IS NULL THEN
    SELECT id INTO _rs_model FROM public.ai_model_registry WHERE provider='openai' AND capability_tier='low_cost' AND active = true ORDER BY sort_order LIMIT 1;
  END IF;
  IF _rs_model IS NULL THEN
    SELECT id INTO _rs_model FROM public.ai_model_registry WHERE provider='openai' AND active = true ORDER BY sort_order LIMIT 1;
  END IF;

  INSERT INTO public.ai_feature_settings (organization_id, feature_key, provider, model_registry_id, enabled, reasoning_effort, require_user_confirmation)
  VALUES (_org_id, 'btpm_guide', 'openai', _guide_model, false, NULL, false)
  ON CONFLICT (organization_id, feature_key) DO NOTHING;

  INSERT INTO public.ai_feature_settings (organization_id, feature_key, provider, model_registry_id, enabled, reasoning_effort, max_files_per_request, max_individual_file_mb, max_total_file_mb, require_user_confirmation)
  VALUES (_org_id, 'decision_cases', 'openai', _dc_model, false, 'high', 5, 10, 25, true)
  ON CONFLICT (organization_id, feature_key) DO NOTHING;

  INSERT INTO public.ai_feature_settings (organization_id, feature_key, provider, model_registry_id, enabled, reasoning_effort, max_files_per_request, max_individual_file_mb, max_total_file_mb, require_user_confirmation)
  VALUES (_org_id, 'roadmap_story', 'openai', _rs_model, false, 'low', 5, 10, 25, true)
  ON CONFLICT (organization_id, feature_key) DO NOTHING;

  RETURN QUERY SELECT * FROM public.ai_feature_settings WHERE organization_id = _org_id ORDER BY feature_key;
END;
$function$

CREATE OR REPLACE FUNCTION public.get_decrypted_knowledge_article(_id uuid)
 RETURNS TABLE(id uuid, organization_id uuid, category_id uuid, title text, slug text, article_type knowledge_article_type, summary text, body text, tooltip_excerpt text, status knowledge_article_status, visibility knowledge_article_visibility, related_route text, related_object_type text, related_object_id uuid, workspace_id uuid, owner_id uuid, version integer, published_at timestamp with time zone, archived_at timestamp with time zone, created_at timestamp with time zone, updated_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_org      uuid := public.get_user_org_id(auth.uid());
  v_is_admin boolean;
  v_row      public.knowledge_articles%ROWTYPE;
BEGIN
  IF v_org IS NULL OR NOT public.is_active_user(auth.uid()) THEN RETURN; END IF;
  SELECT * INTO v_row FROM public.knowledge_articles WHERE knowledge_articles.id = _id;
  IF v_row.id IS NULL OR v_row.organization_id <> v_org THEN RETURN; END IF;

  v_is_admin := public.is_org_admin(auth.uid(), v_org);
  IF NOT v_is_admin THEN
    IF v_row.status <> 'published' THEN RETURN; END IF;
    IF v_row.visibility = 'admin_only' THEN RETURN; END IF;
    IF v_row.visibility = 'workspace_scoped' THEN
      IF v_row.workspace_id IS NULL OR NOT public.is_workspace_member(auth.uid(), v_row.workspace_id) THEN RETURN; END IF;
    END IF;
  END IF;

  RETURN QUERY SELECT
    v_row.id, v_row.organization_id, v_row.category_id,
    public.btpm_decrypt(v_row.title, v_row.organization_id),
    v_row.slug, v_row.article_type,
    public.btpm_decrypt(v_row.summary, v_row.organization_id),
    public.btpm_decrypt(v_row.body, v_row.organization_id),
    public.btpm_decrypt(v_row.tooltip_excerpt, v_row.organization_id),
    v_row.status, v_row.visibility,
    v_row.related_route, v_row.related_object_type, v_row.related_object_id,
    v_row.workspace_id, v_row.owner_id, v_row.version,
    v_row.published_at, v_row.archived_at, v_row.created_at, v_row.updated_at;
END; $function$

CREATE OR REPLACE FUNCTION public.get_decrypted_profile(_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE _result jsonb; _target_id uuid;
BEGIN
  _target_id := COALESCE(_user_id, auth.uid());
  IF _target_id IS NULL THEN RETURN NULL; END IF;
  IF NOT is_active_user(auth.uid()) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;
  SELECT jsonb_build_object('id', p.id, 'email', p.email, 'is_active', p.is_active, 'organization_id', p.organization_id, 'created_at', p.created_at, 'updated_at', p.updated_at, 'display_name', CASE WHEN p.organization_id IS NOT NULL THEN btpm_decrypt(p.display_name, p.organization_id) ELSE p.display_name END, 'avatar_url', CASE WHEN p.organization_id IS NOT NULL THEN btpm_decrypt(p.avatar_url, p.organization_id) ELSE p.avatar_url END) INTO _result FROM profiles p WHERE p.id = _target_id AND (p.id = auth.uid() OR p.organization_id IS NULL OR p.organization_id = get_user_org_id(auth.uid()));
  RETURN _result;
END;
$function$

CREATE OR REPLACE FUNCTION public.get_decrypted_workspace(_workspace_id uuid)
 RETURNS json
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  _uid    uuid := auth.uid();
  _org_id uuid;
  _is_demo boolean;
  _result json;
BEGIN
  IF _uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF NOT public.is_active_user(_uid) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;

  SELECT organization_id, is_demo INTO _org_id, _is_demo
  FROM public.workspaces WHERE id = _workspace_id;
  IF _org_id IS NULL THEN RAISE EXCEPTION 'Workspace not found'; END IF;

  -- Access: explicit member, org admin, OR (demo workspace AND active org member)
  IF NOT (
    public.is_workspace_member(_uid, _workspace_id)
    OR public.is_org_admin(_uid, _org_id)
    OR (_is_demo = true AND _org_id = public.get_user_org_id(_uid))
  ) THEN
    RAISE EXCEPTION 'Not a workspace member';
  END IF;

  SELECT row_to_json(t) INTO _result
  FROM (
    SELECT
      w.id,
      public.btpm_decrypt(w.name, _org_id) AS name,
      w.organization_id,
      w.is_demo,
      w.is_active,
      w.is_archived
    FROM public.workspaces w
    WHERE w.id = _workspace_id
  ) t;

  RETURN _result;
END;
$function$

CREATE OR REPLACE FUNCTION public.get_environment_safety_profile(_organization_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _o public.organizations;
  _is_prod boolean;
  _actor uuid := auth.uid();
BEGIN
  SELECT * INTO _o FROM public.organizations WHERE id = _organization_id;
  IF _o.id IS NULL THEN RAISE EXCEPTION 'Organization % not found', _organization_id; END IF;

  -- Service role bypass: current_setting('role') is unreliable; instead rely on
  -- caller identity. Service-role JWT has no auth.uid(), so if _actor IS NULL
  -- and this is invoked from service_role via RPC, allow.
  IF _actor IS NOT NULL THEN
    IF NOT (
      public.is_platform_super_admin(_actor)
      OR public.is_tenant_admin(_o.tenant_id, _actor)
      OR public.is_organization_member(_o.id, _actor)
    ) THEN
      RAISE EXCEPTION 'Not authorized to read environment safety profile' USING ERRCODE = '42501';
    END IF;
  END IF;

  _is_prod := (_o.environment_role = 'production');
  RETURN jsonb_build_object(
    'tenant_id', _o.tenant_id,
    'organization_id', _o.id,
    'organization_kind', _o.organization_kind,
    'environment_role', _o.environment_role,
    'allow_outbound_email', _is_prod,
    'allow_external_api_writes', _is_prod,
    'allow_real_integrations', _is_prod,
    'allow_exports', true,
    'export_watermark_required', NOT _is_prod,
    'is_production', _is_prod
  );
END $function$

CREATE OR REPLACE FUNCTION public.get_governance_decision_case_project_summary(_record_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE _row public.governance_records%ROWTYPE; _result jsonb;
BEGIN
  SELECT * INTO _row FROM public.governance_records WHERE id = _record_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Record not found' USING ERRCODE='P0002'; END IF;
  IF _row.record_kind IS DISTINCT FROM 'decision_case' THEN
    RAISE EXCEPTION 'Not a decision case' USING ERRCODE='22023';
  END IF;
  PERFORM public._gov_assert_project_read(_row.project_id);

  SELECT jsonb_build_object(
    'project_id', p.id,
    'project_name', public.btpm_decrypt(p.name, p.organization_id),
    'workspace_id', p.workspace_id,
    'workspace_name', public.btpm_decrypt(w.name, w.organization_id),
    'program_id', p.program_id,
    'program_name', CASE WHEN p.program_id IS NULL THEN NULL
                         ELSE (SELECT public.btpm_decrypt(pr.name, pr.organization_id)
                                 FROM public.programs pr WHERE pr.id = p.program_id) END,
    'organization_id', p.organization_id
  ) INTO _result
  FROM public.projects p
  JOIN public.workspaces w ON w.id = p.workspace_id
  WHERE p.id = _row.project_id;

  RETURN _result;
END; $function$

CREATE OR REPLACE FUNCTION public.get_kpi_app_mapping_admin(_mapping_id uuid)
 RETURNS json
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _org uuid;
  _ws  uuid;
  _proj uuid;
  _kdef uuid;
  _is_active boolean;
BEGIN
  IF NOT is_active_user(auth.uid()) THEN
    RAISE EXCEPTION 'Account is deactivated';
  END IF;

  SELECT m.organization_id, m.workspace_id, m.project_id, m.kpi_definition_id, m.is_active
    INTO _org, _ws, _proj, _kdef, _is_active
    FROM public.kpi_app_mappings m
   WHERE m.id = _mapping_id;

  IF _org IS NULL THEN
    RAISE EXCEPTION 'Mapping not found';
  END IF;

  IF NOT (is_org_admin(auth.uid(), _org) OR is_workspace_admin_or_higher(auth.uid(), _ws)) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  RETURN json_build_object(
    'mapping_id', _mapping_id,
    'organization_id', _org,
    'workspace_id', _ws,
    'project_id', _proj,
    'kpi_definition_id', _kdef,
    'is_active', _is_active
  );
END;
$function$

