CREATE OR REPLACE FUNCTION public.get_kpi_snapshot_decrypted_for_mapping(_mapping_id uuid, _snapshot_id uuid)
 RETURNS json
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  _m record;
  _s record;
BEGIN
  IF NOT is_active_user(auth.uid()) THEN
    RAISE EXCEPTION 'Account is deactivated';
  END IF;

  SELECT id, organization_id, workspace_id, project_id, kpi_definition_id, is_active
    INTO _m FROM public.kpi_app_mappings WHERE id = _mapping_id;
  IF _m.id IS NULL THEN
    RAISE EXCEPTION 'Mapping not found';
  END IF;

  IF NOT (is_org_admin(auth.uid(), _m.organization_id)
          OR is_workspace_admin_or_higher(auth.uid(), _m.workspace_id)) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  SELECT id, organization_id, project_id, kpi_definition_id, value_type,
         value_amount, period_start, period_end, string_value, comment, action_plan
    INTO _s FROM public.kpi_snapshots WHERE id = _snapshot_id;
  IF _s.id IS NULL THEN
    RAISE EXCEPTION 'Snapshot not found';
  END IF;

  IF _s.organization_id <> _m.organization_id
     OR _s.project_id <> _m.project_id
     OR _s.kpi_definition_id <> _m.kpi_definition_id THEN
    RAISE EXCEPTION 'Snapshot scope mismatch';
  END IF;

  RETURN json_build_object(
    'id', _s.id,
    'value_type', _s.value_type,
    'value_amount', _s.value_amount,
    'period_start', _s.period_start,
    'period_end', _s.period_end,
    'string_value', btpm_decrypt(_s.string_value, _s.organization_id),
    'comment', btpm_decrypt(_s.comment, _s.organization_id),
    'action_plan', btpm_decrypt(_s.action_plan, _s.organization_id)
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.get_latest_manual_kpi_value(_kpi_definition_id uuid)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _ws_id uuid;
  _org_id uuid;
  _result json;
BEGIN
  SELECT workspace_id, organization_id INTO _ws_id, _org_id
    FROM kpi_definitions WHERE id = _kpi_definition_id;
  IF _ws_id IS NULL THEN RETURN NULL; END IF;

  IF NOT (is_workspace_member(auth.uid(), _ws_id) OR is_org_admin(auth.uid(), _org_id)) THEN
    RETURN NULL;
  END IF;

  SELECT row_to_json(t) INTO _result
  FROM (
    SELECT
      ku.id, ku.value, ku.update_date, ku.created_at,
      CASE WHEN ku.note IS NOT NULL
           THEN btpm_decrypt(ku.note, ku.organization_id)
           ELSE NULL END AS note
    FROM kpi_updates ku
    WHERE ku.kpi_definition_id = _kpi_definition_id
    ORDER BY ku.update_date DESC, ku.created_at DESC
    LIMIT 1
  ) t;

  RETURN _result;
END;
$function$

CREATE OR REPLACE FUNCTION public.get_latest_roadmap_story_pack_version_content(_story_pack_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _pack public.roadmap_story_packs;
  _v public.roadmap_story_pack_versions;
  _result jsonb;
BEGIN
  IF _uid IS NULL OR NOT public.is_active_user(_uid) THEN
    RAISE EXCEPTION 'unauthorized' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO _pack FROM public.roadmap_story_packs WHERE id = _story_pack_id;
  IF NOT FOUND OR _pack.created_by <> _uid THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO _v
  FROM public.roadmap_story_pack_versions
  WHERE story_pack_id = _story_pack_id
  ORDER BY version_number DESC
  LIMIT 1;
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  SELECT jsonb_build_object(
    'id', _v.id,
    'version_number', _v.version_number,
    'status', _v.status,
    'created_at', _v.created_at,
    'created_by', _v.created_by,
    'source_manifest', _v.source_manifest,
    'model_metadata', _v.model_metadata,
    'story_json', CASE WHEN _v.story_json_encrypted IS NULL THEN NULL
                       ELSE public.btpm_decrypt(_v.story_json_encrypted, _pack.organization_id) END
  ) INTO _result;

  RETURN _result;
END;
$function$

