CREATE OR REPLACE FUNCTION public.get_my_active_context()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _pref RECORD;
  _tenant_count int := 0;
  _org_count int := 0;
  _ws_count int := 0;
  _tenant_id uuid;
  _tenant_row RECORD;
  _org_id uuid;
  _org_row RECORD;
  _ws_id uuid;
  _ws_name text;
  _requires_tenant boolean := false;
  _requires_org boolean := false;
  _is_all_ws boolean := false;
BEGIN
  IF _uid IS NULL THEN
    RETURN jsonb_build_object('authenticated', false);
  END IF;

  SELECT * INTO _pref FROM public.user_active_context_preferences WHERE user_id = _uid;
  SELECT count(*) INTO _tenant_count FROM public.list_my_tenants();

  IF _tenant_count = 0 THEN
    RETURN jsonb_build_object('authenticated', true, 'has_access', false,
      'available_tenant_count', 0, 'available_organization_count', 0, 'available_workspace_count', 0);
  END IF;

  IF _pref.last_active_tenant_id IS NOT NULL
     AND EXISTS (SELECT 1 FROM public.list_my_tenants() t WHERE t.tenant_id = _pref.last_active_tenant_id) THEN
    _tenant_id := _pref.last_active_tenant_id;
  ELSIF _tenant_count = 1 THEN
    SELECT t.tenant_id INTO _tenant_id FROM public.list_my_tenants() t LIMIT 1;
  ELSE
    SELECT t.tenant_id INTO _tenant_id
      FROM public.list_my_tenants() t
      INNER JOIN public.tenants tt ON tt.id = t.tenant_id
      WHERE tt.slug = 'adalvo' LIMIT 1;
    IF _tenant_id IS NULL THEN _requires_tenant := true; END IF;
  END IF;

  IF _requires_tenant OR _tenant_id IS NULL THEN
    RETURN jsonb_build_object('authenticated', true, 'has_access', true,
      'requires_tenant_selection', true, 'available_tenant_count', _tenant_count);
  END IF;

  SELECT id, name, slug INTO _tenant_row FROM public.tenants WHERE id = _tenant_id AND status = 'active';
  IF _tenant_row.id IS NULL THEN
    RETURN jsonb_build_object('authenticated', true, 'has_access', true,
      'requires_tenant_selection', true, 'available_tenant_count', _tenant_count);
  END IF;

  SELECT count(*) INTO _org_count FROM public.list_my_organizations_for_tenant(_tenant_id);
  IF _org_count = 0 THEN
    RETURN jsonb_build_object('authenticated', true, 'has_access', false,
      'tenant_id', _tenant_row.id, 'tenant_name', _tenant_row.name, 'tenant_slug', _tenant_row.slug,
      'available_tenant_count', _tenant_count, 'available_organization_count', 0);
  END IF;

  IF _pref.last_active_organization_id IS NOT NULL
     AND EXISTS (SELECT 1 FROM public.list_my_organizations_for_tenant(_tenant_id) o
                 WHERE o.organization_id = _pref.last_active_organization_id) THEN
    _org_id := _pref.last_active_organization_id;
  ELSE
    SELECT tt.default_organization_id INTO _org_id FROM public.tenants tt WHERE tt.id = _tenant_id;
    IF _org_id IS NOT NULL AND NOT EXISTS (
      SELECT 1 FROM public.list_my_organizations_for_tenant(_tenant_id) o WHERE o.organization_id = _org_id
    ) THEN
      _org_id := NULL;
    END IF;
    IF _org_id IS NULL AND _org_count = 1 THEN
      SELECT o.organization_id INTO _org_id FROM public.list_my_organizations_for_tenant(_tenant_id) o LIMIT 1;
    END IF;
    IF _org_id IS NULL THEN _requires_org := true; END IF;
  END IF;

  IF _requires_org OR _org_id IS NULL THEN
    RETURN jsonb_build_object('authenticated', true, 'has_access', true,
      'requires_organization_selection', true,
      'tenant_id', _tenant_row.id, 'tenant_name', _tenant_row.name, 'tenant_slug', _tenant_row.slug,
      'available_tenant_count', _tenant_count, 'available_organization_count', _org_count);
  END IF;

  SELECT o.id, o.name, o.slug, o.organization_kind, o.environment_role
    INTO _org_row FROM public.organizations o WHERE o.id = _org_id;

  SELECT count(*) INTO _ws_count FROM public.list_my_workspaces_for_organization(_org_id);

  _is_all_ws := COALESCE(_pref.is_all_workspaces, false);
  IF _pref.last_active_workspace_id IS NOT NULL
     AND EXISTS (SELECT 1 FROM public.list_my_workspaces_for_organization(_org_id) w
                 WHERE w.workspace_id = _pref.last_active_workspace_id) THEN
    _ws_id := _pref.last_active_workspace_id;
    _is_all_ws := false;
  ELSIF _is_all_ws THEN
    _ws_id := NULL;
  ELSIF _ws_count = 1 THEN
    SELECT w.workspace_id INTO _ws_id FROM public.list_my_workspaces_for_organization(_org_id) w LIMIT 1;
  ELSIF _ws_count > 1 THEN
    _is_all_ws := true; _ws_id := NULL;
  END IF;

  IF _ws_id IS NOT NULL THEN
    SELECT w.name INTO _ws_name FROM public.workspaces w WHERE w.id = _ws_id;
  END IF;

  -- Persist resolved active context so list_user_workspaces (and any other
  -- caller that reads user_active_context_preferences) agrees with the chip.
  INSERT INTO public.user_active_context_preferences AS p
    (user_id, last_active_tenant_id, last_active_organization_id,
     last_active_workspace_id, is_all_workspaces, updated_at)
  VALUES (_uid, _tenant_row.id, _org_row.id, _ws_id, _is_all_ws, now())
  ON CONFLICT (user_id) DO UPDATE
    SET last_active_tenant_id = EXCLUDED.last_active_tenant_id,
        last_active_organization_id = EXCLUDED.last_active_organization_id,
        last_active_workspace_id = COALESCE(EXCLUDED.last_active_workspace_id, p.last_active_workspace_id),
        is_all_workspaces = EXCLUDED.is_all_workspaces,
        updated_at = now();

  RETURN jsonb_build_object(
    'authenticated', true, 'has_access', true,
    'requires_tenant_selection', false, 'requires_organization_selection', false,
    'tenant_id', _tenant_row.id, 'tenant_name', _tenant_row.name, 'tenant_slug', _tenant_row.slug,
    'organization_id', _org_row.id, 'organization_name', _org_row.name, 'organization_slug', _org_row.slug,
    'organization_kind', _org_row.organization_kind, 'environment_role', _org_row.environment_role,
    'workspace_id', _ws_id, 'workspace_name', _ws_name, 'is_all_workspaces', _is_all_ws,
    'available_tenant_count', _tenant_count, 'available_organization_count', _org_count,
    'available_workspace_count', _ws_count);
END;
$function$

CREATE OR REPLACE FUNCTION public.get_my_admin_access_summary()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _is_super boolean := false;
  _tenants jsonb := '[]'::jsonb;
BEGIN
  IF _uid IS NULL THEN
    RETURN jsonb_build_object(
      'is_platform_super_admin', false,
      'tenant_admin_memberships', '[]'::jsonb
    );
  END IF;

  _is_super := public.is_platform_super_admin(_uid);

  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'tenant_id', tm.tenant_id,
      'tenant_name', t.name,
      'tenant_slug', t.slug,
      'tenant_status', t.status,
      'role', tm.role
    ) ORDER BY t.name
  ), '[]'::jsonb) INTO _tenants
  FROM public.tenant_memberships tm
  JOIN public.tenants t ON t.id = tm.tenant_id
  WHERE tm.user_id = _uid
    AND tm.status = 'active'
    AND tm.role IN ('tenant_owner','tenant_admin');

  RETURN jsonb_build_object(
    'is_platform_super_admin', _is_super,
    'tenant_admin_memberships', _tenants
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.get_org_user_display_name(_user_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_name text;
  v_email text;
  v_org uuid;
  v_caller_org uuid;
BEGIN
  IF _user_id IS NULL THEN RETURN NULL; END IF;
  IF NOT public.is_active_user(auth.uid()) THEN RETURN NULL; END IF;

  SELECT p.organization_id INTO v_caller_org FROM public.profiles p WHERE p.id = auth.uid();

  SELECT p.organization_id,
         CASE WHEN p.organization_id IS NOT NULL AND p.display_name IS NOT NULL
              THEN btpm_decrypt(p.display_name, p.organization_id) ELSE p.display_name END,
         CASE WHEN p.organization_id IS NOT NULL AND p.email IS NOT NULL
              THEN btpm_decrypt(p.email, p.organization_id) ELSE p.email END
    INTO v_org, v_name, v_email
  FROM public.profiles p WHERE p.id = _user_id;

  IF v_caller_org IS NULL OR v_org IS NULL OR v_caller_org <> v_org THEN
    RETURN NULL;
  END IF;

  RETURN COALESCE(NULLIF(v_name, ''), NULLIF(v_email, ''));
END;
$function$

CREATE OR REPLACE FUNCTION public.get_portfolio_item_project_membership_summary(_portfolio_item_id uuid, _include_archived_projects boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _org uuid;
  _result jsonb;
BEGIN
  IF _uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF NOT public.is_active_user(_uid) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;

  SELECT organization_id INTO _org FROM public.portfolio_items WHERE id = _portfolio_item_id;
  IF _org IS NULL THEN RAISE EXCEPTION 'Portfolio item not found'; END IF;

  IF NOT public.is_org_admin(_uid, _org) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  SELECT COALESCE(jsonb_agg(row_to_json(t) ORDER BY t.project_name), '[]'::jsonb)
    INTO _result
  FROM (
    SELECT
      p.id AS project_id,
      public.btpm_decrypt(p.name, p.organization_id) AS project_name,
      p.workspace_id,
      w.name AS workspace_name,
      p.program_id,
      (SELECT public.btpm_decrypt(pr.name, p.organization_id)
         FROM public.programs pr WHERE pr.id = p.program_id) AS program_name,
      p.status,
      p.priority,
      p.project_stage,
      p.delivery_model,
      p.start_date,
      p.target_end_date,
      p.is_archived,
      p.updated_at
    FROM public.projects p
    JOIN public.workspaces w ON w.id = p.workspace_id
    WHERE p.portfolio_item_id = _portfolio_item_id
      AND (_include_archived_projects OR p.is_archived = false)
  ) t;

  RETURN _result;
END;
$function$

CREATE OR REPLACE FUNCTION public.get_powerbi_effective_scope(_organization_id uuid)
 RETURNS TABLE(scope_configured boolean, included_workspace_ids uuid[], included_project_ids uuid[])
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_proj uuid[];
  v_ws uuid[];
  v_configured boolean;
BEGIN
  IF v_uid IS NULL OR NOT public.is_org_admin(v_uid, _organization_id) THEN
    RAISE EXCEPTION 'Org Admin only';
  END IF;

  SELECT EXISTS(
    SELECT 1 FROM public.powerbi_data_scope_rules
    WHERE organization_id = _organization_id
  ) INTO v_configured;

  SELECT COALESCE(array_agg(DISTINCT w.id), ARRAY[]::uuid[]) INTO v_ws
  FROM public.workspaces w
  JOIN public.powerbi_data_scope_rules wr
    ON wr.scope_type = 'workspace'
   AND wr.organization_id = w.organization_id
   AND wr.workspace_id = w.id
   AND wr.scope_mode = 'included'
  WHERE w.organization_id = _organization_id;

  SELECT COALESCE(array_agg(p.id), ARRAY[]::uuid[]) INTO v_proj
  FROM public.projects p
  WHERE p.organization_id = _organization_id
    AND p.workspace_id = ANY(v_ws);

  RETURN QUERY SELECT v_configured, v_ws, v_proj;
END;
$function$

CREATE OR REPLACE FUNCTION public.get_project_governance_summary(_project_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  _p record;
  _result jsonb;
  _active_cnt int := 0;
  _archived_cnt int := 0;
  _overdue_cnt int := 0;
  _due_soon_cnt int := 0;
  _ad_hoc_cnt int := 0;
  _last_date date;
  _last_rec uuid;
  _next_date date;
  _next_cad uuid;
  _total_rec int := 0;
  _rec_30 int := 0;
  _rec_90 int := 0;
  _missing_sp int := 0;
BEGIN
  _p := _gov_assert_project_read(_project_id);

  SELECT
    COUNT(*) FILTER (WHERE archived_at IS NULL),
    COUNT(*) FILTER (WHERE archived_at IS NOT NULL),
    COUNT(*) FILTER (WHERE archived_at IS NULL AND frequency_type <> 'ad_hoc'
                       AND next_expected_date IS NOT NULL
                       AND next_expected_date < CURRENT_DATE),
    COUNT(*) FILTER (WHERE archived_at IS NULL AND frequency_type <> 'ad_hoc'
                       AND next_expected_date IS NOT NULL
                       AND next_expected_date >= CURRENT_DATE
                       AND next_expected_date <= CURRENT_DATE + INTERVAL '7 days'),
    COUNT(*) FILTER (WHERE archived_at IS NULL AND frequency_type = 'ad_hoc')
  INTO _active_cnt, _archived_cnt, _overdue_cnt, _due_soon_cnt, _ad_hoc_cnt
  FROM governance_cadences WHERE project_id = _project_id;

  SELECT actual_date_held, id INTO _last_date, _last_rec
  FROM governance_records
  WHERE project_id = _project_id AND archived_at IS NULL
  ORDER BY actual_date_held DESC, created_at DESC
  LIMIT 1;

  SELECT next_expected_date, id INTO _next_date, _next_cad
  FROM governance_cadences
  WHERE project_id = _project_id AND archived_at IS NULL
    AND frequency_type <> 'ad_hoc'
    AND next_expected_date IS NOT NULL
  ORDER BY next_expected_date ASC
  LIMIT 1;

  SELECT
    COUNT(*),
    COUNT(*) FILTER (WHERE actual_date_held >= CURRENT_DATE - INTERVAL '30 days'),
    COUNT(*) FILTER (WHERE actual_date_held >= CURRENT_DATE - INTERVAL '90 days'),
    COUNT(*) FILTER (WHERE sharepoint_evidence_reference IS NULL)
  INTO _total_rec, _rec_30, _rec_90, _missing_sp
  FROM governance_records
  WHERE project_id = _project_id AND archived_at IS NULL;

  _result := jsonb_build_object(
    'project_id', _project_id,
    'active_cadence_count', _active_cnt,
    'archived_cadence_count', _archived_cnt,
    'overdue_cadence_count', _overdue_cnt,
    'due_soon_cadence_count', _due_soon_cnt,
    'ad_hoc_cadence_count', _ad_hoc_cnt,
    'last_completed_governance_date', _last_date,
    'last_completed_record_id', _last_rec,
    'next_expected_governance_date', _next_date,
    'next_expected_cadence_id', _next_cad,
    'total_record_count', _total_rec,
    'records_last_30_days', _rec_30,
    'records_last_90_days', _rec_90,
    'records_missing_sharepoint_evidence_count', _missing_sp
  );
  RETURN _result;
END; $function$

CREATE OR REPLACE FUNCTION public.get_project_template_detail(_template_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _caller uuid := auth.uid();
  r RECORD;
  _bp jsonb;
  _summary jsonb;
  _proj jsonb;
BEGIN
  IF _caller IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;

  SELECT id, organization_id, workspace_id, source_project_id,
         name, description, blueprint_payload, blueprint_version,
         is_archived, created_at, updated_at, created_by, updated_by
    INTO r
    FROM public.project_templates
   WHERE id = _template_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'template not found';
  END IF;

  IF NOT (public.is_workspace_member(_caller, r.workspace_id) OR public.is_org_admin(_caller, r.organization_id)) THEN
    RAISE EXCEPTION 'access denied' USING ERRCODE = '42501';
  END IF;

  BEGIN
    _bp := public.btpm_decrypt(r.blueprint_payload, r.organization_id)::jsonb;
  EXCEPTION WHEN OTHERS THEN
    _bp := '{}'::jsonb;
  END;

  _summary := public._template_blueprint_summary(_bp);
  _proj := COALESCE(_bp->'project', '{}'::jsonb);

  RETURN jsonb_build_object(
    'template_id', r.id,
    'organization_id', r.organization_id,
    'workspace_id', r.workspace_id,
    'source_project_id', r.source_project_id,
    'name', public.btpm_decrypt(r.name, r.organization_id),
    'description', CASE WHEN r.description IS NULL THEN NULL ELSE public.btpm_decrypt(r.description, r.organization_id) END,
    'blueprint_version', r.blueprint_version,
    'is_archived', r.is_archived,
    'created_at', r.created_at,
    'updated_at', r.updated_at,
    'created_by', r.created_by,
    'updated_by', r.updated_by,
    'schedule_mode', _summary->>'schedule_mode',
    'anchor_source', _summary->>'anchor_source',
    'agile_enabled', (_summary->>'agile_enabled')::boolean,
    'summary_counts', _summary->'summary_counts',
    'project_summary', jsonb_build_object(
      'name',          _proj->>'name',
      'description',   _proj->>'description',
      'charter',       _proj->>'charter',
      'goals',         _proj->>'goals',
      'scope_in',      _proj->>'scope_in',
      'scope_out',     _proj->>'scope_out',
      'priority',      _proj->>'priority',
      'agile_enabled', COALESCE((_proj->>'agile_enabled')::boolean, false)
    )
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.get_roadmap_story_pack_ai_run_status(_run_id uuid)
