$function$

CREATE OR REPLACE FUNCTION public.get_roadmap_story_pack_version_debug(_version_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _v public.roadmap_story_pack_versions;
  _pack public.roadmap_story_packs;
  _run public.roadmap_story_ai_runs;
  _org uuid;
  _files jsonb;
  _result jsonb;
BEGIN
  IF _uid IS NULL OR NOT public.is_active_user(_uid) THEN
    RAISE EXCEPTION 'unauthorized' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO _v FROM public.roadmap_story_pack_versions WHERE id = _version_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO _pack FROM public.roadmap_story_packs WHERE id = _v.story_pack_id;
  IF NOT FOUND OR _pack.created_by <> _uid THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  _org := _pack.organization_id;

  SELECT * INTO _run
  FROM public.roadmap_story_ai_runs
  WHERE story_pack_version_id = _version_id
  ORDER BY started_at DESC
  LIMIT 1;

  IF _run.id IS NOT NULL THEN
    SELECT COALESCE(jsonb_agg(to_jsonb(rf) ORDER BY rf.created_at ASC), '[]'::jsonb)
    INTO _files
    FROM public.roadmap_story_ai_run_files rf
    WHERE rf.ai_run_id = _run.id;
  ELSE
    _files := '[]'::jsonb;
  END IF;

  _result := jsonb_build_object(
    'version', jsonb_build_object(
      'id', _v.id,
      'story_pack_id', _v.story_pack_id,
      'version_number', _v.version_number,
      'status', _v.status,
      'created_at', _v.created_at,
      'created_by', _v.created_by,
      'source_manifest', _v.source_manifest,
      'model_metadata', _v.model_metadata,
      'story_json', CASE WHEN _v.story_json_encrypted IS NULL THEN NULL
                         ELSE public.btpm_decrypt(_v.story_json_encrypted, _org) END,
      'source_snapshot', CASE WHEN _v.source_snapshot_encrypted IS NULL THEN NULL
                              ELSE public.btpm_decrypt(_v.source_snapshot_encrypted, _org) END
    ),
    'ai_run', CASE WHEN _run.id IS NULL THEN NULL ELSE jsonb_build_object(
      'id', _run.id,
      'status', _run.status,
      'provider', _run.provider,
      'model', _run.model,
      'reasoning_effort', _run.reasoning_effort,
      'feature_key', _run.feature_key,
      'input_manifest', _run.input_manifest,
      'started_at', _run.started_at,
      'completed_at', _run.completed_at,
      'prompt_tokens', _run.prompt_tokens,
      'completion_tokens', _run.completion_tokens,
      'total_tokens', _run.total_tokens,
      'openai_response_id', _run.openai_response_id,
      'files_selected_count', _run.files_selected_count,
      'files_sent_count', _run.files_sent_count,
      'files_skipped_count', _run.files_skipped_count,
      'total_bytes_sent', _run.total_bytes_sent,
      'prompt_text', CASE WHEN _run.prompt_summary_encrypted IS NULL THEN NULL
                          ELSE public.btpm_decrypt(_run.prompt_summary_encrypted, _org) END,
      'raw_response', CASE WHEN _run.output_text_encrypted IS NULL THEN NULL
                           ELSE public.btpm_decrypt(_run.output_text_encrypted, _org) END
    ) END,
    'files', _files
  );

  RETURN _result;
END;
$function$

