CREATE OR REPLACE FUNCTION public.get_roadmap_story_presentation_version_for_view(_version_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _v public.roadmap_story_presentation_versions;
  _title text;
  _snapshot jsonb;
  _limitations jsonb;
BEGIN
  IF _uid IS NULL OR NOT public.is_active_user(_uid) THEN
    RAISE EXCEPTION 'unauthorized' USING ERRCODE = '42501';
  END IF;

  IF NOT public.can_view_roadmap_story_presentation_version(_version_id, _uid) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO _v FROM public.roadmap_story_presentation_versions WHERE id = _version_id;

  _title := public.btpm_decrypt(_v.title_encrypted, _v.organization_id);

  BEGIN
    _snapshot := public.btpm_decrypt(_v.snapshot_encrypted, _v.organization_id)::jsonb;
  EXCEPTION WHEN others THEN
    _snapshot := '{}'::jsonb;
  END;

  IF _v.source_limitations_encrypted IS NOT NULL THEN
    BEGIN
      _limitations := public.btpm_decrypt(_v.source_limitations_encrypted, _v.organization_id)::jsonb;
    EXCEPTION WHEN others THEN
      _limitations := NULL;
    END;
  END IF;

  RETURN jsonb_build_object(
    'version_id', _v.id,
    'presentation_id', _v.presentation_id,
    'story_pack_id', _v.story_pack_id,
    'version_number', _v.version_number,
    'title', _title,
    'snapshot', _snapshot,
    'source_limitations', _limitations,
    'published_by', _v.published_by,
    'published_at', _v.published_at,
    'status', _v.status
  );
END;
$function$

