CREATE OR REPLACE FUNCTION public.hard_delete_phase(_id uuid)
 RETURNS TABLE(storage_path text, bucket text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _row phases%ROWTYPE;
BEGIN
  SELECT * INTO _row FROM phases WHERE id = _id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Phase not found'; END IF;
  PERFORM _assert_admin(_row.workspace_id, _row.organization_id);
  IF NOT _row.is_archived THEN RAISE EXCEPTION 'Phase must be archived before hard delete'; END IF;
  PERFORM set_config('app.allow_lifecycle_bypass', 'on', true);
  PERFORM log_activity_event(_row.organization_id, auth.uid(), 'lifecycle.hard_delete', 'phase', _id, '{}'::jsonb, _row.workspace_id);
  DELETE FROM raci_assignments WHERE target_type IN ('phase','task') AND target_id IN (SELECT _id UNION ALL SELECT id FROM tasks WHERE phase_id=_id);
  DELETE FROM dependencies WHERE workspace_id = _row.workspace_id AND (
    (source_type IN ('phase','task') AND source_id IN (SELECT _id UNION ALL SELECT id FROM tasks WHERE phase_id=_id))
    OR (target_type IN ('phase','task') AND target_id IN (SELECT _id UNION ALL SELECT id FROM tasks WHERE phase_id=_id))
  );
  DELETE FROM task_assignments WHERE task_id IN (SELECT id FROM tasks WHERE phase_id=_id);
  DELETE FROM kpi_updates WHERE kpi_definition_id IN (SELECT id FROM kpi_definitions WHERE target_type IN ('phase','task') AND target_id IN (SELECT _id UNION ALL SELECT id FROM tasks WHERE phase_id=_id));
  DELETE FROM kpi_definitions WHERE target_type IN ('phase','task') AND target_id IN (SELECT _id UNION ALL SELECT id FROM tasks WHERE phase_id=_id);
  DELETE FROM blockers WHERE target_type IN ('phase','task') AND target_id IN (SELECT _id UNION ALL SELECT id FROM tasks WHERE phase_id=_id);
  DELETE FROM risks WHERE target_type IN ('phase','task') AND target_id IN (SELECT _id UNION ALL SELECT id FROM tasks WHERE phase_id=_id);
  DELETE FROM comments WHERE target_type IN ('phase','task') AND target_id IN (SELECT _id UNION ALL SELECT id FROM tasks WHERE phase_id=_id);
  DELETE FROM execution_updates WHERE target_type IN ('phase','task') AND target_id IN (SELECT _id UNION ALL SELECT id FROM tasks WHERE phase_id=_id);
  DELETE FROM tasks WHERE phase_id=_id;
  DELETE FROM phases WHERE id=_id;
  RETURN;
END;
$function$

