CREATE OR REPLACE FUNCTION public.hard_delete_project(_id uuid)
 RETURNS TABLE(storage_path text, bucket text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _row projects%ROWTYPE;
BEGIN
  SELECT * INTO _row FROM projects WHERE id=_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Project not found'; END IF;
  PERFORM _assert_admin(_row.workspace_id, _row.organization_id);
  IF NOT _row.is_archived THEN RAISE EXCEPTION 'Project must be archived before hard delete'; END IF;
