  PERFORM log_activity_event(_row.organization_id, auth.uid(), 'lifecycle.hard_delete', 'project', _id, '{}'::jsonb, _row.workspace_id);
  UPDATE project_templates SET source_project_id = NULL WHERE source_project_id=_id;
  DELETE FROM raci_assignments WHERE workspace_id=_row.workspace_id AND target_type IN ('project','phase','task') AND target_id IN (
    SELECT _id UNION ALL SELECT id FROM phases WHERE project_id=_id UNION ALL SELECT id FROM tasks WHERE project_id=_id
  );
  DELETE FROM dependencies WHERE workspace_id=_row.workspace_id;
  DELETE FROM task_assignments WHERE task_id IN (SELECT id FROM tasks WHERE project_id=_id);
  DELETE FROM kpi_updates WHERE kpi_definition_id IN (SELECT id FROM kpi_definitions WHERE target_type IN ('project','phase','task') AND target_id IN (
    SELECT _id UNION ALL SELECT id FROM phases WHERE project_id=_id UNION ALL SELECT id FROM tasks WHERE project_id=_id
  ));
  DELETE FROM kpi_definitions WHERE target_type IN ('project','phase','task') AND target_id IN (
    SELECT _id UNION ALL SELECT id FROM phases WHERE project_id=_id UNION ALL SELECT id FROM tasks WHERE project_id=_id
  );
  DELETE FROM blockers WHERE target_type IN ('project','phase','task') AND target_id IN (
    SELECT _id UNION ALL SELECT id FROM phases WHERE project_id=_id UNION ALL SELECT id FROM tasks WHERE project_id=_id
  );
  DELETE FROM risks WHERE target_type IN ('project','phase','task') AND target_id IN (
    SELECT _id UNION ALL SELECT id FROM phases WHERE project_id=_id UNION ALL SELECT id FROM tasks WHERE project_id=_id
  );
  DELETE FROM comments WHERE target_type IN ('project','phase','task') AND target_id IN (
    SELECT _id UNION ALL SELECT id FROM phases WHERE project_id=_id UNION ALL SELECT id FROM tasks WHERE project_id=_id
  );
  DELETE FROM execution_updates WHERE target_type IN ('project','phase','task') AND target_id IN (
    SELECT _id UNION ALL SELECT id FROM phases WHERE project_id=_id UNION ALL SELECT id FROM tasks WHERE project_id=_id
  );
  DELETE FROM tasks WHERE project_id=_id;
  DELETE FROM backlog_items WHERE project_id=_id;
  DELETE FROM sprints WHERE project_id=_id;
  DELETE FROM board_workflow_states WHERE project_id=_id;
  DELETE FROM project_team_members WHERE project_id=_id;
  DELETE FROM phases WHERE project_id=_id;
  DELETE FROM projects WHERE id=_id;
  RETURN;
END;
$function$

