  IF NOT _row.is_archived THEN RAISE EXCEPTION 'Task must be archived before hard delete'; END IF;
  PERFORM set_config('app.allow_lifecycle_bypass', 'on', true);
  PERFORM log_activity_event(_row.organization_id, auth.uid(), 'lifecycle.hard_delete', 'task', _id, '{}'::jsonb, _row.workspace_id);
  DELETE FROM raci_assignments WHERE target_type='task' AND target_id=_id;
  DELETE FROM dependencies WHERE workspace_id=_row.workspace_id AND ((source_type='task' AND source_id=_id) OR (target_type='task' AND target_id=_id));
  DELETE FROM task_assignments WHERE task_id=_id;
  DELETE FROM kpi_updates WHERE kpi_definition_id IN (SELECT id FROM kpi_definitions WHERE target_type='task' AND target_id=_id);
  DELETE FROM kpi_definitions WHERE target_type='task' AND target_id=_id;
  DELETE FROM blockers WHERE target_type='task' AND target_id=_id;
  DELETE FROM risks WHERE target_type='task' AND target_id=_id;
  DELETE FROM comments WHERE target_type='task' AND target_id=_id;
  DELETE FROM execution_updates WHERE target_type='task' AND target_id=_id;
  DELETE FROM tasks WHERE id=_id;
  RETURN;
END;
$function$

CREATE OR REPLACE FUNCTION public.instantiate_project_from_template(_template_id uuid, _new_project_name text, _program_id uuid DEFAULT NULL::uuid, _project_start_date date DEFAULT NULL::date, _confirm_widening boolean DEFAULT false, _delivery_model project_delivery_model DEFAULT NULL::project_delivery_model)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _caller uuid := auth.uid();
  _tpl RECORD;
  _org uuid; _ws uuid; _src_project uuid;
  _payload_text text;
  _bp jsonb;
  _bp_kind text;
  _schedule_mode text;
  _schedule_mode_applied text;
  _proj_obj jsonb;
  _new_project_id uuid;
  _phase jsonb; _task jsonb; _dep jsonb; _kpi jsonb;
  _state jsonb; _sprint jsonb; _backlog jsonb;
  _new_id uuid;
  _phase_map jsonb := '{}'::jsonb;
  _task_map jsonb := '{}'::jsonb;
  _kpi_map jsonb := '{}'::jsonb;
  _state_map jsonb := '{}'::jsonb;
  _sprint_map jsonb := '{}'::jsonb;
  _backlog_map jsonb := '{}'::jsonb;
  _agile_enabled boolean;
  _src_id uuid; _tgt_id uuid;
  _dep_entity text;
  _phase_count int := 0; _task_count int := 0; _dep_count int := 0;
  _kpi_count int := 0; _state_count int := 0;
  _sprint_count int := 0; _backlog_count int := 0;
  _start_off int; _end_off int; _due_off int;
  _proj_start date; _proj_end date;
  _ph_start date; _ph_end date;
  _t_start date; _t_due date;
  _sp_start date; _sp_end date;
  _eff jsonb;
  _did_widen boolean := false;
BEGIN
  IF _caller IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF _new_project_name IS NULL OR length(btrim(_new_project_name)) = 0 THEN
    RAISE EXCEPTION 'New project name is required';
  END IF;

  SELECT id, organization_id, workspace_id, source_project_id,
         blueprint_payload, blueprint_version, is_archived
    INTO _tpl FROM public.project_templates WHERE id = _template_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Template not found'; END IF;
  IF _tpl.is_archived THEN RAISE EXCEPTION 'Template is archived'; END IF;

  _org := _tpl.organization_id;
  _ws  := _tpl.workspace_id;
  _src_project := _tpl.source_project_id;

  IF NOT public.has_pm_authority(_caller, _ws) THEN
    RAISE EXCEPTION 'PM authority required in template workspace';
  END IF;
  IF _tpl.blueprint_version <> 'clone_blueprint_v1' THEN
    RAISE EXCEPTION 'Unsupported blueprint version: %', _tpl.blueprint_version;
  END IF;

  IF _program_id IS NOT NULL THEN
    PERFORM 1 FROM public.programs
      WHERE id = _program_id AND organization_id = _org
        AND workspace_id = _ws AND is_archived = false;
    IF NOT FOUND THEN RAISE EXCEPTION 'Program not found in template workspace/organization'; END IF;
  END IF;

  _payload_text := public.btpm_decrypt(_tpl.blueprint_payload, _org);
  IF _payload_text IS NULL OR length(_payload_text) = 0 THEN
    RAISE EXCEPTION 'Stored blueprint is empty or undecryptable';
  END IF;
  _bp := _payload_text::jsonb;

  IF (_bp->>'version') <> 'clone_blueprint_v1' THEN
    RAISE EXCEPTION 'Stored blueprint has unsupported version: %', _bp->>'version';
  END IF;
  _bp_kind := _bp->>'blueprint_kind';
  IF _bp_kind <> 'project' THEN
    RAISE EXCEPTION 'Stored blueprint is not a project blueprint (kind=%)', _bp_kind;
  END IF;

  _schedule_mode := COALESCE(_bp->>'schedule_mode', 'unscheduled');

  IF _project_start_date IS NULL THEN
    _schedule_mode_applied := 'unscheduled';
  ELSIF _schedule_mode = 'relative' THEN
    _schedule_mode_applied := 'relative_reanchored';
  ELSIF _schedule_mode = 'unscheduled' THEN
    _schedule_mode_applied := 'unscheduled';
  ELSE
    RAISE EXCEPTION 'Unsupported blueprint schedule_mode: %', _schedule_mode;
  END IF;

  _proj_obj := COALESCE(_bp->'project', '{}'::jsonb);
  _agile_enabled := COALESCE((_proj_obj->>'agile_enabled')::boolean, false);

  IF _schedule_mode_applied = 'relative_reanchored' THEN
    _eff := public._compute_project_effective_window(_bp, _project_start_date);
    IF (_eff->>'requires_widening')::boolean AND NOT _confirm_widening THEN
      RAISE EXCEPTION 'BTPM_REQUIRES_WIDENING:%',
        (_eff || jsonb_build_object('scope','project_template_instantiation'))::text
        USING ERRCODE = 'check_violation';
    END IF;

    _proj_start := NULLIF(_eff->>'effective_start','')::date;
    _proj_end   := NULLIF(_eff->>'effective_end','')::date;
    _did_widen  := (_eff->>'requires_widening')::boolean;
  ELSE
    _proj_start := NULL;
    _proj_end   := NULL;
  END IF;

  INSERT INTO public.projects (
    organization_id, workspace_id, program_id, name,
    description, charter, goals, scope_in, scope_out,
    priority, agile_enabled,
    status, is_archived, is_baselined,
    start_date, target_end_date, created_by,
    delivery_model
  ) VALUES (
    _org, _ws, _program_id, _new_project_name,
    NULLIF(_proj_obj->>'description',''),
    NULLIF(_proj_obj->>'charter',''),
    NULLIF(_proj_obj->>'goals',''),
    NULLIF(_proj_obj->>'scope_in',''),
    NULLIF(_proj_obj->>'scope_out',''),
    COALESCE((_proj_obj->>'priority')::pm_priority, 'medium'::pm_priority),
    _agile_enabled,
    'planned'::pm_status, false, false,
    _proj_start, _proj_end, _caller,
    _delivery_model
  ) RETURNING id INTO _new_project_id;

  FOR _phase IN SELECT * FROM jsonb_array_elements(COALESCE(_bp->'phases','[]'::jsonb)) LOOP
    IF _schedule_mode_applied = 'relative_reanchored' THEN
      _start_off := NULLIF(_phase->'schedule'->>'start_offset_days','')::int;
      _end_off   := NULLIF(_phase->'schedule'->>'target_end_offset_days','')::int;
      _ph_start := CASE WHEN _start_off IS NOT NULL THEN _project_start_date + _start_off ELSE NULL END;
      _ph_end   := CASE WHEN _end_off   IS NOT NULL THEN _project_start_date + _end_off   ELSE NULL END;
    ELSE
      _ph_start := NULL; _ph_end := NULL;
    END IF;

    INSERT INTO public.phases (
      organization_id, workspace_id, project_id,
      name, description, phase_type, sort_order,
      status, is_archived, start_date, target_end_date, created_by
    ) VALUES (
      _org, _ws, _new_project_id,
      COALESCE(NULLIF(_phase->>'name',''), 'Phase'),
      NULLIF(_phase->>'description',''),
      COALESCE((_phase->>'phase_type')::phase_type, 'work_item'::phase_type),
      COALESCE((_phase->>'sort_order')::int, 0),
      'planned'::pm_status, false, _ph_start, _ph_end, _caller
    ) RETURNING id INTO _new_id;

    _phase_map := _phase_map || jsonb_build_object(_phase->>'ref', _new_id::text);
    _phase_count := _phase_count + 1;
  END LOOP;

  IF _agile_enabled THEN
    FOR _state IN SELECT * FROM jsonb_array_elements(COALESCE(_bp->'agile'->'workflow_states','[]'::jsonb)) LOOP
      INSERT INTO public.board_workflow_states (
        organization_id, workspace_id, project_id,
        name, category, sort_order, is_archived, created_by
      ) VALUES (
        _org, _ws, _new_project_id,
        COALESCE(NULLIF(_state->>'name',''), 'State'),
        COALESCE((_state->>'category')::workflow_state_category, 'todo'::workflow_state_category),
        COALESCE((_state->>'sort_order')::int, 0), false, _caller
      ) RETURNING id INTO _new_id;
      _state_map := _state_map || jsonb_build_object(_state->>'ref', _new_id::text);
      _state_count := _state_count + 1;
    END LOOP;

    FOR _sprint IN SELECT * FROM jsonb_array_elements(COALESCE(_bp->'agile'->'sprints','[]'::jsonb)) LOOP
      IF _schedule_mode_applied = 'relative_reanchored' THEN
        _start_off := NULLIF(_sprint->'schedule'->>'start_offset_days','')::int;
        _end_off   := NULLIF(_sprint->'schedule'->>'end_offset_days','')::int;
        _sp_start := CASE WHEN _start_off IS NOT NULL THEN _project_start_date + _start_off ELSE NULL END;
        _sp_end   := CASE WHEN _end_off   IS NOT NULL THEN _project_start_date + _end_off   ELSE NULL END;
      ELSE
        _sp_start := NULL; _sp_end := NULL;
      END IF;
      INSERT INTO public.sprints (
        organization_id, workspace_id, project_id,
        name, goal, sort_order, status, is_archived,
        start_date, end_date, created_by
      ) VALUES (
        _org, _ws, _new_project_id,
        COALESCE(NULLIF(_sprint->>'name',''), 'Sprint'),
        NULLIF(_sprint->>'goal',''),
        COALESCE((_sprint->>'sort_order')::int, 0),
        'planning'::sprint_status, false,
        _sp_start, _sp_end, _caller
      ) RETURNING id INTO _new_id;
      _sprint_map := _sprint_map || jsonb_build_object(_sprint->>'ref', _new_id::text);
      _sprint_count := _sprint_count + 1;
    END LOOP;

    FOR _backlog IN SELECT * FROM jsonb_array_elements(COALESCE(_bp->'agile'->'backlog_items','[]'::jsonb)) LOOP
      INSERT INTO public.backlog_items (
        organization_id, workspace_id, project_id,
        phase_id, sprint_id, workflow_state_id,
        title, description, priority, sort_order, is_archived, created_by
      ) VALUES (
        _org, _ws, _new_project_id,
        NULLIF(_phase_map->>(_backlog->>'phase_ref'), '')::uuid,
        NULLIF(_sprint_map->>(_backlog->>'sprint_ref'), '')::uuid,
        NULLIF(_state_map->>(_backlog->>'workflow_state_ref'), '')::uuid,
        COALESCE(NULLIF(_backlog->>'title',''), 'Backlog item'),
        NULLIF(_backlog->>'description',''),
        COALESCE((_backlog->>'priority')::pm_priority, 'medium'::pm_priority),
        COALESCE((_backlog->>'sort_order')::int, 0),
        false, _caller
      ) RETURNING id INTO _new_id;
      _backlog_map := _backlog_map || jsonb_build_object(_backlog->>'ref', _new_id::text);
      _backlog_count := _backlog_count + 1;
    END LOOP;
  END IF;

  FOR _task IN SELECT * FROM jsonb_array_elements(COALESCE(_bp->'tasks','[]'::jsonb)) LOOP
    IF _schedule_mode_applied = 'relative_reanchored' THEN
      _start_off := NULLIF(_task->'schedule'->>'start_offset_days','')::int;
      _due_off   := NULLIF(_task->'schedule'->>'due_offset_days','')::int;
      _t_start := CASE WHEN _start_off IS NOT NULL THEN _project_start_date + _start_off ELSE NULL END;
      _t_due   := CASE WHEN _due_off   IS NOT NULL THEN _project_start_date + _due_off   ELSE NULL END;
    ELSE
      _t_start := NULL; _t_due := NULL;
    END IF;

    INSERT INTO public.tasks (
      organization_id, workspace_id, project_id, phase_id,
      name, description, task_type, priority, status,
      sort_order, estimated_hours, is_archived,
      start_date, due_date,
      backlog_item_id, workflow_state_id, created_by
    ) VALUES (
      _org, _ws, _new_project_id,
      NULLIF(_phase_map->>(_task->>'phase_ref'),'')::uuid,
      COALESCE(NULLIF(_task->>'name',''), 'Task'),
      NULLIF(_task->>'description',''),
      COALESCE((_task->>'task_type')::task_type, 'work_item'::task_type),
      COALESCE((_task->>'priority')::pm_priority, 'medium'::pm_priority),
      'planned'::pm_status,
      COALESCE((_task->>'sort_order')::int, 0),
      NULLIF(_task->>'estimated_hours','')::numeric,
      false, _t_start, _t_due,
      NULLIF(_backlog_map->>(_task->>'backlog_item_ref'),'')::uuid,
      NULLIF(_state_map->>(_task->>'workflow_state_ref'),'')::uuid,
      _caller
    ) RETURNING id INTO _new_id;

    _task_map := _task_map || jsonb_build_object(_task->>'ref', _new_id::text);
    _task_count := _task_count + 1;
  END LOOP;

  FOR _dep IN SELECT * FROM jsonb_array_elements(COALESCE(_bp->'dependencies','[]'::jsonb)) LOOP
    _dep_entity := COALESCE(_dep->>'entity_type', _dep->>'source_type');
    IF _dep_entity = 'phase' THEN
      _src_id := NULLIF(_phase_map->>(_dep->>'source_ref'),'')::uuid;
      _tgt_id := NULLIF(_phase_map->>(_dep->>'target_ref'),'')::uuid;
    ELSIF _dep_entity = 'task' THEN
      _src_id := NULLIF(_task_map->>(_dep->>'source_ref'),'')::uuid;
      _tgt_id := NULLIF(_task_map->>(_dep->>'target_ref'),'')::uuid;
    ELSE
      CONTINUE;
    END IF;
    IF _src_id IS NULL OR _tgt_id IS NULL THEN CONTINUE; END IF;
    INSERT INTO public.dependencies (
      organization_id, workspace_id,
      source_type, source_id, target_type, target_id,
      dependency_type, description, created_by
    ) VALUES (
      _org, _ws,
      _dep_entity, _src_id,
      _dep_entity, _tgt_id,
      COALESCE((_dep->>'dependency_type')::dependency_type, 'finish_to_start'::dependency_type),
      NULLIF(_dep->>'description',''), _caller
    );
    _dep_count := _dep_count + 1;
  END LOOP;

  FOR _kpi IN SELECT * FROM jsonb_array_elements(COALESCE(_bp->'kpi_definitions','[]'::jsonb)) LOOP
    INSERT INTO public.kpi_definitions (
      organization_id, workspace_id,
      target_type, target_id,
      name, description, unit,
      target_value, target_direction,
      current_value, is_archived, created_by
    ) VALUES (
      _org, _ws,
      'project', _new_project_id,
      COALESCE(NULLIF(_kpi->>'name',''), 'KPI'),
      NULLIF(_kpi->>'description',''),
      NULLIF(_kpi->>'unit',''),
      NULLIF(_kpi->>'target_value','')::numeric,
      COALESCE((_kpi->>'target_direction')::kpi_target_direction, 'target_exact'::kpi_target_direction),
      NULL, false, _caller
    ) RETURNING id INTO _new_id;
    _kpi_map := _kpi_map || jsonb_build_object(_kpi->>'ref', _new_id::text);
    _kpi_count := _kpi_count + 1;
  END LOOP;

  BEGIN
    PERFORM public.log_activity_event(
      _caller, 'project_template_instantiated',
      jsonb_build_object(
        'template_id', _template_id,
        'source_project_id', _src_project,
        'workspace_id', _ws,
        'blueprint_version', 'clone_blueprint_v1',
        'schedule_mode_applied', _schedule_mode_applied,
        'widened', _did_widen
      ),
      _org, _new_project_id, 'project', _ws
    );
  EXCEPTION WHEN OTHERS THEN NULL; END;

  IF _did_widen THEN
    BEGIN
      PERFORM public.log_activity_event(
        _caller, 'project_widened_for_template_instantiation',
        jsonb_build_object(
          'template_id', _template_id,
          'nominal_start', _eff->>'nominal_start',
          'nominal_end', _eff->>'nominal_end',
          'effective_start', _eff->>'effective_start',
          'effective_end', _eff->>'effective_end',
          'reasons', _eff->'reasons'
        ),
        _org, _new_project_id, 'project', _ws
      );
    EXCEPTION WHEN OTHERS THEN NULL; END;
  END IF;

  RETURN jsonb_build_object(
    'project_id', _new_project_id,
    'organization_id', _org,
    'workspace_id', _ws,
    'program_id', _program_id,
    'template_id', _template_id,
    'source_project_id', _src_project,
    'blueprint_version', 'clone_blueprint_v1',
    'schedule_mode_applied', _schedule_mode_applied,
    'project_start_date_applied', _project_start_date,
    'widened', _did_widen,
    'effective_window', CASE WHEN _did_widen THEN _eff ELSE NULL END,
    'created_counts', jsonb_build_object(
      'phases', _phase_count, 'tasks', _task_count,
      'dependencies', _dep_count, 'kpi_definitions', _kpi_count,
      'workflow_states', _state_count, 'sprints', _sprint_count,
      'backlog_items', _backlog_count
    )
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.kc_admin_archive_article(_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_org uuid;
BEGIN
  SELECT organization_id INTO v_org FROM public.knowledge_articles WHERE id = _id;
  IF v_org IS NULL THEN RAISE EXCEPTION 'not found'; END IF;
  IF NOT public.is_org_admin(auth.uid(), v_org) THEN RAISE EXCEPTION 'forbidden'; END IF;
  UPDATE public.knowledge_articles
  SET status = 'archived', archived_at = now(),
      updated_by = auth.uid(), updated_at = now()
  WHERE id = _id;
END; $function$

CREATE OR REPLACE FUNCTION public.kc_admin_create_article(_category_id uuid, _title text, _slug text, _article_type knowledge_article_type DEFAULT 'concept'::knowledge_article_type, _summary text DEFAULT NULL::text, _body text DEFAULT NULL::text, _tooltip_excerpt text DEFAULT NULL::text, _visibility knowledge_article_visibility DEFAULT 'all_users'::knowledge_article_visibility, _related_route text DEFAULT NULL::text, _related_object_type text DEFAULT NULL::text, _related_object_id uuid DEFAULT NULL::uuid, _workspace_id uuid DEFAULT NULL::uuid, _owner_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_org uuid := public.get_user_org_id(auth.uid());
  v_id  uuid;
BEGIN
  IF v_org IS NULL OR NOT public.is_org_admin(auth.uid(), v_org) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;
  -- ensure category belongs to same org
  IF NOT EXISTS (SELECT 1 FROM public.knowledge_categories WHERE id = _category_id AND organization_id = v_org) THEN
    RAISE EXCEPTION 'invalid category';
  END IF;
  INSERT INTO public.knowledge_articles (
    organization_id, category_id, title, slug, article_type,
    summary, body, tooltip_excerpt, status, visibility,
    related_route, related_object_type, related_object_id,
    workspace_id, owner_id, created_by, updated_by
  ) VALUES (
    v_org, _category_id, _title, _slug, _article_type,
    _summary, _body, _tooltip_excerpt, 'draft', _visibility,
    _related_route, _related_object_type, _related_object_id,
    _workspace_id, _owner_id, auth.uid(), auth.uid()
  ) RETURNING id INTO v_id;
  RETURN v_id;
END; $function$

CREATE OR REPLACE FUNCTION public.kc_admin_create_category(_name text, _slug text, _description text DEFAULT NULL::text, _sort_order integer DEFAULT 0)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_org uuid := public.get_user_org_id(auth.uid());
  v_id  uuid;
BEGIN
  IF v_org IS NULL OR NOT public.is_org_admin(auth.uid(), v_org) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;
  INSERT INTO public.knowledge_categories (organization_id, name, slug, description, sort_order, created_by, updated_by)
  VALUES (v_org, _name, _slug, _description, COALESCE(_sort_order,0), auth.uid(), auth.uid())
  RETURNING id INTO v_id;
  RETURN v_id;
END; $function$

CREATE OR REPLACE FUNCTION public.kc_admin_publish_article(_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_org uuid;
BEGIN
  SELECT organization_id INTO v_org FROM public.knowledge_articles WHERE id = _id;
  IF v_org IS NULL THEN RAISE EXCEPTION 'not found'; END IF;
  IF NOT public.is_org_admin(auth.uid(), v_org) THEN RAISE EXCEPTION 'forbidden'; END IF;
  UPDATE public.knowledge_articles
  SET status = 'published', published_at = now(), archived_at = NULL,
      updated_by = auth.uid(), updated_at = now()
  WHERE id = _id;
END; $function$

