CREATE OR REPLACE FUNCTION public.link_adoption_object(_adoption_plan_id uuid, _object_type text, _object_id uuid, _adoption_initiative_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _org uuid; _ws uuid; _proj uuid; _uid uuid := auth.uid();
        _obj_proj uuid; _init_plan uuid; _id uuid; _evt text;
BEGIN
  IF _uid IS NULL OR NOT public.is_active_user(_uid) THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  IF _object_type NOT IN ('risk','blocker','kpi') THEN RAISE EXCEPTION 'invalid_object_type'; END IF;
  SELECT organization_id, workspace_id, project_id INTO _org, _ws, _proj
  FROM public.adoption_plans WHERE id = _adoption_plan_id;
  IF _org IS NULL THEN RAISE EXCEPTION 'invalid_adoption_plan'; END IF;
  IF NOT public.has_pm_authority(_uid, _ws) THEN RAISE EXCEPTION 'forbidden'; END IF;

  IF _adoption_initiative_id IS NOT NULL THEN
    SELECT adoption_plan_id INTO _init_plan FROM public.adoption_initiatives WHERE id = _adoption_initiative_id;
    IF _init_plan IS DISTINCT FROM _adoption_plan_id THEN
      RAISE EXCEPTION 'initiative_plan_mismatch';
    END IF;
  END IF;

  _obj_proj := public.adoption_resolve_object_project(_object_type, _object_id);
  IF _obj_proj IS NULL THEN RAISE EXCEPTION 'invalid_object_reference'; END IF;
  IF _obj_proj <> _proj THEN RAISE EXCEPTION 'object_project_mismatch'; END IF;

  INSERT INTO public.adoption_object_links(
    organization_id, workspace_id, project_id, adoption_plan_id,
    adoption_initiative_id, object_type, object_id, created_by
  ) VALUES (
    _org, _ws, _proj, _adoption_plan_id,
    _adoption_initiative_id, _object_type, _object_id, _uid
  ) RETURNING id INTO _id;

  _evt := CASE _object_type
    WHEN 'risk' THEN 'adoption_risk_linked'
    WHEN 'blocker' THEN 'adoption_blocker_linked'
    WHEN 'kpi' THEN 'adoption_kpi_linked'
  END;

  PERFORM public.log_activity_event(
    _organization_id => _org, _actor_id => _uid,
    _event_type => _evt,
    _target_type => 'project', _target_id => _proj,
    _metadata => jsonb_build_object(
      'adoption_plan_id', _adoption_plan_id,
      'adoption_initiative_id', _adoption_initiative_id,
      'object_type', _object_type,
      'object_id', _object_id,
      'link_id', _id
    ),
    _workspace_id => _ws
  );
  RETURN _id;
END $function$

CREATE OR REPLACE FUNCTION public.link_task_to_adoption(_task_id uuid, _adoption_initiative_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _org uuid; _ws uuid; _proj uuid; _phase uuid;
  _old_init uuid; _was_related boolean;
  _plan_id uuid; _init_plan uuid; _init_archived boolean;
BEGIN
  IF _uid IS NULL OR NOT public.is_active_user(_uid) THEN RAISE EXCEPTION 'not_authenticated'; END IF;

  SELECT t.organization_id, t.workspace_id, p.project_id, t.phase_id,
         t.adoption_initiative_id, COALESCE(t.is_adoption_related, false)
    INTO _org, _ws, _proj, _phase, _old_init, _was_related
  FROM public.tasks t
  JOIN public.phases p ON p.id = t.phase_id
  WHERE t.id = _task_id;
  IF _org IS NULL THEN RAISE EXCEPTION 'invalid_task'; END IF;

  IF NOT public.has_pm_authority(_uid, _ws) THEN RAISE EXCEPTION 'forbidden'; END IF;

  SELECT id INTO _plan_id FROM public.adoption_plans
  WHERE project_id = _proj AND COALESCE(is_archived, false) = false
  LIMIT 1;
  IF _plan_id IS NULL THEN RAISE EXCEPTION 'adoption_plan_required'; END IF;

  IF _adoption_initiative_id IS NOT NULL THEN
    SELECT adoption_plan_id, COALESCE(is_archived, false)
      INTO _init_plan, _init_archived
    FROM public.adoption_initiatives WHERE id = _adoption_initiative_id;
    IF _init_plan IS NULL THEN RAISE EXCEPTION 'invalid_initiative'; END IF;
    IF _init_plan IS DISTINCT FROM _plan_id THEN RAISE EXCEPTION 'initiative_plan_mismatch'; END IF;
    IF _init_archived THEN RAISE EXCEPTION 'invalid_initiative'; END IF;
  END IF;

  UPDATE public.tasks
     SET is_adoption_related = true,
         adoption_initiative_id = _adoption_initiative_id,
         updated_at = now()
   WHERE id = _task_id;

  PERFORM public.log_activity_event(
    _organization_id => _org, _actor_id => _uid,
    _event_type => 'adoption_task_linked',
    _target_type => 'task', _target_id => _task_id,
    _metadata => jsonb_build_object(
      'project_id', _proj,
      'phase_id', _phase,
      'adoption_plan_id', _plan_id,
      'old_adoption_initiative_id', _old_init,
      'new_adoption_initiative_id', _adoption_initiative_id,
      'linked_to_general_plan', (_adoption_initiative_id IS NULL)
    ),
    _workspace_id => _ws
  );

  RETURN _task_id;
END $function$

