  SELECT json_agg(row_to_json(t)) INTO _result FROM (
    SELECT r.id,
           btpm_decrypt(r.title, r.organization_id) as title,
           r.status, r.likelihood, r.impact,
           btpm_decrypt(r.description, r.organization_id) as description,
           btpm_decrypt(r.mitigation_plan, r.organization_id) as mitigation_plan,
           r.reported_by, r.target_type, r.target_id,
           r.organization_id, r.workspace_id,
           r.created_at, r.updated_at
    FROM risks r
    WHERE r.target_id = _target_id AND r.target_type = _target_type
    ORDER BY r.created_at DESC
