CREATE OR REPLACE FUNCTION public.list_knowledge_article_ai_metadata_for_visible_articles(_article_ids uuid[])
 RETURNS TABLE(article_id uuid, ai_flow text, feature_area text[], route_patterns text[], user_intents text[], audience text[], synonyms text[], freshness_label text, related_feature_flags text[], question_examples text[], answer_rules text[], forbidden_claims text[], workflow_metadata jsonb, updated_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_org uuid := public.get_user_org_id(auth.uid());
  v_is_admin boolean := FALSE;
BEGIN
  IF v_uid IS NULL OR v_org IS NULL THEN RETURN; END IF;
  v_is_admin := public.is_org_admin(v_uid, v_org);
  RETURN QUERY
  SELECT
    m.article_id, m.ai_flow, m.feature_area, m.route_patterns, m.user_intents, m.audience,
    m.synonyms, m.freshness_label, m.related_feature_flags,
    public._kc_ai_meta_decrypt_array(m.question_examples_protected, m.organization_id),
    public._kc_ai_meta_decrypt_array(m.answer_rules_protected,      m.organization_id),
    public._kc_ai_meta_decrypt_array(m.forbidden_claims_protected,  m.organization_id),
    public._kc_ai_meta_decrypt_jsonb(m.workflow_metadata_protected, m.organization_id),
    m.updated_at
  FROM public.knowledge_article_ai_metadata m
  JOIN public.knowledge_articles a ON a.id = m.article_id
  WHERE a.organization_id = v_org
    AND m.article_id = ANY(_article_ids)
    AND (
      v_is_admin
      OR (a.status = 'published' AND (
        a.visibility = 'all_users'
        OR (a.visibility = 'workspace_scoped' AND a.workspace_id IS NOT NULL
            AND public.is_workspace_member(v_uid, a.workspace_id))
      ))
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.list_project_templates(_workspace_id uuid, _include_archived boolean DEFAULT false)
 RETURNS SETOF jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _caller uuid := auth.uid();
  _org_id uuid;
  r RECORD;
  _bp jsonb;
  _summary jsonb;
BEGIN
  IF _caller IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;

  SELECT organization_id INTO _org_id FROM public.workspaces WHERE id = _workspace_id;
  IF _org_id IS NULL THEN
    RAISE EXCEPTION 'workspace not found';
  END IF;

  IF NOT (public.is_workspace_member(_caller, _workspace_id) OR public.is_org_admin(_caller, _org_id)) THEN
    RAISE EXCEPTION 'access denied' USING ERRCODE = '42501';
  END IF;

  FOR r IN
    SELECT id, organization_id, workspace_id, source_project_id,
           name, description, blueprint_payload, blueprint_version,
           is_archived, created_at, updated_at, created_by, updated_by
      FROM public.project_templates
     WHERE workspace_id = _workspace_id
       AND (_include_archived OR is_archived = false)
     ORDER BY updated_at DESC
  LOOP
    BEGIN
      _bp := public.btpm_decrypt(r.blueprint_payload, r.organization_id)::jsonb;
    EXCEPTION WHEN OTHERS THEN
      _bp := '{}'::jsonb;
    END;

    _summary := public._template_blueprint_summary(_bp);

    RETURN NEXT jsonb_build_object(
      'template_id', r.id,
      'organization_id', r.organization_id,
      'workspace_id', r.workspace_id,
      'source_project_id', r.source_project_id,
      'name', public.btpm_decrypt(r.name, r.organization_id),
      'description', CASE WHEN r.description IS NULL THEN NULL ELSE public.btpm_decrypt(r.description, r.organization_id) END,
      'blueprint_version', r.blueprint_version,
      'is_archived', r.is_archived,
      'created_at', r.created_at,
      'updated_at', r.updated_at,
      'created_by', r.created_by,
      'updated_by', r.updated_by,
      'schedule_mode', _summary->>'schedule_mode',
      'agile_enabled', (_summary->>'agile_enabled')::boolean,
      'summary_counts', _summary->'summary_counts'
    );
  END LOOP;
  RETURN;
END;
$function$

CREATE OR REPLACE FUNCTION public.list_user_saved_views(_surface_key text, _scope_key text DEFAULT 'global'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user uuid := auth.uid();
  v_org  uuid;
  v_out  jsonb;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'not authenticated';
  END IF;
  SELECT organization_id INTO v_org FROM public.profiles WHERE id = v_user;
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'organization not resolved for user';
  END IF;

  SELECT COALESCE(jsonb_agg(row ORDER BY (row->>'updated_at') DESC), '[]'::jsonb)
  INTO v_out
  FROM (
    SELECT jsonb_build_object(
      'id',         v.id,
      'name',       public.btpm_decrypt(v.name, v.organization_id),
      'state',      public.btpm_decrypt(v.state_payload, v.organization_id)::jsonb,
      'created_at', v.created_at,
      'updated_at', v.updated_at
    ) AS row
    FROM public.user_saved_views v
    WHERE v.user_id = v_user
      AND v.organization_id = v_org
      AND v.surface_key = _surface_key
      AND v.scope_key   = _scope_key
  ) s;

  RETURN v_out;
END;
$function$

CREATE OR REPLACE FUNCTION public.list_user_workspaces()
 RETURNS json
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _org_id uuid;
  _pref_org uuid;
  _active_org_count int;
  _result json;
BEGIN
  IF _uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF NOT public.is_active_user(_uid) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;

  -- Prefer explicit preference when still valid.
  SELECT p.last_active_organization_id INTO _pref_org
    FROM public.user_active_context_preferences p
   WHERE p.user_id = _uid;

  IF _pref_org IS NOT NULL AND public.is_organization_member(_pref_org, _uid) THEN
    _org_id := _pref_org;
  ELSE
    -- Fallback: sole active organization membership. Runtime authority is
    -- organization_memberships + tenant_memberships — never profiles.organization_id.
    SELECT COUNT(*) INTO _active_org_count
      FROM public.organization_memberships om
      JOIN public.tenant_memberships tm
        ON tm.tenant_id = om.tenant_id AND tm.user_id = om.user_id
     WHERE om.user_id = _uid AND om.status = 'active' AND tm.status = 'active';

    IF _active_org_count = 1 THEN
      SELECT om.organization_id INTO _org_id
        FROM public.organization_memberships om
        JOIN public.tenant_memberships tm
          ON tm.tenant_id = om.tenant_id AND tm.user_id = om.user_id
       WHERE om.user_id = _uid AND om.status = 'active' AND tm.status = 'active'
       LIMIT 1;
    ELSE
      _org_id := NULL;
    END IF;
  END IF;

  IF _org_id IS NULL THEN RETURN '[]'::json; END IF;

  SELECT json_agg(row_to_json(t)) INTO _result
  FROM (
    SELECT * FROM (
      SELECT DISTINCT ON (w.id)
        w.id, public.btpm_decrypt(w.name, _org_id) AS name,
        w.organization_id, w.is_archived, w.is_demo
      FROM public.workspaces w
      LEFT JOIN public.workspace_memberships wm
        ON wm.workspace_id = w.id AND wm.user_id = _uid
      WHERE w.is_archived = false
        AND w.organization_id = _org_id
        AND (wm.user_id IS NOT NULL OR w.is_demo = true OR public.is_org_admin(_uid, w.organization_id))
      ORDER BY w.id
    ) inner_t
    ORDER BY name
  ) t;

  RETURN COALESCE(_result, '[]'::json);
END;
$function$

CREATE OR REPLACE FUNCTION public.list_workspace_projects(_workspace_id uuid, _include_archived boolean DEFAULT false)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _org_id uuid;
  _result json;
BEGIN
  IF _uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF NOT public.is_active_user(_uid) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;
  IF NOT public.can_read_demo_or_member(_uid, _workspace_id) THEN
    RAISE EXCEPTION 'Not a workspace member';
  END IF;

  SELECT organization_id INTO _org_id FROM public.workspaces WHERE id = _workspace_id;
  IF _org_id IS NULL THEN RAISE EXCEPTION 'Workspace not found'; END IF;

  SELECT json_agg(row_to_json(t)) INTO _result
  FROM (
    SELECT
      p.id,
      public.btpm_decrypt(p.name, _org_id) AS name,
      p.status,
      p.priority,
      p.project_stage,
      p.delivery_model,
      p.program_id,
      p.start_date,
      p.target_end_date,
      p.agile_enabled,
      p.is_archived,
      (SELECT public.btpm_decrypt(pr.name, _org_id) FROM public.programs pr WHERE pr.id = p.program_id) AS program_name,
      p.portfolio_item_id,
      (SELECT public.btpm_decrypt(pi.name, _org_id) FROM public.portfolio_items pi WHERE pi.id = p.portfolio_item_id) AS portfolio_name,
      (SELECT public.btpm_decrypt(pi.code, _org_id) FROM public.portfolio_items pi WHERE pi.id = p.portfolio_item_id) AS portfolio_code,
      (SELECT pi.lifecycle_state FROM public.portfolio_items pi WHERE pi.id = p.portfolio_item_id) AS portfolio_lifecycle_state,
      (SELECT pi.is_archived FROM public.portfolio_items pi WHERE pi.id = p.portfolio_item_id) AS portfolio_is_archived
    FROM public.projects p
    WHERE p.workspace_id = _workspace_id
      AND (_include_archived OR p.is_archived = false)
    ORDER BY public.btpm_decrypt(p.name, _org_id)
  ) t;

  RETURN COALESCE(_result, '[]'::json);
END;
$function$

CREATE OR REPLACE FUNCTION public.log_activity_event(_organization_id uuid, _actor_id uuid, _event_type text, _target_type text, _target_id uuid, _metadata jsonb DEFAULT '{}'::jsonb, _workspace_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE _event_id UUID;
BEGIN
  IF NOT public.is_active_user(auth.uid()) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;
  IF _workspace_id IS NOT NULL THEN
    IF NOT (is_workspace_member(auth.uid(), _workspace_id) OR is_org_admin(auth.uid(), _organization_id)) THEN RAISE EXCEPTION 'Access denied: not authorized for this workspace'; END IF;
  ELSE
    IF NOT is_org_admin(auth.uid(), _organization_id) THEN
      IF _actor_id != auth.uid() THEN RAISE EXCEPTION 'Access denied: org-level events require admin authority'; END IF;
    END IF;
  END IF;
  INSERT INTO public.activity_events (organization_id, actor_id, event_type, target_type, target_id, metadata, workspace_id) VALUES (_organization_id, _actor_id, _event_type, _target_type, _target_id, _metadata::text, _workspace_id) RETURNING id INTO _event_id;
  RETURN _event_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.mark_decision_case_ai_run_discarded(_ai_run_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  _run public.decision_case_ai_runs%ROWTYPE;
  _row public.governance_records%ROWTYPE;
BEGIN
  SELECT * INTO _run FROM public.decision_case_ai_runs WHERE id = _ai_run_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'AI run not found' USING ERRCODE='P0002'; END IF;
  SELECT * INTO _row FROM public.governance_records WHERE id = _run.governance_record_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Parent record not found' USING ERRCODE='P0002'; END IF;
  PERFORM public._gov_assert_project_write(_row.project_id);

  IF _run.status <> 'completed' THEN
    RAISE EXCEPTION 'AI run is not in a discardable state (status=%)', _run.status USING ERRCODE='22023';
  END IF;
  IF _run.brief_version_id IS NOT NULL THEN
    RAISE EXCEPTION 'AI run is already linked to a brief version' USING ERRCODE='22023';
  END IF;

  UPDATE public.decision_case_ai_runs
    SET status = 'discarded',
        discarded_at = now(),
        updated_at = now()
    WHERE id = _ai_run_id;

  PERFORM public.log_activity_event(_row.organization_id, auth.uid(),
    'decision_case_ai_run_discarded', 'governance_record', _row.id,
    jsonb_build_object('project_id', _row.project_id, 'ai_run_id', _ai_run_id),
    _row.workspace_id);
END; $function$

CREATE OR REPLACE FUNCTION public.mark_governance_record_copilot_data_package_downloaded(_package_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  _p public.governance_record_copilot_data_packages%ROWTYPE;
  _row public.governance_records%ROWTYPE;
  _sp_id uuid;
BEGIN
  SELECT * INTO _p FROM public.governance_record_copilot_data_packages WHERE id = _package_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Data package not found' USING ERRCODE='P0002'; END IF;
  SELECT * INTO _row FROM public.governance_records WHERE id = _p.governance_record_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Parent record not found' USING ERRCODE='P0002'; END IF;
  IF _row.record_kind IS DISTINCT FROM 'decision_case' THEN
    RAISE EXCEPTION 'Data packages are only allowed on decision_case records' USING ERRCODE='22023';
  END IF;
  PERFORM public._gov_assert_project_read(_row.project_id);
  FOREACH _sp_id IN ARRAY _p.source_project_ids LOOP
    IF NOT public.has_project_access(auth.uid(), _sp_id) THEN
      RAISE EXCEPTION 'You do not have access to source project %', _sp_id USING ERRCODE='42501';
    END IF;
  END LOOP;

  UPDATE public.governance_record_copilot_data_packages
    SET downloaded_at = now(), downloaded_by = auth.uid()
    WHERE id = _package_id;
END; $function$

CREATE OR REPLACE FUNCTION public.mark_governance_record_stakeholder_package_provided(_package_id uuid, _distribution_note text DEFAULT NULL::text, _distribution_evidence_url text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  _p public.governance_record_stakeholder_packages%ROWTYPE;
  _row public.governance_records%ROWTYPE;
  _dn text; _url text;
BEGIN
  SELECT * INTO _p FROM public.governance_record_stakeholder_packages WHERE id = _package_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Stakeholder package not found' USING ERRCODE='P0002'; END IF;
  SELECT * INTO _row FROM public.governance_records WHERE id = _p.governance_record_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Parent record not found' USING ERRCODE='P0002'; END IF;
  IF _row.record_kind IS DISTINCT FROM 'decision_case' THEN
    RAISE EXCEPTION 'Stakeholder packages are only allowed on decision_case records' USING ERRCODE='22023';
  END IF;
  PERFORM public._gov_assert_project_write(_row.project_id);

  _dn  := NULLIF(trim(COALESCE(_distribution_note, '')), '');
  _url := NULLIF(trim(COALESCE(_distribution_evidence_url, '')), '');

  IF _url IS NOT NULL AND _url NOT LIKE 'http://%' AND _url NOT LIKE 'https://%' THEN
    RAISE EXCEPTION 'distribution_evidence_url must start with http:// or https://' USING ERRCODE='22023';
  END IF;

  UPDATE public.governance_record_stakeholder_packages
    SET package_status = 'provided',
        distribution_note = COALESCE(_dn, distribution_note),
        distribution_evidence_url = COALESCE(_url, distribution_evidence_url),
        provided_to_stakeholders_at = now(),
        provided_to_stakeholders_by = auth.uid(),
        updated_at = now(),
        updated_by = auth.uid()
    WHERE id = _package_id;

  UPDATE public.governance_record_stakeholder_packages
    SET is_current = false, updated_by = auth.uid(), updated_at = now()
    WHERE governance_record_id = _p.governance_record_id AND is_current = true AND id <> _package_id;

  UPDATE public.governance_record_stakeholder_packages
    SET is_current = true, updated_by = auth.uid(), updated_at = now()
    WHERE id = _package_id;

  IF _row.decision_stage NOT IN ('decision_taken','closed') THEN
    UPDATE public.governance_records
       SET decision_stage = 'provided_to_stakeholders', updated_at = now()
     WHERE id = _p.governance_record_id
       AND decision_stage NOT IN ('decision_taken','closed');
  END IF;

  PERFORM public.log_activity_event(_row.organization_id, auth.uid(),
    'governance_record_stakeholder_package_provided', 'governance_record', _p.governance_record_id,
    jsonb_build_object('project_id', _row.project_id,
                       'stakeholder_package_id', _package_id,
                       'version_number', _p.version_number),
    _row.workspace_id);
END; $function$

CREATE OR REPLACE FUNCTION public.move_task_workflow_state(_task_id uuid, _workflow_state_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  _user_id uuid := auth.uid();
  _task record;
  _state record;
  _previous_workflow_state_id uuid;
BEGIN
  IF _user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  IF NOT public.is_active_user(_user_id) THEN
    RAISE EXCEPTION 'Account is deactivated';
  END IF;

  SELECT id, project_id, workspace_id, organization_id, workflow_state_id
  INTO _task
  FROM public.tasks
  WHERE id = _task_id;

  IF _task IS NULL THEN
    RAISE EXCEPTION 'Task not found';
  END IF;

  SELECT id, project_id, workspace_id, organization_id, is_archived
  INTO _state
  FROM public.board_workflow_states
  WHERE id = _workflow_state_id;

  IF _state IS NULL THEN
    RAISE EXCEPTION 'Workflow state not found';
  END IF;

  IF _state.is_archived THEN
    RAISE EXCEPTION 'Workflow state is archived';
  END IF;

  IF _task.project_id <> _state.project_id OR _task.workspace_id <> _state.workspace_id OR _task.organization_id <> _state.organization_id THEN
    RAISE EXCEPTION 'Task and workflow state must belong to the same project and workspace';
  END IF;

  IF NOT public.has_pm_authority(_user_id, _task.workspace_id) THEN
    RAISE EXCEPTION 'Insufficient authority';
  END IF;

  IF NOT public.can_write_demo(_user_id, _task.workspace_id) THEN
    RAISE EXCEPTION 'Not authorized to write in this workspace (read-only/demo)';
  END IF;

  _previous_workflow_state_id := _task.workflow_state_id;

  UPDATE public.tasks
  SET workflow_state_id = _workflow_state_id
  WHERE id = _task_id;

  PERFORM public.log_activity_event(
    _organization_id => _task.organization_id,
    _workspace_id => _task.workspace_id,
    _actor_id => _user_id,
    _event_type => 'workflow_state_changed',
    _target_type => 'task',
    _target_id => _task_id,
    _metadata => jsonb_build_object(
      'source', 'agile_board',
      'from_workflow_state_id', _previous_workflow_state_id,
      'to_workflow_state_id', _workflow_state_id
    )
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.org_admin_assign_org_admin(_organization_id uuid, _target_user_id uuid, _reason text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _om public.organization_memberships%ROWTYPE; _tid uuid; _prev text;
BEGIN
  IF NOT public.is_user_org_admin(auth.uid(), _organization_id) THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE='42501';
  END IF;
  SELECT tenant_id INTO _tid FROM public.organizations WHERE id=_organization_id;
  SELECT * INTO _om FROM public.organization_memberships
   WHERE organization_id=_organization_id AND user_id=_target_user_id;
  IF NOT FOUND OR _om.status<>'active' THEN
    RAISE EXCEPTION 'target_not_active_org_member' USING ERRCODE='42501';
  END IF;
  _prev := _om.role::text;
  IF _om.role<>'org_admin' THEN
    UPDATE public.organization_memberships SET role='org_admin', updated_at=now(), updated_by=auth.uid() WHERE id=_om.id;
  END IF;
  PERFORM public._log_admin_authority('assign_org_admin',
    _tid, _organization_id, _target_user_id, NULL, _prev, 'org_admin', _om.status::text, _om.status::text, _reason, '{}'::jsonb);
  RETURN _om.id;
END;$function$

CREATE OR REPLACE FUNCTION public.org_admin_remove_org_admin(_organization_id uuid, _target_user_id uuid, _reason text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _om public.organization_memberships%ROWTYPE; _tid uuid; _remaining int;
BEGIN
  IF NOT public.is_user_org_admin(auth.uid(), _organization_id) THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE='42501';
  END IF;
  SELECT tenant_id INTO _tid FROM public.organizations WHERE id=_organization_id;
  SELECT * INTO _om FROM public.organization_memberships
   WHERE organization_id=_organization_id AND user_id=_target_user_id;
  IF NOT FOUND OR _om.role<>'org_admin' OR _om.status<>'active' THEN
    RAISE EXCEPTION 'target_not_active_org_admin' USING ERRCODE='42501';
  END IF;
  SELECT count(*) INTO _remaining FROM public.organization_memberships
   WHERE organization_id=_organization_id AND role='org_admin' AND status='active' AND user_id<>_target_user_id;
  IF _remaining<1 THEN
    PERFORM public._log_admin_authority('blocked_last_admin_change',
      _tid, _organization_id, _target_user_id, NULL, 'org_admin', 'org_member', _om.status::text, _om.status::text, _reason, '{}'::jsonb);
    RAISE EXCEPTION 'last_org_admin' USING ERRCODE='42501';
  END IF;
  UPDATE public.organization_memberships SET role='org_member', updated_at=now(), updated_by=auth.uid() WHERE id=_om.id;
  PERFORM public._log_admin_authority('remove_org_admin',
    _tid, _organization_id, _target_user_id, NULL, 'org_admin', 'org_member', _om.status::text, _om.status::text, _reason, '{}'::jsonb);
  RETURN _om.id;
END;$function$

CREATE OR REPLACE FUNCTION public.pa_can_admin_workspace(_workspace_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _caller uuid := auth.uid();
  _org_id uuid;
BEGIN
  IF _caller IS NULL THEN RETURN false; END IF;
  SELECT organization_id INTO _org_id FROM public.workspaces WHERE id = _workspace_id;
  IF _org_id IS NULL THEN RETURN false; END IF;
  RETURN public.is_org_admin(_caller, _org_id)
      OR public.is_workspace_admin_or_higher(_caller, _workspace_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.pa_grant_all_workspace_projects(_target_user_id uuid, _workspace_id uuid, _override_role project_role DEFAULT NULL::project_role)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _caller uuid := auth.uid();
  _ws_role text;
  _mapped public.project_role;
  _affected integer := 0;
BEGIN
  IF NOT public.pa_can_admin_workspace(_workspace_id) THEN
    RAISE EXCEPTION 'not authorized to administer this workspace';
  END IF;

  -- Resolve role
  IF _override_role IS NOT NULL THEN
    _mapped := _override_role;
  ELSE
    SELECT wm.role::text INTO _ws_role
    FROM public.workspace_memberships wm
    WHERE wm.workspace_id = _workspace_id
      AND wm.user_id = _target_user_id
    LIMIT 1;

    IF _ws_role IS NULL THEN
      RAISE EXCEPTION 'user does not have workspace membership';
    END IF;
    _mapped := public.pa_map_workspace_role_to_project_role(_ws_role);
    IF _mapped IS NULL THEN
      RAISE EXCEPTION 'workspace role % is not mappable to a project role', _ws_role;
    END IF;
  END IF;

  -- Insert/upsert for every non-archived project in workspace
  WITH target_projects AS (
    SELECT id AS project_id
    FROM public.projects
    WHERE workspace_id = _workspace_id
      AND is_archived = false
  ),
  upserted AS (
    INSERT INTO public.project_memberships (project_id, user_id, role, granted_by)
    SELECT tp.project_id, _target_user_id, _mapped, _caller
    FROM target_projects tp
    WHERE NOT EXISTS (
      SELECT 1 FROM public.project_memberships pm
      WHERE pm.project_id = tp.project_id
        AND pm.user_id = _target_user_id
        AND pm.removed_at IS NULL
    )
    RETURNING 1
  ),
  revived AS (
    UPDATE public.project_memberships pm
    SET role = _mapped, granted_by = _caller, removed_at = NULL, updated_at = now()
    FROM target_projects tp
    WHERE pm.project_id = tp.project_id
      AND pm.user_id = _target_user_id
      AND pm.removed_at IS NOT NULL
      AND NOT EXISTS (
        SELECT 1 FROM public.project_memberships pm2
        WHERE pm2.project_id = tp.project_id
          AND pm2.user_id = _target_user_id
          AND pm2.removed_at IS NULL
      )
    RETURNING 1
  )
  SELECT (SELECT count(*) FROM upserted) + (SELECT count(*) FROM revived)
  INTO _affected;

  RETURN _affected;
END;
$function$

CREATE OR REPLACE FUNCTION public.pa_grant_project_access(_target_user_id uuid, _project_id uuid, _role project_role)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _caller uuid := auth.uid();
  _ws_id uuid;
  _existing_id uuid;
  _has_ws_membership boolean;
BEGIN
  IF _caller IS NULL THEN
    RAISE EXCEPTION 'authentication required';
  END IF;
  IF _caller = _target_user_id THEN
    -- Block self-grant for non-admins; admins still go through the same path so block uniformly
    -- Allow only if caller is org_admin (rare, supportable case)
    NULL;
  END IF;

  SELECT workspace_id INTO _ws_id FROM public.projects WHERE id = _project_id;
  IF _ws_id IS NULL THEN
    RAISE EXCEPTION 'project not found';
  END IF;

  IF NOT public.pa_can_admin_workspace(_ws_id) THEN
    RAISE EXCEPTION 'not authorized to administer this workspace';
  END IF;

  -- Require target user to have workspace membership before granting project access
  SELECT EXISTS (
    SELECT 1 FROM public.workspace_memberships
    WHERE workspace_id = _ws_id AND user_id = _target_user_id
  ) INTO _has_ws_membership;
  IF NOT _has_ws_membership THEN
    RAISE EXCEPTION 'user does not have workspace membership';
  END IF;

  -- Upsert active membership
  SELECT id INTO _existing_id
  FROM public.project_memberships
  WHERE project_id = _project_id
    AND user_id = _target_user_id
    AND removed_at IS NULL;

  IF _existing_id IS NOT NULL THEN
    UPDATE public.project_memberships
    SET role = _role,
        granted_by = _caller,
        updated_at = now()
    WHERE id = _existing_id;
    RETURN _existing_id;
  END IF;

  -- If a soft-removed row exists, revive it
  SELECT id INTO _existing_id
  FROM public.project_memberships
  WHERE project_id = _project_id
    AND user_id = _target_user_id
  ORDER BY created_at DESC
  LIMIT 1;

  IF _existing_id IS NOT NULL THEN
    UPDATE public.project_memberships
    SET role = _role,
        granted_by = _caller,
        removed_at = NULL,
        updated_at = now()
    WHERE id = _existing_id;
    RETURN _existing_id;
  END IF;

  INSERT INTO public.project_memberships (project_id, user_id, role, granted_by)
  VALUES (_project_id, _target_user_id, _role, _caller)
  RETURNING id INTO _existing_id;

  RETURN _existing_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.pa_remove_project_access(_target_user_id uuid, _project_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _ws_id uuid;
BEGIN
  SELECT workspace_id INTO _ws_id FROM public.projects WHERE id = _project_id;
  IF _ws_id IS NULL THEN
    RAISE EXCEPTION 'project not found';
  END IF;
  IF NOT public.pa_can_admin_workspace(_ws_id) THEN
    RAISE EXCEPTION 'not authorized to administer this workspace';
  END IF;

  UPDATE public.project_memberships
  SET removed_at = now(),
      updated_at = now()
  WHERE project_id = _project_id
    AND user_id = _target_user_id
    AND removed_at IS NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.pa_reset_workspace_to_inherited(_target_user_id uuid, _workspace_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _caller uuid := auth.uid();
  _ws_role text;
  _mapped public.project_role;
  _affected integer := 0;
BEGIN
  IF NOT public.pa_can_admin_workspace(_workspace_id) THEN
    RAISE EXCEPTION 'not authorized to administer this workspace';
  END IF;

  SELECT wm.role::text INTO _ws_role
  FROM public.workspace_memberships wm
  WHERE wm.workspace_id = _workspace_id AND wm.user_id = _target_user_id
  LIMIT 1;
  IF _ws_role IS NULL THEN
    RAISE EXCEPTION 'user does not have workspace membership';
  END IF;
  _mapped := public.pa_map_workspace_role_to_project_role(_ws_role);
  IF _mapped IS NULL THEN
    RAISE EXCEPTION 'workspace role % is not mappable to a project role', _ws_role;
  END IF;

  -- Update active rows to mapped role
  UPDATE public.project_memberships pm
  SET role = _mapped, granted_by = _caller, updated_at = now()
  FROM public.projects p
  WHERE pm.project_id = p.id
    AND p.workspace_id = _workspace_id
    AND p.is_archived = false
    AND pm.user_id = _target_user_id
    AND pm.removed_at IS NULL
    AND pm.role <> _mapped;
  GET DIAGNOSTICS _affected = ROW_COUNT;

  -- Insert missing for non-archived projects
  WITH inserted AS (
    INSERT INTO public.project_memberships (project_id, user_id, role, granted_by)
    SELECT p.id, _target_user_id, _mapped, _caller
    FROM public.projects p
    WHERE p.workspace_id = _workspace_id
      AND p.is_archived = false
      AND NOT EXISTS (
        SELECT 1 FROM public.project_memberships pm
        WHERE pm.project_id = p.id
          AND pm.user_id = _target_user_id
          AND pm.removed_at IS NULL
      )
    RETURNING 1
  )
  SELECT _affected + count(*) FROM inserted INTO _affected;

  RETURN _affected;
END;
$function$

CREATE OR REPLACE FUNCTION public.platform_admin_assign_tenant_admin(_tenant_id uuid, _target_user_id uuid, _reason text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _row public.tenant_memberships%ROWTYPE;
  _prev_role text;
BEGIN
  IF NOT public.is_platform_super_admin(auth.uid()) THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO _row FROM public.tenant_memberships
   WHERE tenant_id = _tenant_id AND user_id = _target_user_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'target_not_tenant_member' USING ERRCODE = '42501';
  END IF;
  IF _row.status <> 'active' THEN
    RAISE EXCEPTION 'target_not_active_tenant_member' USING ERRCODE = '42501';
  END IF;
  IF _row.role = 'tenant_owner' THEN
    PERFORM public._log_admin_authority('blocked_protected_tenant_admin_change',
      _tenant_id, NULL, _target_user_id, NULL, _row.role::text, 'tenant_admin', _row.status::text, _row.status::text, _reason, '{}'::jsonb);
    RAISE EXCEPTION 'protected_tenant_admin' USING ERRCODE = '42501';
  END IF;
  _prev_role := _row.role::text;
  IF _row.role <> 'tenant_admin' THEN
    UPDATE public.tenant_memberships
       SET role = 'tenant_admin', updated_at = now(), updated_by = auth.uid()
     WHERE id = _row.id;
  END IF;
  PERFORM public._log_admin_authority('assign_tenant_admin',
    _tenant_id, NULL, _target_user_id, NULL, _prev_role, 'tenant_admin', _row.status::text, _row.status::text, _reason, '{}'::jsonb);
  RETURN _row.id;
END;
$function$

CREATE OR REPLACE FUNCTION public.platform_admin_get_encryption_posture_overview()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _caller uuid := auth.uid();
  _tenants jsonb;
  _totals  jsonb;
BEGIN
  IF _caller IS NULL THEN
    RAISE EXCEPTION 'authentication_required';
  END IF;
  IF NOT public.is_platform_super_admin(_caller) THEN
    RAISE EXCEPTION 'not_platform_super_admin';
  END IF;

  SELECT COALESCE(jsonb_agg(to_jsonb(tep) ORDER BY tep.tenant_name), '[]'::jsonb)
    INTO _tenants
    FROM public.tenant_encryption_posture tep;

  SELECT jsonb_build_object(
    'tenants_total',                      (SELECT COUNT(*) FROM public.tenants),
    'tenants_with_metadata',              (SELECT COUNT(DISTINCT tenant_id) FROM public.tenant_encryption_keys),
    'organizations_total',                (SELECT COUNT(*) FROM public.organizations),
    'organizations_with_metadata',        (SELECT COUNT(*) FROM public.organization_encryption_keys),
    'organizations_missing_metadata',     (SELECT COUNT(*) FROM public.organizations o
                                              WHERE NOT EXISTS (SELECT 1 FROM public.organization_encryption_keys oek WHERE oek.organization_id = o.id)),
    'production_org_count',               (SELECT COUNT(*) FROM public.organizations WHERE environment_role = 'production'),
    'non_production_org_count',           (SELECT COUNT(*) FROM public.organizations WHERE environment_role = 'non_production')
  ) INTO _totals;

  RETURN jsonb_build_object('totals', _totals, 'tenants', _tenants);
END;
$function$

CREATE OR REPLACE FUNCTION public.platform_admin_remove_tenant_admin(_tenant_id uuid, _target_user_id uuid, _reason text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _row public.tenant_memberships%ROWTYPE;
  _remaining int;
BEGIN
  IF NOT public.is_platform_super_admin(auth.uid()) THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO _row FROM public.tenant_memberships
   WHERE tenant_id = _tenant_id AND user_id = _target_user_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'target_not_tenant_member' USING ERRCODE = '42501';
  END IF;
  IF _row.role = 'tenant_owner' THEN
    PERFORM public._log_admin_authority('blocked_protected_tenant_admin_change',
      _tenant_id, NULL, _target_user_id, NULL, _row.role::text, _row.role::text, _row.status::text, _row.status::text, _reason, '{}'::jsonb);
    RAISE EXCEPTION 'protected_tenant_admin' USING ERRCODE = '42501';
  END IF;
  IF _row.role <> 'tenant_admin' THEN
    RAISE EXCEPTION 'target_not_tenant_admin' USING ERRCODE = '42501';
  END IF;
  SELECT count(*) INTO _remaining
    FROM public.tenant_memberships
   WHERE tenant_id = _tenant_id AND status='active'
     AND role IN ('tenant_owner','tenant_admin')
     AND user_id <> _target_user_id;
  IF _remaining < 1 THEN
    PERFORM public._log_admin_authority('blocked_last_admin_change',
      _tenant_id, NULL, _target_user_id, NULL, _row.role::text, 'tenant_member', _row.status::text, _row.status::text, _reason, '{}'::jsonb);
    RAISE EXCEPTION 'last_tenant_admin' USING ERRCODE = '42501';
  END IF;
  UPDATE public.tenant_memberships
     SET role='tenant_member', updated_at=now(), updated_by=auth.uid()
   WHERE id=_row.id;
  PERFORM public._log_admin_authority('remove_tenant_admin',
    _tenant_id, NULL, _target_user_id, NULL, 'tenant_admin', 'tenant_member', _row.status::text, _row.status::text, _reason, '{}'::jsonb);
  RETURN _row.id;
END;
$function$

CREATE OR REPLACE FUNCTION public.pmg_build_result(_status pmg_command_status, _command text, _target_type text DEFAULT NULL::text, _target_id uuid DEFAULT NULL::uuid, _project_id uuid DEFAULT NULL::uuid, _data jsonb DEFAULT '{}'::jsonb, _changes jsonb DEFAULT '[]'::jsonb, _warnings jsonb DEFAULT '[]'::jsonb, _confirmations jsonb DEFAULT '[]'::jsonb, _conflict jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
DECLARE
  v_data jsonb := COALESCE(_data, '{}'::jsonb);
  v_changes jsonb := COALESCE(_changes, '[]'::jsonb);
  v_warnings jsonb := COALESCE(_warnings, '[]'::jsonb);
  v_confirmations jsonb := COALESCE(_confirmations, '[]'::jsonb);
BEGIN
  IF _command IS NULL OR btrim(_command) = '' THEN
    RAISE EXCEPTION 'pmg_build_result: command must be a non-empty string' USING ERRCODE = '22023';
  END IF;
  IF jsonb_typeof(v_data) <> 'object' THEN
    RAISE EXCEPTION 'pmg_build_result: data must be a JSON object' USING ERRCODE = '22023';
  END IF;
  IF jsonb_typeof(v_changes) <> 'array' THEN
    RAISE EXCEPTION 'pmg_build_result: changes must be a JSON array' USING ERRCODE = '22023';
  END IF;
  IF jsonb_typeof(v_warnings) <> 'array' THEN
    RAISE EXCEPTION 'pmg_build_result: warnings must be a JSON array' USING ERRCODE = '22023';
  END IF;
  IF jsonb_typeof(v_confirmations) <> 'array' THEN
    RAISE EXCEPTION 'pmg_build_result: confirmations must be a JSON array' USING ERRCODE = '22023';
  END IF;
  IF _conflict IS NOT NULL AND jsonb_typeof(_conflict) <> 'object' THEN
    RAISE EXCEPTION 'pmg_build_result: conflict must be null or a JSON object' USING ERRCODE = '22023';
  END IF;

  RETURN jsonb_build_object(
    'status',        _status::text,
    'command',       _command,
    'target_type',   _target_type,
    'target_id',     _target_id,
    'project_id',    _project_id,
    'data',          v_data,
    'changes',       v_changes,
    'warnings',      v_warnings,
    'confirmations', v_confirmations,
    'conflict',      _conflict
  );
END; $function$

CREATE OR REPLACE FUNCTION public.prepare_kpi_app_report_now_select(_mapping_id uuid, _reporting_period_start date, _reporting_period_end date)
 RETURNS json
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _m record;
  _kdef record;
  _ext record;
  _snap record;
  _carry_used boolean := false;
  _reportable boolean := false;
  _reason text := NULL;
  _snapshot_creator_email text := NULL;
BEGIN
  IF NOT is_active_user(auth.uid()) THEN
    RAISE EXCEPTION 'Account is deactivated';
  END IF;

  IF _reporting_period_end < _reporting_period_start THEN
    RAISE EXCEPTION 'reporting_period_end < reporting_period_start';
  END IF;

  SELECT * INTO _m FROM public.kpi_app_mappings WHERE id = _mapping_id;
  IF _m.id IS NULL THEN
    RAISE EXCEPTION 'Mapping not found';
  END IF;

  IF NOT (is_org_admin(auth.uid(), _m.organization_id)
          OR is_workspace_admin_or_higher(auth.uid(), _m.workspace_id)) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  IF NOT _m.is_active THEN
    RETURN json_build_object('reportable', false, 'reason', 'mapping_inactive');
  END IF;

  SELECT * INTO _kdef FROM public.kpi_definitions WHERE id = _m.kpi_definition_id;
  IF _kdef.id IS NULL THEN
    RETURN json_build_object('reportable', false, 'reason', 'kpi_definition_missing');
  END IF;
  IF _kdef.is_archived THEN
    RETURN json_build_object('reportable', false, 'reason', 'kpi_definition_archived');
  END IF;
  IF _kdef.organization_id <> _m.organization_id
     OR _kdef.workspace_id <> _m.workspace_id
     OR _kdef.target_type <> 'project'
     OR _kdef.target_id <> _m.project_id THEN
    RETURN json_build_object('reportable', false, 'reason', 'mapping_kpi_scope_mismatch');
  END IF;
  IF _kdef.calculation_key = 'schedule_signal' THEN
    RETURN json_build_object('reportable', false, 'reason', 'schedule_signal_not_submittable');
  END IF;

  SELECT * INTO _ext
    FROM public.kpi_app_external_kpis
   WHERE organization_id = _m.organization_id
     AND external_kpi_id = _m.external_kpi_id;
  IF _ext.id IS NULL OR NOT _ext.is_active THEN
    RETURN json_build_object('reportable', false, 'reason', 'external_catalog_inactive');
  END IF;
  IF _ext.value_type <> _kdef.value_type THEN
    RETURN json_build_object('reportable', false, 'reason', 'value_type_mismatch');
  END IF;

  SELECT * INTO _snap
    FROM public.kpi_snapshots s
   WHERE s.kpi_definition_id = _m.kpi_definition_id
     AND s.organization_id = _m.organization_id
     AND s.project_id = _m.project_id
     AND s.value_type = _kdef.value_type
     AND s.period_start = _reporting_period_start
     AND s.period_end = _reporting_period_end
   ORDER BY s.created_at DESC
   LIMIT 1;

  IF _snap.id IS NOT NULL THEN
    _reportable := true;
    _carry_used := false;
  ELSIF _m.carry_forward_allowed THEN
    SELECT * INTO _snap
      FROM public.kpi_snapshots s
     WHERE s.kpi_definition_id = _m.kpi_definition_id
       AND s.organization_id = _m.organization_id
       AND s.project_id = _m.project_id
       AND s.value_type = _kdef.value_type
       AND s.period_end IS NOT NULL
       AND s.period_end <= _reporting_period_end
     ORDER BY s.period_end DESC, s.created_at DESC
     LIMIT 1;
    IF _snap.id IS NOT NULL THEN
      _reportable := true;
      _carry_used := true;
    ELSE
      _reason := 'no_snapshot_available';
    END IF;
  ELSE
    _reason := 'no_current_period_snapshot';
  END IF;

  IF _reportable AND _m.entered_by_email_source = 'snapshot_created_by' THEN
    SELECT p.email INTO _snapshot_creator_email
      FROM public.profiles p
     WHERE p.id = _snap.created_by;
    IF _snapshot_creator_email IS NULL OR btrim(_snapshot_creator_email) = '' THEN
      _reportable := false;
      _reason := 'snapshot_created_by_email_unavailable';
    END IF;
  END IF;

  IF NOT _reportable THEN
    RETURN json_build_object(
      'reportable', false,
      'reason', _reason,
      'carry_forward_allowed', _m.carry_forward_allowed,
      'mapping', json_build_object(
        'id', _m.id,
        'organization_id', _m.organization_id,
        'workspace_id', _m.workspace_id,
        'project_id', _m.project_id,
        'kpi_definition_id', _m.kpi_definition_id,
        'external_kpi_id', _m.external_kpi_id,
        'scenario_id', _m.scenario_id,
        'currency_id', _m.currency_id,
        'reporting_frequency', _m.reporting_frequency,
        'is_active', _m.is_active,
        'carry_forward_allowed', _m.carry_forward_allowed
      ),
      'external_kpi', json_build_object(
        'external_kpi_id', _ext.external_kpi_id,
        'external_kpi_name', _ext.external_kpi_name,
        'value_type', _ext.value_type
      )
    );
  END IF;

  RETURN json_build_object(
    'reportable', true,
    'carry_forward_used', _carry_used,
    'mapping', json_build_object(
      'id', _m.id,
      'organization_id', _m.organization_id,
      'workspace_id', _m.workspace_id,
      'project_id', _m.project_id,
      'kpi_definition_id', _m.kpi_definition_id,
      'external_kpi_id', _m.external_kpi_id,
      'scenario_id', _m.scenario_id,
      'currency_id', _m.currency_id,
      'reporting_frequency', _m.reporting_frequency,
      'is_active', _m.is_active,
      'carry_forward_allowed', _m.carry_forward_allowed
    ),
    'external_kpi', json_build_object(
      'external_kpi_id', _ext.external_kpi_id,
      'external_kpi_name', _ext.external_kpi_name,
      'value_type', _ext.value_type
    ),
    'snapshot', json_build_object(
      'id', _snap.id,
      'period_start', _snap.period_start,
      'period_end', _snap.period_end,
      'value_type', _snap.value_type,
      'value_amount', _snap.value_amount,
      'text_value_present', (_snap.string_value IS NOT NULL AND length(_snap.string_value) > 0),
      'comment_present', (_snap.comment IS NOT NULL AND length(_snap.comment) > 0),
      'action_plan_present', (_snap.action_plan IS NOT NULL AND length(_snap.action_plan) > 0)
    )
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.preview_adoption_template(_workspace_id uuid, _template_id uuid DEFAULT NULL::uuid, _template_key text DEFAULT 'btpm_standard_adoption'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _org uuid;
  _t record;
  _initiatives jsonb := '[]'::jsonb;
  _i record;
  _tasks jsonb;
BEGIN
  IF _uid IS NULL OR NOT public.is_active_user(_uid) THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;
  SELECT organization_id INTO _org FROM public.workspaces WHERE id = _workspace_id;
  IF _org IS NULL THEN
    RAISE EXCEPTION 'invalid_workspace';
  END IF;
  IF NOT (public.is_workspace_member(_uid, _workspace_id)
          OR public.is_org_admin(_uid, _org)) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  -- Standard template
  IF _template_id IS NULL THEN
    IF COALESCE(_template_key, '') <> 'btpm_standard_adoption' THEN
      RAISE EXCEPTION 'invalid_template_key';
    END IF;
    SELECT jsonb_agg(
      jsonb_build_object(
        'key', i->>'key',
        'name', i->>'name',
        'readiness_area', i->>'readiness_area',
        'sort_order', (i->>'sort_order')::int,
        'summary', i->>'summary',
        'default_selected', true,
        'tasks', (
          SELECT jsonb_agg(jsonb_build_object(
            'key', t->>'key',
            'title', t->>'title',
            'description', NULL,
            'default_selected', true,
            'is_custom', false
          ))
          FROM jsonb_array_elements(i->'tasks') AS t
        )
      )
    ) INTO _initiatives FROM jsonb_array_elements(public._btpm_adoption_template_v1()) AS i;

    RETURN jsonb_build_object(
      'template_id', NULL,
      'template_key', 'btpm_standard_adoption',
      'name', 'BTPM Standard Adoption Plan',
      'description', 'The built-in BTPM adoption template.',
      'is_system', true,
      'editable', false,
      'scope', 'system',
      'source_template_key', NULL,
      'initiatives', COALESCE(_initiatives, '[]'::jsonb)
    );
  END IF;

  -- Saved custom template
  SELECT * INTO _t FROM public.adoption_templates WHERE id = _template_id;
  IF _t.id IS NULL THEN
    RAISE EXCEPTION 'invalid_template';
  END IF;
  IF _t.workspace_id <> _workspace_id THEN
    RAISE EXCEPTION 'template_workspace_mismatch';
  END IF;
  IF NOT (public.is_workspace_member(_uid, _t.workspace_id)
          OR public.is_org_admin(_uid, _t.organization_id)) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  SELECT jsonb_agg(
    jsonb_build_object(
      'key', i.template_key,
      'name', public.btpm_decrypt(i.name, i.organization_id),
      'readiness_area', i.readiness_area,
      'sort_order', i.sort_order,
      'summary', public.btpm_decrypt(i.summary, i.organization_id),
      'default_selected', i.default_selected,
      'tasks', COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
          'key', tk.template_key,
          'title', public.btpm_decrypt(tk.title, tk.organization_id),
          'description', public.btpm_decrypt(tk.description, tk.organization_id),
          'default_selected', tk.default_selected,
          'is_custom', tk.is_custom
        ) ORDER BY tk.sort_order, tk.template_key)
        FROM public.adoption_template_tasks tk
        WHERE tk.adoption_template_initiative_id = i.id
          AND tk.is_archived = false
      ), '[]'::jsonb)
    ) ORDER BY i.sort_order, i.template_key
  ) INTO _initiatives
  FROM public.adoption_template_initiatives i
  WHERE i.adoption_template_id = _t.id AND i.is_archived = false;

  RETURN jsonb_build_object(
    'template_id', _t.id,
    'template_key', NULL,
    'name', public.btpm_decrypt(_t.name, _t.organization_id),
    'description', public.btpm_decrypt(_t.description, _t.organization_id),
    'is_system', false,
    'editable', true,
    'scope', _t.scope,
    'source_template_key', _t.source_template_key,
    'initiatives', COALESCE(_initiatives, '[]'::jsonb)
  );
END $function$

CREATE OR REPLACE FUNCTION public.preview_phase_clone_blueprint(_phase_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _phase public.phases%ROWTYPE;
  _org uuid;
  _ws  uuid;
  _proj uuid;
  _anchor date;
  _schedule_mode text;
  _anchor_source text;

  _phase_obj jsonb;
  _tasks jsonb;
  _deps jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'authentication required';
  END IF;

  SELECT * INTO _phase FROM public.phases WHERE id = _phase_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'phase not found';
  END IF;

  _org  := _phase.organization_id;
  _ws   := _phase.workspace_id;
  _proj := _phase.project_id;

  IF NOT public.has_pm_authority(auth.uid(), _ws) THEN
    RAISE EXCEPTION 'PM authority required for phase clone blueprint';
  END IF;

  _anchor := public._clone_anchor_for_phase(_phase_id);
  IF _anchor IS NULL THEN
    _schedule_mode := 'unscheduled';
    _anchor_source := NULL;
  ELSIF _phase.start_date IS NOT NULL THEN
    _schedule_mode := 'relative';
    _anchor_source := 'phase_start_date';
  ELSE
    _schedule_mode := 'relative';
    _anchor_source := 'earliest_planning_date';
  END IF;

  _phase_obj := jsonb_build_object(
    'name', public.btpm_decrypt(_phase.name, _org),
    'description', public.btpm_decrypt(_phase.description, _org),
    'phase_type', _phase.phase_type,
    'sort_order_provenance', _phase.sort_order,
    'schedule', jsonb_build_object(
      'start_offset_days',      public._clone_offset_days(_anchor, _phase.start_date),
      'target_end_offset_days', public._clone_offset_days(_anchor, _phase.target_end_date)
    )
  );

  -- Tasks within this phase
  WITH tk AS (
    SELECT 'task_' || ROW_NUMBER() OVER (ORDER BY t.sort_order, t.created_at) AS ref, t.*
    FROM public.tasks t
    WHERE t.phase_id = _phase_id AND t.is_archived = false
  )
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'ref', ref,
    'source_id', id,
    'phase_ref', 'phase_1',
    'name', public.btpm_decrypt(name, _org),
    'description', public.btpm_decrypt(description, _org),
    'task_type', task_type,
    'priority', priority,
    'estimated_hours', estimated_hours,
    'sort_order', sort_order,
    'backlog_item_provenance_id', backlog_item_id,
    'schedule', jsonb_build_object(
      'start_offset_days', public._clone_offset_days(_anchor, start_date),
      'due_offset_days',   public._clone_offset_days(_anchor, due_date)
    )
  ) ORDER BY sort_order), '[]'::jsonb) INTO _tasks FROM tk;

  -- Internal task-to-task dependencies only — both ends inside this phase
  WITH tk AS (
    SELECT 'task_' || ROW_NUMBER() OVER (ORDER BY t.sort_order, t.created_at) AS ref, t.id
    FROM public.tasks t
    WHERE t.phase_id = _phase_id AND t.is_archived = false
  )
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'entity_type', 'task',
    'source_ref', src.ref,
    'target_ref', tgt.ref,
    'dependency_type', d.dependency_type,
    'description', public.btpm_decrypt(d.description, _org)
  )), '[]'::jsonb) INTO _deps
  FROM public.dependencies d
  JOIN tk src ON d.source_type = 'task' AND d.source_id = src.id
  JOIN tk tgt ON d.target_type = 'task' AND d.target_id = tgt.id;

  RETURN jsonb_build_object(
    'version', 'clone_blueprint_v1',
    'blueprint_kind', 'phase',
    'saved_at', to_jsonb(now()),
    'schedule_mode', _schedule_mode,
    'anchor_source', _anchor_source,
    'anchor_date', _anchor,
    'source', jsonb_build_object(
      'organization_id', _org,
      'workspace_id', _ws,
      'project_id', _proj,
      'phase_id', _phase_id
    ),
    'project', NULL,
    'phase', _phase_obj,
    'phases', jsonb_build_array(jsonb_build_object('ref','phase_1') || _phase_obj),
    'tasks',  _tasks,
    'dependencies', _deps,
    'kpi_definitions', '[]'::jsonb,
    'agile', jsonb_build_object(
      'enabled', false,
      'workflow_states', '[]'::jsonb,
      'sprints', '[]'::jsonb,
      'backlog_items', '[]'::jsonb
    )
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.preview_phase_clone_in_project(_phase_id uuid, _phase_start_date date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _caller uuid := auth.uid();
  _bp jsonb;
  _src_phase RECORD;
  _proj RECORD;
  _tk jsonb;
  _start_off int; _due_off int; _end_off int;
  _new_phase_start date; _new_phase_end date;
  _eff_start date; _eff_end date;
  _reasons jsonb := '[]'::jsonb;
  _requires boolean := false;
BEGIN
  IF _caller IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;

  SELECT id, project_id, workspace_id, organization_id, name
    INTO _src_phase
  FROM public.phases WHERE id = _phase_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Phase not found'; END IF;

  IF NOT public.has_pm_authority(_caller, _src_phase.workspace_id) THEN
    RAISE EXCEPTION 'PM authority required';
  END IF;

  SELECT id, name, start_date, target_end_date
    INTO _proj
  FROM public.projects WHERE id = _src_phase.project_id;

  _bp := public.preview_phase_clone_blueprint(_phase_id);

  IF _phase_start_date IS NULL OR (_bp->>'schedule_mode') <> 'relative' THEN
    RETURN jsonb_build_object(
      'requires_widening', false,
      'schedule_mode_applied',
        CASE WHEN _phase_start_date IS NULL THEN 'unscheduled_seeded_start_only'
             ELSE 'unscheduled_seeded_start_only' END,
      'parent_project_id', _proj.id,
      'parent_project_name', _proj.name,
      'parent_current_start', _proj.start_date,
      'parent_current_end', _proj.target_end_date,
      'parent_proposed_start', _proj.start_date,
      'parent_proposed_end', _proj.target_end_date
    );
  END IF;

  -- Compute new phase + task window from blueprint offsets and _phase_start_date
  _start_off := NULLIF(_bp->'phase'->'schedule'->>'start_offset_days','')::int;
  _end_off   := NULLIF(_bp->'phase'->'schedule'->>'target_end_offset_days','')::int;
  _new_phase_start := CASE WHEN _start_off IS NOT NULL THEN _phase_start_date + _start_off ELSE _phase_start_date END;
  _new_phase_end   := CASE WHEN _end_off   IS NOT NULL THEN _phase_start_date + _end_off   ELSE NULL END;

  _eff_start := _new_phase_start;
  _eff_end := _new_phase_end;

  FOR _tk IN SELECT * FROM jsonb_array_elements(COALESCE(_bp->'tasks','[]'::jsonb)) LOOP
    _start_off := NULLIF(_tk->'schedule'->>'start_offset_days','')::int;
    _due_off   := NULLIF(_tk->'schedule'->>'due_offset_days','')::int;
    IF _start_off IS NOT NULL THEN
      IF _eff_start IS NULL OR (_phase_start_date + _start_off) < _eff_start THEN
        _eff_start := _phase_start_date + _start_off;
      END IF;
    END IF;
    IF _due_off IS NOT NULL THEN
      IF _eff_end IS NULL OR (_phase_start_date + _due_off) > _eff_end THEN
        _eff_end := _phase_start_date + _due_off;
      END IF;
    END IF;
  END LOOP;

  -- Compare against parent project window
  IF _proj.start_date IS NOT NULL AND _eff_start IS NOT NULL AND _eff_start < _proj.start_date THEN
    _requires := true;
    _reasons := _reasons || jsonb_build_object('kind','phase_before_project','date', _eff_start);
  END IF;
  IF _proj.target_end_date IS NOT NULL AND _eff_end IS NOT NULL AND _eff_end > _proj.target_end_date THEN
    _requires := true;
    _reasons := _reasons || jsonb_build_object('kind','phase_after_project','date', _eff_end);
  END IF;

  RETURN jsonb_build_object(
    'requires_widening', _requires,
    'schedule_mode_applied','relative_reanchored',
    'parent_project_id', _proj.id,
    'parent_project_name', _proj.name,
    'parent_current_start', _proj.start_date,
    'parent_current_end', _proj.target_end_date,
    'parent_proposed_start',
        CASE WHEN _eff_start IS NOT NULL AND (_proj.start_date IS NULL OR _eff_start < _proj.start_date)
             THEN _eff_start ELSE _proj.start_date END,
    'parent_proposed_end',
        CASE WHEN _eff_end IS NOT NULL AND (_proj.target_end_date IS NULL OR _eff_end > _proj.target_end_date)
             THEN _eff_end ELSE _proj.target_end_date END,
    'phase_proposed_start', _new_phase_start,
    'phase_proposed_end', _new_phase_end,
    'reasons', _reasons
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.preview_phase_planning_change(_phase_id uuid, _new_start date, _new_end date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  ph record;
  pr record;
  bad_child record;
  needs_ext boolean := false;
  proposed_start date;
  proposed_end   date;
BEGIN
  SELECT id, project_id, workspace_id, status, is_archived, start_date, target_end_date, name
    INTO ph
    FROM public.phases
   WHERE id = _phase_id;

  IF ph.id IS NULL THEN
    RETURN jsonb_build_object('blocked', true, 'blocked_reason', 'phase_not_found');
  END IF;

  IF NOT public.is_workspace_admin_or_higher(auth.uid(), ph.workspace_id) THEN
    RETURN jsonb_build_object('blocked', true, 'blocked_reason', 'not_authorized');
  END IF;

  IF ph.status = 'completed' THEN
    RETURN jsonb_build_object('blocked', true, 'blocked_reason', 'phase_completed_locked');
  END IF;
  IF ph.status = 'cancelled' OR ph.is_archived THEN
    RETURN jsonb_build_object('blocked', true, 'blocked_reason', 'phase_cancelled_or_archived');
  END IF;

  IF _new_start IS NOT NULL AND _new_end IS NOT NULL AND _new_end < _new_start THEN
    RETURN jsonb_build_object('blocked', true, 'blocked_reason', 'invalid_range');
  END IF;

  -- Cannot shrink under existing children
  SELECT name, start_date AS d INTO bad_child
    FROM public.tasks
   WHERE phase_id = ph.id
     AND status <> 'cancelled' AND NOT is_archived
     AND start_date IS NOT NULL
     AND _new_start IS NOT NULL
     AND start_date < _new_start
   ORDER BY start_date ASC LIMIT 1;
  IF bad_child.name IS NOT NULL THEN
    RETURN jsonb_build_object('blocked', true,
      'blocked_reason', format('phase_shrinks_under_child_start:%s:%s', bad_child.name, bad_child.d));
  END IF;

  SELECT name, due_date AS d INTO bad_child
    FROM public.tasks
   WHERE phase_id = ph.id
     AND status <> 'cancelled' AND NOT is_archived
     AND due_date IS NOT NULL
     AND _new_end IS NOT NULL
     AND due_date > _new_end
   ORDER BY due_date DESC LIMIT 1;
  IF bad_child.name IS NOT NULL THEN
    RETURN jsonb_build_object('blocked', true,
      'blocked_reason', format('phase_shrinks_under_child_end:%s:%s', bad_child.name, bad_child.d));
  END IF;

  -- Project containment
  SELECT id, name, start_date, target_end_date
    INTO pr
    FROM public.projects
   WHERE id = ph.project_id;

  IF pr.id IS NULL THEN
    RETURN jsonb_build_object('blocked', true, 'blocked_reason', 'project_not_found');
  END IF;

  proposed_start := pr.start_date;
  proposed_end   := pr.target_end_date;

  IF _new_start IS NOT NULL AND pr.start_date IS NOT NULL AND _new_start < pr.start_date THEN
    needs_ext := true; proposed_start := _new_start;
  END IF;
  IF _new_end IS NOT NULL AND pr.target_end_date IS NOT NULL AND _new_end > pr.target_end_date THEN
    needs_ext := true; proposed_end := _new_end;
  END IF;

  RETURN jsonb_build_object(
    'valid', NOT needs_ext,
    'requires_extension', needs_ext,
    'blocked', false,
    'blocked_reason', NULL,
    'parent_project_id', pr.id,
    'parent_project_name', pr.name,
    'parent_current_start', pr.start_date,
    'parent_current_end',   pr.target_end_date,
    'parent_proposed_start', proposed_start,
    'parent_proposed_end',   proposed_end
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.preview_phase_timeline_action(_phase_id uuid, _action text, _new_start date, _new_end date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_phase   public.phases%ROWTYPE;
  v_project public.projects%ROWTYPE;
  v_uid     uuid := auth.uid();

  v_delta_days   int;
  v_executed_cnt int := 0;
  v_active_cnt   int := 0;
  v_movable_cnt  int := 0;

  v_resolved_action text;
  v_proposed_start  date := _new_start;
  v_proposed_end    date := _new_end;

  v_proj_proposed_start date;
  v_proj_proposed_end   date;
  v_requires_proj_ext   boolean := false;

  v_anchor_min_start date;
  v_anchor_max_end   date;

  v_blocking_child_name text;
  v_blocking_child_date date;
BEGIN
  SELECT * INTO v_phase FROM public.phases WHERE id = _phase_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('valid', false, 'blocked', true, 'blocked_reason', 'phase_not_found');
  END IF;

  SELECT * INTO v_project FROM public.projects WHERE id = v_phase.project_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('valid', false, 'blocked', true, 'blocked_reason', 'project_not_found');
  END IF;

  -- Authorization: PM/workspace-admin or higher.
  IF NOT public.is_workspace_admin_or_higher(v_uid, v_phase.workspace_id)
     AND NOT public.has_pm_authority(v_uid, v_phase.workspace_id) THEN
    RETURN jsonb_build_object('valid', false, 'blocked', true, 'blocked_reason', 'not_authorized');
  END IF;

  -- Lifecycle guards (mirror 4F.2).
  IF v_phase.is_archived OR v_phase.status = 'cancelled' THEN
    RETURN jsonb_build_object('valid', false, 'blocked', true, 'blocked_reason', 'phase_cancelled_or_archived');
  END IF;
  IF v_phase.status = 'completed' THEN
    RETURN jsonb_build_object('valid', false, 'blocked', true, 'blocked_reason', 'phase_completed_locked');
  END IF;

  IF _new_start IS NULL OR _new_end IS NULL OR _new_end < _new_start THEN
    RETURN jsonb_build_object('valid', false, 'blocked', true, 'blocked_reason', 'invalid_range');
  END IF;

  -- Count executed/active/movable children (eligible = not archived, not cancelled).
  SELECT
    COUNT(*) FILTER (WHERE actual_start_date IS NOT NULL),
    COUNT(*) FILTER (WHERE status = 'completed' OR actual_end_date IS NOT NULL),
    COUNT(*) FILTER (WHERE actual_start_date IS NULL AND actual_end_date IS NULL
                       AND status <> 'completed')
  INTO v_executed_cnt, v_active_cnt, v_movable_cnt
  FROM public.tasks
  WHERE phase_id = _phase_id
    AND is_archived = false
    AND status <> 'cancelled';

  -- Anchored window across executed/completed children (used for resize floor).
  SELECT
    MIN(COALESCE(actual_start_date, start_date)),
    MAX(COALESCE(actual_end_date, due_date))
  INTO v_anchor_min_start, v_anchor_max_end
  FROM public.tasks
  WHERE phase_id = _phase_id
    AND is_archived = false
    AND status <> 'cancelled'
    AND (actual_start_date IS NOT NULL OR status = 'completed');

  IF _action = 'drag' THEN
    v_delta_days := (_new_start - v_phase.start_date);

    IF v_executed_cnt > 0 THEN
      -- Shift remaining work: only not-started movable children shift.
      v_resolved_action := 'shift_remaining_work';

      -- Recompute phase window so it contains BOTH anchored work and shifted
      -- not-started work. We use the proposed delta on the not-started children.
      SELECT
        LEAST(
          COALESCE(MIN(start_date) + v_delta_days, _new_start),
          COALESCE(v_anchor_min_start, _new_start)
        ),
        GREATEST(
          COALESCE(MAX(due_date)   + v_delta_days, _new_end),
          COALESCE(v_anchor_max_end, _new_end)
        )
      INTO v_proposed_start, v_proposed_end
      FROM public.tasks
      WHERE phase_id = _phase_id
        AND is_archived = false
        AND status <> 'cancelled'
        AND actual_start_date IS NULL
        AND actual_end_date IS NULL
        AND status <> 'completed'
        AND start_date IS NOT NULL
        AND due_date   IS NOT NULL;

      IF v_proposed_start IS NULL THEN v_proposed_start := _new_start; END IF;
      IF v_proposed_end   IS NULL THEN v_proposed_end   := _new_end;   END IF;

    ELSE
      v_resolved_action := 'move_phase_plan';
      v_proposed_start := _new_start;
      v_proposed_end   := _new_end;
    END IF;

  ELSIF _action = 'resize' THEN
    v_resolved_action := 'resize_phase';
    v_proposed_start := _new_start;
    v_proposed_end   := _new_end;

    -- Shrinking under anchored or active planned child work is blocked.
    -- Check anchored floor.
    IF v_anchor_min_start IS NOT NULL AND _new_start > v_anchor_min_start THEN
      v_blocking_child_name := 'anchored work';
      v_blocking_child_date := v_anchor_min_start;
      RETURN jsonb_build_object(
        'valid', false, 'blocked', true,
        'blocked_reason', 'phase_shrinks_under_child_start:' || v_blocking_child_name || ':' || v_blocking_child_date::text,
        'has_executed_children', v_executed_cnt > 0
      );
    END IF;
    IF v_anchor_max_end IS NOT NULL AND _new_end < v_anchor_max_end THEN
      v_blocking_child_name := 'anchored work';
      v_blocking_child_date := v_anchor_max_end;
      RETURN jsonb_build_object(
        'valid', false, 'blocked', true,
        'blocked_reason', 'phase_shrinks_under_child_end:' || v_blocking_child_name || ':' || v_blocking_child_date::text,
        'has_executed_children', v_executed_cnt > 0
      );
    END IF;

    -- Check planned floor (any not-cancelled child).
    SELECT name, start_date INTO v_blocking_child_name, v_blocking_child_date
    FROM public.tasks
    WHERE phase_id = _phase_id
      AND is_archived = false
      AND status <> 'cancelled'
      AND start_date IS NOT NULL
      AND start_date < _new_start
    ORDER BY start_date ASC LIMIT 1;
    IF FOUND THEN
      RETURN jsonb_build_object(
        'valid', false, 'blocked', true,
        'blocked_reason', 'phase_shrinks_under_child_start:' || v_blocking_child_name || ':' || v_blocking_child_date::text,
        'has_executed_children', v_executed_cnt > 0
      );
    END IF;
    SELECT name, due_date INTO v_blocking_child_name, v_blocking_child_date
    FROM public.tasks
    WHERE phase_id = _phase_id
      AND is_archived = false
      AND status <> 'cancelled'
      AND due_date IS NOT NULL
      AND due_date > _new_end
    ORDER BY due_date DESC LIMIT 1;
    IF FOUND THEN
      RETURN jsonb_build_object(
        'valid', false, 'blocked', true,
        'blocked_reason', 'phase_shrinks_under_child_end:' || v_blocking_child_name || ':' || v_blocking_child_date::text,
        'has_executed_children', v_executed_cnt > 0
      );
    END IF;
  ELSE
    RETURN jsonb_build_object('valid', false, 'blocked', true, 'blocked_reason', 'invalid_action');
  END IF;

  -- Project extension check.
  IF v_project.start_date IS NOT NULL AND v_proposed_start < v_project.start_date THEN
    v_requires_proj_ext := true;
    v_proj_proposed_start := v_proposed_start;
  ELSE
    v_proj_proposed_start := v_project.start_date;
  END IF;

  IF v_project.target_end_date IS NOT NULL AND v_proposed_end > v_project.target_end_date THEN
    v_requires_proj_ext := true;
    v_proj_proposed_end := v_proposed_end;
  ELSE
    v_proj_proposed_end := v_project.target_end_date;
  END IF;

  RETURN jsonb_build_object(
    'valid', true,
    'blocked', false,
    'blocked_reason', NULL,
    'resolved_action', v_resolved_action,
    'has_executed_children', v_executed_cnt > 0,
    'requires_project_extension', v_requires_proj_ext,
    'requires_extension', v_requires_proj_ext,
    'phase_id', v_phase.id,
    'phase_name', v_phase.name,
    'phase_current_start', v_phase.start_date,
    'phase_current_end',   v_phase.target_end_date,
    'phase_proposed_start', v_proposed_start,
    'phase_proposed_end',   v_proposed_end,
    'parent_project_id', v_project.id,
    'parent_project_name', v_project.name,
    'parent_current_start', v_project.start_date,
    'parent_current_end',   v_project.target_end_date,
    'parent_proposed_start', v_proj_proposed_start,
    'parent_proposed_end',   v_proj_proposed_end,
    'moved_children_count', CASE WHEN v_resolved_action = 'shift_remaining_work' THEN v_movable_cnt
                                 WHEN v_resolved_action = 'move_phase_plan' THEN v_movable_cnt + v_active_cnt
                                 ELSE 0 END,
    'anchored_children_count', v_executed_cnt,
    'delta_days', v_delta_days
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.preview_project_adoption_template(_project_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _proj_start date;
  _proj_end date;
  _sug_start date;
  _sug_end date;
  _date_source text := 'none';
  _initiatives jsonb;
  _enriched jsonb := '[]'::jsonb;
  _i jsonb;
  _task_count int := 0;
BEGIN
  IF _uid IS NULL OR NOT public.is_active_user(_uid) THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;
  SELECT start_date, target_end_date INTO _proj_start, _proj_end
  FROM public.projects WHERE id = _project_id;
  IF _proj_start IS NULL AND _proj_end IS NULL AND NOT EXISTS (
    SELECT 1 FROM public.projects WHERE id = _project_id
  ) THEN
    RAISE EXCEPTION 'invalid_project';
  END IF;
  IF NOT public.has_project_access(_uid, _project_id) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  -- Date suggestion: project > phases > tasks > none
  IF _proj_start IS NOT NULL OR _proj_end IS NOT NULL THEN
    _sug_start := _proj_start;
    _sug_end   := _proj_end;
    _date_source := 'project_dates';
  ELSE
    SELECT MIN(start_date), MAX(target_end_date)
      INTO _sug_start, _sug_end
    FROM public.phases
    WHERE project_id = _project_id AND is_archived = false;
    IF _sug_start IS NOT NULL OR _sug_end IS NOT NULL THEN
      _date_source := 'phase_dates';
    ELSE
      SELECT MIN(start_date), MAX(due_date)
        INTO _sug_start, _sug_end
      FROM public.tasks
      WHERE project_id = _project_id AND is_archived = false;
      IF _sug_start IS NOT NULL OR _sug_end IS NOT NULL THEN
        _date_source := 'task_dates';
      END IF;
    END IF;
  END IF;

  _initiatives := public._btpm_adoption_template_v1();

  FOR _i IN SELECT * FROM jsonb_array_elements(_initiatives)
  LOOP
    _enriched := _enriched || jsonb_build_array(
      jsonb_build_object(
        'key', _i->>'key',
        'name', _i->>'name',
        'readiness_area', _i->>'readiness_area',
        'sort_order', (_i->>'sort_order')::int,
        'summary', _i->>'summary',
        'default_selected', true,
        'tasks', (
          SELECT jsonb_agg(jsonb_build_object(
            'key', t->>'key',
            'title', t->>'title',
            'description', NULL,
            'default_selected', true
          ))
          FROM jsonb_array_elements(_i->'tasks') AS t
        )
      )
    );
    _task_count := _task_count + jsonb_array_length(_i->'tasks');
  END LOOP;

  RETURN jsonb_build_object(
    'project_id', _project_id,
    'template_key', 'btpm_standard_adoption',
    'template_name', 'BTPM Standard Adoption Plan',
    'recommended_phase_name', 'Adoption & Readiness',
    'creates_normal_phase', true,
    'creates_normal_tasks', true,
    'dates_auto_populated', _date_source <> 'none',
    'suggested_phase_start_date', _sug_start,
    'suggested_phase_end_date',   _sug_end,
    'date_source', _date_source,
    'initiative_count', jsonb_array_length(_enriched),
    'task_count', _task_count,
    'initiatives', _enriched
  );
END $function$

CREATE OR REPLACE FUNCTION public.preview_project_template_instantiation(_template_id uuid, _project_start_date date DEFAULT NULL::date, _program_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _caller uuid := auth.uid();
  _tpl RECORD;
  _payload_text text;
  _bp jsonb;
  _bp_kind text;
  _schedule_mode text;
  _eff jsonb;
BEGIN
  IF _caller IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  SELECT id, organization_id, workspace_id, source_project_id,
         blueprint_payload, blueprint_version, is_archived
    INTO _tpl
  FROM public.project_templates
  WHERE id = _template_id;

  IF NOT FOUND THEN RAISE EXCEPTION 'Template not found'; END IF;
  IF _tpl.is_archived THEN RAISE EXCEPTION 'Template is archived'; END IF;

  IF NOT public.has_pm_authority(_caller, _tpl.workspace_id) THEN
    RAISE EXCEPTION 'PM authority required in template workspace';
  END IF;

  IF _program_id IS NOT NULL THEN
    PERFORM 1 FROM public.programs
      WHERE id = _program_id
        AND organization_id = _tpl.organization_id
        AND workspace_id = _tpl.workspace_id
        AND is_archived = false;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Program not found in template workspace/organization';
    END IF;
  END IF;

  IF _tpl.blueprint_version <> 'clone_blueprint_v1' THEN
    RAISE EXCEPTION 'Unsupported blueprint version: %', _tpl.blueprint_version;
  END IF;

  _payload_text := public.btpm_decrypt(_tpl.blueprint_payload, _tpl.organization_id);
  _bp := _payload_text::jsonb;
  _bp_kind := _bp->>'blueprint_kind';
  _schedule_mode := COALESCE(_bp->>'schedule_mode', 'unscheduled');

  IF _bp_kind <> 'project' THEN
    RAISE EXCEPTION 'Stored blueprint is not a project blueprint (kind=%)', _bp_kind;
  END IF;

  IF _project_start_date IS NULL OR _schedule_mode <> 'relative' THEN
    -- Unscheduled apply path: nothing to widen
    RETURN jsonb_build_object(
      'requires_widening', false,
      'schedule_mode_applied',
        CASE WHEN _project_start_date IS NULL THEN 'unscheduled'
             ELSE 'unscheduled' END,
      'nominal_start', NULL, 'nominal_end', NULL,
      'effective_start', NULL, 'effective_end', NULL,
      'reasons', '[]'::jsonb
    );
  END IF;

  _eff := public._compute_project_effective_window(_bp, _project_start_date);

  RETURN _eff || jsonb_build_object(
    'schedule_mode_applied','relative_reanchored',
    'template_id', _template_id,
    'project_start_date_applied', _project_start_date
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.preview_task_clone_blueprint(_task_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _caller uuid;
  _task_row public.tasks%ROWTYPE;
  _phase_row public.phases%ROWTYPE;
  _phase_name text;
  _phase_desc text;
  _anchor date;
  _schedule_mode text;
  _anchor_source text;
  _result jsonb;
BEGIN
  _caller := auth.uid();
  IF _caller IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO _task_row FROM public.tasks WHERE id = _task_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Task % not found', _task_id USING ERRCODE = 'P0002';
  END IF;

  IF NOT public.has_pm_authority(_caller, _task_row.workspace_id) THEN
    RAISE EXCEPTION 'Access denied: PM authority required in workspace %', _task_row.workspace_id
      USING ERRCODE = '42501';
  END IF;

  SELECT * INTO _phase_row FROM public.phases WHERE id = _task_row.phase_id;

  -- Decrypt phase narrative for provenance
  BEGIN
    _phase_name := public.btpm_decrypt(_phase_row.name, _phase_row.organization_id);
  EXCEPTION WHEN OTHERS THEN
    _phase_name := _phase_row.name;
  END;
  BEGIN
    _phase_desc := public.btpm_decrypt(_phase_row.description, _phase_row.organization_id);
  EXCEPTION WHEN OTHERS THEN
    _phase_desc := _phase_row.description;
  END;

  -- Anchor resolution
  _anchor := public._clone_anchor_for_task(_task_id);
  IF _anchor IS NULL THEN
    _schedule_mode := 'unscheduled';
    _anchor_source := NULL;
  ELSE
    _schedule_mode := 'relative';
    IF _task_row.start_date IS NOT NULL THEN
      _anchor_source := 'task_start_date';
    ELSE
      _anchor_source := 'task_earliest_date';
    END IF;
  END IF;

  -- Decrypt task narrative
  DECLARE
    _task_name text;
    _task_desc text;
  BEGIN
    BEGIN
      _task_name := public.btpm_decrypt(_task_row.name, _task_row.organization_id);
    EXCEPTION WHEN OTHERS THEN
      _task_name := _task_row.name;
    END;
    BEGIN
      _task_desc := public.btpm_decrypt(_task_row.description, _task_row.organization_id);
    EXCEPTION WHEN OTHERS THEN
      _task_desc := _task_row.description;
    END;

    _result := jsonb_build_object(
      'version', 'clone_blueprint_v1',
      'blueprint_kind', 'task',
      'saved_at', to_jsonb(now()),
      'schedule_mode', _schedule_mode,
      'anchor_source', _anchor_source,
      'anchor_date', to_jsonb(_anchor),
      'source', jsonb_build_object(
        'organization_id', _task_row.organization_id,
        'workspace_id', _task_row.workspace_id,
        'project_id', _task_row.project_id,
        'phase_id', _task_row.phase_id,
        'task_id', _task_row.id
      ),
      'project', NULL,
      'phase', jsonb_build_object(
        'ref', 'phase_1',
        'source_id', _phase_row.id,
        'name', _phase_name,
        'description', _phase_desc
      ),
      'phases', '[]'::jsonb,
      'tasks', jsonb_build_array(
        jsonb_build_object(
          'ref', 'task_1',
          'source_id', _task_row.id,
          'phase_ref', 'phase_1',
          'name', _task_name,
          'description', _task_desc,
          'task_type', _task_row.task_type,
          'priority', _task_row.priority,
          'estimated_hours', _task_row.estimated_hours,
          'sort_order', _task_row.sort_order,
          'backlog_item_ref', NULL,
          'workflow_state_ref', NULL,
          'provenance', jsonb_build_object(
            'backlog_item_id', _task_row.backlog_item_id,
            'workflow_state_id', _task_row.workflow_state_id
          ),
          'schedule', CASE
            WHEN _schedule_mode = 'unscheduled' THEN jsonb_build_object(
              'start_offset_days', NULL,
              'due_offset_days', NULL
            )
            ELSE jsonb_build_object(
              'start_offset_days', public._clone_offset_days(_anchor, _task_row.start_date),
              'due_offset_days',   public._clone_offset_days(_anchor, _task_row.due_date)
            )
          END
        )
      ),
      'dependencies', '[]'::jsonb,
      'kpi_definitions', '[]'::jsonb,
      'agile', jsonb_build_object(
        'enabled', false,
        'workflow_states', '[]'::jsonb,
        'sprints', '[]'::jsonb,
        'backlog_items', '[]'::jsonb
      )
    );
  END;

  RETURN _result;
END;
$function$

CREATE OR REPLACE FUNCTION public.preview_task_clone_in_phase(_task_id uuid, _task_start_date date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _caller uuid := auth.uid();
  _src_task RECORD;
  _phase RECORD;
  _bp jsonb;
  _start_off int; _due_off int;
  _t_start date; _t_due date;
  _requires boolean := false;
  _reasons jsonb := '[]'::jsonb;
BEGIN
  IF _caller IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;

  SELECT * INTO _src_task FROM public.tasks WHERE id = _task_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Task not found'; END IF;

  IF NOT public.has_pm_authority(_caller, _src_task.workspace_id) THEN
    RAISE EXCEPTION 'PM authority required';
  END IF;

  SELECT id, name, start_date, target_end_date INTO _phase
    FROM public.phases WHERE id = _src_task.phase_id;

  _bp := public.preview_task_clone_blueprint(_task_id);

  IF _task_start_date IS NULL OR (_bp->>'schedule_mode') <> 'relative' THEN
    RETURN jsonb_build_object(
      'requires_widening', false,
      'schedule_mode_applied','unscheduled_preserved',
      'parent_phase_id', _phase.id,
      'parent_phase_name', _phase.name,
      'parent_current_start', _phase.start_date,
      'parent_current_end', _phase.target_end_date,
      'parent_proposed_start', _phase.start_date,
      'parent_proposed_end', _phase.target_end_date
    );
  END IF;

  _start_off := NULLIF(_bp->'task'->'schedule'->>'start_offset_days','')::int;
  _due_off   := NULLIF(_bp->'task'->'schedule'->>'due_offset_days','')::int;
  _t_start := CASE WHEN _start_off IS NOT NULL THEN _task_start_date + _start_off ELSE _task_start_date END;
  _t_due   := CASE WHEN _due_off   IS NOT NULL THEN _task_start_date + _due_off   ELSE NULL END;

  IF _phase.start_date IS NOT NULL AND _t_start IS NOT NULL AND _t_start < _phase.start_date THEN
    _requires := true;
    _reasons := _reasons || jsonb_build_object('kind','task_before_phase','date', _t_start);
  END IF;
  IF _phase.target_end_date IS NOT NULL AND _t_due IS NOT NULL AND _t_due > _phase.target_end_date THEN
    _requires := true;
    _reasons := _reasons || jsonb_build_object('kind','task_after_phase','date', _t_due);
  END IF;

  RETURN jsonb_build_object(
    'requires_widening', _requires,
    'schedule_mode_applied','relative_reanchored',
    'parent_phase_id', _phase.id,
    'parent_phase_name', _phase.name,
    'parent_current_start', _phase.start_date,
    'parent_current_end', _phase.target_end_date,
    'parent_proposed_start',
        CASE WHEN _t_start IS NOT NULL AND (_phase.start_date IS NULL OR _t_start < _phase.start_date)
             THEN _t_start ELSE _phase.start_date END,
    'parent_proposed_end',
        CASE WHEN _t_due IS NOT NULL AND (_phase.target_end_date IS NULL OR _t_due > _phase.target_end_date)
             THEN _t_due ELSE _phase.target_end_date END,
    'task_proposed_start', _t_start,
    'task_proposed_end', _t_due,
    'reasons', _reasons
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.preview_task_planning_change(_task_id uuid, _new_phase_id uuid, _new_start date, _new_due date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  t  record;
  ph record;
  ws_id uuid;
  needs_ext boolean := false;
  proposed_start date;
  proposed_end   date;
  blocked boolean := false;
  reason  text := NULL;
BEGIN
  SELECT id, phase_id, workspace_id, status, is_archived, start_date, due_date, name
    INTO t
    FROM public.tasks
   WHERE id = _task_id;

  IF t.id IS NULL THEN
    RETURN jsonb_build_object('blocked', true, 'blocked_reason', 'task_not_found');
  END IF;

  ws_id := t.workspace_id;
  IF NOT public.is_workspace_admin_or_higher(auth.uid(), ws_id) THEN
    RETURN jsonb_build_object('blocked', true, 'blocked_reason', 'not_authorized');
  END IF;

  -- Completed-item lock (4F.2)
  IF t.status = 'completed' THEN
    RETURN jsonb_build_object('blocked', true, 'blocked_reason', 'task_completed_locked');
  END IF;
  IF t.status = 'cancelled' OR t.is_archived THEN
    RETURN jsonb_build_object('blocked', true, 'blocked_reason', 'task_cancelled_or_archived');
  END IF;

  IF _new_start IS NOT NULL AND _new_due IS NOT NULL AND _new_due < _new_start THEN
    RETURN jsonb_build_object('blocked', true, 'blocked_reason', 'invalid_range');
  END IF;

  SELECT id, name, start_date, target_end_date, status, is_archived
    INTO ph
    FROM public.phases
   WHERE id = COALESCE(_new_phase_id, t.phase_id);

  IF ph.id IS NULL THEN
    RETURN jsonb_build_object('blocked', true, 'blocked_reason', 'phase_not_found');
  END IF;

  proposed_start := ph.start_date;
  proposed_end   := ph.target_end_date;

  IF _new_start IS NOT NULL AND ph.start_date IS NOT NULL AND _new_start < ph.start_date THEN
    needs_ext := true;
    proposed_start := _new_start;
  END IF;
  IF _new_due IS NOT NULL AND ph.target_end_date IS NOT NULL AND _new_due > ph.target_end_date THEN
    needs_ext := true;
    proposed_end := _new_due;
  END IF;

  RETURN jsonb_build_object(
    'valid', NOT needs_ext AND NOT blocked,
    'requires_extension', needs_ext,
    'blocked', blocked,
    'blocked_reason', reason,
    'parent_phase_id', ph.id,
    'parent_phase_name', ph.name,
    'parent_current_start', ph.start_date,
    'parent_current_end',   ph.target_end_date,
    'parent_proposed_start', proposed_start,
    'parent_proposed_end',   proposed_end
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.publish_roadmap_story_presentation_version(_story_pack_id uuid, _story_pack_version_id uuid, _presentation_blueprint_run_id uuid, _title text, _snapshot_json text, _source_limitations_json text, _source_mode text, _publish_warnings jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _pack public.roadmap_story_packs;
  _pack_version public.roadmap_story_pack_versions;
  _run public.roadmap_story_pack_presentation_runs;
  _presentation public.roadmap_story_presentations;
  _presentation_id uuid;
  _next_version integer;
  _new_version_id uuid;
  _title_final text;
  _pack_title_plain text;
  _title_enc text;
  _snapshot_enc text;
  _limitations_enc text;
  _effective_pack_version_id uuid;
  _snapshot_scope_used boolean := false;
  _scope_config_fallback_used boolean := false;
  _source_snap_json text;
  _source_snap jsonb;
  _sources jsonb;
  _cat_key text;
  _cat_val jsonb;
  _cat_items jsonb;
  _row jsonb;
  _pid uuid;
  _wid uuid;
  _pid_text text;
  _wid_text text;
  _candidates jsonb := '[]'::jsonb;
  _captured jsonb;
  _captured_project_ids uuid[];
  _captured_workspace_ids uuid[];
  _candidate_ids uuid[];
  _proj record;
  _accepted_count integer := 0;
  _skipped_no_access integer := 0;
  _skipped_org_mismatch integer := 0;
  _skipped_invalid integer := 0;
  _warnings jsonb := COALESCE(_publish_warnings, '[]'::jsonb);
BEGIN
  IF _uid IS NULL OR NOT public.is_active_user(_uid) THEN
    RAISE EXCEPTION 'unauthorized' USING ERRCODE = '42501';
  END IF;

  IF _source_mode IS NULL OR _source_mode NOT IN ('ai_blueprint','deterministic') THEN
    RAISE EXCEPTION 'invalid_source_mode' USING ERRCODE = '22023';
  END IF;

  IF _snapshot_json IS NULL OR length(_snapshot_json) = 0 THEN
    RAISE EXCEPTION 'invalid_snapshot' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO _pack FROM public.roadmap_story_packs WHERE id = _story_pack_id;
  IF NOT FOUND OR _pack.created_by <> _uid THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF _pack.status = 'archived' THEN
    RAISE EXCEPTION 'story_pack_archived' USING ERRCODE = '22023';
  END IF;

  IF _presentation_blueprint_run_id IS NOT NULL THEN
    SELECT * INTO _run FROM public.roadmap_story_pack_presentation_runs
     WHERE id = _presentation_blueprint_run_id;
    IF NOT FOUND
       OR _run.story_pack_id <> _story_pack_id
       OR _run.status <> 'succeeded'
       OR COALESCE(_run.is_valid, false) = false THEN
      RAISE EXCEPTION 'invalid_presentation_blueprint_run' USING ERRCODE = '22023';
    END IF;
  END IF;

  IF _story_pack_version_id IS NOT NULL THEN
    _effective_pack_version_id := _story_pack_version_id;
    IF _run.id IS NOT NULL
       AND _run.story_pack_version_id IS NOT NULL
       AND _run.story_pack_version_id <> _story_pack_version_id THEN
      RAISE EXCEPTION 'inconsistent_story_pack_version_run' USING ERRCODE = '22023';
    END IF;
  ELSIF _run.id IS NOT NULL THEN
    _effective_pack_version_id := _run.story_pack_version_id;
  END IF;

  IF _effective_pack_version_id IS NOT NULL THEN
    SELECT * INTO _pack_version FROM public.roadmap_story_pack_versions
     WHERE id = _effective_pack_version_id;
    IF NOT FOUND OR _pack_version.story_pack_id <> _story_pack_id THEN
      RAISE EXCEPTION 'invalid_story_pack_version' USING ERRCODE = '22023';
    END IF;
  END IF;

  -- Title: prefer explicit request, then decrypted pack title, then default.
  BEGIN
    _pack_title_plain := CASE
      WHEN _pack.title_encrypted IS NULL THEN NULL
      ELSE public.btpm_decrypt(_pack.title_encrypted, _pack.organization_id)
    END;
  EXCEPTION WHEN others THEN
    _pack_title_plain := NULL;
  END;
  _title_final := COALESCE(
    NULLIF(btrim(_title), ''),
    NULLIF(btrim(_pack_title_plain), ''),
    'Roadmap Story'
  );
  IF length(_title_final) > 300 THEN
    _title_final := left(_title_final, 300);
  END IF;

  IF _pack_version.id IS NOT NULL
     AND _pack_version.source_snapshot_encrypted IS NOT NULL THEN
    BEGIN
      _source_snap_json := public.btpm_decrypt(
        _pack_version.source_snapshot_encrypted, _pack.organization_id
      );
      IF _source_snap_json IS NOT NULL AND length(_source_snap_json) > 0 THEN
        BEGIN
          _source_snap := _source_snap_json::jsonb;
        EXCEPTION WHEN others THEN
          _source_snap := NULL;
        END;
      END IF;
    EXCEPTION WHEN others THEN
      _source_snap := NULL;
    END;

    IF _source_snap IS NOT NULL THEN
      _sources := _source_snap -> 'sources';
      IF _sources IS NOT NULL AND jsonb_typeof(_sources) = 'object' THEN
        FOR _cat_key, _cat_val IN SELECT * FROM jsonb_each(_sources) LOOP
          _cat_items := _cat_val -> 'items';
          IF _cat_items IS NULL OR jsonb_typeof(_cat_items) <> 'array' THEN
            CONTINUE;
          END IF;
          FOR _row IN SELECT * FROM jsonb_array_elements(_cat_items) LOOP
            _pid_text := COALESCE(
              _row ->> 'project_id',
              _row ->> 'projectId',
              (_row -> 'project') ->> 'id'
            );
            _wid_text := COALESCE(
              _row ->> 'workspace_id',
              _row ->> 'workspaceId',
              (_row -> 'workspace') ->> 'id'
            );
            BEGIN
              _pid := _pid_text::uuid;
            EXCEPTION WHEN others THEN
              _pid := NULL;
            END;
            BEGIN
              _wid := _wid_text::uuid;
            EXCEPTION WHEN others THEN
              _wid := NULL;
            END;
            IF _pid IS NOT NULL THEN
              _candidates := _candidates || jsonb_build_object(
                'project_id', _pid,
                'workspace_id', _wid
              );
            END IF;
          END LOOP;
        END LOOP;
      END IF;

      IF jsonb_array_length(_candidates) > 0 THEN
        SELECT COALESCE(array_agg(DISTINCT (v ->> 'project_id')::uuid), ARRAY[]::uuid[])
          INTO _candidate_ids
          FROM jsonb_array_elements(_candidates) v;
        _snapshot_scope_used := true;
      END IF;
    END IF;
  END IF;

  IF _candidate_ids IS NULL OR array_length(_candidate_ids, 1) IS NULL THEN
    _captured := COALESCE(_pack.scope_config, '{}'::jsonb) -> 'roadmap_filters';
    IF _captured IS NOT NULL THEN
      SELECT COALESCE(array_agg((v)::uuid), ARRAY[]::uuid[])
        INTO _captured_project_ids
        FROM jsonb_array_elements_text(COALESCE(_captured -> 'project_ids', '[]'::jsonb)) v;
      SELECT COALESCE(array_agg((v)::uuid), ARRAY[]::uuid[])
        INTO _captured_workspace_ids
        FROM jsonb_array_elements_text(COALESCE(_captured -> 'workspace_ids', '[]'::jsonb)) v;

      IF array_length(_captured_project_ids, 1) IS NOT NULL THEN
        _candidate_ids := _captured_project_ids;
        _scope_config_fallback_used := true;
      ELSIF array_length(_captured_workspace_ids, 1) IS NOT NULL THEN
        SELECT COALESCE(array_agg(p.id), ARRAY[]::uuid[])
          INTO _candidate_ids
          FROM public.projects p
         WHERE p.workspace_id = ANY(_captured_workspace_ids);
        _scope_config_fallback_used := true;
      END IF;
    END IF;
    IF _candidate_ids IS NULL THEN
      _candidate_ids := ARRAY[]::uuid[];
    END IF;
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtext('roadmap_story_pack:' || _story_pack_id::text)::bigint
  );

  SELECT * INTO _presentation FROM public.roadmap_story_presentations
   WHERE story_pack_id = _story_pack_id;

  IF NOT FOUND THEN
    INSERT INTO public.roadmap_story_presentations
      (organization_id, story_pack_id, title_encrypted, status, created_by)
    VALUES (
      _pack.organization_id,
      _story_pack_id,
      public.btpm_encrypt(_title_final, _pack.organization_id),
      'active',
      _uid
    )
    RETURNING * INTO _presentation;
  ELSE
    IF _presentation.status = 'archived' THEN
      UPDATE public.roadmap_story_presentations
         SET status = 'active',
             title_encrypted = public.btpm_encrypt(_title_final, _pack.organization_id),
             updated_at = now()
       WHERE id = _presentation.id
       RETURNING * INTO _presentation;
    ELSE
      UPDATE public.roadmap_story_presentations
         SET title_encrypted = public.btpm_encrypt(_title_final, _pack.organization_id),
             updated_at = now()
       WHERE id = _presentation.id
       RETURNING * INTO _presentation;
    END IF;
  END IF;
  _presentation_id := _presentation.id;

  SELECT COALESCE(MAX(version_number), 0) + 1
    INTO _next_version
    FROM public.roadmap_story_presentation_versions
   WHERE presentation_id = _presentation_id;

  _title_enc := public.btpm_encrypt(_title_final, _pack.organization_id);
  _snapshot_enc := public.btpm_encrypt(_snapshot_json, _pack.organization_id);
  _limitations_enc := CASE
    WHEN _source_limitations_json IS NULL OR length(_source_limitations_json) = 0 THEN NULL
    ELSE public.btpm_encrypt(_source_limitations_json, _pack.organization_id)
  END;

  INSERT INTO public.roadmap_story_presentation_versions (
    organization_id,
    presentation_id,
    story_pack_id,
    story_pack_version_id,
    presentation_blueprint_run_id,
    version_number,
    title_encrypted,
    snapshot_encrypted,
    source_limitations_encrypted,
    status,
    published_by
  ) VALUES (
    _pack.organization_id,
    _presentation_id,
    _story_pack_id,
    _effective_pack_version_id,
    _presentation_blueprint_run_id,
    _next_version,
    _title_enc,
    _snapshot_enc,
    _limitations_enc,
    'active',
    _uid
  )
  RETURNING id INTO _new_version_id;

  IF array_length(_candidate_ids, 1) IS NOT NULL THEN
    FOR _proj IN
      SELECT DISTINCT p.id AS project_id, p.workspace_id AS workspace_id,
             w.organization_id AS workspace_org
        FROM public.projects p
        JOIN public.workspaces w ON w.id = p.workspace_id
       WHERE p.id = ANY(_candidate_ids)
    LOOP
      IF _proj.workspace_org IS DISTINCT FROM _pack.organization_id THEN
        _skipped_org_mismatch := _skipped_org_mismatch + 1;
        CONTINUE;
      END IF;
      IF NOT public.has_project_access(_uid, _proj.project_id) THEN
        _skipped_no_access := _skipped_no_access + 1;
        CONTINUE;
      END IF;
      INSERT INTO public.roadmap_story_presentation_version_projects
        (presentation_version_id, organization_id, workspace_id, project_id)
      VALUES (_new_version_id, _pack.organization_id, _proj.workspace_id, _proj.project_id)
      ON CONFLICT DO NOTHING;
      _accepted_count := _accepted_count + 1;
    END LOOP;
    _skipped_invalid := array_length(_candidate_ids, 1)
      - (_accepted_count + _skipped_no_access + _skipped_org_mismatch);
    IF _skipped_invalid < 0 THEN _skipped_invalid := 0; END IF;
  END IF;

  IF _snapshot_scope_used THEN
    _warnings := _warnings || to_jsonb(
      'Source-project scope derived from captured Story Pack source snapshot.'::text
    );
  ELSIF _scope_config_fallback_used THEN
    _warnings := _warnings || to_jsonb(
      'Source-project scope derived from Story Pack filter configuration (fallback).'::text
    );
  END IF;
  IF _skipped_no_access > 0 THEN
    _warnings := _warnings || to_jsonb(
      format('%s source project(s) skipped because the publisher lacks access.',
             _skipped_no_access)
    );
  END IF;
  IF _skipped_org_mismatch > 0 THEN
    _warnings := _warnings || to_jsonb(
      format('%s source project(s) skipped because they belong to another organization.',
             _skipped_org_mismatch)
    );
  END IF;
  IF _skipped_invalid > 0 THEN
    _warnings := _warnings || to_jsonb(
      format('%s candidate project id(s) skipped because no matching project row was found.',
             _skipped_invalid)
    );
  END IF;
  IF _accepted_count = 0 THEN
    _warnings := _warnings || to_jsonb(
      'No source projects could be derived. This published version will be openable only by the publisher or Story Pack owner.'::text
    );
  END IF;

  RETURN jsonb_build_object(
    'presentation_id', _presentation_id,
    'version_id', _new_version_id,
    'story_pack_id', _story_pack_id,
    'story_pack_version_id', _effective_pack_version_id,
    'version_number', _next_version,
    'title', _title_final,
    'status', 'active',
    'published_at', now(),
    'source_project_count', _accepted_count,
    'source_mode', _source_mode,
    'scope_source', CASE
      WHEN _snapshot_scope_used THEN 'source_snapshot'
      WHEN _scope_config_fallback_used THEN 'scope_config_fallback'
      ELSE 'none'
    END,
    'warnings', _warnings
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.reactivate_workspace(_workspace_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_org uuid;
  v_actor uuid := auth.uid();
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'NOT_AUTHENTICATED' USING ERRCODE = '42501';
  END IF;

  SELECT organization_id INTO v_org
    FROM public.workspaces
   WHERE id = _workspace_id;

  IF v_org IS NULL THEN
    RAISE EXCEPTION 'WORKSPACE_NOT_FOUND' USING ERRCODE = 'P0002';
  END IF;

  IF NOT public.is_org_admin(v_actor, v_org) THEN
    RAISE EXCEPTION 'NOT_AUTHORIZED_ORG_ADMIN_REQUIRED' USING ERRCODE = '42501';
  END IF;

  UPDATE public.workspaces
     SET is_active  = true,
         updated_at = now()
   WHERE id = _workspace_id
     AND is_active = false;

  INSERT INTO public.activity_events
    (organization_id, workspace_id, actor_id, target_type, target_id, event_type, metadata)
  VALUES
    (v_org, _workspace_id, v_actor, 'workspace', _workspace_id,
     'workspace.reactivated',
     jsonb_build_object('lifecycle', 'reactivate', 'step', '5.4')::text);
END;
$function$

CREATE OR REPLACE FUNCTION public.rebaseline_project(_project_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_proj public.projects%ROWTYPE;
BEGIN
  SELECT * INTO v_proj FROM public.projects WHERE id = _project_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Project not found'; END IF;
  IF NOT v_proj.is_baselined THEN
    RAISE EXCEPTION 'Project is not baselined. Use approve_project_baseline first.';
  END IF;
  PERFORM public._snapshot_baseline(_project_id);
  PERFORM public.log_activity_event(
    _organization_id => v_proj.organization_id,
    _actor_id        => auth.uid(),
    _event_type      => 'baseline_rebaselined',
    _target_type     => 'project',
    _target_id       => _project_id,
    _metadata        => jsonb_build_object('rebaselined_at', now()),
    _workspace_id    => v_proj.workspace_id
  );
END; $function$

CREATE OR REPLACE FUNCTION public.record_generated_decision_case_document(_record_id uuid, _document_type generated_doc_type, _generation_status generated_doc_status, _output_filename text, _source_snapshot_at timestamp with time zone, _publish_status generated_doc_publish_status DEFAULT 'not_published'::generated_doc_publish_status, _sharepoint_item_id text DEFAULT NULL::text, _sharepoint_web_url text DEFAULT NULL::text, _error_note text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _row public.governance_records%ROWTYPE;
  _uid uuid := auth.uid();
  _new_id uuid;
  _note text;
BEGIN
  IF _uid IS NULL THEN RAISE EXCEPTION 'Not authenticated' USING ERRCODE='42501'; END IF;

  SELECT * INTO _row FROM public.governance_records WHERE id = _record_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Record not found' USING ERRCODE='P0002'; END IF;
  IF _row.record_kind IS DISTINCT FROM 'decision_case' THEN
    RAISE EXCEPTION 'Generated documents are only available for decision cases' USING ERRCODE='22023';
  END IF;

  PERFORM public._gov_assert_project_write(_row.project_id);

  IF _document_type NOT IN (
    'decision_case_word_brief'::public.generated_doc_type,
    'decision_case_ppt_onepager'::public.generated_doc_type
  ) THEN
    RAISE EXCEPTION 'Unsupported document_type for decision case' USING ERRCODE='22023';
  END IF;

  _note := CASE WHEN _error_note IS NULL THEN NULL ELSE left(_error_note, 500) END;

  INSERT INTO public.generated_operational_documents (
    organization_id, workspace_id, project_id, governance_record_id,
    document_type, generation_status, output_filename, generated_by,
    source_snapshot_at, sharepoint_publish_status, sharepoint_item_id,
    sharepoint_web_url, error_note
  ) VALUES (
    _row.organization_id, _row.workspace_id, _row.project_id, _row.id,
    _document_type, _generation_status, _output_filename, _uid,
    _source_snapshot_at,
    COALESCE(_publish_status, 'not_published'::public.generated_doc_publish_status),
    _sharepoint_item_id, _sharepoint_web_url, _note
  )
  RETURNING id INTO _new_id;

  RETURN _new_id;
END; $function$

