CREATE OR REPLACE FUNCTION public.record_roadmap_story_run_files(_run_id uuid, _files jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _run public.roadmap_story_ai_runs;
  _inserted integer := 0;
  _item jsonb;
BEGIN
  IF _uid IS NULL OR NOT public.is_active_user(_uid) THEN
    RAISE EXCEPTION 'unauthorized' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO _run FROM public.roadmap_story_ai_runs WHERE id = _run_id;
  IF NOT FOUND OR _run.created_by <> _uid THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF _files IS NULL OR jsonb_typeof(_files) <> 'array' THEN
    RETURN 0;
  END IF;

  FOR _item IN SELECT * FROM jsonb_array_elements(_files) LOOP
    INSERT INTO public.roadmap_story_ai_run_files (
      ai_run_id, story_pack_id, external_file_id, attachment_alias,
      status, input_kind, file_extension, mime_type, size_bytes, sha256, skip_reason
    ) VALUES (
      _run_id,
      _run.story_pack_id,
      NULLIF(_item->>'external_file_id','')::uuid,
      COALESCE(_item->>'attachment_alias','file'),
      COALESCE(_item->>'status','skipped'),
      COALESCE(_item->>'input_kind','none'),
      _item->>'file_extension',
      _item->>'mime_type',
      NULLIF(_item->>'size_bytes','')::bigint,
      _item->>'sha256',
      _item->>'skip_reason'
    );
    _inserted := _inserted + 1;
  END LOOP;
  RETURN _inserted;
END;
$function$

CREATE OR REPLACE FUNCTION public.register_tenant_storage_object(_tenant_id uuid, _organization_id uuid, _workspace_id uuid, _bucket text, _surface text, _object_type text, _object_id uuid, _file_name text, _content_type text DEFAULT NULL::text, _size_bytes bigint DEFAULT NULL::bigint, _checksum text DEFAULT NULL::text, _metadata jsonb DEFAULT '{}'::jsonb, _legacy_object_path text DEFAULT NULL::text)
 RETURNS tenant_storage_objects
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _row public.tenant_storage_objects;
  _path text;
  _bucket_seg text;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF NOT (
    public.is_platform_super_admin(auth.uid())
    OR public.is_tenant_admin(_tenant_id, auth.uid())
    OR public.is_organization_admin(_organization_id, auth.uid())
    OR (_workspace_id IS NOT NULL AND public.is_workspace_member(auth.uid(), _workspace_id))
  ) THEN
    RAISE EXCEPTION 'Not authorized to register storage object in this scope' USING ERRCODE = '42501';
  END IF;

  _bucket_seg := public._sanitize_storage_segment(_bucket);
  IF _bucket_seg IS NULL THEN RAISE EXCEPTION 'bucket is required'; END IF;

  _path := public.build_tenant_storage_path(
    _tenant_id, _organization_id, _workspace_id, _surface, _object_type, _object_id, _file_name
  );

  INSERT INTO public.tenant_storage_objects (
    tenant_id, organization_id, workspace_id, bucket, object_path, legacy_object_path,
    surface, object_type, object_id, file_name, content_type, size_bytes, checksum,
    storage_status, created_by, updated_by, metadata
  ) VALUES (
    _tenant_id, _organization_id, _workspace_id, _bucket_seg, _path, _legacy_object_path,
    _surface, _object_type, _object_id, _file_name, _content_type, _size_bytes, _checksum,
    'pending', auth.uid(), auth.uid(), COALESCE(_metadata, '{}'::jsonb)
  )
  ON CONFLICT (bucket, object_path) DO UPDATE
     SET updated_by = auth.uid(),
         updated_at = now(),
         metadata = COALESCE(EXCLUDED.metadata, public.tenant_storage_objects.metadata)
  RETURNING * INTO _row;
  RETURN _row;
END $function$

CREATE OR REPLACE FUNCTION public.remove_dependency(_dependency_id uuid, _expected_updated_at timestamp with time zone, _correlation_id text DEFAULT NULL::text, _idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_ws uuid; v_org uuid;
  v_src_type text; v_src_id uuid; v_tgt_type text; v_tgt_id uuid;
  v_updated_at timestamptz;
  v_project uuid;
BEGIN
  IF v_actor IS NULL OR NOT public.is_active_user(v_actor) THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'remove_dependency',
      'dependency', NULL, NULL,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF _dependency_id IS NULL OR _expected_updated_at IS NULL THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'remove_dependency',
      'dependency', NULL, NULL,
      jsonb_build_object('reason','invalid_input'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  SELECT workspace_id, organization_id, source_type, source_id, target_type, target_id, updated_at
    INTO v_ws, v_org, v_src_type, v_src_id, v_tgt_type, v_tgt_id, v_updated_at
    FROM public.dependencies
    WHERE id = _dependency_id
    FOR UPDATE;

  IF v_ws IS NULL THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'remove_dependency',
      'dependency', NULL, NULL,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF NOT public.has_pm_authority(v_actor, v_ws)
     OR NOT public.can_write_demo(v_actor, v_ws) THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'remove_dependency',
      'dependency', _dependency_id, NULL,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  -- Derive parent project (needed for both conflict audit and applied audit).
  IF v_src_type = 'phase' THEN
    SELECT project_id INTO v_project FROM public.phases WHERE id = v_src_id;
  ELSIF v_src_type = 'task' THEN
    SELECT project_id INTO v_project FROM public.tasks WHERE id = v_src_id;
  ELSE
    v_project := v_src_id;
  END IF;

  IF v_updated_at IS DISTINCT FROM _expected_updated_at THEN
    PERFORM public.pmg_record_command_audit(
      'conflict'::public.pmg_command_status, 'remove_dependency',
      'btpm_ui'::public.pmg_source_channel,
      v_project, 'dependency', _dependency_id, NULL,
      _correlation_id, _idempotency_key,
      jsonb_build_object(
        'stale', true,
        'source_type', v_src_type,
        'target_type', v_tgt_type,
        'workspace_id', v_ws
      )
    );
    RETURN public.pmg_build_result(
      'conflict'::public.pmg_command_status, 'remove_dependency',
      'dependency', _dependency_id, v_project,
      jsonb_build_object('reason','stale_write','current_updated_at', v_updated_at),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  DELETE FROM public.dependencies WHERE id = _dependency_id;

  PERFORM public.pmg_record_command_audit(
    'applied'::public.pmg_command_status, 'remove_dependency',
    'btpm_ui'::public.pmg_source_channel,
    v_project, 'dependency', _dependency_id, NULL,
    _correlation_id, _idempotency_key,
    jsonb_build_object(
      'source_type', v_src_type, 'target_type', v_tgt_type,
      'workspace_id', v_ws
    )
  );

  RETURN public.pmg_build_result(
    'applied'::public.pmg_command_status, 'remove_dependency',
    'dependency', _dependency_id, v_project,
    jsonb_build_object('id', _dependency_id),
    '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.remove_project_people_preset_member(_member_id uuid, _expected_preset_updated_at timestamp with time zone, _correlation_id text DEFAULT NULL::text, _idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor  uuid := auth.uid();
  v_preset public.project_people_presets;
  v_member public.project_people_preset_members;
  v_count  int;
BEGIN
  SELECT * INTO v_member FROM public.project_people_preset_members WHERE id = _member_id FOR UPDATE;
  IF v_member.id IS NULL THEN
    RETURN public.pmg_build_result('no_change', 'remove_project_people_preset_member',
      'project_people_preset_member', NULL, NULL,
      jsonb_build_object('reason','not_found'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL);
  END IF;
  SELECT * INTO v_preset FROM public.project_people_presets WHERE id = v_member.preset_id FOR UPDATE;
  PERFORM public._ppp_authorize_write(v_actor, v_preset, true);

  IF v_preset.updated_at IS DISTINCT FROM _expected_preset_updated_at THEN
    RETURN public.pmg_build_result('conflict', 'remove_project_people_preset_member',
      'project_people_preset_member', _member_id, NULL, '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb,
      jsonb_build_object('server_updated_at', v_preset.updated_at));
  END IF;

  SELECT COUNT(*)::int INTO v_count FROM public.project_people_preset_members WHERE preset_id = v_member.preset_id;
  IF v_count <= 1 THEN
    RETURN public.pmg_build_result('invalid', 'remove_project_people_preset_member',
      'project_people_preset_member', _member_id, NULL,
      jsonb_build_object('reason','cannot_remove_final_member'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL);
  END IF;

  DELETE FROM public.project_people_preset_members WHERE id = _member_id;
  UPDATE public.project_people_presets SET updated_at = now() WHERE id = v_member.preset_id;

  PERFORM public._ppp_record_audit('applied', 'remove_project_people_preset_member',
    v_preset, 'project_people_preset_member', _member_id, _correlation_id, _idempotency_key,
    jsonb_build_object('member_kind', v_member.member_kind, 'stakeholder_type', v_member.stakeholder_type));

  RETURN public.pmg_build_result('applied', 'remove_project_people_preset_member',
    'project_people_preset_member', _member_id, NULL,
    jsonb_build_object('id', _member_id),
    '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL);
END; $function$

CREATE OR REPLACE FUNCTION public.remove_project_stakeholder(_stakeholder_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_row public.project_stakeholders;
  v_display text;
BEGIN
  IF v_actor IS NULL OR NOT public.is_active_user(v_actor) THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT *
  INTO v_row
  FROM public.project_stakeholders
  WHERE id = _stakeholder_id;

  IF v_row.id IS NULL THEN
    RAISE EXCEPTION 'Stakeholder not found';
  END IF;

  IF NOT (public.is_org_admin(v_actor, v_row.organization_id) OR public.has_pm_authority(v_actor, v_row.workspace_id)) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  IF v_row.removed_at IS NOT NULL THEN
    RETURN;
  END IF;

  UPDATE public.project_stakeholders
  SET removed_at = now(), removed_by = v_actor
  WHERE id = _stakeholder_id;

  IF v_row.stakeholder_type = 'workspace_member' THEN
    SELECT COALESCE(display_name, email, v_row.user_id::text)
    INTO v_display
    FROM public.profiles
    WHERE id = v_row.user_id;
  ELSE
    v_display := v_row.external_name;
  END IF;

  PERFORM public.log_activity_event(
    v_row.organization_id,
    v_actor,
    'stakeholder_removed',
    'project',
    v_row.project_id,
    jsonb_build_object(
      'stakeholder_id', _stakeholder_id,
      'stakeholder_type', v_row.stakeholder_type,
      'display_name', v_display,
      'role_label', v_row.role_label,
      'start_date', v_row.start_date
    ),
    v_row.workspace_id
  );
END;
$function$

