CREATE OR REPLACE FUNCTION public.rename_project_people_preset(_preset_id uuid, _name text, _description text, _expected_updated_at timestamp with time zone, _correlation_id text DEFAULT NULL::text, _idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor       uuid := auth.uid();
  v_preset      public.project_people_presets;
  v_name_norm   text;
  v_desc_norm   text;
  v_dupe        uuid;
  r             record;
BEGIN
  SELECT * INTO v_preset FROM public.project_people_presets WHERE id = _preset_id FOR UPDATE;
  IF v_preset.id IS NULL THEN
    RETURN public.pmg_build_result('not_authorized', 'rename_project_people_preset',
      'project_people_preset', NULL, NULL, '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL);
  END IF;
  PERFORM public._ppp_authorize_write(v_actor, v_preset, true);

  v_name_norm := NULLIF(btrim(COALESCE(_name, '')), '');
  v_desc_norm := NULLIF(btrim(COALESCE(_description, '')), '');
  IF v_name_norm IS NULL THEN
    RETURN public.pmg_build_result('invalid', 'rename_project_people_preset',
      'project_people_preset', _preset_id, NULL,
      jsonb_build_object('reason','name_required'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL);
  END IF;

  IF v_preset.updated_at IS DISTINCT FROM _expected_updated_at THEN
    RETURN public.pmg_build_result('conflict', 'rename_project_people_preset',
      'project_people_preset', _preset_id, NULL, '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb,
      jsonb_build_object('server_updated_at', v_preset.updated_at));
  END IF;

  -- Duplicate name within same workspace amongst active presets (decrypt + compare, locked scope)
  FOR r IN
    SELECT id, name FROM public.project_people_presets
     WHERE workspace_id = v_preset.workspace_id
       AND archived_at IS NULL
       AND id <> _preset_id
     FOR UPDATE
  LOOP
    IF lower(btrim(public.btpm_decrypt(r.name, v_preset.organization_id))) = lower(v_name_norm) THEN
      v_dupe := r.id;
      EXIT;
    END IF;
  END LOOP;

  IF v_dupe IS NOT NULL THEN
    RETURN public.pmg_build_result('invalid', 'rename_project_people_preset',
      'project_people_preset', _preset_id, NULL,
      jsonb_build_object('reason','duplicate_name'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL);
  END IF;

  UPDATE public.project_people_presets
     SET name = v_name_norm, description = v_desc_norm
   WHERE id = _preset_id;

  PERFORM public._ppp_record_audit('applied', 'rename_project_people_preset',
    v_preset, 'project_people_preset', _preset_id, _correlation_id, _idempotency_key,
    jsonb_build_object('description_present', v_desc_norm IS NOT NULL));

  RETURN public.pmg_build_result('applied', 'rename_project_people_preset',
    'project_people_preset', _preset_id, NULL,
    jsonb_build_object('id', _preset_id),
    '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL);
END; $function$

CREATE OR REPLACE FUNCTION public.reopen_phase(_phase_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_row public.phases%ROWTYPE;
BEGIN
  IF NOT public.is_active_user(auth.uid()) THEN
    RAISE EXCEPTION 'Account is deactivated';
  END IF;

  SELECT * INTO v_row FROM public.phases WHERE id = _phase_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Phase not found'; END IF;

  IF NOT public.has_pm_authority(auth.uid(), v_row.workspace_id) THEN
    RAISE EXCEPTION 'Not authorized: PM authority required to reopen a phase';
  END IF;

  IF NOT public.can_write_demo(auth.uid(), v_row.workspace_id) THEN
    RAISE EXCEPTION 'Not authorized: this workspace is read-only';
  END IF;

  IF v_row.status <> 'completed' THEN
    RAISE EXCEPTION 'Only completed phases can be reopened (current status: %)', v_row.status;
  END IF;

  PERFORM set_config('app.allow_lifecycle_bypass', 'on', true);
  UPDATE public.phases
  SET status     = 'active',
      updated_at = now()
  WHERE id = _phase_id;
  PERFORM set_config('app.allow_lifecycle_bypass', '', true);

  PERFORM public.log_activity_event(
    v_row.organization_id,
    auth.uid(),
    'phase_reopened',
    'phase',
    _phase_id,
    jsonb_build_object(
      'prior_status', 'completed',
      'new_status',   'active',
      'project_id',   v_row.project_id
    ),
    v_row.workspace_id
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.reopen_task(_task_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_row public.tasks%ROWTYPE;
BEGIN
  IF NOT public.is_active_user(auth.uid()) THEN
    RAISE EXCEPTION 'Account is deactivated';
  END IF;

  SELECT * INTO v_row FROM public.tasks WHERE id = _task_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Task not found'; END IF;

  IF NOT public.has_pm_authority(auth.uid(), v_row.workspace_id) THEN
    RAISE EXCEPTION 'Not authorized: PM authority required to reopen a task';
  END IF;

  IF NOT public.can_write_demo(auth.uid(), v_row.workspace_id) THEN
    RAISE EXCEPTION 'Not authorized: this workspace is read-only';
  END IF;

  IF v_row.status <> 'completed' THEN
    RAISE EXCEPTION 'Only completed tasks can be reopened (current status: %)', v_row.status;
  END IF;

  PERFORM set_config('app.allow_lifecycle_bypass', 'on', true);
  UPDATE public.tasks
  SET status     = 'active',
      updated_at = now()
  WHERE id = _task_id;
  PERFORM set_config('app.allow_lifecycle_bypass', '', true);

  PERFORM public.log_activity_event(
    v_row.organization_id,
    auth.uid(),
    'task_reopened',
    'task',
    _task_id,
    jsonb_build_object(
      'prior_status', 'completed',
      'new_status',   'active',
      'project_id',   v_row.project_id,
      'phase_id',     v_row.phase_id
    ),
    v_row.workspace_id
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.reorder_backlog_items(_project_id uuid, _rows jsonb, _correlation_id text DEFAULT NULL::text, _idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_project record;
  v_input_count int;
  v_stale_ids uuid[];
  v_changed_count int := 0;
  v_audit_status public.pmg_command_status;
  v_data jsonb;
BEGIN
  IF v_actor IS NULL OR NOT public.is_active_user(v_actor) THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'reorder_backlog_items',
      'backlog_item_collection', _project_id, _project_id,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  SELECT id, workspace_id INTO v_project FROM public.projects WHERE id = _project_id;
  IF v_project.id IS NULL THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'reorder_backlog_items',
      'backlog_item_collection', _project_id, _project_id,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF NOT public.has_project_pm_authority(v_actor, _project_id)
     OR NOT public.can_write_demo(v_actor, v_project.workspace_id) THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'reorder_backlog_items',
      'backlog_item_collection', _project_id, _project_id,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF _rows IS NULL OR jsonb_typeof(_rows) <> 'array' THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'reorder_backlog_items',
      'backlog_item_collection', _project_id, _project_id,
      jsonb_build_object('reason','rows_not_array'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  DROP TABLE IF EXISTS pg_temp._pmg_backlog_reorder_input;
  CREATE TEMP TABLE _pmg_backlog_reorder_input (
    id uuid,
    expected_updated_at timestamptz,
    new_sort_order integer
  ) ON COMMIT DROP;

  BEGIN
    INSERT INTO pg_temp._pmg_backlog_reorder_input (id, expected_updated_at, new_sort_order)
    SELECT (elem->>'id')::uuid,
           (elem->>'expected_updated_at')::timestamptz,
           (elem->>'new_sort_order')::int
      FROM jsonb_array_elements(_rows) AS elem;
  EXCEPTION WHEN others THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'reorder_backlog_items',
      'backlog_item_collection', _project_id, _project_id,
      jsonb_build_object('reason','malformed_rows'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END;

  SELECT count(*) INTO v_input_count FROM pg_temp._pmg_backlog_reorder_input;

  IF v_input_count = 0 THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'reorder_backlog_items',
      'backlog_item_collection', _project_id, _project_id,
      jsonb_build_object('reason','no_rows'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF EXISTS (
    SELECT 1 FROM pg_temp._pmg_backlog_reorder_input
     WHERE id IS NULL OR expected_updated_at IS NULL OR new_sort_order IS NULL
  ) THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'reorder_backlog_items',
      'backlog_item_collection', _project_id, _project_id,
      jsonb_build_object('reason','row_field_missing'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF (SELECT count(DISTINCT id) FROM pg_temp._pmg_backlog_reorder_input) <> v_input_count THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'reorder_backlog_items',
      'backlog_item_collection', _project_id, _project_id,
      jsonb_build_object('reason','duplicate_row_ids'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF (SELECT count(DISTINCT new_sort_order) FROM pg_temp._pmg_backlog_reorder_input) <> v_input_count THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'reorder_backlog_items',
      'backlog_item_collection', _project_id, _project_id,
      jsonb_build_object('reason','duplicate_sort_positions'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  -- Lock the parent scope: all backlog rows for this project.
  PERFORM 1 FROM public.backlog_items WHERE project_id = _project_id FOR UPDATE;

  -- Every submitted id must exist in this project.
  IF EXISTS (
    SELECT 1 FROM pg_temp._pmg_backlog_reorder_input i
      LEFT JOIN public.backlog_items b
        ON b.id = i.id AND b.project_id = _project_id
     WHERE b.id IS NULL
  ) THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'reorder_backlog_items',
      'backlog_item_collection', _project_id, _project_id,
      jsonb_build_object('reason','unknown_or_cross_project_rows'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  SELECT COALESCE(array_agg(b.id), ARRAY[]::uuid[])
    INTO v_stale_ids
    FROM public.backlog_items b
    JOIN pg_temp._pmg_backlog_reorder_input i ON i.id = b.id
   WHERE b.project_id = _project_id
     AND b.updated_at IS DISTINCT FROM i.expected_updated_at;

  IF array_length(v_stale_ids, 1) IS NOT NULL THEN
    PERFORM public.pmg_record_command_audit(
      'conflict'::public.pmg_command_status, 'reorder_backlog_items',
      'btpm_ui'::public.pmg_source_channel,
      _project_id, 'backlog_item_collection', _project_id, NULL,
      _correlation_id, _idempotency_key,
      jsonb_build_object(
        'submitted_count', v_input_count,
        'changed_count', 0,
        'stale_count', array_length(v_stale_ids, 1)
      )
    );
    RETURN public.pmg_build_result(
      'conflict'::public.pmg_command_status, 'reorder_backlog_items',
      'backlog_item_collection', _project_id, _project_id,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb,
      jsonb_build_object('code','stale_backlog_order','stale_ids', to_jsonb(v_stale_ids))
    );
  END IF;

  WITH upd AS (
    UPDATE public.backlog_items b
       SET sort_order = i.new_sort_order
      FROM pg_temp._pmg_backlog_reorder_input i
     WHERE b.id = i.id
       AND b.project_id = _project_id
       AND b.sort_order IS DISTINCT FROM i.new_sort_order
    RETURNING b.id
  )
  SELECT count(*) INTO v_changed_count FROM upd;

  v_audit_status := CASE WHEN v_changed_count = 0
    THEN 'no_change'::public.pmg_command_status
    ELSE 'applied'::public.pmg_command_status END;

  SELECT jsonb_build_object(
    'submitted_count', v_input_count,
    'changed_count', v_changed_count,
    'ordered_items', COALESCE(jsonb_agg(
      jsonb_build_object('id', b.id, 'sort_order', b.sort_order, 'updated_at', b.updated_at)
      ORDER BY b.sort_order
    ), '[]'::jsonb)
  ) INTO v_data
  FROM public.backlog_items b
  WHERE b.id IN (SELECT id FROM pg_temp._pmg_backlog_reorder_input);

  PERFORM public.pmg_record_command_audit(
    v_audit_status, 'reorder_backlog_items',
    'btpm_ui'::public.pmg_source_channel,
    _project_id, 'backlog_item_collection', _project_id, NULL,
    _correlation_id, _idempotency_key,
    jsonb_build_object(
      'submitted_count', v_input_count,
      'changed_count', v_changed_count,
      'stale_count', 0
    )
  );

  RETURN public.pmg_build_result(
    v_audit_status, 'reorder_backlog_items',
    'backlog_item_collection', _project_id, _project_id,
    v_data, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.reorder_phases(_project_id uuid, _rows jsonb, _correlation_id text DEFAULT NULL::text, _idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_project record;
  v_input_count int;
  v_existing_count int;
  v_stale_ids uuid[];
  v_changed_count int := 0;
  v_audit_status public.pmg_command_status;
  v_data jsonb;
BEGIN
  -- Authentication
  IF v_actor IS NULL THEN
    RETURN public.pmg_build_result(
      _status => 'not_authorized'::public.pmg_command_status,
      _command => 'reorder_phases',
      _target_type => 'phase_collection',
      _target_id => NULL,
      _project_id => _project_id,
      _data => '{}'::jsonb,
      _changes => '[]'::jsonb,
      _warnings => '[]'::jsonb,
      _confirmations => '[]'::jsonb,
      _conflict => NULL
    );
  END IF;

  IF NOT public.is_active_user(v_actor) THEN
    RETURN public.pmg_build_result(
      _status => 'not_authorized'::public.pmg_command_status,
      _command => 'reorder_phases',
      _target_type => 'phase_collection',
      _target_id => NULL,
      _project_id => _project_id,
      _data => '{}'::jsonb,
      _changes => '[]'::jsonb,
      _warnings => '[]'::jsonb,
      _confirmations => '[]'::jsonb,
      _conflict => NULL
    );
  END IF;

  -- Project existence
  SELECT id, organization_id, workspace_id
    INTO v_project
    FROM public.projects
   WHERE id = _project_id;

  IF v_project.id IS NULL THEN
    RETURN public.pmg_build_result(
      _status => 'not_authorized'::public.pmg_command_status,
      _command => 'reorder_phases',
      _target_type => 'phase_collection',
      _target_id => NULL,
      _project_id => _project_id,
      _data => '{}'::jsonb,
      _changes => '[]'::jsonb,
      _warnings => '[]'::jsonb,
      _confirmations => '[]'::jsonb,
      _conflict => NULL
    );
  END IF;

  -- Authority (project-level PM + demo write gate on resolved workspace)
  IF NOT public.has_project_pm_authority(v_actor, _project_id)
     OR NOT public.can_write_demo(v_actor, v_project.workspace_id) THEN
    RETURN public.pmg_build_result(
      _status => 'not_authorized'::public.pmg_command_status,
      _command => 'reorder_phases',
      _target_type => 'phase_collection',
      _target_id => NULL,
      _project_id => _project_id,
      _data => '{}'::jsonb,
      _changes => '[]'::jsonb,
      _warnings => '[]'::jsonb,
      _confirmations => '[]'::jsonb,
      _conflict => NULL
    );
  END IF;

  -- Structural validation of _rows
  IF _rows IS NULL OR jsonb_typeof(_rows) <> 'array' THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'reorder_phases',
      'phase_collection', NULL, _project_id,
      jsonb_build_object('reason','rows_not_array'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  DROP TABLE IF EXISTS pg_temp._pmg_reorder_input;
  CREATE TEMP TABLE _pmg_reorder_input (
    id uuid,
    expected_updated_at timestamptz,
    new_sort_order integer
  ) ON COMMIT DROP;

  BEGIN
    INSERT INTO pg_temp._pmg_reorder_input (id, expected_updated_at, new_sort_order)
    SELECT
      (elem->>'id')::uuid,
      (elem->>'expected_updated_at')::timestamptz,
      (elem->>'new_sort_order')::int
    FROM jsonb_array_elements(_rows) AS elem;
  EXCEPTION WHEN others THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'reorder_phases',
      'phase_collection', NULL, _project_id,
      jsonb_build_object('reason','malformed_rows'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END;

  SELECT count(*) INTO v_input_count FROM pg_temp._pmg_reorder_input;

  IF v_input_count = 0 THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'reorder_phases',
      'phase_collection', NULL, _project_id,
      jsonb_build_object('reason','no_rows'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF EXISTS (
    SELECT 1 FROM pg_temp._pmg_reorder_input
     WHERE id IS NULL OR expected_updated_at IS NULL OR new_sort_order IS NULL
  ) THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'reorder_phases',
      'phase_collection', NULL, _project_id,
      jsonb_build_object('reason','row_field_missing'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF (SELECT count(DISTINCT id) FROM pg_temp._pmg_reorder_input) <> v_input_count THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'reorder_phases',
      'phase_collection', NULL, _project_id,
      jsonb_build_object('reason','duplicate_row_ids'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF (SELECT count(DISTINCT new_sort_order) FROM pg_temp._pmg_reorder_input) <> v_input_count THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'reorder_phases',
      'phase_collection', NULL, _project_id,
      jsonb_build_object('reason','duplicate_sort_positions'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF NOT (
    SELECT bool_and(new_sort_order = expected_pos)
      FROM (
        SELECT new_sort_order,
               row_number() OVER (ORDER BY new_sort_order) - 1 AS expected_pos
          FROM pg_temp._pmg_reorder_input
      ) x
  ) THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'reorder_phases',
      'phase_collection', NULL, _project_id,
      jsonb_build_object('reason','non_contiguous_sort_positions'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  PERFORM 1 FROM public.phases WHERE project_id = _project_id FOR UPDATE;

  SELECT count(*) INTO v_existing_count
    FROM public.phases WHERE project_id = _project_id;

  IF v_input_count <> v_existing_count THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'reorder_phases',
      'phase_collection', NULL, _project_id,
      jsonb_build_object(
        'reason','row_count_mismatch',
        'submitted_count', v_input_count,
        'expected_count', v_existing_count
      ),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF EXISTS (
    SELECT 1 FROM pg_temp._pmg_reorder_input i
      LEFT JOIN public.phases ph
        ON ph.id = i.id AND ph.project_id = _project_id
     WHERE ph.id IS NULL
  ) THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'reorder_phases',
      'phase_collection', NULL, _project_id,
      jsonb_build_object('reason','unknown_or_cross_project_rows'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.phases ph
      LEFT JOIN pg_temp._pmg_reorder_input i ON i.id = ph.id
     WHERE ph.project_id = _project_id AND i.id IS NULL
  ) THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'reorder_phases',
      'phase_collection', NULL, _project_id,
      jsonb_build_object('reason','missing_phase_rows'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  SELECT COALESCE(array_agg(ph.id), ARRAY[]::uuid[])
    INTO v_stale_ids
    FROM public.phases ph
    JOIN pg_temp._pmg_reorder_input i ON i.id = ph.id
   WHERE ph.project_id = _project_id
     AND ph.updated_at IS DISTINCT FROM i.expected_updated_at;

  IF array_length(v_stale_ids, 1) IS NOT NULL THEN
    v_audit_status := 'conflict'::public.pmg_command_status;
    PERFORM public.pmg_record_command_audit(
      v_audit_status, 'reorder_phases',
      'btpm_ui'::public.pmg_source_channel,
      _project_id, 'phase_collection', NULL, NULL,
      _correlation_id, _idempotency_key,
      jsonb_build_object(
        'submitted_count', v_input_count,
        'changed_count', 0,
        'stale_count', array_length(v_stale_ids, 1)
      )
    );
    RETURN public.pmg_build_result(
      v_audit_status, 'reorder_phases',
      'phase_collection', NULL, _project_id,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb,
      jsonb_build_object(
        'code', 'stale_phase_order',
        'stale_ids', to_jsonb(v_stale_ids)
      )
    );
  END IF;

  WITH upd AS (
    UPDATE public.phases ph
       SET sort_order = i.new_sort_order
      FROM pg_temp._pmg_reorder_input i
     WHERE ph.id = i.id
       AND ph.project_id = _project_id
       AND ph.sort_order IS DISTINCT FROM i.new_sort_order
    RETURNING ph.id
  )
  SELECT count(*) INTO v_changed_count FROM upd;

  IF v_changed_count = 0 THEN
    v_audit_status := 'no_change'::public.pmg_command_status;
  ELSE
    v_audit_status := 'applied'::public.pmg_command_status;
  END IF;

  SELECT jsonb_build_object(
    'submitted_count', v_input_count,
    'changed_count', v_changed_count,
    'ordered_phases', COALESCE(jsonb_agg(
      jsonb_build_object(
        'id', ph.id,
        'sort_order', ph.sort_order,
        'updated_at', ph.updated_at
      ) ORDER BY ph.sort_order
    ), '[]'::jsonb)
  )
  INTO v_data
  FROM public.phases ph
  WHERE ph.project_id = _project_id;

  PERFORM public.pmg_record_command_audit(
    v_audit_status, 'reorder_phases',
    'btpm_ui'::public.pmg_source_channel,
    _project_id, 'phase_collection', NULL, NULL,
    _correlation_id, _idempotency_key,
    jsonb_build_object(
      'submitted_count', v_input_count,
      'changed_count', v_changed_count,
      'stale_count', 0
    )
  );

  RETURN public.pmg_build_result(
    v_audit_status, 'reorder_phases',
    'phase_collection', NULL, _project_id,
    v_data, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.reorder_tasks(_phase_id uuid, _rows jsonb, _correlation_id text DEFAULT NULL::text, _idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
