      'task_collection', _phase_id, v_project_id,
      jsonb_build_object('reason','malformed_rows'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END;

  SELECT count(*) INTO v_input_count FROM pg_temp._pmg_task_reorder_input;

  IF v_input_count = 0 THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'reorder_tasks',
      'task_collection', _phase_id, v_project_id,
      jsonb_build_object('reason','no_rows'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF EXISTS (
    SELECT 1 FROM pg_temp._pmg_task_reorder_input
     WHERE id IS NULL OR expected_updated_at IS NULL OR new_sort_order IS NULL
  ) THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'reorder_tasks',
      'task_collection', _phase_id, v_project_id,
      jsonb_build_object('reason','row_field_missing'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF (SELECT count(DISTINCT id) FROM pg_temp._pmg_task_reorder_input) <> v_input_count THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'reorder_tasks',
      'task_collection', _phase_id, v_project_id,
      jsonb_build_object('reason','duplicate_row_ids'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF (SELECT count(DISTINCT new_sort_order) FROM pg_temp._pmg_task_reorder_input) <> v_input_count THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'reorder_tasks',
      'task_collection', _phase_id, v_project_id,
      jsonb_build_object('reason','duplicate_sort_positions'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF NOT (
    SELECT bool_and(new_sort_order = expected_pos)
      FROM (
        SELECT new_sort_order,
               row_number() OVER (ORDER BY new_sort_order) - 1 AS expected_pos
          FROM pg_temp._pmg_task_reorder_input
      ) x
  ) THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'reorder_tasks',
      'task_collection', _phase_id, v_project_id,
      jsonb_build_object('reason','non_contiguous_sort_positions'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  PERFORM 1 FROM public.tasks WHERE phase_id = _phase_id FOR UPDATE;

  SELECT count(*) INTO v_existing_count
    FROM public.tasks WHERE phase_id = _phase_id;

  IF v_input_count <> v_existing_count THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'reorder_tasks',
      'task_collection', _phase_id, v_project_id,
      jsonb_build_object(
        'reason','row_count_mismatch',
        'submitted_count', v_input_count,
        'expected_count', v_existing_count
      ),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF EXISTS (
    SELECT 1 FROM pg_temp._pmg_task_reorder_input i
      LEFT JOIN public.tasks t
        ON t.id = i.id AND t.phase_id = _phase_id
     WHERE t.id IS NULL
  ) THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'reorder_tasks',
      'task_collection', _phase_id, v_project_id,
      jsonb_build_object('reason','unknown_or_cross_phase_rows'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.tasks t
      LEFT JOIN pg_temp._pmg_task_reorder_input i ON i.id = t.id
     WHERE t.phase_id = _phase_id AND i.id IS NULL
  ) THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'reorder_tasks',
      'task_collection', _phase_id, v_project_id,
      jsonb_build_object('reason','missing_task_rows'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  SELECT COALESCE(array_agg(t.id), ARRAY[]::uuid[])
    INTO v_stale_ids
    FROM public.tasks t
    JOIN pg_temp._pmg_task_reorder_input i ON i.id = t.id
   WHERE t.phase_id = _phase_id
     AND t.updated_at IS DISTINCT FROM i.expected_updated_at;

  IF array_length(v_stale_ids, 1) IS NOT NULL THEN
    v_audit_status := 'conflict'::public.pmg_command_status;
    PERFORM public.pmg_record_command_audit(
      v_audit_status, 'reorder_tasks',
      'btpm_ui'::public.pmg_source_channel,
      v_project_id, 'task_collection', _phase_id, NULL,
      _correlation_id, _idempotency_key,
      jsonb_build_object(
        'submitted_count', v_input_count,
        'changed_count', 0,
        'stale_count', array_length(v_stale_ids, 1)
      )
    );
    RETURN public.pmg_build_result(
      v_audit_status, 'reorder_tasks',
      'task_collection', _phase_id, v_project_id,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb,
      jsonb_build_object(
        'code', 'stale_task_order',
        'stale_ids', to_jsonb(v_stale_ids)
      )
    );
  END IF;

  WITH upd AS (
    UPDATE public.tasks t
       SET sort_order = i.new_sort_order
      FROM pg_temp._pmg_task_reorder_input i
     WHERE t.id = i.id
       AND t.phase_id = _phase_id
       AND t.sort_order IS DISTINCT FROM i.new_sort_order
    RETURNING t.id
  )
  SELECT count(*) INTO v_changed_count FROM upd;

  IF v_changed_count = 0 THEN
    v_audit_status := 'no_change'::public.pmg_command_status;
  ELSE
    v_audit_status := 'applied'::public.pmg_command_status;
  END IF;

  SELECT jsonb_build_object(
    'submitted_count', v_input_count,
    'changed_count', v_changed_count,
    'ordered_tasks', COALESCE(jsonb_agg(
      jsonb_build_object(
        'id', t.id,
        'sort_order', t.sort_order,
        'updated_at', t.updated_at
      ) ORDER BY t.sort_order
    ), '[]'::jsonb)
  )
  INTO v_data
  FROM public.tasks t
  WHERE t.phase_id = _phase_id;

  PERFORM public.pmg_record_command_audit(
    v_audit_status, 'reorder_tasks',
    'btpm_ui'::public.pmg_source_channel,
    v_project_id, 'task_collection', _phase_id, NULL,
    _correlation_id, _idempotency_key,
    jsonb_build_object(
      'submitted_count', v_input_count,
      'changed_count', v_changed_count,
      'stale_count', 0
    )
  );

  RETURN public.pmg_build_result(
    v_audit_status, 'reorder_tasks',
    'task_collection', _phase_id, v_project_id,
    v_data, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.reset_kpi_app_outbox(_outbox_id uuid, _reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _row public.kpi_app_submission_outbox%ROWTYPE;
  _stale_after_minutes constant integer := 15;
  _now timestamptz := now();
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Unauthorized' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO _row
  FROM public.kpi_app_submission_outbox
  WHERE id = _outbox_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Outbox not found' USING ERRCODE = 'P0002';
  END IF;

  -- Authority gate: org admin OR workspace admin/higher for this row.
  IF NOT (
    public.is_org_admin(auth.uid(), _row.organization_id)
    OR public.is_workspace_admin_or_higher(auth.uid(), _row.workspace_id)
  ) THEN
    RAISE EXCEPTION 'Access denied' USING ERRCODE = '42501';
  END IF;

  -- Already superseded: idempotent success.
  IF _row.superseded_at IS NOT NULL THEN
    RETURN jsonb_build_object(
      'ok', true,
      'outbox_id', _row.id,
      'already_superseded', true,
      'superseded_at', _row.superseded_at
    );
  END IF;

  -- Never reset a successful submission.
  IF _row.status = 'submitted' OR _row.submitted_at IS NOT NULL AND _row.status = 'submitted' THEN
    RAISE EXCEPTION 'Submitted outbox cannot be reset' USING ERRCODE = '22023';
  END IF;

  -- Never reset an in-progress row unless it is stale.
  IF _row.status = 'submitting'
     AND (_row.last_attempt_at IS NULL
          OR _row.last_attempt_at > _now - make_interval(mins => _stale_after_minutes)) THEN
    RAISE EXCEPTION 'In-progress outbox is not stale; cannot reset' USING ERRCODE = '22023';
  END IF;

  -- Allow reset for failed / queued / payload_ready / retry_pending / stale submitting.
  IF _row.status NOT IN ('failed', 'queued', 'payload_ready', 'retry_pending', 'submitting') THEN
    RAISE EXCEPTION 'Outbox status % is not resettable', _row.status USING ERRCODE = '22023';
  END IF;

  UPDATE public.kpi_app_submission_outbox
     SET superseded_at = _now,
         superseded_by = auth.uid(),
         superseded_reason = NULLIF(btrim(_reason), '')
   WHERE id = _outbox_id
     AND superseded_at IS NULL;

  RETURN jsonb_build_object(
    'ok', true,
    'outbox_id', _outbox_id,
    'superseded_at', _now,
    'previous_status', _row.status
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.resolve_child_project_scope(_table text, _target_type text, _target_id uuid, _project_id_direct uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_pid uuid;
BEGIN
  IF _table IN ('phases','tasks') THEN
    RETURN _project_id_direct;
  END IF;
  IF _target_type = 'project' THEN
    RETURN _target_id;
  ELSIF _target_type = 'phase' THEN
    SELECT project_id INTO v_pid FROM public.phases WHERE id = _target_id;
    RETURN v_pid;
  ELSIF _target_type = 'task' THEN
    SELECT project_id INTO v_pid FROM public.tasks WHERE id = _target_id;
    RETURN v_pid;
  END IF;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.resolve_effective_integration_secret_ref(_tenant_id uuid, _organization_id uuid, _integration_kind tenant_integration_kind, _secret_name text, _integration_name text DEFAULT 'default'::text, _reason text DEFAULT NULL::text, _function_name text DEFAULT NULL::text, _request_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _integration public.tenant_integrations;
  _org_tenant uuid;
  _integration_disabled_override_id uuid;
  _secret_override public.organization_secret_overrides;
  _selected_ref_id uuid;
  _ref public.tenant_secret_refs;
BEGIN
  IF _tenant_id IS NULL THEN
    RAISE EXCEPTION 'tenant_id is required';
  END IF;

  IF _organization_id IS NOT NULL THEN
    SELECT tenant_id INTO _org_tenant
      FROM public.organizations WHERE id = _organization_id;
    IF _org_tenant IS NULL OR _org_tenant <> _tenant_id THEN
      INSERT INTO public.tenant_secret_access_audit(
        tenant_id, organization_id, actor_user_id, actor_type,
        action, reason, function_name, request_id, result, error_message
      ) VALUES (_tenant_id, _organization_id, auth.uid(), 'service',
                'failed', _reason, _function_name, _request_id, 'blocked',
                'organization_not_in_tenant');
      RETURN jsonb_build_object('status','blocked','reason','organization_not_in_tenant');
    END IF;
  END IF;

  SELECT * INTO _integration FROM public.tenant_integrations
   WHERE tenant_id = _tenant_id
     AND kind = _integration_kind
     AND name = _integration_name;

  IF _integration.id IS NULL OR NOT _integration.is_enabled OR _integration.status <> 'active' THEN
    INSERT INTO public.tenant_secret_access_audit(
      tenant_id, organization_id, integration_id, actor_user_id, actor_type,
      action, reason, function_name, request_id, result, error_message
    ) VALUES (_tenant_id, _organization_id, _integration.id, auth.uid(), 'service',
              'failed', _reason, _function_name, _request_id, 'blocked',
              'integration_not_active');
    RETURN jsonb_build_object('status','blocked','reason','integration_not_active');
  END IF;

  IF _organization_id IS NOT NULL THEN
    SELECT id INTO _integration_disabled_override_id
      FROM public.organization_secret_overrides
     WHERE organization_id = _organization_id
       AND integration_id = _integration.id
       AND secret_name IS NULL
       AND is_disabled = true
     LIMIT 1;
    IF _integration_disabled_override_id IS NOT NULL THEN
      INSERT INTO public.tenant_secret_access_audit(
        tenant_id, organization_id, integration_id, actor_user_id, actor_type,
        action, reason, function_name, request_id, result, error_message
      ) VALUES (_tenant_id, _organization_id, _integration.id, auth.uid(), 'service',
                'failed', _reason, _function_name, _request_id, 'blocked',
                'organization_integration_disabled');
      RETURN jsonb_build_object('status','blocked','reason','organization_integration_disabled');
    END IF;

    SELECT * INTO _secret_override
      FROM public.organization_secret_overrides
     WHERE organization_id = _organization_id
       AND integration_id = _integration.id
       AND secret_name = _secret_name
     LIMIT 1;
    IF _secret_override.id IS NOT NULL THEN
      IF _secret_override.is_disabled THEN
        INSERT INTO public.tenant_secret_access_audit(
          tenant_id, organization_id, integration_id, actor_user_id, actor_type,
          action, reason, function_name, request_id, result, error_message
        ) VALUES (_tenant_id, _organization_id, _integration.id, auth.uid(), 'service',
                  'failed', _reason, _function_name, _request_id, 'blocked',
                  'organization_secret_disabled');
        RETURN jsonb_build_object('status','blocked','reason','organization_secret_disabled');
      END IF;
      IF _secret_override.secret_ref_id IS NOT NULL THEN
        SELECT * INTO _ref FROM public.tenant_secret_refs
         WHERE id = _secret_override.secret_ref_id
           AND tenant_id = _tenant_id
           AND integration_id = _integration.id
           AND organization_id = _organization_id
           AND secret_name = _secret_name
           AND secret_scope = 'organization_override'
           AND status = 'active';
        IF _ref.id IS NOT NULL THEN
          _selected_ref_id := _ref.id;
        END IF;
      END IF;
    END IF;
  END IF;

  IF _selected_ref_id IS NULL THEN
    SELECT * INTO _ref FROM public.tenant_secret_refs
     WHERE tenant_id = _tenant_id
       AND integration_id = _integration.id
       AND secret_name = _secret_name
       AND secret_scope = 'tenant'
       AND organization_id IS NULL
       AND status = 'active'
     LIMIT 1;
    IF _ref.id IS NOT NULL THEN
      _selected_ref_id := _ref.id;
    END IF;
  END IF;

  IF _selected_ref_id IS NULL THEN
    INSERT INTO public.tenant_secret_access_audit(
      tenant_id, organization_id, integration_id, actor_user_id, actor_type,
      action, reason, function_name, request_id, result, error_message
    ) VALUES (_tenant_id, _organization_id, _integration.id, auth.uid(), 'service',
              'failed', _reason, _function_name, _request_id, 'failure',
              'no_active_secret_ref');
    RETURN jsonb_build_object('status','not_found','reason','no_active_secret_ref');
  END IF;

  INSERT INTO public.tenant_secret_access_audit(
    tenant_id, organization_id, integration_id, secret_ref_id, actor_user_id, actor_type,
    action, reason, function_name, request_id, result
  ) VALUES (_tenant_id, _organization_id, _integration.id, _ref.id, auth.uid(), 'service',
            'resolved', _reason, _function_name, _request_id, 'success');

  RETURN jsonb_build_object(
    'status','ok',
    'integration_id', _integration.id,
    'integration_kind', _integration.kind,
    'integration_name', _integration.name,
    'secret_ref_id', _ref.id,
    'secret_name', _ref.secret_name,
    'secret_kind', _ref.secret_kind,
    'secret_scope', _ref.secret_scope,
    'organization_id', _ref.organization_id,
    'vault_secret_id', _ref.vault_secret_id,
    'fingerprint', _ref.secret_fingerprint,
    'config_metadata', _integration.config_metadata
  );
END $function$

CREATE OR REPLACE FUNCTION public.resolve_route_context_boundary(_workspace_id uuid DEFAULT NULL::uuid, _project_id uuid DEFAULT NULL::uuid, _program_id uuid DEFAULT NULL::uuid, _phase_id uuid DEFAULT NULL::uuid, _task_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _resolved_ws uuid;
  _resolved_org uuid;
  _object_type text := 'workspace';
  _object_id uuid;
  _org RECORD;
  _tenant RECORD;
  _ws RECORD;
  _task RECORD;
  _phase RECORD;
  _project RECORD;
  _program RECORD;
  _has_access boolean := false;
BEGIN
  IF _uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;

  IF _task_id IS NOT NULL THEN
    _object_type := 'task'; _object_id := _task_id;
    SELECT id, workspace_id, project_id, phase_id INTO _task FROM public.tasks WHERE id = _task_id;
    IF _task.id IS NULL THEN
      RETURN jsonb_build_object('has_access', false, 'object_type','task','object_id',_task_id,'not_found', true);
    END IF;
    _resolved_ws := _task.workspace_id;
    IF _project_id IS NOT NULL AND _task.project_id IS DISTINCT FROM _project_id THEN
      RETURN jsonb_build_object('has_access', false, 'object_type','task','object_id',_task_id,'inconsistent', true, 'reason','Task does not belong to the provided project');
    END IF;
    IF _phase_id IS NOT NULL AND _task.phase_id IS DISTINCT FROM _phase_id THEN
      RETURN jsonb_build_object('has_access', false, 'object_type','task','object_id',_task_id,'inconsistent', true, 'reason','Task does not belong to the provided phase');
    END IF;
  ELSIF _phase_id IS NOT NULL THEN
    _object_type := 'phase'; _object_id := _phase_id;
    SELECT id, workspace_id, project_id INTO _phase FROM public.phases WHERE id = _phase_id;
    IF _phase.id IS NULL THEN
      RETURN jsonb_build_object('has_access', false, 'object_type','phase','object_id',_phase_id,'not_found', true);
    END IF;
    _resolved_ws := _phase.workspace_id;
    IF _project_id IS NOT NULL AND _phase.project_id IS DISTINCT FROM _project_id THEN
      RETURN jsonb_build_object('has_access', false, 'object_type','phase','object_id',_phase_id,'inconsistent', true, 'reason','Phase does not belong to the provided project');
    END IF;
  ELSIF _project_id IS NOT NULL THEN
    _object_type := 'project'; _object_id := _project_id;
    SELECT id, workspace_id, program_id INTO _project FROM public.projects WHERE id = _project_id;
    IF _project.id IS NULL THEN
      RETURN jsonb_build_object('has_access', false, 'object_type','project','object_id',_project_id,'not_found', true);
    END IF;
    _resolved_ws := _project.workspace_id;
    IF _program_id IS NOT NULL AND _project.program_id IS DISTINCT FROM _program_id THEN
      RETURN jsonb_build_object('has_access', false, 'object_type','project','object_id',_project_id,'inconsistent', true, 'reason','Project does not belong to the provided program');
    END IF;
  ELSIF _program_id IS NOT NULL THEN
    _object_type := 'program'; _object_id := _program_id;
    SELECT id, workspace_id INTO _program FROM public.programs WHERE id = _program_id;
    IF _program.id IS NULL THEN
      RETURN jsonb_build_object('has_access', false, 'object_type','program','object_id',_program_id,'not_found', true);
    END IF;
    _resolved_ws := _program.workspace_id;
  ELSIF _workspace_id IS NOT NULL THEN
    _object_type := 'workspace'; _object_id := _workspace_id;
    _resolved_ws := _workspace_id;
  ELSE
    RAISE EXCEPTION 'At least one id must be provided';
  END IF;

  -- Workspace consistency: any explicit _workspace_id must match resolution
  IF _workspace_id IS NOT NULL AND _resolved_ws IS DISTINCT FROM _workspace_id THEN
    RETURN jsonb_build_object('has_access', false, 'object_type', _object_type, 'object_id', _object_id, 'inconsistent', true, 'reason','Object does not belong to the provided workspace');
  END IF;

  SELECT id, name, organization_id INTO _ws FROM public.workspaces WHERE id = _resolved_ws;
  IF _ws.id IS NULL THEN
    RETURN jsonb_build_object('has_access', false, 'object_type', _object_type, 'object_id', _object_id, 'not_found', true);
  END IF;
  _resolved_org := _ws.organization_id;

  SELECT id, name, tenant_id, environment_role, organization_kind, slug INTO _org FROM public.organizations WHERE id = _resolved_org;
  SELECT id, name, slug INTO _tenant FROM public.tenants WHERE id = _org.tenant_id;

  -- Operational route access: workspace member OR organization admin.
  -- Tenant-admin / platform-super-admin alone do NOT pass here.
  _has_access :=
       public.is_workspace_member(_uid, _resolved_ws)
    OR public.is_organization_admin(_resolved_org, _uid);

  IF NOT _has_access THEN
    RETURN jsonb_build_object(
      'has_access', false,
      'access_denied', true,
      'object_type', _object_type,
      'object_id', _object_id
    );
  END IF;

  RETURN jsonb_build_object(
    'has_access', true,
    'object_type', _object_type,
    'object_id', _object_id,
    'tenant_id', _tenant.id,
    'tenant_name', _tenant.name,
    'tenant_slug', _tenant.slug,
    'organization_id', _org.id,
    'organization_name', _org.name,
    'organization_slug', _org.slug,
    'environment_role', _org.environment_role,
    'organization_kind', _org.organization_kind,
    'workspace_id', _ws.id,
    'workspace_name', _ws.name
  );
END $function$

CREATE OR REPLACE FUNCTION public.restore_governance_cadence(_cadence_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _row governance_cadences%ROWTYPE;
BEGIN
  SELECT * INTO _row FROM governance_cadences WHERE id = _cadence_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Cadence not found' USING ERRCODE='P0002'; END IF;
  PERFORM _gov_assert_project_write(_row.project_id);
  IF _row.archived_at IS NOT NULL THEN
    UPDATE governance_cadences SET archived_at = NULL, archived_by = NULL, updated_at = now()
    WHERE id = _cadence_id;
    PERFORM log_activity_event(_row.organization_id, auth.uid(),
      'governance_cadence_restored', 'governance_cadence', _cadence_id,
      jsonb_build_object('project_id', _row.project_id), _row.workspace_id);
  END IF;
END; $function$

CREATE OR REPLACE FUNCTION public.restore_governance_record(_record_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _row governance_records%ROWTYPE;
BEGIN
  SELECT * INTO _row FROM governance_records WHERE id = _record_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Record not found' USING ERRCODE='P0002'; END IF;
  PERFORM _gov_assert_project_write(_row.project_id);
  IF _row.archived_at IS NOT NULL THEN
    UPDATE governance_records SET archived_at = NULL, archived_by = NULL, updated_at = now()
    WHERE id = _record_id;
    PERFORM log_activity_event(_row.organization_id, auth.uid(),
      'governance_record_restored', 'governance_record', _record_id,
      jsonb_build_object('project_id', _row.project_id), _row.workspace_id);
  END IF;
END; $function$

CREATE OR REPLACE FUNCTION public.restore_governance_record_btpm_context_link(_context_link_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
