CREATE OR REPLACE FUNCTION public.restore_project_people_preset(_preset_id uuid, _expected_updated_at timestamp with time zone, _correlation_id text DEFAULT NULL::text, _idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_preset public.project_people_presets;
  v_dupe uuid;
  r record;
  v_name_plain text;
BEGIN
  SELECT * INTO v_preset FROM public.project_people_presets WHERE id = _preset_id FOR UPDATE;
  IF v_preset.id IS NULL THEN
    RETURN public.pmg_build_result('not_authorized', 'restore_project_people_preset',
      'project_people_preset', NULL, NULL, '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL);
  END IF;
  -- restore acts on archived rows; skip _require_active
  PERFORM public._ppp_authorize_write(v_actor, v_preset, false);

  IF v_preset.archived_at IS NULL THEN
    RETURN public.pmg_build_result('no_change', 'restore_project_people_preset',
      'project_people_preset', _preset_id, NULL,
      jsonb_build_object('reason','not_archived'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL);
  END IF;

  IF v_preset.updated_at IS DISTINCT FROM _expected_updated_at THEN
    RETURN public.pmg_build_result('conflict', 'restore_project_people_preset',
      'project_people_preset', _preset_id, NULL, '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb,
      jsonb_build_object('server_updated_at', v_preset.updated_at));
  END IF;

  v_name_plain := lower(btrim(public.btpm_decrypt(v_preset.name, v_preset.organization_id)));
  FOR r IN
    SELECT id, name FROM public.project_people_presets
     WHERE workspace_id = v_preset.workspace_id
       AND archived_at IS NULL
       AND id <> _preset_id
     FOR UPDATE
  LOOP
    IF lower(btrim(public.btpm_decrypt(r.name, v_preset.organization_id))) = v_name_plain THEN
      v_dupe := r.id; EXIT;
    END IF;
  END LOOP;

  IF v_dupe IS NOT NULL THEN
    RETURN public.pmg_build_result('invalid', 'restore_project_people_preset',
      'project_people_preset', _preset_id, NULL,
      jsonb_build_object('reason','duplicate_active_name'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL);
  END IF;

  UPDATE public.project_people_presets
     SET archived_at = NULL, archived_by = NULL
   WHERE id = _preset_id;

  PERFORM public._ppp_record_audit('applied', 'restore_project_people_preset',
    v_preset, 'project_people_preset', _preset_id, _correlation_id, _idempotency_key, '{}'::jsonb);

  RETURN public.pmg_build_result('applied', 'restore_project_people_preset',
    'project_people_preset', _preset_id, NULL,
    jsonb_build_object('id', _preset_id),
    '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL);
END; $function$

CREATE OR REPLACE FUNCTION public.restore_project_stakeholder(_stakeholder_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_row public.project_stakeholders;
  v_display text;
BEGIN
  IF v_actor IS NULL OR NOT public.is_active_user(v_actor) THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT *
  INTO v_row
  FROM public.project_stakeholders
  WHERE id = _stakeholder_id;

  IF v_row.id IS NULL THEN
    RAISE EXCEPTION 'Stakeholder not found';
  END IF;

  IF NOT (public.is_org_admin(v_actor, v_row.organization_id) OR public.has_pm_authority(v_actor, v_row.workspace_id)) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  IF v_row.removed_at IS NULL THEN
    RETURN;
  END IF;

  IF v_row.stakeholder_type = 'workspace_member' AND EXISTS (
    SELECT 1
    FROM public.project_stakeholders
    WHERE project_id = v_row.project_id
      AND stakeholder_type = 'workspace_member'
      AND user_id = v_row.user_id
      AND removed_at IS NULL
      AND id <> _stakeholder_id
  ) THEN
    RAISE EXCEPTION 'An active stakeholder already exists for this member';
  END IF;

  UPDATE public.project_stakeholders
  SET removed_at = NULL, removed_by = NULL
  WHERE id = _stakeholder_id;

  IF v_row.stakeholder_type = 'workspace_member' THEN
    SELECT COALESCE(display_name, email, v_row.user_id::text)
    INTO v_display
    FROM public.profiles
    WHERE id = v_row.user_id;
  ELSE
    v_display := v_row.external_name;
  END IF;

  PERFORM public.log_activity_event(
    v_row.organization_id,
    v_actor,
    'stakeholder_restored',
    'project',
    v_row.project_id,
    jsonb_build_object(
      'stakeholder_id', _stakeholder_id,
      'stakeholder_type', v_row.stakeholder_type,
      'display_name', v_display,
      'role_label', v_row.role_label,
      'start_date', v_row.start_date
    ),
    v_row.workspace_id
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.revoke_api_d_policy(_client_key text, _correlation_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  _uid uuid := auth.uid();
  _client public.api_clients%rowtype;
  _policy public.api_client_policy_versions%rowtype;
  _policy_count integer;
  _org_count integer;
  _existing public.api_user_policy_acknowledgements%rowtype;
  _fail_closed constant jsonb := jsonb_build_object('ok', false, 'changed', false, 'acknowledged', false);
begin
  if _uid is null then return _fail_closed; end if;

  if _client_key is null
     or length(_client_key) < 3 or length(_client_key) > 64
     or _client_key !~ '^[a-z0-9][a-z0-9_.-]{1,62}[a-z0-9]$' then
    return _fail_closed;
  end if;

  if _correlation_id is not null
     and _correlation_id !~ '^[A-Za-z0-9_-]{1,64}$' then
    return _fail_closed;
  end if;

  if not exists (
    select 1 from public.profiles p
    where p.id = _uid and p.is_active = true
  ) then
    return _fail_closed;
  end if;

  select * into _client
  from public.api_clients
  where client_key = _client_key and lifecycle_status = 'active'
  limit 1;
  if _client.id is null then return _fail_closed; end if;

  select count(*) into _policy_count
  from public.api_client_policy_versions
  where api_client_id = _client.id and lifecycle_status = 'active';
  if _policy_count <> 1 then return _fail_closed; end if;

  select * into _policy
  from public.api_client_policy_versions
  where api_client_id = _client.id and lifecycle_status = 'active'
  limit 1;

  select count(*) into _org_count
  from public.organization_memberships om
  join public.organizations o
    on o.id = om.organization_id
  join public.tenants t
    on t.id = o.tenant_id
   and t.id = om.tenant_id
  join public.tenant_memberships tm_o
    on tm_o.tenant_id = t.id
   and tm_o.user_id = _uid
   and tm_o.status = 'active'
   and tm_o.deactivated_at is null
  join public.api_organization_client_enablements oe
    on oe.organization_id = o.id
   and oe.tenant_id = t.id
   and oe.api_client_id = _client.id
   and oe.lifecycle_status = 'enabled'
  where om.user_id = _uid
    and om.status = 'active'
    and om.deactivated_at is null
    and t.status = 'active'
    and t.suspended_at is null
    and t.archived_at is null
    and t.purged_at is null;

  if _org_count = 0 then return _fail_closed; end if;

  select * into _existing
  from public.api_user_policy_acknowledgements
  where user_id = _uid
    and api_client_id = _client.id
    and policy_version_id = _policy.id
  limit 1;

  if _existing.id is null or _existing.revoked_at is not null then
    -- Idempotent no-op — do not append an audit row and never delete.
    return jsonb_build_object('ok', true, 'changed', false, 'acknowledged', false);
  end if;

  update public.api_user_policy_acknowledgements
     set revoked_at = now()
   where id = _existing.id;

  insert into public.api_consent_audit_events
    (actor_user_id, api_client_id, policy_version_id, action, source_channel, correlation_id)
  values
    (_uid, _client.id, _policy.id, 'revoke', 'btpm_ui', _correlation_id);

  return jsonb_build_object('ok', true, 'changed', true, 'acknowledged', false);
exception
  when others then
    return _fail_closed;
end;
$function$

CREATE OR REPLACE FUNCTION public.save_ai_decision_brief_version(_record_id uuid, _ai_run_id uuid, _edited_brief_text text, _make_current boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  _row public.governance_records%ROWTYPE;
  _run public.decision_case_ai_runs%ROWTYPE;
  _next int;
  _id uuid;
  _edited text;
BEGIN
  SELECT * INTO _row FROM public.governance_records WHERE id = _record_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Record not found' USING ERRCODE='P0002'; END IF;
  IF _row.record_kind IS DISTINCT FROM 'decision_case' THEN
    RAISE EXCEPTION 'Brief versions are only allowed on decision_case records' USING ERRCODE='22023';
  END IF;
  PERFORM public._gov_assert_project_write(_row.project_id);

  SELECT * INTO _run FROM public.decision_case_ai_runs WHERE id = _ai_run_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'AI run not found' USING ERRCODE='P0002'; END IF;
  IF _run.governance_record_id <> _record_id THEN
    RAISE EXCEPTION 'AI run does not belong to this record' USING ERRCODE='22023';
  END IF;
  IF _run.status NOT IN ('completed') THEN
    RAISE EXCEPTION 'AI run is not in a saveable state (status=%)', _run.status USING ERRCODE='22023';
  END IF;
  IF _run.brief_version_id IS NOT NULL THEN
    RAISE EXCEPTION 'AI run is already linked to a brief version' USING ERRCODE='22023';
  END IF;

  _edited := NULLIF(trim(COALESCE(_edited_brief_text, '')), '');
  IF _edited IS NULL THEN
    RAISE EXCEPTION 'edited_brief_text is required' USING ERRCODE='22023';
  END IF;

  SELECT COALESCE(MAX(version_number), 0) + 1 INTO _next
    FROM public.governance_record_brief_versions
    WHERE governance_record_id = _record_id;

  IF COALESCE(_make_current, false) THEN
    UPDATE public.governance_record_brief_versions
      SET is_current = false, updated_by = auth.uid(), updated_at = now()
      WHERE governance_record_id = _record_id AND is_current = true;
  END IF;

  INSERT INTO public.governance_record_brief_versions (
    organization_id, workspace_id, project_id, governance_record_id,
    version_number, source_type, is_current,
    edited_brief_text,
    created_by, updated_by
  ) VALUES (
    _row.organization_id, _row.workspace_id, _row.project_id, _record_id,
    _next, 'btpm_generated', COALESCE(_make_current, false),
    _edited,
    auth.uid(), auth.uid()
  ) RETURNING id INTO _id;

  UPDATE public.decision_case_ai_runs
    SET status = 'saved',
        saved_at = now(),
        brief_version_id = _id,
        updated_at = now()
    WHERE id = _ai_run_id;

  PERFORM public.log_activity_event(_row.organization_id, auth.uid(),
    'governance_record_brief_version_created', 'governance_record', _record_id,
    jsonb_build_object('project_id', _row.project_id,
                       'brief_version_id', _id,
                       'version_number', _next,
                       'source_type', 'btpm_generated',
                       'is_current', COALESCE(_make_current, false),
                       'ai_run_id', _ai_run_id),
    _row.workspace_id);

  PERFORM public.log_activity_event(_row.organization_id, auth.uid(),
    'decision_case_ai_run_saved', 'governance_record', _record_id,
    jsonb_build_object('project_id', _row.project_id,
                       'ai_run_id', _ai_run_id,
                       'brief_version_id', _id),
    _row.workspace_id);

  RETURN jsonb_build_object('brief_version_id', _id, 'version_number', _next, 'ai_run_id', _ai_run_id);
END; $function$

CREATE OR REPLACE FUNCTION public.save_ai_decision_brief_version_v2(_record_id uuid, _ai_run_id uuid, _edited_brief_text text, _make_current boolean DEFAULT false, _recommendation_text text DEFAULT NULL::text, _requested_decision_text text DEFAULT NULL::text, _guardrails_text text DEFAULT NULL::text, _residual_risks_text text DEFAULT NULL::text, _open_questions_text text DEFAULT NULL::text, _confidence_level text DEFAULT NULL::text, _decision_readiness text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  _row public.governance_records%ROWTYPE;
  _run public.decision_case_ai_runs%ROWTYPE;
  _next int;
  _id uuid;
  _edited text;
  _conf text;
  _ready text;
BEGIN
  SELECT * INTO _row FROM public.governance_records WHERE id = _record_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Record not found' USING ERRCODE='P0002'; END IF;
  IF _row.record_kind IS DISTINCT FROM 'decision_case' THEN
    RAISE EXCEPTION 'Brief versions are only allowed on decision_case records' USING ERRCODE='22023';
  END IF;
  PERFORM public._gov_assert_project_write(_row.project_id);

  SELECT * INTO _run FROM public.decision_case_ai_runs WHERE id = _ai_run_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'AI run not found' USING ERRCODE='P0002'; END IF;
  IF _run.governance_record_id <> _record_id THEN
    RAISE EXCEPTION 'AI run does not belong to this record' USING ERRCODE='22023';
  END IF;
  IF _run.status NOT IN ('completed') THEN
    RAISE EXCEPTION 'AI run is not in a saveable state (status=%)', _run.status USING ERRCODE='22023';
  END IF;
  IF _run.brief_version_id IS NOT NULL THEN
    RAISE EXCEPTION 'AI run is already linked to a brief version' USING ERRCODE='22023';
  END IF;

  _edited := NULLIF(trim(COALESCE(_edited_brief_text, '')), '');
  IF _edited IS NULL THEN
    RAISE EXCEPTION 'edited_brief_text is required' USING ERRCODE='22023';
  END IF;

  _conf := NULLIF(trim(COALESCE(_confidence_level, '')), '');
  IF _conf IS NOT NULL AND _conf NOT IN ('high','medium','low') THEN
    RAISE EXCEPTION 'Invalid confidence_level: %', _conf USING ERRCODE='22023';
  END IF;
  _ready := NULLIF(trim(COALESCE(_decision_readiness, '')), '');
  IF _ready IS NOT NULL AND _ready NOT IN ('ready_for_decision','needs_clarification','not_ready') THEN
    RAISE EXCEPTION 'Invalid decision_readiness: %', _ready USING ERRCODE='22023';
  END IF;

  SELECT COALESCE(MAX(version_number), 0) + 1 INTO _next
    FROM public.governance_record_brief_versions
    WHERE governance_record_id = _record_id;

  IF COALESCE(_make_current, false) THEN
    UPDATE public.governance_record_brief_versions
      SET is_current = false, updated_by = auth.uid(), updated_at = now()
      WHERE governance_record_id = _record_id AND is_current = true;
  END IF;

  INSERT INTO public.governance_record_brief_versions (
    organization_id, workspace_id, project_id, governance_record_id,
    version_number, source_type, is_current,
    edited_brief_text,
    recommendation_text, requested_decision_text,
    guardrails_text, residual_risks_text,
    open_questions_text, confidence_level, decision_readiness,
    created_by, updated_by
  ) VALUES (
    _row.organization_id, _row.workspace_id, _row.project_id, _record_id,
    _next, 'btpm_generated', COALESCE(_make_current, false),
    _edited,
    NULLIF(trim(COALESCE(_recommendation_text,'')),''),
    NULLIF(trim(COALESCE(_requested_decision_text,'')),''),
    NULLIF(trim(COALESCE(_guardrails_text,'')),''),
    NULLIF(trim(COALESCE(_residual_risks_text,'')),''),
    NULLIF(trim(COALESCE(_open_questions_text,'')),''),
    _conf,
    _ready,
    auth.uid(), auth.uid()
  ) RETURNING id INTO _id;

  UPDATE public.decision_case_ai_runs
    SET status = 'saved',
        saved_at = now(),
        brief_version_id = _id,
        updated_at = now()
    WHERE id = _ai_run_id;

  PERFORM public.log_activity_event(_row.organization_id, auth.uid(),
    'governance_record_brief_version_created', 'governance_record', _record_id,
    jsonb_build_object('project_id', _row.project_id,
                       'brief_version_id', _id,
                       'version_number', _next,
                       'source_type', 'btpm_generated',
                       'is_current', COALESCE(_make_current, false),
                       'ai_run_id', _ai_run_id,
                       'has_structured_fields', true),
    _row.workspace_id);

  PERFORM public.log_activity_event(_row.organization_id, auth.uid(),
    'decision_case_ai_run_saved', 'governance_record', _record_id,
    jsonb_build_object('project_id', _row.project_id,
                       'ai_run_id', _ai_run_id,
                       'brief_version_id', _id),
    _row.workspace_id);

  RETURN jsonb_build_object('brief_version_id', _id, 'version_number', _next, 'ai_run_id', _ai_run_id);
END; $function$

CREATE OR REPLACE FUNCTION public.save_decision_brief_version_v3(_record_id uuid, _source_type text, _edited_brief_text text DEFAULT NULL::text, _make_current boolean DEFAULT true, _ai_run_id uuid DEFAULT NULL::uuid, _executive_intro_text text DEFAULT NULL::text, _options_summary text DEFAULT NULL::text, _requested_decision_text text DEFAULT NULL::text, _recommendation_text text DEFAULT NULL::text, _guardrails_text text DEFAULT NULL::text, _residual_risks_text text DEFAULT NULL::text, _open_questions_text text DEFAULT NULL::text, _confidence_level text DEFAULT NULL::text, _decision_readiness text DEFAULT NULL::text)
