DECLARE
  _row public.governance_records%ROWTYPE;
  _run public.decision_case_ai_runs%ROWTYPE;
  _next int;
  _id uuid;
  _edited text;
  _intro text; _opts text; _req text; _rec text; _grd text; _rsk text; _oq text;
  _conf text; _ready text;
  _src text;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE='42501';
  END IF;

  SELECT * INTO _row FROM public.governance_records WHERE id = _record_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Record not found' USING ERRCODE='P0002'; END IF;
  IF _row.record_kind IS DISTINCT FROM 'decision_case' THEN
    RAISE EXCEPTION 'Brief versions are only allowed on decision_case records' USING ERRCODE='22023';
  END IF;
  PERFORM public._gov_assert_project_write(_row.project_id);

  _src := NULLIF(trim(COALESCE(_source_type, '')), '');
  IF _src IS NULL OR _src NOT IN ('btpm_generated','manual_edit','copilot_paste') THEN
    RAISE EXCEPTION 'Invalid source_type %', _source_type USING ERRCODE='22023';
  END IF;

  IF _ai_run_id IS NOT NULL THEN
    SELECT * INTO _run FROM public.decision_case_ai_runs WHERE id = _ai_run_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'AI run not found' USING ERRCODE='P0002'; END IF;
    IF _run.governance_record_id <> _record_id THEN
      RAISE EXCEPTION 'AI run does not belong to this record' USING ERRCODE='22023';
    END IF;
    IF _run.status NOT IN ('completed','saved') THEN
      RAISE EXCEPTION 'AI run is not in a saveable state (status=%)', _run.status USING ERRCODE='22023';
    END IF;
  END IF;

  _edited := NULLIF(trim(COALESCE(_edited_brief_text, '')), '');
  _intro  := NULLIF(trim(COALESCE(_executive_intro_text, '')), '');
  _opts   := NULLIF(trim(COALESCE(_options_summary, '')), '');
  _req    := NULLIF(trim(COALESCE(_requested_decision_text, '')), '');
  _rec    := NULLIF(trim(COALESCE(_recommendation_text, '')), '');
  _grd    := NULLIF(trim(COALESCE(_guardrails_text, '')), '');
  _rsk    := NULLIF(trim(COALESCE(_residual_risks_text, '')), '');
  _oq     := NULLIF(trim(COALESCE(_open_questions_text, '')), '');

  IF _edited IS NULL AND _intro IS NULL AND _opts IS NULL AND _req IS NULL
     AND _rec IS NULL AND _grd IS NULL AND _rsk IS NULL AND _oq IS NULL THEN
    RAISE EXCEPTION 'At least one brief field is required' USING ERRCODE='22023';
  END IF;

  _conf := NULLIF(trim(COALESCE(_confidence_level, '')), '');
  IF _conf IS NOT NULL AND _conf NOT IN ('high','medium','low') THEN
    RAISE EXCEPTION 'Invalid confidence_level: %', _conf USING ERRCODE='22023';
  END IF;
  _ready := NULLIF(trim(COALESCE(_decision_readiness, '')), '');
  IF _ready IS NOT NULL AND _ready NOT IN ('ready_for_decision','needs_clarification','not_ready') THEN
    RAISE EXCEPTION 'Invalid decision_readiness: %', _ready USING ERRCODE='22023';
  END IF;

  SELECT COALESCE(MAX(version_number), 0) + 1 INTO _next
    FROM public.governance_record_brief_versions
    WHERE governance_record_id = _record_id;

  IF COALESCE(_make_current, true) THEN
    UPDATE public.governance_record_brief_versions
      SET is_current = false, updated_by = auth.uid(), updated_at = now()
      WHERE governance_record_id = _record_id AND is_current = true;
  END IF;

  INSERT INTO public.governance_record_brief_versions (
    organization_id, workspace_id, project_id, governance_record_id,
    version_number, source_type, is_current,
    edited_brief_text,
    executive_intro_text, options_summary,
    requested_decision_text, recommendation_text,
    guardrails_text, residual_risks_text,
    open_questions_text, confidence_level, decision_readiness,
    created_by, updated_by
  ) VALUES (
    _row.organization_id, _row.workspace_id, _row.project_id, _record_id,
    _next, _src, COALESCE(_make_current, true),
    _edited,
    _intro, _opts,
    _req, _rec,
    _grd, _rsk,
    _oq, _conf, _ready,
    auth.uid(), auth.uid()
  ) RETURNING id INTO _id;

  IF _ai_run_id IS NOT NULL AND _run.status = 'completed' THEN
    UPDATE public.decision_case_ai_runs
      SET status = 'saved',
          saved_at = now(),
          brief_version_id = _id,
          updated_at = now()
      WHERE id = _ai_run_id AND brief_version_id IS NULL;
  END IF;

  PERFORM public.log_activity_event(_row.organization_id, auth.uid(),
    'governance_record_brief_version_created', 'governance_record', _record_id,
    jsonb_build_object('project_id', _row.project_id,
                       'brief_version_id', _id,
                       'version_number', _next,
                       'source_type', _src,
                       'is_current', COALESCE(_make_current, true),
                       'ai_run_id', _ai_run_id,
                       'has_structured_fields', true,
                       'rpc', 'save_decision_brief_version_v3'),
    _row.workspace_id);

  RETURN jsonb_build_object(
    'brief_version_id', _id,
    'version_number', _next,
    'ai_run_id', _ai_run_id
  );
END; $function$

CREATE OR REPLACE FUNCTION public.save_project_template_from_project(_project_id uuid, _template_name text, _template_description text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE _caller uuid := auth.uid(); _org uuid; _ws uuid; _blueprint jsonb; _new_id uuid; _agile jsonb; _counts jsonb;
BEGIN
  IF _caller IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE='42501'; END IF;
  IF _template_name IS NULL OR length(trim(_template_name)) = 0 THEN
    RAISE EXCEPTION 'template_name required' USING ERRCODE='22023'; END IF;
  SELECT p.organization_id, p.workspace_id INTO _org, _ws FROM public.projects p WHERE p.id = _project_id;
  IF _org IS NULL THEN RAISE EXCEPTION 'project not found' USING ERRCODE='P0002'; END IF;
  IF NOT public.has_project_pm_authority(_caller, _project_id) THEN
    RAISE EXCEPTION 'access denied: PM authority required' USING ERRCODE='42501'; END IF;
  _blueprint := public.preview_project_clone_blueprint(_project_id);
  IF _blueprint IS NULL OR _blueprint->>'version' <> 'clone_blueprint_v1'
     OR _blueprint->>'blueprint_kind' <> 'project' THEN
    RAISE EXCEPTION 'invalid blueprint payload returned by preview_project_clone_blueprint' USING ERRCODE='22023'; END IF;
  INSERT INTO public.project_templates (organization_id, workspace_id, source_project_id,
    name, description, blueprint_payload, blueprint_version, created_by, updated_by)
  VALUES (_org, _ws, _project_id, _template_name, _template_description, _blueprint::text,
    'clone_blueprint_v1', _caller, _caller) RETURNING id INTO _new_id;
  BEGIN
    PERFORM public.log_activity_event(_caller, 'project_template_created',
      jsonb_build_object('source_project_id', _project_id, 'workspace_id', _ws,
        'blueprint_version', 'clone_blueprint_v1'),
      _org, _new_id, 'project_template', _ws);
  EXCEPTION WHEN OTHERS THEN NULL; END;
  _agile := COALESCE(_blueprint->'agile', '{}'::jsonb);
  _counts := jsonb_build_object(
    'phases', jsonb_array_length(COALESCE(_blueprint->'phases', '[]'::jsonb)),
    'tasks', jsonb_array_length(COALESCE(_blueprint->'tasks', '[]'::jsonb)),
    'dependencies', jsonb_array_length(COALESCE(_blueprint->'dependencies', '[]'::jsonb)),
    'kpi_definitions', jsonb_array_length(COALESCE(_blueprint->'kpi_definitions', '[]'::jsonb)),
    'workflow_states', jsonb_array_length(COALESCE(_agile->'workflow_states', '[]'::jsonb)),
    'sprints', jsonb_array_length(COALESCE(_agile->'sprints', '[]'::jsonb)),
    'backlog_items', jsonb_array_length(COALESCE(_agile->'backlog_items', '[]'::jsonb)));
  RETURN jsonb_build_object('template_id', _new_id, 'organization_id', _org,
    'workspace_id', _ws, 'source_project_id', _project_id,
    'blueprint_version', 'clone_blueprint_v1', 'template_name', _template_name,
    'schedule_mode', _blueprint->>'schedule_mode', 'copied_counts', _counts);
END; $function$

CREATE OR REPLACE FUNCTION public.service_enqueue_tenant_background_job(_tenant_id uuid, _job_type text, _payload jsonb DEFAULT '{}'::jsonb, _organization_id uuid DEFAULT NULL::uuid, _workspace_id uuid DEFAULT NULL::uuid, _priority integer DEFAULT 100, _idempotency_key text DEFAULT NULL::text, _max_attempts integer DEFAULT 3, _not_before timestamp with time zone DEFAULT NULL::timestamp with time zone, _requested_by uuid DEFAULT NULL::uuid, _run_as_user_id uuid DEFAULT NULL::uuid)
 RETURNS tenant_background_jobs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _row public.tenant_background_jobs;
  _org_tenant uuid;
BEGIN
  IF _tenant_id IS NULL THEN RAISE EXCEPTION 'tenant_id is required'; END IF;
  IF _job_type IS NULL OR length(btrim(_job_type)) = 0 THEN RAISE EXCEPTION 'job_type is required'; END IF;
  IF jsonb_typeof(COALESCE(_payload, '{}'::jsonb)) <> 'object' THEN
    RAISE EXCEPTION 'payload must be a JSON object';
  END IF;
  PERFORM public._assert_job_payload_no_secret_keys(COALESCE(_payload, '{}'::jsonb));

  IF _organization_id IS NOT NULL THEN
    SELECT tenant_id INTO _org_tenant FROM public.organizations WHERE id = _organization_id;
    IF _org_tenant IS NULL OR _org_tenant <> _tenant_id THEN
      RAISE EXCEPTION 'Organization % does not belong to tenant %', _organization_id, _tenant_id;
    END IF;
  END IF;

  IF _requested_by IS NOT NULL THEN
    IF NOT public.is_tenant_member(_tenant_id, _requested_by) THEN
      RAISE EXCEPTION 'requested_by is not an active tenant member';
    END IF;
    IF _organization_id IS NOT NULL
       AND NOT public.is_organization_member(_organization_id, _requested_by) THEN
      RAISE EXCEPTION 'requested_by is not an active organization member';
    END IF;
    IF _workspace_id IS NOT NULL
       AND NOT public.is_workspace_member(_requested_by, _workspace_id) THEN
      RAISE EXCEPTION 'requested_by is not an active workspace member';
    END IF;
  END IF;

  IF _run_as_user_id IS NOT NULL THEN
    IF NOT public.is_tenant_member(_tenant_id, _run_as_user_id) THEN
      RAISE EXCEPTION 'run_as_user_id is not an active tenant member';
    END IF;
    IF _organization_id IS NOT NULL
       AND NOT public.is_organization_member(_organization_id, _run_as_user_id) THEN
      RAISE EXCEPTION 'run_as_user_id is not an active organization member';
    END IF;
    IF _workspace_id IS NOT NULL
       AND NOT public.is_workspace_member(_run_as_user_id, _workspace_id) THEN
      RAISE EXCEPTION 'run_as_user_id is not an active workspace member';
    END IF;
  END IF;

  IF _idempotency_key IS NOT NULL THEN
    SELECT * INTO _row FROM public.tenant_background_jobs
      WHERE tenant_id = _tenant_id AND job_type = _job_type AND idempotency_key = _idempotency_key;
    IF _row.id IS NOT NULL THEN RETURN _row; END IF;
  END IF;

  INSERT INTO public.tenant_background_jobs (
    tenant_id, organization_id, workspace_id, job_type, priority,
    requested_by, run_as_user_id, idempotency_key, payload, max_attempts, not_before
  ) VALUES (
    _tenant_id, _organization_id, _workspace_id, _job_type, COALESCE(_priority, 100),
    _requested_by, _run_as_user_id, _idempotency_key, COALESCE(_payload, '{}'::jsonb),
    COALESCE(_max_attempts, 3), _not_before
  ) RETURNING * INTO _row;
  RETURN _row;
END $function$

CREATE OR REPLACE FUNCTION public.service_get_tenant_protected_download_context(_storage_object_id uuid, _requested_by uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _o public.tenant_storage_objects;
BEGIN
  SELECT * INTO _o FROM public.tenant_storage_objects WHERE id = _storage_object_id;
  IF _o.id IS NULL THEN RAISE EXCEPTION 'Storage object % not found', _storage_object_id; END IF;

  IF _requested_by IS NOT NULL THEN
    IF NOT public.is_tenant_member(_o.tenant_id, _requested_by) THEN
      RAISE EXCEPTION 'requested_by is not an active tenant member';
    END IF;
    IF NOT public.is_organization_member(_o.organization_id, _requested_by) THEN
      RAISE EXCEPTION 'requested_by is not an active organization member';
    END IF;
    IF _o.workspace_id IS NOT NULL
       AND NOT public.is_workspace_member(_requested_by, _o.workspace_id) THEN
      RAISE EXCEPTION 'requested_by is not an active workspace member';
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'storage_object_id', _o.id,
    'tenant_id', _o.tenant_id,
    'organization_id', _o.organization_id,
    'workspace_id', _o.workspace_id,
    'bucket', _o.bucket,
    'object_path', _o.object_path,
    'file_name', _o.file_name,
    'content_type', _o.content_type,
    'size_bytes', _o.size_bytes,
    'storage_status', _o.storage_status
  );
END $function$

CREATE OR REPLACE FUNCTION public.service_register_tenant_storage_object(_tenant_id uuid, _organization_id uuid, _bucket text, _surface text, _object_type text, _file_name text, _workspace_id uuid DEFAULT NULL::uuid, _object_id uuid DEFAULT NULL::uuid, _content_type text DEFAULT NULL::text, _size_bytes bigint DEFAULT NULL::bigint, _checksum text DEFAULT NULL::text, _metadata jsonb DEFAULT '{}'::jsonb, _legacy_object_path text DEFAULT NULL::text, _created_by uuid DEFAULT NULL::uuid)
 RETURNS tenant_storage_objects
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _row public.tenant_storage_objects;
  _path text;
  _bucket_seg text;
BEGIN
  IF _tenant_id IS NULL OR _organization_id IS NULL THEN
    RAISE EXCEPTION 'tenant_id and organization_id are required';
  END IF;

  _bucket_seg := public._sanitize_storage_segment(_bucket);
  IF _bucket_seg IS NULL THEN RAISE EXCEPTION 'bucket is required'; END IF;

  IF _created_by IS NOT NULL THEN
    IF NOT public.is_tenant_member(_tenant_id, _created_by) THEN
      RAISE EXCEPTION 'created_by user is not an active tenant member';
    END IF;
    IF NOT public.is_organization_member(_organization_id, _created_by) THEN
      RAISE EXCEPTION 'created_by user is not an active organization member';
    END IF;
    IF _workspace_id IS NOT NULL
       AND NOT public.is_workspace_member(_created_by, _workspace_id) THEN
      RAISE EXCEPTION 'created_by user is not an active workspace member';
    END IF;
  END IF;

  _path := public.build_tenant_storage_path(
    _tenant_id, _organization_id, _workspace_id, _surface, _object_type, _object_id, _file_name
  );

  INSERT INTO public.tenant_storage_objects (
    tenant_id, organization_id, workspace_id, bucket, object_path, legacy_object_path,
    surface, object_type, object_id, file_name, content_type, size_bytes, checksum,
    storage_status, created_by, updated_by, metadata
  ) VALUES (
    _tenant_id, _organization_id, _workspace_id, _bucket_seg, _path, _legacy_object_path,
    _surface, _object_type, _object_id, _file_name, _content_type, _size_bytes, _checksum,
    'pending', _created_by, _created_by, COALESCE(_metadata, '{}'::jsonb)
  )
  ON CONFLICT (bucket, object_path) DO UPDATE
     SET updated_by = COALESCE(_created_by, public.tenant_storage_objects.updated_by),
         updated_at = now(),
         metadata = COALESCE(EXCLUDED.metadata, public.tenant_storage_objects.metadata)
  RETURNING * INTO _row;
  RETURN _row;
END $function$

CREATE OR REPLACE FUNCTION public.set_current_governance_record_brief_version(_brief_version_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  _v public.governance_record_brief_versions%ROWTYPE;
  _row public.governance_records%ROWTYPE;
BEGIN
  SELECT * INTO _v FROM public.governance_record_brief_versions WHERE id = _brief_version_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Brief version not found' USING ERRCODE='P0002'; END IF;
  SELECT * INTO _row FROM public.governance_records WHERE id = _v.governance_record_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Parent record not found' USING ERRCODE='P0002'; END IF;
  IF _row.record_kind IS DISTINCT FROM 'decision_case' THEN
    RAISE EXCEPTION 'Brief versions are only allowed on decision_case records' USING ERRCODE='22023';
  END IF;
  PERFORM public._gov_assert_project_write(_row.project_id);

  UPDATE public.governance_record_brief_versions
    SET is_current = false, updated_by = auth.uid(), updated_at = now()
    WHERE governance_record_id = _v.governance_record_id AND is_current = true AND id <> _brief_version_id;

  UPDATE public.governance_record_brief_versions
    SET is_current = true, updated_by = auth.uid(), updated_at = now()
    WHERE id = _brief_version_id;

  PERFORM public.log_activity_event(_row.organization_id, auth.uid(),
    'governance_record_brief_version_set_current', 'governance_record', _v.governance_record_id,
    jsonb_build_object('project_id', _row.project_id,
                       'brief_version_id', _brief_version_id,
                       'version_number', _v.version_number),
    _row.workspace_id);
END; $function$

CREATE OR REPLACE FUNCTION public.set_current_governance_record_copilot_data_package(_package_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  _p public.governance_record_copilot_data_packages%ROWTYPE;
  _row public.governance_records%ROWTYPE;
  _sp_id uuid;
BEGIN
  SELECT * INTO _p FROM public.governance_record_copilot_data_packages WHERE id = _package_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Data package not found' USING ERRCODE='P0002'; END IF;
  SELECT * INTO _row FROM public.governance_records WHERE id = _p.governance_record_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Parent record not found' USING ERRCODE='P0002'; END IF;
  IF _row.record_kind IS DISTINCT FROM 'decision_case' THEN
    RAISE EXCEPTION 'Data packages are only allowed on decision_case records' USING ERRCODE='22023';
  END IF;
  PERFORM public._gov_assert_project_write(_row.project_id);
  FOREACH _sp_id IN ARRAY _p.source_project_ids LOOP
    IF NOT public.has_project_access(auth.uid(), _sp_id) THEN
      RAISE EXCEPTION 'You do not have access to source project %', _sp_id USING ERRCODE='42501';
    END IF;
  END LOOP;

  UPDATE public.governance_record_copilot_data_packages
    SET is_current = false, package_status = CASE WHEN package_status = 'prepared' THEN 'superseded' ELSE package_status END
    WHERE governance_record_id = _p.governance_record_id AND is_current = true AND id <> _package_id;

  UPDATE public.governance_record_copilot_data_packages
    SET is_current = true
    WHERE id = _package_id;

  PERFORM public.log_activity_event(_row.organization_id, auth.uid(),
    'governance_record_copilot_data_package_set_current', 'governance_record', _p.governance_record_id,
    jsonb_build_object('project_id', _row.project_id,
                       'data_package_id', _package_id,
                       'version_number', _p.version_number),
    _row.workspace_id);
END; $function$

