CREATE OR REPLACE FUNCTION public.set_governance_record_decisions(_record_id uuid, _decisions jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  _row governance_records%ROWTYPE;
  _d jsonb;
  _count int := 0;
  _stakeholder_id uuid;
  _stakeholder_type text;
  _stakeholder_user uuid;
  _owner_user uuid;
BEGIN
  SELECT * INTO _row FROM governance_records WHERE id = _record_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Record not found' USING ERRCODE='P0002'; END IF;
  PERFORM _gov_assert_project_write(_row.project_id);
  IF _decisions IS NULL OR jsonb_typeof(_decisions) <> 'array' THEN
    RAISE EXCEPTION 'Decisions payload must be a JSON array' USING ERRCODE='22023';
  END IF;
  DELETE FROM governance_record_decisions WHERE governance_record_id = _record_id;
  FOR _d IN SELECT * FROM jsonb_array_elements(_decisions) LOOP
    IF NULLIF(trim(_d->>'decision_text'),'') IS NULL THEN
      RAISE EXCEPTION 'decision_text is required' USING ERRCODE='22023';
    END IF;

    _stakeholder_id := NULLIF(_d->>'decision_owner_stakeholder_id','')::uuid;
    _stakeholder_type := NULL;
    _stakeholder_user := NULL;
    _owner_user := NULLIF(_d->>'decision_owner_id','')::uuid;

    IF _stakeholder_id IS NOT NULL THEN
      SELECT s.stakeholder_type, s.user_id
        INTO _stakeholder_type, _stakeholder_user
        FROM project_stakeholders s
        WHERE s.id = _stakeholder_id AND s.project_id = _row.project_id;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'Stakeholder owner does not belong to this project' USING ERRCODE='22023';
      END IF;
      -- Internal stakeholders: mirror user_id for back-compat. Externals: leave null.
      IF _stakeholder_type = 'workspace_member' AND _stakeholder_user IS NOT NULL THEN
        _owner_user := _stakeholder_user;
      ELSE
        _owner_user := NULL;
      END IF;
    END IF;

    INSERT INTO governance_record_decisions (
      organization_id, workspace_id, project_id, governance_record_id,
      decision_text, decision_owner_id, decision_owner_stakeholder_id,
      target_date, created_by, updated_by)
    VALUES (
      _row.organization_id, _row.workspace_id, _row.project_id, _record_id,
      _d->>'decision_text',
      _owner_user,
      _stakeholder_id,
      NULLIF(_d->>'target_date','')::date,
      auth.uid(), auth.uid());
    _count := _count + 1;
  END LOOP;
  PERFORM log_activity_event(_row.organization_id, auth.uid(),
    'governance_record_decisions_updated', 'governance_record', _record_id,
    jsonb_build_object('project_id', _row.project_id, 'decision_count', _count),
    _row.workspace_id);
END; $function$

CREATE OR REPLACE FUNCTION public.set_governance_record_links(_record_id uuid, _links jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE _row governance_records%ROWTYPE; _l jsonb; _count int := 0;
BEGIN
  SELECT * INTO _row FROM governance_records WHERE id = _record_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Record not found' USING ERRCODE='P0002'; END IF;
  PERFORM _gov_assert_project_write(_row.project_id);
  IF _links IS NULL OR jsonb_typeof(_links) <> 'array' THEN
    RAISE EXCEPTION 'Links payload must be a JSON array' USING ERRCODE='22023';
  END IF;
  DELETE FROM governance_record_links WHERE governance_record_id = _record_id;
  FOR _l IN SELECT * FROM jsonb_array_elements(_links) LOOP
    INSERT INTO governance_record_links (
      organization_id, workspace_id, project_id, governance_record_id,
      linked_object_type, linked_object_id, created_by)
    VALUES (
      _row.organization_id, _row.workspace_id, _row.project_id, _record_id,
      _l->>'linked_object_type',
      (_l->>'linked_object_id')::uuid,
      auth.uid());
    _count := _count + 1;
  END LOOP;
  PERFORM log_activity_event(_row.organization_id, auth.uid(),
    'governance_record_links_updated', 'governance_record', _record_id,
    jsonb_build_object('project_id', _row.project_id, 'link_count', _count),
    _row.workspace_id);
END; $function$

CREATE OR REPLACE FUNCTION public.set_my_active_context(_tenant_id uuid, _organization_id uuid, _workspace_id uuid DEFAULT NULL::uuid, _is_all_workspaces boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _ok boolean;
  _org_tenant uuid;
  _ws_org uuid;
BEGIN
  IF _uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;
  IF _tenant_id IS NULL OR _organization_id IS NULL THEN
    RAISE EXCEPTION 'tenant_and_organization_required';
  END IF;

  -- Validate tenant membership (via list_my_tenants — respects active/active)
  SELECT EXISTS (SELECT 1 FROM public.list_my_tenants() t WHERE t.tenant_id = _tenant_id) INTO _ok;
  IF NOT _ok THEN
    RAISE EXCEPTION 'tenant_membership_required';
  END IF;

  -- Validate org belongs to tenant
  SELECT tenant_id INTO _org_tenant FROM public.organizations WHERE id = _organization_id;
  IF _org_tenant IS NULL OR _org_tenant <> _tenant_id THEN
    RAISE EXCEPTION 'organization_not_in_tenant';
  END IF;

  -- Validate org membership
  SELECT EXISTS (
    SELECT 1 FROM public.list_my_organizations_for_tenant(_tenant_id) o
    WHERE o.organization_id = _organization_id
  ) INTO _ok;
  IF NOT _ok THEN
    RAISE EXCEPTION 'organization_membership_required';
  END IF;

  IF _is_all_workspaces THEN
    _workspace_id := NULL;
  END IF;

  IF _workspace_id IS NOT NULL THEN
    SELECT organization_id INTO _ws_org FROM public.workspaces WHERE id = _workspace_id;
    IF _ws_org IS NULL OR _ws_org <> _organization_id THEN
      RAISE EXCEPTION 'workspace_not_in_organization';
    END IF;
    SELECT EXISTS (
      SELECT 1 FROM public.list_my_workspaces_for_organization(_organization_id) w
      WHERE w.workspace_id = _workspace_id
    ) INTO _ok;
    IF NOT _ok THEN
      RAISE EXCEPTION 'workspace_membership_required';
    END IF;
  END IF;

  INSERT INTO public.user_active_context_preferences AS p (
    user_id, last_active_tenant_id, last_active_organization_id, last_active_workspace_id, is_all_workspaces, updated_at
  ) VALUES (
    _uid, _tenant_id, _organization_id, _workspace_id, COALESCE(_is_all_workspaces, false), now()
  )
  ON CONFLICT (user_id) DO UPDATE SET
    last_active_tenant_id = EXCLUDED.last_active_tenant_id,
    last_active_organization_id = EXCLUDED.last_active_organization_id,
    last_active_workspace_id = EXCLUDED.last_active_workspace_id,
    is_all_workspaces = EXCLUDED.is_all_workspaces,
    updated_at = now();

  RETURN public.get_my_active_context();
END;
$function$

CREATE OR REPLACE FUNCTION public.set_powerbi_workspace_scope(_organization_id uuid, _workspace_id uuid, _scope_mode text, _reason text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_rule_id uuid;
  v_org_match boolean;
BEGIN
  IF v_uid IS NULL OR NOT public.is_org_admin(v_uid, _organization_id) THEN
    RAISE EXCEPTION 'Org Admin only';
  END IF;
  IF _scope_mode NOT IN ('included','excluded') THEN
    RAISE EXCEPTION 'Invalid scope_mode for workspace rule (use included|excluded)';
  END IF;
  SELECT EXISTS(
    SELECT 1 FROM public.workspaces
    WHERE id = _workspace_id AND organization_id = _organization_id
  ) INTO v_org_match;
  IF NOT v_org_match THEN
    RAISE EXCEPTION 'Workspace does not belong to organization';
  END IF;

  INSERT INTO public.powerbi_data_scope_rules
    (organization_id, scope_type, workspace_id, scope_mode, reason, created_by, updated_by)
  VALUES
    (_organization_id, 'workspace', _workspace_id, _scope_mode, _reason, v_uid, v_uid)
  ON CONFLICT (organization_id, workspace_id)
    WHERE scope_type = 'workspace'
  DO UPDATE SET
    scope_mode = EXCLUDED.scope_mode,
    reason = EXCLUDED.reason,
    updated_by = v_uid,
    updated_at = now()
  RETURNING id INTO v_rule_id;

  RETURN v_rule_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.set_project_template_archived(_template_id uuid, _is_archived boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _caller uuid := auth.uid();
  r RECORD;
BEGIN
  IF _caller IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;

  IF _is_archived IS NULL THEN
    RAISE EXCEPTION 'is_archived is required';
  END IF;

  SELECT id, organization_id, workspace_id
    INTO r
    FROM public.project_templates
   WHERE id = _template_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'template not found';
  END IF;

  IF NOT public.has_pm_authority(_caller, r.workspace_id) THEN
    RAISE EXCEPTION 'access denied: PM authority required' USING ERRCODE = '42501';
  END IF;

  UPDATE public.project_templates
     SET is_archived = _is_archived,
         updated_at = now(),
         updated_by = _caller
   WHERE id = _template_id;

  RETURN jsonb_build_object(
    'template_id', _template_id,
    'workspace_id', r.workspace_id,
    'organization_id', r.organization_id,
    'is_archived', _is_archived,
    'updated_at', now(),
    'updated_by', _caller
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.set_roadmap_story_pack_sources(_story_pack_id uuid, _sources jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _allowed text[] := public.roadmap_story_allowed_source_categories();
  _item jsonb;
  _cat text;
BEGIN
  IF _uid IS NULL OR NOT public.is_active_user(_uid) THEN
    RAISE EXCEPTION 'unauthorized' USING ERRCODE = '42501';
  END IF;
  IF NOT public.is_story_pack_owner(_uid, _story_pack_id) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  PERFORM public.assert_roadmap_story_pack_editable(_story_pack_id);
  IF jsonb_typeof(_sources) <> 'array' THEN
    RAISE EXCEPTION 'sources must be an array' USING ERRCODE = '22023';
  END IF;

  FOR _item IN SELECT * FROM jsonb_array_elements(_sources) LOOP
    _cat := _item->>'source_category';
    IF _cat IS NULL OR NOT (_cat = ANY(_allowed)) THEN
      RAISE EXCEPTION 'unknown source_category: %', _cat USING ERRCODE = '22023';
    END IF;
    INSERT INTO public.roadmap_story_pack_sources (story_pack_id, source_category, is_enabled, config, sort_order)
    VALUES (
      _story_pack_id, _cat,
      COALESCE((_item->>'is_enabled')::boolean, true),
      COALESCE(_item->'config', '{}'::jsonb),
      NULLIF(_item->>'sort_order','')::integer
    )
    ON CONFLICT (story_pack_id, source_category) DO UPDATE
      SET is_enabled = COALESCE((_item->>'is_enabled')::boolean, public.roadmap_story_pack_sources.is_enabled),
          config     = COALESCE(_item->'config', public.roadmap_story_pack_sources.config),
          sort_order = COALESCE(NULLIF(_item->>'sort_order','')::integer, public.roadmap_story_pack_sources.sort_order);
  END LOOP;
END;
$function$

