CREATE OR REPLACE FUNCTION public.start_roadmap_story_generation_run(_story_pack_id uuid, _provider text, _model text, _reasoning_effort text, _input_manifest jsonb, _prompt_summary text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _pack public.roadmap_story_packs;
  _run_id uuid;
BEGIN
  IF _uid IS NULL OR NOT public.is_active_user(_uid) THEN
    RAISE EXCEPTION 'unauthorized' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO _pack FROM public.roadmap_story_packs WHERE id = _story_pack_id;
  IF NOT FOUND OR _pack.created_by <> _uid THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF _pack.status = 'archived' THEN
    RAISE EXCEPTION 'This Story Pack is archived. Unarchive it before generating.' USING ERRCODE = '42501';
  END IF;

  IF _reasoning_effort IS NOT NULL AND _reasoning_effort NOT IN ('low','medium','high') THEN
    RAISE EXCEPTION 'invalid reasoning_effort';
  END IF;

  INSERT INTO public.roadmap_story_ai_runs (
    story_pack_id, created_by, status, provider, model, reasoning_effort,
    feature_key, input_manifest, prompt_summary_encrypted, started_at
  )
  VALUES (
    _story_pack_id, _uid, 'pending', _provider, _model, _reasoning_effort,
    'roadmap_story',
    COALESCE(_input_manifest, '{}'::jsonb),
    CASE WHEN _prompt_summary IS NULL OR _prompt_summary = '' THEN NULL
         ELSE public.btpm_encrypt(_prompt_summary, _pack.organization_id) END,
    now()
  )
  RETURNING id INTO _run_id;

  RETURN _run_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.start_roadmap_story_presentation_run(_story_pack_id uuid, _story_pack_version_id uuid, _provider text, _model text, _reasoning_effort text, _input_manifest jsonb, _prompt text, _input_package_json text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _pack public.roadmap_story_packs;
  _version_pack_id uuid;
  _run_id uuid;
BEGIN
  IF _uid IS NULL OR NOT public.is_active_user(_uid) THEN
    RAISE EXCEPTION 'unauthorized' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO _pack FROM public.roadmap_story_packs WHERE id = _story_pack_id;
  IF NOT FOUND OR _pack.created_by <> _uid THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF _pack.status = 'archived' THEN
    RAISE EXCEPTION 'This Story Pack is archived.' USING ERRCODE = '42501';
  END IF;
  IF _reasoning_effort IS NOT NULL AND _reasoning_effort NOT IN ('low','medium','high') THEN
    RAISE EXCEPTION 'invalid reasoning_effort';
  END IF;

  -- Phase 6B.7b.1 — Version integrity guard: when a version id is provided,
  -- it must exist and belong to the same Story Pack.
  IF _story_pack_version_id IS NOT NULL THEN
    SELECT story_pack_id INTO _version_pack_id
      FROM public.roadmap_story_pack_versions
     WHERE id = _story_pack_version_id;
    IF NOT FOUND OR _version_pack_id <> _story_pack_id THEN
      RAISE EXCEPTION 'invalid_story_pack_version' USING ERRCODE = '42501';
    END IF;
  END IF;

  INSERT INTO public.roadmap_story_pack_presentation_runs (
    story_pack_id, story_pack_version_id, created_by, status,
    provider, model, reasoning_effort, feature_key, input_manifest,
    prompt_encrypted, input_package_encrypted, started_at
  ) VALUES (
    _story_pack_id, _story_pack_version_id, _uid, 'pending',
    _provider, _model, _reasoning_effort, 'roadmap_story_presentation',
    COALESCE(_input_manifest, '{}'::jsonb),
    CASE WHEN _prompt IS NULL OR _prompt = '' THEN NULL
         ELSE public.btpm_encrypt(_prompt, _pack.organization_id) END,
    CASE WHEN _input_package_json IS NULL OR _input_package_json = '' THEN NULL
         ELSE public.btpm_encrypt(_input_package_json, _pack.organization_id) END,
    now()
  )
  RETURNING id INTO _run_id;
  RETURN _run_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.tenant_admin_assign_org_admin(_organization_id uuid, _target_user_id uuid, _reason text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _tid uuid; _om public.organization_memberships%ROWTYPE; _tm_ok boolean; _prev text;
BEGIN
  SELECT tenant_id INTO _tid FROM public.organizations WHERE id=_organization_id;
  IF _tid IS NULL THEN RAISE EXCEPTION 'organization_not_found' USING ERRCODE='42501'; END IF;
  PERFORM public._assert_tenant_admin_caller(_tid);
  SELECT EXISTS(SELECT 1 FROM public.tenant_memberships
    WHERE tenant_id=_tid AND user_id=_target_user_id AND status='active') INTO _tm_ok;
  IF NOT _tm_ok THEN RAISE EXCEPTION 'target_not_active_tenant_member' USING ERRCODE='42501'; END IF;
  SELECT * INTO _om FROM public.organization_memberships
   WHERE organization_id=_organization_id AND user_id=_target_user_id;
  IF NOT FOUND THEN
    INSERT INTO public.organization_memberships(tenant_id, organization_id, user_id, role, status, created_by, updated_by)
    VALUES (_tid, _organization_id, _target_user_id, 'org_admin', 'active', auth.uid(), auth.uid())
    RETURNING * INTO _om;
    PERFORM public._log_admin_authority('assign_org_admin',
      _tid, _organization_id, _target_user_id, NULL, NULL, 'org_admin', NULL, 'active', _reason, '{"created_membership":true}'::jsonb);
    RETURN _om.id;
  END IF;
  IF _om.status<>'active' THEN RAISE EXCEPTION 'target_membership_inactive' USING ERRCODE='42501'; END IF;
  _prev := _om.role::text;
  IF _om.role<>'org_admin' THEN
    UPDATE public.organization_memberships SET role='org_admin', updated_at=now(), updated_by=auth.uid() WHERE id=_om.id;
  END IF;
  PERFORM public._log_admin_authority('assign_org_admin',
    _tid, _organization_id, _target_user_id, NULL, _prev, 'org_admin', _om.status::text, _om.status::text, _reason, '{}'::jsonb);
  RETURN _om.id;
END;$function$

CREATE OR REPLACE FUNCTION public.tenant_admin_assign_tenant_admin(_tenant_id uuid, _target_user_id uuid, _reason text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _row public.tenant_memberships%ROWTYPE; _prev text;
BEGIN
  PERFORM public._assert_tenant_admin_caller(_tenant_id);
  SELECT * INTO _row FROM public.tenant_memberships
   WHERE tenant_id=_tenant_id AND user_id=_target_user_id;
  IF NOT FOUND OR _row.status<>'active' THEN
    RAISE EXCEPTION 'target_not_active_tenant_member' USING ERRCODE='42501';
  END IF;
  IF _row.role='tenant_owner' THEN
    PERFORM public._log_admin_authority('blocked_protected_tenant_admin_change',
      _tenant_id, NULL, _target_user_id, NULL, _row.role::text, 'tenant_admin', _row.status::text, _row.status::text, _reason, '{}'::jsonb);
    RAISE EXCEPTION 'protected_tenant_admin' USING ERRCODE='42501';
  END IF;
  _prev := _row.role::text;
  IF _row.role<>'tenant_admin' THEN
    UPDATE public.tenant_memberships SET role='tenant_admin', updated_at=now(), updated_by=auth.uid() WHERE id=_row.id;
  END IF;
  PERFORM public._log_admin_authority('assign_tenant_admin',
    _tenant_id, NULL, _target_user_id, NULL, _prev, 'tenant_admin', _row.status::text, _row.status::text, _reason, '{}'::jsonb);
  RETURN _row.id;
END;$function$

CREATE OR REPLACE FUNCTION public.tenant_admin_disable_integration_secret(_integration_id uuid, _secret_name text, _organization_id uuid DEFAULT NULL::uuid, _reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _integ public.tenant_integrations;
  _ref_id uuid;
  _row public.tenant_secret_refs;
BEGIN
  IF _integration_id IS NULL OR _secret_name IS NULL THEN
    RAISE EXCEPTION 'integration_id and secret_name are required' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO _integ FROM public.tenant_integrations WHERE id = _integration_id;
  IF _integ.id IS NULL THEN
    RAISE EXCEPTION 'Integration % not found', _integration_id USING ERRCODE = '42501';
  END IF;

  IF NOT public.is_tenant_admin(_integ.tenant_id, auth.uid()) THEN
    RAISE EXCEPTION 'Only Tenant Admin may disable integration secrets for tenant %', _integ.tenant_id
      USING ERRCODE = '42501';
  END IF;

  IF NOT public._is_allowed_tenant_integration_secret_name(_integ.kind, _secret_name) THEN
    RAISE EXCEPTION 'Secret name % is not allowed for integration kind %', _secret_name, _integ.kind::text
      USING ERRCODE = '22023';
  END IF;

  IF _organization_id IS NULL THEN
    SELECT id INTO _ref_id
      FROM public.tenant_secret_refs
     WHERE integration_id = _integ.id
       AND secret_name = _secret_name
       AND secret_scope = 'tenant'
     LIMIT 1;

    IF _ref_id IS NULL THEN
      RAISE EXCEPTION 'Secret % not configured for this scope', _secret_name USING ERRCODE = '42704';
    END IF;

    _row := public.admin_disable_tenant_secret(_ref_id, false, _reason);

    RETURN jsonb_build_object(
      'integration_id',  _row.integration_id,
      'organization_id', _row.organization_id,
      'secret_name',     _row.secret_name,
      'secret_scope',    _row.secret_scope,
      'status',          _row.status,
      'disabled_at',     _row.disabled_at
    );
  END IF;

  -- Organization override path.
  IF NOT EXISTS (
    SELECT 1 FROM public.organizations
     WHERE id = _organization_id AND tenant_id = _integ.tenant_id
  ) THEN
    RAISE EXCEPTION 'Organization % does not belong to tenant %', _organization_id, _integ.tenant_id
      USING ERRCODE = '42501';
  END IF;

  SELECT id INTO _ref_id
    FROM public.tenant_secret_refs
   WHERE integration_id = _integ.id
     AND secret_name = _secret_name
     AND secret_scope = 'organization_override'
     AND organization_id = _organization_id
   LIMIT 1;

  IF _ref_id IS NOT NULL THEN
    _row := public.admin_disable_tenant_secret(_ref_id, false, _reason);
  END IF;

  -- Upsert override row as disabled so the resolver blocks fallback.
  INSERT INTO public.organization_secret_overrides (
    tenant_id, organization_id, integration_id, secret_name,
    secret_ref_id, is_disabled, override_reason, created_by, updated_by
  ) VALUES (
    _integ.tenant_id, _organization_id, _integ.id, _secret_name,
    _ref_id, true, _reason, auth.uid(), auth.uid()
  )
  ON CONFLICT (organization_id, integration_id, secret_name)
  WHERE secret_name IS NOT NULL
  DO UPDATE SET
    secret_ref_id   = COALESCE(EXCLUDED.secret_ref_id, public.organization_secret_overrides.secret_ref_id),
    is_disabled     = true,
    override_reason = EXCLUDED.override_reason,
    updated_by      = auth.uid(),
    updated_at      = now();

  IF _ref_id IS NULL THEN
    -- No existing secret ref, but override is marked disabled -> resolver blocks.
    RETURN jsonb_build_object(
      'integration_id',  _integ.id,
      'organization_id', _organization_id,
      'secret_name',     _secret_name,
      'secret_scope',    'organization_override',
      'status',          'disabled',
      'disabled_at',     now()
    );
  END IF;

  RETURN jsonb_build_object(
    'integration_id',  _row.integration_id,
    'organization_id', _row.organization_id,
    'secret_name',     _row.secret_name,
    'secret_scope',    _row.secret_scope,
    'status',          _row.status,
    'disabled_at',     _row.disabled_at
  );
END $function$

