CREATE OR REPLACE FUNCTION public.tenant_admin_get_azure_openai_deployments(_integration_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_ti public.tenant_integrations;
  v_meta jsonb;
  v_deps jsonb;
  v_rows jsonb := '[]'::jsonb;
  v_configured int := 0;
  v_required int := 0;
  v_key text;
  v_label text;
  v_usage text;
  v_dep text;
BEGIN
  IF _integration_id IS NULL THEN
    RAISE EXCEPTION 'integration_id is required' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_ti FROM public.tenant_integrations WHERE id = _integration_id;
  IF v_ti.id IS NULL THEN
    RAISE EXCEPTION 'integration not found' USING ERRCODE = '42501';
  END IF;
  IF v_ti.kind::text <> 'azure_openai' OR v_ti.name <> 'default' THEN
    RAISE EXCEPTION 'integration is not azure_openai default' USING ERRCODE = '42501';
  END IF;

  PERFORM public._assert_tenant_admin_caller(v_ti.tenant_id);

  v_meta := COALESCE(v_ti.config_metadata, '{}'::jsonb);
  IF jsonb_typeof(v_meta) = 'object'
     AND (v_meta ? 'azure_deployments')
     AND jsonb_typeof(v_meta -> 'azure_deployments') = 'object' THEN
    v_deps := v_meta -> 'azure_deployments';
  ELSE
    v_deps := '{}'::jsonb;
  END IF;

  -- Text models from active registry.
  FOR v_key, v_label IN
    SELECT model_id, display_name
    FROM public.ai_model_registry
    WHERE provider = 'openai' AND active = true
    ORDER BY sort_order, model_id
  LOOP
    v_required := v_required + 1;
    v_dep := NULL;
    IF (v_deps ? v_key)
       AND jsonb_typeof(v_deps -> v_key) = 'string'
       AND btrim(v_deps ->> v_key) <> '' THEN
      v_dep := v_deps ->> v_key;
      v_configured := v_configured + 1;
    END IF;
    v_rows := v_rows || jsonb_build_array(jsonb_build_object(
      'model_key', v_key,
      'display_label', v_label,
      'usage', 'text',
      'deployment_name', v_dep
    ));
  END LOOP;

  -- Fixed embedding entry.
  v_key := 'text-embedding-3-small';
  v_required := v_required + 1;
  v_dep := NULL;
  IF (v_deps ? v_key)
     AND jsonb_typeof(v_deps -> v_key) = 'string'
     AND btrim(v_deps ->> v_key) <> '' THEN
    v_dep := v_deps ->> v_key;
    v_configured := v_configured + 1;
  END IF;
  v_rows := v_rows || jsonb_build_array(jsonb_build_object(
    'model_key', v_key,
    'display_label', 'Text embedding 3 small',
    'usage', 'embedding',
    'deployment_name', v_dep
  ));

  RETURN jsonb_build_object(
    'integration_id', v_ti.id,
    'mappings', v_rows,
    'required_count', v_required,
    'configured_count', v_configured,
    'complete', (v_configured = v_required)
  );
END $function$

CREATE OR REPLACE FUNCTION public.tenant_admin_get_azure_openai_endpoint(_integration_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _ti public.tenant_integrations;
  _endpoint text;
BEGIN
  IF _integration_id IS NULL THEN
    RAISE EXCEPTION 'integration_id is required' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO _ti FROM public.tenant_integrations WHERE id = _integration_id;
  IF _ti.id IS NULL THEN
    RAISE EXCEPTION 'integration not found' USING ERRCODE = '42501';
  END IF;
  IF _ti.kind::text <> 'azure_openai' THEN
    RAISE EXCEPTION 'integration is not azure_openai' USING ERRCODE = '42501';
  END IF;

  PERFORM public._assert_tenant_admin_caller(_ti.tenant_id);

  IF jsonb_typeof(COALESCE(_ti.config_metadata, '{}'::jsonb)) = 'object'
     AND (_ti.config_metadata ? 'endpoint')
     AND jsonb_typeof(_ti.config_metadata -> 'endpoint') = 'string' THEN
    _endpoint := _ti.config_metadata ->> 'endpoint';
    IF btrim(_endpoint) = '' THEN _endpoint := NULL; END IF;
  ELSE
    _endpoint := NULL;
  END IF;

  RETURN jsonb_build_object(
    'integration_id', _ti.id,
    'endpoint', _endpoint,
    'endpoint_configured', (_endpoint IS NOT NULL)
  );
END $function$

CREATE OR REPLACE FUNCTION public.tenant_admin_get_encryption_posture(_tenant_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _caller uuid := auth.uid();
  _tenant jsonb;
  _orgs   jsonb;
  _v1     jsonb;
BEGIN
  IF _caller IS NULL THEN
    RAISE EXCEPTION 'authentication_required';
  END IF;
  IF _tenant_id IS NULL THEN
    RAISE EXCEPTION 'tenant_id_required';
  END IF;
  IF NOT public.is_tenant_admin(_tenant_id, _caller) THEN
    RAISE EXCEPTION 'not_tenant_admin_for_tenant';
  END IF;

  SELECT to_jsonb(tep) INTO _tenant
    FROM public.tenant_encryption_posture tep
   WHERE tep.tenant_id = _tenant_id;

  SELECT COALESCE(jsonb_agg(to_jsonb(oep) ORDER BY oep.environment_role, oep.organization_name), '[]'::jsonb)
    INTO _orgs
    FROM public.organization_encryption_posture oep
   WHERE oep.tenant_id = _tenant_id;

  _v1 := public.resolve_tenant_encryption_v1_metadata(_tenant_id);

  RETURN jsonb_build_object(
    'tenant', COALESCE(_tenant, jsonb_build_object('tenant_id', _tenant_id, 'tenant_key_status', 'missing_metadata')),
    'organizations', _orgs,
    'tenant_key_v1', _v1
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.tenant_admin_get_operations_summary(_tenant_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _exports jsonb;
  _imports jsonb;
  _jobs jsonb;
  _scheduler jsonb;
  _storage_total bigint;
BEGIN
  PERFORM public._assert_tenant_admin_caller(_tenant_id);

  SELECT COALESCE(jsonb_object_agg(status, cnt), '{}'::jsonb) INTO _exports
  FROM (SELECT status, COUNT(*) AS cnt FROM public.tenant_export_packages
        WHERE tenant_id = _tenant_id GROUP BY status) e;

  SELECT COALESCE(jsonb_object_agg(status, cnt), '{}'::jsonb) INTO _imports
  FROM (SELECT status, COUNT(*) AS cnt FROM public.tenant_import_temp_objects
        WHERE tenant_id = _tenant_id GROUP BY status) i;

  SELECT COALESCE(jsonb_object_agg(status, cnt), '{}'::jsonb) INTO _jobs
  FROM (SELECT status, COUNT(*) AS cnt FROM public.tenant_background_jobs
        WHERE tenant_id = _tenant_id GROUP BY status) j;

  SELECT COALESCE(jsonb_object_agg(status, cnt), '{}'::jsonb) INTO _scheduler
  FROM (SELECT status, COUNT(*) AS cnt FROM public.tenant_scheduler_runs
        WHERE tenant_id = _tenant_id GROUP BY status) s;

  SELECT COUNT(*) INTO _storage_total FROM public.tenant_storage_objects
   WHERE tenant_id = _tenant_id AND deleted_at IS NULL;

  RETURN jsonb_build_object(
    'storage_object_count', _storage_total,
    'export_packages_by_status', _exports,
    'import_temp_by_status', _imports,
    'background_jobs_by_status', _jobs,
    'scheduler_runs_by_status', _scheduler,
    'generated_at', now()
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.tenant_admin_get_organization_encryption_posture(_organization_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _caller uuid := auth.uid();
  _tenant_id uuid;
  _row jsonb;
BEGIN
  IF _caller IS NULL THEN
    RAISE EXCEPTION 'authentication_required';
  END IF;
  IF _organization_id IS NULL THEN
    RAISE EXCEPTION 'organization_id_required';
  END IF;

  SELECT o.tenant_id INTO _tenant_id
    FROM public.organizations o
   WHERE o.id = _organization_id;

  IF _tenant_id IS NULL THEN
    RAISE EXCEPTION 'organization_not_found';
  END IF;

  IF NOT public.is_tenant_admin(_tenant_id, _caller) THEN
