    'organization_id', _organization_id,
    'tenant_id', _tenant_id,
    'key_status', 'missing_metadata'
  ));
END;
$function$

CREATE OR REPLACE FUNCTION public.tenant_admin_get_powerbi_reporting_readiness(_tenant_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pbi_reporting_security', 'pbi_reporting'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _tenant record;
  _map record;
  _role text;
  _role_oid oid;
  _role_exists boolean := false;
  _login boolean := false;
  _conn_limit int := NULL;
  _rolsuper boolean;
  _rolcreatedb boolean;
  _rolcreaterole boolean;
  _rolreplication boolean;
  _rolbypassrls boolean;
  _rolinherit boolean;
  _memberships text[] := ARRAY[]::text[];
  _settings text[];
  _role_security_ok boolean := false;
  _membership_ok boolean := false;
  _session_defaults_ok boolean := false;
  _op jsonb := '{}'::jsonb;
  _last_verified_evt timestamptz;
  _session_pooler_verified boolean := false;
  _session_user_verified boolean := false;
  _fail_closed_verified boolean := false;
  _mapping_state text := NULL;
  _credential_state text := NULL;
  _orgs jsonb;
  _coverage jsonb;
  _readiness text;
  _latest_evt record;
  _has_search_path boolean := false;
  _has_readonly boolean := false;
  _has_stmt_timeout boolean := false;
  _has_idle_timeout boolean := false;
  _s text;
BEGIN
  IF _uid IS NULL OR _tenant_id IS NULL THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;
  IF NOT (public.is_platform_super_admin(_uid) OR public.is_tenant_admin(_tenant_id, _uid)) THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  SELECT id, name, slug, status::text AS status
    INTO _tenant
    FROM public.tenants
   WHERE id = _tenant_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'tenant_not_found' USING ERRCODE = 'P0002';
  END IF;

  SELECT login_role_name, state::text AS state,
         provisioned_at, last_rotated_at, last_verified_at,
         disabled_at, operational_metadata
    INTO _map
    FROM pbi_reporting_security.tenant_login_map
   WHERE tenant_id = _tenant_id
   ORDER BY provisioned_at DESC
   LIMIT 1;

  IF _map.login_role_name IS NOT NULL THEN
    _role := _map.login_role_name;
    _op := COALESCE(_map.operational_metadata, '{}'::jsonb);
    _mapping_state := _map.state;
    _credential_state := _op->>'credential_state';

    SELECT r.oid, true, r.rolcanlogin, r.rolconnlimit,
           r.rolsuper, r.rolcreatedb, r.rolcreaterole,
           r.rolreplication, r.rolbypassrls, r.rolinherit
      INTO _role_oid, _role_exists, _login, _conn_limit,
           _rolsuper, _rolcreatedb, _rolcreaterole,
           _rolreplication, _rolbypassrls, _rolinherit
      FROM pg_catalog.pg_roles r
     WHERE r.rolname = _role;

    IF _role_exists THEN
      _role_security_ok := COALESCE(_login,false)
                       AND _rolsuper = false
                       AND _rolcreatedb = false
                       AND _rolcreaterole = false
                       AND _rolreplication = false
                       AND _rolbypassrls = false
                       AND _rolinherit = true
                       AND _conn_limit = 8;

      SELECT COALESCE(array_agg(pr.rolname ORDER BY pr.rolname), ARRAY[]::text[])
        INTO _memberships
        FROM pg_catalog.pg_auth_members m
        JOIN pg_catalog.pg_roles pr ON pr.oid = m.roleid
       WHERE m.member = _role_oid;

      _membership_ok := (_memberships = ARRAY['btpm_pbi_reader']::text[]);

      SELECT s.setconfig INTO _settings
        FROM pg_catalog.pg_db_role_setting s
       WHERE s.setrole = _role_oid AND s.setdatabase = 0;

      IF _settings IS NOT NULL THEN
        FOREACH _s IN ARRAY _settings LOOP
          IF _s = 'search_path=pbi_reporting, pbi_reporting_security, pg_catalog' THEN
            _has_search_path := true;
          ELSIF _s = 'default_transaction_read_only=on' THEN
            _has_readonly := true;
          ELSIF _s = 'statement_timeout=5min' THEN
            _has_stmt_timeout := true;
          ELSIF _s = 'idle_in_transaction_session_timeout=1min' THEN
            _has_idle_timeout := true;
          END IF;
        END LOOP;
      END IF;
      _session_defaults_ok := _has_search_path AND _has_readonly
                          AND _has_stmt_timeout AND _has_idle_timeout;
    END IF;

    _session_pooler_verified := COALESCE((_op->>'session_pooler_verified')::boolean, false);
    _session_user_verified   := COALESCE((_op->>'session_user_verified')::boolean, false);
    _fail_closed_verified    := COALESCE((_op->>'fail_closed_pre_activation_verified')::boolean, false);

    SELECT event_type::text AS event_type, event_at
      INTO _latest_evt
      FROM pbi_reporting_security.tenant_login_audit
     WHERE tenant_id = _tenant_id
       AND login_role_name = _role
     ORDER BY event_at DESC
     LIMIT 1;

    IF _map.last_verified_at IS NULL THEN
      SELECT MAX(event_at) INTO _last_verified_evt
        FROM pbi_reporting_security.tenant_login_audit
       WHERE tenant_id = _tenant_id
         AND login_role_name = _role
         AND event_type = 'verified';
    END IF;
  END IF;

  WITH tenant_orgs AS (
    SELECT o.id, o.name, o.environment_role::text AS environment_role
      FROM public.organizations o
     WHERE o.tenant_id = _tenant_id
  ),
  ws_counts AS (
    SELECT w.organization_id, COUNT(*) AS total_ws
      FROM public.workspaces w
      JOIN tenant_orgs o ON o.id = w.organization_id
     WHERE NOT w.is_archived
     GROUP BY w.organization_id
  ),
  rules AS (
    SELECT r.organization_id, r.scope_mode
      FROM public.powerbi_data_scope_rules r
      JOIN tenant_orgs o ON o.id = r.organization_id
     WHERE r.scope_type = 'workspace'
  ),
  rule_counts AS (
    SELECT organization_id,
           COUNT(*) FILTER (WHERE scope_mode = 'included') AS included_ws,
           COUNT(*) FILTER (WHERE scope_mode = 'excluded') AS excluded_ws
      FROM rules
     GROUP BY organization_id
  ),
  projects_in_scope AS (
    SELECT sp.organization_id, COUNT(*)::int AS scoped_project_count
      FROM pbi_reporting._scope_projects sp
      JOIN tenant_orgs o ON o.id = sp.organization_id
     GROUP BY sp.organization_id
  )
  SELECT COALESCE(jsonb_agg(row_json ORDER BY (row_json->>'organization_name')), '[]'::jsonb)
    INTO _orgs
    FROM (
      SELECT jsonb_build_object(
               'organization_id', o.id,
               'organization_name', o.name,
               'environment_role', o.environment_role,
               'total_workspace_count', COALESCE(wc.total_ws, 0),
               'included_workspace_count', COALESCE(rc.included_ws, 0),
               'excluded_workspace_count', COALESCE(rc.excluded_ws, 0),
               'unconfigured_workspace_count',
                 GREATEST(COALESCE(wc.total_ws,0) - COALESCE(rc.included_ws,0) - COALESCE(rc.excluded_ws,0), 0),
               'scoped_project_count', COALESCE(ps.scoped_project_count, 0),
               'scope_configured', (COALESCE(rc.included_ws,0) + COALESCE(rc.excluded_ws,0)) > 0
             ) AS row_json
        FROM tenant_orgs o
        LEFT JOIN ws_counts wc ON wc.organization_id = o.id
        LEFT JOIN rule_counts rc ON rc.organization_id = o.id
        LEFT JOIN projects_in_scope ps ON ps.organization_id = o.id
    ) s;

  _coverage := jsonb_build_object(
    'organization_count', jsonb_array_length(_orgs),
    'organizations_with_reporting_scope',
      (SELECT COUNT(*) FROM jsonb_array_elements(_orgs) x WHERE (x->>'scope_configured')::boolean),
    'included_workspace_count',
      COALESCE((SELECT SUM((x->>'included_workspace_count')::int) FROM jsonb_array_elements(_orgs) x), 0),
    'excluded_workspace_count',
      COALESCE((SELECT SUM((x->>'excluded_workspace_count')::int) FROM jsonb_array_elements(_orgs) x), 0),
    'scoped_project_count',
      COALESCE((SELECT SUM((x->>'scoped_project_count')::int) FROM jsonb_array_elements(_orgs) x), 0)
  );

  -- Adjusted status ordering
  IF _map.login_role_name IS NULL THEN
    _readiness := 'not_provisioned';
  ELSIF _mapping_state = 'revoked' THEN
    _readiness := 'revoked';
  ELSIF _mapping_state = 'disabled' AND _credential_state = 'pending_activation' THEN
    _readiness := 'attention_required';
  ELSIF _mapping_state = 'disabled' AND _credential_state = 'disabled' THEN
    _readiness := 'disabled';
  ELSIF _mapping_state = 'disabled' THEN
    _readiness := 'disabled';
  ELSIF _mapping_state = 'active'
        AND _role_exists
        AND COALESCE(_login,false)
        AND _role_security_ok
        AND _membership_ok
        AND _session_defaults_ok
        AND _session_pooler_verified
        AND _session_user_verified
        AND _fail_closed_verified
        AND COALESCE(_map.last_verified_at, _last_verified_evt) IS NOT NULL
        AND (_coverage->>'included_workspace_count')::int > 0 THEN
    _readiness := 'ready';
  ELSE
    _readiness := 'attention_required';
  END IF;

  RETURN jsonb_build_object(
    'tenant', jsonb_build_object(
      'id', _tenant.id,
      'name', _tenant.name,
      'slug', _tenant.slug,
      'status', _tenant.status
    ),
    'readiness_status', _readiness,
    'identity', jsonb_build_object(
      'login_role_name', _map.login_role_name,
      'mapping_state', _mapping_state,
      'role_exists', _role_exists,
      'login_enabled', COALESCE(_login, false),
      'connection_limit', _conn_limit,
      'role_security_attributes_valid', _role_security_ok,
      'membership_valid', _membership_ok,
      'session_defaults_valid', _session_defaults_ok,
      'session_pooler_verified', _session_pooler_verified,
      'session_user_verified', _session_user_verified,
      'fail_closed_verified', _fail_closed_verified,
      'provisioned_at', _map.provisioned_at,
      'last_rotated_at', _map.last_rotated_at,
      'last_verified_at', COALESCE(_map.last_verified_at, _last_verified_evt),
      'credential_state', _credential_state
    ),
    'connection_guidance', jsonb_build_object(
      'host_hint', 'Obtain from Supabase → Connect (Session Pooler)',
      'connection_method', 'Supabase Session Pooler',
      'port', 5432,
      'database', 'postgres',
      'connectivity_mode', 'Import',
      'notes', 'Use the Tenant-specific reporting login shown above with the Supabase Session Pooler. The password is provisioned outside BTPM and is never displayed here.'
    ),
    'latest_safe_event', jsonb_build_object(
      'event_type', _latest_evt.event_type,
      'event_at',   _latest_evt.event_at
    ),
    'coverage_summary', _coverage,
    'organizations', _orgs
  );
END $function$

CREATE OR REPLACE FUNCTION public.tenant_admin_list_org_authority_audit(_organization_id uuid, _limit integer DEFAULT 50)
 RETURNS SETOF admin_authority_audit
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _tid uuid;
BEGIN
  SELECT tenant_id INTO _tid FROM public.organizations WHERE id=_organization_id;
  IF _tid IS NULL THEN RAISE EXCEPTION 'organization_not_found' USING ERRCODE='42501'; END IF;
  PERFORM public._assert_tenant_admin_caller(_tid);
  RETURN QUERY SELECT * FROM public.admin_authority_audit
    WHERE organization_id=_organization_id ORDER BY created_at DESC LIMIT LEAST(GREATEST(_limit,1),500);
END;$function$

CREATE OR REPLACE FUNCTION public.tenant_admin_remove_org_admin(_organization_id uuid, _target_user_id uuid, _reason text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _tid uuid; _om public.organization_memberships%ROWTYPE; _remaining int;
BEGIN
  SELECT tenant_id INTO _tid FROM public.organizations WHERE id=_organization_id;
  IF _tid IS NULL THEN RAISE EXCEPTION 'organization_not_found' USING ERRCODE='42501'; END IF;
  PERFORM public._assert_tenant_admin_caller(_tid);
  SELECT * INTO _om FROM public.organization_memberships
   WHERE organization_id=_organization_id AND user_id=_target_user_id;
  IF NOT FOUND OR _om.role<>'org_admin' OR _om.status<>'active' THEN
    RAISE EXCEPTION 'target_not_active_org_admin' USING ERRCODE='42501';
  END IF;
  SELECT count(*) INTO _remaining FROM public.organization_memberships
   WHERE organization_id=_organization_id AND role='org_admin' AND status='active' AND user_id<>_target_user_id;
  IF _remaining<1 THEN
    PERFORM public._log_admin_authority('blocked_last_admin_change',
      _tid, _organization_id, _target_user_id, NULL, 'org_admin', 'org_member', _om.status::text, _om.status::text, _reason, '{}'::jsonb);
    RAISE EXCEPTION 'last_org_admin' USING ERRCODE='42501';
  END IF;
  UPDATE public.organization_memberships SET role='org_member', updated_at=now(), updated_by=auth.uid() WHERE id=_om.id;
  PERFORM public._log_admin_authority('remove_org_admin',
    _tid, _organization_id, _target_user_id, NULL, 'org_admin', 'org_member', _om.status::text, _om.status::text, _reason, '{}'::jsonb);
  RETURN _om.id;
END;$function$

CREATE OR REPLACE FUNCTION public.tenant_admin_remove_tenant_admin(_tenant_id uuid, _target_user_id uuid, _reason text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _row public.tenant_memberships%ROWTYPE; _remaining int;
BEGIN
  PERFORM public._assert_tenant_admin_caller(_tenant_id);
  SELECT * INTO _row FROM public.tenant_memberships
   WHERE tenant_id=_tenant_id AND user_id=_target_user_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'target_not_tenant_member' USING ERRCODE='42501'; END IF;
  IF _row.role='tenant_owner' THEN
    PERFORM public._log_admin_authority('blocked_protected_tenant_admin_change',
      _tenant_id, NULL, _target_user_id, NULL, _row.role::text, _row.role::text, _row.status::text, _row.status::text, _reason, '{}'::jsonb);
    RAISE EXCEPTION 'protected_tenant_admin' USING ERRCODE='42501';
  END IF;
  IF _row.role<>'tenant_admin' THEN
    RAISE EXCEPTION 'target_not_tenant_admin' USING ERRCODE='42501';
  END IF;
  SELECT count(*) INTO _remaining FROM public.tenant_memberships
    WHERE tenant_id=_tenant_id AND status='active'
      AND role IN ('tenant_owner','tenant_admin') AND user_id<>_target_user_id;
  IF _remaining<1 THEN
    PERFORM public._log_admin_authority('blocked_last_admin_change',
      _tenant_id, NULL, _target_user_id, NULL, _row.role::text, 'tenant_member', _row.status::text, _row.status::text, _reason, '{}'::jsonb);
    RAISE EXCEPTION 'last_tenant_admin' USING ERRCODE='42501';
  END IF;
  UPDATE public.tenant_memberships SET role='tenant_member', updated_at=now(), updated_by=auth.uid() WHERE id=_row.id;
  PERFORM public._log_admin_authority('remove_tenant_admin',
    _tenant_id, NULL, _target_user_id, NULL, 'tenant_admin', 'tenant_member', _row.status::text, _row.status::text, _reason, '{}'::jsonb);
  RETURN _row.id;
END;$function$

CREATE OR REPLACE FUNCTION public.tenant_admin_set_ai_provider(_tenant_id uuid, _provider text, _reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_readiness jsonb;
BEGIN
  PERFORM public._assert_tenant_admin_caller(_tenant_id);

  IF _provider IS NULL OR _provider NOT IN ('openai', 'azure_openai') THEN
    RAISE EXCEPTION 'ai_provider_invalid' USING ERRCODE = '22023';
  END IF;

  v_readiness := public._tenant_ai_provider_readiness(_tenant_id, _provider);
  IF NOT COALESCE((v_readiness ->> 'ready')::boolean, false) THEN
    RAISE EXCEPTION 'ai_provider_not_ready' USING ERRCODE = 'P0001';
  END IF;

  INSERT INTO public.tenant_ai_provider_settings (tenant_id, active_provider, updated_at, updated_by)
  VALUES (_tenant_id, _provider, now(), auth.uid())
  ON CONFLICT (tenant_id) DO UPDATE
    SET active_provider = EXCLUDED.active_provider,
        updated_at = now(),
        updated_by = auth.uid();

  BEGIN
    INSERT INTO public.admin_authority_audit (
      actor_user_id, action, tenant_id, reason, metadata
    ) VALUES (
      auth.uid(), 'tenant_ai_provider_set', _tenant_id, _reason,
      jsonb_build_object('active_provider', _provider)
    );
  EXCEPTION WHEN OTHERS THEN NULL;
  END;

  RETURN jsonb_build_object(
    'tenant_id', _tenant_id,
    'active_provider', _provider,
    'runtime_activation_note',
      'Provider selection saved. Runtime activation will occur after the AI provider migration is completed.'
  );
END $function$

CREATE OR REPLACE FUNCTION public.tenant_admin_set_integration_enabled(_integration_id uuid, _is_enabled boolean, _reason text DEFAULT NULL::text)
 RETURNS TABLE(integration_id uuid, is_enabled boolean, status tenant_integration_status, active_secret_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tenant_id uuid;
  v_kind public.tenant_integration_kind;
  v_config jsonb;
  v_required text[];
  v_required_config text[];
  v_missing text[];
  v_missing_config text[];
  v_active_count integer := 0;
  v_new_status public.tenant_integration_status;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'authentication required' USING ERRCODE = '28000';
  END IF;

  SELECT ti.tenant_id, ti.kind, COALESCE(ti.config_metadata, '{}'::jsonb)
    INTO v_tenant_id, v_kind, v_config
  FROM public.tenant_integrations ti
  WHERE ti.id = _integration_id;

  IF v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'integration not found' USING ERRCODE = 'P0002';
  END IF;

  IF NOT public.is_tenant_admin(v_tenant_id, auth.uid()) THEN
    RAISE EXCEPTION 'tenant admin required' USING ERRCODE = '42501';
  END IF;

  v_required := public._required_tenant_integration_secret_names(v_kind);
  v_required_config := public._required_tenant_integration_config_names(v_kind);

  IF _is_enabled THEN
    SELECT array_agg(req) INTO v_missing
    FROM unnest(v_required) req
    WHERE NOT EXISTS (
      SELECT 1
      FROM public.tenant_secret_refs r
      WHERE r.tenant_id = v_tenant_id
        AND r.integration_id = _integration_id
        AND r.secret_name = req
        AND r.secret_scope = 'tenant'
        AND r.disabled_at IS NULL
        AND r.revoked_at IS NULL
        AND r.status = 'active'
    );

    IF v_missing IS NOT NULL AND array_length(v_missing, 1) > 0 THEN
      RAISE EXCEPTION 'integration cannot be enabled — missing required secrets: %',
        array_to_string(v_missing, ', ')
        USING ERRCODE = 'P0001';
    END IF;

    -- Validate required non-secret configuration keys are present and non-empty.
    IF v_required_config IS NOT NULL AND array_length(v_required_config, 1) > 0 THEN
      SELECT array_agg(cfg) INTO v_missing_config
      FROM unnest(v_required_config) cfg
      WHERE NOT (
        jsonb_typeof(v_config) = 'object'
        AND v_config ? cfg
        AND jsonb_typeof(v_config -> cfg) = 'string'
        AND btrim(v_config ->> cfg) <> ''
      );

      IF v_missing_config IS NOT NULL AND array_length(v_missing_config, 1) > 0 THEN
        RAISE EXCEPTION 'integration cannot be enabled — missing required configuration: %',
          array_to_string(v_missing_config, ', ')
          USING ERRCODE = 'P0001';
      END IF;
    END IF;

    v_new_status := 'active'::public.tenant_integration_status;
  ELSE
    v_new_status := 'disabled'::public.tenant_integration_status;
  END IF;

  UPDATE public.tenant_integrations ti
     SET is_enabled = _is_enabled,
         status = v_new_status,
         updated_at = now(),
         updated_by = auth.uid()
   WHERE ti.id = _integration_id;

  BEGIN
    INSERT INTO public.admin_authority_audit (
      actor_user_id, action, tenant_id, reason, metadata
    ) VALUES (
      auth.uid(),
      CASE WHEN _is_enabled THEN 'tenant_integration_enable' ELSE 'tenant_integration_disable' END,
      v_tenant_id,
      _reason,
      jsonb_build_object(
        'integration_id', _integration_id,
        'integration_kind', v_kind::text,
        'new_status', v_new_status::text
      )
    );
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;

  SELECT count(*)::int INTO v_active_count
  FROM public.tenant_secret_refs r
  WHERE r.tenant_id = v_tenant_id
    AND r.integration_id = _integration_id
    AND r.secret_scope = 'tenant'
    AND r.disabled_at IS NULL
    AND r.revoked_at IS NULL
    AND r.status = 'active';

  RETURN QUERY
    SELECT _integration_id, _is_enabled, v_new_status, v_active_count;
END;
$function$

CREATE OR REPLACE FUNCTION public.tenant_admin_store_integration_secret(_integration_id uuid, _secret_name text, _secret_value text, _secret_kind text DEFAULT 'text'::text, _organization_id uuid DEFAULT NULL::uuid, _reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _integ public.tenant_integrations;
  _scope public.tenant_secret_scope;
  _kind text;
  _res jsonb;
  _ref_id uuid;
BEGIN
  IF _integration_id IS NULL OR _secret_name IS NULL OR _secret_value IS NULL THEN
    RAISE EXCEPTION 'integration_id, secret_name and secret_value are required' USING ERRCODE = '22023';
  END IF;
  IF length(_secret_value) = 0 THEN
    RAISE EXCEPTION 'Secret value must not be empty' USING ERRCODE = '22023';
  END IF;

  _kind := lower(COALESCE(NULLIF(trim(_secret_kind), ''), 'text'));
  IF _kind NOT IN ('text','secret') THEN
    RAISE EXCEPTION 'secret_kind must be text or secret' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO _integ FROM public.tenant_integrations WHERE id = _integration_id;
  IF _integ.id IS NULL THEN
    RAISE EXCEPTION 'Integration % not found', _integration_id USING ERRCODE = '42501';
  END IF;

  IF NOT public.is_tenant_admin(_integ.tenant_id, auth.uid()) THEN
    RAISE EXCEPTION 'Only Tenant Admin may configure integration secrets for tenant %', _integ.tenant_id
      USING ERRCODE = '42501';
  END IF;

  IF NOT public._is_allowed_tenant_integration_secret_name(_integ.kind, _secret_name) THEN
    RAISE EXCEPTION 'Secret name % is not allowed for integration kind %', _secret_name, _integ.kind::text
      USING ERRCODE = '22023';
  END IF;

  IF _organization_id IS NULL THEN
    _scope := 'tenant';
  ELSE
    _scope := 'organization_override';
    IF NOT EXISTS (
      SELECT 1 FROM public.organizations
       WHERE id = _organization_id AND tenant_id = _integ.tenant_id
    ) THEN
      RAISE EXCEPTION 'Organization % does not belong to tenant %', _organization_id, _integ.tenant_id
        USING ERRCODE = '42501';
    END IF;
  END IF;

  _res := public.admin_store_tenant_secret(
    _tenant_id       => _integ.tenant_id,
    _integration_id  => _integ.id,
    _secret_name     => _secret_name,
    _secret_kind     => _kind,
    _secret_value    => _secret_value,
    _fingerprint     => NULL,
    _scope           => _scope,
    _reason          => _reason,
    _organization_id => _organization_id
  );

  -- Wire organization override into organization_secret_overrides so the
  -- runtime resolver can find and honor it.
  IF _scope = 'organization_override' THEN
    SELECT id INTO _ref_id
      FROM public.tenant_secret_refs
     WHERE tenant_id = _integ.tenant_id
       AND integration_id = _integ.id
       AND secret_name = _secret_name
       AND secret_scope = 'organization_override'
       AND organization_id = _organization_id
     LIMIT 1;

    INSERT INTO public.organization_secret_overrides (
      tenant_id, organization_id, integration_id, secret_name,
      secret_ref_id, is_disabled, override_reason, created_by, updated_by
    ) VALUES (
      _integ.tenant_id, _organization_id, _integ.id, _secret_name,
      _ref_id, false, _reason, auth.uid(), auth.uid()
    )
    ON CONFLICT (organization_id, integration_id, secret_name)
    WHERE secret_name IS NOT NULL
    DO UPDATE SET
      secret_ref_id   = EXCLUDED.secret_ref_id,
      is_disabled     = false,
      override_reason = EXCLUDED.override_reason,
      updated_by      = auth.uid(),
      updated_at      = now();
  END IF;

  RETURN jsonb_build_object(
    'integration_id',   _res->'integration_id',
    'organization_id',  _res->'organization_id',
    'secret_name',      _res->'secret_name',
    'secret_kind',      _res->'secret_kind',
    'secret_scope',     _res->'secret_scope',
    'status',           _res->'status',
    'rotated_at',       _res->'rotated_at'
  );
END $function$

CREATE OR REPLACE FUNCTION public.tenant_admin_update_azure_openai_deployments(_integration_id uuid, _deployments jsonb, _reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_ti public.tenant_integrations;
  v_normalized jsonb;
  v_new_meta jsonb;
BEGIN
  IF _integration_id IS NULL THEN
    RAISE EXCEPTION 'integration_id is required' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_ti FROM public.tenant_integrations WHERE id = _integration_id;
  IF v_ti.id IS NULL THEN
    RAISE EXCEPTION 'integration not found' USING ERRCODE = '42501';
  END IF;
  IF v_ti.kind::text <> 'azure_openai' OR v_ti.name <> 'default' THEN
    RAISE EXCEPTION 'integration is not azure_openai default' USING ERRCODE = '42501';
  END IF;

  PERFORM public._assert_tenant_admin_caller(v_ti.tenant_id);

  v_normalized := public._validate_azure_openai_deployments(_deployments);

  -- Preserve endpoint + other safe (non-secret) metadata; overwrite azure_deployments.
  v_new_meta := public._safe_integration_config_metadata(COALESCE(v_ti.config_metadata, '{}'::jsonb))
                || jsonb_build_object('azure_deployments', v_normalized);

  UPDATE public.tenant_integrations
     SET config_metadata = v_new_meta,
         updated_by = auth.uid(),
         updated_at = now()
   WHERE id = v_ti.id;

  BEGIN
    INSERT INTO public.admin_authority_audit (
      actor_user_id, action, tenant_id, reason, metadata
    ) VALUES (
      auth.uid(),
      'tenant_azure_openai_deployments_update',
      v_ti.tenant_id,
      _reason,
      jsonb_build_object('integration_id', v_ti.id, 'key_count', (SELECT count(*) FROM jsonb_object_keys(v_normalized)))
    );
  EXCEPTION WHEN OTHERS THEN NULL;
  END;

  INSERT INTO public.tenant_secret_access_audit(
    tenant_id, integration_id, actor_user_id, action, reason, function_name, result
  ) VALUES (
    v_ti.tenant_id, v_ti.id, auth.uid(), 'updated', _reason,
    'tenant_admin_update_azure_openai_deployments', 'success'
  );

  RETURN jsonb_build_object(
    'integration_id', v_ti.id,
    'configured_count', (SELECT count(*)::int FROM jsonb_object_keys(v_normalized)),
    'complete', true
  );
END $function$

CREATE OR REPLACE FUNCTION public.tenant_admin_update_azure_openai_endpoint(_integration_id uuid, _endpoint text, _reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _ti public.tenant_integrations;
  _normalized text;
  _new_meta jsonb;
  _prev_endpoint text;
  _endpoint_changed boolean;
BEGIN
  IF _integration_id IS NULL THEN
    RAISE EXCEPTION 'integration_id is required' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO _ti FROM public.tenant_integrations WHERE id = _integration_id;
  IF _ti.id IS NULL THEN
    RAISE EXCEPTION 'integration not found' USING ERRCODE = '42501';
  END IF;
  IF _ti.kind::text <> 'azure_openai' THEN
    RAISE EXCEPTION 'integration is not azure_openai' USING ERRCODE = '42501';
  END IF;

  PERFORM public._assert_tenant_admin_caller(_ti.tenant_id);

  _normalized := public._normalize_azure_openai_endpoint(_endpoint);
  IF _normalized IS NULL THEN
    RAISE EXCEPTION 'azure_openai_endpoint_invalid' USING ERRCODE = '22023';
  END IF;

  IF jsonb_typeof(COALESCE(_ti.config_metadata, '{}'::jsonb)) = 'object'
     AND (_ti.config_metadata ? 'endpoint')
     AND jsonb_typeof(_ti.config_metadata -> 'endpoint') = 'string' THEN
    _prev_endpoint := _ti.config_metadata ->> 'endpoint';
  ELSE
    _prev_endpoint := NULL;
  END IF;
  _endpoint_changed := (_prev_endpoint IS DISTINCT FROM _normalized);

  _new_meta := public._safe_integration_config_metadata(COALESCE(_ti.config_metadata, '{}'::jsonb))
               || jsonb_build_object('endpoint', _normalized);

  UPDATE public.tenant_integrations
     SET config_metadata = _new_meta,
         updated_by = auth.uid(),
         updated_at = now(),
         last_tested_at    = CASE WHEN _endpoint_changed THEN NULL ELSE last_tested_at END,
         last_success_at   = CASE WHEN _endpoint_changed THEN NULL ELSE last_success_at END,
         last_error_at     = CASE WHEN _endpoint_changed THEN NULL ELSE last_error_at END,
         last_error_message= CASE WHEN _endpoint_changed THEN NULL ELSE last_error_message END
   WHERE id = _ti.id;

  INSERT INTO public.tenant_secret_access_audit(
    tenant_id, integration_id, actor_user_id, action, reason, function_name, result
  ) VALUES (
    _ti.tenant_id, _ti.id, auth.uid(), 'updated', _reason,
    'tenant_admin_update_azure_openai_endpoint', 'success'
  );

  RETURN jsonb_build_object(
    'integration_id', _ti.id,
    'endpoint_configured', true,
    'endpoint_changed', _endpoint_changed
  );
END $function$

CREATE OR REPLACE FUNCTION public.toggle_project_agile_mode(_project_id uuid, _enable boolean DEFAULT true)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _project record; _user_id uuid := auth.uid();
BEGIN
  SELECT id, workspace_id, organization_id, agile_enabled
  INTO _project FROM public.projects WHERE id = _project_id;
  IF _project IS NULL THEN RAISE EXCEPTION 'Project not found'; END IF;
  IF NOT public.has_project_pm_authority(_user_id, _project_id) THEN
    RAISE EXCEPTION 'Insufficient authority'; END IF;
  UPDATE public.projects SET agile_enabled = _enable WHERE id = _project_id;
  IF _enable THEN
    IF NOT EXISTS (SELECT 1 FROM public.board_workflow_states WHERE project_id = _project_id LIMIT 1) THEN
      INSERT INTO public.board_workflow_states (organization_id, workspace_id, project_id, name, category, sort_order, created_by)
      VALUES
        (_project.organization_id, _project.workspace_id, _project_id, 'To Do',       'todo',        1, _user_id),
        (_project.organization_id, _project.workspace_id, _project_id, 'In Progress', 'in_progress', 2, _user_id),
        (_project.organization_id, _project.workspace_id, _project_id, 'In Review',   'in_review',   3, _user_id),
        (_project.organization_id, _project.workspace_id, _project_id, 'Done',        'done',        4, _user_id);
    END IF;
  END IF;
END; $function$

CREATE OR REPLACE FUNCTION public.transition_governance_decision_case_stage(_record_id uuid, _target_stage text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  _row public.governance_records%ROWTYPE;
  _current text;
  _order int;
  _target_order int;
  _has_brief boolean;
  _has_provided_pkg boolean;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO _row FROM public.governance_records WHERE id = _record_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Governance record not found' USING ERRCODE = 'P0002';
  END IF;

  IF _row.record_kind IS DISTINCT FROM 'decision_case' THEN
    RAISE EXCEPTION 'Stage transitions are only allowed on decision_case records'
      USING ERRCODE = '22023';
  END IF;

  PERFORM public._gov_assert_project_write(_row.project_id);

  _current := COALESCE(_row.decision_stage, 'initiated');

  IF _current = 'closed' THEN
    RAISE EXCEPTION 'This decision case is closed and cannot be transitioned.'
      USING ERRCODE = '22023';
  END IF;
  IF _current = 'decision_taken' THEN
    RAISE EXCEPTION 'A decision has been taken; further progression is handled by the closure flow.'
      USING ERRCODE = '22023';
  END IF;

  IF _target_stage NOT IN ('evidence_collection','brief_prepared','pending_decision') THEN
    RAISE EXCEPTION 'Target stage % is not allowed via lifecycle transition.', _target_stage
      USING ERRCODE = '22023';
  END IF;

  _order := CASE _current
    WHEN 'initiated' THEN 1
    WHEN 'evidence_collection' THEN 2
    WHEN 'brief_prepared' THEN 3
    WHEN 'provided_to_stakeholders' THEN 4
    WHEN 'pending_decision' THEN 5
    WHEN 'decision_taken' THEN 6
    WHEN 'closed' THEN 7
  END;
  _target_order := CASE _target_stage
    WHEN 'evidence_collection' THEN 2
    WHEN 'brief_prepared' THEN 3
    WHEN 'pending_decision' THEN 5
  END;

  IF _target_order <= _order THEN
    RAISE EXCEPTION 'Stage transitions are forward-only.'
      USING ERRCODE = '22023';
  END IF;

  IF _target_stage = 'brief_prepared' THEN
    SELECT EXISTS(
      SELECT 1 FROM public.governance_record_brief_versions
       WHERE governance_record_id = _record_id AND is_current = true
    ) INTO _has_brief;
    IF NOT _has_brief THEN
      RAISE EXCEPTION 'Create a Copilot Brief version before marking the brief as prepared.'
        USING ERRCODE = '22023';
    END IF;
  END IF;

  IF _target_stage = 'pending_decision' THEN
    SELECT EXISTS(
      SELECT 1 FROM public.governance_record_stakeholder_packages
       WHERE governance_record_id = _record_id
         AND is_current = true
         AND package_status = 'provided'
    ) INTO _has_provided_pkg;
    IF NOT _has_provided_pkg THEN
      RAISE EXCEPTION 'Mark a stakeholder package as provided before moving to pending decision.'
        USING ERRCODE = '22023';
    END IF;
  END IF;

  UPDATE public.governance_records
     SET decision_stage = _target_stage,
         updated_at = now()
   WHERE id = _record_id;

  PERFORM public.log_activity_event(
    _row.organization_id,
    auth.uid(),
    'governance_decision_case_stage_transitioned',
    'governance_record',
    _record_id,
    jsonb_build_object(
      'project_id', _row.project_id,
      'record_id', _record_id,
      'from_stage', _current,
      'to_stage', _target_stage
    ),
    _row.workspace_id
  );
END; $function$

CREATE OR REPLACE FUNCTION public.transition_project_stage(_project_id uuid, _project_stage project_stage)
 RETURNS projects
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_project public.projects; v_old_stage public.project_stage;
BEGIN
  SELECT * INTO v_project FROM public.projects WHERE id = _project_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Project not found'; END IF;
  IF NOT public.is_active_user(auth.uid()) THEN
    RAISE EXCEPTION 'Not authorized: inactive user'; END IF;
  IF NOT public.has_project_pm_authority(auth.uid(), _project_id) THEN
    RAISE EXCEPTION 'Not authorized: PM+ authority required to transition project stage'; END IF;
  v_old_stage := v_project.project_stage;
  IF v_old_stage = _project_stage THEN RETURN v_project; END IF;
  UPDATE public.projects SET project_stage = _project_stage, updated_at = now()
  WHERE id = _project_id RETURNING * INTO v_project;
  INSERT INTO public.activity_events (organization_id, workspace_id, actor_id,
    target_id, target_type, event_type, metadata)
  VALUES (v_project.organization_id, v_project.workspace_id, auth.uid(),
    v_project.id, 'project', 'project_stage_transitioned',
    json_build_object('from_stage', v_old_stage::text, 'to_stage', _project_stage::text)::text);
  RETURN v_project;
END; $function$

CREATE OR REPLACE FUNCTION public.unarchive_backlog_item(_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
