CREATE OR REPLACE FUNCTION public.unarchive_phase(_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _row phases%ROWTYPE;
BEGIN
  SELECT * INTO _row FROM phases WHERE id = _id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Phase not found' USING ERRCODE='P0002'; END IF;
  PERFORM _assert_pm_or_admin(_row.workspace_id, _row.organization_id);
  IF _row.is_archived THEN
    PERFORM set_config('app.allow_lifecycle_bypass', 'on', true);
    UPDATE phases SET is_archived = false, updated_at = now() WHERE id = _id;
    PERFORM set_config('app.allow_lifecycle_bypass', 'off', true);
    PERFORM log_activity_event(_row.organization_id, auth.uid(), 'phase_unarchived', 'phase', _id, '{}'::jsonb, _row.workspace_id);
  END IF;
END;
$function$

