CREATE OR REPLACE FUNCTION public.unlink_adoption_object(_link_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _org uuid; _ws uuid; _proj uuid; _plan uuid; _init uuid;
        _otype text; _oid uuid; _uid uuid := auth.uid(); _evt text;
BEGIN
  IF _uid IS NULL OR NOT public.is_active_user(_uid) THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  SELECT organization_id, workspace_id, project_id, adoption_plan_id,
         adoption_initiative_id, object_type, object_id
    INTO _org, _ws, _proj, _plan, _init, _otype, _oid
    FROM public.adoption_object_links WHERE id = _link_id;
  IF _org IS NULL THEN RAISE EXCEPTION 'invalid_link'; END IF;
  IF NOT public.has_pm_authority(_uid, _ws) THEN RAISE EXCEPTION 'forbidden'; END IF;

  DELETE FROM public.adoption_object_links WHERE id = _link_id;

  _evt := CASE _otype
    WHEN 'risk' THEN 'adoption_risk_unlinked'
    WHEN 'blocker' THEN 'adoption_blocker_unlinked'
    WHEN 'kpi' THEN 'adoption_kpi_unlinked'
  END;

  PERFORM public.log_activity_event(
    _organization_id => _org, _actor_id => _uid,
    _event_type => _evt,
    _target_type => 'project', _target_id => _proj,
    _metadata => jsonb_build_object(
      'adoption_plan_id', _plan,
      'adoption_initiative_id', _init,
      'object_type', _otype,
      'object_id', _oid,
      'link_id', _link_id
    ),
    _workspace_id => _ws
  );
  RETURN true;
END $function$

CREATE OR REPLACE FUNCTION public.unlink_task_from_adoption(_task_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _org uuid; _ws uuid; _proj uuid; _phase uuid;
  _old_init uuid; _was_related boolean; _plan_id uuid;
BEGIN
  IF _uid IS NULL OR NOT public.is_active_user(_uid) THEN RAISE EXCEPTION 'not_authenticated'; END IF;

  SELECT t.organization_id, t.workspace_id, p.project_id, t.phase_id,
         t.adoption_initiative_id, COALESCE(t.is_adoption_related, false)
    INTO _org, _ws, _proj, _phase, _old_init, _was_related
  FROM public.tasks t
  JOIN public.phases p ON p.id = t.phase_id
  WHERE t.id = _task_id;
  IF _org IS NULL THEN RAISE EXCEPTION 'invalid_task'; END IF;

  IF NOT public.has_pm_authority(_uid, _ws) THEN RAISE EXCEPTION 'forbidden'; END IF;

  -- Idempotent: if not adoption-related and no initiative, return without event.
  IF NOT _was_related AND _old_init IS NULL THEN
    RETURN _task_id;
  END IF;

  SELECT id INTO _plan_id FROM public.adoption_plans
  WHERE project_id = _proj AND COALESCE(is_archived, false) = false
  LIMIT 1;

  UPDATE public.tasks
     SET is_adoption_related = false,
         adoption_initiative_id = NULL,
         updated_at = now()
   WHERE id = _task_id;

  PERFORM public.log_activity_event(
    _organization_id => _org, _actor_id => _uid,
    _event_type => 'adoption_task_unlinked',
    _target_type => 'task', _target_id => _task_id,
    _metadata => jsonb_build_object(
      'project_id', _proj,
      'phase_id', _phase,
      'adoption_plan_id', _plan_id,
      'old_adoption_initiative_id', _old_init
    ),
    _workspace_id => _ws
  );

  RETURN _task_id;
END $function$

CREATE OR REPLACE FUNCTION public.update_adoption_template_from_payload(_template_id uuid, _name text, _description text, _payload jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _t record;
BEGIN
  IF _uid IS NULL OR NOT public.is_active_user(_uid) THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;
  IF COALESCE(btrim(_name), '') = '' THEN
    RAISE EXCEPTION 'template_name_required';
  END IF;
  SELECT * INTO _t FROM public.adoption_templates WHERE id = _template_id;
  IF _t.id IS NULL THEN
    RAISE EXCEPTION 'invalid_template';
  END IF;
  IF _t.is_system THEN
    RAISE EXCEPTION 'system_template_read_only';
  END IF;
  IF NOT public.has_pm_authority(_uid, _t.workspace_id) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  UPDATE public.adoption_templates SET
    name = btrim(_name),
    description = NULLIF(btrim(COALESCE(_description,'')),''),
    updated_by = _uid,
    updated_at = now()
  WHERE id = _template_id;

  PERFORM public._adoption_template_validate_and_load(_template_id, _t.organization_id, _t.workspace_id, _payload);

  RETURN _template_id;
END $function$

CREATE OR REPLACE FUNCTION public.update_ai_feature_setting(_feature_key text, _model_registry_id uuid, _enabled boolean, _reasoning_effort text, _max_files_per_request integer, _max_individual_file_mb integer, _max_total_file_mb integer, _require_user_confirmation boolean)
 RETURNS ai_feature_settings
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _org_id uuid;
  _model public.ai_model_registry;
  _row public.ai_feature_settings;
BEGIN
  SELECT organization_id INTO _org_id FROM public.profiles WHERE id = auth.uid();
  IF _org_id IS NULL OR NOT public.is_org_admin(auth.uid(), _org_id) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF _feature_key NOT IN ('btpm_guide','decision_cases','roadmap_story') THEN
    RAISE EXCEPTION 'invalid feature_key';
  END IF;

  SELECT * INTO _model FROM public.ai_model_registry WHERE id = _model_registry_id AND active = true;
  IF _model.id IS NULL THEN
    RAISE EXCEPTION 'model not found or inactive';
  END IF;
  IF _model.provider <> 'openai' THEN
    RAISE EXCEPTION 'unsupported provider';
  END IF;

  IF _reasoning_effort IS NOT NULL AND _reasoning_effort NOT IN ('low','medium','high') THEN
    RAISE EXCEPTION 'invalid reasoning_effort';
  END IF;
  IF _max_files_per_request IS NOT NULL AND _max_files_per_request <= 0 THEN RAISE EXCEPTION 'max_files_per_request must be positive'; END IF;
  IF _max_individual_file_mb IS NOT NULL AND _max_individual_file_mb <= 0 THEN RAISE EXCEPTION 'max_individual_file_mb must be positive'; END IF;
  IF _max_total_file_mb IS NOT NULL AND _max_total_file_mb <= 0 THEN RAISE EXCEPTION 'max_total_file_mb must be positive'; END IF;

  INSERT INTO public.ai_feature_settings AS s
    (organization_id, feature_key, provider, model_registry_id, enabled, reasoning_effort, max_files_per_request, max_individual_file_mb, max_total_file_mb, require_user_confirmation, updated_by)
  VALUES
    (_org_id, _feature_key, 'openai', _model_registry_id, _enabled, _reasoning_effort, _max_files_per_request, _max_individual_file_mb, _max_total_file_mb, _require_user_confirmation, auth.uid())
  ON CONFLICT (organization_id, feature_key) DO UPDATE SET
    model_registry_id = EXCLUDED.model_registry_id,
    enabled = EXCLUDED.enabled,
    reasoning_effort = EXCLUDED.reasoning_effort,
    max_files_per_request = EXCLUDED.max_files_per_request,
    max_individual_file_mb = EXCLUDED.max_individual_file_mb,
    max_total_file_mb = EXCLUDED.max_total_file_mb,
    require_user_confirmation = EXCLUDED.require_user_confirmation,
    updated_by = auth.uid(),
    updated_at = now()
  RETURNING * INTO _row;

  RETURN _row;
END;
$function$

CREATE OR REPLACE FUNCTION public.update_blocker_with_links(_blocker_id uuid, _title text, _description text, _severity text, _status text, _user_links jsonb DEFAULT '[]'::jsonb, _object_links jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_row public.blockers%ROWTYPE;
  v jsonb; v_idx int; v_resolve boolean := false; v_project_id uuid;
  v_old_title text; v_old_description text; v_old_severity text;
  v_old_user_ids uuid[]; v_old_user_labels jsonb;
  v_old_obj_keys text[]; v_old_obj_labels jsonb;
  v_new_user_ids uuid[]; v_new_user_labels jsonb;
  v_new_obj_keys text[]; v_new_obj_labels jsonb;
  v_scalar_diff jsonb := '{}'::jsonb;
  v_new_title text; v_new_description text; v_new_severity text;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF NOT public.is_active_user(v_uid) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;

  SELECT * INTO v_row FROM public.blockers WHERE id = _blocker_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Blocker not found'; END IF;

  IF NOT public.has_pm_authority(v_uid, v_row.workspace_id) THEN
    RAISE EXCEPTION 'PM authority required';
  END IF;

  IF NOT public.can_write_demo(v_uid, v_row.workspace_id) THEN
    RAISE EXCEPTION 'Not authorized: this workspace is read-only';
  END IF;

  v_project_id := public._project_id_from_target(v_row.target_type, v_row.target_id);

  PERFORM public._validate_object_links(_object_links, v_row.workspace_id, v_row.organization_id);
  PERFORM public._validate_user_links(_user_links, v_row.workspace_id, v_project_id);

  v_old_title       := v_row.title;
  v_old_description := public.btpm_decrypt(v_row.description, v_row.organization_id);
  v_old_severity    := v_row.severity::text;

  SELECT COALESCE(array_agg(COALESCE(eul.user_id, eul.stakeholder_id) ORDER BY eul.sort_order), ARRAY[]::uuid[]),
         COALESCE(jsonb_agg(jsonb_build_object(
           'user_id', COALESCE(eul.user_id, eul.stakeholder_id),
           'display_name', CASE
             WHEN eul.user_id IS NOT NULL THEN public.btpm_decrypt(p.display_name, p.organization_id)
             ELSE COALESCE(s.external_name, public.btpm_decrypt(sp.display_name, sp.organization_id))
           END
         ) ORDER BY eul.sort_order), '[]'::jsonb)
    INTO v_old_user_ids, v_old_user_labels
    FROM public.entity_user_links eul
    LEFT JOIN public.profiles p ON p.id = eul.user_id
    LEFT JOIN public.project_stakeholders s ON s.id = eul.stakeholder_id
    LEFT JOIN public.profiles sp ON sp.id = s.user_id
   WHERE eul.owner_type='blocker' AND eul.owner_id=_blocker_id AND eul.link_role='related_person';

  SELECT COALESCE(array_agg((eol.referenced_type || ':' || eol.referenced_id::text) ORDER BY eol.sort_order), ARRAY[]::text[]),
         COALESCE(jsonb_agg(jsonb_build_object(
           'referenced_type', eol.referenced_type,
           'referenced_id',   eol.referenced_id,
           'display_label',   CASE eol.referenced_type
             WHEN 'project' THEN (SELECT public.btpm_decrypt(p.name, p.organization_id) FROM public.projects p  WHERE p.id  = eol.referenced_id)
             WHEN 'phase'   THEN (SELECT public.btpm_decrypt(ph.name, ph.organization_id) FROM public.phases ph WHERE ph.id = eol.referenced_id)
             WHEN 'task'    THEN (SELECT public.btpm_decrypt(t.name,  t.organization_id) FROM public.tasks  t  WHERE t.id  = eol.referenced_id)
           END
         ) ORDER BY eol.sort_order), '[]'::jsonb)
    INTO v_old_obj_keys, v_old_obj_labels
    FROM public.entity_object_links eol
   WHERE eol.owner_type='blocker' AND eol.owner_id=_blocker_id AND eol.link_role='related_object';

  v_resolve := (_status = 'resolved' AND v_row.status::text <> 'resolved');

  UPDATE public.blockers SET
    title = COALESCE(_title, title),
    description = _description,
    severity = COALESCE(_severity::pm_priority, severity),
    status = COALESCE(_status::blocker_status, status),
    resolved_by = CASE WHEN v_resolve THEN v_uid ELSE resolved_by END,
    resolved_at = CASE WHEN v_resolve THEN now() ELSE resolved_at END
  WHERE id = _blocker_id;

  DELETE FROM public.entity_user_links   WHERE owner_type='blocker' AND owner_id=_blocker_id AND link_role='related_person';
  DELETE FROM public.entity_object_links WHERE owner_type='blocker' AND owner_id=_blocker_id AND link_role='related_object';

  v_idx := 0;
  FOR v IN SELECT * FROM jsonb_array_elements(COALESCE(_user_links,'[]'::jsonb)) LOOP
    INSERT INTO public.entity_user_links (owner_type, owner_id, organization_id, workspace_id,
                                          user_id, stakeholder_id, link_role, sort_order, created_by)
    VALUES ('blocker', _blocker_id, v_row.organization_id, v_row.workspace_id,
            NULLIF(v->>'user_id','')::uuid,
            NULLIF(v->>'stakeholder_id','')::uuid,
            'related_person', v_idx, v_uid)
    ON CONFLICT DO NOTHING;
    v_idx := v_idx + 1;
  END LOOP;

  v_idx := 0;
  FOR v IN SELECT * FROM jsonb_array_elements(COALESCE(_object_links,'[]'::jsonb)) LOOP
    INSERT INTO public.entity_object_links (owner_type, owner_id, organization_id, workspace_id, referenced_type, referenced_id, link_role, sort_order, created_by)
    VALUES ('blocker', _blocker_id, v_row.organization_id, v_row.workspace_id, v->>'referenced_type', (v->>'referenced_id')::uuid, 'related_object', v_idx, v_uid)
    ON CONFLICT DO NOTHING;
    v_idx := v_idx + 1;
  END LOOP;

  v_new_title       := COALESCE(_title, v_old_title);
  v_new_description := _description;
  v_new_severity    := COALESCE(_severity, v_old_severity);

  IF v_new_title       IS DISTINCT FROM v_old_title       THEN v_scalar_diff := v_scalar_diff || jsonb_build_object('title',       jsonb_build_object('old', v_old_title,       'new', v_new_title));       END IF;
  IF v_new_description IS DISTINCT FROM v_old_description THEN v_scalar_diff := v_scalar_diff || jsonb_build_object('description', jsonb_build_object('old', v_old_description, 'new', v_new_description)); END IF;
  IF v_new_severity    IS DISTINCT FROM v_old_severity    THEN v_scalar_diff := v_scalar_diff || jsonb_build_object('severity',    jsonb_build_object('old', v_old_severity,    'new', v_new_severity));    END IF;

  SELECT COALESCE(array_agg(COALESCE(eul.user_id, eul.stakeholder_id) ORDER BY eul.sort_order), ARRAY[]::uuid[]),
         COALESCE(jsonb_agg(jsonb_build_object(
           'user_id', COALESCE(eul.user_id, eul.stakeholder_id),
           'display_name', CASE
             WHEN eul.user_id IS NOT NULL THEN public.btpm_decrypt(p.display_name, p.organization_id)
             ELSE COALESCE(s.external_name, public.btpm_decrypt(sp.display_name, sp.organization_id))
           END
         ) ORDER BY eul.sort_order), '[]'::jsonb)
    INTO v_new_user_ids, v_new_user_labels
    FROM public.entity_user_links eul
    LEFT JOIN public.profiles p ON p.id = eul.user_id
    LEFT JOIN public.project_stakeholders s ON s.id = eul.stakeholder_id
    LEFT JOIN public.profiles sp ON sp.id = s.user_id
   WHERE eul.owner_type='blocker' AND eul.owner_id=_blocker_id AND eul.link_role='related_person';

  SELECT COALESCE(array_agg((eol.referenced_type || ':' || eol.referenced_id::text) ORDER BY eol.sort_order), ARRAY[]::text[]),
         COALESCE(jsonb_agg(jsonb_build_object(
           'referenced_type', eol.referenced_type,
           'referenced_id',   eol.referenced_id,
           'display_label',   CASE eol.referenced_type
             WHEN 'project' THEN (SELECT public.btpm_decrypt(p.name, p.organization_id) FROM public.projects p  WHERE p.id  = eol.referenced_id)
             WHEN 'phase'   THEN (SELECT public.btpm_decrypt(ph.name, ph.organization_id) FROM public.phases ph WHERE ph.id = eol.referenced_id)
             WHEN 'task'    THEN (SELECT public.btpm_decrypt(t.name,  t.organization_id) FROM public.tasks  t  WHERE t.id  = eol.referenced_id)
           END
         ) ORDER BY eol.sort_order), '[]'::jsonb)
    INTO v_new_obj_keys, v_new_obj_labels
    FROM public.entity_object_links eol
   WHERE eol.owner_type='blocker' AND eol.owner_id=_blocker_id AND eol.link_role='related_object';

  PERFORM public._log_entity_material_update(
    'blocker', _blocker_id, v_row.organization_id, v_row.workspace_id,
    v_row.target_type, v_row.target_id,
    v_scalar_diff,
    v_old_user_ids, v_new_user_ids,
    v_old_obj_keys, v_new_obj_keys,
    v_old_user_labels, v_new_user_labels,
    v_old_obj_labels, v_new_obj_labels,
    v_new_title
  );

  RETURN jsonb_build_object('id', _blocker_id);
END $function$

CREATE OR REPLACE FUNCTION public.update_comment_with_references(_comment_id uuid, _body text, _references jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_row public.comments%ROWTYPE;
  v_ref jsonb;
  v_idx int := 0;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF NOT public.is_active_user(v_uid) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;

  SELECT * INTO v_row FROM public.comments WHERE id = _comment_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Comment not found'; END IF;
  IF v_row.author_id <> v_uid THEN RAISE EXCEPTION 'Only the author can edit this comment'; END IF;

  IF NOT public.can_write_demo(v_uid, v_row.workspace_id) THEN
    RAISE EXCEPTION 'Not authorized to write in this workspace (read-only/demo)';
  END IF;

  PERFORM public._validate_object_links(_references, v_row.workspace_id, v_row.organization_id);

  UPDATE public.comments SET body = _body WHERE id = _comment_id;

  DELETE FROM public.entity_object_links
   WHERE owner_type = 'comment' AND owner_id = _comment_id AND link_role = 'reference';

  IF _references IS NOT NULL AND jsonb_typeof(_references) = 'array' THEN
    FOR v_ref IN SELECT * FROM jsonb_array_elements(_references) LOOP
      INSERT INTO public.entity_object_links (
        owner_type, owner_id, organization_id, workspace_id,
        referenced_type, referenced_id, link_role, sort_order, created_by
      ) VALUES (
        'comment', _comment_id, v_row.organization_id, v_row.workspace_id,
        v_ref->>'referenced_type',
        (v_ref->>'referenced_id')::uuid,
        'reference',
        COALESCE((v_ref->>'sort_order')::int, v_idx),
        v_uid
      ) ON CONFLICT DO NOTHING;
      v_idx := v_idx + 1;
    END LOOP;
  END IF;

  RETURN jsonb_build_object('id', _comment_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.update_governance_cadence(_cadence_id uuid, _event_type text DEFAULT NULL::text, _frequency_type text DEFAULT NULL::text, _event_name text DEFAULT NULL::text, _owner_id uuid DEFAULT NULL::uuid, _next_expected_date date DEFAULT NULL::date, _expected_evidence_type text DEFAULT NULL::text, _clear_event_name boolean DEFAULT false, _clear_owner boolean DEFAULT false, _clear_next_expected_date boolean DEFAULT false, _clear_expected_evidence_type boolean DEFAULT false, _owner_stakeholder_id uuid DEFAULT NULL::uuid, _clear_owner_stakeholder boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE _row governance_cadences%ROWTYPE; _sh project_stakeholders%ROWTYPE; _eff_owner_id uuid;
BEGIN
  SELECT * INTO _row FROM governance_cadences WHERE id = _cadence_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Cadence not found' USING ERRCODE='P0002'; END IF;
  PERFORM _gov_assert_project_write(_row.project_id);

  _eff_owner_id := _owner_id;

  IF _owner_stakeholder_id IS NOT NULL THEN
    SELECT * INTO _sh FROM project_stakeholders
      WHERE id = _owner_stakeholder_id AND project_id = _row.project_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Stakeholder not found for this project' USING ERRCODE='P0002';
    END IF;
    IF _sh.stakeholder_type = 'workspace_member' AND _sh.user_id IS NOT NULL AND _eff_owner_id IS NULL THEN
      _eff_owner_id := _sh.user_id;
    END IF;
  END IF;

  UPDATE governance_cadences SET
    event_type = COALESCE(_event_type, event_type),
    frequency_type = COALESCE(_frequency_type, frequency_type),
    event_name = CASE WHEN _clear_event_name THEN NULL ELSE COALESCE(_event_name, event_name) END,
    owner_id = CASE
      WHEN _clear_owner OR _clear_owner_stakeholder THEN NULL
      ELSE COALESCE(_eff_owner_id, owner_id)
    END,
    owner_stakeholder_id = CASE
      WHEN _clear_owner_stakeholder THEN NULL
      ELSE COALESCE(_owner_stakeholder_id, owner_stakeholder_id)
    END,
    next_expected_date = CASE WHEN _clear_next_expected_date THEN NULL ELSE COALESCE(_next_expected_date, next_expected_date) END,
    expected_evidence_type = CASE WHEN _clear_expected_evidence_type THEN NULL ELSE COALESCE(_expected_evidence_type, expected_evidence_type) END,
    updated_at = now(),
    updated_by = auth.uid()
  WHERE id = _cadence_id;

  PERFORM log_activity_event(_row.organization_id, auth.uid(),
    'governance_cadence_updated', 'governance_cadence', _cadence_id,
    jsonb_build_object('project_id', _row.project_id), _row.workspace_id);
END; $function$

CREATE OR REPLACE FUNCTION public.update_governance_record_btpm_context_link(_context_link_id uuid, _source_project_id uuid DEFAULT NULL::uuid, _object_type text DEFAULT NULL::text, _object_id uuid DEFAULT NULL::uuid, _relationship_type text DEFAULT NULL::text, _context_reason text DEFAULT NULL::text, _relevance_level text DEFAULT NULL::text, _included_in_package boolean DEFAULT NULL::boolean, _clear_context_reason boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  _ln public.governance_record_btpm_context_links%ROWTYPE;
  _row public.governance_records%ROWTYPE;
  _sp record;
  _new_sp uuid;
  _new_sws uuid;
  _reason text;
BEGIN
  SELECT * INTO _ln FROM public.governance_record_btpm_context_links WHERE id = _context_link_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'BTPM context link not found' USING ERRCODE='P0002'; END IF;

  SELECT * INTO _row FROM public.governance_records WHERE id = _ln.governance_record_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Parent record not found' USING ERRCODE='P0002'; END IF;
  IF _row.record_kind IS DISTINCT FROM 'decision_case' THEN
    RAISE EXCEPTION 'BTPM context links are only allowed on decision_case records' USING ERRCODE='22023';
  END IF;
  PERFORM public._gov_assert_project_write(_row.project_id);

  IF NOT public.has_project_access(auth.uid(), _ln.source_project_id) THEN
    RAISE EXCEPTION 'You do not have access to the source project' USING ERRCODE='42501';
  END IF;

  _new_sp := COALESCE(_source_project_id, _ln.source_project_id);
  IF _new_sp <> _ln.source_project_id THEN
    SELECT id, organization_id, workspace_id INTO _sp
      FROM public.projects WHERE id = _new_sp;
    IF _sp IS NULL THEN RAISE EXCEPTION 'Source project not found' USING ERRCODE='P0002'; END IF;
    IF _sp.organization_id <> _row.organization_id THEN
      RAISE EXCEPTION 'Source project must be in the same organization' USING ERRCODE='22023';
    END IF;
    IF NOT public.has_project_access(auth.uid(), _new_sp) THEN
      RAISE EXCEPTION 'You do not have access to the source project' USING ERRCODE='42501';
    END IF;
    _new_sws := _sp.workspace_id;
  ELSE
    _new_sws := _ln.source_workspace_id;
  END IF;

  IF _context_reason IS NOT NULL THEN
    _reason := NULLIF(trim(_context_reason), '');
  END IF;

  UPDATE public.governance_record_btpm_context_links SET
    source_project_id = _new_sp,
    source_workspace_id = _new_sws,
    object_type = COALESCE(_object_type, object_type),
    object_id = COALESCE(_object_id, object_id),
    relationship_type = COALESCE(_relationship_type, relationship_type),
    context_reason = CASE
      WHEN _clear_context_reason THEN NULL
      WHEN _context_reason IS NOT NULL THEN _reason
      ELSE context_reason END,
    relevance_level = COALESCE(_relevance_level, relevance_level),
    included_in_package = COALESCE(_included_in_package, included_in_package),
    updated_by = auth.uid(),
    updated_at = now()
  WHERE id = _context_link_id;

  PERFORM public.log_activity_event(_row.organization_id, auth.uid(),
    'governance_record_btpm_context_link_updated', 'governance_record', _ln.governance_record_id,
    jsonb_build_object('project_id', _row.project_id,
                       'btpm_context_link_id', _context_link_id,
                       'source_project_id', _new_sp),
    _row.workspace_id);
END; $function$

CREATE OR REPLACE FUNCTION public.update_governance_record_cross_project_link(_cross_project_link_id uuid, _linked_project_id uuid DEFAULT NULL::uuid, _relationship_type text DEFAULT NULL::text, _relationship_reason text DEFAULT NULL::text, _source_dependency_id uuid DEFAULT NULL::uuid, _included_in_package boolean DEFAULT NULL::boolean, _clear_relationship_reason boolean DEFAULT false, _clear_source_dependency_id boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  _ln public.governance_record_cross_project_links%ROWTYPE;
  _row public.governance_records%ROWTYPE;
  _lp record;
  _new_linked uuid;
  _new_ws uuid;
  _reason text;
BEGIN
  SELECT * INTO _ln FROM public.governance_record_cross_project_links WHERE id = _cross_project_link_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Cross-project link not found' USING ERRCODE='P0002'; END IF;

  SELECT * INTO _row FROM public.governance_records WHERE id = _ln.governance_record_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Parent record not found' USING ERRCODE='P0002'; END IF;
  IF _row.record_kind IS DISTINCT FROM 'decision_case' THEN
    RAISE EXCEPTION 'Cross-project links are only allowed on decision_case records' USING ERRCODE='22023';
  END IF;
  PERFORM public._gov_assert_project_write(_row.project_id);

  IF NOT public.has_project_access(auth.uid(), _ln.linked_project_id) THEN
    RAISE EXCEPTION 'You do not have access to the linked project' USING ERRCODE='42501';
  END IF;

  _new_linked := COALESCE(_linked_project_id, _ln.linked_project_id);
  IF _new_linked <> _ln.linked_project_id THEN
    IF _new_linked = _row.project_id THEN
      RAISE EXCEPTION 'Cross-project link cannot reference the parent project itself' USING ERRCODE='22023';
    END IF;
    SELECT id, organization_id, workspace_id INTO _lp
      FROM public.projects WHERE id = _new_linked;
    IF _lp IS NULL THEN RAISE EXCEPTION 'Linked project not found' USING ERRCODE='P0002'; END IF;
    IF _lp.organization_id <> _row.organization_id THEN
      RAISE EXCEPTION 'Linked project must be in the same organization' USING ERRCODE='22023';
    END IF;
    IF NOT public.has_project_access(auth.uid(), _new_linked) THEN
      RAISE EXCEPTION 'You do not have access to the linked project' USING ERRCODE='42501';
    END IF;
    _new_ws := _lp.workspace_id;
  ELSE
    _new_ws := _ln.linked_project_workspace_id;
  END IF;

  IF _relationship_type IS NOT NULL
     AND _relationship_type NOT IN
     ('formal_dependency','shared_risk','shared_blocker','shared_milestone','manual_related','other') THEN
    RAISE EXCEPTION 'Invalid relationship_type %', _relationship_type USING ERRCODE='22023';
  END IF;

  IF _relationship_reason IS NOT NULL THEN
    _reason := NULLIF(trim(_relationship_reason), '');
  END IF;

  UPDATE public.governance_record_cross_project_links SET
    linked_project_id = _new_linked,
    linked_project_workspace_id = _new_ws,
    relationship_type = COALESCE(_relationship_type, relationship_type),
    relationship_reason = CASE
      WHEN _clear_relationship_reason THEN NULL
      WHEN _relationship_reason IS NOT NULL THEN _reason
      ELSE relationship_reason END,
    source_dependency_id = CASE
      WHEN _clear_source_dependency_id THEN NULL
      WHEN _source_dependency_id IS NOT NULL THEN _source_dependency_id
      ELSE source_dependency_id END,
    included_in_package = COALESCE(_included_in_package, included_in_package),
    updated_by = auth.uid(),
    updated_at = now()
  WHERE id = _cross_project_link_id;

  PERFORM public.log_activity_event(_row.organization_id, auth.uid(),
    'governance_record_cross_project_link_updated', 'governance_record', _ln.governance_record_id,
    jsonb_build_object('project_id', _row.project_id, 'cross_project_link_id', _cross_project_link_id,
                       'linked_project_id', _new_linked),
    _row.workspace_id);
END; $function$

CREATE OR REPLACE FUNCTION public.update_governance_record_evidence_file(_evidence_file_id uuid, _evidence_title text DEFAULT NULL::text, _evidence_summary text DEFAULT NULL::text, _evidence_date date DEFAULT NULL::date, _relevance_level text DEFAULT NULL::text, _included_in_package boolean DEFAULT NULL::boolean, _clear_evidence_summary boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE _ev governance_record_evidence_files%ROWTYPE;
        _row governance_records%ROWTYPE;
        _t text; _s text;
BEGIN
  SELECT * INTO _ev FROM governance_record_evidence_files WHERE id = _evidence_file_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Evidence file not found' USING ERRCODE='P0002'; END IF;
  SELECT * INTO _row FROM governance_records WHERE id = _ev.governance_record_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Parent record not found' USING ERRCODE='P0002'; END IF;
  IF _row.record_kind IS DISTINCT FROM 'decision_case' THEN
    RAISE EXCEPTION 'Evidence files are only allowed on decision_case records' USING ERRCODE='22023';
  END IF;
  PERFORM _gov_assert_project_write(_row.project_id);

  IF _relevance_level IS NOT NULL AND _relevance_level NOT IN ('high','medium','low') THEN
    RAISE EXCEPTION 'Invalid relevance_level' USING ERRCODE='22023';
  END IF;
  IF _evidence_title IS NOT NULL THEN
    _t := NULLIF(trim(_evidence_title), '');
    IF _t IS NULL THEN RAISE EXCEPTION 'Evidence title cannot be blank' USING ERRCODE='22023'; END IF;
  END IF;
  IF _evidence_summary IS NOT NULL THEN
    _s := NULLIF(trim(_evidence_summary), '');
  END IF;

  UPDATE governance_record_evidence_files SET
    evidence_title = COALESCE(_t, evidence_title),
    evidence_summary = CASE WHEN _clear_evidence_summary THEN NULL
                            WHEN _evidence_summary IS NOT NULL THEN _s
                            ELSE evidence_summary END,
    evidence_date = COALESCE(_evidence_date, evidence_date),
    relevance_level = COALESCE(_relevance_level, relevance_level),
    included_in_package = COALESCE(_included_in_package, included_in_package),
    updated_by = auth.uid(),
    updated_at = now()
  WHERE id = _evidence_file_id;

  PERFORM log_activity_event(_row.organization_id, auth.uid(),
    'governance_record_evidence_file_updated', 'governance_record', _ev.governance_record_id,
    jsonb_build_object('project_id', _row.project_id, 'evidence_file_id', _evidence_file_id),
    _row.workspace_id);
END; $function$

CREATE OR REPLACE FUNCTION public.update_governance_record_evidence_reference(_evidence_id uuid, _evidence_type text DEFAULT NULL::text, _title text DEFAULT NULL::text, _external_url text DEFAULT NULL::text, _summary text DEFAULT NULL::text, _evidence_date date DEFAULT NULL::date, _owner_stakeholder_id uuid DEFAULT NULL::uuid, _relevance_level text DEFAULT NULL::text, _included_in_package boolean DEFAULT NULL::boolean, _clear_summary boolean DEFAULT false, _clear_evidence_date boolean DEFAULT false, _clear_owner_stakeholder_id boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE _ev governance_record_evidence_references%ROWTYPE;
        _row governance_records%ROWTYPE;
        _t text; _u text; _s text;
BEGIN
  SELECT * INTO _ev FROM governance_record_evidence_references WHERE id = _evidence_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Evidence reference not found' USING ERRCODE='P0002'; END IF;
  SELECT * INTO _row FROM governance_records WHERE id = _ev.governance_record_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Parent record not found' USING ERRCODE='P0002'; END IF;
  IF _row.record_kind IS DISTINCT FROM 'decision_case' THEN
    RAISE EXCEPTION 'Evidence references are only allowed on decision_case records' USING ERRCODE='22023';
  END IF;
  PERFORM _gov_assert_project_write(_row.project_id);

  IF _evidence_type IS NOT NULL AND _evidence_type NOT IN
    ('sharepoint_file','onenote_page','outlook_reference','teams_reference','meeting_minutes','other_link') THEN
    RAISE EXCEPTION 'Invalid evidence_type' USING ERRCODE='22023';
  END IF;
  IF _relevance_level IS NOT NULL AND _relevance_level NOT IN ('high','medium','low') THEN
    RAISE EXCEPTION 'Invalid relevance_level' USING ERRCODE='22023';
  END IF;

  IF _title IS NOT NULL THEN
    _t := NULLIF(trim(_title), '');
    IF _t IS NULL THEN RAISE EXCEPTION 'Title cannot be blank' USING ERRCODE='22023'; END IF;
  END IF;
  IF _external_url IS NOT NULL THEN
    _u := NULLIF(trim(_external_url), '');
    IF _u IS NULL THEN RAISE EXCEPTION 'External URL cannot be blank' USING ERRCODE='22023'; END IF;
    IF lower(_u) NOT LIKE 'http://%' AND lower(_u) NOT LIKE 'https://%' THEN
      RAISE EXCEPTION 'External URL must start with http:// or https://' USING ERRCODE='22023';
    END IF;
  END IF;
  IF _summary IS NOT NULL THEN
    _s := NULLIF(trim(_summary), '');
  END IF;

  IF _owner_stakeholder_id IS NOT NULL AND NOT _clear_owner_stakeholder_id THEN
    IF NOT EXISTS (SELECT 1 FROM project_stakeholders s
                   WHERE s.id = _owner_stakeholder_id AND s.project_id = _row.project_id) THEN
      RAISE EXCEPTION 'Owner stakeholder does not belong to this project' USING ERRCODE='22023';
    END IF;
  END IF;

  UPDATE governance_record_evidence_references SET
    evidence_type = COALESCE(_evidence_type, evidence_type),
    title = COALESCE(_t, title),
    external_url = COALESCE(_u, external_url),
    summary = CASE WHEN _clear_summary THEN NULL
                   WHEN _summary IS NOT NULL THEN _s
                   ELSE summary END,
    evidence_date = CASE WHEN _clear_evidence_date THEN NULL
                         WHEN _evidence_date IS NOT NULL THEN _evidence_date
                         ELSE evidence_date END,
    owner_stakeholder_id = CASE WHEN _clear_owner_stakeholder_id THEN NULL
                                WHEN _owner_stakeholder_id IS NOT NULL THEN _owner_stakeholder_id
                                ELSE owner_stakeholder_id END,
    relevance_level = COALESCE(_relevance_level, relevance_level),
    included_in_package = COALESCE(_included_in_package, included_in_package),
    updated_by = auth.uid(),
    updated_at = now()
  WHERE id = _evidence_id;

  PERFORM log_activity_event(_row.organization_id, auth.uid(),
    'governance_record_evidence_reference_updated', 'governance_record', _ev.governance_record_id,
    jsonb_build_object('project_id', _row.project_id, 'evidence_id', _evidence_id),
    _row.workspace_id);
END; $function$

CREATE OR REPLACE FUNCTION public.update_project_people_preset_member(_member_id uuid, _expected_preset_updated_at timestamp with time zone, _canonical_role_key text, _role_label text, _external_name text, _correlation_id text DEFAULT NULL::text, _idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor          uuid := auth.uid();
  v_preset         public.project_people_presets;
  v_member         public.project_people_preset_members;
  v_role_norm      text;
  v_canonical_norm text;
  v_external_norm  text;
  v_dupe_external  uuid;
  r                record;
BEGIN
  SELECT * INTO v_member FROM public.project_people_preset_members WHERE id = _member_id FOR UPDATE;
  IF v_member.id IS NULL THEN
    RETURN public.pmg_build_result('not_authorized', 'update_project_people_preset_member',
      'project_people_preset_member', NULL, NULL, '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL);
  END IF;
  SELECT * INTO v_preset FROM public.project_people_presets WHERE id = v_member.preset_id FOR UPDATE;
  PERFORM public._ppp_authorize_write(v_actor, v_preset, true);

  IF v_preset.updated_at IS DISTINCT FROM _expected_preset_updated_at THEN
    RETURN public.pmg_build_result('conflict', 'update_project_people_preset_member',
      'project_people_preset_member', _member_id, NULL, '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb,
      jsonb_build_object('server_updated_at', v_preset.updated_at));
  END IF;

  v_role_norm      := NULLIF(btrim(COALESCE(_role_label, '')), '');
  v_canonical_norm := NULLIF(btrim(COALESCE(_canonical_role_key, '')), '');
  v_external_norm  := NULLIF(btrim(COALESCE(_external_name, '')), '');

  -- Only external stakeholders may have external_name changed
  IF NOT (v_member.member_kind = 'stakeholder' AND v_member.stakeholder_type = 'external') THEN
    v_external_norm := v_member.external_name; -- leave encrypted value alone via IS DISTINCT check below
  END IF;

  -- canonical_role_key only for team_member
  IF v_member.member_kind <> 'team_member' THEN
    v_canonical_norm := NULL;
  END IF;

  IF v_member.member_kind = 'stakeholder' AND v_member.stakeholder_type = 'external'
     AND v_external_norm IS NOT NULL THEN
    FOR r IN
      SELECT id, external_name FROM public.project_people_preset_members
       WHERE preset_id = v_member.preset_id
         AND member_kind = 'stakeholder' AND stakeholder_type = 'external'
         AND id <> _member_id
       FOR UPDATE
    LOOP
      IF lower(btrim(public.btpm_decrypt(r.external_name, v_preset.organization_id))) = lower(v_external_norm) THEN
        v_dupe_external := r.id; EXIT;
      END IF;
    END LOOP;
    IF v_dupe_external IS NOT NULL THEN
      RETURN public.pmg_build_result('invalid', 'update_project_people_preset_member',
        'project_people_preset_member', _member_id, NULL,
        jsonb_build_object('reason','duplicate_external_name'),
        '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL);
    END IF;
  END IF;

  IF v_member.member_kind = 'stakeholder' AND v_member.stakeholder_type = 'external' AND v_external_norm IS NULL THEN
    RETURN public.pmg_build_result('invalid', 'update_project_people_preset_member',
      'project_people_preset_member', _member_id, NULL,
      jsonb_build_object('reason','external_name_required'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL);
  END IF;

  UPDATE public.project_people_preset_members
     SET role_label         = v_role_norm,
         canonical_role_key = v_canonical_norm,
         external_name      = CASE WHEN member_kind='stakeholder' AND stakeholder_type='external'
                                   THEN v_external_norm ELSE external_name END
   WHERE id = _member_id;

  UPDATE public.project_people_presets SET updated_at = now() WHERE id = v_member.preset_id;

  PERFORM public._ppp_record_audit('applied', 'update_project_people_preset_member',
    v_preset, 'project_people_preset_member', _member_id, _correlation_id, _idempotency_key, '{}'::jsonb);

  RETURN public.pmg_build_result('applied', 'update_project_people_preset_member',
    'project_people_preset_member', _member_id, NULL,
    jsonb_build_object('id', _member_id),
    '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL);
END; $function$

CREATE OR REPLACE FUNCTION public.update_project_stakeholder(_stakeholder_id uuid, _role_label text, _external_name text, _notes text, _start_date date DEFAULT NULL::date)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_row public.project_stakeholders;
  v_old_role text;
  v_old_name text;
  v_old_start_date date;
  v_new_name text;
  v_new_role text := NULLIF(btrim(COALESCE(_role_label, '')), '');
  v_new_notes text := NULLIF(btrim(COALESCE(_notes, '')), '');
  v_display text;
BEGIN
  IF v_actor IS NULL OR NOT public.is_active_user(v_actor) THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT *
  INTO v_row
  FROM public.project_stakeholders
  WHERE id = _stakeholder_id;

  IF v_row.id IS NULL THEN
    RAISE EXCEPTION 'Stakeholder not found';
  END IF;

  IF NOT (public.is_org_admin(v_actor, v_row.organization_id) OR public.has_pm_authority(v_actor, v_row.workspace_id)) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  IF v_row.removed_at IS NOT NULL THEN
    RAISE EXCEPTION 'Cannot edit a removed stakeholder; restore first';
  END IF;

  v_old_role := v_row.role_label;
  v_old_name := v_row.external_name;
  v_old_start_date := v_row.start_date;
  v_new_name := CASE
    WHEN v_row.stakeholder_type = 'external' AND _external_name IS NOT NULL AND length(btrim(_external_name)) > 0
      THEN btrim(_external_name)
    ELSE v_row.external_name
  END;

  UPDATE public.project_stakeholders
  SET role_label = v_new_role,
      external_name = v_new_name,
      notes = v_new_notes,
      start_date = _start_date
  WHERE id = _stakeholder_id;

  IF v_row.stakeholder_type = 'workspace_member' THEN
    SELECT COALESCE(display_name, email, v_row.user_id::text)
    INTO v_display
    FROM public.profiles
    WHERE id = v_row.user_id;
  ELSE
    v_display := v_new_name;
  END IF;

  PERFORM public.log_activity_event(
    v_row.organization_id,
    v_actor,
    'stakeholder_updated',
    'project',
    v_row.project_id,
    jsonb_build_object(
      'stakeholder_id', _stakeholder_id,
      'stakeholder_type', v_row.stakeholder_type,
      'display_name', v_display,
      'old_role_label', v_old_role,
      'new_role_label', v_new_role,
      'old_external_name', v_old_name,
      'new_external_name', v_new_name,
      'old_start_date', v_old_start_date,
      'new_start_date', _start_date
    ),
    v_row.workspace_id
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.update_project_template_metadata(_template_id uuid, _name text, _description text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _caller uuid := auth.uid();
  r RECORD;
BEGIN
  IF _caller IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;

  IF _name IS NULL OR length(btrim(_name)) = 0 THEN
    RAISE EXCEPTION 'invalid template name';
  END IF;

  SELECT id, organization_id, workspace_id
    INTO r
    FROM public.project_templates
   WHERE id = _template_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'template not found';
  END IF;

  IF NOT public.has_pm_authority(_caller, r.workspace_id) THEN
    RAISE EXCEPTION 'access denied: PM authority required' USING ERRCODE = '42501';
  END IF;

  -- Write plaintext; the project_templates encrypt trigger is the single
  -- source of encryption responsibility for template metadata at rest.
  UPDATE public.project_templates
     SET name = _name,
         description = _description,
         updated_at = now(),
         updated_by = _caller
   WHERE id = _template_id;

  RETURN jsonb_build_object(
    'template_id', _template_id,
    'workspace_id', r.workspace_id,
    'organization_id', r.organization_id,
    'updated_at', now(),
    'updated_by', _caller
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.update_risk_with_links(_risk_id uuid, _title text, _description text, _mitigation_plan text, _likelihood text, _impact text, _status text, _user_links jsonb DEFAULT '[]'::jsonb, _object_links jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_row public.risks%ROWTYPE;
  v jsonb; v_idx int;
  v_project_id uuid;
  v_old_title text; v_old_description text; v_old_mitigation text;
  v_old_likelihood text; v_old_impact text;
  v_old_user_ids uuid[]; v_old_user_labels jsonb;
  v_old_obj_keys text[]; v_old_obj_labels jsonb;
  v_new_user_ids uuid[]; v_new_user_labels jsonb;
  v_new_obj_keys text[]; v_new_obj_labels jsonb;
  v_scalar_diff jsonb := '{}'::jsonb;
  v_new_title text; v_new_description text; v_new_mitigation text;
  v_new_likelihood text; v_new_impact text;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF NOT public.is_active_user(v_uid) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;

  SELECT * INTO v_row FROM public.risks WHERE id = _risk_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Risk not found'; END IF;

  IF NOT public.has_pm_authority(v_uid, v_row.workspace_id) THEN
    RAISE EXCEPTION 'PM authority required';
  END IF;

  IF NOT public.can_write_demo(v_uid, v_row.workspace_id) THEN
    RAISE EXCEPTION 'Not authorized: this workspace is read-only';
  END IF;

  v_project_id := public._project_id_from_target(v_row.target_type, v_row.target_id);

  PERFORM public._validate_object_links(_object_links, v_row.workspace_id, v_row.organization_id);
  PERFORM public._validate_user_links(_user_links, v_row.workspace_id, v_project_id);

  v_old_title       := v_row.title;
  v_old_description := public.btpm_decrypt(v_row.description,    v_row.organization_id);
  v_old_mitigation  := public.btpm_decrypt(v_row.mitigation_plan, v_row.organization_id);
  v_old_likelihood  := v_row.likelihood::text;
  v_old_impact      := v_row.impact::text;

  SELECT COALESCE(array_agg(COALESCE(eul.user_id, eul.stakeholder_id) ORDER BY eul.sort_order), ARRAY[]::uuid[]),
         COALESCE(jsonb_agg(jsonb_build_object(
           'user_id', COALESCE(eul.user_id, eul.stakeholder_id),
           'display_name', CASE
             WHEN eul.user_id IS NOT NULL THEN public.btpm_decrypt(p.display_name, p.organization_id)
             ELSE COALESCE(s.external_name, public.btpm_decrypt(sp.display_name, sp.organization_id))
           END
         ) ORDER BY eul.sort_order), '[]'::jsonb)
    INTO v_old_user_ids, v_old_user_labels
    FROM public.entity_user_links eul
    LEFT JOIN public.profiles p ON p.id = eul.user_id
    LEFT JOIN public.project_stakeholders s ON s.id = eul.stakeholder_id
    LEFT JOIN public.profiles sp ON sp.id = s.user_id
   WHERE eul.owner_type='risk' AND eul.owner_id=_risk_id AND eul.link_role='related_person';

  SELECT COALESCE(array_agg((eol.referenced_type || ':' || eol.referenced_id::text) ORDER BY eol.sort_order), ARRAY[]::text[]),
         COALESCE(jsonb_agg(jsonb_build_object(
           'referenced_type', eol.referenced_type,
           'referenced_id',   eol.referenced_id,
           'display_label',   CASE eol.referenced_type
             WHEN 'project' THEN (SELECT public.btpm_decrypt(p.name, p.organization_id) FROM public.projects p  WHERE p.id  = eol.referenced_id)
             WHEN 'phase'   THEN (SELECT public.btpm_decrypt(ph.name, ph.organization_id) FROM public.phases ph WHERE ph.id = eol.referenced_id)
             WHEN 'task'    THEN (SELECT public.btpm_decrypt(t.name,  t.organization_id) FROM public.tasks  t  WHERE t.id  = eol.referenced_id)
           END
         ) ORDER BY eol.sort_order), '[]'::jsonb)
    INTO v_old_obj_keys, v_old_obj_labels
    FROM public.entity_object_links eol
   WHERE eol.owner_type='risk' AND eol.owner_id=_risk_id AND eol.link_role='related_object';

  UPDATE public.risks SET
    title = COALESCE(_title, title),
    description = _description,
    mitigation_plan = _mitigation_plan,
    likelihood = COALESCE(_likelihood::risk_likelihood, likelihood),
    impact = COALESCE(_impact::pm_priority, impact),
    status = COALESCE(_status::risk_status, status)
  WHERE id = _risk_id;

  DELETE FROM public.entity_user_links   WHERE owner_type='risk' AND owner_id=_risk_id AND link_role='related_person';
  DELETE FROM public.entity_object_links WHERE owner_type='risk' AND owner_id=_risk_id AND link_role='related_object';

  v_idx := 0;
  FOR v IN SELECT * FROM jsonb_array_elements(COALESCE(_user_links,'[]'::jsonb)) LOOP
    INSERT INTO public.entity_user_links (owner_type, owner_id, organization_id, workspace_id,
                                          user_id, stakeholder_id, link_role, sort_order, created_by)
    VALUES ('risk', _risk_id, v_row.organization_id, v_row.workspace_id,
            NULLIF(v->>'user_id','')::uuid,
            NULLIF(v->>'stakeholder_id','')::uuid,
            'related_person', v_idx, v_uid)
    ON CONFLICT DO NOTHING;
    v_idx := v_idx + 1;
  END LOOP;

  v_idx := 0;
  FOR v IN SELECT * FROM jsonb_array_elements(COALESCE(_object_links,'[]'::jsonb)) LOOP
    INSERT INTO public.entity_object_links (owner_type, owner_id, organization_id, workspace_id, referenced_type, referenced_id, link_role, sort_order, created_by)
    VALUES ('risk', _risk_id, v_row.organization_id, v_row.workspace_id, v->>'referenced_type', (v->>'referenced_id')::uuid, 'related_object', v_idx, v_uid)
    ON CONFLICT DO NOTHING;
    v_idx := v_idx + 1;
  END LOOP;

  v_new_title       := COALESCE(_title, v_old_title);
  v_new_description := _description;
  v_new_mitigation  := _mitigation_plan;
  v_new_likelihood  := COALESCE(_likelihood, v_old_likelihood);
  v_new_impact      := COALESCE(_impact,     v_old_impact);

  IF v_new_title       IS DISTINCT FROM v_old_title       THEN v_scalar_diff := v_scalar_diff || jsonb_build_object('title',           jsonb_build_object('old', v_old_title,       'new', v_new_title));       END IF;
  IF v_new_description IS DISTINCT FROM v_old_description THEN v_scalar_diff := v_scalar_diff || jsonb_build_object('description',     jsonb_build_object('old', v_old_description, 'new', v_new_description)); END IF;
  IF v_new_mitigation  IS DISTINCT FROM v_old_mitigation  THEN v_scalar_diff := v_scalar_diff || jsonb_build_object('mitigation_plan', jsonb_build_object('old', v_old_mitigation,  'new', v_new_mitigation));  END IF;
  IF v_new_likelihood  IS DISTINCT FROM v_old_likelihood  THEN v_scalar_diff := v_scalar_diff || jsonb_build_object('likelihood',      jsonb_build_object('old', v_old_likelihood,  'new', v_new_likelihood));  END IF;
  IF v_new_impact      IS DISTINCT FROM v_old_impact      THEN v_scalar_diff := v_scalar_diff || jsonb_build_object('impact',          jsonb_build_object('old', v_old_impact,      'new', v_new_impact));      END IF;

  SELECT COALESCE(array_agg(COALESCE(eul.user_id, eul.stakeholder_id) ORDER BY eul.sort_order), ARRAY[]::uuid[]),
         COALESCE(jsonb_agg(jsonb_build_object(
           'user_id', COALESCE(eul.user_id, eul.stakeholder_id),
           'display_name', CASE
             WHEN eul.user_id IS NOT NULL THEN public.btpm_decrypt(p.display_name, p.organization_id)
             ELSE COALESCE(s.external_name, public.btpm_decrypt(sp.display_name, sp.organization_id))
           END
         ) ORDER BY eul.sort_order), '[]'::jsonb)
    INTO v_new_user_ids, v_new_user_labels
    FROM public.entity_user_links eul
    LEFT JOIN public.profiles p ON p.id = eul.user_id
    LEFT JOIN public.project_stakeholders s ON s.id = eul.stakeholder_id
    LEFT JOIN public.profiles sp ON sp.id = s.user_id
   WHERE eul.owner_type='risk' AND eul.owner_id=_risk_id AND eul.link_role='related_person';

  SELECT COALESCE(array_agg((eol.referenced_type || ':' || eol.referenced_id::text) ORDER BY eol.sort_order), ARRAY[]::text[]),
         COALESCE(jsonb_agg(jsonb_build_object(
           'referenced_type', eol.referenced_type,
           'referenced_id',   eol.referenced_id,
           'display_label',   CASE eol.referenced_type
             WHEN 'project' THEN (SELECT public.btpm_decrypt(p.name, p.organization_id) FROM public.projects p  WHERE p.id  = eol.referenced_id)
             WHEN 'phase'   THEN (SELECT public.btpm_decrypt(ph.name, ph.organization_id) FROM public.phases ph WHERE ph.id = eol.referenced_id)
             WHEN 'task'    THEN (SELECT public.btpm_decrypt(t.name,  t.organization_id) FROM public.tasks  t  WHERE t.id  = eol.referenced_id)
           END
         ) ORDER BY eol.sort_order), '[]'::jsonb)
    INTO v_new_obj_keys, v_new_obj_labels
    FROM public.entity_object_links eol
   WHERE eol.owner_type='risk' AND eol.owner_id=_risk_id AND eol.link_role='related_object';

  PERFORM public._log_entity_material_update(
    'risk', _risk_id, v_row.organization_id, v_row.workspace_id,
    v_row.target_type, v_row.target_id,
    v_scalar_diff,
    v_old_user_ids, v_new_user_ids,
    v_old_obj_keys, v_new_obj_keys,
    v_old_user_labels, v_new_user_labels,
    v_old_obj_labels, v_new_obj_labels,
    v_new_title
  );

  RETURN jsonb_build_object('id', _risk_id);
END $function$

CREATE OR REPLACE FUNCTION public.update_roadmap_story_pack_config(_story_pack_id uuid, _title text DEFAULT NULL::text, _guidance text DEFAULT NULL::text, _audience text DEFAULT NULL::text, _focus text DEFAULT NULL::text, _primary_workspace_id uuid DEFAULT NULL::uuid, _program_id uuid DEFAULT NULL::uuid, _scope_config jsonb DEFAULT NULL::jsonb, _source_config jsonb DEFAULT NULL::jsonb, _patch_title boolean DEFAULT false, _patch_guidance boolean DEFAULT false, _patch_audience boolean DEFAULT false, _patch_focus boolean DEFAULT false, _patch_primary_workspace boolean DEFAULT false, _patch_program boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _pack public.roadmap_story_packs;
BEGIN
  IF _uid IS NULL OR NOT public.is_active_user(_uid) THEN
    RAISE EXCEPTION 'unauthorized' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO _pack FROM public.roadmap_story_packs WHERE id = _story_pack_id FOR UPDATE;
  IF NOT FOUND OR _pack.created_by <> _uid THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  PERFORM public.assert_roadmap_story_pack_editable(_story_pack_id);

  IF _patch_primary_workspace AND _primary_workspace_id IS NOT NULL THEN
    IF NOT EXISTS (SELECT 1 FROM public.workspaces WHERE id = _primary_workspace_id AND organization_id = _pack.organization_id)
       OR NOT public.is_workspace_member(_uid, _primary_workspace_id) THEN
      RAISE EXCEPTION 'forbidden: primary workspace not accessible' USING ERRCODE = '42501';
    END IF;
  END IF;

  IF _patch_program AND _program_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.programs p
      JOIN public.workspaces w ON w.id = p.workspace_id
      WHERE p.id = _program_id AND w.organization_id = _pack.organization_id AND public.is_workspace_member(_uid, p.workspace_id)
    ) THEN
      RAISE EXCEPTION 'forbidden: program not accessible' USING ERRCODE = '42501';
    END IF;
  END IF;

  IF _scope_config IS NOT NULL THEN
    PERFORM public.validate_roadmap_story_scope(_uid, _pack.organization_id, _scope_config);
  END IF;

  UPDATE public.roadmap_story_packs SET
    title_encrypted          = CASE WHEN _patch_title    THEN (CASE WHEN _title    IS NULL OR _title    = '' THEN NULL ELSE public.btpm_encrypt(_title,    _pack.organization_id) END) ELSE title_encrypted END,
    user_guidance_encrypted  = CASE WHEN _patch_guidance THEN (CASE WHEN _guidance IS NULL OR _guidance = '' THEN NULL ELSE public.btpm_encrypt(_guidance, _pack.organization_id) END) ELSE user_guidance_encrypted END,
    audience                 = CASE WHEN _patch_audience THEN NULLIF(_audience,'') ELSE audience END,
    focus                    = CASE WHEN _patch_focus    THEN NULLIF(_focus,'')    ELSE focus END,
    primary_workspace_id     = CASE WHEN _patch_primary_workspace THEN _primary_workspace_id ELSE primary_workspace_id END,
    program_id               = CASE WHEN _patch_program  THEN _program_id ELSE program_id END,
    scope_config             = COALESCE(_scope_config, scope_config),
    source_config            = COALESCE(_source_config, source_config)
  WHERE id = _story_pack_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.update_roadmap_story_pack_external_file(_file_id uuid, _display_name text DEFAULT NULL::text, _web_url text DEFAULT NULL::text, _user_note text DEFAULT NULL::text, _mime_type text DEFAULT NULL::text, _size_bytes bigint DEFAULT NULL::bigint, _include_in_story boolean DEFAULT NULL::boolean, _patch_display_name boolean DEFAULT false, _patch_web_url boolean DEFAULT false, _patch_user_note boolean DEFAULT false, _patch_mime_type boolean DEFAULT false, _patch_size_bytes boolean DEFAULT false, _patch_include_in_story boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _story_pack_id uuid;
  _org_id uuid;
BEGIN
  IF _uid IS NULL OR NOT public.is_active_user(_uid) THEN
    RAISE EXCEPTION 'unauthorized' USING ERRCODE = '42501';
  END IF;
  SELECT f.story_pack_id, p.organization_id INTO _story_pack_id, _org_id
  FROM public.roadmap_story_pack_external_files f
  JOIN public.roadmap_story_packs p ON p.id = f.story_pack_id
  WHERE f.id = _file_id;
  IF _story_pack_id IS NULL OR NOT public.is_story_pack_owner(_uid, _story_pack_id) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  PERFORM public.assert_roadmap_story_pack_editable(_story_pack_id);

  UPDATE public.roadmap_story_pack_external_files SET
    display_name_encrypted = CASE WHEN _patch_display_name THEN (CASE WHEN _display_name IS NULL OR _display_name = '' THEN NULL ELSE public.btpm_encrypt(_display_name, _org_id) END) ELSE display_name_encrypted END,
    web_url_encrypted      = CASE WHEN _patch_web_url      THEN (CASE WHEN _web_url      IS NULL OR _web_url      = '' THEN NULL ELSE public.btpm_encrypt(_web_url,      _org_id) END) ELSE web_url_encrypted END,
    user_note_encrypted    = CASE WHEN _patch_user_note    THEN (CASE WHEN _user_note    IS NULL OR _user_note    = '' THEN NULL ELSE public.btpm_encrypt(_user_note,    _org_id) END) ELSE user_note_encrypted END,
    mime_type              = CASE WHEN _patch_mime_type    THEN _mime_type ELSE mime_type END,
    size_bytes             = CASE WHEN _patch_size_bytes   THEN _size_bytes ELSE size_bytes END,
    include_in_story       = CASE WHEN _patch_include_in_story THEN COALESCE(_include_in_story, include_in_story) ELSE include_in_story END
  WHERE id = _file_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.update_roadmap_story_pack_note(_note_id uuid, _body text DEFAULT NULL::text, _label text DEFAULT NULL::text, _include_in_story boolean DEFAULT NULL::boolean, _sort_order integer DEFAULT NULL::integer, _patch_body boolean DEFAULT false, _patch_label boolean DEFAULT false, _patch_include boolean DEFAULT false, _patch_sort boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _story_pack_id uuid;
  _org_id uuid;
BEGIN
  IF _uid IS NULL OR NOT public.is_active_user(_uid) THEN
    RAISE EXCEPTION 'unauthorized' USING ERRCODE = '42501';
  END IF;
  SELECT n.story_pack_id, p.organization_id INTO _story_pack_id, _org_id
  FROM public.roadmap_story_pack_notes n
  JOIN public.roadmap_story_packs p ON p.id = n.story_pack_id
  WHERE n.id = _note_id;
  IF _story_pack_id IS NULL OR NOT public.is_story_pack_owner(_uid, _story_pack_id) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  PERFORM public.assert_roadmap_story_pack_editable(_story_pack_id);

  IF _patch_body AND (_body IS NULL OR length(_body) = 0) THEN
    RAISE EXCEPTION 'body required' USING ERRCODE = '22023';
  END IF;

  UPDATE public.roadmap_story_pack_notes SET
    body_encrypted   = CASE WHEN _patch_body  THEN public.btpm_encrypt(_body, _org_id) ELSE body_encrypted END,
    label_encrypted  = CASE WHEN _patch_label THEN (CASE WHEN _label IS NULL OR _label = '' THEN NULL ELSE public.btpm_encrypt(_label, _org_id) END) ELSE label_encrypted END,
    include_in_story = CASE WHEN _patch_include THEN COALESCE(_include_in_story, include_in_story) ELSE include_in_story END,
    sort_order       = CASE WHEN _patch_sort THEN _sort_order ELSE sort_order END
  WHERE id = _note_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.update_roadmap_story_pack_visual_settings(_story_pack_id uuid, _settings jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _pack public.roadmap_story_packs;
BEGIN
  IF _uid IS NULL OR NOT public.is_active_user(_uid) THEN
    RAISE EXCEPTION 'unauthorized' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO _pack FROM public.roadmap_story_packs WHERE id = _story_pack_id FOR UPDATE;
  IF NOT FOUND OR _pack.created_by <> _uid THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF _pack.status = 'archived' THEN
    RAISE EXCEPTION 'story_pack_archived' USING ERRCODE = '22023';
  END IF;
  IF _settings IS NOT NULL AND jsonb_typeof(_settings) <> 'object' THEN
    RAISE EXCEPTION 'invalid_visual_settings' USING ERRCODE = '22023';
  END IF;

  UPDATE public.roadmap_story_packs
     SET visual_settings = _settings,
         updated_at = now()
   WHERE id = _story_pack_id;

  RETURN COALESCE(_settings, 'null'::jsonb);
END;
$function$

CREATE OR REPLACE FUNCTION public.upsert_governance_record_decision_outcome(_record_id uuid, _decision_result text, _final_decision_text text, _decision_date date, _decided_by_text text DEFAULT NULL::text, _approval_forum text DEFAULT NULL::text, _decision_rationale text DEFAULT NULL::text, _conditions_guardrails text DEFAULT NULL::text, _residual_risks text DEFAULT NULL::text, _follow_up_actions text DEFAULT NULL::text, _implementation_owner_stakeholder_id uuid DEFAULT NULL::uuid, _implementation_target_date date DEFAULT NULL::date, _signoff_status text DEFAULT 'draft'::text, _signoff_evidence_url text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  _row public.governance_records%ROWTYPE;
  _existing_id uuid;
  _existing_closed_at timestamptz;
  _id uuid;
  _final text; _decided text; _forum text; _rat text; _cond text; _risks text; _follow text; _url text;
BEGIN
  SELECT * INTO _row FROM public.governance_records WHERE id = _record_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Record not found' USING ERRCODE='P0002'; END IF;
  IF _row.record_kind IS DISTINCT FROM 'decision_case' THEN
    RAISE EXCEPTION 'Decision outcomes are only allowed on decision_case records' USING ERRCODE='22023';
  END IF;
  PERFORM public._gov_assert_project_write(_row.project_id);

  IF _row.decision_stage = 'closed' THEN
    RAISE EXCEPTION 'Closed decision cases cannot be edited' USING ERRCODE='22023';
  END IF;

  IF _decision_result NOT IN ('approved','approved_with_conditions','rejected','deferred') THEN
    RAISE EXCEPTION 'Invalid decision_result %', _decision_result USING ERRCODE='22023';
  END IF;
  IF _signoff_status NOT IN ('draft','ready_for_signoff','signed_off') THEN
    RAISE EXCEPTION 'Invalid signoff_status %', _signoff_status USING ERRCODE='22023';
  END IF;

  _final := NULLIF(trim(COALESCE(_final_decision_text, '')), '');
  IF _final IS NULL THEN
    RAISE EXCEPTION 'final_decision_text is required' USING ERRCODE='22023';
  END IF;
  IF _decision_date IS NULL THEN
    RAISE EXCEPTION 'decision_date is required' USING ERRCODE='22023';
  END IF;

  _decided := NULLIF(trim(COALESCE(_decided_by_text, '')), '');
  _forum   := NULLIF(trim(COALESCE(_approval_forum, '')), '');
  _rat     := NULLIF(trim(COALESCE(_decision_rationale, '')), '');
  _cond    := NULLIF(trim(COALESCE(_conditions_guardrails, '')), '');
  _risks   := NULLIF(trim(COALESCE(_residual_risks, '')), '');
  _follow  := NULLIF(trim(COALESCE(_follow_up_actions, '')), '');
  _url     := NULLIF(trim(COALESCE(_signoff_evidence_url, '')), '');

  IF _url IS NOT NULL AND _url NOT LIKE 'http://%' AND _url NOT LIKE 'https://%' THEN
    RAISE EXCEPTION 'signoff_evidence_url must start with http:// or https://' USING ERRCODE='22023';
  END IF;

  IF _implementation_owner_stakeholder_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.project_stakeholders s
      WHERE s.id = _implementation_owner_stakeholder_id AND s.project_id = _row.project_id
    ) THEN
      RAISE EXCEPTION 'Implementation owner stakeholder does not belong to this project' USING ERRCODE='22023';
    END IF;
  END IF;

  SELECT id, closed_at INTO _existing_id, _existing_closed_at
    FROM public.governance_record_decision_outcomes
   WHERE governance_record_id = _record_id;

  IF _existing_id IS NOT NULL AND _existing_closed_at IS NOT NULL THEN
    RAISE EXCEPTION 'Closed decision cases cannot be edited' USING ERRCODE='22023';
  END IF;

  IF _existing_id IS NULL THEN
    INSERT INTO public.governance_record_decision_outcomes (
      organization_id, workspace_id, project_id, governance_record_id,
      decision_result, final_decision_text, decision_date,
      decided_by_text, approval_forum, decision_rationale,
      conditions_guardrails, residual_risks, follow_up_actions,
      implementation_owner_stakeholder_id, implementation_target_date,
      signoff_status, signoff_evidence_url,
      created_by, updated_by
    ) VALUES (
      _row.organization_id, _row.workspace_id, _row.project_id, _record_id,
      _decision_result, _final, _decision_date,
      _decided, _forum, _rat,
      _cond, _risks, _follow,
      _implementation_owner_stakeholder_id, _implementation_target_date,
      _signoff_status, _url,
      auth.uid(), auth.uid()
    )
    RETURNING id INTO _id;
  ELSE
    UPDATE public.governance_record_decision_outcomes SET
      decision_result = _decision_result,
      final_decision_text = _final,
      decision_date = _decision_date,
      decided_by_text = _decided,
      approval_forum = _forum,
      decision_rationale = _rat,
      conditions_guardrails = _cond,
      residual_risks = _risks,
      follow_up_actions = _follow,
      implementation_owner_stakeholder_id = _implementation_owner_stakeholder_id,
      implementation_target_date = _implementation_target_date,
      signoff_status = _signoff_status,
      signoff_evidence_url = _url,
      updated_by = auth.uid(),
      updated_at = now()
    WHERE id = _existing_id
    RETURNING id INTO _id;
  END IF;

  IF _row.decision_stage IS DISTINCT FROM 'closed' THEN
    UPDATE public.governance_records
       SET decision_stage = 'decision_taken', updated_at = now()
     WHERE id = _record_id AND decision_stage IS DISTINCT FROM 'closed';
  END IF;

  PERFORM public.log_activity_event(_row.organization_id, auth.uid(),
    'governance_record_decision_outcome_saved', 'governance_record', _record_id,
    jsonb_build_object('project_id', _row.project_id,
                       'decision_outcome_id', _id,
                       'decision_result', _decision_result,
                       'signoff_status', _signoff_status,
                       'decision_date', _decision_date),
    _row.workspace_id);

  RETURN _id;
END; $function$

CREATE OR REPLACE FUNCTION public.upsert_project_closure_summary(_project_id uuid, _outcome_summary text DEFAULT NULL::text, _benefits_summary text DEFAULT NULL::text, _achievements_summary text DEFAULT NULL::text, _open_items_summary text DEFAULT NULL::text, _transition_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  _p record;
  _existing_id uuid;
  _id uuid;
  _proj_status text;
  _o text; _b text; _a text; _oi text; _tn text;
  _is_create boolean;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE='42501';
  END IF;
  IF NOT public.has_project_pm_authority(auth.uid(), _project_id) THEN
    RAISE EXCEPTION 'Project-edit authority required' USING ERRCODE='42501';
  END IF;

  SELECT organization_id, workspace_id, status::text
    INTO _p FROM public.projects WHERE id = _project_id;
  IF _p IS NULL THEN
    RAISE EXCEPTION 'Project not found' USING ERRCODE='P0002';
  END IF;
  _proj_status := _p.status;

  -- Normalize: trim & convert empty strings to NULL
  _o  := NULLIF(btrim(COALESCE(_outcome_summary, '')), '');
  _b  := NULLIF(btrim(COALESCE(_benefits_summary, '')), '');
  _a  := NULLIF(btrim(COALESCE(_achievements_summary, '')), '');
  _oi := NULLIF(btrim(COALESCE(_open_items_summary, '')), '');
  _tn := NULLIF(btrim(COALESCE(_transition_notes, '')), '');

  IF _o IS NULL AND _b IS NULL AND _a IS NULL AND _oi IS NULL AND _tn IS NULL THEN
    RAISE EXCEPTION 'Enter at least one closure summary field before saving.'
      USING ERRCODE='22023';
  END IF;

  -- Optional length guardrails (per-field 4000 chars)
  IF length(COALESCE(_o,''))  > 4000
     OR length(COALESCE(_b,''))  > 4000
     OR length(COALESCE(_a,''))  > 4000
     OR length(COALESCE(_oi,'')) > 4000
     OR length(COALESCE(_tn,'')) > 4000 THEN
    RAISE EXCEPTION 'Each closure summary field must be 4000 characters or fewer.'
      USING ERRCODE='22023';
  END IF;

  SELECT id INTO _existing_id
    FROM public.project_closure_summaries WHERE project_id = _project_id;

  IF _existing_id IS NULL THEN
    _is_create := true;
    INSERT INTO public.project_closure_summaries (
      organization_id, workspace_id, project_id,
      outcome_summary_encrypted, benefits_summary_encrypted,
      achievements_summary_encrypted, open_items_summary_encrypted,
      transition_notes_encrypted, created_by, updated_by
    ) VALUES (
      _p.organization_id, _p.workspace_id, _project_id,
      _o, _b, _a, _oi, _tn, auth.uid(), auth.uid()
    ) RETURNING id INTO _id;
  ELSE
    _is_create := false;
    UPDATE public.project_closure_summaries SET
      outcome_summary_encrypted      = _o,
      benefits_summary_encrypted     = _b,
      achievements_summary_encrypted = _a,
      open_items_summary_encrypted   = _oi,
      transition_notes_encrypted     = _tn,
      updated_by                     = auth.uid(),
      updated_at                     = now()
    WHERE id = _existing_id;
    _id := _existing_id;
  END IF;

  PERFORM public.log_activity_event(
    _p.organization_id, auth.uid(),
    CASE WHEN _is_create
         THEN 'project_closure_summary_created'
         ELSE 'project_closure_summary_updated' END,
    'project_closure_summary', _id,
    jsonb_build_object(
      'project_id', _project_id,
      'project_status_at_event', _proj_status,
      'post_closure', (_proj_status IN ('completed','cancelled'))
    ),
    _p.workspace_id);

  RETURN _id;
END;
$function$

CREATE OR REPLACE FUNCTION public.upsert_project_lessons_learned_document_metadata(_project_id uuid, _status text, _document_name text DEFAULT NULL::text, _sharepoint_web_url text DEFAULT NULL::text, _sharepoint_drive_id text DEFAULT NULL::text, _sharepoint_item_id text DEFAULT NULL::text, _created_in_sharepoint_at timestamp with time zone DEFAULT NULL::timestamp with time zone, _last_modified_at timestamp with time zone DEFAULT NULL::timestamp with time zone, _event_type text DEFAULT 'project_lessons_learned_document_status_changed'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  _p record;
  _existing record;
  _id uuid;
  _prev_status text;
  _is_create boolean := false;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE='42501';
  END IF;
  IF NOT public.has_project_pm_authority(auth.uid(), _project_id) THEN
    RAISE EXCEPTION 'Project-edit authority required' USING ERRCODE='42501';
  END IF;

  IF _status NOT IN ('not_created','available','missing_folder','creation_failed','link_broken') THEN
    RAISE EXCEPTION 'Invalid status: %', _status USING ERRCODE='22023';
  END IF;

  SELECT organization_id, workspace_id INTO _p
    FROM public.projects WHERE id = _project_id;
  IF _p IS NULL THEN
    RAISE EXCEPTION 'Project not found' USING ERRCODE='P0002';
  END IF;

  SELECT id, status INTO _existing
    FROM public.project_lessons_learned_documents WHERE project_id = _project_id;

  IF _existing.id IS NULL THEN
    _is_create := true;
    INSERT INTO public.project_lessons_learned_documents (
      organization_id, workspace_id, project_id,
      document_name_encrypted, sharepoint_web_url_encrypted,
      sharepoint_drive_id_encrypted, sharepoint_item_id_encrypted,
      created_in_sharepoint_at, last_modified_at,
      status, created_by, metadata_refreshed_at
    ) VALUES (
      _p.organization_id, _p.workspace_id, _project_id,
      _document_name, _sharepoint_web_url, _sharepoint_drive_id, _sharepoint_item_id,
      _created_in_sharepoint_at, _last_modified_at,
      _status, auth.uid(), now()
    ) RETURNING id INTO _id;
    _prev_status := NULL;
  ELSE
    _id := _existing.id;
    _prev_status := _existing.status;
    -- For non-available statuses, preserve prior encrypted fields when caller passes NULL
    UPDATE public.project_lessons_learned_documents SET
      document_name_encrypted       = COALESCE(_document_name, document_name_encrypted),
      sharepoint_web_url_encrypted  = COALESCE(_sharepoint_web_url, sharepoint_web_url_encrypted),
      sharepoint_drive_id_encrypted = COALESCE(_sharepoint_drive_id, sharepoint_drive_id_encrypted),
      sharepoint_item_id_encrypted  = COALESCE(_sharepoint_item_id, sharepoint_item_id_encrypted),
      created_in_sharepoint_at      = COALESCE(_created_in_sharepoint_at, created_in_sharepoint_at),
      last_modified_at              = COALESCE(_last_modified_at, last_modified_at),
      status                        = _status,
      metadata_refreshed_at         = now()
    WHERE id = _id;
  END IF;

  PERFORM public.log_activity_event(
    _p.organization_id, auth.uid(),
    _event_type, 'project_lessons_learned_document', _id,
    jsonb_build_object(
      'project_id', _project_id,
      'status', _status,
      'previous_status', _prev_status,
      'created', _is_create
    ),
    _p.workspace_id);

  RETURN _id;
END;
$function$

CREATE OR REPLACE FUNCTION public.upsert_sharepoint_project_binding(_project_id uuid, _binding_mode sharepoint_project_binding_mode, _folder_web_url text, _folder_relative_path text DEFAULT NULL::text, _folder_item_id text DEFAULT NULL::text, _resolved_site_web_url text DEFAULT NULL::text, _resolved_site_id text DEFAULT NULL::text, _resolved_library_web_url text DEFAULT NULL::text, _resolved_library_id_or_drive_id text DEFAULT NULL::text)
 RETURNS sharepoint_project_bindings
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_ws uuid; v_org uuid; v_existing public.sharepoint_project_bindings;
  v_row public.sharepoint_project_bindings; v_ws_binding_id uuid; v_is_restricted boolean;
BEGIN
  IF NOT public.is_active_user(auth.uid()) THEN RAISE EXCEPTION 'unauthorized'; END IF;
  SELECT workspace_id, organization_id INTO v_ws, v_org FROM public.projects WHERE id = _project_id;
  IF v_ws IS NULL THEN RAISE EXCEPTION 'project_not_found'; END IF;
  IF NOT public.has_project_pm_authority(auth.uid(), _project_id) THEN
    RAISE EXCEPTION 'unauthorized'; END IF;
  IF _folder_web_url IS NULL OR length(btrim(_folder_web_url)) = 0 THEN
    RAISE EXCEPTION 'folder_web_url_required'; END IF;
  IF _binding_mode = 'workspace_library_default' THEN
    SELECT id INTO v_ws_binding_id FROM public.sharepoint_workspace_bindings
    WHERE workspace_id = v_ws AND binding_status <> 'disabled' LIMIT 1;
    IF v_ws_binding_id IS NULL THEN RAISE EXCEPTION 'workspace_binding_required_for_default_mode'; END IF;
    v_is_restricted := false;
  ELSE
    IF _resolved_site_web_url IS NULL OR _resolved_library_web_url IS NULL THEN
      RAISE EXCEPTION 'resolved_site_and_library_required_for_restricted_mode'; END IF;
    v_ws_binding_id := NULL; v_is_restricted := true;
  END IF;
  SELECT * INTO v_existing FROM public.sharepoint_project_bindings
  WHERE project_id = _project_id AND binding_status <> 'disabled' LIMIT 1;
  IF v_existing.id IS NOT NULL THEN
    UPDATE public.sharepoint_project_bindings
    SET binding_mode = _binding_mode, binding_status = 'linked_unvalidated',
        workspace_sharepoint_binding_id = v_ws_binding_id,
        folder_web_url = _folder_web_url, folder_relative_path = _folder_relative_path,
        folder_item_id = _folder_item_id,
        resolved_site_web_url = _resolved_site_web_url, resolved_site_id = _resolved_site_id,
        resolved_library_web_url = _resolved_library_web_url,
        resolved_library_id_or_drive_id = _resolved_library_id_or_drive_id,
        is_restricted = v_is_restricted, last_validated_at = NULL,
        last_validation_code = NULL, last_validation_note = NULL, updated_by = auth.uid()
    WHERE id = v_existing.id RETURNING * INTO v_row;
  ELSE
    INSERT INTO public.sharepoint_project_bindings (organization_id, workspace_id, project_id,
      workspace_sharepoint_binding_id, binding_mode, binding_status,
      folder_web_url, folder_relative_path, folder_item_id,
      resolved_site_web_url, resolved_site_id,
      resolved_library_web_url, resolved_library_id_or_drive_id,
      is_restricted, created_by, updated_by)
    VALUES (v_org, v_ws, _project_id, v_ws_binding_id, _binding_mode, 'linked_unvalidated',
      _folder_web_url, _folder_relative_path, _folder_item_id,
      _resolved_site_web_url, _resolved_site_id,
      _resolved_library_web_url, _resolved_library_id_or_drive_id,
      v_is_restricted, auth.uid(), auth.uid()) RETURNING * INTO v_row;
  END IF;
  RETURN v_row;
END; $function$

CREATE OR REPLACE FUNCTION public.upsert_sharepoint_workspace_binding(_workspace_id uuid, _site_web_url text DEFAULT NULL::text, _library_web_url text DEFAULT NULL::text, _site_label_or_name text DEFAULT NULL::text, _library_label_or_name text DEFAULT NULL::text, _site_id text DEFAULT NULL::text, _library_id_or_drive_id text DEFAULT NULL::text, _managed_outside_btpm boolean DEFAULT true)
 RETURNS sharepoint_workspace_bindings
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_org uuid;
  v_site public.sharepoint_org_site_connections;
  v_existing public.sharepoint_workspace_bindings;
  v_row public.sharepoint_workspace_bindings;
BEGIN
  IF NOT public.is_active_user(auth.uid()) THEN
    RAISE EXCEPTION 'unauthenticated';
  END IF;

  SELECT organization_id INTO v_org FROM public.workspaces WHERE id = _workspace_id;
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'workspace_not_found';
  END IF;
  IF NOT public.is_org_admin(auth.uid(), v_org) THEN
    RAISE EXCEPTION 'unauthorized';
  END IF;

  -- The org-level SharePoint site MUST be configured first.
  SELECT * INTO v_site
  FROM public.sharepoint_org_site_connections
  WHERE organization_id = v_org
    AND connection_status <> 'disabled'
  LIMIT 1;
  IF v_site.id IS NULL THEN
    RAISE EXCEPTION 'org_site_not_configured';
  END IF;

  IF _library_web_url IS NULL OR length(btrim(_library_web_url)) = 0 THEN
    RAISE EXCEPTION 'library_web_url_required';
  END IF;

  -- Validate library belongs to the configured org site (prefix match,
  -- case-insensitive, tolerant of trailing slash).
  IF lower(btrim(_library_web_url)) NOT LIKE lower(rtrim(v_site.site_web_url, '/')) || '%' THEN
    RAISE EXCEPTION 'library_outside_org_site';
  END IF;

  SELECT * INTO v_existing
  FROM public.sharepoint_workspace_bindings
  WHERE workspace_id = _workspace_id
    AND binding_status <> 'disabled'
  LIMIT 1;

  IF v_existing.id IS NOT NULL THEN
    UPDATE public.sharepoint_workspace_bindings
    SET site_web_url           = v_site.site_web_url,
        site_id                = v_site.site_id,
        site_label_or_name     = COALESCE(v_site.site_label_or_name, _site_label_or_name),
        library_web_url        = _library_web_url,
        library_label_or_name  = _library_label_or_name,
        library_id_or_drive_id = _library_id_or_drive_id,
        managed_outside_btpm   = COALESCE(_managed_outside_btpm, true),
        binding_status         = 'configured_unvalidated',
        last_validated_at      = NULL,
        last_validation_code   = NULL,
        last_validation_note   = NULL,
        updated_by             = auth.uid()
    WHERE id = v_existing.id
    RETURNING * INTO v_row;
  ELSE
    INSERT INTO public.sharepoint_workspace_bindings (
      organization_id, workspace_id,
      site_web_url, library_web_url, site_label_or_name, library_label_or_name,
      site_id, library_id_or_drive_id, managed_outside_btpm,
      binding_status, created_by
    ) VALUES (
      v_org, _workspace_id,
      v_site.site_web_url, _library_web_url,
      COALESCE(v_site.site_label_or_name, _site_label_or_name),
      _library_label_or_name,
      v_site.site_id, _library_id_or_drive_id, COALESCE(_managed_outside_btpm, true),
      'configured_unvalidated', auth.uid()
    )
    RETURNING * INTO v_row;
  END IF;

  RETURN v_row;
END
$function$

CREATE OR REPLACE FUNCTION public.upsert_user_saved_view(_id uuid, _surface_key text, _scope_key text, _name text, _state jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user uuid := auth.uid();
  v_org  uuid;
  v_id   uuid;
  v_row  jsonb;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'not authenticated';
  END IF;
  IF _name IS NULL OR length(btrim(_name)) = 0 THEN
    RAISE EXCEPTION 'name required';
  END IF;
  IF _state IS NULL THEN
    RAISE EXCEPTION 'state required';
  END IF;
  SELECT organization_id INTO v_org FROM public.profiles WHERE id = v_user;
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'organization not resolved for user';
  END IF;

  IF _id IS NULL THEN
    INSERT INTO public.user_saved_views (
      organization_id, user_id, surface_key, scope_key, name, state_payload
    ) VALUES (
      v_org, v_user, _surface_key, COALESCE(_scope_key, 'global'),
      public.btpm_encrypt(btrim(_name), v_org),
      public.btpm_encrypt(_state::text, v_org)
    )
    RETURNING id INTO v_id;
  ELSE
    UPDATE public.user_saved_views
       SET name          = public.btpm_encrypt(btrim(_name), v_org),
           state_payload = public.btpm_encrypt(_state::text, v_org)
     WHERE id = _id
       AND user_id = v_user
       AND organization_id = v_org
     RETURNING id INTO v_id;
    IF v_id IS NULL THEN
      RAISE EXCEPTION 'saved view not found';
    END IF;
  END IF;

  SELECT jsonb_build_object(
    'id',         v.id,
    'name',       public.btpm_decrypt(v.name, v.organization_id),
    'state',      public.btpm_decrypt(v.state_payload, v.organization_id)::jsonb,
    'created_at', v.created_at,
    'updated_at', v.updated_at
  ) INTO v_row
  FROM public.user_saved_views v
  WHERE v.id = v_id;

  RETURN v_row;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_project_completion(_project_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid                  uuid := auth.uid();
  v_open_blockers        int := 0;
  v_incomplete_phases    int := 0;
  v_incomplete_tasks     int := 0;
  v_open_risks           int := 0;
  v_target_in_future     int := 0;
  v_target_end           date;
  v_hard                 jsonb := '[]'::jsonb;
  v_warn                 jsonb := '[]'::jsonb;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION
      'BTPM_PROJECT_COMPLETION_VALIDATION_FORBIDDEN: authentication required'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF NOT public.is_active_user(v_uid) THEN
    RAISE EXCEPTION
      'BTPM_PROJECT_COMPLETION_VALIDATION_FORBIDDEN: inactive user'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF _project_id IS NULL OR NOT public.has_project_access(v_uid, _project_id) THEN
    RAISE EXCEPTION
      'BTPM_PROJECT_COMPLETION_VALIDATION_FORBIDDEN: no access to project'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  SELECT COUNT(*) INTO v_open_blockers
  FROM public.blockers b
  WHERE b.status <> 'resolved'
    AND (
      (b.target_type = 'project' AND b.target_id = _project_id)
      OR (b.target_type = 'phase' AND b.target_id IN (
            SELECT id FROM public.phases WHERE project_id = _project_id))
      OR (b.target_type = 'task'  AND b.target_id IN (
            SELECT id FROM public.tasks  WHERE project_id = _project_id))
    );

  SELECT COUNT(*) INTO v_incomplete_phases
  FROM public.phases
  WHERE project_id = _project_id
    AND COALESCE(is_archived, false) = false
    AND status NOT IN ('completed', 'cancelled');

  SELECT COUNT(*) INTO v_incomplete_tasks
  FROM public.tasks
  WHERE project_id = _project_id
    AND COALESCE(is_archived, false) = false
    AND status NOT IN ('completed', 'cancelled');

  SELECT COUNT(*) INTO v_open_risks
  FROM public.risks r
  WHERE r.status NOT IN ('closed', 'accepted', 'realized')
    AND (
      (r.target_type = 'project' AND r.target_id = _project_id)
      OR (r.target_type = 'phase' AND r.target_id IN (
            SELECT id FROM public.phases WHERE project_id = _project_id))
      OR (r.target_type = 'task'  AND r.target_id IN (
            SELECT id FROM public.tasks  WHERE project_id = _project_id))
    );

  SELECT target_end_date INTO v_target_end
  FROM public.projects WHERE id = _project_id;
  IF v_target_end IS NOT NULL AND v_target_end > CURRENT_DATE THEN
    v_target_in_future := 1;
  END IF;

  IF v_open_blockers > 0 THEN
    v_hard := v_hard || jsonb_build_object(
      'code', 'open_blockers',
      'message', 'Project has unresolved blockers in its scope (project, phases, or tasks).',
      'count', v_open_blockers);
  END IF;
  IF v_incomplete_phases > 0 THEN
    v_warn := v_warn || jsonb_build_object(
      'code', 'incomplete_phases',
      'message', 'Project has phases that are not Completed or Cancelled.',
      'count', v_incomplete_phases);
  END IF;
  IF v_incomplete_tasks > 0 THEN
    v_warn := v_warn || jsonb_build_object(
      'code', 'incomplete_tasks',
      'message', 'Project has tasks that are not Completed or Cancelled.',
      'count', v_incomplete_tasks);
  END IF;
  IF v_open_risks > 0 THEN
    v_warn := v_warn || jsonb_build_object(
      'code', 'open_risks',
      'message', 'Project has open risks in its scope.',
      'count', v_open_risks);
  END IF;
  IF v_target_in_future = 1 THEN
    v_warn := v_warn || jsonb_build_object(
      'code', 'target_end_in_future',
      'message', 'Project target end date is in the future.',
      'count', 1);
  END IF;

  RETURN jsonb_build_object(
    'hard_blocks', v_hard,
    'warnings', v_warn,
    'counts', jsonb_build_object(
      'open_blockers', v_open_blockers,
      'incomplete_phases', v_incomplete_phases,
      'incomplete_tasks', v_incomplete_tasks,
      'open_risks', v_open_risks,
      'target_in_future', v_target_in_future
    ),
    'can_complete', (jsonb_array_length(v_hard) = 0 AND jsonb_array_length(v_warn) = 0),
    'can_complete_with_confirmation', (jsonb_array_length(v_hard) = 0)
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_roadmap_story_scope(_user_id uuid, _org_id uuid, _scope jsonb)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _ws uuid;
  _pj uuid;
  _pg uuid;
BEGIN
  IF _scope IS NULL THEN RETURN; END IF;

  -- workspace_ids: must be in org AND caller must be a member
  IF jsonb_typeof(_scope->'workspace_ids') = 'array' THEN
    FOR _ws IN SELECT (jsonb_array_elements_text(_scope->'workspace_ids'))::uuid LOOP
      IF NOT EXISTS (
        SELECT 1 FROM public.workspaces w
        WHERE w.id = _ws AND w.organization_id = _org_id
      ) OR NOT public.is_workspace_member(_user_id, _ws) THEN
        RAISE EXCEPTION 'forbidden: workspace % not accessible', _ws USING ERRCODE = '42501';
      END IF;
    END LOOP;
  END IF;

  -- project_ids: caller must have project access
  IF jsonb_typeof(_scope->'project_ids') = 'array' THEN
    FOR _pj IN SELECT (jsonb_array_elements_text(_scope->'project_ids'))::uuid LOOP
      IF NOT public.has_project_access(_user_id, _pj) THEN
        RAISE EXCEPTION 'forbidden: project % not accessible', _pj USING ERRCODE = '42501';
      END IF;
    END LOOP;
  END IF;

  -- program_ids: must belong to a workspace in caller's org AND caller must be a member of that workspace
  IF jsonb_typeof(_scope->'program_ids') = 'array' THEN
    FOR _pg IN SELECT (jsonb_array_elements_text(_scope->'program_ids'))::uuid LOOP
      IF NOT EXISTS (
        SELECT 1 FROM public.programs p
        JOIN public.workspaces w ON w.id = p.workspace_id
        WHERE p.id = _pg
          AND w.organization_id = _org_id
          AND public.is_workspace_member(_user_id, p.workspace_id)
      ) THEN
        RAISE EXCEPTION 'forbidden: program % not accessible', _pg USING ERRCODE = '42501';
      END IF;
    END LOOP;
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_tenant_storage_access(_storage_object_id uuid, _action text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _o public.tenant_storage_objects;
  _actor uuid := auth.uid();
  _creator_still_active boolean;
BEGIN
  SELECT * INTO _o FROM public.tenant_storage_objects WHERE id = _storage_object_id;
  IF _o.id IS NULL THEN RETURN false; END IF;
  IF _action NOT IN ('read','write','delete','download') THEN
    RAISE EXCEPTION 'Unknown action %', _action;
  END IF;
  IF _actor IS NULL THEN RETURN false; END IF;
  IF public.is_platform_super_admin(_actor) THEN RETURN true; END IF;
  IF public.is_tenant_admin(_o.tenant_id, _actor) THEN RETURN true; END IF;
  IF public.is_organization_admin(_o.organization_id, _actor) THEN RETURN true; END IF;
  IF _o.workspace_id IS NOT NULL AND public.is_workspace_member(_actor, _o.workspace_id) THEN
    RETURN true;
  END IF;
  IF _action IN ('read','download') AND _o.created_by = _actor THEN
    _creator_still_active :=
      public.is_tenant_member(_o.tenant_id, _actor)
      AND public.is_organization_member(_o.organization_id, _actor)
      AND (_o.workspace_id IS NULL OR public.is_workspace_member(_actor, _o.workspace_id));
    IF _creator_still_active THEN RETURN true; END IF;
  END IF;
  RETURN false;
END $function$

CREATE OR REPLACE FUNCTION public.ws_add_member(_workspace_id uuid, _target_user_id uuid, _role app_role)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE _org_id uuid; _ws_name text;
BEGIN
  IF NOT public.is_active_user(auth.uid()) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;
  SELECT organization_id, name INTO _org_id, _ws_name FROM public.workspaces WHERE id = _workspace_id;
  IF _org_id IS NULL THEN RAISE EXCEPTION 'Workspace not found'; END IF;
  IF NOT public.is_workspace_admin_or_higher(auth.uid(), _workspace_id) THEN RAISE EXCEPTION 'Access denied'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = _target_user_id AND organization_id = _org_id AND is_active = true) THEN RAISE EXCEPTION 'User not found or inactive'; END IF;
  IF _role IN ('org_admin') THEN RAISE EXCEPTION 'Cannot assign org_admin as workspace role'; END IF;
  INSERT INTO public.workspace_memberships (workspace_id, user_id) VALUES (_workspace_id, _target_user_id) ON CONFLICT (workspace_id, user_id) DO NOTHING;
  DELETE FROM public.user_roles WHERE user_id = _target_user_id AND workspace_id = _workspace_id AND organization_id = _org_id;
  INSERT INTO public.user_roles (user_id, role, organization_id, workspace_id) VALUES (_target_user_id, _role, _org_id, _workspace_id);
  PERFORM public.log_activity_event(_org_id, auth.uid(), 'workspace_member_added', 'user', _target_user_id, jsonb_build_object('workspace_id', _workspace_id, 'workspace_name', _ws_name, 'role', _role::text), _workspace_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.ws_change_member_role(_workspace_id uuid, _target_user_id uuid, _new_role app_role)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE _org_id uuid; _ws_name text; _old_role text;
BEGIN
  IF NOT public.is_active_user(auth.uid()) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;
  SELECT organization_id, name INTO _org_id, _ws_name FROM public.workspaces WHERE id = _workspace_id;
  IF _org_id IS NULL THEN RAISE EXCEPTION 'Workspace not found'; END IF;
  IF NOT public.is_workspace_admin_or_higher(auth.uid(), _workspace_id) THEN RAISE EXCEPTION 'Access denied'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.workspace_memberships WHERE user_id = _target_user_id AND workspace_id = _workspace_id) THEN RAISE EXCEPTION 'User is not a member'; END IF;
  IF _new_role IN ('org_admin') THEN RAISE EXCEPTION 'Cannot assign org_admin as workspace role'; END IF;
  SELECT ur.role::text INTO _old_role FROM public.user_roles ur WHERE ur.user_id = _target_user_id AND ur.workspace_id = _workspace_id LIMIT 1;
  DELETE FROM public.user_roles WHERE user_id = _target_user_id AND workspace_id = _workspace_id AND organization_id = _org_id;
  INSERT INTO public.user_roles (user_id, role, organization_id, workspace_id) VALUES (_target_user_id, _new_role, _org_id, _workspace_id);
  PERFORM public.log_activity_event(_org_id, auth.uid(), 'workspace_role_changed', 'user', _target_user_id, jsonb_build_object('workspace_id', _workspace_id, 'workspace_name', _ws_name, 'old_role', _old_role, 'new_role', _new_role::text), _workspace_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.ws_create_invitation(_workspace_id uuid, _email text, _role app_role)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE _caller_id uuid; _org_id uuid; _inv_id uuid; _ws_name text; _raw_token uuid; _token_hash text;
BEGIN
  _caller_id := auth.uid(); IF _caller_id IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF NOT public.is_active_user(_caller_id) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;
  SELECT organization_id, name INTO _org_id, _ws_name FROM public.workspaces WHERE id = _workspace_id;
  IF _org_id IS NULL THEN RAISE EXCEPTION 'Workspace not found'; END IF;
  IF NOT public.is_workspace_admin_or_higher(_caller_id, _workspace_id) THEN RAISE EXCEPTION 'Access denied'; END IF;
  IF _role = 'org_admin' THEN RAISE EXCEPTION 'Cannot assign org_admin as workspace role'; END IF;
  IF EXISTS (SELECT 1 FROM public.invitations WHERE organization_id = _org_id AND workspace_id = _workspace_id AND lower(email) = lower(_email) AND status = 'pending' AND expires_at > now()) THEN RAISE EXCEPTION 'A pending invitation already exists'; END IF;
  IF EXISTS (SELECT 1 FROM public.workspace_memberships wm JOIN public.profiles p ON p.id = wm.user_id WHERE wm.workspace_id = _workspace_id AND lower(p.email) = lower(_email)) THEN RAISE EXCEPTION 'User is already a member'; END IF;
  _raw_token := gen_random_uuid(); _token_hash := encode(digest(_raw_token::text, 'sha256'), 'hex');
  INSERT INTO public.invitations (email, organization_id, workspace_id, role, invited_by, status, token) VALUES (lower(_email), _org_id, _workspace_id, _role, _caller_id, 'pending', _token_hash) RETURNING id INTO _inv_id;
  PERFORM public.log_activity_event(_org_id, _caller_id, 'invitation_created', 'invitation', _inv_id, jsonb_build_object('email', lower(_email), 'role', _role::text, 'workspace_id', _workspace_id, 'workspace_name', _ws_name), _workspace_id);
  RETURN _inv_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.ws_remove_member(_workspace_id uuid, _target_user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE _org_id uuid; _ws_name text;
BEGIN
  IF NOT public.is_active_user(auth.uid()) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;
  SELECT organization_id, name INTO _org_id, _ws_name FROM public.workspaces WHERE id = _workspace_id;
  IF _org_id IS NULL THEN RAISE EXCEPTION 'Workspace not found'; END IF;
  IF NOT public.is_workspace_admin_or_higher(auth.uid(), _workspace_id) THEN RAISE EXCEPTION 'Access denied'; END IF;
  IF _target_user_id = auth.uid() THEN RAISE EXCEPTION 'Cannot remove yourself'; END IF;
  PERFORM public.log_activity_event(_org_id, auth.uid(), 'workspace_member_removed', 'user', _target_user_id, jsonb_build_object('workspace_id', _workspace_id, 'workspace_name', _ws_name), _workspace_id);
  DELETE FROM public.user_roles WHERE user_id = _target_user_id AND workspace_id = _workspace_id AND organization_id = _org_id;
  DELETE FROM public.workspace_memberships WHERE user_id = _target_user_id AND workspace_id = _workspace_id;
END;
$function$
